P.entries["quest:646"] = {n="托卡拉尔",s="漫长的Trol'kalar任务线终于到了最后一步。光芒渐渐消散，被封印在石鞘中的Trol'kalar重见天日。将它带给落锤镇的森古。",h="漫长的Trol'kalar任务线终于到了最后一步。光芒渐渐消散，被封印在石鞘中的Trol'kalar重见天日。将它带给落锤镇的森古。",kw={"阿拉希","落锤镇","尼姆布亚","trol'kalar","托尔贝恩","森古","祖尔格拉布"},sec={{t="重获自由之剑",b="在托尔贝恩之墓，光芒渐渐消散，被封印在石鞘中的Trol'kalar重见天日。你带着这把剑鞘包裹着的剑，前往阿拉希高地落锤镇的森古那里。"},{t="森古的话",b="森古告诉你，斯托姆加德和阿拉索的军队世世代代都在捕杀巨魔，而现在他们最伟大的武器落入了他族人的手中。向祖尔格拉布潮湿丛林的缓慢推进将不再是一场苦战。他说暗矛巨魔欠你一个人情，他会负责将这把剑送到格罗姆高营地的尼姆布亚手中。"}},faq={{q="Trol'kalar需要带去哪里？",a="去阿拉希高地落锤镇找森古。你拿到这把剑时，它依然被封在石鞘里。",al={"我要把trolkalar带到哪里","trol'kalar运送","trolkalar上交"}},{q="我在哪里能找到这把剑？",a="在托尔贝恩之墓，那里消散的光芒使其从石鞘中释放了出来。",al={"trol'kalar在哪里","trolkalar位置"}},{q="这一步之前发生了什么？",a="这是漫长的Trol'kalar任务线的最后一步，它紧接着之前的Trol'kalar任务。",al={"trol'kalar前置任务","trolkalar任务线"}}},fp="10,158,16.173.0,15.357.1,33.97.0,26.82.0,27.95.0"}
P.entries["quest:6461"] = {n="盗窃的蜘蛛",s="“吸血者”是玛拉卡金暗矛巨魔定居点中的辛吉拉发布的一项部落狩猎契约。当地的巨魔在石爪山脉的坡地上找到了丰富的猎物，但屠宰猎物散发出的气味引来了大群捕食性的深苔蜘蛛，它们成群结队地侵入了营地。",h="“吸血者”是玛拉卡金暗矛巨魔定居点中的辛吉拉发布的一项部落狩猎契约。当地的巨魔在石爪山脉的坡地上找到了丰富的猎物，但屠宰猎物散发出的气味引来了大群捕食性的深苔蜘蛛，它们成群结队地侵入了营地。",kw={"吸血者","深苔爬行者","深苔毒液喷吐者","玛拉卡金","希塞尔山谷","蜘蛛","石爪山脉","辛吉拉"},ang={["class:Hunter"]="对于穿行在岩架间的资深追踪者而言，追踪那些狩猎并骚扰友好定居点的危险掠食者是顺理成章的工作。",["faction:Horde"]="玛拉卡金是部落从北部贫瘠之地进入石爪山脉的重要通路支点，保卫这个村庄也就确保了整个南部隘道的安全。",["race:Troll"]="玛拉卡金的猎人们是同胞，他们努力在卡利姆多崎岖的高地上开辟自给自足的领地，而不屈服于荒野。"},sec={{t="不受欢迎的晚餐宾客",b="在石爪山脉东南部建立玛拉卡金前哨站的巨魔们最初是为了寻找良好的狩猎场所。崎岖的山坡果然物产丰富，但他们带回的肉类和猎物很快就引起了夜行性掠食者的注意。深苔蜘蛛是北方岩架和峡谷中的原生攻击性蛛形纲动物，它们开始在夜幕的掩护下潜入营地，试图搜刮补给，甚至将猎人当作猎物。"},{t="清理岩架",b="为了确保营地的安全并保护补给，辛吉拉请求冒险者们向北追踪这些掠食者，进入山间隘口。在希塞尔山谷的岩石沟壑和蛛网密布的区域，深苔爬行者和毒液喷吐者的数量最为密集。削减它们的数量可以将蜘蛛群从玛拉卡金的边界驱赶出去，确保村庄在夜晚无需担忧遭到伏击。"}},faq={{q="谁发布了任务“吸血者”？",a="位于石爪山脉东南部玛拉卡金村的暗矛巨魔辛吉拉，向途经此地的部落勇士发布了这项任务。",al={"谁发布吸血者任务","吸血者任务发布人","辛吉拉任务"}},{q="为什么蜘蛛会攻击玛拉卡金？",a="玛拉卡金的巨魔们在当地进行了大规模狩猎。新鲜猎物和风干肉食散发的气味在夜间将深苔蜘蛛从山口引诱下来，它们以此偷窃补给并猎杀村民。",al={"为什么蜘蛛会攻击","蜘蛛袭击玛拉卡金","为什么蜘蛛在入侵"}},{q="深苔蜘蛛位于何处？",a="深苔爬行者和毒液喷吐者在玛拉卡金以北的中央隘口和岩架上游荡，其中在蛛网密布的希塞尔山谷深处聚集成群。",al={"深苔蜘蛛在哪里","深苔爬行者位置","深苔毒液喷吐者位置"}},{q="什么是玛拉卡金？",a="玛拉卡金是一个暗矛巨魔定居点，位于石爪山脉的南入口，靠近贫瘠之地边界，是部落的一个前哨狩猎基地。",al={"什么是玛拉卡金","玛拉卡金背景传说","石爪山脉巨魔村庄"}},{q="这些蜘蛛是否还引发了更大的威胁？",a="在希塞尔山谷的蛛网深处居住着一只体型巨大且致命的蜘蛛女王。峡谷外的一块告示牌警告了过往的旅行者这种危险，并鼓励小队前去铲除它。",al={"石爪山脉大蜘蛛","希塞尔山谷精英蜘蛛","石爪山脉蜘蛛女王"}},{q="清理蜘蛛后会发生什么？",a="清理掉爬行者和毒液喷吐者后，玛拉卡金的压力得以缓解，巨魔猎人可以守住肉食储备，并在夜间于营地中走动，不再时刻受到伏击的威胁。",al={"吸血者任务后续","玛拉卡金是否变安全"}}},fp="13,163,22.391.0,18.364.0,35.138.0,41.214.0,39.164.0,19.173.0,48.179.0,42.169.0"}
P.entries["quest:6462"] = {n="巨魔符咒",s="“巨魔符咒”是部落的一项任务，由位于灰谷佐拉姆加前哨站的暗矛巨魔米苏瓦提供。在一队旅行的巨魔遭到蓟皮熊怪的伏击并被屠杀后，米苏瓦请求冒险者深入它们的巢穴，找回被从死者身上偷走的圣物。",h="“巨魔符咒”是部落的一项任务，由位于灰谷佐拉姆加前哨站的暗矛巨魔米苏瓦提供。在一队旅行的巨魔遭到蓟皮熊怪的伏击并被屠杀后，米苏瓦请求冒险者深入它们的巢穴，找回被从死者身上偷走的圣物。",kw={"灰谷","暗矛","熊怪","米苏瓦","thistlefur hold","蓟皮村","巨魔符咒","佐拉姆加前哨站"},ang={["faction:Horde"]="深入蓟皮熊怪的领地是对那些伏击部落补给线和穿过灰谷的旅行者的林地威胁的反击。",["race:Troll"]="对于暗矛巨魔来说，找回符咒是一种精神职责，旨在确保神圣的祖传物品从野蛮的熊怪魔爪中被救回。"},sec={{t="遇袭的车队",b="佐拉姆加前哨站是部落在灰谷海岸西部的一处偏远避难所，这使得沿着林间小路行进充满了危险。一队前往该哨所的暗矛巨魔在途中失踪，他们遭遇了领地意识极强的蓟皮熊怪的暴力伏击。虽然米苏瓦接受了他的族人死亡这一事实，认为他们终会在来世重聚，但对他们圣物符咒的亵渎和窃取是不可容忍的侮辱。"},{t="圣物",b="在巨魔文化中，符咒和护身符与身份、精神保护以及与洛阿神的联系紧密相连。米苏瓦认为，一个没有符咒的巨魔就像一个没有战斗伤疤的兽人一样空虚且毫无价值。蓟皮熊怪将这些偷来的神器拖回了位于蓟皮村深处的Thistlefur Hold洞穴系统中，并将它们藏在箱子里，使其远离真正的主人。"}},faq={{q="谁提供这个任务，他们位于哪里？",a="该任务由米苏瓦提供，他是一名驻扎在灰谷西北海岸佐拉姆海岸的佐拉姆加前哨站的暗矛巨魔。",al={"任务提供者","米苏瓦的位置","谁开启巨魔符咒任务"}},{q="为什么巨魔符咒对米苏瓦如此重要？",a="对巨魔而言，圣物符咒具有深远的精神和文化意义。米苏瓦将没有符咒的巨魔比作没有战斗伤疤的兽人，他认为敌对的熊怪持有这些圣物是对他被杀害的族人的粗暴亵渎。",al={"符咒的重要性","为什么巨魔符咒很重要","符咒的意义"}},{q="巨魔符咒位于哪里？",a="符咒被存放在Thistlefur Hold内的箱子里，这是一个位于蓟皮村北缘的深层洞穴建筑群，坐落在暗夜精灵定居点阿斯特兰纳的北部。",al={"符咒位置","箱子在哪里","寻找符咒"}},{q="谁偷走了符咒？",a="蓟皮熊怪在米苏瓦的族人前往佐拉姆加前哨站的途中伏击并杀害了他们，洗劫了他们的财物并将圣物符咒拖入了他们的洞穴中。",al={"谁拿走了符咒","伏击元凶"}},{q="最初携带符咒的巨魔遭遇了什么？",a="他们在路上被蓟皮熊怪杀害了。米苏瓦哀悼他们的离去，但相信终有一天能在来世与他们重聚，目前他将找回他们的圣物作为首要任务。",al={"车队命运","被杀的巨魔","米苏瓦的族人"}},{q="联盟可以接这个任务吗？",a="不可以。该任务始于佐拉姆加前哨站，仅供帮助暗矛部族的部落玩家接取。",al={"联盟能接巨魔符咒吗","联盟可以做这个任务吗"}}},fp="11,204,19.384.0,15.383.0,48.109.0,49.197.0,35.134.0,21.167.0,62.177.0,40.58.0"}
P.entries["quest:647"] = {n="马克里尔的月光酒",s="马克里尔的月光酒是一个节奏紧凑的跑腿任务，受托于醉鬼马克里尔。这位矮人被困在萨多尔大桥断裂的一侧。由于贪杯喝多了自己酿的烈酒，导致在执勤时睡过了头，醉鬼马克里尔只能拜托一名联盟旅人赶紧把刚酿好的一批酒送去希尔斯布莱德，以还清他欠南海镇布鲁米·比格尔的一笔旧债。",h="马克里尔的月光酒是一个节奏紧凑的跑腿任务，受托于醉鬼马克里尔。这位矮人被困在萨多尔大桥断裂的一侧。由于贪杯喝多了自己酿的烈酒，导致在执勤时睡过了头，醉鬼马克里尔只能拜托一名联盟旅人赶紧把刚酿好的一批酒送去希尔斯布莱德，以...",kw={"比格尔","醉鬼马克里尔","布莱德·长须","马克里尔","米奈希尔","月光酒","南海镇"},ang={["faction:Alliance"]="这段快速的陆路行程突显了萨多尔大桥与希尔斯布莱德联盟控制下的南海镇之间至关重要的联系。",["race:Dwarf"]="矮人们会立刻理解那种伴随着剧烈宿醉，同时又欠同胞一笔酿酒债的双重窘境。"},sec={{t="守卫的宿醉",b="在断裂的萨多尔大桥上执勤的日子又湿又冷，而且出了名的枯燥。醉鬼马克里尔通过畅饮自己私酿的月光酒来抵御潮湿的寒意，这种酒极其猛烈，他形容喝完之后的感觉就像有一整支攻城器械部队从他的脑壳上碾过。但不幸的是，马克里尔因为喝得太多，在执勤时昏了过去。由于布莱德·长须正在指挥守卫大桥的矮人部队，马克里尔绝不能再出任何纪律上的岔子了。"},{t="与时间的赛跑",b="让马克里尔雪上加霜的是，他欠南海镇的布鲁米·比格尔一笔长期债务。马克里尔曾答应比格尔会送去一批他亲手酿的酒来抵债，但宿醉加上执勤任务，让他距离违约只剩几分钟的时间了。旅人必须依靠狮鹫和双脚，穿过阿拉希高地赶往南海镇，在比格尔认定马克里尔又一次赖账之前把酒桶送达。"}},faq={{q="醉鬼马克里尔是谁？",a="醉鬼马克里尔是一位矮人，可以在萨多尔大桥断裂的一侧找到，从阿拉希高地那一侧可以到达那里。他以酿造极其烈性的私酿月光酒而闻名，而且在执勤时往往会对自己的产品浅尝辄止得有点过头。",al={"醉鬼马克里尔","醉鬼马克里尔是谁","马克里尔任务发布者"}},{q="为什么这次送货这么紧急？",a="马克里尔因为在执勤时醉倒，导致任务严重延误。他有一个必须把月光酒送到布鲁米·比格尔手中以还清逾期债务的最后期限，从萨多尔大桥赶往南海镇的时间只剩下不到一刻钟了。",al={"为什么有计时器","为什么是15分钟","马克里尔的月光酒计时器"}},{q="布鲁米·比格尔是谁？",a="布鲁米·比格尔是一位矮人酿酒大师，在希尔斯布莱德丘陵的南海镇沿海定居点经营他的生意。他钟爱烈性酒精，并与醉鬼马克里尔有一笔未完成的商业协议。",al={"布鲁米·比格尔","比格尔是谁","比格尔 南海镇"}},{q="如何才能及时把月光酒送到南海镇？",a="从大桥没有船去南海镇。最快的路线是前往阿拉希高地，如果你知道飞行点，就从避难谷地骑狮鹫飞往南海镇，然后在计时结束前在镇子里找到布鲁米·比格尔。",al={"如何运送月光酒","马克里尔南海镇最快路线","月光酒配送路线"}},{q="长须是谁？",a="布莱德·长须是驻扎在湿地丹莫德外围的矮人指挥官，负责领导萨多尔大桥的守卫工作。马克里尔非常害怕被长须发现他在执勤时喝得不省人事。",al={"长须队长","长须 米奈希尔"}}},fp="20,226,18.417.0,24.369.0,22.183.0,31.215.0,26.206.0,53.200.0,17.203.0"}
P.entries["quest:648"] = {n="拯救OOX-17/TN！",s="受损的归航机器人OOX-17/TN发出了奥格索普的声音。它需要一个开阔、安全的地方来进行长时间的起飞，你被要求将其安全护送至热砂港，然后前往藏宝海湾找到奥格索普·奥布诺提斯。",h="受损的归航机器人OOX-17/TN发出了奥格索普的声音。它需要一个开阔、安全的地方来进行长时间的起飞，你被要求将其安全护送至热砂港，然后前往藏宝海湾找到奥格索普·奥布诺提斯。",kw={"藏宝海湾","归航机器人","机械小鸡","奥格索普·奥布诺提斯","oox-17/tn","热砂港","塔纳利斯"},sec={{t="护送至港口",b="奥格索普的声音再次从机器人体内传出，伴随着杂音。该机器人有内置的隐形装置，但奥格索普需要时间使其重新运作，因此它必须到达一个开阔、安全的地方，以便开始其漫长的起飞程序。热砂港正是奥格索普所想的地方，这段旅程能为他争取到修复的时间。你的任务是将机器人安全护送至那里。"},{t="前往藏宝海湾报告",b="一旦机器人安全抵达港口，你被要求在藏宝海湾寻找工程学大师奥格索普·奥布诺提斯。"},{t="感激的发明家",b="奥格索普把你当作救下OOX-17/TN的人来迎接。归航机器人系列仍需改进，但找回这一台机器节省了无数的重建时间以及大量的金币重造费用。奥格索普说，无论是机器人还是这位发明家都欠你一个人情。"}},faq={{q="需要把机器人护送到哪里？",a="送往热砂港，它可以在那里安全地开始起飞。",al={"oox-17要去哪里","oox-17护送路线","机器人目的地"}},{q="是谁在通过机器人说话？",a="奥格索普·奥布诺提斯，一位侏儒兼工程学大师，这台归航机器人就是他的。你可以在藏宝海湾找到这位发明家。",al={"谁制造了oox-17","oox-17的制造者","谁在通过机器人说话"}},{q="为什么要转移这台机器人？",a="它需要一个开阔、安全的地方来开始漫长的起飞程序。它内置的隐形装置也需要时间来重新恢复运作。",al={"为什么要转移oox-17","为什么要前往热砂港"}},{q="护送任务完成后该去哪里报告？",a="奥格索普·奥布诺提斯在藏宝海湾等待。",al={"奥格索普·奥布诺提斯在哪里","任务交给谁","oox-17任务交接地点"}}},fp="17,228,21.386.0,19.118.0,19.289.1,41.61.0,34.114.0,36.125.0,37.40.0"}
P.entries["quest:6481"] = {n="土灵的觉醒",s="在滚岩峡谷深处，萨满祭司摩罗加尔发现了一个名为Goggeroc的沉睡土灵，它被封印在一个共鸣水晶桶中。由于担心这古老的石造生物会给卡利姆多带来破坏性的力量，他派遣一名勇士去击碎水晶桶，趁Goggeroc恢复全部实力之前将其击倒。",h="在滚岩峡谷深处，萨满祭司摩罗加尔发现了一个名为Goggeroc的沉睡土灵，它被封印在一个共鸣水晶桶中。由于担心这古老的石造生物会给卡利姆多带来破坏性的力量，他派遣一名勇士去击碎水晶桶，趁Goggeroc恢复全部实力之前将...",kw={"滚岩峡谷","土灵","石中沉眠任务","goggeroc","摩罗加尔","共鸣水晶桶","萨满祭司","石爪山脉"},ang={["class:Shaman"]="摩罗加尔引导萨满力量来操纵共鸣水晶，破坏了保护桶内土灵的元素平衡。",["faction:Horde"]="通过消灭Goggeroc，部落的勇士巩固了他们在石爪山脉险峻岩脊上的立足点，同时也赢得了雷霆崖领袖们长久的尊重。",["race:Tauren"]="石爪山脉是雷霆崖各部族神圣的先祖狩猎地，在其山峰深处中和这个古老的毁灭性实体，保护了这片土地免遭荒废。"},sec={{t="石中沉眠",b="在调查滚岩峡谷的害虫侵扰时，侦察兵在狗头人中发现了一件奇怪的遗物：一个散发着超自然力量的共鸣水晶桶。摩罗加尔，一位驻扎在石爪山脉的牛头人萨满祭司，认出了这个容器的真面目——它是一个囚禁着沉睡土灵Goggeroc的监狱兼庇护所。这些原始的石造生物拥有超过凡人战士的力量，Goggeroc一旦重获自由，将对该地区构成生存威胁。"},{t="共鸣水晶",b="唤醒全盛时期的土灵对石爪山脉来说将是灾难性的。为了扭转局势，摩罗加尔改变了他所获得的共鸣水晶的混合比例，并向其中注入了萨满魔法。这种魔化共鸣水晶旨在以足够的力度击碎共鸣水晶桶，从而在Goggeroc极度虚弱的状态下将其震醒。部落的战士必须击碎容器，在泰坦造物从数百年的沉睡中清醒过来之前将其击倒。"}},faq={{q="摩罗加尔是谁？",a="摩罗加尔是一位驻扎在石爪山脉的牛头人萨满祭司。他研究该地区的异常现象，并利用他的元素魔法来评估当地害虫挖掘出的奇异古代文物和威胁。",al={"摩罗加尔","任务给予者是谁","兽人萨满摩罗加尔"}},{q="什么是土灵？",a="土灵是古代由活石锻造而成的生物，是泰坦在世界黎明时期留下的造物。它们与大地有着深厚的联系，并拥有惊人的体魄，数千年来一直沉睡在卡利姆多和东部王国的地下。",al={"什么是土灵","土灵背景知识","土灵是什么人"}},{q="摩罗加尔为什么要杀死Goggeroc？",a="摩罗加尔担心，一个活跃的土灵所拥有的无与伦比的力量会给石爪山脉和整个卡利姆多带来灾难。由于这种原始生物不可预测且力量强大，他认为在Goggeroc沉睡后的虚弱状态下将其消灭，是保护这片土地的唯一方法。",al={"为什么要杀死goggeroc","goggeroc是邪恶的吗","为什么要击杀土灵"}},{q="Goggeroc在哪里？",a="Goggeroc被封印在位于石爪山脉东南部的滚岩峡谷的洞穴深处的一个共鸣水晶桶中，周围环绕着在那挖掘洞穴的滚岩狗头人。",al={"水晶桶在哪里","goggeroc的位置","寻找共鸣水晶桶"}},{q="如何唤醒Goggeroc？",a="你需要直接在洞穴中的共鸣水晶桶上使用摩罗加尔提供的魔化共鸣水晶。这种经过魔法改造的水晶会使容器破裂，迫使沉睡的土灵现身。",al={"如何召唤goggeroc","使用魔化共鸣水晶","打开水晶桶"}},{q="击杀Goggeroc后会发生什么？",a="带着Goggeroc死亡的消息回到摩罗加尔那里，可以缓解这位萨满祭司深沉的忧虑。他将你视为英雄，你的事迹避免了一场巨大的灾难，这为你赢得了雷霆崖牛头人中崇高的荣誉和地位。",al={"任务奖励剧情","摩罗加尔的反应","提交任务石中沉眠"}}},fp="13,236,18.381.0,20.381.1,17.201.0,19.237.0,38.195.0,26.172.0,27.158.0,37.204.1"}
P.entries["quest:6482"] = {n="鲁尔的自由",s="在灰谷北部，Ruul 被关在 Thistlefur Hold 深处的一座牢笼里。他需要一位部落盟友助他杀出这座被腐化的熊怪巢穴，抵达安全之地。",h="在灰谷北部，Ruul 被关在 Thistlefur Hold 深处的一座牢笼里。他需要一位部落盟友助他杀出这座被腐化的熊怪巢穴，抵达安全之地。",kw={"灰谷","德鲁伊护送","熊怪","碎木岗哨","thistlefur hold","雅玛·雪蹄"},ang={["class:Druid"]="鲁尔的被捕是一个令人谦卑的提醒，告诫人们以动物伪装在野性领地徘徊的风险，因为在那里的腐化生物无法分辨谁是朋友，谁是猎物。",["faction:Horde"]="从灰谷北部腐化的空洞中救出的每一个灵魂，都在加强部落在碎木岗哨那摇摇欲坠的据点。",["race:Tauren"]="拯救一名塞纳里奥议会的被困兄弟，并平息他在碎木岗哨亲人的忧虑，这既是对大地母亲的尊崇，也是对部落情谊的践行。"},sec={{t="枷锁中的德鲁伊",b="当德鲁伊鲁尔·雪蹄在灰谷北部的腐化森林中冒险时，他以熊形态徘徊到了离Thistlefur Hold太近的地方。那些失去祖先智慧并受野性偏执驱使的腐化熊怪，误以为这位变形的牛头人只是一头普通的野兽。它们不仅没有对他保持敬畏，反而将他关进笼子里并让他挨饿，耗尽了他的魔法储备，使他无法独自脱身。"},{t="逃离巢穴",b="由于饥饿和囚禁而虚弱不堪，鲁尔无法变形或在没有帮助的情况下从熊怪巢穴中杀出重围。一旦被部落的盟友救出，他便依赖援救者清理出一条道路，以通过成群的敌对Thistlefur熊怪。在安全抵达碎木岗哨郊外后，他短暂地显露出牛头人的真身，表达了衷心的感谢，随后便回到荒野中去睡觉以消除疲劳。"}},faq={{q="为什么鲁尔·雪蹄会被熊怪关起来？",a="鲁尔当时正以熊的形态探索森林。腐化的Thistlefur熊怪没能认出他是一位德鲁伊，误以为他是一头野兽，便将他关进笼子里，让他挨饿，直到他没有力气逃跑。",al={"为什么鲁尔被困","鲁尔是如何被捕的","为什么被关在笼子里"}},{q="雅玛·雪蹄是谁？",a="雅玛·雪蹄是鲁尔的妹妹，驻扎在灰谷的碎木岗哨。几天前鲁尔进入森林后便没了音讯，她为此深感担忧。",al={"鲁尔的妹妹","碎木岗哨的雅玛","雅玛是谁"}},{q="为什么鲁尔不能直接变回人形逃走？",a="长期的囚禁和Thistlefur熊怪蓄意的虐待让他饥肠辘辘，鲁尔变得极度虚弱。由于缺乏食物和体力，他体内的自然能量储备完全耗尽，直到获救前都束手无策。",al={"为什么鲁尔没有变身","德鲁伊熊形态陷阱"}},{q="鲁尔到达安全地带后会发生什么？",a="一旦被护送出充满敌意的巢穴并到达碎木岗哨的边缘，鲁尔会短暂地变回牛头人的自然形态以表达感激之情，随后变回熊的形态，去寻找一个安静的地方睡觉和恢复体力。",al={"鲁尔去哪里了","鲁尔结局"}},{q="灰谷里的所有熊怪都像Thistlefur熊怪一样敌对吗？",a="不。虽然许多熊怪部族拥有高贵的传承和与自然的深厚联系，但灰谷北部的Thistlefur部族已经屈服于黑暗的腐化力量，变得具有攻击性且难以预料。",al={"熊怪是邪恶的吗","thistlefur腐化"}},{q="救援在哪里进行？",a="鲁尔被关押在Thistlefur Hold内部，这是一个位于灰谷碎木岗哨西北方山区和阿斯特兰纳北部的熊怪巢穴。",al={"鲁尔在哪里","鲁尔·雪蹄位置"}}},fx={cd4f3bf3={q="鲁尔·雪蹄为什么需要你护送，而不是自己逃出去？",a="鲁尔被困在一座刺毛熊怪的牢笼里已有数日，遭受堕落的熊怪囚禁并忍受饥饿。他的体力几乎耗尽。他虚弱不堪、营养不良，又身陷敌对的刺毛熊怪巢穴深处，无法独自杀出周围部族的包围，只能依靠你为他开辟一条自由之路。",al={"鲁尔为什么需要帮助","鲁尔为什么不能独自逃走","为什么让我找鲁尔·雪蹄"}}},fp="15,164,17.433.0,19.421.1,48.238.0,21.176.1,56.235.0,39.229.1,59.215.0,33.145.0"}
P.entries["quest:65"] = {n="迪菲亚兄弟会",s="这一差事标志着揭开恐怖统治西部荒野的秘密辛迪加面纱的第一步。受哨兵岭的格里安·斯托曼派遣，旅行者被指引向东进入赤脊山，去咨询一位可能知道窃贼藏身之处的线人。",h="这一差事标志着揭开恐怖统治西部荒野的秘密辛迪加面纱的第一步。受哨兵岭的格里安·斯托曼派遣，旅行者被指引向东进入赤脊山，去咨询一位可能知道窃贼藏身之处的线人。",kw={"迪菲亚","格里安·斯托曼","湖畔镇","赤脊山","哨兵岭","西部荒野","黑衣威利"},ang={["class:Rogue"]="斯托曼认识到正规军无法瓦解一个犯罪集团；这需要一个了解阴影和街头交易的人，这直接指向了黑衣威利。",["faction:Alliance"]="从西部荒野到赤脊山的漫长旅程凸显了在首都漠不关心的情况下，暴风城的外围领地必须多么依赖彼此。"},sec={{t="尘土中的威胁",b="西部荒野已沦为废墟，农作物被洗劫一空，且到处都是戴着红色头巾的强盗。格里安·斯托曼和人民民兵团在哨兵岭抵御着近乎不断的骚扰，但他们是在盲目作战。斯托曼意识到，如果不找到这个卡特尔的核心圈子并查明幕后主使，仅靠砍杀零散的劫匪永远无法拯救这片地区。"},{t="外地的线人",b="斯托曼没有依赖官方军事渠道或暴风城那些缺位的贵族，而是动用了他的人情债。他派遣值得信任的冒险者穿过艾尔文森林进入赤脊山。在宁静的湖畔镇，潜伏在当地旅店二楼的是一名叫黑衣威利的潜行者。比起任何民兵队长，威利更了解地下世界，他是揭开迪菲亚潜行者藏身处的第一条线索。"}},faq={{q="格里安·斯托曼是谁？",a="格里安·斯托曼是人民民兵团的领袖，这是一支驻扎在西部荒野哨兵岭的乌合之众般的防御力量。由于暴风城忽视了边境地区，他负责协调剩余少数当地农民和难民的防御工作。",al={"格里安·斯托曼","谁发布了这个任务","西部荒野任务发布者"}},{q="斯托曼为什么要让你去湖畔镇？",a="人民民兵团在西部荒野内部缺乏地下线人。斯托曼动用了以前欠下的人情，要求湖畔镇旅店里的潜行者黑衣威利帮忙，希望通过地下情报网揭露谁是窃贼的头目。",al={"为什么去湖畔镇","为什么要前往赤脊山","为什么找威利"}},{q="黑衣威利是谁？",a="黑衣威利是一名潜行者，住在赤脊山的Lakeshire Inn二楼。他欠格里安·斯托曼一个人情，这使他成为传递地下传闻和犯罪消息的有用渠道。",al={"威利是谁","威利 湖畔镇","黑衣威利"}},{q="什么是迪菲亚潜行者？",a="迪菲亚潜行者是一个戴着红色面具的冷酷犯罪卡特尔，他们夺取了西部荒野的农场、道路和废弃矿井的控制权，正积极驱逐定居者并挑战暴风城的权威。",al={"迪菲亚潜行者","什么是迪菲亚","红头巾强盗"}},{q="我在湖畔镇哪里可以找到威利？",a="黑衣威利位于赤脊山湖畔镇大桥附近的Lakeshire Inn二楼。",al={"威利在哪里","寻找威利","威利位置"}},{q="这个任务需要战斗吗？",a="不需要。最初的这一步纯粹是信息收集。你只需从西部荒野的哨兵岭出发，穿过艾尔文森林前往湖畔镇的旅店与威利取得联系。",al={"这个任务难吗","迪菲亚潜行者任务有战斗吗","敌人"}}},fp="22,189,22.352.0,22.414.0,25.219.0,43.215.0,23.194.0,31.179.0,36.130.0,35.102.0"}
P.entries["quest:6503"] = {n="灰谷先驱者",s="“灰谷斥候”是库莱比在灰谷发布的一项部落巡逻拦截任务。暗夜精灵侦察兵从银翼哨站四散而出，搜集附近部落营地的情报，这促使部落发动先发制人的打击，以隐藏哨站的防御状况。通过猎杀这些潜行的侦察兵，部落可以使当地的联盟部队失去耳目，并遏制其未来的入侵企图。",h="“灰谷斥候”是库莱比在灰谷发布的一项部落巡逻拦截任务。暗夜精灵侦察兵从银翼哨站四散而出，搜集附近部落营地的情报，这促使部落发动先发制人的打击，以隐藏哨站的防御状况。通过猎杀这些潜行的侦察兵，部落可以使当地的联盟部队失去耳...",kw={"联盟","灰谷","灰谷斥候","部落","库莱比","暗夜精灵侦察兵","银翼哨站"},ang={["class:Hunter"]="在深邃的林地地形中追踪隐蔽的斥候，依靠的是敏锐的直觉、强化的追踪感官和精准的箭术。",["class:Rogue"]="消灭敌方斥候可以扭转暗夜精灵的隐身优势，确保部落的渗透者能掌控森林阴影中的主动权。",["faction:Horde"]="在灰谷中每消灭一个暗夜精灵侦察兵，都能保护当地营地和伐木作业免受联盟协同反攻的威胁。"},sec={{t="林冠之眼",b="灰谷的森林依然是一片竞争激烈的边境，每一条小径和山脊都受到严密的监视。情报如同战斧一般致命，传给库莱比的报告证实，被称为“灰谷斥候”的暗夜精灵侦察兵已经从联盟位于银翼哨站的据点溜了出来。这些侦察兵在基地以东、当地部落据点以南的茂密荒野中活动，他们在林间小径潜行，以绘制防御工事图并追踪部队动向。"},{t="致盲联盟",b="为了防止有组织的突袭，部落必须在敌方侦察兵返回基地前将其消灭。通过猎杀这些斥候，部落勇士可以阻止银翼哨站的指挥官获得有关部队兵力和哨站外围防御的重要情报。失去了前进的耳目，暗夜精灵将变得不知所措，在穿越这片争议林区时也会减少采取激进战术的意愿。"}},faq={{q="谁发布了“灰谷斥候”这个任务？",a="该任务由驻扎在灰谷的部落侦察协调员库莱比发布，他致力于追踪并反制暗夜精灵在森林各处的行动。",al={"任务发布者","谁发布任务","库莱比任务"}},{q="灰谷斥候位于何处？",a="这些斥候在银翼哨站以东、库莱比营地以南的森林中徘徊，在灌木丛中巡逻以搜集情报。",al={"斥候位置","斥候在哪里","去哪里找斥候"}},{q="为什么斥候对部落构成威胁？",a="这些斥候是从银翼哨站出发的先遣侦察兵。如果他们成功绘制了部落营地和部队兵力的地图，联盟就能针对薄弱位置协调进行精确突袭。",al={"为什么要杀斥候","斥候的威胁","斥候的目的"}},{q="什么是银翼哨站？",a="银翼哨站是暗夜精灵在灰谷的重要军事设施，作为联盟部队保卫森林和对抗部落扩张的前线基地。",al={"银翼哨站背景","什么是银翼哨站","银翼联盟"}},{q="这个任务是更长故事线的一部分吗？",a="此任务主要是一项独立的战术任务，旨在减少该区域的联盟侦察活动，奖励那些协助库莱比巩固周边防线的战士。",al={"任务链","后续任务","斥候任务链"}},{q="联盟玩家可以完成这个任务吗？",a="不可以，此任务仅限部落玩家。库莱比完全是代表部落在灰谷的前线利益行事。",al={"这是部落专属吗","联盟版本","联盟能做这个吗"}}},fp="20,193,20.372.0,21.321.0,41.139.0,43.138.0,45.183.0,27.172.0,41.147.0,41.110.0"}
P.entries["quest:6504"] = {n="丢失的书页",s="在将一台刚从棘齿城买来的地精伐木机运往战歌伐木营地的途中，兽人古尔达·怒痕因为一阵突如其来的大风弄丢了机器的操作手册。她现在被困在碎木岗哨附近，如果不找回这些散落的书页，她根本无法操作这台复杂的工程奇迹。",h="在将一台刚从棘齿城买来的地精伐木机运往战歌伐木营地的途中，兽人古尔达·怒痕因为一阵突如其来的大风弄丢了机器的操作手册。她现在被困在碎木岗哨附近，如果不找回这些散落的书页，她根本无法操作这台复杂的工程奇迹。",kw={"灰谷","古尔达·怒痕","棘齿城","伐木机","伐木机操作手册","碎木岗哨","丢失的书页","战歌伐木营地"},ang={["faction:Horde"]="每一台运抵战歌伐木营地的伐木机，都能加快采集珍贵木材的速度，这些木材是杜隆塔尔建设围墙、小屋和战舰所必需的。",["profession:Engineering"]="工匠们会对古尔达的困境感同身受：在没有制造商指南的情况下驾驶地精制造的伐木机，很容易导致锅炉灾难性地损坏。",["race:Orc"]="体力劳动和战士传统使得人们对繁琐的地精文书工作缺乏耐心，这让古尔达因为丢失技术手册而感到懊恼显得非常真实。"},sec={{t="倒霉的一阵风",b="战歌氏族主要依靠从棘齿城港口的地精那里购买的蒸汽伐木机来清除灰谷的树木。对于普通的兽人战士来说，操作这些精巧又吵闹的装置绝非易事。当古尔达·怒痕带着一台刚买来的伐木机向北行进时，一阵突如其来的狂风从她手中卷走了说明书，十二页脆弱的羊皮纸散落在森林的地面上。"},{t="荒野中的书页",b="由于狂风将手册吹过了树冠，散落的书页散布到了整个地区，落入了游荡的生物、邪教徒和森林居民的手中。如果无法集齐这三个章节，这台复杂的机器就只是一堆静止的钢铁和旋转的锯片，古尔达也只能被困在前往碎木岗哨的路上，无法去伐木营地报到。"}},faq={{q="古尔达·怒痕是谁？",a="古尔达·怒痕是一位部落劳工，她的任务是将一台地精伐木机从棘齿城商港运送到灰谷，加入战歌伐木营地的伐木工作。",al={"古尔达","怒痕","任务发布者是谁"}},{q="为什么古尔达需要说明书才能驾驶伐木机？",a="地精工程学以挑剔和反直觉著称，依赖于不稳定的锅炉、复杂的压力阀和精密的杠杆。即使是一个急切的兽人，如果不阅读制造商的手册，也无法安全地操作这种装置。",al={"为什么需要说明书","为什么她无法驾驶伐木机","伐木机操作手册"}},{q="手册的书页是怎么散落在灰谷各处的？",a="在沿森林道路向北行驶时，一阵猛烈的狂风将书从古尔达的手中吹走。散乱的书页在树林中四散飘落，只剩下空荡荡的封皮还抓在她手里。",al={"书页是如何丢失的","风吹散了书页"}},{q="伐木机最终要去哪里？",a="这台机器的目的地是战歌伐木营地，部落在那里开展了大规模的砍伐行动，为奥格瑞玛和杜隆塔尔提供木材。",al={"伐木机要去哪里","战歌伐木机的目的地"}},{q="在哪里可以找到丢失的书页？",a="狂风将书页吹得到处都是，它们已经被在灰谷各处游荡的各种人形生物和敌对森林生物捡走了。",al={"去哪里寻找书页","谁会掉落书页"}},{q="部落为什么要从棘齿城购买机械？",a="棘齿城是最近的中立港口，拥有与地精贸易财阀相连的活跃贸易网络。部落经常购买专业的工程设备、爆破工具和蒸汽驱动的车辆来加强其军事后勤。",al={"部落的地精机械","棘齿城的部落贸易"}}},fp="14,205,18.341.0,23.262.0,22.130.0,64.139.0,61.182.0,42.111.0,37.118.0,51.189.0"}
P.entries["quest:651"] = {n="禁锢之石",s="在“公主被困”任务完成后，来自虹色碎片的一个声音讲述了分散在阿拉希的四块缚灵石，它们将它镇压在地下。其中最强大的那一块——内缚灵石，只有使用从其他三块石头上取得的钥匙才能解锁。",h="在“公主被困”任务完成后，来自虹色碎片的一个声音讲述了分散在阿拉希的四块缚灵石，它们将它镇压在地下。其中最强大的那一块——内缚灵石，只有使用从其他三块石头上取得的钥匙才能解锁。",kw={"阿拉希高地","烈焰钥匙","海浪钥匙","虹色碎片","米兹拉尔","内缚灵石","缚灵石","雷霆钥匙"},sec={{t="四块缚灵石",b="那个声音讲述了分散在阿拉希的四块缚灵石，它们将它镇压在地下。若要松动它们，必须首先解锁最强大的一块：内缚灵石，它需要从其他三块——西缚灵石、东缚灵石和外缚灵石上收集的钥匙。这些钥匙分别是烈焰钥匙、海浪钥匙和雷霆钥匙。守护者们看守着这些石头，但聪明或幸运的人或许能找到驱逐它们的方法。收集齐钥匙后，便可将其带到内缚灵石处。"},{t="在内缚灵石处",b="这块石头传出了米兹拉尔的声音：缚灵石已被打开，枷锁正在松动，自由已近在咫尺。米兹拉尔称赞你是高尚的拯救者。"}},faq={{q="这一步来自哪里？",a="它来自虹色碎片，是在完成“公主被困”之后。",al={"缚灵石任务发布者","谁发布缚灵石任务","如何开始缚灵石任务"}},{q="四块缚灵石分别是什么？",a="西缚灵石、东缚灵石、外缚灵石，以及最强大的内缚灵石。",al={"哪些是缚灵石","阿拉希缚灵石","四块石头"}},{q="解锁内缚灵石需要哪些钥匙？",a="烈焰钥匙、海浪钥匙和雷霆钥匙，分别从西、东和外缚灵石处收集。",al={"缚灵钥匙","需要什么钥匙","内缚灵石的钥匙"}},{q="谁在看守缚灵石？",a="守护者们在看守着这些石头，不过聪明或幸运的冒险者也许能找到驱逐它们的方法。",al={"石头守护者","谁在看守石头","缚灵石保卫者"}},{q="钥匙必须送到哪里？",a="送到内缚灵石处，这是其中最强大的一块，必须先解锁它，其他石头才会打开。",al={"我该把钥匙带去哪里","交付缚灵石任务","内缚灵石位置"}}},fp="17,253,11.501.0,18.162.1,31.64.0,36.127.0,48.115.0,30.99.0,33.107.0"}
P.entries["quest:652"] = {n="打开钥匙之石",s="一旦束缚之石被开启，那个声音的禁锢便缓解了许多，但仍有一道锁将其困住。那道锁就是石环中的基石，而那个声音的囚禁者之一，岩石看守者Fozruk，持有这把钥匙。看守者们称其为秩序魔棒。",h="一旦束缚之石被开启，那个声音的禁锢便缓解了许多，但仍有一道锁将其困住。那道锁就是石环中的基石，而那个声音的囚禁者之一，岩石看守者Fozruk，持有这把钥匙。看守者们称其为秩序魔棒。",kw={"阿拉希高地","fozruk","基石","秩序魔棒","内在束缚之石","岩石看守者"},sec={{t="最后的锁",b="随着束缚之石被开启，那个声音的禁锢已经大大缓解，但仍有一道锁未解：基石，位于你周围的石环之中。它的钥匙由一名囚禁者持有，即岩石看守者Fozruk，看守者们称之为秩序魔棒。从Fozruk手中夺取魔棒并将其带到基石处，这道锁就会被解开。那个声音承诺，如果你能做到这一点，它的感激之情将震动大地的根基。基石本身充盈着巨大的地脉能量。"},{t="在基石处",b="当魔棒被插入基石时，你的脚下传来一阵颤动。"}},faq={{q="这一步之前要做什么？",a="首先是束缚之石，开启那些石头减轻了那个声音的大部分禁锢。",al={"前置条件","前置任务","束缚之石前置条件"}},{q="Fozruk是谁？",a="Fozruk是一位岩石看守者，也是那个声音的囚禁者之一，他持有基石的钥匙。",al={"fozruk是谁","fozruk背景故事","岩石看守者fozruk"}},{q="什么是秩序魔棒？",a="这是岩石看守者对基石钥匙的称呼，由Fozruk持有。",al={"秩序魔棒","什么是秩序魔棒","基石钥匙"}},{q="基石在哪里？",a="基石矗立在阿拉希高地的一处石环之中。",al={"破碎基石在哪里","基石位置","阿拉希石环"}}},fp="21,271,13.497.0,15.65.1,28.96.0,14.92.0,25.80.0,22.69.0"}
P.entries["quest:6523"] = {n="保护卡雅",s="“保护卡雅”是一个位于石爪山脉的部落护送任务。在发现卡雅·扁蹄被敌对的恐怖图腾牛头人俘虏后，冒险者将指引她穿过危险的山路，抵达阿帕拉耶营地。带回她幸存的消息，会让她焦急的父亲玛卡巴·扁蹄感到无比宽慰。",h="“保护卡雅”是一个位于石爪山脉的部落护送任务。在发现卡雅·扁蹄被敌对的恐怖图腾牛头人俘虏后，冒险者将指引她穿过危险的山路，抵达阿帕拉耶营地。带回她幸存的消息，会让她焦急的父亲玛卡巴·扁蹄感到无比宽慰。",kw={"阿帕拉耶营地","护送","恐怖图腾","卡雅·扁蹄","玛卡巴·扁蹄","保护卡雅","石爪山脉","牛头人"},ang={["faction:Horde"]="确保旅行家庭的安全可以巩固部落在石爪山脉来之不易的立足点和补给路线。",["race:Tauren"]="营救卡雅直接帮助了因恐怖图腾氏族的侵略行径而分崩离析的同胞。"},sec={{t="岩架上的囚徒",b="石爪山脉中弥漫着牛头人之间激烈的竞争，其中最尖锐的矛盾莫过于针对奸诈的恐怖图腾氏族的紧张局势。卡雅·扁蹄在敌对领地的深处被俘并遭到囚禁。徒步逃离需要穿过蜿蜒的小径，那里既有伺机而动的捕食者，又有警惕的敌人，因此武装护送是她能抵达安全地带的唯一现实希望。"},{t="前往阿帕拉耶营地",b="阿帕拉耶营地位于石爪山脉东部，卡雅知道从那里回家的路。她的目标是那个营地，并确信一旦抵达那里，她就能找到回家的路。护送她通过充满伏击的路径，可以确保她在抓捕者意识到她溜走之前避免再次被俘。"},{t="父亲的宽慰",b="玛卡巴·扁蹄在石爪山脉东南部边界等待消息，他非常担心失踪女儿的安危。当信使带来卡雅已安全抵达阿帕拉耶营地的确切消息时，玛卡巴的绝望转变成了对那些在他孩子与绑架者之间筑起防线的英雄们的无尽感激。"}},faq={{q="卡雅·扁蹄是谁？",a="卡雅·扁蹄是一位年轻的牛头人，在石爪山脉被敌对的恐怖图腾势力俘虏。她依靠路过的部落冒险者将她解救出来，并护送至安全地带。",al={"卡雅是谁","卡雅·扁蹄背景故事","卡雅"}},{q="卡雅需要被护送到哪里？",a="卡雅必须被安全地护送穿过通往石爪山脉东部阿帕拉耶营地的小径，从那里她知道回家的路。",al={"卡雅护送目的地","要把卡雅带到哪里","卡雅去哪里"}},{q="玛卡巴·扁蹄是谁？",a="玛卡巴·扁蹄是卡雅的父亲，焦急地等待在石爪山脉的东南部入口处。在冒险者带回她获救的消息之前，他一直为失踪的孩子感到绝望。",al={"玛卡巴是谁","玛卡巴·扁蹄背景故事","卡雅的父亲"}},{q="是谁俘虏了卡雅？",a="卡雅是被敌对的恐怖图腾牛头人俘虏的，他们在石爪山脉的岩架上设有营地并进行伏击。",al={"谁抓了卡雅","谁绑架了卡雅","卡雅的绑架者"}},{q="卡雅抵达阿帕拉耶营地后会发生什么？",a="一旦卡雅抵达阿帕拉耶营地，她就能找到回家的路，而玩家的任务是回到玛卡巴·扁蹄身边，传递她幸存下来的喜讯。",al={"保护卡雅之后","护送之后做什么","保护卡雅后续"}},{q="联盟玩家可以接这个任务吗？",a="不能。扁蹄家族属于热爱和平的牛头人，他们效忠于部落，因此这项救援任务仅限部落冒险者。",al={"联盟能做保护卡雅吗","卡雅是部落专属吗"}}},fp="12,240,22.398.0,22.255.0,17.273.1,21.180.0,36.106.0,23.198.0,18.100.0,45.137.0,44.117.0"}
P.entries["quest:653"] = {n="密斯莱尔的盟友",s="Myzrael大喊着她自由了，并且说她会躲起来积蓄力量以避开她的囚禁者。她称你为高尚的盟友，并让你去找位于铁炉堡Forlorn Cavern里的一家商店中的葛利·硬骨，他知道如何召唤她。",h="Myzrael大喊着她自由了，并且说她会躲起来积蓄力量以避开她的囚禁者。她称你为高尚的盟友，并让你去找位于铁炉堡Forlorn Cavern里的一家商店中的葛利·硬骨，他知道如何召唤她。",kw={"阿拉希高地","forlorn cavern","葛利·硬骨","巨人","铁炉堡","基石","myzrael"},sec={{t="重获自由积蓄力量",b="Myzrael自由了，她打算躲起来积蓄力量，避开她的囚禁者，因为如果现在与他们相遇，她肯定会被再次击败并囚禁起来。终有一天她要面对那些巨人，她发誓他们会后悔曾经囚禁过她。她称你为高尚的盟友，并说她会再次需要你的帮助，在她准备好时将她召唤到地表。"},{t="给葛利·硬骨的消息",b="Myzrael让你去和葛利·硬骨交谈，他的商店位于铁炉堡的Forlorn Cavern。他知道该如何召唤她。"}},faq={{q="在哪里可以找到葛利·硬骨？",a="葛利·硬骨在铁炉堡的Forlorn Cavern开了一家店。",al={"葛利·硬骨位置","葛利·硬骨在哪里","寻找葛利·硬骨"}},{q="为什么Myzrael要躲起来？",a="她需要先积蓄力量。如果她的囚禁者现在就面对她，她肯定会被再次击败并囚禁起来。",al={"为什么myzrael要躲藏","myzrael要去哪里"}},{q="Myzrael提到的囚禁者是谁？",a="是那些曾经监管她的巨人。她说终有一天她会去面对他们，他们会为此感到后悔。",al={"myzrael的囚禁者","谁囚禁了myzrael","myzrael和巨人"}},{q="为什么Myzrael让你去铁炉堡？",a="葛利·硬骨知道如何召唤她，她说当她准备好时，需要你把她召唤到地表。",al={"为什么去铁炉堡","拜访葛利的目的"}}},fp="16,237,23.352.0,24.133.0,35.64.0,35.125.0,38.106.0,39.125.0"}
P.entries["quest:654"] = {n="塔纳利斯的样本",s="开启电源后，野外测试工具包开始发光并振动。你现在有两个小时的时间来收集塔纳利斯的沙漠产物，否则数据就会丢失。",h="开启电源后，野外测试工具包开始发光并振动。你现在有两个小时的时间来收集塔纳利斯的沙漠产物，否则数据就会丢失。",kw={"蜥蜴","比格维兹","野外测试工具包","加基森","鬣狗","电源","蝎子","塔纳利斯","水业公司"},sec={{t="滴答作响的电源",b="电源启动后，工具包开始发光并振动，看起来一切运行正常。首席工程师沙克斯·比格维兹说，你需要在两小时内从塔纳利斯沙漠收集到足够的数据：从八只蜥蜴、八只鬣狗和八只蝎子身上采集的合格样本。如果时间耗尽，所有的东西都会丢失，你必须从比格维兹那里重新购买电源。在电量耗尽前，必须将该工具包带回加基森交给比格维兹。"},{t="公司的利润",b="对于任何工具包没电的人，比格维兹都不会表示同情。他唯一关心的就是加基森水业公司能赚多少钱。比格维兹愿意一直出售电源，直到公司有能力从丹莫罗的冰泉进口水源。"}},faq={{q="测试工具包需要采集哪些生物的样本？",a="从塔纳利斯沙漠的八只蜥蜴、八只鬣狗和八只蝎子身上采集的合格样本。",al={"需要测试哪些动物","样本采集目标","需要击杀什么"}},{q="完成样本采集有多少时间？",a="从电源开启的那一刻起，你有两个小时的时间。",al={"时间限制","我有多少时间","计时器"}},{q="如果电源耗尽会发生什么？",a="工具包里的一切都会损毁，你必须从加基森的首席工程师沙克斯·比格维兹那里重新购买一个电源才能重新开始。",al={"如果计时器时间到了","任务失败","电源耗尽"}},{q="装满后的测试工具包要送到哪里？",a="在电量耗尽前，送到加基森的首席工程师沙克斯·比格维兹那里。",al={"我该交给谁","交任务地点","比格维兹在哪里"}},{q="为什么比格维兹要一直出售电源？",a="比格维兹希望加基森水业公司能盈利，即使这意味着要通过出售电源来维持，直到公司有能力从丹莫罗的冰泉进口水源。",al={"比格维兹的目标","加基森水业公司的目标","为什么要采集样本"}}},fp="22,167,22.449.0,20.266.0,54.96.0,52.58.0,42.134.0,40.75.0,49.186.0"}
P.entries["quest:6541"] = {n="向卡德拉克报到",s="十字路口的索克指引有能力的部落战士前往灰谷边境附近的卡德拉克岗哨。卡德拉克负责协调部落向这座古老森林的扩张，并让新来的招募者为前方的持续冲突做好准备。",h="十字路口的索克指引有能力的部落战士前往灰谷边境附近的卡德拉克岗哨。卡德拉克负责协调部落向这座古老森林的扩张，并让新来的招募者为前方的持续冲突做好准备。",kw={"灰谷","贫瘠之地","十字路口","卡德拉克","碎木岗哨","索克","岗哨","佐拉姆海岸"},ang={["faction:Horde"]="这份调令标志着从保卫贫瘠之地已定居领土到确保北方争议森林中重要资源生命线的转变。",["race:Orc"]="灰谷是兽人至关重要的试炼场，确保了加固奥格瑞玛并在卡利姆多建立永久家园所需的木材。"},sec={{t="通往北方之路",b="当十字路口忙于应对野猪人、半人马和当地强盗时，部落更广泛的领土利益着眼于北方的灰谷茂密森林。索克充当中间人，将那些在贫瘠之地中部证明了自己的老练战士引导至卡德拉克驻守的北部边境岗哨。"},{t="边境战略",b="卡德拉克负责监管通往灰谷的南部路径，组织增援部队以巩固部落在边境线上的立足点。随着碎木岗哨和佐拉姆海岸前哨站等新营地的建立，部落尽管面临当地暗夜精灵的激烈抵抗，仍在积极巩固其在木材资源丰富的林地中的存在。"}},faq={{q="谁是索克？",a="索克是一名驻扎在贫瘠之地十字路口的兽人军官。他协助协调当地的防御工作，并将有前途的冒险者指派去参与灰谷战役等区域性的战争行动。",al={"索克 十字路口","谁给予向卡德拉克报到的任务","索克 贫瘠之地"}},{q="卡德拉克在哪里？",a="卡德拉克驻扎在贫瘠之地的北部岗哨，就在通往灰谷森林的主干道旁。",al={"卡德拉克位置","卡德拉克在哪里","卡德拉克 岗哨"}},{q="为什么部落要进军灰谷？",a="部落需要木材和资源来建设他们在杜隆塔尔和贫瘠之地的新城市。向灰谷扩张提供了至关重要的木材，尽管这使他们与暗夜精灵陷入了直接冲突。",al={"为什么是灰谷","部落在灰谷","灰谷入侵"}},{q="部落在灰谷建立了哪些前哨站？",a="卡德拉克提到，部落在通往森林的中央道路旁建立了碎木岗哨，并在更西边的佐拉姆海岸建立了另一个前哨站。",al={"部落在灰谷的基地","佐拉姆海岸基地","碎木岗哨"}},{q="向卡德拉克报到后会发生什么？",a="一旦你向卡德拉克报到，他会向你简要说明当地的军事局势，并指派你收集散布在灰谷各处的战歌伐木场哨所的报告。",al={"卡德拉克之后","卡德拉克之后的任务","卡德拉克提供什么"}},{q="除了贫瘠之地，还有其他地方能接到这个任务吗？",a="可以。石爪山脉玛拉卡金的部落战士也会接到一份几乎完全相同的去向卡德拉克报到的征召令。",al={"其他的卡德拉克任务","石爪山脉 卡德拉克任务"}}},fp="16,179,14.247.0,17.295.0,13.170.0,24.90.0,40.219.0,53.128.0,37.149.0,69.129.0"}
P.entries["quest:6542"] = {n="向卡德拉克报到",s="这份军事急报引导部落战士从石爪山脉的玛拉卡金前往位于北贫瘠之地边界的卡德拉克岗哨。这标志着从保卫山崖转为增援部落在灰谷内充满争议的军事行动。通过向卡德拉克报到，士兵们被召集起来支持碎木岗哨和佐拉姆海岸等前哨营地。",h="这份军事急报引导部落战士从石爪山脉的玛拉卡金前往位于北贫瘠之地边界的卡德拉克岗哨。这标志着从保卫山崖转为增援部落在灰谷内充满争议的军事行动。通过向卡德拉克报到，士兵们被召集起来支持碎木岗哨和佐拉姆海岸等前哨营地。",kw={"灰谷","贫瘠之地","达恩·鹰爪","卡德拉克","碎木岗哨","石爪山脉","战歌报告","佐拉姆海岸"},ang={["faction:Horde"]="这道命令将你纳入了酋长更广泛的战争努力中，将边境老兵投入到争夺灰谷资源的积极斗争中。",["race:Orc"]="灰谷战役对于战歌氏族和杜隆塔尔的生存至关重要，这也使卡德拉克的岗哨成为了年轻兽人战士的试炼场。",["race:Tauren"]="像兽人达恩·鹰爪这样的部落哨兵引导旅行者安全地穿越山区边界，保持了血蹄领地与酋长北方战线之间的通讯畅通。"},sec={{t="北方战线的征召",b="在玛拉卡金的崎岖山口，兽人达恩·鹰爪时刻注视着部落的南部和山区边境。然而，最大的军事压力来自于北方的灰谷古老森林，在那里，暗夜精灵哨兵与战歌伐木工不断发生冲突。达恩发现了途径石爪山脉的浴血战士，便引导有能力的征募兵前往北贫瘠之地的瞭望塔，以协助正在进行的战役。"},{t="卡德拉克的岗哨",b="兽人卡德拉克驻守在干旱大草原与灰谷葱郁树冠交汇的北部边界，负责监督部落军队进入争议领土的行动。部落正在积极巩固其立足点，在西部的佐拉姆海岸和北部的碎木岗哨都设有前哨。卡德拉克是协调这些交战森林前线物资、部队和紧急报告的重要枢纽。"}},faq={{q="是谁从石爪山脉派你去卡德拉克那里的？",a="达恩·鹰爪，一位驻扎在石爪山脉玛拉卡金部落前哨站的兽人，向前往森林边界的有能力的冒险者提供了这份急报。",al={"任务发布人：向卡德拉克报到","谁开启了向卡德拉克报到（石爪山脉）","达恩·鹰爪任务"}},{q="卡德拉克在哪里？",a="卡德拉克驻扎在贫瘠之地的北部瞭望塔，守卫着通往北面灰谷的主要道路。",al={"卡德拉克位置","卡德拉克在哪里","寻找卡德拉克"}},{q="为什么部落要为灰谷征募战士？",a="部落需要木材来维持奥格瑞玛的运转，并已建立了诸如佐拉姆海岸和碎木岗哨等防御阵地。由于这些行动遭到了当地暗夜精灵的强烈抵抗，指挥官们需要不断的增援来确保该地区的安全。",al={"为什么去灰谷","部落灰谷战役","为什么在灰谷作战"}},{q="向卡德拉克报到后会发生什么？",a="卡德拉克将向你简要介绍灰谷的战略局势，并指派你通过《战歌报告》在森林中的各处交战前哨传递和收集军事报告。",al={"向卡德拉克报到后做什么","战歌报告","卡德拉克后续任务"}},{q="这个任务和贫瘠之地的版本有什么不同吗？",a="这两个都是引导玩家前往灰谷边界卡德拉克处的引导任务。一个在贫瘠之地（十字路口）提供，而这一个在石爪山脉提供；完成其中任何一个都会引导你进入灰谷的故事线。",al={"贫瘠之地与石爪山脉卡德拉克任务","两个向卡德拉克报到的任务","卡德拉克引导任务重复"}},{q="简报中提到的佐拉姆海岸是什么地方？",a="佐拉姆海岸是位于灰谷西北部沿隐匿之海的一个沿海地区。部落在那里建立了一个防御性的海滩前哨，以支持战术行动并确保海上通道的安全。",al={"什么是佐拉姆海岸","佐拉姆海岸前哨站","灰谷海滩基地"}}},fp="16,244,28.376.0,14.295.0,40.138.0,24.98.0,51.199.0,39.129.0,49.188.0,51.187.0"}
P.entries["quest:6543"] = {n="战歌报告",s="这项任务由卡德拉克指派，他在贫瘠之地北部与灰谷交界的边境岗哨执勤。任务要求信使在这一交战森林区域协调前线情报。冒险者必须将常备军令送达，并从驻扎在艾萨拉、碎木岗哨和佐拉姆海岸附近的战歌氏族成员那里收集前线侦察信息。",h="这项任务由卡德拉克指派，他在贫瘠之地北部与灰谷交界的边境岗哨执勤。任务要求信使在这一交战森林区域协调前线情报。冒险者必须将常备军令送达，并从驻扎在艾萨拉、碎木岗哨和佐拉姆海岸附近的战歌氏族成员那里收集前线侦察信息。",kw={"灰谷","贫瘠之地","卡德拉克","碎木岗哨","战歌侦查骑兵","战歌报告","战歌信使","战歌斥候","佐拉姆海岸","佐拉姆加前哨站"},ang={["class:Hunter"]="在灰谷危机四伏的道路上行进，是对导航和野外生存技能的考验，必须应对野兽掠食者和隐藏的精灵弓箭手。",["faction:Horde"]="递送这些报告，标志着一名年轻的部落勇士在卡利姆多北部对抗暗夜精灵的领土斗争中迈出的真正第一步。",["race:Orc"]="对于兽人来说，支持战歌氏族既是氏族荣誉的表现，也是实际的需要，以确保木材源源不断地运往奥格瑞玛进行建设。"},sec={{t="边境后勤",b="卡德拉克伫立在贫瘠之地北缘的加固岗哨上，俯瞰着通往灰谷的狭窄山谷。对于部落而言，确保这条通道的安全至关重要：干旱的草原无法提供奥格瑞玛所需的巨量木材，这迫使战歌氏族深入古老的精灵林地。要让分散的前方巡逻队获得补给并保持同步，就需要可靠的信使，他们必须能够躲避灰谷危机四伏的荒野小径上的暗夜精灵伏击。"},{t="灰谷之眼",b="这项任务的路线横跨整片古老森林。在最西端雾气弥漫的佐拉姆海岸，一名战歌信使负责监视纳迦的活动以及佐拉姆加前哨站附近的沿海威胁。深入内陆的碎木岗哨，一名战歌斥候负责协调防御，抵御哨兵不断的突袭。在通往艾萨拉废墟的蜿蜒道路上向东更远处，一名战歌侦查骑兵负责监控东部的动向。从这三个哨站收集更新信息，能让卡德拉克对暗夜精灵的部队动向和边境漏洞有一个全局的了解。"}},faq={{q="这项任务在哪里开始？",a="任务开始于卡德拉克，他是一名兽人军官，驻守在贫瘠之地北部与灰谷南部交界处守护山口的木制岗哨内。",al={"任务发布者","卡德拉克位置","谁发布战歌报告任务","在哪里开始"}},{q="为什么部落要在灰谷进行侦察？",a="部落严重依赖灰谷茂密的木材来建造和加固像奥格瑞玛这样的定居点。当地的暗夜精灵拼死捍卫他们神圣的林地，使整个区域变成了一个活跃的战区，需要持续的侦察来维护哨站并保障补给线。",al={"为什么是灰谷","战歌伐木","灰谷冲突"}},{q="这三名战歌斥候在哪里可以找到？",a="战歌信使驻扎在最西北端佐拉姆海岸的佐拉姆加前哨站。战歌斥候驻守在大路旁的碎木岗哨。战歌侦查骑兵在通往艾萨拉边界的东部道路上巡逻。",al={"斥候位置","斥候在哪里","侦查骑兵信使斥候位置"}},{q="战歌侦查骑兵是谁？",a="战歌侦查骑兵是战歌兽人氏族的斥候和突袭者。他们以凶猛的骑兵和游击战术而闻名，是部落在灰谷森林进行扩张、木材采伐和领土防御的先锋。",al={"战歌氏族","谁是战歌侦查骑兵","灰谷的战歌氏族"}},{q="交回报告后会发生什么？",a="在收到收集到的情报后，卡德拉克会利用这些战术更新来规划后续的部队调动，增援佐拉姆加和碎木岗哨等脆弱的据点，并巩固部落在森林深处的存在。",al={"报告交付","下一步行动","卡德拉克的作用"}},{q="对于低等级信使来说，穿过灰谷的道路安全吗？",a="不安全。穿过灰谷的主干道经常面临隐身的暗夜精灵哨兵、潜行者和熊等危险野生动物的伏击，以及从阿斯特兰纳等定居点出动的联盟巡逻队的威胁。",al={"灰谷危险","道路是否安全","暗夜精灵偷袭"}}},fp="19,209,18.405.0,21.417.0,30.150.0,37.237.0,44.214.0,30.179.0,41.195.0,58.169.0"}
P.entries["quest:6544"] = {n="托雷克的突袭",s="“托雷克的突袭”是一场部落发动的直接突袭，他们从灰谷的荒野中出发，进攻附近银翼哨站的暗夜精灵驻军。在碎木岗哨的指令下，由兽人劫掠者托雷克率领，此次打击旨在粉碎当地哨兵的抵抗，并击杀她们的指挥官杜利尔·月火。这标志着在这场旷日持久的灰谷边境战争中，最鲁莽且血腥的冲突之一。",h="“托雷克的突袭”是一场部落发动的直接突袭，他们从灰谷的荒野中出发，进攻附近银翼哨站的暗夜精灵驻军。在碎木岗哨的指令下，由兽人劫掠者托雷克率领，此次打击旨在粉碎当地哨兵的抵抗，并击杀她们的指挥官杜利尔·月火。这标志着在这场...",kw={"灰谷","杜利尔·月火","埃尔托格·怒齿","劫掠者","哨兵","银翼哨站","碎木岗哨","托雷克"},ang={["class:Warrior"]="这是一场残酷的正面近战，考验着战士们面对经验丰富的哨兵弓箭手和刀锋战士时的纯粹肉体耐力。",["faction:Alliance"]="杜利尔·月火的倒下使银翼哨站陷入危机，并威胁到暗夜精灵的祖传林地领地。",["faction:Horde"]="对于部落来说，突破银翼哨站是一次至关重要的力量测试，削弱了包围碎木岗哨的暗夜精灵封锁线。",["race:NightElf"]="这场突袭直接打击了哨兵前线指挥的核心，在灰谷的树荫下洒下了精灵的鲜血。"},sec={{t="阴影中的打击",b="灰谷正陷入部落伐木场与当地暗夜精灵之间不断升级的边境战争。为了突破联盟的防御圈，托雷克在银翼哨站外集结了一队碎木岗哨的劫掠者。托雷克并没有等待反击，而是协调了一次正面冲锋，试图在暗夜精灵针对碎木岗哨组织起增援行动前，彻底摧毁哨站的防御。"},{t="攻占银翼",b="银翼哨站是一座防御森严的林地据点，驻守着警惕的银翼要塞守军和凶猛的精灵战士。托雷克的主要目标是她们的领袖，杜利尔·月火。击倒杜利尔就等于铲除了当地暗夜精灵的军事指挥中枢，让劫掠者们能够向碎木岗哨的埃尔托格·怒齿指挥官报告这一血腥的胜利。"}},faq={{q="谁是托雷克？",a="托雷克是一位激进的兽人劫掠者，活动于灰谷的碎木岗哨。他凶猛且渴望战斗，指挥着一支肩负重任的劫掠者小队，旨在直接打击盘踞在森林中的暗夜精灵部队。",al={"托雷克 npc","谁是托雷克","托雷克 兽人"}},{q="什么是银翼哨站？",a="银翼哨站是灰谷内一座防御性的暗夜精灵定居点。由精锐的哨兵和战士守卫，它是监视林间小道上部落军队动向的军事堡垒。",al={"银翼哨站","什么是银翼"}},{q="谁是杜利尔·月火？",a="杜利尔·月火是负责守卫银翼哨站的暗夜精灵指挥官。作为驻军首领，她指挥当地哨兵抵御部落的入侵，直到托雷克的突袭小队突破营地并将她击倒。",al={"杜利尔·月火","杜利尔"}},{q="谁是埃尔托格·怒齿？",a="埃尔托格·怒齿是驻扎在碎木岗哨的部落军官。他是托雷克的上级，负责监督该地区的军事行动，并接收针对联盟的胜利报告。",al={"埃尔托格·怒齿","埃尔托格"}},{q="部落为什么要攻击银翼哨站？",a="部落与暗夜精灵在整个灰谷陷入了激烈的领土战争。打击银翼哨站可以减轻部落补给线的压力，并直接削弱守护森林深处的哨兵防御网络。",al={"为什么攻击银翼","灰谷冲突 银翼"}},{q="这次袭击发生在哪里？",a="突袭始于银翼哨站外，位于灰谷内弗伦河东侧的部落控制区，并最终在暗夜精灵营地内部达到高潮。",al={"托雷克突袭地点","托雷克在哪里"}}},fp="15,265,25.355.0,17.340.0,13.206.0,27.186.0,23.222.1,22.189.0,45.220.0,34.161.0"}
P.entries["quest:6545"] = {n="战歌信使的报告",s="“战歌信使的报告”是一项部落的通讯任务，旨在连接灰谷的前线防御工事与边境各地的指挥官。这份信件被托付给信使和新兵，详细说明了战歌侦察兵所面临的军事压力日益增长，尤其是来自入侵纳迦的侵略行径。",h="“战歌信使的报告”是一项部落的通讯任务，旨在连接灰谷的前线防御工事与边境各地的指挥官。这份信件被托付给信使和新兵，详细说明了战歌侦察兵所面临的军事压力日益增长，尤其是来自入侵纳迦的侵略行径。",kw={"灰谷","卡德拉克","莫尔杉","纳迦","壁垒","报告","信使","侦察兵","战歌"},ang={["faction:Horde"]="森林前线的每一名士兵都很重要，在此处，维持贫瘠之地与前线哨站之间的通讯线路对于生存至关重要。",["race:Orc"]="战歌氏族依赖其信使的勇气和警惕，以守住在大酋长萨尔命令下所占领的土地。"},sec={{t="前线急报",b="战歌氏族在整个灰谷部署了一系列的侦察兵和信使，以监视周边的敌对势力并保持补给线畅通。由于与暗夜精灵哨兵的领土冲突以及恶劣的地理环境，迅速获取情报至关重要。运送前线急报的信使对于确保偏远哨站与驻扎在莫尔杉壁垒的卡德拉克等指挥官保持协调至关重要。"},{t="纳迦的威胁",b="虽然部落预计会遭遇来自树林中暗夜精灵的猛烈反抗，但前哨岗哨报告称，纳迦的袭击正变得日益大胆。这些蛇形入侵者从水道和古代遗迹发起突袭，试探着哨站的防御工事，并迫使守军分散注意力，无法专心进行林业生产和边境巡逻。带回莫尔杉壁垒的报告拉响了关于这些协同两栖攻击的警报。"}},faq={{q="这份报告是发给谁的？",a="这份报告被直接送回给卡德拉克，他是一位驻扎在莫尔杉壁垒的监工，该壁垒位于灰谷与北贫瘠之地交界的边境线上。",al={"谁收到报告","卡德拉克报告","报告去向"}},{q="报告中提到了哪些威胁？",a="侦察兵报告说，当地哨站已经抵御了多次袭击，并强调了附近水域中敌对纳迦日益升级的威胁。",al={"报告内容","信使报告详情","纳迦袭击"}},{q="为什么部落在这里依赖徒步信使？",a="茂密的植被、活跃的暗夜精灵神射手以及孤立的哨站使得空中运输在灰谷的部分地区变得困难重重或极易暴露。地面信使能够在受到保护的小径上进行迅速、隐秘的通讯。",al={"为什么需要信使","战歌信使背景","为什么不用双足飞龙"}},{q="什么是战歌信使？",a="他们是战歌氏族的侦察兵、信使和先锋战士，负责确保补给线的安全，并监视森林争议边境周围的敌军动向。",al={"战歌氏族灰谷","谁是战歌信使"}},{q="纳迦在灰谷的哪些地方发动攻击？",a="纳迦在灰谷的岸边和湖泊旁的遗迹中建立了据点，经常伏击旅行者并突袭附近的营地。",al={"纳迦在哪里","灰谷纳迦"}},{q="哨站在这个地区的作用是什么？",a="该哨所作为早期预警站和防御锚点，确保敌对势力无法切断深林伐木作业与贫瘠之地之间的通讯。",al={"哨站设立原因","部落营地目的"}}},fp="21,180,20.303.0,15.346.0,32.120.0,41.117.0,45.185.0,28.170.0,42.119.0,43.138.0"}
P.entries["quest:6546"] = {n="战歌侍从的报告",s="“战歌侍从的报告”是一个部落送达任务，任务发起始于灰谷东部险象环生的道路上。一名孤身在此的战歌斥候将一份至关重要的情报托付给了一位冒险者，这份情报详细记录了来自附近联盟军队、根深蒂固的萨特以及临近艾萨拉地区不断蔓延的纳迦所构成的威胁。",h="“战歌侍从的报告”是一个部落送达任务，任务发起始于灰谷东部险象环生的道路上。一名孤身在此的战歌斥候将一份至关重要的情报托付给了一位冒险者，这份情报详细记录了来自附近联盟军队、根深蒂固的萨特以及临近艾萨拉地区不断蔓延的纳迦...",kw={"灰谷","艾萨拉","卡德拉克","莫尔杉壁垒","纳迦","萨特","战歌侦查骑兵","战歌报告"},ang={["faction:Horde"]="每一份在莫尔杉防线上传递的简报，都巩固了部落在灰谷茂密森林中脆弱的立足点。",["race:Orc"]="战歌氏族以身处前锋为荣，但他们的斥候深知，仅凭勇气无法抵挡四面受敌的困境。"},sec={{t="森林边缘的注视",b="灰谷东部是一个充满争端的边界地区，部落的补给线在这里不断遭到袭扰。战歌氏族在丛林中保持着严密的警戒网，他们会在敌方突袭队威胁到莫尔杉壁垒或碎木岗哨等前哨站之前，就侦查到敌人的动向。遇到一名巡逻的战歌侦查骑兵，就意味着直接进入了一个活跃的侦查战区，在这里，情报可能决定了一个据点是能守住，还是会沦陷于伏击。"},{t="地平线上的威胁",b="这份由战歌侦查骑兵汇编的报告，勾勒出了部落在卡利姆多中部森林所面临的严峻战术局势。除了与暗夜精灵及更广泛的联盟之间无处不在的小规模冲突外，灰谷东部还潜伏着狡猾的恶魔萨特。更危险的是，斥候们发现大批纳迦正扩散至邻近的艾萨拉沿海废墟，这警告指挥官们，部落正处于几乎来自四面八方的敌对势力的包围之中。"}},faq={{q="什么是战歌报告？",a="这是一份由战歌侦查骑兵撰写的情报简报，总结了敌军的部署和区域威胁。它强调了来自附近联盟部队、灰谷东部活跃的萨特集会以及艾萨拉新发现的纳迦动向的威胁。",al={"战歌报告任务物品","报告上说了什么","斥候报告"}},{q="卡德拉克是谁？",a="卡德拉克是一位驻扎在莫尔杉壁垒的部落指挥官，那是守卫贫瘠之地和灰谷北部边界的防御屏障。他负责监管进出的斥候，并协调进入森林的前线行动。",al={"卡德拉克是谁","卡德拉克在哪里","卡德拉克交任务"}},{q="为什么要提到艾萨拉的纳迦？",a="艾萨拉直接与灰谷东部接壤。侦查骑兵会跟踪相邻领土上的外敌动向，以确保部落在应对暗夜精灵的同时，侧翼不会被大规模的入侵所突袭。",al={"纳迦与艾萨拉的联系","为什么要提到艾萨拉","艾萨拉的纳迦威胁"}},{q="为什么灰谷东部对部落如此危险？",a="该地区夹在活跃的联盟分遣队、渗透着恶魔腐化的远古萨特遗迹以及未驯服的丛林野兽之间，这使得部落的信使和巡逻队极易遭到来自各个方向的伏击。",al={"为什么灰谷东部很危险","灰谷的威胁","萨特威胁"}},{q="谁是战歌氏族？",a="他们是战歌氏族在灰谷的前锋部队和侦查骑兵，负责追踪暗夜精灵的动向、守卫伐木场并保障贸易路线的安全。",al={"什么是侦查骑兵","战歌斥候","侦查骑兵背景设定"}},{q="为什么侦查骑兵不能亲自递交报告？",a="这名侦查骑兵肩负着在小径上保持警戒的任务，以实时追踪敌对动向的发展。离开他的观察点，前线将无法及时察觉到联盟或萨特的突然袭击。",al={"我为什么要递交报告","为什么他不自己递交"}}},fp="23,209,26.387.0,24.363.0,27.252.0,14.226.0,38.222.0,56.223.0,30.182.0,50.184.0"}
P.entries["quest:6547"] = {n="战歌斥候的报告",s="战歌斥候的报告是一项部落的通讯任务，旨在连接灰谷边界的前哨指挥官与监视这片争议森林的前线斥候。信使携带来自卡德拉克的战略命令，以确保战歌氏族保持严密监视，防范暗夜精灵的伏击。它凸显了部落在他们新占领的领土上努力维持的岌岌可危、充满敌意的控制权。",h="战歌斥候的报告是一项部落的通讯任务，旨在连接灰谷边界的前哨指挥官与监视这片争议森林的前线斥候。信使携带来自卡德拉克的战略命令，以确保战歌氏族保持严密监视，防范暗夜精灵的伏击。它凸显了部落在他们新占领的领土上努力维持的岌岌...",kw={"灰谷","贫瘠之地","卡德拉克","暗夜精灵","报告","斥候","哨兵部队","战歌"},ang={["faction:Horde"]="每一位在卡德拉克和外围斥候之间传递命令的信使，都在帮助部落在灰谷站稳脚跟，抵御暗夜精灵不断的伏击。",["race:NightElf"]="战歌斥候在边界潜伏，代表着对艾露恩神圣森林的持续亵渎，而哨兵部队正致力于将其清除。",["race:Orc"]="战歌氏族的传奇由他们在灰谷的顽强意志所定义，尽管土地及其古老的守护者充满敌意，他们依然夺取了至关重要的木材。"},sec={{t="阴影中的双眼",b="灰谷的边境地区依然是一个火药桶，双方寸步不让。卡德拉克指挥下的部落军队严重依赖部署在高风险前哨的零散战歌斥候，来追踪暗夜精灵的动向并保护争议中的补给线。由于森林本身为联盟隐秘的哨兵提供了天然掩护，定期的报告和书面更新对于防止孤立的斥候被切断联系并遭歼灭至关重要。"},{t="坚守阵地",b="对战歌氏族来说，每一片被清理或占领的森林都是用鲜血换来的。斥候们时刻警惕着旨在夺回林地的暗夜精灵报复性突袭。传递卡德拉克的命令让先锋部队确信增援和协调依然在进行，并使斥候能够汇报他们的防御措施在持续的精灵抵抗下依然行之有效。"}},faq={{q="卡德拉克是谁？",a="卡德拉克是一名驻扎在贫瘠之地与灰谷边界的部落指挥官。他负责协调侦察任务、边境防御，以及为侵入古老森林的战歌行动提供后勤支持。",al={"卡德拉克","卡德拉克是谁","卡德拉克的职责"}},{q="为什么战歌斥候对暗夜精灵如此警惕？",a="暗夜精灵能自然地融入他们祖传森林的阴影中，对部落巡逻队发动突袭。由于战歌氏族正在积极清理木材并定居在精灵视为圣地的土地上，斥候们时刻面临着致命偷袭的威胁。",al={"为何惧怕暗夜精灵","阴影中的暗夜精灵","战歌斥候面临的精灵威胁"}},{q="为什么灰谷会成为争夺焦点？",a="部落需要灰谷的木材和资源来建设奥格瑞玛，并支持其在干旱的贫瘠之地和杜隆塔尔的定居点。当地的暗夜精灵将森林视为圣地，并积极抗争，试图将兽人伐木工和驻军赶走。",al={"为何争夺灰谷","灰谷战争","部落在灰谷的冲突"}},{q="战歌氏族在这里的角色是什么？",a="战歌氏族是部落在灰谷扩张和资源采集的先锋。他们在第三次战争期间由格罗姆·地狱咆哮带领进入森林，此后他们的存在一直根深蒂固，运营着伐木场，并与哨兵部队进行着持续的小规模冲突。",al={"战歌氏族在灰谷","战歌氏族的职责"}},{q="这份报告在送达斥候后会去哪里？",a="在斥候收到卡德拉克的最新指示后，他们会将针对精灵反击的当地战况汇报回去，确保部落领导层随时掌握前线的稳定情况。",al={"报告的接收者","卡德拉克的报告","斥候报告的结果"}},{q="部落目前在灰谷的计划进展顺利吗？",a="前线斥候认为他们的防御工作是成功的，能够守住防御阵地并击退精灵的打击，尽管该地区仍然是一个激烈争夺的战场，双方都未能取得绝对优势。",al={"部落是否在灰谷占据优势","战歌氏族的进展"}}},fp="20,180,19.293.0,18.297.0,14.170.0,57.213.0,35.224.0,37.217.0,51.171.0,60.193.0"}
P.entries["quest:6548"] = {n="为我的村庄复仇",s="玛卡巴·扁蹄在石爪山脉东南部的村庄遭到恐怖图腾部族的突袭，他侥幸逃过一劫。他与族人失散，周围满是尸体。他请求部落的旅者反击恐怖图腾恶棍和雇佣兵的营地，为他死去的族人复仇。",h="玛卡巴·扁蹄在石爪山脉东南部的村庄遭到恐怖图腾部族的突袭，他侥幸逃过一劫。他与族人失散，周围满是尸体。他请求部落的旅者反击恐怖图腾恶棍和雇佣兵的营地，为他死去的族人复仇。",kw={"复仇之村","恐怖图腾","恐怖图腾雇佣兵","恐怖图腾恶棍","格伦迪格·黑云","玛卡巴·扁蹄","石爪山脉"},ang={["faction:Horde"]="部落依赖于贫瘠之地和石爪山脉之间开放且安全的通道。一支残暴的恐怖图腾小队谋杀旅客和盟友村庄，威胁到了大酋长穿过山脉的补给线。",["race:Tauren"]="恐怖图腾部族的背叛对牛头人旅客打击最大。看到同胞舒哈鲁（shu'halo）被同类屠杀，更加凸显了部族分裂的残酷现实，以及恐怖图腾对凯恩的团结子民所构成的危险。"},sec={{t="岩石中的鲜血",b="在贫瘠之地与石爪山脉红石隘口的边界附近，玛卡巴·扁蹄独自站在一场残酷大屠杀的余波中。打着恐怖图腾部族黑暗旗帜的掠夺者毫无预兆地突然袭击，杀光了他定居点里的所有人。虽然玛卡巴奋力反击并击倒了几名袭击者，但最终还是被迫逃亡，只剩下一条命和满腔怒火。"},{t="恐怖图腾的威胁",b="恐怖图腾长期以来一直是大酋长凯恩·血蹄领导下团结的牛头人部落中桀骜不驯、充满侵略性的眼中钉。与在莫高雷游荡的和平游牧民不同，恐怖图腾战团经常雇佣冷酷的恶棍和投机取巧的雇佣兵来开拓领土，袭击孤立的定居点。对玛卡巴来说，外交或部落亲情现在毫无意义；只有血债血偿才能缓解他的悲痛。"}},faq={{q="谁发布了这个任务？",a="玛卡巴·扁蹄是一位驻扎在通往石爪山脉东南隘口附近的牛头人幸存者。他在附近村庄遭到恐怖图腾部族的暴力洗劫后幸存下来，并寻求向那些掠夺者复仇。",al={"任务发布者","玛卡巴·扁蹄","玛卡巴是谁"}},{q="为什么恐怖图腾要袭击其他牛头人？",a="恐怖图腾部族从来没有真正拥护过部落的团结，也不认可凯恩·血蹄的和平愿景。他们极具领地意识、排外且充满攻击性，他们公开劫掠敌对定居点，杀害外来者，并利用武装暴徒和雇佣兵来宣称对石爪山脉等地区的主权。",al={"为何恐怖图腾敌对","牛头人攻击牛头人","恐怖图腾部族背景故事"}},{q="恐怖图腾袭击者在哪里？",a="恐怖图腾的恶棍和雇佣兵驻扎在玛卡巴·扁蹄在石爪山东南部位置以西的一个营地里，位于俯瞰隘口的岩石山丘中。",al={"怪物在哪里","恐怖图腾营地位置","去哪里找恶棍"}},{q="谁是恐怖图腾雇佣兵？",a="恐怖图腾部族经常通过雇佣冷酷的战士和雇佣兵来加强其战团，从而补充自身兵力，确保他们有足够的武力来恐吓和践踏孤立的定居点。",al={"雇佣兵","恐怖图腾雇佣兵","雇佣兵是谁"}},{q="这个任务之后会发生什么？",a="在消灭了前线的恶棍和雇佣兵后，玛卡巴请求你去打击大屠杀背后的首领——格伦迪格·黑云（Grundig Darkcloud），这在后续任务“杀死格伦迪格·黑云”中进行。",al={"后续任务","复仇之村后续","杀死格伦迪格·黑云"}},{q="玛卡巴的村庄位于哪里？",a="玛卡巴的定居点是一个孤立的牛头人营地，位于石爪山脉东南部的边界隘口附近。它在恐怖图腾的突袭中被彻底摧毁，玛卡巴是为数不多的已知幸存者之一。",al={"扁蹄村","村庄在哪里","哪个村庄被摧毁"}}},fp="17,259,18.341.0,20.363.0,20.195.0,45.262.0,42.146.0,34.132.0,30.138.1,35.187.0"}
P.entries["quest:655"] = {n="落锤镇",s="落锤镇讲述了部落大酋长Orgrim Doomhammer在阿拉希高地解放一座联盟收容所时不幸阵亡的悲剧。通过戈穆尔那些充满悲痛的回忆，旅人们得以了解这座营地是如何被解放的，以及这座据点为何拥有这个庄严的名字。",h="落锤镇讲述了部落大酋长Orgrim Doomhammer在阿拉希高地解放一座联盟收容所时不幸阵亡的悲剧。通过戈穆尔那些充满悲痛的回忆，旅人们得以了解这座营地是如何被解放的，以及这座据点为何拥有这个庄严的名字。",kw={"阿拉希高地","orgrim doomhammer","戈穆尔","落锤镇","收容所","萨尔","托尔甘"},ang={["class:Warrior"]="Orgrim Doomhammer依然是一位标志性的传奇战士，行走在他阵亡的战场上具有沉重的军事意义。",["faction:Horde"]="落锤镇作为一座庄严的纪念碑，见证了兽人收容所的解放和大酋长Orgrim Doomhammer的牺牲。",["race:Orc"]="对于兽人来说，Orgrim Doomhammer在阿拉希的倒下是他们历史上最痛苦的时刻之一，这标志着一个时代的结束和萨尔领导的新部落的崛起。"},sec={{t="血与断链",b="落锤镇曾是一座阴森的联盟收容所，在第二次战争后，俘虏的兽人们被囚禁在木头与钢铁构成的牢笼中。当年轻的萨尔和大酋长Orgrim Doomhammer发起突袭，击碎了牢笼并解放了他们的族人时，一切都改变了。尽管这次突袭成功解放了许多俘虏并摧毁了营地的防御，但它却以悲剧告终：Orgrim Doomhammer在冲锋中被一名骑兵从背后用长矛刺中，倒在了如今这座部落定居点所在的土地上。"},{t="失败的阴影",b="并非每一位俘虏在那命运之日都获得了自由。在战斗的混乱和大地的震颤中，一位名叫戈穆尔的兽人眼睁睁看着那位传奇大酋长倒下，丧失了所有的斗志。当他的同胞逃离时，他被留在了原地，戈穆尔在荒原上漫无目的地游荡，心中充满了悲伤。即使如今部落已将此地收复为一座堡垒，那次卑劣袭击的记忆仍困扰着幸存者们。"}},faq={{q="谁是戈穆尔？",a="戈穆尔曾是被关押在落锤镇旧址收容所里的一名兽人俘虏。尽管萨尔和Orgrim Doomhammer发起突袭解放了该营地，但戈穆尔在混乱的逃亡中被抛下，在绝望中孤独地游荡了多年。",al={"谁是戈穆尔","戈穆尔背景故事","戈穆尔的经历"}},{q="Orgrim Doomhammer是如何阵亡的？",a="Orgrim Doomhammer在解放阿拉希收容所的战斗中阵亡。当他身穿黑色板甲领导进攻时，一名骑马冲锋的联盟骑士从背后用长矛刺穿了他的身体。",al={"orgrim doomhammer是如何阵亡的","谁杀了orgrim doomhammer","orgrim doomhammer阵亡的故事"}},{q="为什么这座前哨站被命名为落锤镇？",a="这座前哨站被命名为落锤镇，是为了纪念在此地为了将族人从人类的囚禁中解放出来而阵亡的大酋长Orgrim Doomhammer。部落后来回到了这座荒废的营地，建立了一座永久的基地。",al={"为什么叫落锤镇","落锤镇名字的由来","落锤镇历史"}},{q="谁是托尔甘？",a="托尔甘是驻扎在落锤镇的一名部落代表，他帮助照看这座营地，并理解像戈穆尔这样的前俘虏所遭受的创伤。",al={"谁是托尔甘","托尔甘 落锤镇","托尔甘任务"}},{q="萨尔参加了此地的战斗吗？",a="是的。萨尔与大酋长Orgrim Doomhammer并肩作战，袭击了这座阿拉希收容所。他们共同击碎了营地的防御以解放被俘的兽人，尽管这场胜利的代价是Orgrim Doomhammer的生命。",al={"萨尔和orgrim doomhammer 阿拉希","落锤镇的解放","萨尔在落锤镇战斗过吗"}},{q="为什么戈穆尔如此消沉？",a="戈穆尔亲眼目睹Orgrim Doomhammer倒下，这击碎了他的精神。当其他俘虏逃入荒野时，他被留在了原地，在毫无希望的情况下漫无目的地游荡，直到部落回来建立了落锤镇。",al={"为什么戈穆尔如此悲伤","戈穆尔的消沉","戈穆尔为什么失去希望"}}},fp="10,276,23.483.0,30.437.0,15.253.0,30.240.0,36.226.0,15.172.0,40.235.0,29.230.0"}
P.entries["quest:656"] = {n="召唤大地公主",s="迷失者塞尔杜林说，必须在密斯莱尔还在成长时将其击败，不能让她积蓄起足以挑战监禁者们的力量。你需要在密斯莱尔之碎片处召唤她，将其击败，并将她的怪异镣铐束缚在这些碎片上。",h="迷失者塞尔杜林说，必须在密斯莱尔还在成长时将其击败，不能让她积蓄起足以挑战监禁者们的力量。你需要在密斯莱尔之碎片处召唤她，将其击败，并将她的怪异镣铐束缚在这些碎片上。",kw={"阿拉希高地","怪异镣铐","密斯莱尔","密斯莱尔卷轴","密斯莱尔之碎片","迷失者塞尔杜林"},sec={{t="为什么要阻止她",b="塞尔杜林希望在密斯莱尔的力量膨胀到足以对抗她的监禁者之前就阻止她。有人声称她可以被控制；塞尔杜林反问，如果真是这样，巨人为什么还要费尽心机去锁住她。"},{t="在碎片处",b="你带着密斯莱尔卷轴前往密斯莱尔之碎片，也就是你第一次与她交谈的地方，将她召唤出来。在你击败她之后，你便可以把她的怪异镣铐束缚在碎片上，再次将她封印。"},{t="当镣铐被安置好后",b="当镣铐在碎片周围稳固时，深处传来一声哀号，紧接着是一声咆哮。碎片曾经给予的温暖与安全感荡然无存。现在，它们脉动着显而易见的威胁，仿佛藏在它们之下的东西对地表怀有恶意。"}},faq={{q="谁派你去对付密斯莱尔？",a="迷失者塞尔杜林。他警告说，必须在密斯莱尔的力量增长到足以挑战她的监禁者之前将其击败。",al={"任务发布者","谁给予召唤公主任务","塞尔杜林任务"}},{q="召唤在什么地方进行？",a="在密斯莱尔之碎片，也就是你第一次与她交谈的地方。",al={"在哪里召唤密斯莱尔","密斯莱尔之碎片位置","召唤地点"}},{q="为什么塞尔杜林想要击败密斯莱尔？",a="塞尔杜林担心她会变得足够强大，从而挑战她的监禁者。塞尔杜林还指出，如果她真的能被控制，巨人就不会把她锁起来了。",al={"为什么要杀掉密斯莱尔","塞尔杜林的动机","为什么要召唤她"}},{q="密斯莱尔是如何被召唤的？",a="使用密斯莱尔卷轴，在密斯莱尔之碎片处使用。",al={"如何召唤她","密斯莱尔卷轴的使用","召唤过程"}},{q="你如何处理怪异镣铐？",a="击败密斯莱尔，取得她的镣铐，并将它们固定在碎片上。这样她就会再次被封印。",al={"需要什么物品","怪异镣铐"}}},fp="22,248,23.195.0,13.212.0,28.245.1,31.116.0,36.68.0,41.173.0,24.58.0,42.92.0"}
P.entries["quest:65601"] = {n="Love Hurts",s="Gan'rul让你沿着奥格瑞玛的主街寻找Magar。他对Krilge的思念或许能指向召唤魅魔来到现世所需的物品。",h="Gan'rul让你沿着奥格瑞玛的主街寻找Magar。他对Krilge的思念或许能指向召唤魅魔来到现世所需的物品。",kw={"cleft of shadow","gan'rul","魅魔","krilge","爱让人受伤","magar","奥格瑞玛","萨亚德"},sec={{t="Magar的寻觅",b="Magar住在暗影裂口以东。他盼望Krilge归来，并请你寻找一件珍贵之物。把那件物品带给Gan'rul，他需要一件饱含爱意与忠诚的物品来召唤魅魔。"}},faq={{q="Magar是谁？",a="Magar住在奥格瑞玛的主街附近，盼望Krilge归来。",al={"magar是谁"}},{q="Krilge是谁？",a="Krilge是Magar的伴侣，Magar盼望着他归来。",al={"krilge是谁","magar的伴侣"}},{q="魅魔是什么？",a="魅魔是男性萨亚德，以极度邪恶、一心一意著称。",al={"魅魔含义","男性萨亚德"}},{q="Gan'rul需要什么？",a="Gan'rul需要一件代表深厚爱意与忠诚的物品，以引诱魅魔来到现世。",al={"gan'rul需要什么","魅魔召唤物品"}},{q="我在哪里能找到Magar？",a="Magar住在暗影裂口以东，奥格瑞玛的主街附近。",al={"magar的位置","magar在哪里"}}},fp="10,149,14.211.0,13.75.0,14.50.0,19.76.0,23.96.0,23.69.0"}
P.entries["quest:6561"] = {n="黑暗深渊中的邪恶",s="“黑暗深渊的邪恶”是一项紧急请求，由一名被困在黑暗深渊内部且生命垂危的银色黎明十字军战士发出。部落的冒险者受命去终结梦游者克尔里斯，这位邪教领袖正在下方的废墟中策划着向某种古老怪物的恐怖血祭。",h="“黑暗深渊的邪恶”是一项紧急请求，由一名被困在黑暗深渊内部且生命垂危的银色黎明十字军战士发出。部落的冒险者受命去终结梦游者克尔里斯，这位邪教领袖正在下方的废墟中策划着向某种古老怪物的恐怖血祭。",kw={"阿库麦尔","银色黎明","巴珊娜·符文图腾","黑暗深渊","黑暗深渊的邪恶","克尔里斯","月亮井","塞尔瑞德","梦游者克尔里斯","暮光之锤"},ang={["class:Druid"]="虚空崇拜邪教徒和纳迦对一座古老暗夜精灵月亮井的亵渎，是卡利姆多的自然和精神圣地上的一道痛苦伤口。",["class:Shaman"]="由克尔里斯和阿库麦尔引起的动荡触犯了元素的平衡，将纯净的地下水扭曲成了一个充满阴影和祭祀的溃烂之地。",["faction:Horde"]="对于部落来说，与一名银色黎明侦察兵达成这一契约，代表了在对抗宇宙祸害这一共同利益上难得的时刻，从而赢得了银色黎明的早期好感。",["race:Tauren"]="巴珊娜·符文图腾将击败克尔里斯视为对大地母亲至关重要的防御，清除了一个试图将世界的自然秩序推向原始混沌的憎恶。"},sec={{t="绝望的背水一战",b="银月守卫塞尔瑞德被吸引到了灰谷海岸下的地下神庙中，却发现了远比单纯的纳迦入侵更可怕的恐怖。这名暗夜精灵在洞穴中身受重伤、精疲力竭，他意识到自己无法独自完成任务。与其让自己的侦察成果随自己而去，他向任何愿意打击盘踞在沉没大厅中的黑暗势力的路过的部落勇士寻求帮助。"},{t="深渊的祭品",b="这项任务的目标是梦游者克尔里斯，他是暮光之锤邪教徒的首领，这些邪教徒已经在废墟般的Temple of the Moon中扎下根来。克尔里斯与当地的纳迦结盟，在受亵渎的月亮井上进行黑暗仪式，将活着的俘虏喂给阿库麦尔——一头贪婪的多头蛇，也是上古之神的野兽——以此疯狂追求宇宙力量和原始混沌。"},{t="带给雷霆崖的消息",b="银色黎明曾一度认为克尔里斯已死或失踪，因此确认他的死讯至关重要。与其强迫英雄们回到人类领土，塞尔瑞德指示将这名邪教领袖死亡的证明交给雷霆崖长者高地的巴珊娜·符文图腾。巴珊娜与大地母亲的自然平衡有着深刻的感应，她赞扬了这一胜利，因为这消除了意图将卡利姆多拖入原始废墟的邪恶腐化。"}},faq={{q="谁是梦游者克尔里斯？",a="克尔里斯是占领了黑暗深渊的暮光之锤邪教徒的首领。银色黎明曾以为他已死或失踪，但他却一直在受腐化的月亮井中通过向古老多头蛇阿库麦尔献上活祭来秘密积蓄力量。",al={"克尔里斯","谁是克尔里斯","梦游者克尔里斯"}},{q="为什么会有银色黎明成员在黑暗深渊里？",a="银月守卫塞尔瑞德前来调查这座暗夜精灵废墟神庙中日益增长的威胁。他被其中的居民击溃且身受重伤，被困在此地，必须依靠路过的冒险者来完成他的职责并消灭克尔里斯。",al={"银月守卫塞尔瑞德","为什么塞尔瑞德在这里","银色黎明在黑暗深渊"}},{q="阿库麦尔是什么？",a="阿库麦尔是一头巨大的古老多头蛇，被认为是上古之神的原始仆从。它沉睡在沉没的废墟之下，当深层的地下腐化污染了神庙的神圣水域时，它苏醒了，现在它吞噬着由暮光之锤送来的俘虏。",al={"阿库麦尔","谁是阿库麦尔","阿库麦尔背景故事"}},{q="为什么要将任务提交给巴珊娜·符文图腾？",a="塞尔瑞德指引部落勇士前往雷霆崖长者高地寻找巴珊娜·符文图腾。作为大地母亲平衡的守护者，巴珊娜与对抗古老邪恶的防御者们保持联系，并将克尔里斯对上古之神的崇拜视为卡利姆多上令人憎恶的祸害。",al={"巴珊娜·符文图腾","为什么在雷霆崖","黑暗深渊的邪恶任务去哪交"}},{q="黑暗深渊的废墟发生了什么？",a="很久以前，这个地下建筑群是一座供奉月亮女神艾露恩的神圣神庙。大灾变和来自地底的古老黑暗渗漏污染了宏伟的月亮井，使纳迦和末日邪教徒得以将这些沉没的圣所据为己有，献给他们黑暗的主人阿库麦尔。",al={"黑暗深渊的历史","艾露恩神庙废墟","为什么黑暗深渊被腐化了"}},{q="暮光之锤邪教在此的目标是什么？",a="暮光之锤试图通过崇拜上古之神将世界带回原始混沌的时代。克尔里斯寻求通过黑暗交流获得个人力量，将无辜者投入深渊以换取古老实体的青睐。",al={"暮光之锤的动机","为什么邪教在黑暗深渊","克尔里斯的目标"}}},fp="20,242,22.310.0,22.297.0,21.314.1,28.228.0,54.228.0,16.246.0,43.250.0,48.257.0,52.211.0"}
P.entries["quest:65610"] = {n="Wish You Were Here",s="一位月布制作者请你前往灰谷的坠星湖寻找Krilge。曾与他并肩服役的人称他为逃兵，但制作者相信他并未擅离岗位。",h="一位月布制作者请你前往灰谷的坠星湖寻找Krilge。曾与他并肩服役的人称他为逃兵，但制作者相信他并未擅离岗位。",kw={"灰谷","沼泽兽","逃兵","坠星湖","甘鲁尔·血眼","krilge","失踪","月布"},sec={{t="失踪的朋友",b="制作者在灰谷制作月布时结识了Krilge。Krilge奉命驻守当地保护平民，之后却失踪了。他们常在坠星湖相会，直到凶猛的沼泽兽占据了那里。制作者仍希望查明他的下落。"},{t="湖畔寻踪",b="有人请你调查坠星湖，并将发现报告给奥格瑞玛的甘鲁尔·血眼。此番搜寻或许能找到Krilge的踪迹，他的战友已经不再寻找他了。"}},faq={{q="Krilge是谁？",a="Krilge曾驻守灰谷保护平民，后来失踪了。他和月布制作者常在坠星湖相会。",al={"krilge","月布制作者失踪的朋友"}},{q="为什么Krilge被称为逃兵？",a="Krilge从岗位上失踪后，曾与他并肩服役的人不再寻找他，并认定他是逃兵。",al={"krilge逃兵","他们为何不再寻找"}},{q="是谁请你寻找Krilge？",a="一位在灰谷结识Krilge的月布制作者请你寻找他的踪迹。",al={"是谁派我来的","月布制作者"}},{q="Krilge和制作者在哪里见面？",a="在凶猛的沼泽兽占据该地之前，他们常在灰谷的坠星湖相会。",al={"krilge会面地点","坠星湖在哪里"}},{q="你应该把发现报告给谁？",a="有人请你将发现报告给奥格瑞玛的甘鲁尔·血眼。",al={"向甘鲁尔报告","我该向谁报告"}}},fp="18,176,16.255.0,11.187.0,14.134.0,38.110.0,32.83.0,36.94.0,38.71.0"}
P.entries["quest:6562"] = {n="帮助耶努萨克雷",s="“深渊中的麻烦”是一项从石爪山脉发出的求援呼吁，目标直指遥远的灰谷海岸。苏纳曼指引部落的冒险者前往佐拉姆加前哨站寻找巨魔学者耶努萨克雷，并警告说海岸边潜伏着危险的势力。",h="“深渊中的麻烦”是一项从石爪山脉发出的求援呼吁，目标直指遥远的灰谷海岸。苏纳曼指引部落的冒险者前往佐拉姆加前哨站寻找巨魔学者耶努萨克雷，并警告说海岸边潜伏着危险的势力。",kw={"灰谷","黑暗深渊","耶努萨克雷","石爪山脉","苏纳曼","狂风峭壁","佐拉姆海岸","佐拉姆加前哨站"},ang={["class:Shaman"]="佐拉姆海岸波涛下的骚动威胁到了当地水之灵的平衡，需要精神上的洞察力来净化这种腐朽。",["faction:Horde"]="在佐拉姆加前哨站坚守阵地，对于保卫卡利姆多的西侧防线免受暗夜精灵部队和海岸恐怖的侵害至关重要。",["race:Troll"]="响应耶努萨克雷的呼唤为暗矛部族的族人提供了一个至关重要的机会，去协助他们最杰出的学者之一揭开远古卡利姆多的谜团。"},sec={{t="海岸的召唤",b="在石爪山脉干旱的峭壁上，苏纳曼察觉到北方传来的黑暗隆隆声不容忽视。他派遣有能力的部落旅人穿过灰谷——暗夜精灵的祖传林地——去与耶努萨克雷取得联系。耶努萨克雷驻扎在被称为佐拉姆海岸的遥远西缘的佐拉姆加前哨站，他发现自己正面临着需要外界干预的日益严重的危险。"},{t="通往佐拉姆海岸之路",b="对于部落的旅人来说，抵达灰谷的西海岸并非易事。无论是穿过地精出没的狂风峭壁隘口，还是从贫瘠之地向北出发，旅人们都必须进入由暗夜精灵哨兵严密守卫的敌对森林。穿过密集的树冠，在那被风暴冲刷的佐拉姆海岸上，这座孤零零的前哨站正一边窥视着附近阴影笼罩的水域，一边苦苦支撑。"},{t="波涛下的低语",b="抵达海岸后，耶努萨克雷揭示了正在酝酿的麻烦根源于黑暗深渊的地下神庙。古老的腐蚀、邪恶的水元素和暮光之锤的邪教徒们聚集在潮汐之下，诱使远古邪恶重返世界。耶努萨克雷依靠前来的勇士深入地表之下，直面在那沉没大厅中被唤醒的原始恐怖。"}},faq={{q="谁给予了任务“深渊中的麻烦”？",a="位于石爪山脉的苏纳曼提供了这项任务。他意识到灰谷海岸线的盟友需要增援，并指引旅行中的部落冒险者前往大海。",al={"任务发布者","谁开启深渊中的麻烦","苏纳曼"}},{q="耶努萨克雷在哪里？",a="耶努萨克雷驻扎在佐拉姆海岸的佐拉姆加前哨站，位于灰谷最西端的海岸线上。",al={"耶努在哪里","耶努萨克雷位置","佐拉姆加前哨站"}},{q="如何从石爪山脉到达佐拉姆加前哨站？",a="旅人可以向东北穿过狂风峭壁进入灰谷，或者向东绕过贫瘠之地并从南面进入森林。从灰谷中部出发，径直向西走，直到到达佐拉姆海岸的开阔水域。",al={"通往灰谷的路径","如何前往佐拉姆海岸","从石爪山脉到灰谷的路线"}},{q="耶努萨克雷在调查什么麻烦？",a="耶努萨克雷正在监视附近的黑暗深渊废墟，那里的邪教徒和受腐蚀的水生实体正在地表之下搅动远古恐怖。",al={"佐拉姆海岸发生了什么","为什么耶努需要帮助"}},{q="“深渊中的麻烦”后续任务是什么？",a="与耶努萨克雷交谈将直接引出“阿库麦尔的精华”，该任务会派遣冒险者进入黑暗深渊，从其隧道中收集被元素充能的阿库麦尔蓝宝石。",al={"下一个任务","深渊中的麻烦后续"}},{q="为什么穿越灰谷的旅程被认为是危险的？",a="灰谷是暗夜精灵的领地，他们会激烈抵制任何部落的入侵。穿过林地的旅人面临着遭遇敌对哨兵和隐秘伏击者的风险。",al={"灰谷的危险","暗夜精灵威胁"}}},fp="20,191,22.265.0,24.355.0,24.318.1,41.99.0,32.96.0,51.196.0,37.144.0,40.120.0,57.133.0"}
P.entries["quest:6563"] = {n="阿库麦尔水晶",s="位于佐拉姆加前哨站的耶努萨克雷发现，黑暗深渊的娜迦正在洞穴中采集威力强大的蓝宝石簇。出于对这些宝石所蕴含的魔法属性和元素水能量的担忧，这位萨满委托部落冒险者在这些宝石被滥用之前将其回收。",h="位于佐拉姆加前哨站的耶努萨克雷发现，黑暗深渊的娜迦正在洞穴中采集威力强大的蓝宝石簇。出于对这些宝石所蕴含的魔法属性和元素水能量的担忧，这位萨满委托部落冒险者在这些宝石被滥用之前将其回收。",kw={"灰谷","黑暗深渊","耶努萨克雷","娜迦","阿库麦尔蓝宝石","深渊中的麻烦","水之灵","佐拉姆海岸"},ang={["class:Shaman"]="耶努萨克雷对水晶的解读揭示了束缚在其中的躁动不安的水之灵，这是一种微妙的警告，表明元素力量正在神庙下方受到腐蚀。",["faction:Horde"]="部落在佐拉姆加前哨站的立足点岌岌可危；阻止附近的娜迦获取原始魔法力量有助于保护这个海岸营地。",["race:Troll"]="耶努萨克雷是一位目光敏锐的暗矛秘术师，依靠与灵魂沟通以及祖先的智慧，来应对卡利姆多面临的各种奇异威胁。"},sec={{t="深渊中的威胁",b="在雾气笼罩的佐拉姆海岸，暗矛萨满耶努萨克雷一直在监视着那些被邪恶势力侵占的古老卡多雷遗迹。在黑暗深渊淹没的洞室深处，娜迦们开始挖掘生长在潮湿洞穴壁上的鲜艳蓝宝石。萨克雷感觉到这些蛇形入侵者企图利用这种不稳定的力量，因此他试图在他们的阴谋得逞之前拦截这些战利品。"},{t="水之灵与奥术力量",b="阿库麦尔的蓝宝石绝非普通的宝石；它们搏动着元素共鸣，并依附着水之灵。在熟练的施法者手中，这些媒介能够助长危险的奥术仪式，或是增强阴影九头蛇阿库麦尔的影响力——它那黑暗的存在渗透着整个地下神庙。回收这些宝石簇不仅剥夺了娜迦宝贵的试剂，还能保护海岸线免受失控元素魔法的侵害。"}},faq={{q="谁发布了这个任务？",a="该任务由暗矛巨魔萨满耶努萨克雷发布，他驻扎在灰谷西北部的佐拉姆海岸的佐拉姆加前哨站。",al={"任务发布者","谁开启阿库麦尔的精华任务","耶努萨克雷位置"}},{q="为什么娜迦想要阿库麦尔的蓝宝石？",a="虽然他们具体的阴谋仍笼罩在迷雾之中，但这些蓝宝石拥有强大的元素水能量和原始的魔法力量，这使得它们成为娜迦施法时极其危险的试剂。",al={"娜迦为什么想要蓝宝石","水晶有什么用","蓝宝石用途"}},{q="在哪里可以找到蓝宝石簇？",a="它们分布在黑暗深渊外部隧道和被淹没通道的洞穴壁和地面上，就在佐拉姆海岸沿线那被毁坏的地下入口内部。",al={"去哪里找蓝宝石","阿库麦尔的蓝宝石位置","水晶刷新点"}},{q="阿库麦尔是什么？",a="阿库麦尔是一头居住在被淹没的神庙遗迹深处的巨大三头九头蛇。它受到暮光之锤教徒的崇拜，并作为上古之神的仆从而令人恐惧。",al={"阿库麦尔是谁","阿库麦尔是什么","阿库麦尔"}},{q="这个任务需要击杀地下城首领吗？",a="不需要。蓝宝石簇生长在早期被淹没的洞穴墙壁上，在遇到黑暗深渊的主要首领之前就可以找到。",al={"需要组满队伍吗","可以单人完成蓝宝石收集吗","首领击杀要求"}},{q="这个任务与其他剧情有关联吗？",a="是的。它紧随“深渊中的麻烦”任务，是耶努萨克雷对黑暗深渊内不断滋生的黑暗和邪教活动调查的一部分。",al={"任务链","前置任务","深渊中的麻烦"}}},fp="22,179,22.315.0,30.366.0,21.128.0,46.141.0,38.176.0,16.158.0,52.117.0,47.151.0"}
P.entries["quest:6564"] = {n="上古之神的仆从",s="“忠于古神”是一个部落任务，可以通过从黑暗深渊内的娜迦身上找回一份浸水的便笺来触发。将这份便笺交给佐拉姆加前哨站的耶努萨克雷，会揭开一个在黑暗深渊被淹没的遗迹深处酝酿的邪恶仪式阴谋。",h="“忠于古神”是一个部落任务，可以通过从黑暗深渊内的娜迦身上找回一份浸水的便笺来触发。将这份便笺交给佐拉姆加前哨站的耶努萨克雷，会揭开一个在黑暗深渊被淹没的遗迹深处酝酿的邪恶仪式阴谋。",kw={"阿库麦尔","效忠","灰谷","黑暗深渊","潮湿的便笺","耶努萨克雷","洛古斯·杰特","古神","怒鳞","佐拉姆加前哨站"},ang={["class:Shaman"]="娜迦在仪式水晶中奴役水元素灵魂代表着对自然平衡的严重扭曲，需要迅速予以纠正。",["faction:Horde"]="发现洛古斯·杰特的便笺有助于保护佐拉姆加前哨站免受暮光之锤及其娜迦盟友的侵害，这些敌人威胁着部落在灰谷西海岸的立足点。",["race:Troll"]="协助你的暗矛同胞耶努萨克雷将揭开那些古老宇宙实体的真面目，它们的回归将威胁到艾泽拉斯的每一个部族。"},sec={{t="潦草的声明",b="在与黑暗深渊的娜迦战斗时，部落侦察兵发现了一份潮湿、皱巴巴的便笺，上面有着狂乱的笔迹。这份潦草的羊皮纸详细记录了针对娜迦女祭司的指令，命令她们收集水元素水晶。这些水晶绝非随意掠夺而来，而是被收集起来为娜迦水术士的召唤提供能量，汇集元素力量以达到更黑暗的目的。"},{t="深渊的低语",b="找回的命令显示，娜迦打算利用水晶中的元素能量来安抚并完全召唤阿库麦尔，这是一头侍奉古神的怪物多头蛇。便笺大胆地宣称，这样做将预示着世界“最伟大时代”的回归——即古神统治的史前时代。在佐拉姆加前哨站收到这份羊皮纸后，暗矛秘术师耶努萨克雷指出了这场阴谋背后的始作俑者：暮光之锤教徒洛古斯·杰特。"}},faq={{q="什么是潮湿的便笺？",a="潮湿的便笺是一份由暮光之锤教徒洛古斯·杰特所写的被找回的命令。它指示娜迦女祭司收集注入元素的水晶，以加强她们的水术士并召唤怪物仆从阿库麦尔。",al={"潮湿的便笺","便笺上写了什么","便笺背景知识"}},{q="耶努萨克雷是谁？",a="耶努萨克雷是一位驻扎在灰谷佐拉姆加前哨站的暗矛巨魔先知兼学者。作为大地之环的代表，他正在调查附近的黑暗深渊遗迹中涌现的元素失衡和古老威胁。",al={"耶努萨克雷","耶努是谁","佐拉姆加任务发布者"}},{q="洛古斯·杰特是谁？",a="洛古斯·杰特是一位在黑暗深渊内活动的暮光之锤教派的人类萨满，教徒们在那里与娜迦结盟。他负责监督元素水晶的采集工作，以增强娜迦的仪式并唤醒黑暗的古老恐惧。",al={"洛古斯·杰特","谁写了便笺","佐拉姆娜迦首领"}},{q="阿库麦尔是什么？",a="阿库麦尔是一头居住在黑暗深渊淹没深处的巨大三头多头蛇。这只生物与古神的原始黑暗紧密相连，受到暮光之锤教派和黑暗深渊娜迦的崇拜。",al={"阿库麦尔","阿库麦尔是谁","阿库麦尔背景知识"}},{q="娜迦为什么要收集水元素水晶？",a="被困在水晶中的水元素灵魂为娜迦水术士提供了原始力量。通过汲取这种元素魔法，他们希望能安抚阿库麦尔，并聚集足够的力量迎来古神的回归。",al={"为什么娜迦需要水晶","娜迦元素水晶","水术士水晶"}},{q="这个任务链通向哪里？",a="将便笺交给耶努萨克雷会直接开启一个后续任务，该任务要求追踪并处决洛古斯·杰特，以破坏教派在黑暗深渊的仪式计划。",al={"忠于古神后续任务","忠于古神第二部分","下一个任务"}}},fp="26,199,23.332.0,20.397.1,22.216.0,22.207.0,19.220.0,16.206.0,43.221.0,33.159.1"}
P.entries["quest:6565"] = {n="上古之神的仆从",s="“效忠上古之神”是一个部落任务，要求冒险者前往黑暗深渊的深处消灭洛古斯·杰特。该任务由佐拉姆加前哨站的暗矛巨魔先知耶努萨克雷发布，旨在打击试图唤醒远古破坏力量的暮光之锤邪教徒。击败洛古斯将对邪教在灰谷海岸下的颠覆性行动给予直接打击。",h="“效忠上古之神”是一个部落任务，要求冒险者前往黑暗深渊的深处消灭洛古斯·杰特。该任务由佐拉姆加前哨站的暗矛巨魔先知耶努萨克雷发布，旨在打击试图唤醒远古破坏力量的暮光之锤邪教徒。击败洛古斯将对邪教在灰谷海岸下的颠覆性行动给...",kw={"效忠上古之神","灰谷","黑暗深渊","耶努萨克雷","洛古斯·杰特","上古之神","暮光之锤","佐拉姆加"},ang={["class:Shaman"]="暮光之锤试图通过侍奉混乱的上古之神来释放元素的愤怒，这使得铲除他们成为了那些发誓要与大地之环共同维护元素平衡之人的优先事项。",["faction:Horde"]="消灭洛古斯·杰特巩固了佐拉姆加前哨站的周边防御，保护了部落在灰谷这座孤立的沿海营地免受邪教徒阴险阴谋的侵害。",["race:Troll"]="协助耶努萨克雷不仅能保护艾泽拉斯的原始精神，也是对这位远在回音群岛之外努力工作的受人尊敬的暗矛先知的智慧表示敬意。"},sec={{t="佐拉姆加之下的威胁",b="坐落在灰谷海岸边的部落前哨站佐拉姆加，时刻保持着对黑暗深渊的警惕。这座被淹没的寺庙建筑群已沦为黑暗魔法的滋生地，到处都是娜迦、受腐蚀的野兽以及披着斗篷的暮光之锤狂热信徒。驻扎在海岸边的大地之环先知耶努萨克雷敏锐地察觉到，这些邪教徒并不敬畏自然的平衡或大地之灵。相反，他们宣誓效忠于上古之神——那些在远古时代被击败、充满混乱的怪物，而它们邪恶的触须至今仍残留在艾泽拉斯那些被遗忘的角落。"},{t="终结洛古斯·杰特",b="耶努指派部落的勇士潜入地下废墟，搜寻并消灭邪教高层中的关键人物洛古斯·杰特。洛古斯活动在巨龟加摩拉和水元素阿奎尼斯男爵之间的石质走廊深处。耶努本人因年迈体衰无法亲自深入那潮湿黑暗的洞穴，因此除掉洛古斯对于切断邪教徒在灰谷浪潮下试图策划的任何黑暗仪式至关重要。"},{t="遏制混乱",b="随着洛古斯·杰特的死亡，对海岸直接造成的仪式性威胁已被控制，但耶努深知暮光之锤远未被彻底根除。邪教在古老圣地的悄然渗透预示着一场更大、更阴险的危机正在蔓延，其目的正是为了让上古之神彻底回归。对于驻扎在佐拉姆加的部落而言，击败洛古斯为对抗这些潜伏在世界阴影中的敌人争取了宝贵的时间。"}},faq={{q="洛古斯·杰特是谁？",a="洛古斯·杰特是盘踞在黑暗深渊中的暮光之锤邪教徒的重要头目之一。他指挥着旨在迎接远古上古之神回归与统治的邪教仪式。",al={"洛古斯·杰特","洛古斯是谁","洛古斯·杰特背景故事"}},{q="在黑暗深渊哪里可以找到洛古斯·杰特？",a="洛古斯·杰特在黑暗深渊被淹没的走廊中巡逻，具体位于加摩拉的巢穴和阿奎尼斯男爵的祭坛区域之间的通道内。",al={"洛古斯·杰特位置","洛古斯在哪里","寻找洛古斯·杰特"}},{q="耶努萨克雷是谁？",a="耶努萨克雷是一名隶属于大地之环的暗矛巨魔先知，驻扎在灰谷佐拉姆海岸的佐拉姆加前哨站，负责监视元素骚乱以及黑暗深渊中的腐化。",al={"耶努萨克雷","谁发布效忠上古之神","耶努"}},{q="为什么耶努会关注暮光之锤？",a="作为一名致力于理解自然与元素平衡的先知，耶努将暮光之锤视为一种生存威胁。该邪教侍奉上古之神，那是充满混乱的远古存在，它们的回归将摧毁世界的和谐。",al={"为什么要对抗暮光之锤","大地之环上古之神"}},{q="什么是上古之神？",a="上古之神是代表混乱与毁灭的太古存在，在远古时代统治过艾泽拉斯，随后被击败并封印。暮光之锤邪教一直在崇拜它们，密谋打破封印，让它们那充满毁灭性的统治重现世间。",al={"上古之神背景故事","上古之神是什么","混乱生物"}},{q="为什么耶努萨克雷不能亲自去杀死洛古斯·杰特？",a="耶努承认自己年迈体衰，无法独自面对黑暗深渊中的危险，因此他只能依靠强大的部落勇士去战斗，而他自己则留在前哨站追踪精神和元素的波动。",al={"为什么耶努不去","耶努体弱吗"}}},fp="26,235,28.449.0,18.437.0,17.332.1,19.168.0,52.141.0,22.201.0,49.206.0,22.243.0,50.156.0"}
P.entries["quest:6568"] = {n="幻术的欺诈",s="雷克萨说，想要潜入黑龙军团的防线，需要用到幻象。他认识一位幻术大师，即住在西瘟疫之地的巫女麦兰达，并让你带一封信给她。",h="雷克萨说，想要潜入黑龙军团的防线，需要用到幻象。他认识一位幻术大师，即住在西瘟疫之地的巫女麦兰达，并让你带一封信给她。",kw={"黑龙军团","凄凉之地","幻象","欺诈大师","巫女麦兰达","雷克萨","悔恨岭","雷克萨的遗嘱","西瘟疫之地"},sec={{t="幻术的艺术",b="雷克萨问你对幻象了解多少，因为你必须依靠幻象来绕过黑龙军团的防线。他提到了一个可以协助你进行伪装的人：巫女麦兰达，一位被洛丹伦联盟驱逐的幻术大师，现居住在西瘟疫之地。雷克萨说，只要她认为值得，她以前就曾帮助过他的族人。你带着他的信去找她。"},{t="洛丹伦的访客",b="麦兰达评论说，部落成员在洛丹伦的这一带很少见，她询问你带了什么给她。"},{t="麦兰达的回答",b="麦兰达拿着便条，停顿了一下，微笑了。她询问雷克萨的情况，然后解释说这张纸之所以是空白的，是因为写信人的意图都在这上面。她明白雷克萨为什么不写上字，因为如果你在途中被俘虏或杀害，这些内容可能会带来危险。她同意帮助你，因为她欠大酋长一个人情。"}},faq={{q="巫女麦兰达是谁？",a="巫女麦兰达是一位幻术大师，曾属于洛丹伦，后被联盟驱逐。她位于西瘟疫之地的悔恨岭。",al={"麦兰达是谁","巫女麦兰达背景故事","麦兰达在哪里"}},{q="为什么要寻找幻术师？",a="雷克萨说，你必须依靠幻象来绕过黑龙军团的防线，他认识一位可以提供帮助的大师。",al={"为什么要伪装","为什么要寻找幻术师","欺骗黑龙军团"}},{q="雷克萨让你去哪儿？",a="他让你前往西瘟疫之地，在悔恨岭找到巫女麦兰达。",al={"我该去哪里","悔恨岭在哪里","欺诈大师目的地"}},{q="麦兰达以前帮助过部落吗？",a="雷克萨说，只要她认为事业值得，她以前就曾帮助过他的族人。",al={"麦兰达喜欢部落吗","麦兰达是联盟还是部落","麦兰达与大酋长的人情"}}},fp="23,204,19.393.0,22.127.0,16.328.1,23.154.0,37.115.0,27.80.0,36.80.0"}
P.entries["quest:657"] = {n="新的瘟疫？",s="奎艾翻阅了文件夹，得知药剂师Jorell正在格沙克农场进行致命的实验。奎艾在与兽人冲突后状态不佳，无法帮助基恩洛。基恩洛前往农场窃取尚未送往塔伦米尔的Jorell的研究成果时，需要你的保护。",h="奎艾翻阅了文件夹，得知药剂师Jorell正在格沙克农场进行致命的实验。奎艾在与兽人冲突后状态不佳，无法帮助基恩洛。基恩洛前往农场窃取尚未送往塔伦米尔的Jorell的研究成果时，需要你的保护。",kw={"药剂师jorell","被遗忘者","格沙克农场","基恩洛","phin","瘟疫","奎艾","塔伦米尔"},sec={{t="Jorell的实验",b="奎艾翻阅了文件夹，发现药剂师Jorell正在格沙克农场进行致命的实验。奎艾并不清楚这与希尔斯布莱德有什么关系，但Phin一定不希望这种事继续下去。Jorell的一些研究成果已经被送往了塔伦米尔。"},{t="基恩洛的保护者",b="在你离开期间，奎艾与一些兽人发生了冲突，现在的状态无法帮助基恩洛。基恩洛打算前往农场窃取Jorell尚未送往塔伦米尔的研究成果，她需要保护。你去和基恩洛谈谈吧。"},{t="基恩洛的决心",b="基恩洛说，如果能让Phin获得安宁，她会亲手消灭每一个被遗忘者。自从瘟疫爆发以来，Phin为基恩洛和其他人做了很多事，他们本以为再也找不到朋友或家人了。基恩洛让你准备好后告诉她，你们俩马上就会出发。"}},faq={{q="为什么奎艾不能陪同基恩洛？",a="奎艾在你离开期间与一些兽人发生了冲突，现在的状态无法帮助基恩洛。",al={"为什么奎艾留在这里","为什么奎艾不帮忙","为什么要独自护送基恩洛"}},{q="文件夹里发现了什么？",a="药剂师Jorell一直在格沙克农场进行致命的实验。",al={"文件夹里有什么","jorell的实验","jorell在做什么"}},{q="为什么奎艾和基恩洛要调查这件事？",a="她们是Phin的同伴，Phin领导着一群调查异常事件的冒险者。Phin不希望Jorell的实验继续下去。",al={"phin是谁","为什么他们关心瘟疫","为什么要帮助phin"}},{q="研究成果被送往哪里？",a="一部分已经被送往了塔伦米尔。基恩洛计划窃取Jorell尚未送出的那部分。",al={"笔记被送往哪里","塔伦米尔的研究"}}},fp="22,243,20.214.0,20.200.0,18.311.1,34.84.0,34.91.0,45.159.0,33.110.0"}
P.entries["quest:6571"] = {n="战歌氏族的补给品",s="“战歌补给”是一个由位于碎木岗哨的洛克·奥卡尔发放的部落大型后勤任务。为了维持战歌伐木营地的正常运转，必须收回散落在充满敌意的熊怪和萨特领地中的重要伐木装备，同时还需要从遥远的地精港口获取进口物资。",h="“战歌补给”是一个由位于碎木岗哨的洛克·奥卡尔发放的部落大型后勤任务。为了维持战歌伐木营地的正常运转，必须收回散落在充满敌意的熊怪和萨特领地中的重要伐木装备，同时还需要从遥远的地精港口获取进口物资。",kw={"灰谷","藏宝海湾","洛克·奥卡尔","伐木绳","皮克希尔","锯条","碎木岗哨","战歌伐木营地","战歌之油","战歌补给"},ang={["faction:Horde"]="部落在杜隆塔尔的扩张完全取决于战歌氏族提供的木材。收回这些工具直接巩固了奥格瑞玛的根基。",["profession:Engineering"]="这批货物中的地精组件凸显了采伐古老森林所必需的基础机械供应链——从皮克希尔的锯条到蒸汽引擎润滑油。",["race:Orc"]="为了战歌氏族在灰谷的荣耀，必须让他们的斧头保持锋利，并保证营地的补给充足，尽管要面对来自森林原住民的不断骚扰。"},sec={{t="让锯子转起来",b="战歌氏族在灰谷采伐古老木材的行动需要源源不断的重型工具供应。部落军需官们在碎木岗哨的前哨基地面临着持续不断的补给中断问题。洛克·奥卡尔负责确保伐木营地的装备齐全，但当地的货物运送遭到了本土生物和恶魔邪教徒的劫掠而损失殆尽，导致该行动急需关键装备。"},{t="分散的后勤链",b="获取所需的设备是一项艰巨的任务，范围覆盖了大部分卡利姆多，甚至跨越了海洋。圆锯片在碎木岗哨的地精信使皮克希尔那里等待领取，而一箱重型斧头则需要去藏宝海湾的码头管理员罗兹基尔那里领取。其余的基本物资必须直接从敌人手中夺回：被充满敌意的黑木熊怪和蓟皮熊怪抢走的坚固伐木绳，以及被夜道谷、萨维亚和萨提纳尔的萨特偷走用于其亵渎仪式的战歌之油桶。"}},faq={{q="所需的战歌补给有哪些？",a="洛克·奥卡尔需要四种基本物品：地精皮克希尔持有的战歌锯条、运往藏宝海湾的一箱战歌之斧、当地熊怪劫掠的重型伐木绳，以及被灰谷的萨特偷走的战歌之油桶。",al={"战歌补给清单","需要什么物品","需要的补给"}},{q="洛克·奥卡尔是谁？",a="洛克·奥卡尔是一名驻扎在碎木岗哨的兽人，负责协调向战歌伐木营地的物资运送。为了避免行动延误，他承受着巨大的压力，于是他招募往来的部落冒险者来找回他散失的货物。",al={"洛克·奥卡尔背景","谁发放战歌补给任务","碎木岗哨任务发布者"}},{q="为什么部落要从藏宝海湾运送装备？",a="部落依赖热砂港这样的中立贸易网络来进口杜隆塔尔和贫瘠之地无法轻易大量锻造的特种制成品。通过地精渠道订购的重型伐木斧会通过藏宝海湾这样的海运枢纽，最后才能到达灰谷。",al={"为什么是藏宝海湾","藏宝海湾的斧头货物","热砂港工具"}},{q="为什么萨特需要战歌之油？",a="居住在萨提纳尔、夜道谷和萨维亚等遗迹中的萨特并没有将这些工业用油用于机械，而是将其转用于献给燃烧军团的黑暗腐化仪式，以及加剧费伍德森林的污染。",al={"萨特之油背景","为什么萨特会有油","战歌之油仪式"}},{q="是哪些熊怪偷走了伐木绳？",a="伐木绳是被黑木熊怪和蓟皮熊怪部落伏击并夺走的。这两个部落对部落在灰谷进行的皆伐作业怀有强烈的领土敌意。",al={"谁偷了绳子","熊怪抢劫绳子背景","黑木蓟皮熊怪绳子"}},{q="为什么战歌伐木营地对部落如此重要？",a="杜隆塔尔的干旱土地几乎无法提供可用于建筑的木材。战歌氏族被部署到灰谷郁郁葱葱的边境地区，专门为了采伐建造奥格瑞玛和为部落日益增长的军事基础设施提供燃料所需的巨大树木。",al={"为什么要开发灰谷","战歌伐木营地的重要性","兽人伐木"}}},fp="16,176,25.281.0,27.370.0,39.193.0,19.186.0,51.267.0,35.177.0,38.139.0,53.281.0"}
P.entries["quest:658"] = {n="新的瘟疫？",s="奎艾和金已经监视格沙克农场好几天了。金看到一名信使从南边的一间小屋里走出来，他们怀疑那名信使带着要送往塔伦米尔的笔记。奎艾想要那些文件，并询问你是否是一名熟练的追踪者。",h="奎艾和金已经监视格沙克农场好几天了。金看到一名信使从南边的一间小屋里走出来，他们怀疑那名信使带着要送往塔伦米尔的笔记。奎艾想要那些文件，并询问你是否是一名熟练的追踪者。",kw={"药剂师","阿拉希高地","被遗忘者信使","格沙克农场","金","费恩·奥德利克","奎艾","密封的信件","塔伦米尔"},sec={{t="监视农场",b="奎艾对费恩·奥德利克派你来查看他们的状况并不感到惊讶，因为费恩总是杞人忧天。奎艾和金已经监视农场好几天了。不久前，金看到一名信使从南边的一间小屋里走出来。金虽然话多，但奎艾总是信任金在危险区域的感知能力。"},{t="信使的文件夹",b="奎艾询问你是否是一名熟练的追踪者。那名信使可能带着要送往塔伦米尔的笔记，弄到这些文件或许能揭示希尔斯布莱德正在发生的事情。你要找到被遗忘者信使，并将她的密封的信件带回给格沙克农场附近的奎艾。当你搜索时，金发现一名药剂师也离开了那间屋子。奎艾确信那个药剂师没安好心，但在有人做出鲁莽举动之前，需要证据。"}},faq={{q="是谁派你来找奎艾和金的？",a="费恩·奥德利克派你来查看他们的状况，奎艾对此并不感到惊讶，因为费恩总是杞人忧天。",al={"谁派我去找奎艾","谁开启了新的瘟疫的迹象任务","费恩·奥德利克任务"}},{q="信使是从哪里出来的？",a="金看到信使从南边的一间小屋里走出来。",al={"信使从哪里来","信使位置","农场南边的屋子"}},{q="信使要去哪里？",a="奎艾和金怀疑信使带着要送往塔伦米尔的笔记。",al={"信使目的地","信使要去哪里"}},{q="你要找回什么物品？",a="被遗忘者信使的密封的信件，要将其带回给格沙克农场附近的奎艾。",al={"信使有什么物品","密封的信件"}},{q="还有谁在那间屋子被发现？",a="在你离开时，金发现一名药剂师也离开了那间位于南边的屋子。",al={"农场的药剂师","谁从屋子里出来"}},{q="为什么奎艾想要这些文件？",a="它们可能有助于了解希尔斯布莱德正在发生的事情，在有人做出鲁莽举动之前，奎艾需要证据。",al={"为什么要获取文件","这些笔记是做什么用的"}}},fp="22,219,17.238.0,20.409.0,34.93.0,32.53.0,29.69.0,35.80.0,34.83.0,33.109.0"}
P.entries["quest:6581"] = {n="战歌锯条",s="“战歌锯条”是部落在碎木岗哨进行的一项差事，旨在支持战歌氏族的伐木行动。为了获得从棘齿城进口的重型锯条，冒险者必须与信使皮克希尔达成一笔私下交易，她要求在交出货物前获得人身保护。完成这笔交易可以确保部落在灰谷的伐木场顺利运转所需的关键机械设备。",h="“战歌锯条”是部落在碎木岗哨进行的一项差事，旨在支持战歌氏族的伐木行动。为了获得从棘齿城进口的重型锯条，冒险者必须与信使皮克希尔达成一笔私下交易，她要求在交出货物前获得人身保护。完成这笔交易可以确保部落在灰谷的伐木场顺利...",kw={"灰谷","致命的短枪","皮克希尔","棘齿城","碎木岗哨","战歌氏族","战歌锯条","战歌补给品"},ang={["faction:Horde"]="灰谷的伐木营地为奥格瑞玛的扩张提供了至关重要的结构骨干，使得每一批机械的运送对部落在卡利姆多的生存都至关重要。",["profession:Engineering"]="皮克希尔要求的“致命的短枪”是熟练工匠的主要产品，凸显了地精和凡人的工程学如何推动前线战争的后勤工作。",["race:Orc"]="战歌氏族在格罗玛什·地狱咆哮的领导下将他们的骄傲寄托在对灰谷的伐木上；让他们的工业锯条持续运转，是对该氏族在森林中继续立足的尊重。"},sec={{t="信使的精明易货",b="灰谷的战歌伐木工完全依赖进口的重型机械来砍伐深林中的古老树木。虽然皮克希尔已经成功地将一批特制的锯条直接从地精港口棘齿城运到了碎木岗哨，但她无意免费交出它们。在灰谷危机四伏的野外，金币的价值有限，而人身安全则要珍贵得多。皮克希尔没有索要金币，而是坚持用重型锯条换取一把可靠的“致命的短枪”，以确保她在危险的敌对领土旅行时的安全。"},{t="供应战争物资",b="灰谷茂密的树冠深受部落青睐，因为杜隆塔尔和贫瘠之地的干旱平原正面临严重的木材短缺。然而，砍伐古老的哨兵之林会迅速磨损普通的斧头，使得地精锻造的工业锯条成为必需品。获得皮克希尔的这批货物将直接推动战歌伐木场的运作，确保部落能够在暗夜精灵的激烈抵抗下继续建造前哨站和战争机器。"}},faq={{q="皮克希尔是谁，为什么她会有锯条？",a="皮克希尔是一名目前驻扎在碎木岗哨的信使，她运送了一批直接来自地精港口棘齿城的工业锯条。她扣留了这批货物，直到能为自己获得一件可靠的武器以寻求保护。",al={"皮克希尔是谁","皮克希尔 碎木岗哨","锯条信使"}},{q="为什么皮克希尔想要“致命的短枪”而不是金币？",a="穿越贫瘠之地并深入灰谷的暗夜精灵领地极其危险。了解道路上的凶险，皮克希尔认为人身防御比金币更重要，因此要求获得一件工程学制造的火器来保卫她的旅途。",al={"为什么需要致命的短枪","皮克希尔枪械交易","为什么要枪"}},{q="为什么这些锯条对部落如此重要？",a="部落需要大量的木材来在卡利姆多各地建造防御工事和战争机器。标准的切割工具在灰谷古老的铁木面前很快就会磨损，因此进口的机械锯条对于战歌氏族的伐木机械至关重要。",al={"为什么需要锯条","战歌伐木的重要性","为什么需要战歌补给品"}},{q="这些锯条最初来自哪里？",a="这些锯条是在贫瘠之地东海岸的中立地精港口——棘齿城制造并运出的，随后被陆运至碎木岗哨。",al={"锯条的来源","棘齿城锯条","锯条从哪里来"}},{q="这个任务在战歌伐木行动中处于什么位置？",a="这项任务是为灰谷的伐木营地筹集战歌补给品这一更大行动的一部分。从皮克希尔手中收回锯条是维持部落伐木运作所需的关键后勤要求之一。",al={"战歌补给链","战歌锯条前置任务"}},{q="有人能制造皮克希尔想要的武器吗？",a="“致命的短枪”是由熟练的工程师使用铜管、铜栓、木质枪托和皮革制造的，不过信使和战士们也经常通过当地市场或同行冒险者来交换它们。",al={"如何获得致命的短枪","短枪来源","工程学枪械"}}},fp="18,244,25.290.0,24.333.0,50.149.0,57.178.0,51.178.0,46.79.0,58.100.0,39.200.0"}
P.entries["quest:659"] = {n="新的瘟疫？",s="费恩·奥德利克带领着一队冒险者调查该地区发生的离奇事件，他认为亡灵牵涉其中。他的两位同伴，奎艾和基恩洛，前往了阿拉希高地的格沙克农场。他们已经好几天没有消息了。",h="费恩·奥德利克带领着一队冒险者调查该地区发生的离奇事件，他认为亡灵牵涉其中。他的两位同伴，奎艾和基恩洛，前往了阿拉希高地的格沙克农场。他们已经好几天没有消息了。",kw={"阿拉希高地","格沙克农场","希尔斯布莱德丘陵","基恩洛","费恩·奥德利克","奎艾","斯坦利"},sec={{t="离奇事件",b="不久前，费恩在希尔斯布莱德的表亲不得不除掉了他的狗斯坦利。那头野兽离奇地肿胀到了巨大的体型，并疯狂地攻击任何靠近的人。费恩认为亡灵与这些离奇事件有关，该团队正在寻找证据以证明这一点。"},{t="失踪的同伴",b="奎艾和基恩洛是费恩的两名同伴，他们前往了阿拉希高地的格沙克农场，已经好几天没有消息了。费恩非常担心，希望你能去农场附近找到他们。"}},faq={{q="费恩·奥德利克是谁？",a="费恩带领着一队冒险者，正在调查该地区发生的离奇事件。",al={"费恩·奥德利克","谁暗示了新瘟疫","任务发布者"}},{q="斯坦利怎么了？",a="斯坦利是费恩在希尔斯布莱德的表亲的狗。那头野兽离奇地肿胀到了巨大的体型，并疯狂地攻击任何靠近的人，所以他的表亲除掉了它。",al={"狗斯坦利","这条狗发生了什么","希尔斯布莱德的斯坦利"}},{q="奎艾和基恩洛应该在哪里？",a="在阿拉希高地的格沙克农场附近，他们出发前往了那里。费恩已经好几天没收到他们的消息了。",al={"奎艾在哪里","基恩洛在哪里","奎艾的位置","寻找奎艾"}},{q="费恩为什么要进行调查？",a="费恩认为亡灵牵涉到了该地区的离奇事件中，而他的团队正在寻找证据来证明这一点。",al={"为什么要前往格沙克农场","格沙克农场的亡灵","调查格沙克"}}},fp="22,167,14.255.0,22.193.0,19.81.0,25.139.0,43.110.0,26.105.0"}
P.entries["quest:66"] = {n="斯塔文的传说",s="斯塔文的传说始于夜色镇，起因是镇上的占卜师伊瓦夫人带来的一个不祥预兆。伊瓦因其孙女艾丽莎即将面临死亡的凶兆而深感不安，她通过卡牌和恍惚的幻象占卜出了一个挥之不去的名字：斯塔文。为了理清这股恐惧的源头，她派遣冒险者前往Darkshire Town Hall查阅镇上的记录。",h="斯塔文的传说始于夜色镇，起因是镇上的占卜师伊瓦夫人带来的一个不祥预兆。伊瓦因其孙女艾丽莎即将面临死亡的凶兆而深感不安，她通过卡牌和恍惚的幻象占卜出了一个挥之不去的名字：斯塔文。为了理清这股恐惧的源头，她派遣冒险者前往Da...",kw={"艾丽莎","书记员达尔塔","夜色镇","死神牌","暮色森林","伊瓦夫人","斯塔文","市政厅"},ang={["class:Priest"]="走在夜色镇黑暗道路上的牧师们通常会留意精神上的警示，这使得伊瓦夫人那令人不寒而栗的死亡预兆成了牧师职责中一件刻不容缓的大事。",["faction:Alliance"]="由于暮色森林在缺乏暴风城正规军队支持的情况下艰难求生，联盟冒险者经常挺身而出，协助镇上的长者并保护像伊瓦夫人家庭这样脆弱的平民。"},sec={{t="死亡的幻象",b="在暮色森林永恒的阴霾中，伊瓦夫人作为夜色镇的常驻占卜师，为忧心忡忡的当地人解读预兆和占卜卡牌。在一次因可怕的心灵感应而惊醒后，伊瓦查阅了她的占卜牌，结果却抽到了与她年幼的孙女艾丽莎有关的死神牌。她陷入了一场深沉而阴暗的恍惚中以穿透迷雾，最终只带出了唯一的线索：斯塔文这个名字。出于对这一预兆可能给她的家人和城镇带来灾难的恐惧，她转而求助于有能力的冒险者，希望在悲剧发生前顺藤摸瓜找到真相。"},{t="Town Hall的问询",b="伊瓦知道，揭开斯塔文真相的关键在于查阅夜色镇的书面历史。她指引冒险者穿过广场前往Darkshire Town Hall，去寻找书记员达尔塔，他是市政账本和公共档案的保管员。达尔塔掌管着镇上尘封的文档，因此只有他能够确定斯塔文究竟是前居民、过路旅人，还是埋葬在暮色森林过去中更邪恶的存在。"}},faq={{q="伊瓦夫人是谁？",a="伊瓦夫人是一位居住在夜色镇的算命师和占卜师。她利用卡牌和恍惚仪式来窥探未来的预兆，并能感知到暮色森林中发生的魔法波动。",al={"伊瓦夫人","伊瓦是谁","夜色镇算命师"}},{q="为什么伊瓦夫人需要帮助？",a="伊瓦夫人经历了一个可怕的幻象，预示着她的孙女艾丽莎正处于致命的危险之中。她的牌组抽到了死神牌，而她的恍惚状态中只出现了“斯塔文”这个名字，这促使她寻求外界的援助来调查这一威胁。",al={"为何开启斯塔文任务","伊瓦的幻象","为何帮助伊瓦"}},{q="书记员达尔塔是谁？",a="书记员达尔塔是驻守在Darkshire Town Hall的市政记录官。他负责管理城镇的账本、登记册和历史文档，是询问陌生人名字的最佳人选。",al={"书记员达尔塔","达尔塔","谁是镇书记员"}},{q="什么是Darkshire Town Hall？",a="Darkshire Town Hall是该镇的行政中心，这里设有地方政府官员、历史记录档案以及守夜人的指挥人员。",al={"darkshire town hall","暮色森林市政厅"}},{q="艾丽莎是谁？",a="艾丽莎是居住在夜色镇的伊瓦夫人的年幼孙女。伊瓦的占卜显示，艾丽莎正受到一个与名为斯塔文的人有关的死亡预兆的威胁。",al={"艾丽莎","伊瓦夫人的孙女"}},{q="这项调查接下来会指向何处？",a="与书记员达尔塔交谈将揭示城镇记录和过往的询问，从而开启一项遍布暮色森林及周边地区的广泛调查，以揭开斯塔文的历史和命运。",al={"斯塔文后续步骤","达尔塔说了什么"}}},fp="21,223,17.369.0,22.322.0,18.166.0,30.180.0,20.166.0,28.109.0,14.145.0,40.185.0"}
P.entries["quest:660"] = {n="新的瘟疫？",s="基恩洛准备前往农场，希望你与她同行。她担心亡灵在希尔斯布莱德拖得越久，造成的伤害就越大，她请求你护送她安全回到奎艾身边。",h="基恩洛准备前往农场，希望你与她同行。她担心亡灵在希尔斯布莱德拖得越久，造成的伤害就越大，她请求你护送她安全回到奎艾身边。",kw={"护送","希尔斯布莱德丘陵","新瘟疫的迹象","基恩洛","瘟疫","奎艾"},sec={{t="为基恩洛保驾护航",b="在完成了早先的调查步骤后，基恩洛准备采取行动。她请求你陪她前往农场。你需要护送她安全回到奎艾身边，所有关心希尔斯布莱德人民安危的人都被敦促去保护她。"},{t="安全返回",b="回到奎艾身边后，你因为这次护送得到了感谢。奎艾承认她曾担心基恩洛会不会太难缠：她非常友善，但若是你的敌人，她也同样致命。"}},faq={{q="是谁让你执行这次护送任务的？",a="基恩洛准备动身时，要求你与她同行。",al={"任务发布者","谁给予任务","谁开始新瘟疫的迹象4"}},{q="基恩洛要去哪里？",a="她前往农场，然后动身返回奎艾那里。",al={"护送路线","基恩洛要去哪","基恩洛目的地"}},{q="完成后向谁汇报？",a="奎艾，一旦基恩洛安全回到她身边。",al={"任务交付","谁完成任务","在哪里交付任务"}},{q="在调查的这一部分之前发生了什么？",a="“新瘟疫的迹象？”的第三部分，直接引导至本部分。",al={"前置任务","前提条件","之前是什么"}},{q="安全返回后接下来是什么？",a="调查将继续进行，“新瘟疫的迹象？”的第五部分。",al={"后续任务","what comes next","后续"}},{q="为什么要保护基恩洛？",a="所有关心希尔斯布莱德人民的人都被敦促确保她平安无事。",al={"为何保护基恩洛","为何关心基恩洛"}}},fp="22,176,24.222.0,13.170.1,29.62.0,31.62.0,35.57.0,54.92.0,36.74.0,31.87.0"}
P.entries["quest:6608"] = {n="你真棒！",s="“你太强了。”是一个部落任务，由奥格瑞玛的钓鱼训练师鲁玛克在钓鱼者超越了普通训练水平后提供。鲁玛克会派遣他有成就的学生去寻找他的人类朋友——纳特·帕格，此人驻扎在尘泥沼泽偏远的海岸边。这个任务标志着从标准教学到高难度的专家级钓鱼艺术的转变。",h="“你太强了。”是一个部落任务，由奥格瑞玛的钓鱼训练师鲁玛克在钓鱼者超越了普通训练水平后提供。鲁玛克会派遣他有成就的学生去寻找他的人类朋友——纳特·帕格，此人驻扎在尘泥沼泽偏远的海岸边。这个任务标志着从标准教学到高难度的专...",kw={"专家级钓鱼","尘泥沼泽","鲁玛克","纳特·帕格","奥格瑞玛","塞拉摩","你太强了"},ang={["faction:Horde"]="这个任务展示了在阵营战争之下，个人有时能通过无害的技艺和共同的爱好形成跨阵营的羁绊。",["race:Orc"]="即使在奥格瑞玛这座崇尚武力的堡垒中，鲁玛克也证明了耐心、幽默感和对大自然的深刻尊重，可以引导一名兽人在敌对阵营之间结交朋友。"},sec={{t="鲁玛克的局限",b="鲁玛克是奥格瑞玛荣誉谷的主要钓鱼训练师，但即使是这位耐心的兽人也能看出来，当学生在钓鱼技术上的造诣已经追上了他时，他已无更多知识可教。鲁玛克坦率地承认，这位钓鱼者的水平已经“太强了”，普通课程已不适用。为了达到专家等级，必须将目光投向城墙之外，超越种族的界限。"},{t="一段非同寻常的友谊",b="尽管卡利姆多大陆上部落与联盟之间的摩擦不断，但钓鱼往往能在外交失败的地方架起沟通的桥梁。鲁玛克向旅行者指引他的一位私人好友，纳特·帕格，并郑重其事地强调绝不能伤害或吃掉这名人类。纳特在尘泥沼泽的塞拉摩岛南边的一个小岛上扎营，只要有鱼上钩，他便乐于忽略政治纷争。"}},faq={{q="谁发布了这个任务？",a="鲁玛克，位于奥格瑞玛荣誉谷水边的钓鱼训练师。当你的钓鱼技能等级足以超越专家级时，他会给你这个任务。",al={"谁开启你太强了任务","鲁玛克任务发布者","在哪里领取你太强了任务"}},{q="纳特·帕格在哪里？",a="纳特·帕格驻扎在尘泥沼泽海岸外的一个小岛上，位于人类定居点塞拉摩岛的南面。",al={"纳特·帕格在哪里","纳特·帕格位置","寻找纳特·帕格"}},{q="为什么兽人会有个人类朋友？",a="艾泽拉斯各地的钓鱼爱好者往往拥有超越阵营战争的相互尊重。鲁玛克和纳特·帕格纯粹是因为钓鱼而结缘，不论兽人和人类之间有何苦涩的敌对关系，他们都认可彼此对这项活动的挚爱。",al={"鲁玛克和纳特·帕格的友谊","为什么纳特·帕格和兽人是朋友"}},{q="当我与纳特·帕格交谈时会发生什么？",a="与纳特·帕格交谈将开启他那高难度的专家级试炼，你需要横跨艾泽拉斯捕获各种稀有鱼类，他才会亲自传授你进一步的技巧。",al={"纳特·帕格教授什么","钓鱼专家任务"}},{q="部落穿过塞拉摩安全吗？",a="不安全，塞拉摩是联盟严密把守的堡垒城镇。部落冒险者必须绕道城镇或沿着海岸绕行，才能在不引起塞拉摩卫兵敌意的情况下到达纳特的小岛。",al={"部落可以穿过塞拉摩吗","部落如何到达纳特·帕格处"}},{q="为什么鲁玛克不能继续训练我？",a="鲁玛克已经教给你他所知道的一切。钓鱼艺术的真正大师之道需要纳特·帕格的点拨，他被公认为已知世界中最传奇的钓鱼者。",al={"为什么鲁玛克停止训练","部落钓鱼从专家到专家级"}}},fp="13,160,14.261.0,22.296.0,27.109.0,27.87.0,36.126.0,39.111.0,44.139.0,41.134.0"}
P.entries["quest:661"] = {n="新的瘟疫？",s="基恩洛已经从农场安全归来了，奎艾拿到了她带回来的物品。奎艾和基恩洛打算在阿拉希多待一会儿，所以把消息带给南海镇的费恩·奥德利克的任务就交给你了。",h="基恩洛已经从农场安全归来了，奎艾拿到了她带回来的物品。奎艾和基恩洛打算在阿拉希多待一会儿，所以把消息带给南海镇的费恩·奥德利克的任务就交给你了。",kw={"阿拉希高地","被遗忘者","希尔斯布莱德","基恩洛","费恩·奥德利克","瘟疫","奎艾","南海镇"},sec={{t="带给南海镇的消息",b="奎艾很高兴你把基恩洛照顾得这么好，她回来时的状态甚至比在酒馆待了一晚还要好。从农场带回来的物品应该能让费恩·奥德利克对阿拉希发生的状况有所了解。由于农场遭到了袭击，奎艾和基恩洛打算再多待一阵子，以防有人报复，并请求你回到南海镇去找费恩谈谈。"},{t="费恩的回答",b="得知基恩洛和奎艾安然无恙，费恩感到很高兴，称她们二人是不可替代的朋友和旅伴。费恩代表整个团队赠送了一份礼物向你表示感谢，并希望他们能幸运地探明被遗忘者究竟在计划什么，并阻止这一切。"}},faq={{q="是谁让你去和费恩·奥德利克交谈的？",a="在基恩洛从农场安全回来后，奎艾请求你去南海镇。",al={"谁提供了新瘟疫的线索 5","谁开启了新瘟疫的线索","奎艾的任务"}},{q="为什么奎艾和基恩洛不亲自返回南海镇？",a="奎艾想让她们在阿拉希多待一会儿，以防有人因农场遇袭而进行报复。",al={"为什么奎艾要留在阿拉希","为什么要留下来","奎艾留守"}},{q="在哪里可以找到费恩·奥德利克？",a="在南海镇。",al={"费恩·奥德利克的位置","费恩在哪里","费恩·奥德利克 南海镇"}},{q="给费恩·奥德利克带去消息的目的是什么？",a="基恩洛从农场带回来的物品应该能帮助费恩·奥德利克了解阿拉希究竟发生了什么。",al={"为什么要拜访费恩","费恩·奥德利克的目的","费恩想要什么"}}},fp="22,137,19.374.0,13.282.1,40.77.0,64.110.0,31.29.0,52.104.0"}
P.entries["quest:6611"] = {n="加基森之旅！",s="“前往加基森！”是部落厨师为了超越主城训练师所能传授的极限而踏上的旅程。在奥格瑞玛的扎姆沙指引下，渴望精进技艺的厨师们会向南穿过卡利姆多，前往塔纳利斯寻找古怪的地精屠夫迪尔格·奎克里弗。这项引导任务标志着厨师迈向烹饪艺术大师之路的起点。",h="“前往加基森！”是部落厨师为了超越主城训练师所能传授的极限而踏上的旅程。在奥格瑞玛的扎姆沙指引下，渴望精进技艺的厨师们会向南穿过卡利姆多，前往塔纳利斯寻找古怪的地精屠夫迪尔格·奎克里弗。这项引导任务标志着厨师迈向烹饪艺术...",kw={"专家级烹饪","烹饪","迪尔格·奎克里弗","加基森","奥格瑞玛","塔纳利斯","valley of strength","扎姆沙"},ang={["faction:Horde"]="奥格瑞玛需要依靠像中立地精厨师这样的外部专家，来帮助其工匠突破部落标准菜肴的局限。",["profession:Cooking"]="这个任务标志着厨师在主城训练师的教导下学有所成，必须冒险进入危险的荒野，向一位专家级大师求学的里程碑。"},sec={{t="超越奥格瑞玛的厨艺",b="在奥格瑞玛的暗影裂口，巨魔厨师扎姆沙为来往于杜隆塔尔红褐色峡谷的无数战士和旅行者提供食物。然而，当一名专注的厨师学会了扎姆沙所能传授的所有食谱和技巧后，这位大师也只能承认自己已经倾囊相授。在传授了她所有的烹饪秘诀后，她会将这位成熟的学生送往南方的塔纳利斯沙漠，并坦言只有一位精通奇特异域肉类的真正大师，才能帮助天赋异禀的厨师更进一步。"},{t="沙漠中的屠夫",b="目的地是加基森，这是一座由热砂港运营的蒸汽动力贸易枢纽。在那里，在嘈杂的城镇旅店里，经营着迪尔格·奎克里弗。迪尔格是一位拥有非凡味觉且对烹饪毫无顾忌的地精，他在整个卡利姆多都颇具传奇色彩，他能将各种可怕的沙漠生物（有时甚至是皮革废料）烹饪成足以支撑坚毅冒险者的丰盛大餐。"}},faq={{q="谁会指引你去加基森？",a="扎姆沙是位于奥格瑞玛暗影裂口篝火旁的巨魔专家烹饪训练师，她会将这项任务交给已经掌握了她所知全部技艺的厨师。",al={"任务发布者","谁开启任务","扎姆沙任务"}},{q="为什么扎姆沙要让你离开？",a="扎姆沙已经传授了她所能教授的所有食谱和烹饪技巧。为了达到专家级的烹饪大师水平，她指引有前途的厨师前往塔纳利斯的迪尔格·奎克里弗那里学习，这位古怪的专家以善于用最严酷的沙漠食材制作出可口的饭菜而闻名。",al={"为什么去加基森","为什么找迪尔格·奎克里弗","烹饪大师"}},{q="迪尔格·奎克里弗是谁？",a="迪尔格·奎克里弗是一位地精屠夫兼专家级烹饪训练师，位于加基森的旅店中。他以暴躁的脾气、古怪的营养理论（比如从旧皮靴中提取蛋白质）以及对高端异域荒野烹饪的精通而闻名。",al={"谁是迪尔格","迪尔格 加基森"}},{q="学习专家级烹饪需要这个任务吗？",a="不需要。这个任务仅仅是一个引导玩家前往塔纳利斯的指引任务。只要烹饪等级足够，厨师可以直接前往加基森，在没有收到扎姆沙推荐的情况下与迪尔格·奎克里弗交谈。",al={"我需要这个任务吗","烹饪引导任务","这是强制的吗"}},{q="加基森在哪里？",a="加基森是一座由热砂港运营的围墙式沙漠前哨站，位于塔纳利斯北部的沙漠中，坐落在卡利姆多大陆最南端，千针石林的下方。",al={"加基森位置","迪尔格在哪里"}},{q="当你回来时，扎姆沙真的能学到什么吗？",a="虽然扎姆沙调皮地要求你成为烹饪大师后回来教她，但她依然是奥格瑞玛的一位专家级训练师，继续在篝火旁为下一代旅行者服务。",al={"扎姆沙会学烹饪吗","教扎姆沙"}}},fp="20,86,25.346.0,25.368.0,27.124.0,29.200.0,24.239.0,48.181.0,27.143.0,51.199.0"}
P.entries["quest:662"] = {n="深海打捞",s="继“陆地啊！”之后，大副尼兹利克斯要求你在任何人离开海湾之前找回两艘沉船的海图和航海日志。",h="继“陆地啊！”之后，大副尼兹利克斯要求你在任何人离开海湾之前找回两艘沉船的海图和航海日志。",kw={"阿拉希高地","藏宝海湾","深海打捞","先驱号","少女的愚行号","尼兹利克斯","奥布林","卡拉·海角","银松之魂号"},sec={{t="礁石上的两艘沉船",b="奥布林带领三艘船进入海湾，确信宝藏就在这里。先驱号安全靠岸。随后，当“少女的愚行号”和“银松之魂号”驶入时，潮水开始退去，两艘船都搁浅在礁石中一座类似神庙的结构上，并迅速沉没。"},{t="尼兹利克斯想要找回的东西",b="尼兹利克斯希望回收两艘失事船只的航海日志和海图，因为这些信息绝不能留给窥探者。他说，如果这些东西落入敌人手中，舰队指挥官卡拉·海角会将船员们全部处死。"}},faq={{q="为什么少女的愚行号和银松之魂号会沉没？",a="当这两艘船驶入时，潮水开始退去。它们都搁浅在礁石中一座类似神庙的东西上，并迅速沉没。",al={"船只失事原因","船只沉没方式","阿拉希海湾沉船原因"}},{q="大副尼兹利克斯是谁？",a="他是提及奥布林带领三艘船进入海湾的那位大副，他要求找回那两艘沉船的航海日志和海图。",al={"尼兹利克斯","谁发布了深海打捞任务"}},{q="为什么海图和航海日志如此重要？",a="尼兹利克斯不希望这些信息被留下来落入窥探者手中。他说，如果被敌人获得，舰队指挥官卡拉·海角会将船员们全部处死。",al={"为什么要找回日志","为什么是海图和日志"}},{q="哪艘船安全抵达了？",a="只有先驱号。它在海湾安全靠岸，而另外两艘船则沉没了。",al={"哪艘船幸存","先驱号"}},{q="舰队指挥官卡拉·海角是谁？",a="尼兹利克斯提到他，说如果船队的记录落入敌人手中，他会将船员们全部处死。",al={"舰队指挥官卡拉·海角的作用","卡拉·海角是谁"}},{q="这项任务之前是什么？",a="它紧随“陆地啊！”之后。",al={"深海打捞前置任务","上一个任务"}}},fp="16,132,26.272.0,23.228.0,57.125.0,26.144.0,41.160.0,28.86.0,28.106.0,27.19.0"}
P.entries["quest:6621"] = {n="污林熊怪之王",s="“肮脏之林之王”是部落在佐拉姆加前哨站由卡拉恩·阿玛卡发起的一次军事打击行动。为了制服阿斯特兰纳东南方受腐化的肮脏之林熊怪，部落勇士需要在该部落神圣的图腾堆顶端插上一面战旗，以此激怒并处决他们的首领穆戈特酋长。",h="“肮脏之林之王”是部落在佐拉姆加前哨站由卡拉恩·阿玛卡发起的一次军事打击行动。为了制服阿斯特兰纳东南方受腐化的肮脏之林熊怪，部落勇士需要在该部落神圣的图腾堆顶端插上一面战旗，以此激怒并处决他们的首领穆戈特酋长。",kw={"灰谷","肮脏之林","熊怪","绿爪村","卡拉恩·阿玛卡","穆戈特","图腾堆","佐拉姆加"},ang={["class:Shaman"]="肮脏之林那扭曲的图腾和侵略性，反映了燃烧军团入侵后困扰灰谷土著部落的持续精神失衡。",["faction:Horde"]="卡拉恩·阿玛卡利用公开的武力展示来震慑灰谷的敌对部落，从而确保部落补给车队能够安全通过中央道路。",["race:Orc"]="通过插旗来激怒敌方首领进行单挑，是典型的兽人式战争手段，它将力量和决定性的对抗置于长期的摩擦之上。"},sec={{t="武力展示",b="当暗夜精灵竭力遏制灰谷中受腐化的土著部落时，部落采取了经过深思熟虑的侵略性手段来应对这一威胁。佐拉姆加前哨站的卡拉恩·阿玛卡认为，虽然肮脏之林部落的数量无法与北方的蓟皮熊怪相提并论，但他们那肆无忌惮的凶残性构成了沿南方道路潜伏的巨大危险。与其等待部落巡逻队遭到伏击，卡拉恩下令进行一次先发制人的军事威慑，以摧毁该部落的意志。"},{t="亵渎与挑战",b="这次打击的目标是位于密斯特拉湖东北方的绿爪村。卡拉恩制作了一面部落战旗，旨在将其直接插入肮脏之林图腾堆的中心——这对于该部落的先祖之灵和尊严来说是不可饶恕的侮辱。熊怪防卫者们绝望地冲向图腾堆试图拔掉这面冒犯性的旗帜，迫使穆戈特酋长不得不现身，在公开战斗中捍卫自己的荣誉。夺取穆戈特的个人图腾会击溃他们的领导层，并确立部落在该地区的统治地位。"}},faq={{q="是谁下令处死穆戈特酋长的？",a="卡拉恩·阿玛卡，一名驻扎在灰谷西海岸佐拉姆加前哨站的兽人。在对邻近的蓟皮熊怪进行调查后，他发布了这项任务。",al={"肮脏之林之王任务发放者","谁发布肮脏之林之王任务","卡拉恩·阿玛卡任务"}},{q="绿爪村位于哪里？",a="绿爪村位于暗夜精灵定居点阿斯特兰纳的东南方，坐落在密斯特拉湖的东北侧，正好位于灰谷主要东向大道的南边。",al={"绿爪村位置","肮脏之林位置","卡拉恩的旗子插在哪里"}},{q="为什么部落要在图腾堆上插旗？",a="将卡拉恩的旗子直接插在部落神圣的图腾堆上是一种蓄意的挑衅。亵渎他们神圣的领地会迫使肮脏之林熊怪愤怒地发起攻击，并迫使穆戈特酋长为了捍卫自己的地位而公开应战。",al={"为什么插旗","图腾堆插旗目的","为什么要挑战穆戈特"}},{q="肮脏之林熊怪是什么？",a="肮脏之林是灰谷中在第三次战争后陷入疯狂与腐化的众多熊怪部落之一。尽管他们的人数比蓟皮熊怪要少，但他们对外来者依然充满暴力和敌意。",al={"什么是肮脏之林","肮脏之林部落背景","穆戈特酋长是谁"}},{q="取回穆戈特的图腾有什么作用？",a="将穆戈特酋长的图腾带回佐拉姆加前哨站证明了这位酋长的落败。失去了领导者，且神圣的图腾堆也蒙受了羞辱，幸存的肮脏之林熊怪会被震慑，从而避免与部落发生进一步的冲突。",al={"穆戈特的图腾用途","穆戈特死后发生了什么"}},{q="这个任务是如何与之前的熊怪调查联系起来的？",a="这个任务紧随“两难之间（蓟皮熊怪）”之后。在处理完北方的蓟皮熊怪部落后，卡拉恩将注意力转向南方，旨在先发制人地粉碎肮脏之林部落，以防他们发动协同突袭。",al={"与两难之间（蓟皮熊怪）的联系","肮脏之林之王前置任务"}}},fp="21,205,15.277.0,25.401.0,37.162.0,34.126.0,53.178.0,31.190.0,47.216.0,64.181.0"}
P.entries["quest:6623"] = {n="部落医疗队",s="“部落创伤”是一份征召令，指示经验丰富的部落医护人员前往阿拉希高地的落锤镇报到。部落创伤部门的首席医师格里高利·维克托医生正在招募并考察那些能够在极端压力下挽救生命的技术能手。响应此征召意味着医护人员将直接投身于前线野战外科手术残酷且高风险的现实之中。",h="“部落创伤”是一份征召令，指示经验丰富的部落医护人员前往阿拉希高地的落锤镇报到。部落创伤部门的首席医师格里高利·维克托医生正在招募并考察那些能够在极端压力下挽救生命的技术能手。响应此征召意味着医护人员将直接投身于前线野战...",kw={"阿拉希高地","格里高利·维克托医生","急救","落锤镇","部落创伤","阿诺克","救死扶伤"},ang={["class:Priest"]="虽然神圣魔法可以瞬间缝合伤口，但世俗的分诊技术能教人养成必要的纪律，在法力耗尽时分辨出谁是可以被挽救的。",["faction:Horde"]="部落的军事实力在很大程度上依赖于坚韧的战场外科医生，他们能让步兵在阿拉希高地这样残酷的边境冲突中保持战力。"},sec={{t="来自落锤镇的征召",b="在奥格瑞玛的荣誉谷，兽人急救训练师阿诺克会向精通治疗术的人员传达消息，告知他们已经引起了格里高利·维克托医生本人的注意。维克托在落锤镇的防御工事中监管着部落创伤部门，该镇坐落于阿拉希高地崎岖的丘陵地带。阿诺克不仅将这份征召视为一道命令，更将其看作任何一名战场外科医生职业生涯的巅峰。"},{t="残酷的战场分诊工作",b="抵达落锤镇后，你会发现这里的环境极其艰苦。在与激流堡军队和当地敌对势力的持续小规模冲突中，维克托医生被源源不断的受伤步兵、劫掠者和侦察兵搞得应接不暇。首席医师没有时间对新人寒暄；相反，受招募者会立即被要求换上手术服，在快节奏的残酷紧急分诊中证明自己的价值。"}},faq={{q="什么是“部落创伤”？",a="“部落创伤”代表着服务于部落前线的专业医疗和外科分支。它由格里高利·维克托医生在落锤镇领导，其成员专门从事战场医疗、紧急分诊，以及在混乱条件下处理严重的战斗伤势。",al={"部落创伤阵营","什么是部落创伤","部落创伤是谁"}},{q="是谁指派我执行这个任务的？",a="奥格瑞玛荣誉谷的兽人急救训练师阿诺克发布了这份征召。他认为，能够在格里高利·维克托医生麾下效力，是一名有抱负的野战医护人员所能获得的最高荣誉。",al={"部落创伤任务发布者","谁开始部落创伤任务","克伦克·断肢","阿诺克"}},{q="格里高利·维克托医生在哪里？",a="格里高利·维克托医生驻扎在落锤镇的医疗室，这是位于阿拉希高地东北部的主要部落据点。",al={"格里高利·维克托医生位置","维克托在哪里","落锤镇医生"}},{q="报到落锤镇后会发生什么？",a="抵达后，维克托医生会立即指示你换上手术服，进行后续任务“救死扶伤”。你将被置于一项高压测试中，必须在受伤士兵因伤势恶化而死亡之前，对他们进行优先级排序和治疗。",al={"部落创伤后是什么","部落创伤后续任务","救死扶伤任务"}},{q="为什么落锤镇如此急需野战医护人员？",a="落锤镇在阿拉希地区四面楚歌，不断面临人类军队、辛迪加特工和当地野兽的侵袭。伤员源源不断地涌入营地，使得基地本就匮乏的医疗人员捉襟见肘。",al={"为什么落锤镇需要医护人员","落锤镇医疗状况"}},{q="联盟玩家可以接受这个任务吗？",a="不可以。“部落创伤”仅面向部落成员。联盟有对应的医疗评估任务，由塞拉摩岛据点的古斯塔夫·范沃森医生负责。",al={"联盟可以做部落创伤吗","部落创伤联盟版本"}}},fp="12,223,25.350.0,37.332.0,21.258.0,32.206.0,39.111.0,43.264.0,48.235.0,42.145.0"}
P.entries["quest:6625"] = {n="联盟医疗队",s="“联盟创伤”是一份征召令，旨在指引造诣深厚的战地医生前往尘泥沼泽的塞拉摩岛。该征召令由联盟各大主城的急救训练师发出，邀请技术娴熟的医师在联盟精英医疗团的首席医师古斯塔夫·范沃森医生麾下进修。",h="“联盟创伤”是一份征召令，旨在指引造诣深厚的战地医生前往尘泥沼泽的塞拉摩岛。该征召令由联盟各大主城的急救训练师发出，邀请技术娴熟的医师在联盟精英医疗团的首席医师古斯塔夫·范沃森医生麾下进修。",kw={"联盟创伤","尘泥沼泽","急救","铁炉堡","尼莎·火石","塞拉摩","分诊","范沃森"},ang={["faction:Alliance"]="“联盟创伤”确保了卡利姆多和东部王国的每一位前线战士都能拥有在炮火下稳定危重伤情的娴熟战地医生。",["race:Dwarf"]="像铁炉堡的尼莎·火石这样的训练师，正热切地从Great Forge发掘有前途的从业者，派遣他们前往塞拉摩代表联盟最顶尖的医疗人才。"},sec={{t="战地征召",b="当一名医生掌握了联盟各大城市所能传授的基础急救技术后，当地的训练师就已很难再有更多指教。对于那些在缝合、包扎和分诊方面表现出卓越天赋的医师，消息会被直接传达给古斯塔夫·范沃森医生。范沃森医生坐镇于塞拉摩岛这一前线要塞，统领着“联盟创伤”组织，负责在卡利姆多乃至更广阔地区的残酷战区中挽救生命。"},{t="通往塞拉摩之路",b="诸如铁炉堡的尼莎·火石之类的训练师，将范沃森医生的亲自征召视为一种非同寻常的殊荣。塞拉摩岛长期受到来自区域威胁、小规模冲突和严酷荒野环境的压力，不断有重伤士兵被送往此处。要抵达范沃森医生的诊所，需要经过漫长的海上航行前往尘泥沼泽，只有最沉着冷静的战地外科医生才有望通过他严苛的分诊考核。"}},faq={{q="什么是联盟创伤？",a="“联盟创伤”是联盟负责高级战地医疗和紧急分诊的精英医疗分支。该组织由首席医师古斯塔夫·范沃森领导，负责处理常规战地包扎无法解决的危重伤情。",al={"联盟创伤背景故事","谁是联盟创伤"}},{q="是谁指派了这个任务？",a="联盟的急救训练师，例如铁炉堡Great Forge的尼莎·火石，会在有前途的医师达到常规城市训练的巅峰水平后将他们引荐过去。",al={"谁发布联盟创伤任务","铁炉堡急救任务发布者"}},{q="你需要前往哪里？",a="你必须前往位于卡利姆多大陆尘泥沼泽东海岸的人类港口要塞——塞拉摩岛。",al={"范沃森在哪里","联盟创伤目的地"}},{q="古斯塔夫·范沃森医生是谁？",a="古斯塔夫·范沃森医生是“联盟创伤”的首席医师。他驻扎在塞拉摩的军事诊所，被公认为联盟在急救医学和外科分诊领域最权威的专家之一。",al={"古斯塔夫·范沃森","首席医师范沃森"}},{q="向范沃森医生报到后会发生什么？",a="抵达塞拉摩后，范沃森会对候选人进行严酷的实地分诊评估，测试他们在一波又一波垂死士兵面前的救治能力，只有通过测试才能被允许加入战地医疗的高级序列。",al={"联盟创伤之后做什么","分诊任务后续"}},{q="为什么诊所设在塞拉摩，而不是暴风城或铁炉堡？",a="塞拉摩是一座活跃的前线驻军要塞，四周环绕着充满敌意的沼泽、危险的野兽和地区性冲突。不断涌入的重伤士兵使其成为进行高强度创伤训练的理想基地。",al={"为什么选择塞拉摩诊所","为什么在尘泥沼泽进行创伤训练"}}},fp="15,237,19.341.0,21.352.0,24.221.0,28.168.0,28.100.0,31.206.0,49.186.0,71.231.0"}
P.entries["quest:6627"] = {n="知识试炼",s="“知识的试炼”是隐士布劳格·幽魂在石爪山脉设下的一项关于智慧与历史记忆的考验。在取回古籍“巨龙的遗产”后，旅者必须回答布劳格的提问，以证明他们对古代历史的理解。那些未能研读文本的人会发现自己被突然放逐到卡利姆多的各个角落。",h="“知识的试炼”是隐士布劳格·幽魂在石爪山脉设下的一项关于智慧与历史记忆的考验。在取回古籍“巨龙的遗产”后，旅者必须回答布劳格的提问，以证明他们对古代历史的理解。那些未能研读文本的人会发现自己被突然放逐到卡利姆多的各个角落...",kw={"守护巨龙","布劳格·幽魂","大地守卫者","耐萨里奥","石爪山脉","陶拉祖营地","信仰的试炼","老屋"},ang={["class:Mage"]="法师们会发现布劳格的传送结界既令人印象深刻又具有惩罚性，这表明石爪山脉的隐士们掌握着古老的魔法，用来教训那些粗心的学者。",["faction:Horde"]="部落在卡利姆多的试炼需要的不仅仅是蛮力；无论是战士还是萨满，都应当理解塑造了这片大陆的古老伤痕和巨龙之力。",["race:Tauren"]="这项试炼体现了牛头人对祖先智慧和古代历史的尊重，确保年轻的勇士们不会在不了解世界平衡的情况下盲目前行。"},sec={{t="智慧的试炼",b="作为由老屋的多恩·平原行者所开启的一系列试炼的一部分，“知识的试炼”将重点从武力生存或盲目信任转移到了对这个世界古老过去的理解上。居住在石爪山脉峭壁间的布劳格·幽魂要求寻求者找回古籍，并真正吸收书页中所蕴含的知识。"},{t="巨龙的遗产",b="这一课的重点在于守护巨龙的创造与分化，特别是早在天崩地裂发生前就已缔结的宿命契约。布劳格考察寻求者对大地守卫者耐萨里奥的回忆，正是他的堕落与背叛重塑了艾泽拉斯的地表。不尊重历史的人将无法继续走上智慧之路。"},{t="臆测的代价",b="布劳格无法容忍随意的猜测。提供错误答案的寻求者会立即被神秘力量驱逐，并被传送到数英里外的南贫瘠之地陶拉祖营地。若想挽回自己的地位，必须长途跋涉回到石爪山脉，再次面对这位隐士的审视。"}},faq={{q="布劳格·幽魂的问题的答案是什么？",a="布劳格询问的是古籍“巨龙的遗产”中记载的大地守卫者的身份。正确答案是耐萨里奥，这位黑龙之王后来背叛了他的同族巨龙。",al={"布劳格的问题答案","知识的试炼答案","巨龙的遗产问题"}},{q="如果回答错误会发生什么？",a="给布劳格错误的答案会立即导致魔法放逐，将你直接传送到贫瘠之地的陶拉祖营地。你必须长途跋涉回到他在石爪山脉的栖身处，才能再次尝试这项试炼。",al={"知识的试炼回答错误","知识的试炼失败","传送到陶拉祖"}},{q="布劳格·幽魂是谁？",a="布劳格·幽魂是一位居住在石爪山脉的年长隐士，他为部落主持知识和传说的试炼，延续了在千针石林开启的一系列精神试炼。",al={"布劳格·幽魂","谁提供知识的试炼"}},{q="这与千针石林的试炼有何关联？",a="这项试炼始于千针石林老屋的多恩·平原行者所主持的“信仰的试炼”。多恩考察身体和精神上的信任，然后将合格的受试者派往卡利姆多各地，接受其他睿智长者的考验，以检验他们的智慧、意志和力量。",al={"多恩·平原行者的联系","信仰的试炼任务链"}},{q="布劳格考核你的书是什么？",a="这次考核旨在测试你对“巨龙的遗产”的理解，这是一部古老的论著，详细记载了泰坦赐福给五大守护巨龙以守护艾泽拉斯的事迹。",al={"布劳格考核的书籍","巨龙的遗产"}},{q="这个任务链接下来通向哪里？",a="通过布劳格关于守护巨龙的考核后，接下来将进行更深入的古代历史探索试炼，要求寻求者搜寻遥远的地区，以寻找更多的失落记录和祖先知识。",al={"知识的试炼之后是什么","知识的试炼的后续任务"}}},fx={a70a9b29={q="布劳格·幽魂为什么要考验你？",al={"布劳格为什么考验你","布劳格·幽魂的职责","为什么要进行知识试炼"}}},fp="12,361,17.381.0,21.371.0,22.317.1,49.193.0,39.226.0,23.203.0,56.265.0,38.171.0,38.192.0"}
P.entries["quest:6628"] = {n="知识试炼",s="这项试炼是千针石林一系列精神测试中智力考核的标志。在搜寻世界各地的历史文献后，初学者必须前往幽暗城觐见帕科瓦·芬塔拉斯，证明他们了解塑造了艾泽拉斯的那些黑暗历史。",h="这项试炼是千针石林一系列精神测试中智力考核的标志。在搜寻世界各地的历史文献后，初学者必须前往幽暗城觐见帕科瓦·芬塔拉斯，证明他们了解塑造了艾泽拉斯的那些黑暗历史。",kw={"多恩·平原行者","巫妖王","耻辱印记","耐奥祖","帕科瓦·芬塔拉斯","博学试炼","千针石林","幽暗城","老屋"},ang={["faction:Horde"]="这项试炼加强了卡利姆多各部落与洛丹伦地下王国之间的联系，提醒勇士们：智慧对于部落的生存与蛮力同样重要。",["race:Tauren"]="在长者传统的引导下，这项测试促使牛头人旅行者去了解他们北方的盟友——被遗忘者的冷酷历史，以及卡利姆多之外的世界。",["race:Undead"]="试炼的主题直指被遗忘者身份的核心：耐奥祖被创造的悲剧，以及在希尔瓦娜斯打破巫妖王掌控之前，束缚他们的诅咒起源。"},sec={{t="知识的试炼",b="虽然部落的许多试炼旨在考验武力或耐力，“博学试炼”则要求学者般的专注。这一试炼源自多恩·平原行者在老屋制定的精神修炼法，其旅程将候选人从千针石林风蚀的峡谷带往幽暗城阴暗的大厅。帕科瓦·芬塔拉斯担任考官，以严苛的历史知识标准要求寻求者。"},{t="天灾军团的起源",b="为了满足帕科瓦的要求，初学者必须研读《亡灵威胁的开端》，这是一本详述洛丹伦天灾军团被诅咒起源的文献。他盘问的核心是统治冰封王座之实体的起源：前萨满长老耐奥祖，他的精华被燃烧军团锻造成了巫妖王。了解这段冷酷的血统对于理解被遗忘者的存在，以及卡利姆多和东部王国共同面临的危险至关重要。"}},faq={{q="帕科瓦的问题答案是什么？",a="帕科瓦·芬塔拉斯询问的是巫妖王的真名。正确答案是耐奥祖，这位古老的兽人萨满的灵魂被束缚在冰封王座上。",al={"巫妖王答案","帕科瓦的问题","博学试炼答案"}},{q="如果问题回答错误会怎样？",a="回答错误会被施加“耻辱印记”减益效果，你必须等待惩罚时间结束，帕科瓦才会允许你再次尝试考试。",al={"耻辱印记","博学试炼回答错误"}},{q="这个任务链从哪里开始？",a="整个试炼始于千针石林高耸尖塔中的老屋，找多恩·平原行者接取。",al={"博学试炼从哪里开始","多恩·平原行者任务线"}},{q="帕科瓦·芬塔拉斯在哪里？",a="帕科瓦·芬塔拉斯居住在幽暗城，徘徊于被遗忘者的地下图书馆和走廊间，在那里盘问未来的学生。",al={"寻找帕科瓦","帕科瓦·芬塔拉斯位置"}},{q="这项试炼基于什么文献？",a="该测试基于《亡灵威胁的开端》一书，书中详述了亡灵瘟疫的起源和巫妖王的诞生。",al={"博学试炼需要哪本书","《开端》之书"}},{q="为什么千针石林的任务会让人去幽暗城？",a="牛头人设立的这些试炼旨在挑战冒险者的方方面面。为了考验博学程度，候选人需跨越大海，去探寻保存在洛丹伦废墟中的学术记录。",al={"为什么去幽暗城","千针石林到幽暗城"}}},fx={b37475e3={q="帕科瓦·芬塔拉斯为什么要你完成这件事？",a="帕科瓦·芬塔拉斯要用这项任务考验你追求知识的决心。他相信，在这个危机四伏的世界里，知识至关重要——你学得越多、观察得越仔细，就越能看清真相。他让你去取得《亡灵威胁》一书，要求你证明自己确实研读并理解了其中阴郁的历史，而不是只跑了一趟腿。",al={"帕科瓦的动机","帕科瓦为什么考验我","为什么要进行知识试炼"}}},fp="12,297,20.430.0,21.495.1,41.162.0,46.165.0,34.130.0,35.155.0,33.152.0,60.208.0"}
P.entries["quest:6629"] = {n="杀死格鲁迪格·暗云",s="“干掉格伦迪格·暗云”是一个由玛卡巴·扁蹄在石爪山脉东南侧道路旁给予的部落任务。在消灭了恐怖图腾暴徒和雇佣兵之后，玛卡巴指引你去击杀那个摧毁他家园的罪魁祸首：格伦迪格·暗云。除掉格伦迪格和他手下的蛮兵，能为那座被毁的定居点伸张正义。",h="“干掉格伦迪格·暗云”是一个由玛卡巴·扁蹄在石爪山脉东南侧道路旁给予的部落任务。在消灭了恐怖图腾暴徒和雇佣兵之后，玛卡巴指引你去击杀那个摧毁他家园的罪魁祸首：格伦迪格·暗云。除掉格伦迪格和他手下的蛮兵，能为那座被毁的定居...",kw={"蛮兵","暗云","扁蹄","恐怖图腾","格伦迪格","玛卡巴","岗哨","石爪山脉"},ang={["faction:Horde"]="石爪山脉对于部落向卡利姆多的扩张至关重要，而像格伦迪格这样激进的恐怖图腾督军，威胁到了连接贫瘠之地与烈日石居的补给线。",["race:Tauren"]="恐怖图腾氏族不断在牛头人之中播撒不和的种子，格伦迪格的屠杀行径表明，他们始终会以极端的残暴手段反对部落旗下的统一。"},sec={{t="道路屠夫",b="玛卡巴·扁蹄在石爪山脉的小径上遭遇了突如其来的暴力袭击，虽然他侥幸逃生，但心中的伤痛依然无法平复。在确认你有能力对付恐怖图腾的步兵之后，他指引你去找这场血腥屠杀的幕后黑手：格伦迪格·暗云。与那些只是趁火打劫的掠夺者不同，格伦迪格拥有一群忠心耿耿的蛮兵，并亲自带头实施了夷平该村庄的屠杀。"},{t="突袭恐怖图腾岗哨",b="格伦迪格在位于西侧山路更上方的恐怖图腾岗哨建立了营地。为了替玛卡巴的族人复仇并确保这条通道不再遭受暴力侵害，旅行者必须深入这座据点，杀穿暗云的蛮兵核心圈，并在他的袭击小队骚扰其他脆弱的营地之前，终结格伦迪格的性命。"}},faq={{q="格伦迪格·暗云是谁？",a="格伦迪格·暗云是一名残暴的恐怖图腾指挥官，以石爪山脉东南部的恐怖图腾岗哨为基地。他直接策划并领导了那场摧毁玛卡巴·扁蹄村庄的残酷袭击。",al={"格伦迪格·暗云","格伦迪格是谁","恐怖图腾首领"}},{q="在哪里可以找到格伦迪格·暗云？",a="格伦迪格·暗云位于恐怖图腾岗哨，就在靠近贫瘠之地边界、玛卡巴·扁蹄营地西侧的小径上方的山道旁。",al={"格伦迪格位置","格伦迪格在哪","恐怖图腾岗哨位置"}},{q="玛卡巴·扁蹄执行这项任务的动机是什么？",a="玛卡巴眼睁睁看着自己的家园和族人被恐怖图腾屠杀。在初步惩戒了他们的暴徒和雇佣兵之后，他请求取下首领格伦迪格·暗云的人头，以获得真正的了结与复仇。",al={"为什么杀格伦迪格","玛卡巴故事","玛卡巴复仇"}},{q="为什么恐怖图腾会袭击这里的和平定居点？",a="恐怖图腾氏族对其他牛头人部族怀有强烈的蔑视，尤其是那些与部落结盟或信奉温和道路的部族。他们经常使用伏击、掠夺和纯粹的暴力手段，将竞争对手赶出他们想要霸占的土地。",al={"为什么恐怖图腾攻击","恐怖图腾敌意"}},{q="杀掉格伦迪格·暗云之后会发生什么？",a="杀掉格伦迪格·暗云和他手下的蛮兵，就是玛卡巴·扁蹄短暂复仇链条的终点。随着这名屠夫被诛杀，玛卡巴终于可以在确认正义得到伸张后，为他的村庄哀悼。",al={"格伦迪格之后做什么","扁蹄任务链后续"}},{q="这项任务的前置任务是什么？",a="你必须先完成“复仇我的村庄”，玛卡巴·扁蹄会在该任务中测试你的决心，让你去击杀驻扎在西侧的恐怖图腾暴徒和雇佣兵。",al={"击杀格伦迪格前置","格伦迪格之前的任务"}}},fp="22,197,23.328.0,24.270.0,25.158.0,37.124.0,47.191.0,58.191.0,43.151.0,45.162.0"}
P.entries["quest:663"] = {n="法迪尔海湾",s="在法迪尔海湾，瞭望员洛洛迎接了你，并带来了一个消息：奥布里船长在此的停留时间将比原计划长得多。舰队中的两艘船，银松之魂号和少女的愚行号，已经失踪了。洛洛建议你去找船长谈谈。",h="在法迪尔海湾，瞭望员洛洛迎接了你，并带来了一个消息：奥布里船长在此的停留时间将比原计划长得多。舰队中的两艘船，银松之魂号和少女的愚行号，已经失踪了。洛洛建议你去找船长谈谈。",kw={"藏宝海湾","法迪尔海湾","先驱号","瞭望员洛洛","少女的愚行号","seahorn","沙克斯·奥布里","银松之魂号"},sec={{t="洛洛的欢迎",b="一直在瞭望的洛洛发现了你抵达法迪尔海湾。奥布里船长原本承诺船员们只在这里停留几个小时，时间足够收集财宝并返回藏宝海湾。洛洛怀疑事情不会那么顺利。舰队中的两艘船，银松之魂号和少女的愚行号，现在正沉在海底。任何打算留下来的人都被告知要去找船长谈话。"},{t="船长的叙述",b="奥布里船长称整件事是一团糟，并担心如果消息传出去，Seahorn会夺走这艘船。教授的某个装置指向了海湾附近的失踪财宝，所以先驱号靠岸停泊，并向其他两艘船发出了跟随信号。随后大海隆隆作响，海水退去，两艘船都撞上了暗礁。船长说，那不仅仅是暗礁，水下有东西。如果能帮助船员，将会得到丰厚的报酬。"}},faq={{q="其他船只发生了什么事？",a="舰队中的两艘船，银松之魂号和少女的愚行号，已经失踪并沉在海底。",al={"其他船只在哪里","法迪尔海湾的沉船","是什么击沉了船只"}},{q="船员们为什么来到法迪尔海湾？",a="奥布里船长来到海湾是为了收集财宝，原计划只停留几个小时就返回藏宝海湾。",al={"他们为什么在这里","探险的目的","是什么把他们带到了阿拉希"}},{q="在法迪尔海湾应该找谁谈话？",a="如果你打算留下来，瞭望员洛洛建议你去找法迪尔海湾的奥布里船长谈谈。",al={"奥布里船长是谁","沙克斯·奥布里在哪里"}}},fp="8,256,14.390.0,21.472.1,33.120.0,39.121.0,40.105.0"}
P.entries["quest:664"] = {n="船长的复仇",s="斯迪加特船长在失去心爱的“少女的愚行”号后，正坐在法迪尔海湾哀悼。斯迪加特请求你前去追杀那些屠杀了船难幸存者的刺脊娜迦。",h="斯迪加特船长在失去心爱的“少女的愚行”号后，正坐在法迪尔海湾哀悼。斯迪加特请求你前去追杀那些屠杀了船难幸存者的刺脊娜迦。",kw={"阿拉希","刺脊","法迪尔海湾","少女的愚行","娜迦","奥布林","劫掠者","女巫","斯迪加特"},sec={{t="火边的船长",b="斯迪加特船长坐在法迪尔海湾的火堆旁，真希望自己也已葬身鱼腹。船员们拼尽全力想要挽救美丽的“少女的愚行”号，但大海吞噬了它，海水瞬间涌入。奥布林安全抵达了岸边，但娜迦杀害了幸存者。斯迪加特想要刺脊劫掠者和刺脊女巫偿命。"}},faq={{q="斯迪加特船长是谁？",a="“少女的愚行”号的船长，在船只沉没后，他现在正坐在法迪尔海湾的火堆旁。",al={"斯迪加特船长","斯迪加特","任务发布者是谁"}},{q="“少女的愚行”号发生了什么？",a="斯迪加特说大海吞噬了这艘船：上一秒它还浮在水面上，下一秒海水就涌了进来，尽管船员们竭尽全力去抢救它。",al={"少女的愚行","船怎么了","斯迪加特为何沉船"}},{q="为什么斯迪加特船长要杀死那些娜迦？",a="娜迦杀害了船难的幸存者。斯迪加特称他们为渣滓，并发誓要将他们赶尽杀绝。",al={"为什么要杀娜迦","斯迪加特的复仇","刺脊娜迦的原因"}},{q="斯迪加特想要杀死哪些娜迦？",a="十名刺脊劫掠者和三名刺脊女巫。",al={"要杀哪些娜迦","目标娜迦","刺脊目标"}}},fp="15,183,21.320.0,24.98.0,36.135.0,47.85.0,35.58.0"}
P.entries["quest:6641"] = {n="鞭笞者沃尔沙",s="鞭笞者沃什加是一头残暴的多头蛇，它在灰谷海岸的佐拉姆加前哨站肆虐，威胁着部落的立足点。当地的娜迦敬畏这只怪兽的凶猛，在离岸的一座小岛上设立了一个祭坛火盆来供奉它。部落的勇士可以通过熄灭这团圣火来激怒沃什加，将其引诱上岸，从而终结它的掠食暴行。",h="鞭笞者沃什加是一头残暴的多头蛇，它在灰谷海岸的佐拉姆加前哨站肆虐，威胁着部落的立足点。当地的娜迦敬畏这只怪兽的凶猛，在离岸的一座小岛上设立了一个祭坛火盆来供奉它。部落的勇士可以通过熄灭这团圣火来激怒沃什加，将其引诱上岸，...",kw={"灰谷","火盆","多头蛇","穆格拉什","娜迦","沃什加","佐拉姆海岸","佐拉姆加"},ang={["faction:Horde"]="保卫佐拉姆加前哨站对于维持灰谷北部的后勤补给点至关重要，那里的补给线时刻处于被攻击的状态。",["race:Orc"]="像穆格拉什这样的兽人拒绝躲在简陋的木墙后面，他们选择冲进海浪中，与掠食野兽进行面对面的猎杀。"},sec={{t="深海之恐",b="佐拉姆加前哨站位于灰谷西北部的一片狭长海岸线上，时刻受到敌对生物、暗夜精灵和蛇形入侵者的围攻。在佐拉姆海岸游荡的最具破坏性的威胁之一就是鞭笞者沃什加，这头巨大的多头蛇以对前哨站发动野蛮且无端的袭击而闻名。这头怪兽会从海浪中冲出，摧毁防御工事并屠杀守卫，然后又消失在深海之中。"},{t="娜迦的火盆",b="附近的娜迦不仅容忍这头贪婪的多头蛇，甚至积极崇拜它那掠食的恶意。在海岸外的一处礁石上，这些蛇形怪兽点燃了一座祭坛火盆，以此向沃什加致敬。穆格拉什，一名决心结束前哨站所受无休止骚扰的兽人，意识到亵渎这团仪式之火会使这头怪兽在狂怒中冲出水面，这样防御者们就能将它引诱进埋伏，而不是坐以待毙，等待下一次突如其来的屠杀。"}},faq={{q="谁是鞭笞者沃什加？",a="鞭笞者沃什加是一头凶猛巨大的多头蛇，出没于佐拉姆海岸附近的水域。它经常对佐拉姆加前哨站发动无端的袭击，摧毁营地防御并屠杀部落人员。",al={"沃什加","什么是沃什加","沃什加多头蛇"}},{q="为什么娜迦要供奉沃什加？",a="佐拉姆海岸的娜迦因沃什加那永不满足的凶猛和破坏欲而对其保持敬畏。它们在离岸处维护着一个为纪念这头怪兽邪恶本性而常年点燃的火盆，将它视作野蛮海岸狂怒的化身。",al={"为什么娜迦喜欢多头蛇","沃什加娜迦火盆","为什么要供奉沃什加"}},{q="如何引诱沃什加现身战斗？",a="穆格拉什带队突袭了娜迦照看沃什加火盆的小岛。熄灭圣火会深深激怒当地的娜迦守卫以及多头蛇本身，迫使沃什加从海中浮出水面进行报复。",al={"如何召唤沃什加","如何呼唤沃什加","火盆岛沃什加"}},{q="穆格拉什是谁？",a="穆格拉什是一名驻扎在佐拉姆加前哨站的兽人。厌倦了生活在沃什加无端海岸肆虐的恐惧中，他制定了一个计划：扑灭娜迦的祭祀火盆，并与可靠的盟友一起对抗这头怪兽。",al={"穆格拉什是谁","穆格拉什兽人","佐拉姆加穆格拉什"}},{q="为什么佐拉姆加前哨站容易受到海岸野兽的攻击？",a="佐拉姆加前哨站是一座孤立且毫无遮蔽的边境营地，直接坐落在灰谷的沙滩上。由于海中盘踞着娜迦，冲浪区又有野生多头蛇巡逻，其靠水的地理位置使它在各个方向上都容易受到两栖攻击。",al={"为什么佐拉姆加会被攻击","佐拉姆海岸危险"}},{q="鞭笞者沃什加被击败后会发生什么？",a="随着多头蛇被击败，胜利的消息会传回给坚守佐拉姆加前哨站的战歌远行者，减轻了边境守卫持续的压力，并保障了海岸免受突如其来的袭击。",al={"沃什加任务交付","向谁报告沃什加任务"}}},fp="17,265,22.447.0,23.447.0,25.208.0,29.167.0,33.190.0,15.219.0,54.244.0,35.213.1"}
P.entries["quest:665"] = {n="水下宝藏",s="既然他们现在已经成为了正式的黑水掠夺者，菲兹索普教授和德拉克里格博士就要协助奥布林先生寻找失落的精灵宝藏。为了在黑暗的海底搜寻那些宝石，教授需要你在他于洞穴中为魔法之石上的护目镜充能时提供保护。",h="既然他们现在已经成为了正式的黑水掠夺者，菲兹索普教授和德拉克里格博士就要协助奥布林先生寻找失落的精灵宝藏。为了在黑暗的海底搜寻那些宝石，教授需要你在他于洞穴中为魔法之石上的护目镜充能时提供保护。",kw={"阿拉希高地","黑水掠夺者","德拉克里格","魔法之石","护目镜","奥布林","菲兹索普","沉没的宝藏"},sec={{t="为护目镜充能",b="如果没有帮助，在黑暗的海底几乎不可能找到那些宝石，所以德拉克里格博士制造了用于搜寻的护目镜。这些护目镜需要用山坡上一小段距离外的洞穴里，一块魔法之石所蕴含的能量来充电。然而，那个洞穴被诅咒了：靠近的人都会遭到伏击。菲兹索普教授请求你在他将石头的能量充入护目镜时保护他。"}},faq={{q="是谁在寻求帮助？",a="菲兹索普教授请求你在他往返洞穴，并利用魔法之石为博士的护目镜充能的过程中保护他。",al={"谁发布此任务","菲兹索普","任务发布者"}},{q="为什么要给护目镜充能？",a="德拉克里格博士制造它们是为了帮助在黑暗的海底寻找失落的宝石。为了发挥作用，它们必须先用石头的能量来充电。",al={"为什么给护目镜充能","护目镜用途","护目镜是做什么用的"}},{q="为什么教授需要护送？",a="那个洞穴被诅咒了，当他们靠近时就会受到伏击。他需要你在他引导石头的能量时保护他。",al={"为什么要保护菲兹索普","洞穴里有什么"}},{q="教授和博士在为谁工作？",a="教授说他们现在已经是正式的黑水掠夺者了，所以协助奥布林先生寻找失落的精灵宝藏是他们的职责。",al={"他们在帮助谁","奥布林先生","黑水掠夺者"}}},fp="15,292,20.372.0,23.133.0,38.133.0,38.127.0,49.131.0"}
P.entries["quest:666"] = {n="水下宝藏",s="在完成“沉没的宝藏”的第一部分后，德拉克里格博士会将他的寻宝潜水镜借给你，并请你为奥布林船长收集十枚位于海底的精灵宝石，随后将潜水镜归还给他。",h="在完成“沉没的宝藏”的第一部分后，德拉克里格博士会将他的寻宝潜水镜借给你，并请你为奥布林船长收集十枚位于海底的精灵宝石，随后将潜水镜归还给他。",kw={"阿拉希高地","奥布林船长","德拉克里格博士","精灵宝石","法迪尔海湾","舰队指挥官卡拉·海角","寻宝潜水镜","沉没的宝藏"},sec={{t="化作顽石的宝石",b="海底的宝石因为沉没多年，已经硬化成了顽石。但潜水镜中蕴含的力量让你依然能找到它们。德拉克里格博士为这些潜水镜背后的侏儒科技感到自豪。他将潜水镜借给你，这样你就能为奥布林船长收集那些遗失的宝石。"},{t="博士的旱地工作",b="他说他本可以亲自潜下去，但安全干燥的陆地上还有科学工作在等着他。他希望事后能归还潜水镜，因为他确信奥布林船长之后还会频繁使用它们。"}},faq={{q="谁派你去收集宝石？",a="德拉克里格博士，他正在法迪尔海湾等待。他想为奥布林船长收集十枚精灵宝石。",al={"谁给予沉没的宝藏2","沉没的宝藏任务发布者"}},{q="为什么搜寻工作需要特殊的潜水镜？",a="因为沉在海底太久，这些宝石已经变成了顽石。寻宝潜水镜内置的力量让你能轻松找到它们。",al={"为什么需要寻宝潜水镜","潜水镜的作用"}},{q="为什么德拉克里格博士不亲自下水寻找宝石？",a="他说重要的科学事务使他必须留在安全干燥的陆地上。",al={"为什么德拉克里格不游泳","为什么德拉克里格待在陆地上"}},{q="你能保留寻宝潜水镜吗？",a="不能。博士只是将它们借给你，并且在你完成任务后要求归还，因为他预计奥布林船长会经常用到它们。",al={"保留寻宝潜水镜","我需要归还潜水镜吗"}},{q="这个任务在“沉没的宝藏”系列任务中处于什么位置？",a="它紧接在“沉没的宝藏”第一部分之后，在那部分里菲兹索普教授为潜水镜充了能。在此之后还有第三部分。",al={"此任务之前是什么","下一步是什么"}}},fp="15,204,20.309.0,23.200.0,33.102.0,48.145.0,57.69.0,40.113.0,50.124.0"}
P.entries["quest:6661"] = {n="捕捉矿道老鼠",s="“矿道地铁之鼠”是联盟在矿道地铁的一项任务，玩家需要协助蒙蒂进行害虫防治。玩家需使用一支迷人的音乐笛子，将活着的矿道地铁老鼠聚集起来，为蒙蒂的兄弟提供新鲜的肉类，以便制作烤鼠肉串。",h="“矿道地铁之鼠”是联盟在矿道地铁的一项任务，玩家需要协助蒙蒂进行害虫防治。玩家需使用一支迷人的音乐笛子，将活着的矿道地铁老鼠聚集起来，为蒙蒂的兄弟提供新鲜的肉类，以便制作烤鼠肉串。",kw={"矿道地铁老鼠","矿道地铁之鼠","矿道地铁","蒙蒂","捕鼠者之笛","烤鼠肉串","害虫"},ang={["profession:Cooking"]="蒙蒂的兄弟用刚捕获的矿道地铁害虫来制作烤鼠肉串，他强调这些啮齿动物在烹饪前必须保持活着，以免肉质变质。"},sec={{t="铁轨之下的害虫",b="在矿道地铁的地下管道深处，一个名叫蒙蒂的个性角色正在努力清理地下交通线上的害虫。他满口海员黑话，把地铁当成船甲板一样对待，并招募路过的旅行者帮忙驱赶那些在车站出没的乱窜害虫。"},{t="一道可疑的美味",b="蒙蒂并没有直接消灭这些啮齿动物，而是给帮手配备了一支捕鼠者之笛，吹奏迷人的旋律来引诱矿道地铁老鼠跟随。这些生物必须活着带回来，因为蒙蒂的兄弟需要新鲜的食材来进行烹饪：确切地说，是在肉变质之前把它们做成烤鼠肉串。"}},faq={{q="谁发布了“矿道地铁之鼠”任务？",a="蒙蒂，一个驻扎在矿道地铁、说话像海盗一样的角色，发布了这个任务。他正在寻找帮手来协助管理地下交通线上的鼠患。",al={"谁发布矿道地铁之鼠","蒙蒂 矿道地铁","老鼠任务发布者"}},{q="为什么蒙蒂需要活捉这些老鼠？",a="蒙蒂需要活捉这些矿道地铁老鼠，这样它们在被送到他兄弟手中做成烤鼠肉串之前才不会变质。如果这些害虫死得太早，肉就会坏掉。",al={"为什么要活捉老鼠","蒙蒂用老鼠做什么","烤鼠肉串背景故事"}},{q="如何引诱并聚集这些老鼠？",a="蒙蒂会提供一支附魔的捕鼠者之笛。在害虫附近吹奏它的旋律可以引诱它们，使老鼠跟在玩家身后回到蒙蒂的车站。",al={"如何捕捉矿道地铁老鼠","笛子有什么用","捕鼠者之笛 矿道地铁"}},{q="这项任务在哪里进行？",a="该任务发生在矿道地铁内，这是连接联盟城市暴风城和铁炉堡的地下工程奇迹。蒙蒂驻扎在地铁站台上。",al={"矿道地铁之鼠在哪里","蒙蒂位置","矿道地铁老鼠"}},{q="蒙蒂的兄弟是谁？",a="蒙蒂提到他有一个做烤鼠肉串的兄弟，但没有直接说出他的名字。他的兄弟需要源源不断的新鲜活鼠供应，以避免供应变质的肉。",al={"蒙蒂的兄弟是谁","蒙蒂的兄弟 厨师","制作烤肉串的兄弟"}},{q="为什么蒙蒂说话像个海盗？",a="虽然蒙蒂说话时带着浓重的航海海盗口音，把地铁当成船甲板一样，但他其实是在地下铁路承担着害虫防治的工作。",al={"为什么地铁里有个海盗","蒙蒂 海盗 矿道地铁"}}},fp="19,232,24.312.0,23.357.1,40.189.0,44.167.0,39.166.0,32.186.0,23.176.0,34.157.0"}
P.entries["quest:6662"] = {n="我的兄弟，尼普希",s="“我兄弟，尼普希”是一个联盟的运送任务，它带领旅行者穿过铁炉堡和暴风城之间的矿道地铁。一个名叫蒙提的侏儒委托乘客将一箱活老鼠运送给他兄弟尼普希，尼普希在地铁站的另一端经营着一个鼠肉串摊位。在这个古怪的差事之下，隐藏着诺莫瑞根悲剧后，蒙提破碎的心灵令人动容的一面。",h="“我兄弟，尼普希”是一个联盟的运送任务，它带领旅行者穿过铁炉堡和暴风城之间的矿道地铁。一个名叫蒙提的侏儒委托乘客将一箱活老鼠运送给他兄弟尼普希，尼普希在地铁站的另一端经营着一个鼠肉串摊位。在这个古怪的差事之下，隐藏着诺莫...",kw={"矿道地铁","诺莫瑞根","铁炉堡车站","我兄弟，尼普希","蒙提","神秘的肉","尼普希","鼠肉串","暴风城车站"},ang={["faction:Alliance"]="矿道地铁是连接暴风城和铁炉堡的一项必不可少的、高速的工程奇迹，在两端的车站都有古怪的当地小贩为旅行者服务。",["profession:Cooking"]="尼普希的烹饪事业围绕着将新鲜的矿道地铁老鼠串成可食用的肉串，供在铁炉堡和暴风城之间旅行的通勤者食用。",["race:Gnome"]="蒙提古怪的妄想和海盗做派直接源于诺莫瑞根事件的创伤，显示了城市陷落对幸存侏儒造成的深重个人代价。"},sec={{t="地下的运送",b="“我兄弟，尼普希”是一个简短的快递任务，它向乘客们介绍了矿道地铁的奇观——以及危险。驻扎在矿道地铁铁炉堡一侧的古怪侏儒蒙提，委托旅行者将一箱新鲜的活物通过地下交通走廊运送到暴风城仓库的他兄弟尼普希那里。这次运送凸显了连接矮人和人类首都的山脉之下正在进行的奇异日常商业活动。"},{t="鼠肉串生意",b="虽然被贴上了“装着神秘肉品的纸箱”的标签，但这包裹里其实装满了活蹦乱跳的矿道地铁老鼠。尼普希在暴风城终点站经营着一家鼠肉串企业，他需要在这些货变质前收到它们。当箱子完好无损且还在蠕动着送达时，尼普希松了一口气，因为他能继续为穿过这个交通枢纽的饥饿旅行者提供餐饮了。"},{t="诺莫瑞根的伤痕",b="在这次幽默的运送背后，隐藏着对铁炉堡流离失所的侏儒们沉痛的一瞥。蒙提用夸张的海盗俚语说话，警告旅行者要把手脚留在车内，以免落得截肢的下场。在收到老鼠后，尼普希感叹蒙提这辈子从未见过大海；他古怪的海盗人格仅仅是一种源自诺莫瑞根放射性灾难挥之不去创伤的应对机制。"}},faq={{q="谁发布了“我兄弟，尼普希”这个任务？",a="蒙提是一个在矿道地铁铁炉堡一侧发现的古怪侏儒。深受诺莫瑞根灾难影响的蒙提，尽管从未见过大海，却采用了海盗的言谈举止，并捕捉活老鼠通过地铁线运送。",al={"谁发布了“我兄弟，尼普希”","蒙提是谁","蒙提与地铁"}},{q="尼普希是谁？",a="尼普希是蒙提的兄弟，他在暴风城矿道地铁站经营着一个食品摊。他依靠蒙提通过地铁隧道运送活老鼠，以维持他的鼠肉串生意有充足的新鲜原料。",al={"尼普希是谁","尼普希在哪里","尼普希的位置"}},{q="装着神秘肉品的纸箱里装的是什么？",a="尽管贴着“神秘的肉”这种戏谑的标签，箱子里装的其实是蒙提捕捉的、活蹦乱跳的矿道地铁老鼠。尼普希坚持要求它们活着送达，这样肉才不会在被串成肉串之前变质。",al={"装着神秘肉品的纸箱是什么","神秘肉品箱","箱子里有什么"}},{q="为什么蒙提说话像个海盗？",a="蒙提说话像个海盗是因为诺莫瑞根灾难的创伤摧毁了他的心智。正如他的兄弟尼普希所感叹的那样，蒙提甚至从未见过大海，但他却执着于海盗的做派，并警告旅行者不要因为地铁轨道而失去肢体。",al={"为什么蒙提说话像海盗","蒙提是海盗吗","蒙提的海盗背景故事"}},{q="尼普希用这些老鼠做什么？",a="尼普希为经过暴风城车站的通勤者准备并出售鼠肉串。保持地铁上源源不断地运来新鲜、蠕动的小动物，是他这家非传统的地下餐馆得以经营下去的原因。",al={"尼普希用老鼠做什么","鼠肉串生意","尼普希的食物"}},{q="你要把货物送到哪里？",a="你要带着货物穿过矿道地铁，从铁炉堡车站运往暴风城终点站。登上高速地铁车厢，它会载着你穿过海底隧道，直达暴风城一侧尼普希的车站。",al={"如何找到尼普希","我该把肉送到哪","坐地铁去找尼普希"}}},fp="17,385,23.470.0,19.380.0,19.421.1,38.266.0,13.224.0,42.232.0,35.256.0,33.220.0,34.238.0"}
P.entries["quest:667"] = {n="水下伏兵",s="在阿拉希高地，沙克斯·奥布里预料到刺脊纳迦会从海上发起进攻，而如果没有奥布里对这片水域的了解，船员们就无法航行回藏宝海湾。你留在奥布里身旁，操纵大炮击退纳迦。",h="在阿拉希高地，沙克斯·奥布里预料到刺脊纳迦会从海上发起进攻，而如果没有奥布里对这片水域的了解，船员们就无法航行回藏宝海湾。你留在奥布里身旁，操纵大炮击退纳迦。",kw={"阿拉希高地","藏宝海湾","刺脊","纳迦","沙克斯·奥布里","船载大炮"},sec={{t="坚守甲板",b="在完成“沉没的财宝”任务后，沙克斯·奥布里看到刺脊纳迦正在集结准备进攻。纳迦以残忍著称，他们会不断发起攻击，直到奥布里死亡为止。奥布里并不认为自己的生命比船员们更重要，但请求你保护他们，因为如果没有那份航海知识，船员们就无法到达藏宝海湾。你和奥布里留在船上，等待纳迦从水中出现。"},{t="事后",b="袭击结束后，奥布里说船会在潮汐上涨时立刻起航。奥布里本想邀请你加入船员队伍，但看出你有更重要的使命要去完成。"}},faq={{q="谁在攻击沙克斯·奥布里？",a="刺脊纳迦正在集结准备进攻，他们会不断发起攻击，直到沙克斯·奥布里死亡为止。他们来自海上。",al={"谁攻击沙克斯","谁是攻击者","刺脊袭击"}},{q="为什么保护沙克斯·奥布里对船员如此重要？",a="沙克斯·奥布里并不认为自己的生命比船员们更重要，但如果没有奥布里对这片海洋的了解，船员们就无法航行回藏宝海湾。",al={"为什么要保护沙克斯·奥布里","为什么沙克斯很重要","沙克斯·奥布里航海术"}},{q="你如何击退纳迦的进攻？",a="你留在船上，陪伴沙克斯·奥布里并操纵大炮，在纳迦从海上袭来时将他们击退。",al={"如何完成来自下方的死亡","如何保卫沙克斯","大炮防御"}},{q="这场防守发生在什么地方？",a="在阿拉希高地沙克斯·奥布里的船上，纳迦正从海上袭来。",al={"来自下方的死亡在哪里","来自下方的死亡地点"}}},fp="16,250,16.390.0,9.179.1,32.124.0,54.153.0,34.114.0,35.84.0"}
P.entries["quest:668"] = {n="水下宝藏",s="德拉克里格博士将精灵宝石交给你，并让你将其送往奥布林船长处。在海盗中待了几周后，他和教授都明白，私藏这些财宝是不明智的。",h="德拉克里格博士将精灵宝石交给你，并让你将其送往奥布林船长处。在海盗中待了几周后，他和教授都明白，私藏这些财宝是不明智的。",kw={"阿拉希高地","奥布林船长","德拉克里格博士","精灵宝石","海盗","沙克斯·奥布里","沉没的宝藏"},sec={{t="献给船长的财宝",b="德拉克里格博士不想让奥布林船长久等，因为船长会想亲眼看看这些精灵宝石。在这些海盗中待了数周后，博士和教授都意识到，如果被发现私藏海盗的财宝，对他们的身体健康很不利。他将宝石交给你，让你带给正在甲板上等待的奥布林船长。"}},faq={{q="是谁派你去找奥布林船长的？",a="德拉克里格博士把精灵宝石交给你，并让你把它们送给奥布林船长。",al={"谁给予沉没的宝藏3","德拉克里格任务"}},{q="为什么德拉克里格博士这么急着交出宝石？",a="在这些海盗中待了几周后，他和教授认定，如果被发现私藏这些海盗的财宝，对他们的身体健康很不利。",al={"为什么要交出精灵宝石","为什么要给海盗宝石"}},{q="这个任务在任务链中处于什么位置？",a="它是“沉没的宝藏”的第三部分，其后还有第四部分。",al={"沉没的宝藏任务链位置","沉没的宝藏3之前是什么"}}},fp="15,198,24.341.0,33.89.0,55.157.0,34.80.0"}
P.entries["quest:669"] = {n="水下宝藏",s="在“沉没的宝藏”系列任务的前一步之后，沙克斯·奥布里被困在了原地，需要你给藏宝海湾的舰队指挥官卡拉·海角带个信。他请求你带上一颗宝石样本作为找到宝藏的证明。",h="在“沉没的宝藏”系列任务的前一步之后，沙克斯·奥布里被困在了原地，需要你给藏宝海湾的舰队指挥官卡拉·海角带个信。他请求你带上一颗宝石样本作为找到宝藏的证明。",kw={"阿拉希高地","黑水强盗","藏宝海湾","舰队指挥官卡拉·海角","精灵宝石样本","沙克斯·奥布里","沉没的宝藏"},sec={{t="给藏宝海湾的口信",b="沙克斯·奥布里希望舰队指挥官卡拉·海角能立刻得知宝藏被发现的消息，但他自己却无法轻易离开。潮水退得太低了，而且他们惊扰到的生物正盯着他们的一举一动。他请求你帮助黑水强盗，去藏宝海湾告诉卡拉·海角，宝藏已经被发现，且有更多的宝藏正在被打捞上来。一颗精灵宝石样本将作为证明随你一同前往。"}},faq={{q="为什么沙克斯·奥布里不能亲自去送宝石？",a="因为潮水退得太低，他们无法离开，而且他们惊扰到的生物正密切监视着他们的一举一动。",al={"为什么沙克斯无法离开","为什么沙克斯被困住了","为什么沙克斯需要信使"}},{q="舰队指挥官卡拉·海角是谁？",a="他是藏宝海湾的舰队指挥官，奥布里希望他能立刻得知发现宝藏的消息。",al={"卡拉·海角是谁","舰队指挥官卡拉·海角在哪里"}},{q="带往藏宝海湾的证明是什么？",a="一颗精灵宝石样本，用以证明宝藏已被发现，且有更多宝藏正在开采中。",al={"证明是什么","要交付的宝石是什么"}}},fp="15,204,18.358.0,49.118.0,28.84.0,41.93.0"}
P.entries["quest:67"] = {n="斯塔文的传说",s="这项任务开启了调查斯塔文·密斯特曼托命运的线索，由夜色镇市政厅的书记员达尔塔发出。他最古老的记录指向西方的西部荒野中荒废的月溪镇校舍，从而引发了一场关于一个普通人堕落过程的经典调查。",h="这项任务开启了调查斯塔文·密斯特曼托命运的线索，由夜色镇市政厅的书记员达尔塔发出。他最古老的记录指向西方的西部荒野中荒废的月溪镇校舍，从而引发了一场关于一个普通人堕落过程的经典调查。",kw={"达尔塔","暮色森林","脚柜","弃灵","密斯特曼托","月溪镇","校舍","斯塔文","西部荒野"},ang={["class:Mage"]="守护脚柜的弃灵使用变形术和削弱性的诅咒，在原本平凡的教室场景中提供了一次与被悲伤束缚的魔法进行的诡异遭遇。",["faction:Alliance"]="调查的这一阶段突显了该王国的乡村城镇已经分裂得多么严重，迫使英雄们必须穿越被迪菲亚占领的西部荒野，仅仅为了解决一个夜色镇的城镇登记查询。"},sec={{t="镇书记员的请求",b="在夜色镇进行初步询问后，书记员达尔塔调取了城镇登记册来定位斯塔文·密斯特曼托。令他惊讶的是，这份登记册多年未曾更新，上面记载的斯塔文最后已知的住址在遥远的西方，即月溪镇的校舍。由于并不知晓这桩调查背后的阴暗本质，达尔塔将其视为常规的文书工作，请求旅行者去查看该地址，并收集可能有助于更新夜色镇尘封档案的记录。"},{t="月溪镇废墟",b="追踪这条线索意味着要走出暮色森林的阴霾，进入法外之地西部荒野的尘土中。月溪镇曾经是一个繁荣的农业定居点，如今却到处都是迪菲亚潜行者的暴徒。在废弃城镇的中心附近坐落着那间荒废的校舍，在强盗的占领中静静伫立。在校舍内，一个旧脚柜里存放着斯塔文作为教师的过去生活的最初实证，以及一种束缚在箱子上、挥之不去的烦躁悲伤。"},{t="悲剧性的骚灵",b="打扰那个旧脚柜所揭露的不仅仅是被遗忘的书页；它还召唤出了一个在发掘斯塔文过去时攻击任何人的弃灵。那具幻象所带有的忧伤魔法诅咒了入侵者，并暗示了一场与这位校舍教师离开西部荒野有关的未解悲剧，标志着这桩简单的历史调查转变为一场活跃的闹鬼事件。"}},faq={{q="书记员达尔塔是谁？",a="书记员达尔塔是位于暮色森林夜色镇市政厅的城镇记录保管员。他协助在当地登记册中查找关于斯塔文·密斯特曼托的记录，却只找到了古老且过时的条目。",al={"达尔塔","夜色镇书记员","谁开启了斯塔文的传说之二"}},{q="月溪镇校舍在哪里？",a="校舍位于西部荒野西南部的月溪镇。它的建筑风格类似于夜色镇市政厅，矗立在城镇中央，周围环绕着敌对的迪菲亚强盗。",al={"月溪镇校舍位置","校舍在哪里","斯塔文脚柜在哪里"}},{q="旧脚柜里有什么？",a="脚柜中存放着斯塔文·密斯特曼托在月溪镇担任教师期间的旧记录和个人物品，提供了寻找他下落的下一个线索。",al={"斯塔文的脚柜","脚柜里有什么"}},{q="为什么打开脚柜时会有鬼魂攻击？",a="打开脚柜会召唤出一个弃灵，它会使用变形术和诅咒进行攻击。这个烦躁的幻象与围绕斯塔文的过去及其离开月溪镇的黑暗悲剧紧密相连。",al={"弃灵","为什么会刷出鬼魂","斯塔文鬼魂的诅咒"}},{q="斯塔文为什么离开西部荒野？",a="斯塔文曾在月溪镇担任校舍教师，之后为了在王国其他地方寻求私人补习工作而离开，将他旧校舍里的财物锁在了这个被遗弃的城镇中。",al={"斯塔文为何离开月溪镇","斯塔文在月溪镇的历史"}},{q="月溪镇安全吗？",a="不安全。月溪镇已完全处于迪菲亚潜行者的控制之下，这意味着任何寻找校舍的人都必须在全副武装的盗贼和暴徒中杀出一条路。",al={"月溪镇是否危险","月溪镇的怪物"}}},fp="21,204,24.401.0,22.372.0,17.285.1,20.175.0,35.162.0,34.182.0,52.196.1,31.165.0,27.114.0"}
P.entries["quest:670"] = {n="水下宝藏",s="舰队指挥官卡拉·海角目前因补给问题，船只无法离开藏宝海湾，他委托你将一封机密信件送交给正在阿拉希高地沿岸忙碌的沙克斯·奥布里。",h="舰队指挥官卡拉·海角目前因补给问题，船只无法离开藏宝海湾，他委托你将一封机密信件送交给正在阿拉希高地沿岸忙碌的沙克斯·奥布里。",kw={"阿拉希高地","黑水强盗","藏宝海湾","舰队指挥官卡拉·海角","海角的密封信","沙克斯·奥布里","沉没的宝藏"},sec={{t="给奥布里的信",b="舰队指挥官卡拉·海角打量着你，觉得你是个冒险家。由于补给尚未完成，他的船只暂时无法离开藏宝海湾，而他声称无论是本地还是海外都正在酝酿着大事。他需要将一封绝密信件送交给在阿拉希高地沿岸的沙克斯·奥布里，并询问你是否能保证安全且保密地送达此消息。"}},faq={{q="谁让你去送信？",a="藏宝海湾的舰队指挥官卡拉·海角给了你一封给沙克斯·奥布里的密封信件。",al={"谁发布沉没的宝藏5","谁开启了这个任务","海角的信任务发布者"}},{q="为什么舰队指挥官卡拉·海角不亲自去送信？",a="因为在完成补给之前，他的船只无法离开藏宝海湾。",al={"为什么海角不能离开藏宝海湾","为什么舰队指挥官卡拉·海角被困住了"}},{q="沙克斯·奥布里在哪里？",a="在阿拉希高地沿岸，海角说他正忙于那里的事务。",al={"在哪里找到沙克斯·奥布里","沙克斯·奥布里位置","沙克斯在哪里"}},{q="这次送信任务之前发生了什么？",a="这是“沉没的宝藏”任务线的第四部分后续。",al={"沉没的宝藏任务链","沉没的宝藏5之前的任务是什么"}}},fp="15,160,20.346.0,37.79.0,60.63.0,32.69.0,31.46.0"}
P.entries["quest:671"] = {n="邪恶的魔法",s="“邪恶魔法”是一个部落任务，始于阿拉希高地的落锤镇。托尔甘察觉到西方存在令人不安的恶魔气息，并在诺斯弗德农场发现了黑暗召唤仪式的痕迹。他请求冒险者前往该农场，取回用于这些召唤仪式的血石护身符，以便他研究其中的黑暗魔法。",h="“邪恶魔法”是一个部落任务，始于阿拉希高地的落锤镇。托尔甘察觉到西方存在令人不安的恶魔气息，并在诺斯弗德农场发现了黑暗召唤仪式的痕迹。他请求冒险者前往该农场，取回用于这些召唤仪式的血石护身符，以便他研究其中的黑暗魔法。",kw={"阿拉希高地","血石","血石护身符","恶魔召唤","邪恶魔法","落锤镇","诺斯弗德农场","托尔甘"},ang={["class:Warlock"]="术士非常熟悉召唤恶魔所需的仪式和束缚试剂，这使得在诺斯弗德农场发现的血石护身符成为了特别值得关注的物品。",["faction:Horde"]="由于落锤镇是部落在阿拉希高地唯一的据点，黑暗召唤者在西侧活动的行径对该定居点构成了直接的安全威胁。",["race:Orc"]="兽人与恶魔腐化之间有着沉重而痛苦的历史，残留的邪能魔法会从物理上导致他们的血液沸腾并激起非自然的愤怒。托尔甘在诺斯弗德农场附近的本能反应凸显了兽人对恶魔召唤持久的敏感性。"},sec={{t="沸腾的怒火",b="托尔甘是一名驻扎在部落前哨站落锤镇的兽人，他开始注意到阿拉希高地中弥漫着一种令人不安的波动。对于兽人而言，恶魔能量不仅仅是一种抽象的威胁；它还会引发一种根植于血之诅咒历史的本能生物反应。当托尔甘向西追踪这股让他焦躁不安的源头至诺斯弗德农场时，周围环境中的腐化气息令他的血液沸腾，并在他体内激起了一种无法克制的愤怒。在意识到这是恶魔召唤留下的明显后果后，他在黑暗影响彻底吞噬自己的理智之前撤退了，转而寻求外部的帮助，而不是亲自回去。"},{t="血石护身符",b="在诺斯弗德农场，托尔甘发现了黑暗仪式的物证：地上掉落着一块用血石雕刻而成的护身符。这些魔法护身符被积极地用于促进和稳定恶魔召唤仪式。托尔甘设法回收的那块护身符中的魔法储备已经耗尽，导致无法进行彻底的魔法分析。为了彻底调查召唤事件的程度并确定被召唤出来的实体，他指派部落的旅行者前往诺斯弗德农场，从那里的施法者手中取回十块完好的血石护身符。"}},faq={{q="谁发布了“邪恶魔法”任务？",a="该任务由托尔甘发布，他是一名位于阿拉希高地部落据点落锤镇的兽人。托尔甘感觉到附近存在一股令人不安的恶魔气息，并请求冒险者调查诺斯弗德农场，以发现究竟是何种黑暗力量在作祟。",al={"邪恶魔法任务发布者","谁开启邪恶魔法任务","托尔甘阿拉希任务"}},{q="诺斯弗德农场位于何处？",a="诺斯弗德农场位于落锤镇以西，阿拉希高地的北部丘陵地带。这里曾经是一处人类家园，如今已成为使用血石护身符进行隐秘恶魔召唤的场所。",al={"诺斯弗德农场位置","诺斯弗德农场在哪里","查找阿拉希诺斯弗德农场"}},{q="血石护身符有什么用途？",a="血石护身符是用于辅助恶魔召唤仪式的魔法媒介。托尔甘发现诺斯弗德农场的施法者使用这些石头来引导黑暗魔法，但单个护身符在召唤过程中耗尽力量后就会失去作用。",al={"什么是血石护身符","血石护身符的用途","为什么需要血石护身符"}},{q="为什么托尔甘在诺斯弗德农场附近会感到愤怒？",a="由于残留的恶魔召唤能量，托尔甘在诺斯弗德农场附近产生了剧烈的身体反应。对于兽人来说，接触邪能会激起血之诅咒的残余，导致他们的血液沸腾并引发不可控的愤怒。",al={"为什么托尔甘血液沸腾","托尔甘诺斯弗德之怒","为什么托尔甘会生气"}},{q="为什么托尔甘拒绝回到诺斯弗德农场？",a="托尔甘拒绝回到诺斯弗德农场，因为残留的恶魔力量在他体内激起了危险的怒火。由于担心自己可能会失去控制或屈服于这种腐化的影响，他招募外部的冒险者代他取回护身符。",al={"为什么托尔甘不去诺斯弗德","为什么托尔甘不回去","为什么托尔甘不能自己拿护身符"}},{q="需要多少个血石护身符？",a="托尔甘要求从诺斯弗德农场收集十个血石护身符。由于他在地上找到的那块护身符已经完全耗尽了能量，他需要多个带有能量的样本来正确地检查和理解那里正在进行的仪式。",al={"需要多少个血石护身符","血石护身符数量","邪恶魔法任务目标数量"}},{q="是谁在诺斯弗德农场召唤恶魔？",a="黑暗施法者占领了诺斯弗德农场以进行非法的恶魔召唤。他们的黑暗仪式以及由此产生的邪能残渣引起了落锤镇托尔甘的注意，促使部落对该庄园进行了调查。",al={"谁在诺斯弗德农场","谁在诺斯弗德召唤恶魔","诺斯弗德农场邪教徒"}}},fp="11,344,16.632.0,22.610.0,32.254.0,33.207.0,37.270.0,48.253.0,53.258.0,39.241.0,43.233.0"}
P.entries["quest:672"] = {n="振奋精神",s="“振奋精神”是阿拉希高地的一个部落任务，托尔甘试图借此振奋一位名叫戈穆尔的消沉兽人的精神。当关于奥格瑞玛和萨尔大酋长的故事都无济于事时，托尔甘转而利用新近被重新发现的萨满教传统，用高地迅猛龙的眼睛制作了一个能让人恢复活力的护身符。",h="“振奋精神”是阿拉希高地的一个部落任务，托尔甘试图借此振奋一位名叫戈穆尔的消沉兽人的精神。当关于奥格瑞玛和萨尔大酋长的故事都无济于事时，托尔甘转而利用新近被重新发现的萨满教传统，用高地迅猛龙的眼睛制作了一个能让人恢复活力...",kw={"阿拉希高地","戈穆尔","落锤镇","高地迅猛龙之眼","奥格瑞玛","振奋精神","萨满教","萨尔","托尔甘"},ang={["class:Shaman"]="这次努力展示了部落复兴的萨满传统如何被用来治愈情感创伤和萎靡不振，利用动物之灵重燃兄弟的求生欲望。",["faction:Horde"]="这个任务反映了萨尔领导的部落富有同情心的一面，在落锤镇这样偏远的哨所，战友们会照顾消沉的兄弟，而不是抛弃他们。",["race:Orc"]="许多像戈穆尔这样的老兵在集中营的生活和失去原本的生活方式后，依然承受着倦怠和绝望的重负，难以接受萨尔的新部落。"},sec={{t="落锤镇的沉重心情",b="在阿拉希高地偏远的落锤镇前哨站，兽人们既面临外部的敌人，也承受着内心的煎熬。他们的一员，戈穆尔，陷入了深深的、无法摆脱的忧郁之中。他的同伴们试图用卡利姆多的荣耀故事、宏伟的奥格瑞玛要塞，以及年轻大酋长萨尔的远见卓识来激励他。然而，这些伟大的胜利和遥远的奇迹都无法穿透戈穆尔心中的阴霾，也不能给他带来希望。"},{t="荒野之灵",b="托尔甘意识到单纯的言语对戈穆尔的消沉无济于事，于是他转向了部落复兴的信仰遗产。通过收集阿拉希游荡的凶猛高地迅猛龙的眼睛，托尔甘制作了一个受掠食者之灵祝福的护身符。这项仪式并没有依赖蛮力或邪能，而是调用了新近采纳的萨满教传统所带来的恢复力量，希望野兽的生命之火能唤醒这位兄弟沉睡的求生欲望。"}},faq={{q="托尔甘是谁？",a="托尔甘是驻扎在阿拉希高地部落哨所落锤镇的一名兽人。为了帮助消沉的同伴戈穆尔，托尔甘求助于部落新近重新发现的萨满魔法，制作了一个能够恢复其战友内心之火的护身符。",al={"托尔甘是谁","托尔甘 落锤镇","振奋精神 任务发布者"}},{q="戈穆尔是谁，他为什么需要振作起来？",a="戈穆尔是落锤镇的一名兽人居民，正遭受严重的消沉和倦怠困扰。尽管他的兽人同伴们试图用奥格瑞玛和萨尔领导的故事来让他振作，但没有任何事情能触动他或点燃他的精神。",al={"戈穆尔是谁","为什么戈穆尔很悲伤","落锤镇 抑郁兽人"}},{q="为什么托尔甘需要高地迅猛龙的眼睛？",a="托尔甘使用高地奔行者和高地鞭笞者的眼睛来制作萨满护身符。通过引导这些凶猛掠食者的灵魂，托尔甘希望能将迅猛龙与生俱来的力量和坚韧注入戈穆尔体内，重燃他的斗志。",al={"为什么需要迅猛龙眼睛","迅猛龙眼睛护身符","迅猛龙眼睛的作用"}},{q="这个任务发生在哪里？",a="落锤镇是阿拉希高地主要的部落前哨站，以纪念前大酋长Orgrim Doomhammer而命名。它是留在东部王国的兽人们的一处坚固避难所。",al={"落锤镇在哪里","落锤镇位置","阿拉希的兽人"}},{q="托尔甘提到的新近发现的萨满魔法是什么？",a="在遭受恶魔腐化和随后的俘虏期间，兽人失去了与元素和先祖之灵的精神联系。在大酋长萨尔的领导下，部落重新找回了这条古老的萨满之路，利用精神和谐而不是邪能来指引他们的人民。",al={"兽人萨满魔法","新部落的兽人萨满教","为什么需要新的萨满魔法"}},{q="哪些故事没能让戈穆尔振作起来？",a="他的同伴们试图用卡利姆多大海彼岸的新首都奥格瑞玛的伟大故事，以及萨尔大酋长手持Orgrim Doomhammer的盔甲和传奇战锤的英勇事迹来激励戈穆尔。",al={"关于萨尔的故事","他们讲了什么故事给戈穆尔听","奥格瑞玛 戈穆尔的故事"}}},fp="15,295,27.467.0,19.468.0,15.273.0,48.249.0,43.261.0,33.196.0,63.304.0,40.228.0"}
P.entries["quest:673"] = {n="邪恶的魔法",s="落锤镇的托尔甘确信，在斯托姆加德的城墙内住着一位强大的术士，而且那术士正使用一件奥术圣物大量召唤恶魔。在“邪恶的魔法”第一部分任务完成后，他会派你去干掉那个术士，并将圣物带回来。",h="落锤镇的托尔甘确信，在斯托姆加德的城墙内住着一位强大的术士，而且那术士正使用一件奥术圣物大量召唤恶魔。在“邪恶的魔法”第一部分任务完成后，他会派你去干掉那个术士，并将圣物带回来。",kw={"阿拉希高地","血石","落锤镇","玛瑞兹·考尔","斯托姆加德","托尔甘","术士"},sec={{t="斯托姆加德的术士",b="托尔甘确信，斯托姆加德的城墙内住着一位术士。那个术士时不时地会使用一件奥术圣物来召唤出大批可怕的恶魔。托尔甘血液中的灼烧感日益加剧。他想要找到并杀死那个术士，并将她身上那件魔法物品带回来，这样他就能将其摧毁，防止它的力量污染这片土地。那个术士名叫玛瑞兹·考尔，而那件物品就是邪恶的血石宝珠。"},{t="宝珠带来的回忆",b="随着宝珠被摧毁，托尔甘希望自己焦躁不安的夜晚能变得宁静。对他来说，这件物品勾起了他对恶魔曾经控制兽人们的恐怖回忆，那是在地狱咆哮将他们从诅咒中解放出来之前的事。"}},faq={{q="是谁派你去猎杀术士的？",a="落锤镇的托尔甘派你进入斯托姆加德，找到那个术士并取回她携带的魔法物品。",al={"谁给予邪恶的魔法","邪恶的魔法任务发布者","托尔甘任务"}},{q="那个术士在哪里？",a="玛瑞兹·考尔就在斯托姆加德的城墙内，在要塞外部的西侧，躲在一栋建筑后面。你可以听到她在引导法术的声音。",al={"玛瑞兹·考尔在哪里","斯托姆加德术士位置","哪里找到玛瑞兹·考尔"}},{q="你要取回什么圣物？",a="玛瑞兹·考尔的邪恶的血石宝珠，那是托尔甘想要你带回给他以便摧毁的魔法物品。",al={"托尔甘想要什么物品","邪恶的血石宝珠","邪恶的魔法任务物品"}},{q="为什么托尔甘要阻止那个术士？",a="那个术士已经大量召唤出了可怕的恶魔。托尔甘想要消除这种力量的源头并摧毁宝珠，这样它就不能再污染这片土地了。",al={"为什么要摧毁宝珠","托尔甘的动机","为什么要阻止术士"}}},fp="11,250,23.445.0,20.205.1,34.107.0,29.149.0,36.107.0,42.167.0"}
P.entries["quest:674"] = {n="振奋精神",s="“重燃斗志”是一个部落任务，旨在重新点燃戈穆尔的战斗意志，他是一位被绝望吞噬、深受打击的战士。一位使者送来了迅猛龙利爪护符，希望能唤醒他曾经拥有的狂野精神。然而，戈穆尔依然心怀苦涩，质疑任何简单的饰品是否真的能抚平他的悲伤，或是让部落重现荣耀。",h="“重燃斗志”是一个部落任务，旨在重新点燃戈穆尔的战斗意志，他是一位被绝望吞噬、深受打击的战士。一位使者送来了迅猛龙利爪护符，希望能唤醒他曾经拥有的狂野精神。然而，戈穆尔依然心怀苦涩，质疑任何简单的饰品是否真的能抚平他的悲...",kw={"戈穆尔","部落","重燃斗志","迅猛龙护符","迅猛龙利爪护符","战士"},ang={["class:Warrior"]="这个任务的核心是重新点燃一位兽人心中那熄灭的战士之魂，他因一次懦弱的袭击而陷入绝望和悲痛之中。",["faction:Horde"]="戈穆尔哀悼部落陨落的力量，质疑一件小小的饰品是否真的能让这个阵营恢复往日的荣耀。"},sec={{t="熄灭之焰的火星",b="“重燃斗志”涉及将一件迅猛龙利爪护符交给一位名叫戈穆尔的兽人。他的盟友希望通过这个护符引导迅猛龙的狂野力量和凶猛，从而重新唤醒这位战士曾经在他血管中熊熊燃烧的火焰。"},{t="苦涩与绝望",b="收到护符后，戈穆尔只表现出苦涩的悲痛。他深受最伟大的勇士被懦弱之手击杀的回忆所折磨，将这件信物斥为仅仅是打磨过的骨头，并质疑任何饰品怎能让部落恢复往日的荣耀。"}},faq={{q="什么是“重燃斗志”？",a="“重燃斗志”是一个任务，要求将一件迅猛龙利爪护符交给一位名叫戈穆尔的颓废战士，希望能借此重燃他的战斗精神。",al={"什么是重燃斗志","重燃斗志任务"}},{q="戈穆尔是谁？",a="戈穆尔是一位意志消沉的战士，在目睹了最伟大的勇士死于懦夫之手后，他陷入了绝望。他拒绝接受任何信物，并质疑部落的未来。",al={"戈穆尔是谁","戈穆尔"}},{q="为什么要给戈穆尔送去迅猛龙利爪护符？",a="迅猛龙利爪护符由打磨过的骨头和迅猛龙利爪制成，人们献上它，是希望通过引导迅猛龙天生的力量和凶猛，来唤醒戈穆尔心中的火焰。",al={"为什么要送护符","迅猛龙利爪护符有什么用"}},{q="为什么戈穆尔会如此颓废？",a="在目睹了最强大的战士因懦弱而倒下后，戈穆尔失去了所有的希望。这场悲剧让他确信荣誉和力量可以轻易被抹杀，这摧毁了他的战斗意志。",al={"为什么戈穆尔很悲伤","为什么戈穆尔很颓废"}},{q="戈穆尔对护符有什么反应？",a="戈穆尔拒绝了这个礼物，苦涩地将护符斥为仅仅是打磨过的骨头，认为它绝不可能恢复部落的荣耀，也无法挽回他所哀悼的那场悲剧。",al={"戈穆尔喜欢这个护符吗","戈穆尔的反应"}},{q="戈穆尔对部落说了什么？",a="戈穆尔公开质疑部落是否还能重现往日的荣耀，在卑鄙的背叛甚至能击倒最伟大的英雄时，他看不到多少希望。",al={"部落能恢复吗","戈穆尔 部落荣耀"}}},fp="15,352,26.256.0,22.267.1,24.153.0,15.193.0,50.187.0,26.191.0,37.149.0,38.155.0"}
P.entries["quest:675"] = {n="振奋精神",s="“唤醒灵魂”是一个部落任务，讲述了一位老兽人老兵挥之不去的心理创伤。在托尔甘的指引下，一位萨满试图通过先祖魔法来触动痛苦的戈穆尔，以恢复他失去的骄傲和生存意志。",h="“唤醒灵魂”是一个部落任务，讲述了一位老兽人老兵挥之不去的心理创伤。在托尔甘的指引下，一位萨满试图通过先祖魔法来触动痛苦的戈穆尔，以恢复他失去的骄傲和生存意志。",kw={"护身符","戈穆尔","怜悯","兽人","唤醒灵魂","萨满","托尔甘","老兵","酋长"},ang={["class:Shaman"]="这项任务阐述了现代兽人萨满教的修复和精神目的，利用强化的圣物来帮助治愈破碎老兵中残留的创伤。",["faction:Horde"]="在萨尔的领导下，部落积极寻求重新整合并提升那些心怀苦涩的老兵，而不是让他们沉沦于绝望。",["race:Orc"]="戈穆尔体现了那些老兵深层的精神不适和名誉受损，他们未能实现自己心中与过去的酋长一同光荣战死的愿望。"},sec={{t="破碎的灵魂",b="在历经往昔的战争后，许多兽人老兵都在艰难地承受着生存的负担和所谓的名誉扫地。戈穆尔便是这样一位战士，他因未能与倒下的酋长一同光荣战死，而陷入了苦涩的沮丧之中。身为一名富有同情心的萨满，托尔甘试图通过唤醒族人的精神力量来减轻戈穆尔的痛苦。托尔甘相信先祖能量可以治愈心灵的创伤，于是准备了一枚附魔护身符，旨在重新点燃这位老战士的自豪感。"},{t="护身符的局限",b="当把护身符交给戈穆尔时，它并未产生预期的效果。戈穆尔在愤怒的爆发中将护身符扔在泥地上，质问为什么当命运拒绝给他一个光荣的结局时，还会有人向他施舍怜悯。托尔甘从容地接受了这一挫折，他意识到单凭一枚护身符的力量不足以克服多年累积的悲伤。尽管如此，这位萨满依然坚定地执行着他的使命，决心用萨满教义的蓬勃发展最终引导戈穆尔找回往日的荣誉。"}},faq={{q="谁是戈穆尔？",a="戈穆尔是一位饱受悲痛和幸存者内疚折磨的兽人老兵。他在老部落的冲突中幸存了下来，而他的酋长却倒下了，因此他将继续活着视为命运残酷的捉弄，并拒绝一切常规的同情。",al={"戈穆尔是谁","戈穆尔的背景故事","戈穆尔出了什么问题"}},{q="托尔甘是谁，他为什么要帮助戈穆尔？",a="托尔甘是一位萨满，他试图将戈穆尔从苦涩的绝望中解救出来。托尔甘相信，重新与先祖之道建立联系可以修复破碎的灵魂，因此他制作了注入力量的护身符，以提醒昔日的战士们他们族人精神上的重生。",al={"托尔甘是谁","托尔甘想要什么","托尔甘的目的"}},{q="护身符的目的是什么？",a="护身符是托尔甘准备的一个附魔物品，旨在通过萨满能量重新唤醒戈穆尔的战士之魂。当送给戈穆尔时，他拒绝了并将其扔在地上，认为它的魔法不足以驱散他内心深处的苦涩。",al={"什么是护身符","为什么戈穆尔扔掉了护身符","护身符起作用了吗"}},{q="戈穆尔悼念的是哪位酋长？",a="虽然戈穆尔诅咒命运拒绝让他与自己的酋长一同战死，但他并没有直接说出名字。他的话语反映了老部落被击败的残部所怀有的那种悲剧视角，他们渴望在战场上光荣地死去。",al={"哪位酋长死了","戈穆尔的酋长是谁","戈穆尔曾为谁效力"}},{q="护身符失效后，托尔甘打算做什么？",a="尽管初次尝试失败了，但托尔甘保持着耐心。他承认护身符本身的力量不够强大，但他坚信，展示萨满教义的真正力量最终会重新点燃戈穆尔失去的自豪感。",al={"托尔甘放弃了吗","唤醒灵魂任务之后发生了什么","戈穆尔会恢复吗"}},{q="为什么托尔甘要用萨满教来帮助戈穆尔？",a="这一努力突显了萨满作为新部落精神治疗者的重要作用，他们的工作不仅仅是引导元素进行战争，还要抚慰族人受伤的心灵和自尊。",al={"这表明了萨满的什么特质","为什么在这里使用萨满魔法"}}},fp="15,250,15.528.0,24.526.1,15.228.0,45.242.0,35.254.0,34.238.0,52.232.0,47.200.0"}
P.entries["quest:676"] = {n="落锤之战",s="部落勇士受塔伦米尔的塔洛派遣，穿越群山进入阿拉希高地，以支援战事吃紧的落锤镇。在向杜拉姆法尔报到之前，冒险者必须在激流堡废墟附近潜伏的粗野的巨石拳食人魔身上证明自己的战斗准备情况。",h="部落勇士受塔伦米尔的塔洛派遣，穿越群山进入阿拉希高地，以支援战事吃紧的落锤镇。在向杜拉姆法尔报到之前，冒险者必须在激流堡废墟附近潜伏的粗野的巨石拳食人魔身上证明自己的战斗准备情况。",kw={"阿拉希高地","巨石拳执法者","巨石拳食人魔","杜拉姆法尔","落锤镇","希尔斯布莱德丘陵","激流堡","塔洛","塔伦米尔","粗鲁的征召"},ang={["class:Warrior"]="面对魁梧的巨石拳执法者，是那些希望获得像杜拉姆法尔这样的资深兽人指挥官尊重的先锋战士们的经典试炼场。",["faction:Horde"]="这项任务标志着从希尔斯布莱德的局部争端到阿拉希高地更大规模防御的主要过渡，巩固了落锤镇在该地区的重要立足点。",["race:Orc"]="落锤镇对兽人来说具有深厚的情感和历史价值，它是为了纪念大酋长奥格瑞姆·毁灭之锤在解放运动中牺牲而建立的。"},sec={{t="粗鲁的征召",b="在塔伦米尔，塔洛对在希尔斯布莱德丘陵游荡的未经考验的冒险者没什么耐心。看到无纪律的新兵无所事事，而遥远的盟友却在流血牺牲，他指示有能力的战士向东穿过索拉丁之墙，进入阿拉希高地。部落的前哨站落锤镇正受到多方围攻，但塔洛拒绝派遣那些没有先证明自己能应对重大威胁的人去送死。"},{t="巨石拳的试炼",b="为了不让新兵盲目闯入落锤镇，塔洛要求他们在激流堡东北方的食人魔土堆展示武力。巨石拳氏族在阿拉希有很强的势力，他们魁梧的食人魔和执法者对任何行走在高地小径上的人都构成了直接威胁。屠杀这些蛮族既能削减威胁道路侧翼的敌对势力，也能确保只有能干的战士才会抵达前哨站。"},{t="向落锤镇报到",b="在清理完巨石拳营地后，道路指向东北方的落锤镇，这是一个为纪念大酋长奥格瑞姆·毁灭之锤而命名的前哨站。在那里，指挥官杜拉姆法尔以疲惫且怀疑的态度迎接新到来者。无论塔洛是想加强防御力量，还是仅仅送这些傻瓜去送死，杜拉姆法尔都不会浪费时间，他立刻将这些已被证明了实力的战士投入到威胁前哨站生存的无休止冲突中。"}},faq={{q="这个任务在哪里接取和完成？",a="该任务由位于希尔斯布莱德丘陵塔伦米尔的塔洛提供。在完成阿拉希高地所需的击杀任务后，任务在落锤镇的部落前哨站内交给杜拉姆法尔。",al={"粗鲁的征召从哪里开始","任务交付地点","谁提供了粗鲁的征召任务"}},{q="巨石拳食人魔在哪里？",a="巨石拳食人魔居住在阿拉希高地激流堡废墟东北方的一个显著土堆及周围营地中。",al={"巨石拳食人魔位置","阿拉希的食人魔在哪里","巨石拳土堆"}},{q="落锤镇是什么地方？",a="落锤镇是位于阿拉希高地东北部的一个加固过的部落定居点。它以纪念前大酋长奥格瑞姆·毁灭之锤的名字命名，他在兽人收容所解放战争期间在附近阵亡。",al={"什么是落锤镇","落锤镇背景故事","谁建立了落锤镇"}},{q="为什么塔洛要在报到落锤镇前让你去打食人魔？",a="落锤镇正处于不断的攻击之中，极度需要有能力的战士。塔洛派遣新兵去对付巨石拳食人魔作为严酷的试炼场，以确保任何抵达那里协助杜拉姆法尔的人都是有实战能力的，而不是一个累赘。",al={"为什么要先杀食人魔","塔洛的动机","为什么要测试我"}},{q="杜拉姆法尔是谁？",a="杜拉姆法尔是一位资深的兽人战士兼指挥官，驻守在阿拉希高地的落锤镇，负责组织防卫力量以对抗敌对的野生生物、食人魔、巨魔和联盟残部。",al={"杜拉姆法尔的身份","落锤镇指挥官","杜拉姆法尔是谁"}},{q="这个任务之后是什么？",a="向杜拉姆法尔报到后将直接开启“战斗召唤”战役，这是一系列旨在清除周边威胁的军事行动，包括威胁高地的枯木巨魔部落。",al={"后续任务","粗鲁的征召后续","接下来要做什么"}}},fp="19,224,15.378.0,20.326.0,23.349.1,36.191.0,40.123.0,34.188.0,68.204.0,16.172.0,29.183.0"}
P.entries["quest:677"] = {n="短兵相接",s="“备战”是部落的一项军事行动，由落锤镇前哨站的杜拉姆法尔在阿拉希高地发起。受到当地枯木森林巨魔与巨石拳食人魔结盟的威胁，部落对枯木部族发动了先发制人的攻势，以确保他们在该地区的立足点。",h="“备战”是部落的一项军事行动，由落锤镇前哨站的杜拉姆法尔在阿拉希高地发起。受到当地枯木森林巨魔与巨石拳食人魔结盟的威胁，部落对枯木部族发动了先发制人的攻势，以确保他们在该地区的立足点。",kw={"阿拉希高地","掷斧手","巨石拳","备战","杜拉姆法尔","落锤镇","猎头者","巫医","枯木部族"},ang={["faction:Horde"]="落锤镇孤悬于阿拉希高地，四周强敌环伺；保卫前哨站免受当地敌对势力的侵扰，对于确保部落在人类统治的土地上建立永久据点至关重要。",["race:Orc"]="落锤镇建立在第二次战争时期一处拘留营的旧址之上，它是兽人获得解放的象征，这使得保卫他们的新定居点免受敌对邻居的侵犯变得尤为重要。",["race:Troll"]="对于效忠萨尔部落的暗矛巨魔来说，与敌对的枯木森林巨魔作战，凸显了他们的人民与那些拒绝新部落的部族之间截然不同的分野。"},sec={{t="保卫落锤镇",b="在落锤镇这座坚固的堡垒中，杜拉姆法尔组织了一场针对阿拉希高地敌对原住民势力的先发制人军事打击。由于被古老的人类遗迹和当地的敌对派系所包围，这座部落定居点正面临严峻威胁，威胁来自于当地土著枯木森林巨魔与野蛮的巨石拳食人魔之间形成的合作条约。杜拉姆法尔没有坐等敌人掌握生存的主动权，而是号召勇士们发起进攻。"},{t="枯木部族的威胁",b="最初的攻势集中在落锤镇以南，目标直指枯木部族领地的核心。枯木部族拒绝了任何外交手段，转而选择与巨石拳食人魔密谋，试图将部落势力从高地清除出去。通过猎杀他们精锐的掷斧手、猎头者和巫医，落锤镇试图摧毁他们的军事领导层，并表明部落将在此扎根。"}},faq={{q="谁发布了“备战”任务？",a="“备战”是由杜拉姆法尔发布的，他是一位驻扎在阿拉希高地东北部部落前哨站落锤镇的兽人。他负责协调防御和进攻打击，以确保营地能够在邻近势力的威胁下生存下来。",al={"谁发布备战","杜拉姆法尔在哪里","备战任务发布者"}},{q="为什么落锤镇要攻击枯木巨魔？",a="枯木森林巨魔部族已经与巨石拳食人魔结盟，意图将部落从阿拉希高地清除出去。由于他们拒绝了和平共处，并背弃了部落，他们咄咄逼人的态势使得落锤镇别无选择，只能先发制人。",al={"为什么要杀枯木巨魔","为什么攻击阿拉希的巨魔","枯木部族做了什么"}},{q="枯木巨魔位于何处？",a="枯木巨魔居住在阿拉希高地落锤镇以南的数个定居点和营地中，包括靠近山脉的枯木村深处。",al={"枯木巨魔在哪里","枯木营地位置","去哪里找阿拉希的掷斧手"}},{q="巨石拳食人魔在这个冲突中扮演什么角色？",a="巨石拳食人魔是一个居住在阿拉希高地的野蛮氏族。据杜拉姆法尔所言，他们与枯木巨魔达成了权宜之盟，旨在根除部落在高地的存在。",al={"巨石拳食人魔是谁","阿拉希的食人魔","巨石拳与巨魔结盟"}},{q="什么是落锤镇，为什么需要保卫它？",a="落锤镇是部落在阿拉希高地的主要前哨站，以大酋长Orgrim Doomhammer的名字命名。它坐落在一处旧联盟拘留营的遗址上，是部落在东部王国来之不易的避难所和军事堡垒。",al={"什么是落锤镇","落锤镇背景","部落为何在阿拉希"}},{q="枯木巨魔是部落的一员吗？",a="不是。虽然暗矛部族的丛林巨魔是部落的成员，但枯木巨魔是东部王国的原生森林巨魔。他们对外来者怀有深切的敌意，并暴力拒绝了部落的任何接触提议。",al={"枯木部族属于部落吗","森林巨魔对部落友好吗","暗矛对战枯木"}}},fp="12,316,20.489.0,21.423.0,34.241.0,50.275.0,40.173.0,57.220.0,50.262.0,44.243.0"}
P.entries["quest:678"] = {n="短兵相接",s="“武装号召”是杜拉姆法尔在阿拉希高地的落锤镇哨所发布的部落军事试炼。在证明了自己的基本战斗素养后，冒险者们受命向西南方的矮人桥进发，去对付危险的石拳食人魔。消灭前线的蛮兵和施法者法师，既能考验勇士的决心，也能保护部落在阿拉希脆弱的立足点。",h="“武装号召”是杜拉姆法尔在阿拉希高地的落锤镇哨所发布的部落军事试炼。在证明了自己的基本战斗素养后，冒险者们受命向西南方的矮人桥进发，去对付危险的石拳食人魔。消灭前线的蛮兵和施法者法师，既能考验勇士的决心，也能保护部落在阿...",kw={"阿拉希高地","石拳","石拳蛮兵","石拳法师","武装号召","杜拉姆法尔","落锤镇","食人魔","萨多尔大桥"},ang={["class:Mage"]="对抗石拳法师可以让法师们反制那些将奥术能量引向原始破坏目的的野蛮施法者。",["class:Warrior"]="杜拉姆法尔要求在面对蛮力和奥术力量时展现坚韧，这对勇士们的战斗耐力和尚武荣誉是一次直接的考验。",["faction:Horde"]="保卫落锤镇对于部落在东部王国的立足至关重要，铲除富有侵略性的石拳食人魔可以防止哨所被淹没。",["race:Orc"]="落锤镇是以大酋长 Orgrim Doomhammer 的名字命名的，这使得兽人们在驱逐威胁这座纪念性据点的任何竞争对手时，都有着深切的个人情感羁绊。"},sec={{t="勇气考验",b="在孤立的部落据点落锤镇，生存需要坚定不移的尚武精神。杜拉姆法尔认识到那些援助哨所的旅者能力在不断增强，因此他拒绝让任何人因为轻松的胜利而懈怠。勇士们不仅要面对小股散兵，还必须在法尔认为的真正威胁面前证明自己的勇气：那些笨重的石拳食人魔。这些蛮兵不断骚扰部落的远征队，考验着落锤镇守卫们的决心。法尔对这项任务提出了简单的要求——勇士们要么带着战功归来，要么以勇士之魂回归，而只要在战斗中展现出坚韧不拔的品质，就能获得赞誉。"},{t="石拳威胁",b="石拳氏族在落锤镇西南方建立了一处根深蒂固的巢穴，将其势力范围延伸至连接阿拉希与湿地的宏伟矮人桥。与那些毫无纪律的野兽不同，这些食人魔既拥有压倒性的物理力量，又掌握着致命的神秘法术，既有坚韧的蛮兵，也有狡猾的法师。它们极具侵略性的存在对部落的补给线和区域统治构成了直接挑战。通过下令消灭十名石拳蛮兵和四名石拳法师，杜拉姆法尔试图削弱它们的力量，确保石拳氏族明白落锤镇的勇士绝不会让出地盘，也绝不容忍阿拉希出现竞争对手。"}},faq={{q="谁发布了“武装号召”任务？",a="该任务由杜拉姆法尔发布，他是驻扎在阿拉希高地东北部、防御森严的部落哨所——落锤镇中的一名军官。为了寻求能干的勇士来保卫据点脆弱的阵地，法尔指派久经考验的战士去打击该地区危险的敌人，以展现他们的军事纪律和原始力量。",al={"谁发布了武装号召","杜拉姆法尔任务","武装号召任务发布者"}},{q="石拳巢穴在哪里？",a="石拳食人魔定居点位于落锤镇的西南方，坐落在通往萨多尔大桥的道路沿线，那是通往湿地的大型矮人桥。这些食人魔占据了高地上的土洞和土丘，它们的肉搏战士和施法者都聚集在那里。",al={"石拳位置","食人魔在哪里","阿拉希石拳巢穴"}},{q="完成这项任务需要击败哪些敌人？",a="杜拉姆法尔指示勇士们消灭十名石拳蛮兵和四名石拳法师，然后返回落锤镇。蛮兵依靠沉重的近战攻击，而法师则在远处用奥术进行支援，这使得它们比阿拉希普通的劫掠者要危险得多。",al={"武装号召击杀数量","杀哪些食人魔","武装号召目标"}},{q="为什么石拳食人魔被认为是落锤镇的威胁？",a="石拳氏族在阿拉希建立了牢固的立足点，并屡次挑战落锤镇的部落驻军。它们靠近通往南部矮人桥的关键交通路线，威胁着部落的侦察和补给线。杜拉姆法尔认为它们是一股必须通过常规军事打击加以遏制的真正竞争势力。",al={"为什么要对抗石拳","石拳对部落敌对吗","阿拉希食人魔威胁"}},{q="杜拉姆法尔所说的“带着肉身或灵魂归来”是什么意思？",a="杜拉姆法尔那冷酷的话语反映了阿拉希部落不妥协的勇士精神。他期望他的战士们能成功生还，但也尊重那些在与强大的敌人英勇作战时牺牲的人。在他看来，在压倒性的食人魔力量面前展现出坚韧和无畏本身就是一种荣誉，无论是否能在血腥的战斗中幸存下来。",al={"杜拉姆法尔语录","灵魂归来的含义","肉身或灵魂归来"}},{q="联盟玩家可以接受这个任务吗？",a="不可以，“武装号召”严格来说是杜拉姆法尔在落锤镇内发布的部落任务。联盟军队在西部的避难谷地行动，并将落锤镇的守卫者和石拳食人魔都视为争夺阿拉希高地控制权的敌对势力。",al={"武装号召是部落独有吗","联盟阿拉希武装号召","联盟能做这个任务吗"}},{q="为什么杜拉姆法尔同时针对蛮兵和法师？",a="同时针对这两类食人魔可以抵消石拳氏族兵种组合的战术优势。蛮兵构成了吸收伤害的肌肉前线，而法师则在后方施展破坏性魔法。击败这两类敌人可以确保该氏族无法对落锤镇发起有组织的联合反击。",al={"为什么要杀法师","石拳法师的重要性","石拳蛮兵和法师"}}},fp="12,399,16.642.0,22.661.0,33.356.0,38.307.0,48.306.0,64.356.0,58.370.0,42.275.0,46.307.0"}
P.entries["quest:679"] = {n="短兵相接",s="继之前的“号角吹响”任务后，落锤镇的杜拉姆法尔宣称是时候斩断野兽的头颅了。他派你去寻找盘踞在激流堡废墟中的石拳食人魔领主和萨满。",h="继之前的“号角吹响”任务后，落锤镇的杜拉姆法尔宣称是时候斩断野兽的头颅了。他派你去寻找盘踞在激流堡废墟中的石拳食人魔领主和萨满。",kw={"阿拉希高地","石拳","石拳领主","石拳萨满","杜拉姆法尔","落锤镇","激流堡"},sec={{t="野兽的头颅",b="杜拉姆法尔说你已经证明自己有足够的能力去完成最后一击。那些发动袭击的领袖们盘踞在激流堡废墟中，他称那里是人类脆弱的象征。去猎杀石拳领主和侍奉他们的萨满吧，因为他们正试图将部落驱逐出这片土地。"}},faq={{q="是谁派你去对抗石拳领袖的？",a="杜拉姆法尔，位于阿拉希高地的部落前哨站落锤镇。",al={"谁发布号角吹响任务","杜拉姆法尔任务","谁开启了号角吹响3"}},{q="石拳领主和萨满位于何处？",a="杜拉姆法尔说那些发动袭击的领袖正躲藏在激流堡废墟中。",al={"石拳领主在哪里","石拳萨满位置","去哪里找食人魔领袖"}},{q="这一步在任务链中处于什么位置？",a="它是继之前的“号角吹响”任务后的后续，也是始于塔伦米尔的塔洛任务链的最后一步。",al={"号角吹响3之前是什么任务","号角吹响任务链","落锤镇食人魔任务链"}},{q="杜拉姆法尔希望对石拳领袖们做什么？",a="他希望作为最后一击杀掉那些领导袭击的领主和萨满，因为他们企图将部落赶出这片土地。",al={"为什么要杀石拳领主","为什么要攻击激流堡的食人魔"}}},fp="12,208,21.316.0,47.69.0,51.80.0,40.110.0,56.133.0"}
P.entries["quest:68"] = {n="斯塔文的传说",s="这次调查揭开了斯塔文·密斯曼陀黑暗传说中被遗忘的篇章。在月溪镇的一个旧脚踏箱里找到的一封覆满灰尘的信，成为了他行踪消失前居所的确凿证据，线索再次指向了夜色镇的档案记录。",h="这次调查揭开了斯塔文·密斯曼陀黑暗传说中被遗忘的篇章。在月溪镇的一个旧脚踏箱里找到的一封覆满灰尘的信，成为了他行踪消失前居所的确凿证据，线索再次指向了夜色镇的档案记录。",kw={"书记员达尔塔","斯塔文诅咒","夜色镇","暮色森林","一封覆满灰尘的信","脚踏箱","弃灵","密斯曼陀","月溪镇","斯塔文"},ang={["class:Mage"]="守护脚踏箱的敌对幽灵挥舞着欺骗性的奥术工具（如变形术）以及一种破坏性的诅咒，暗示了斯塔文所过之处编织的不自然力量。",["class:Priest"]="弃灵束缚在一个简单的纪念品箱子上，这一现象说明了一种无法在死后安息的痛苦情感负担。",["faction:Alliance"]="解开斯塔文·密斯曼陀的谜团，有助于饱受困扰的夜色镇整理登记曾穿过该地区边界的阴影人物。"},sec={{t="月溪镇的遗踪",b="在追寻斯塔文·密斯曼陀的历史时，月溪镇一个被冷落的旧脚踏箱里藏着拼图的关键碎片：一封覆满灰尘的信。月溪镇曾是一个繁荣的农业聚居点，如今已沦为废墟，到处是亡命之徒和不安的幽灵。斯塔文在这里的停留时间很短，以至于被人们遗忘，但这一被忽视的信件确凿地证实了他曾在此地停留。"},{t="脚踏箱边的闹鬼事件",b="挖掘斯塔文的遗物并没有悄无声息地进行。翻动箱子惊动了阴影中的一个弃灵，它迫切地想要守护这里留下的秘密。这个幽灵发动了迷惑的魔法和虚弱的斯塔文诅咒进行攻击，这表明无论此人遭遇了什么命运，悲伤和黑暗的咒语都紧紧缠绕着他的剩余物品。"},{t="更新城镇登记册",b="将信送回边界另一端的夜色镇，为书记员达尔塔提供了他所需的缺失证明。虽然达尔塔觉得这封信从未寄出很奇怪，但证据确凿。随着月溪镇这一环节得到证实，官僚的文书记录终于可以指引调查方向，探寻斯塔文接下来逃往了何处。"}},faq={{q="月溪镇的旧脚踏箱里有什么？",a="脚踏箱里有一封“一封覆满灰尘的信”，是斯塔文·密斯曼陀在月溪镇逗留期间写的。它作为确凿证据，证实了他在失踪前曾居住在该镇。",al={"我发现了什么","脚踏箱内容物","斯塔文的信"}},{q="为什么打开箱子时会有灵魂攻击？",a="一个弃灵徘徊在斯塔文被遗忘的遗物附近，一旦有人扰动箱子，它就会起身攻击。它会使用令人不安的魔法，包括恐惧、变形术以及挥之不去的斯塔文诅咒。",al={"弃灵","为什么被攻击","脚踏箱幽灵"}},{q="为什么要带这封信去见书记员达尔塔？",a="书记员达尔塔负责夜色镇市政厅的城镇记录和登记工作。他需要确切的记录来确认斯塔文过去的行踪，然后才能协助进一步追踪他。",al={"书记员达尔塔是谁","为什么要找达尔塔","darkshire town hall"}},{q="为什么这封信从未寄出具有重要意义？",a="这封信被塞在废弃的脚踏箱里无人理睬，暗示了仓促的离去或日益增长的妄想，这加剧了围绕斯塔文行踪的诡异秘密感。",al={"未寄出的信的秘密","为什么没寄出去"}},{q="斯塔文诅咒有什么作用？",a="由守护脚踏箱的弃灵施加，斯塔文诅咒是一种虚弱的妖术，会使受害者的所有主要属性在十分钟内降低。",al={"斯塔文诅咒减益","灵魂诅咒"}},{q="把信交给达尔塔后，线索指向哪里？",a="一旦书记员达尔塔用这份来自月溪镇的证据更新了市政登记册，他就能引导你的查询方向，指向斯塔文随后的已知目的地。",al={"接下来做什么","达尔塔之后的去向","下一条线索"}}},fp="21,183,30.282.0,28.233.1,26.275.0,47.141.0,50.185.0,36.151.0,53.154.0,34.127.0,60.111.0"}
P.entries["quest:680"] = {n="真正的威胁",s="继“号召武装”之后，科林法尔告诉你，她的丈夫并不清楚落锤镇为何会遭受攻击，她请求你去杀死食人魔奥卡拉尔并将他的头颅带给她。",h="继“号召武装”之后，科林法尔告诉你，她的丈夫并不清楚落锤镇为何会遭受攻击，她请求你去杀死食人魔奥卡拉尔并将他的头颅带给她。",kw={"阿拉希高地","落锤镇","科林法尔","玛格索尔","奥卡拉尔","激流堡","阿拉索之塔"},sec={{t="对她丈夫的怨恨",b="科林法尔说你为她丈夫效力得很好，但他却完全不知道落锤镇为何会遭到攻击。罪魁祸首是玛格索尔在激流堡的走卒奥卡拉尔，他因为多年前被她丈夫击败而怀恨在心，一心想要他的命。她的占卜显示，这名食人魔已经为他设下了陷阱。"},{t="科林的隐瞒",b="科林向她的丈夫隐瞒了这名食人魔存在的迹象，因为她认为如果让他知道奥卡拉尔在哪里，他会鲁莽地冲过去。她转而请求你的帮助。你会在阿拉索之塔附近找到奥卡拉尔，她希望他的死能结束对落锤镇的攻击。"}},faq={{q="科林法尔试图保护谁？",a="她的丈夫。她的占卜告诉她，奥卡拉尔已经为他设下了陷阱，这名食人魔因为多年前被他击败而想要他的命。",al={"科林的丈夫","为什么科林需要帮助"}},{q="为什么奥卡拉尔要攻击落锤镇？",a="科林法尔称奥卡拉尔是玛格索尔在激流堡的走卒，对多年前击败他的丈夫怀有刻骨的仇恨。她说他的死将会平息这些攻击。",al={"为什么奥卡拉尔憎恨科林的丈夫","谁是奥卡拉尔","奥卡拉尔的动机"}},{q="奥卡拉尔在哪里？",a="科林法尔说他在阿拉索之塔附近。",al={"奥卡拉尔的位置","哪里找到奥卡拉尔","找到奥卡拉尔"}},{q="为什么科林要对她丈夫隐瞒这个威胁？",a="她担心如果让他知道食人魔的位置，他会鲁莽地冲过去，因此她一直没让他看到任何奥卡拉尔存在的痕迹。",al={"为何保密","为何隐藏奥卡拉尔","科林的秘密"}}},fp="15,169,28.274.0,16.281.0,35.124.0,37.162.0,26.47.0,57.125.0"}
P.entries["quest:681"] = {n="诺斯弗德农场",s="位于避难谷地的尼艾丝队长请求支援，以对抗占据诺斯弗德农场的辛迪加。他们控制了激流堡守军与南海镇之间的土地，使得补给难以运达。",h="位于避难谷地的尼艾丝队长请求支援，以对抗占据诺斯弗德农场的辛迪加。他们控制了激流堡守军与南海镇之间的土地，使得补给难以运达。",kw={"尼艾丝队长","强盗","雇佣兵","诺斯弗德农场","避难谷地","南海镇","激流堡","辛迪加"},sec={{t="苦战",b="激流堡被食人魔、辛迪加和联盟瓜分，各派势力之间进行着血腥的僵持。联盟的军队在不断减少，而敌人的势力却在壮大。守军需要来自南海镇的支援，但补给物资却迟迟不到。"},{t="农场的辛迪加",b="辛迪加占据了守军和南海镇之间的地带。尼艾丝队长希望你去他们的基地——诺斯弗德农场，消灭那里的强盗和雇佣兵，希望能借此减轻补给线的压力，让更多的物资运抵这里。"}},faq={{q="为什么尼艾丝队长想要在诺斯弗德农场攻击辛迪加？",a="南海镇是补给的来源地，但辛迪加却盘踞在南海镇和守军之间的土地上。尼艾丝希望在他们的基地消灭他们，从而减轻补给线的压力。",al={"为何攻击诺斯弗德农场","尼艾丝的目标","诺斯弗德农场任务的目的"}},{q="激流堡目前的局势如何？",a="食人魔、辛迪加和联盟瓜分了这座曾经伟大的城市，各方势力陷入了血腥的僵局。联盟的兵力正在缩减，而敌人的势力却在不断增强。",al={"激流堡战争状态","谁控制了激流堡","激流堡的状况"}},{q="联盟的补给来自哪里？",a="守军指望南海镇能提供支援，但辛迪加对中间地带的控制使得物资难以运送。",al={"谁为避难谷地提供补给","南海镇补给","补给从哪里发出"}},{q="需要在农场消灭哪些敌人？",a="在诺斯弗德农场消灭十名辛迪加强盗和六名辛迪加雇佣兵。",al={"在诺斯弗德杀谁","诺斯弗德的目标","辛迪加敌人列表"}}},fp="15,205,20.269.0,26.257.0,70.197.0,44.201.0,44.140.0,49.81.0"}
P.entries["quest:682"] = {n="激流堡徽章",s="在激流堡，辛迪加正在与一支民兵部队交战，其头目会为从阵亡民兵身上搜出的每一枚徽记支付金币。在避难谷地，尼艾丝队长希望找回这些徽记。",h="在激流堡，辛迪加正在与一支民兵部队交战，其头目会为从阵亡民兵身上搜出的每一枚徽记支付金币。在避难谷地，尼艾丝队长希望找回这些徽记。",kw={"阿拉希","徽记","尼艾丝队长","民兵","避难谷地","激流堡","辛迪加"},sec={{t="士兵的悬赏",b="在激流堡，辛迪加正与一支民兵部队交战。为了驱使手下与训练有素的士兵战斗，辛迪加的头目会对每一枚从阵亡民兵身上搜出的徽记支付金币。尼艾丝队长称他们为割喉恶徒，决不允许他们保留勇敢的阵亡者身上的战利品，因此你被派往辛迪加控制下的激流堡区域搜寻这些徽记，并将它们带回避难谷地。尼艾丝希望让辛迪加明白，他们无法靠死人牟利。"},{t="狩猎之后",b="尼艾丝承诺会告知阵亡者的亲属，他们是战死沙场的。虽然传递这样的消息很残酷，但尼艾丝认为这总比让一个家庭去猜测失踪亲人的下落要好。"}},faq={{q="辛迪加为什么要激流堡徽记？",a="他们的头目对民兵设下了悬赏：每一枚从阵亡民兵身上搜出的徽记都能换取金币，这是为了驱使辛迪加的追随者去攻击那些训练有素的部队。",al={"为什么要辛迪加徽记","辛迪加激流堡悬赏","为什么要收集徽记"}},{q="徽记在哪里可以找到？",a="尼艾丝队长派你进入激流堡中辛迪加控制的区域去寻找这些徽记。",al={"哪里可以找到徽记","激流堡徽记位置","徽记掉落位置"}},{q="是谁下令收回这些徽记的？",a="避难谷地的尼艾丝队长，她不希望辛迪加保留阵亡民兵的战利品。",al={"谁发放激流堡徽记任务","尼艾丝队长徽记任务","激流堡徽记任务发布者"}}},fp="17,200,20.487.0,14.204.1,46.189.0,27.103.0,39.106.0"}
P.entries["quest:683"] = {n="萨拉·巴鲁的请求",s="“萨拉·巴鲁的请求”是一项沉重的任务，委托人是铁炉堡一位悲痛的矮人遗孀。萨拉因沉浸在巨大的悲痛中，无法直面她的君主，因此将一封写给国王麦格尼·铜须的私人请愿书托付给你，这封信是关于她阵亡的丈夫萨利·巴鲁的。",h="“萨拉·巴鲁的请求”是一项沉重的任务，委托人是铁炉堡一位悲痛的矮人遗孀。萨拉因沉浸在巨大的悲痛中，无法直面她的君主，因此将一封写给国王麦格尼·铜须的私人请愿书托付给你，这封信是关于她阵亡的丈夫萨利·巴鲁的。",kw={"国王的敬意","丹莫罗","铁炉堡","magni bronzebeard","萨拉·巴鲁","萨利·巴鲁","萨多尔大桥"},ang={["faction:Alliance"]="在悲伤的市民和联盟领袖之间传递信息，突显了普通民众在保卫王国的冲突中所承受的个人代价。",["race:Dwarf"]="将一位悲伤遗孀的请求直接呈交给你们的国王，触及了矮人文化中对石艺、血统和尊崇先祖牺牲的深厚重视。"},sec={{t="遗孀的请求",b="在从萨多尔大桥深处的水中找回了那封凄惨的遗书后，萨拉·巴鲁悲痛欲绝。为了不让丈夫萨利的牺牲被世人遗忘，她写下了一封呈交给铁炉堡王座的请愿书。由于悲伤过度，她无法亲自前往宫廷遵守礼仪，因此将这封密封的羊皮纸交给了一位值得信赖的联盟勇士，代她向国王麦格尼·铜须陈情。"},{t="觐见国王",b="向铁炉堡的High Seat呈递私人请愿书绝非寻常琐事，但麦格尼·铜须非常关注卡兹莫丹的勇猛保卫者。在收到这份信息后，国王暂停了国事，亲自阅读了一位士兵遗孀谦卑的请求，这体现了他与那些建设并保卫他山中王国的平民矮人之间的深厚纽带。"}},faq={{q="萨拉·巴鲁是谁？",a="萨拉·巴鲁是一位铁炉堡矮人，她的丈夫是士兵萨利·巴鲁，他在萨多尔大桥的惨剧中丧生。她居住在城内，时刻怀念着她的丈夫。",al={"萨拉·巴鲁","萨拉是谁"}},{q="为什么萨拉要我去见国王，而不是自己去？",a="萨拉在最终得知丈夫的确切命运后，被悲痛淹没了。她觉得自己在High Seat向国王麦格尼·铜须请愿时，无法维持应有的礼节和镇定。",al={"为什么萨拉不能亲自去","萨拉的悲伤"}},{q="萨利·巴鲁是谁？",a="萨利·巴鲁是一位矮人士兵，曾保卫过萨多尔大桥。他在桥上的战斗中牺牲，留下了一封被水浸湿的给妻子的信。",al={"萨利·巴鲁","萨拉的丈夫"}},{q="我在哪里递交“萨拉·巴鲁的请求”？",a="你需要直接将这份请愿书送到位于铁炉堡中心的High Seat，交给国王麦格尼·铜须。",al={"麦格尼在哪里","国王麦格尼的位置","任务提交位置"}},{q="国王麦格尼阅读请愿书后会发生什么？",a="阅读萨拉的请求让国王麦格尼决心妥善纪念这位阵亡的士兵，这直接引出了后续的任务“国王的敬意”，旨在建立一座永恒的纪念碑。",al={"任务后续","下一个任务"}},{q="哪个阵营可以执行此任务？",a="这项任务仅限联盟成员执行，因为它涉及矮人的内部事务以及觐见国王麦格尼·铜须。",al={"部落可以做这个吗","阵营要求"}}},fp="18,137,17.343.0,22.301.1,19.150.0,63.170.0,21.144.0,38.94.0,45.124.1,37.127.0"}
P.entries["quest:684"] = {n="通缉：玛雷兹·考尔",s="“通缉：玛瑞兹·考尔”是一个联盟的赏金任务，目标是盘踞在激流堡废墟中的一名辛迪加高层特工。考尔既是一名极具影响力的顾问，也是一名与恶魔勾结的黑暗术士，她对试图收复阿拉希高地的联盟部队构成了严重威胁。",h="“通缉：玛瑞兹·考尔”是一个联盟的赏金任务，目标是盘踞在激流堡废墟中的一名辛迪加高层特工。考尔既是一名极具影响力的顾问，也是一名与恶魔勾结的黑暗术士，她对试图收复阿拉希高地的联盟部队构成了严重威胁。",kw={"阿拉希高地","赏金","尼艾丝队长","玛瑞兹·考尔","避难谷地","激流堡","辛迪加","术士"},ang={["class:Paladin"]="作为一名在古老人类王国废墟中公然与恶魔实体勾结的人，考尔的行为是对圣光和激流堡防御的公然挑衅。",["class:Warlock"]="玛瑞兹·考尔代表了辛迪加中更黑暗的邪教分支，展现了这些政治叛乱分子如何轻易地转向恶魔召唤以扩张自己的势力。",["faction:Alliance"]="在尼艾丝队长的领导下，避难谷地的联盟驻军正在奋力收复激流堡，这使得玛瑞兹·考尔这类辛迪加高层目标成为了首要的战略优先级。"},sec={{t="辛迪加头目的悬赏",b="“通缉：玛瑞兹·考尔”是一份联盟的赏金法令，旨在铲除辛迪加在阿拉希高地的关键领导人物之一。玛瑞兹·考尔在该组织中担任高层顾问和外勤特工，负责策划他们在废墟之城激流堡的活动。通过悬赏她的项上人头，避难谷地的联盟指挥官旨在摧毁辛迪加当地的指挥体系。"},{t="激流堡的术士",b="与辛迪加中常见的强盗或落魄贵族不同，玛瑞兹·考尔是一名精通黑暗巫术的施法者。她以狡诈的术士闻名，公然与恶魔势力勾结，以此贯彻自己的意志并保卫辛迪加的领地。想要进入她在激流堡的巢穴，不仅要面对那些切喉者和阴谋家，还要对抗她所驱使的邪恶实体。"}},faq={{q="玛瑞兹·考尔是谁？",a="玛瑞兹·考尔是辛迪加内部的一名高级特工兼顾问。她绝非普通的步兵，在这个犯罪组织中拥有相当大的影响力，并被公认为一名狡猾且危险的术士，以与恶魔势力勾结而闻名。",al={"玛瑞兹·考尔是谁","玛瑞兹·考尔背景","她是谁"}},{q="玛瑞兹·考尔在哪里？",a="玛瑞兹·考尔居住在阿拉希高地激流堡废墟中由辛迪加控制的区域。任何试图猎杀她的人都必须穿过重重盘踞的犯罪势力，才能找到她的圣所。",al={"哪里能找到玛瑞兹·考尔","玛瑞兹·考尔位置","玛瑞兹在哪里"}},{q="谁发布了针对玛瑞兹·考尔的赏金？",a="这份赏金是代表驻扎在阿拉希高地的联盟军事部队提供的。它由指挥避难谷地联盟据点的尼艾丝队长负责监管。",al={"谁发布了玛瑞兹·考尔的赏金","谁想要玛瑞兹·考尔死","谁支付赏金"}},{q="为什么悬赏她？",a="通缉她是由于她在辛迪加担任重要的领导角色，并积极在激流堡进行恶魔召唤仪式。她的存在对挣扎着收复这座荒废王国的联盟驻军构成了直接威胁。",al={"为什么要通缉玛瑞兹·考尔","为什么悬赏玛瑞兹·考尔","为什么要杀玛瑞兹·考尔"}},{q="玛瑞兹·考尔使用什么魔法？",a="玛瑞兹不仅仅是一名政治阴谋家；她是一位造诣深厚的术士，积极召唤并与恶魔进行交易。猎人们被特别提醒，在面对她和她的恶魔爪牙时务必保持极度谨慎。",al={"玛瑞兹·考尔为什么危险","玛瑞兹·考尔的能力","玛瑞兹·考尔强吗"}},{q="在哪里交付玛瑞兹·考尔的赏金任务？",a="玛瑞兹·考尔被杀后，必须将她的人头直接带给避难谷地的尼艾丝队长，那是阿拉希高地主要的联盟前哨站。",al={"在哪里交付玛瑞兹·考尔的赏金","尼艾丝队长在哪里","交付玛瑞兹的人头"}}},fp="18,312,31.423.0,25.373.0,18.260.0,28.217.0,36.186.0,34.240.0,39.224.0,47.150.0"}
P.entries["quest:685"] = {n="通缉：奥图和法库雷斯特",s="斯托姆加德民兵发出一份悬赏令，宣布通缉辛迪加在当地势力的首领法肯雷德领主及其致命的保镖奥托。消灭他们是对这个犯罪组织在阿拉希高地的立足点的一次重大打击。必须将他们死亡的证明交给避难谷地的尼艾丝队长。",h="斯托姆加德民兵发出一份悬赏令，宣布通缉辛迪加在当地势力的首领法肯雷德领主及其致命的保镖奥托。消灭他们是对这个犯罪组织在阿拉希高地的立足点的一次重大打击。必须将他们死亡的证明交给避难谷地的尼艾丝队长。",kw={"阿拉希高地","悬赏","尼艾丝队长","法肯雷德","奥托","避难谷地","斯托姆加德民兵","辛迪加"},ang={["faction:Alliance"]="法肯雷德领主和他的辛迪加特工威胁着斯托姆加德的残余势力，这份悬赏对于保卫避难谷地和收复高地至关重要。",["race:Human"]="对于斯托姆加德的守军来说，杀死辛迪加中那些背叛的人类贵族是一场为他们陨落的王国复仇的个人之战。"},sec={{t="绝望的悬赏",b="斯托姆加德民兵已经发出了一份正式悬赏，目标是阿拉希高地的两个关键人物：法肯雷德领主和他凶猛的保镖奥托。驻扎在避难谷地的斯托姆加德守军身陷困境，他们试图打破辛迪加对祖先领地的控制。猎手们必须将两个目标的头颅交给尼艾丝队长以领取赏金。"},{t="指挥官与执行者",b="法肯雷德领主是辛迪加协同向阿拉希高地进军的幕后主使。他的死对于联盟而言是一场至关重要的战略胜利，有望严重破坏该犯罪网络在这一地区的行动。在他身边的是奥托，一位极其危险的保镖，他的刀刃已经夺去了数十名斯托姆加德残存民兵的性命。"}},faq={{q="法肯雷德领主是谁？",a="法肯雷德领主是一位贵族兼指挥官，负责领导辛迪加在阿拉希高地的行动。他的存在组织了他们对破碎的斯托姆加德王国的投机性掠夺，因此清除他成为了当地人类民兵的首要目标。",al={"法肯雷德领主是谁","法肯雷德背景故事","法肯雷德是谁"}},{q="奥托是谁？",a="奥托是法肯雷德领主的致命私人保镖。虽然他不像他的主人那样是战略策划者，但他是一位凶猛的战士，曾在高地负责杀害了数十名斯托姆加德守军。",al={"奥托是谁","法肯雷德的保镖","奥托 辛迪加"}},{q="为什么斯托姆加德民兵要悬赏他们？",a="斯托姆加德民兵悬赏他们是为了削弱辛迪加在阿拉希高地的领导层。消灭法肯雷德可以瓦解他们的区域指挥结构，而干掉奥托则可以消除一个屠杀了许多联盟战士的致命威胁。",al={"为什么悬赏法肯雷德","为什么要杀死奥托和法肯雷德","斯托姆加德悬赏"}},{q="谁为奥托和法肯雷德提供奖励？",a="法肯雷德领主和奥托的赏金由尼艾丝队长负责发放，她是驻扎在阿拉希高地避难谷地的一名斯托姆加德民兵军官。",al={"在哪里交奥托和法肯雷德的任务","尼艾丝队长是谁","法肯雷德悬赏上交"}},{q="辛迪加在阿拉希高地做什么？",a="辛迪加由没落的奥特兰克贵族和亡命之徒组成，他们希望在洛丹伦北部崩溃之际攫取土地和财富。在阿拉希高地，他们已经进入了斯托姆加德的废墟，试图从幸存的守军手中夺取控制权。",al={"辛迪加在阿拉希做什么","辛迪加在阿拉希的角色"}},{q="领取赏金需要什么证明？",a="为了领取奖励，猎手们必须将法肯雷德领主和奥托被割下的头颅直接带给避难谷地的尼艾丝队长，作为他们死亡的确凿证据。",al={"在哪里上交奥托的头颅","悬赏证明"}}},fp="28,329,18.373.0,22.393.0,24.255.0,12.206.0,55.267.0,47.168.0,52.255.0,43.171.0"}
P.entries["quest:686"] = {n="国王的礼物",s="“国王的敬意”是联盟的一项任务，由铁炉堡High Seat的国王麦格尼·铜须发放。国王被萨拉·巴鲁的悲痛深深打动，她的丈夫萨利在保卫萨多尔大桥时牺牲。国王决定用一座不朽的丰碑来纪念这位阵亡的士兵。他派遣一位冒险者去向大石匠玛布勒斯坦传达他的皇家委托。",h="“国王的敬意”是联盟的一项任务，由铁炉堡High...",kw={"铁炉堡","magni bronzebeard","玛布勒斯坦","纪念碑","萨拉·巴鲁","萨利·巴鲁","萨多尔大桥"},ang={["faction:Alliance"]="萨多尔大桥的阵亡者们为守卫卡兹莫丹与北方王国之间至关重要的补给线而献出了生命。",["race:Dwarf"]="这项任务展现了麦格尼国王对他族人的关怀，表明即使是地位最低微的矮人步兵，王座也从未将他遗忘。"},sec={{t="君主的重担",b="当国王麦格尼·铜须收到萨拉·巴鲁的恳求时，他并没有忽视这位悲伤的遗孀。虽然他知道平民可能难以理解战争中残酷的必要性，但每一位为联盟旗帜而战的士兵的牺牲，都沉重地压在他的良心上。尽管无法改变前线阵亡的冷酷事实，麦格尼还是决定确保萨利·巴鲁的牺牲永远不会被遗忘。"},{t="石匠的凿子",b="国王并没有只说些空洞的客套话，而是决定竖立一座实体纪念碑来纪念萨利。他任命冒险者作为他皇家意旨的执行者，派遣他们前往铁炉堡的各处去与大石匠玛布勒斯坦商议。身负国王的私人委托，这位石匠大师准备将一位阵亡捍卫者的记忆刻入岩石之中。"}},faq={{q="谁是萨利·巴鲁？",a="萨利·巴鲁是一名矮人士兵，在萨多尔大桥的防御战中为联盟献出了生命。他的遗孀萨拉·巴鲁在得知他的死讯后，向国王麦格尼·铜须请愿。",al={"谁是萨利","萨利·巴鲁背景故事","谁阵亡了"}},{q="为什么麦格尼国王要委托建造纪念碑？",a="国王麦格尼承载着联盟持续不断的斗争中每一位逝去矮人的沉重负担。虽然他无法让萨利回到遗孀身边，但他希望用一座不朽的皇家纪念碑来缅怀这位士兵的勇气。",al={"为什么建造纪念碑","麦格尼的动机","国王的敬意目的"}},{q="谁是大石匠玛布勒斯坦？",a="大石匠玛布勒斯坦是铁炉堡的石工大师，负责执行城内主要的市政和皇家建筑项目。麦格尼国王依靠他来雕刻萨利·巴鲁的纪念碑。",al={"谁是玛布勒斯坦","大石匠职责"}},{q="这个任务发生在哪里？",a="该任务完全在铁炉堡内进行，始于High Seat的国王麦格尼·铜须，并导向城市中其他地点的大石匠玛布勒斯坦。",al={"任务地点在哪里","任务位置"}},{q="这个任务的前置条件是什么？",a="在接受此任务之前，冒险者必须完成“萨拉·巴鲁的恳求”，将这位遗孀感人至深的信件直接送达国王麦格尼·铜须手中。",al={"前置条件","前序任务"}},{q="这座纪念碑只是为了纪念萨利·巴鲁吗？",a="虽然该纪念碑是专门以萨利·巴鲁的名义委托建造以慰藉其遗孀萨拉，但这份敬意也象征着国王对每一位为服务联盟而牺牲的矮人战士的崇敬。",al={"纪念谁","是否只为了萨利"}}},fp="16,186,20.349.0,18.299.0,21.193.0,42.202.0,30.193.0,33.148.0,29.125.0,39.146.0"}
P.entries["quest:687"] = {n="迷失者塞尔杜林",s="一名暮光之锤成员请求你找到迷失者塞尔杜林，他曾是该组织的一员，后来丧失了理智，并带着密斯莱尔卷轴逃走了。传言说他在荒芜之地。",h="一名暮光之锤成员请求你找到迷失者塞尔杜林，他曾是该组织的一员，后来丧失了理智，并带着密斯莱尔卷轴逃走了。传言说他在荒芜之地。",kw={"荒芜之地","葛利·硬骨","密斯莱尔","密斯莱尔卷轴","塞尔杜林","迷失者塞尔杜林","暮光之锤","萨鲁克"},sec={{t="窃取卷轴之人",b="塞尔杜林曾属于暮光之锤，直到他精神错乱，背弃了组织的教条。他在逃跑时带走了密斯莱尔卷轴。他留下的同伙没能追上他。"},{t="关于荒芜之地的传言",b="组织听说塞尔杜林藏身于荒芜之地，变得疯疯癫癫。密斯莱尔卷轴对于那位女士的回归至关重要，要得到它，你必须先找到那个拿走卷轴的人。"}},faq={{q="迷失者塞尔杜林是谁？",a="暮光之锤的前成员，他丧失了理智，摒弃了组织的教条，并带着密斯莱尔卷轴逃走了。",al={"塞尔杜林背景故事","谁是塞尔杜林","塞尔杜林剧情"}},{q="暮光之锤为什么要找他？",a="他带着密斯莱尔卷轴逃跑了，该组织声称必须找到这份卷轴才能让那位女士回归。",al={"为什么要找塞尔杜林","为什么邪教徒要找塞尔杜林"}},{q="塞尔杜林离开组织后逃到了哪里？",a="组织只掌握了一些传言，称他藏身于荒芜之地。",al={"塞尔杜林在哪里","塞尔杜林位置剧情"}},{q="这个任务之前的前置任务是什么？",a="它是《密斯莱尔的盟友》的后续。",al={"塞尔杜林前置任务","迷失者塞尔杜林的前提条件"}}},fp="18,185,28.215.0,22.172.0,26.128.0,45.97.0,49.59.0,39.28.0"}
P.entries["quest:688"] = {n="密斯莱尔的盟友",s="迈兹拉通过基石向你传话，宣称自己已经重获自由，但目前必须躲避囚禁她的人。她让你去落锤镇找萨鲁克，他说知道如何召唤她。",h="迈兹拉通过基石向你传话，宣称自己已经重获自由，但目前必须躲避囚禁她的人。她让你去落锤镇找萨鲁克，他说知道如何召唤她。",kw={"阿拉希高地","巨人","落锤镇","基石","迈兹拉","萨鲁克"},sec={{t="重获自由，但被迫隐藏",b="迈兹拉呼喊着她终于自由了。现在，她必须在囚禁她的人看不见的地方积蓄力量，因为如果现在与他们对抗，他们会再次击败并将她囚禁。她发誓，终有一天她会去面对那些囚禁她的巨人，让他们为囚禁她的行为感到后悔。"},{t="落锤镇的萨鲁克",b="迈兹拉称赞你是高贵的盟友，并表示日后还会需要你的帮助。当她准备好时，她会让你把她召唤到地面上来。现在，她让你去落锤镇找萨鲁克，因为他知道该如何做到这一点。"}},faq={{q="是谁让你去找萨鲁克的？",a="迈兹拉本人通过基石向你传话，让你去落锤镇找萨鲁克。",al={"谁给予了迈兹拉的盟友任务","迈兹拉的盟友任务发布者","谁通过基石传话"}},{q="为什么迈兹拉要躲藏起来？",a="她说如果现在面对那些囚禁她的人，他们会再次将她制服并囚禁，所以她在积蓄力量期间必须躲藏起来。",al={"为什么迈兹拉不战斗","为什么迈兹拉很虚弱","为什么迈兹拉要躲藏"}},{q="在哪里可以找到萨鲁克？",a="在落锤镇。",al={"萨鲁克的位置","萨鲁克在哪里","寻找萨鲁克"}},{q="萨鲁克在迈兹拉的计划中扮演什么角色？",a="迈兹拉说他知道如何将她召唤出来。",al={"为什么要找萨鲁克谈话","萨鲁克知道什么","萨鲁克的目的"}}},fp="16,175,15.274.0,19.217.0,23.85.0,22.123.0,25.14.0,38.46.0"}
P.entries["quest:689"] = {n="国王的礼物",s="国王麦格尼·铜须委托制作了一座纪念萨利·巴鲁的纪念碑，这位矮人战士在保卫萨多尔大桥时英勇牺牲。为了以长久的尊严纪念这位阵亡的战士，大石匠玛布勒斯坦派遣旅行者前往希尔斯布莱德取回纯净的奥特兰克花岗岩。",h="国王麦格尼·铜须委托制作了一座纪念萨利·巴鲁的纪念碑，这位矮人战士在保卫萨多尔大桥时英勇牺牲。为了以长久的尊严纪念这位阵亡的战士，大石匠玛布勒斯坦派遣旅行者前往希尔斯布莱德取回纯净的奥特兰克花岗岩。",kw={"奥特兰克花岗岩","达隆山","铁炉堡","magni bronzebeard","玛布勒斯坦","石匠","萨利·巴鲁","萨多尔大桥"},ang={["faction:Alliance"]="从希尔斯布莱德获取材料不仅加强了联盟在分裂的北方地区的存在感，也纪念了一位为共同事业献出生命的普通士兵。",["profession:Mining"]="矿工们理解玛布勒斯坦挑剔的眼光；奥特兰克花岗岩坚硬、顽固的矿脉需要经验丰富的工匠才能在不破碎的情况下完整开采出来。",["race:Dwarf"]="纪念萨利·巴鲁触动了矮人文化的核心，在这里，石雕工艺、尚武牺牲以及对铜须国王的坚定忠诚是紧密交织在一起的。"},sec={{t="皇家委托",b="当国王麦格尼·铜须认为阵亡士兵萨利·巴鲁值得一座永恒的纪念碑时，这项任务便直接落到了铁炉堡最优秀的工匠，大石匠玛布勒斯坦的肩上。巴鲁在萨多尔大桥的灾难中丧生，这座连接矮人领地与北方王国的重要枢纽曾遭受黑铁矮人破坏者的残酷袭击。对于玛布勒斯坦来说，完成国王的皇家法令意味着创作一座能够经受住时间和战争考验的雕塑，确保矮人的牺牲在Great Forge中既不会被忽视，也不会被遗忘。"},{t="北方的岩石",b="一位矮人石匠大师绝不会满足于用普通的采石场岩石来完成国王的工程。玛布勒斯坦坚持认为，唯有奥特兰克花岗岩才能捕捉到萨利·巴鲁的神韵，这种致密、坚韧的岩石因其耐用性和纯净的质地而备受推崇。挑战在于获取它：最好的矿床位于希尔斯布莱德充满争议的丘陵地带中的达隆山附近。深入这片动荡的北方地区虽然危险，但矮人的石雕工艺需要配得上他们所纪念的英雄主义的材料。"}},faq={{q="萨利·巴鲁是谁？",a="萨利·巴鲁是一名联盟士兵，他在萨多尔大桥遭受毁灭性破坏时为了保卫它而牺牲。国王麦格尼·铜须被其遗孀萨拉·巴鲁的一封悲痛的信所打动，下令竖立一座永久性的雕像以示纪念。",al={"萨利·巴鲁","萨利·巴鲁是谁","萨利·巴鲁背景故事"}},{q="大石匠玛布勒斯坦是谁？",a="大石匠玛布勒斯坦是铁炉堡的雕塑与石工大师。他在城中的平民区工作，负责处理皇家委托，并以只使用最优质的区域性石材而引以为傲。",al={"大石匠玛布勒斯坦","玛布勒斯坦铁炉堡","谁是玛布勒斯坦"}},{q="为什么需要奥特兰克花岗岩？",a="奥特兰克花岗岩因其卓越的密度、细腻的纹理和抗侵蚀能力而在东部王国广受赞誉。玛布勒斯坦坚持认为，唯有这种品质的石材才配得上流传后世的皇家贡品。",al={"为什么选择奥特兰克花岗岩","奥特兰克花岗岩用途","什么是奥特兰克花岗岩"}},{q="达隆山在哪里？",a="达隆山是希尔斯布莱德丘陵北部的一片丘陵地区，位于海岬下方，靠近奥特兰克边境，在那里的洞穴中可以找到奥特兰克花岗岩。",al={"达隆山在哪里","达隆山位置","寻找达隆山"}},{q="萨多尔大桥发生了什么？",a="萨多尔大桥是连接湿地与阿拉希高地的巨大桥梁，遭受了黑铁矮人破坏者的袭击，他们安放炸药切断了联盟的补给路线，导致许多守卫丧生。",al={"萨多尔大桥悲剧","萨多尔大桥灾难","萨多尔大桥发生了什么"}},{q="把花岗岩带给玛布勒斯坦后会发生什么？",a="一旦提供了奥特兰克花岗岩，玛布勒斯坦就会完成纪念碑，并让你向国王麦格尼报告工程已经完工。",al={"上交花岗岩后","玛布勒斯坦雕像进度"}}},fp="16,196,18.441.0,18.351.0,20.224.0,30.184.0,30.206.0,21.139.0,34.192.0,54.125.0"}
P.entries["quest:69"] = {n="斯塔文的传说",s="这项任务标志着搜寻难以捉摸的Stalvan Mistmantle一事的关键转折，引领调查者走出暮色森林的阴霾，回向王国的腹地。在夜色镇的城镇登记册中发现的一条匆忙且被划掉的记录指向了河流对岸的闪金镇。顺着这条线索前往繁忙的Lion's Pride Inn是揭开这位神秘导师去向的下一步。",h="这项任务标志着搜寻难以捉摸的Stalvan...",kw={"书记员达尔塔","夜色镇","暮色森林","艾尔文森林","闪金镇","旅店老板法雷","lion's pride inn","stalvan"},ang={["faction:Alliance"]="揭开南部联盟领地的地方历史和尘封线索，需要往返于像夜色镇这样的边境哨所和像闪金镇这样的核心村庄之间。",["race:Human"]="重走Stalvan的足迹会带你穿越暴风城王国的中心地带，将暮色森林闹鬼的边境与艾尔文森林熟悉的舒适感联系起来。"},sec={{t="账簿中的线索",b="在查阅夜色镇的记录时，书记员达尔塔发现了城镇登记册中的一处疏漏。在Stalvan Mistmantle之前的一条记录下方，隐藏着第二个目的地，书写匆忙且部分被划掉，仿佛有人改变了主意或是刻意想要掩盖其行踪。这条记录表明Stalvan计划向西北方向前往艾尔文森林，具体目标是Lion's Pride Inn。"},{t="进入艾尔文森林",b="离开暮色森林阴暗的树林，前往闪金镇阳光明媚的道路，两者形成了鲜明的对比，但Stalvan过去的阴影甚至笼罩到了这里。Lion's Pride Inn是艾尔文森林繁华的十字路口，迎接各地的旅行者、商人和士兵。旅店老板法雷负责管理这间忙碌的旅店，他是打听一位寻求住宿的受过教育的流浪者的最佳人选。"}},faq={{q="为什么线索指向闪金镇？",a="书记员达尔塔在夜色镇登记册中Stalvan最初的记录下方发现了第二个、部分被划掉的地址。它清楚地表明他计划前往闪金镇的Lion's Pride Inn。",al={"为什么去闪金镇","为什么要前往闪金镇","stalvan在闪金镇"}},{q="谁是书记员达尔塔？",a="书记员达尔塔是驻守在夜色镇市政厅的记录员。他负责维护当地的登记册，并协助发掘有关过去居民的历史文件。",al={"达尔塔","达尔塔是谁"}},{q="我在Lion's Pride Inn应该和谁谈话？",a="你需要直接和旅店老板法雷谈话，他负责管理Lion's Pride Inn，并记录着往来闪金镇的旅行者和顾客。",al={"找谁谈话","lion's pride inn联系人","闪金镇旅店老板"}},{q="为什么登记册上的记录被划掉了？",a="账簿上的条目只是被部分擦除，这表明Stalvan在离开暮色森林时，有人仓促或刻意地试图隐瞒他前往艾尔文森林的路线。",al={"被划掉的笔记","为什么被划掉"}},{q="这个任务涉及战斗吗？",a="不。这一阶段的调查纯粹是旅行和询问，让你安全地从夜色镇的市政厅前往闪金镇的旅店。",al={"有战斗吗","需要战斗吗"}},{q="什么是Lion's Pride Inn？",a="Lion's Pride Inn是艾尔文森林闪金镇的中心枢纽。它是往来于暴风城、西部荒野和暮色森林的旅行者们众所周知的休憩之所。",al={"lion's pride inn","闪金镇旅店"}}},fp="21,89,20.281.0,20.307.0,37.167.0,20.140.0,42.126.0,48.140.0,35.92.0,29.174.0"}
P.entries["quest:690"] = {n="马林的要求",s="“马林的请求”是暴风城Mage Quarter的大法师马林向联盟成员发布的一项任务。马林请求经验丰富的冒险者前往遥远北方的阿拉希高地避难谷地，那里的一支探险队正试图寻回激流堡陷落时遗失的珍贵魔法圣物。",h="“马林的请求”是暴风城Mage Quarter的大法师马林向联盟成员发布的一项任务。马林请求经验丰富的冒险者前往遥远北方的阿拉希高地避难谷地，那里的一支探险队正试图寻回激流堡陷落时遗失的珍贵魔法圣物。",kw={"阿拉希高地","马林","避难谷地","斯奎尔图","暴风城","激流堡","阿拉索之塔","特雷莱恩","奥术圣所"},ang={["class:Mage"]="对于造访奥术圣所的法师们来说，协助马林直接保护了与阿拉索法师遗产息息相关的珍贵奥术研究和圣物。",["faction:Alliance"]="避难谷地代表了联盟在阿拉希脆弱的残余立足点，因此从暴风城派出的任何增援对于维持该地区而言都至关重要。",["race:Human"]="激流堡曾是人类文明的摇篮；协助找回其珍宝对于阿拉索的儿女而言，不仅关乎荣誉，更关乎历史的存续。"},sec={{t="大师遗失的物品",b="驻扎在暴风城法师区的奥术圣所的大法师马林，是代表他的前导师大法师特雷莱恩行事。当尚武的王国激流堡陷入混乱与毁灭时，特雷莱恩曾在阿拉索之塔进行了绝望的坚守。随着城市陷落于敌手，特雷莱恩被迫放弃阵地，并遗留下了强大的附魔财物。马林急于在敌手染指之前取回这些遗失的文物，于是指派有能力的雇佣兵向北进发，去增援他在那里的行动人员。"},{t="避难谷地举步维艰的前哨站",b="寻找特雷莱恩圣物的道路穿过了避难谷地，这是阿拉希高地中部激流堡忠诚派的堡垒，但现在正处于困境之中。马林在防守者中的主要联络人是矮人斯奎尔图。然而，避难谷地正受到周围辛迪加暴徒、枯木巨魔和巨石食人魔的严密挤压。抵达的旅行者很快就会发现，斯奎尔图和前哨站的守军已疲于奔命，如果没有即时的援助，根本无法给予他们热情的接待。"}},faq={{q="大法师马林是谁？",a="大法师马林是一位资深的人类法师，居住在暴风城的奥术圣所。他曾是大法师特雷莱恩的学徒，如今正在暴风城协调各项工作，以寻回他这位前任导师的魔法研究成果。",al={"大法师马林","马林是谁","马林 暴风城"}},{q="为什么马林需要阿拉希的帮助？",a="激流堡近期在围攻下陷落，迫使大法师特雷莱恩逃离了阿拉索之塔。马林在当地的代理人正努力寻回特雷莱恩遗弃的魔法圣物，但他们已不堪重负，急需增援。",al={"为什么去阿拉希","马林的任务目的","为什么是阿拉希高地"}},{q="斯奎尔图在哪里？",a="斯奎尔图是一位驻扎在避难谷地的矮人斥候，该避难谷地是位于阿拉希高地中部主要贸易道路沿线的坚固联盟营地。",al={"寻找斯奎尔图","斯奎尔图位置","避难谷地在哪里"}},{q="阿拉索之塔发生了什么？",a="阿拉索之塔曾是激流堡内的一座奥术堡垒。在王国覆灭期间，大法师特雷莱恩曾试图坚守该塔以抵御入侵的辛迪加盗贼和巨石食人魔，但防御终告失败，他被迫逃离。",al={"阿拉索之塔陷落","激流堡发生了什么","特雷莱恩之塔"}},{q="向斯奎尔图报到后会发生什么？",a="斯奎尔图在初见时会显得不堪重负且表现冷淡，他会立即指引你前往避难谷地的同伴处，开始寻回特雷莱恩散落的财物。",al={"马林任务后续","马林之后的下一个任务","斯奎尔图的下一个任务"}},{q="大法师特雷莱恩是谁？",a="大法师特雷莱恩是激流堡的一位杰出法师，也是大法师马林的导师。在王国陷落前，他是阿拉索首都的主要保卫者之一。",al={"大法师特雷莱恩","特雷莱恩是谁","特雷莱恩 激流堡"}}},fp="15,253,26.467.0,37.407.0,22.199.0,35.198.0,25.136.0,38.207.0,40.154.0,24.154.0"}
P.entries["quest:691"] = {n="证明实力",s="在避难谷地，学徒克里汀正在寻找枯木巨魔的獠牙、医药包和一把暗影猎手的刀，这些都是大法师马林的施法材料，大法师派他和斯奎尔图来收集这些东西。他请求你去阿拉希东南部，在枯木巨魔身上寻找它们。",h="在避难谷地，学徒克里汀正在寻找枯木巨魔的獠牙、医药包和一把暗影猎手的刀，这些都是大法师马林的施法材料，大法师派他和斯奎尔图来收集这些东西。他请求你去阿拉希东南部，在枯木巨魔身上寻找它们。",kw={"学徒克里汀","阿拉希高地","大法师马林","医药包","避难谷地","暗影猎手的刀","斯奎尔图","枯木巨魔","枯木獠牙"},sec={{t="马林的试剂",b="大法师马林派克里汀和斯奎尔图前往阿拉希收集试剂，在见到你之前，克里汀完全不知道该怎么收集它们。他需要十个枯木獠牙、四个医药包和一把暗影猎手的刀。枯木巨魔住在阿拉希的东南部。"},{t="枯木巨魔携带的物品",b="根据克里汀的研究，任何枯木巨魔都应该有獠牙，而巫医则携带着医药包。那把刀属于最强大的暗影猎手，是他们在完成成人礼后得到的。只有通过战斗，才能知道他们中谁持有它。"}},faq={{q="学徒克里汀在为谁工作？",a="大法师马林派克里汀和斯奎尔图前往阿拉希，为他收集试剂。",al={"谁派克里汀来的","克里汀的导师","克里汀为什么在阿拉希"}},{q="枯木巨魔住在哪里？",a="在阿拉希的东南部，那里是枯木巨魔的家园。",al={"枯木巨魔位置","哪里能找到枯木巨魔","枯木村位置"}},{q="哪些巨魔携带医药包？",a="克里汀的研究表明，是枯木巫医携带着医药包，而任何枯木巨魔应该都有獠牙。",al={"医药包来源","谁有医药包","枯木医药包"}},{q="如何获得暗影猎手的刀？",a="最强大的枯木暗影猎手应该有这把刀，这是他们在成人礼后获得的武器。至于他们之中谁持有它，只有通过战斗才能揭晓。",al={"暗影猎手的刀位置","谁掉落暗影猎手的刀","成人礼之刀"}}},fp="24,263,16.278.0,25.264.0,37.77.0,40.72.0,40.131.0,40.159.0"}
P.entries["quest:692"] = {n="遗失的卷轴碎片",s="迷失者塞尔杜林对密斯莱尔卷轴感到十分惊恐。它的魔法可能会把密斯莱尔拖出地面，但如果她已经重获自由，这张卷轴可能就是再次束缚她的唯一办法。狂怒的元素生物已经将其撕碎，并为这些残片争斗不休，而你被派去收集它们。",h="迷失者塞尔杜林对密斯莱尔卷轴感到十分惊恐。它的魔法可能会把密斯莱尔拖出地面，但如果她已经重获自由，这张卷轴可能就是再次束缚她的唯一办法。狂怒的元素生物已经将其撕碎，并为这些残片争斗不休，而你被派去收集它们。",kw={"荒芜之地","揉皱的卷轴碎片","元素生物","密斯莱尔","密斯莱尔卷轴","烧焦的卷轴碎片","迷失者塞尔杜林","撕裂的卷轴碎片"},sec={{t="危险的羊皮纸",b="当听到密斯莱尔卷轴时，迷失者塞尔杜林显得忧心忡忡，担心它的魔法会将密斯莱尔引出地面。随后他又改变了主意：如果她已经逃脱，或者正在积蓄力量准备发动攻击，那么这张卷轴正是你需要用来再次禁锢她的东西。"},{t="元素撕裂",b="卷轴已不再完整。愤怒的元素生物夺走了它，将其撕成了碎片，现在正为这些残片而争斗。你需要找回三片残卷：一片被撕裂的、一片被揉皱的、还有一片被烧焦的，塞尔杜林打算尝试修复它们。这些窃贼就在塞尔杜林身后的山丘上游荡。"}},faq={{q="是谁派你去收集卷轴碎片的？",a="迷失者塞尔杜林请求你带回被毁坏的卷轴碎片。",al={"任务发布者","谁开启了迷失的碎片任务","塞尔杜林任务"}},{q="密斯莱尔卷轴有什么用？",a="塞尔杜林说它的魔法可能会把密斯莱尔引出地面。塞尔杜林还认为，如果她已经重获自由，这就是你需要用来再次禁锢她的东西。",al={"卷轴的作用","密斯莱尔卷轴传说","为什么寻找卷轴碎片"}},{q="卷轴碎片在哪里？",a="狂怒的元素生物带走了卷轴，将其撕碎并为残片争斗。它们就在塞尔杜林身后的山丘上。",al={"谁持有这些碎片","到哪里寻找卷轴碎片","卷轴碎片位置"}},{q="这个任务的前序任务是什么？",a="它是紧接着你之前与迷失者塞尔杜林的交易而来的。",al={"前序任务","迷失的碎片的先决条件"}}},fp="18,284,21.279.0,20.262.0,46.77.0,45.159.0,31.122.0,29.57.0"}
P.entries["quest:6921"] = {n="废墟之间",s="受到佐拉姆加前哨站的耶努萨克雷委托，部落的冒险者深入被淹没的黑暗深渊神庙，试图寻回一枚深渊之核。大地之环正寻求这件圣物，以揭露入侵此地的暮光之锤教派所策划的黑暗元素阴谋。",h="受到佐拉姆加前哨站的耶努萨克雷委托，部落的冒险者深入被淹没的黑暗深渊神庙，试图寻回一枚深渊之核。大地之环正寻求这件圣物，以揭露入侵此地的暮光之锤教派所策划的黑暗元素阴谋。",kw={"amongst the ruins","灰谷","黑暗深渊","大地之环","深渊之核","深渊之石","耶努萨克雷","moonshrine ruins","暮光之锤","佐拉姆加前哨站"},ang={["class:Shaman"]="取回深渊之核直接服务于大地之环的目标，即保护水元素与土元素之灵免受暮光之锤的胁迫。",["faction:Horde"]="通过清理黑暗深渊内的威胁，你可以保卫佐拉姆加前哨站，并稳固部落在灰谷海岸那片充满争端的立足点。",["race:Troll"]="帮助耶努萨克雷也是在帮助一位同胞暗矛巨魔，他架起了部落与大地之环元素守护者之间的桥梁。"},sec={{t="深处的威胁",b="古老的暗夜精灵神庙黑暗深渊，曾经是供奉艾露恩的圣地，如今已沦为邪恶势力的据点。在它那被水淹没的通道深处，暮光之锤的邪教徒们建立了一个要塞。驻扎在灰谷佐拉姆加前哨站那风蚀海岸上的暗矛巨魔萨满耶努萨克雷，怀着日益增长的忧虑注视着这种腐化的蔓延，他意识到该教派企图奴役当地的元素来对抗这片土地及其守卫者。"},{t="深渊之石",b="为了对抗该教派的图谋，耶努萨克雷指派部落的勇士前往Moonshrine Ruins，从水下的深渊之石中取回一枚深渊之核。当技艺精湛的萨满祭司正确解读它时，深渊之核便会展现出一份关于元素潮流与扰动的详尽记录。大地之环希望借助这件神器，看穿暮光之锤的行动，并保护该地区免遭元素灾难的侵袭。"}},faq={{q="谁发布了“Amidst the Ruins”这个任务？",a="该任务由耶努萨克雷发布，他是大地之环的一位巨魔代表，驻扎在灰谷西部的佐拉姆海岸的佐拉姆加前哨站。",al={"任务发布者","任务领取地点","谁发布amongst the ruins任务"}},{q="什么是深渊之核？",a="深渊之核是一件特殊的远古神器，藏在遗迹中被水淹没的深渊之石内。萨满祭司读取它时，能获得一份关于元素活动的完整历史记录，揭示当地的元素是如何受到胁迫与操纵的。",al={"什么是深渊之核","深渊之石的作用","深渊之核有什么用"}},{q="大地之环为何关心黑暗深渊？",a="大地之环致力于在自然元素之间寻求平衡。那些占据了被淹没遗迹的暮光之锤邪教徒们，正在积极地腐化并胁迫元素为他们的黑暗目的服务，这威胁到了整个地区的稳定性。",al={"大地之环的目的","大地之环为何关心此事","黑暗深渊的邪教徒"}},{q="深渊之石位于何处？",a="深渊之石沉没在黑暗深渊内的Moonshrine Ruins的水中，探险者需要潜入水面之下才能取回深渊之核。",al={"深渊之石在哪里","深渊之核位置","moonshrine ruins深渊之核"}},{q="联盟玩家可以接取这个任务吗？",a="不行。该任务仅限部落接取，因为耶努萨克雷是在部落的佐拉姆加前哨站开展工作，并在履行他大地之环职责的同时，协助部落在灰谷的战略部署。",al={"是否部落专属","联盟版本","联盟能否进行amongst the ruins任务"}},{q="是什么组织占据了黑暗深渊？",a="这座洞穴神庙群已经被暮光之锤占领，这是一个致力于侍奉邪恶的上古之神实体，并将元素扭曲至灾难性目的的末日教派。",al={"谁在黑暗深渊中","黑暗深渊的敌人","暮光之锤黑暗深渊"}}},fp="17,202,20.349.0,16.359.0,38.141.0,22.202.0,58.188.0,34.150.0,37.186.0,42.139.0"}
P.entries["quest:6922"] = {n="阿奎尼斯男爵",s="当冒险者在黑暗深渊中击败水元素阿奎尼斯男爵后，可以获得一个装有污浊、腐臭液体的奇怪的水球。将它交给大地之环的耶努萨克雷，这件神器将成为灰谷下方蔓延的元素腐化的关键证据。耶努萨克雷认为，这件物品将证明是什么腐化了男爵，如果这确实是潜伏在沉没遗迹中的暮光之锤邪教徒所为，他一点也不会感到惊讶。",h="当冒险者在黑暗深渊中击败水元素阿奎尼斯男爵后，可以获得一个装有污浊、腐臭液体的奇怪的水球。将它交给大地之环的耶努萨克雷，这件神器将成为灰谷下方蔓延的元素腐化的关键证据。耶努萨克雷认为，这件物品将证明是什么腐化了男爵，如果...",kw={"灰谷","阿奎尼斯男爵","黑暗深渊","大地之环","元素腐化","耶努萨克雷","奇怪的水球","暮光之锤","佐拉姆海岸"},ang={["class:Shaman"]="大地之环将元素之灵的腐化视为对自然秩序的严重践踏。调查阿奎尼斯男爵被污染的状态对于恢复元素平衡至关重要。",["faction:Horde"]="耶努萨克雷与佐拉姆加前哨站的部落侦察兵协同工作，寻找勇敢的勇士来净化潜伏在灰谷海岸下方的腐化水域。"},sec={{t="一颗腐化的心",b="阿奎尼斯男爵并非普通的水之灵，而是在黑暗深渊被淹没的洞穴中被邪恶法术所腐化的强大元素。当这个元素被摧毁时，它会留下一颗奇怪的水球——一个坚不可摧的球体，里面盛着晃动的腐臭液体，似乎正是这种液体维持并扭曲了该生物的本质。该物体不受物理伤害，其中蕴含的能量让那些与元素平衡调和的人感到深深的不安。"},{t="大地之环的研究",b="驻扎在佐拉姆海岸的大地之环萨满耶努萨克雷一眼就认出这件神器是遭到非自然干预的证据。他和他的组织早就怀疑阿奎尼斯男爵成了黑暗势力的猎物，并将矛头直接指向了占据沉没的神庙的暮光之锤邪教徒。通过研究这个水球，耶努萨克雷不仅希望能证实该邪教的罪责，还希望能发现他们究竟使用了什么黑暗手段来奴役和扭曲艾泽拉斯的元素之灵。"}},faq={{q="阿奎尼斯男爵是谁？",a="阿奎尼斯男爵是栖息在黑暗深渊地下水域中的强大水元素。阿奎尼斯并没有自由游荡，而是被居住在神庙废墟中的黑暗修行者所腐化并束缚。",al={"阿奎尼斯是谁","阿奎尼斯首领","阿奎尼斯男爵背景故事"}},{q="奇怪的水球是什么？",a="奇怪的水球是击败阿奎尼斯男爵后留下的坚不可摧的球体。里面晃动着一种污浊、腐臭的液体，它是导致该元素处于腐化状态的污染能量来源。",al={"水球","奇怪的水球","阿奎尼斯任务物品"}},{q="耶努萨克雷为什么想要这个水球？",a="作为大地之环的成员，耶努萨克雷负责监测整个灰谷的元素异常。他研究这个水球是为了确认暮光之锤是否是造成腐化的幕后黑手，并揭开他们用来扭曲元素之灵的仪式真相。",al={"为什么要交给耶努萨克雷","耶努萨克雷的目的"}},{q="是谁腐化了阿奎尼斯男爵？",a="主要嫌疑人是盘踞在黑暗深渊深处的暮光之锤邪教徒。他们在神庙中的存在与亵渎神灵以及与非自然生物进行黑暗沟通的行动相吻合。",al={"谁腐化了阿奎尼斯","阿奎尼斯与暮光之锤","黑暗深渊的邪教徒"}},{q="耶努萨克雷在哪里？",a="耶努萨克雷是一位驻扎在灰谷西北海岸佐拉姆海岸的大地之环萨满，靠近黑暗深渊洞穴系统的入口。",al={"耶努萨克雷在哪里","交还阿奎尼斯任务","在哪里上交水球"}},{q="交还这个任务后会发生什么？",a="上交这个水球会直接引出对该地区元素危机的进一步调查，促使冒险者继续协助大地之环对抗不断增长的灾祸。",al={"下一个任务","元素危机"}}},fp="13,236,17.357.0,27.395.1,22.171.0,32.194.0,39.240.0,46.185.0,32.157.0,39.157.0"}
P.entries["quest:693"] = {n="特雷莱恩的符咒魔杖",s="位于避难谷地的斯奎尔图已经查明了特雷莱恩的第一件遗物在什么地方。科格雷什在石拳大厅拿到了特雷莱恩的符咒魔杖，斯奎尔图想要你把它取回来。",h="位于避难谷地的斯奎尔图已经查明了特雷莱恩的第一件遗物在什么地方。科格雷什在石拳大厅拿到了特雷莱恩的符咒魔杖，斯奎尔图想要你把它取回来。",kw={"阿拉希高地","石拳大厅","科格雷什","避难谷地","斯奎尔图","激流堡","萨多尔大桥","特雷莱恩","符咒魔杖","食人魔与魔杖"},sec={{t="食人魔与魔杖",b="在你为学徒克里汀完成工作后，斯奎尔图已经找到了特雷莱恩的第一件遗物的下落。科格雷什在石拳大厅持有这件遗物，并一直用它向自己的同类发射冰霜冲击，以迫使他们服从。斯奎尔图认为这个食人魔一定快要弄清楚这根魔杖的所有能力了。石拳大厅位于避难谷地以南，萨多尔大桥以东。"},{t="斯奎尔图的清单",b="当你回来时，斯奎尔图根据他的清单计算了一下，这根魔杖是第一件，还有三件没找回。另外三件都在激流堡。"}},faq={{q="谁发布了“食人魔与魔杖”这个任务？",a="阿拉希高地避难谷地的斯奎尔图。",al={"食人魔与魔杖任务发布者","谁开启食人魔与魔杖","哪里接取食人魔与魔杖"}},{q="科格雷什在哪里？",a="科格雷什在石拳大厅，它位于避难谷地以南，萨多尔大桥以东。",al={"科格雷什在哪里","科格雷什位置","找到科格雷什"}},{q="需要回收什么物品？",a="特雷莱恩的符咒魔杖，这是特雷莱恩的第一件遗物。科格雷什一直用它向同类发射冰霜冲击。",al={"科格雷什持有什么物品","什么魔杖","特雷莱恩的魔杖"}},{q="完成这个任务需要什么前提条件？",a="它是“物有所值”的后续任务，也就是你为学徒克里汀所做的工作。",al={"食人魔与魔杖前置任务","食人魔与魔杖的前提条件","食人魔与魔杖的上一个任务"}}},fp="14,183,21.359.0,14.140.1,35.50.0,27.98.0,32.121.0,45.76.0"}
P.entries["quest:694"] = {n="特雷莱恩的防御",s="斯奎尔图手持魔杖，转向包围阿拉索之塔的食人魔。为了激活塔的防御系统，他需要从巨石拳萨满手中夺取一块天蓝玛瑙，并将其送到避难谷地的学徒克里汀那里。",h="斯奎尔图手持魔杖，转向包围阿拉索之塔的食人魔。为了激活塔的防御系统，他需要从巨石拳萨满手中夺取一块天蓝玛瑙，并将其送到避难谷地的学徒克里汀那里。",kw={"学徒克里汀","天蓝玛瑙","巨石拳萨满","避难谷地","斯奎尔图","激流堡","阿拉索之塔","特雷兰的防御系统"},sec={{t="塔的防御系统",b="食人魔包围了激流堡的阿拉索之塔。斯奎尔图说，如果你想在对抗它们的同时活着拿到那些物品，就必须激活塔的防御系统。"},{t="作为钥匙的宝石",b="塔中的某些宝石被巨石拳萨满看中了并被它们抢走，但斯奎尔图说它们不会保管太久。带一块天蓝玛瑙给避难谷地的学徒克里汀，他知道如何附魔这块宝石，使它能作为一把钥匙使用。"}},faq={{q="为什么需要天蓝玛瑙？",a="斯奎尔图想要激活塔的防御系统，这样你才能面对阿拉索之塔周围的食人魔并活着拿到那些物品。经过附魔后，这块宝石就能作为钥匙使用。",al={"为什么需要天蓝玛瑙","特雷兰的防御系统目的","为什么要获取宝石"}},{q="天蓝玛瑙是从哪里来的？",a="巨石拳萨满从阿拉索之塔将它们抢走，并对这些宝石产生了兴趣。",al={"谁拿走了玛瑙","宝石来自哪里","玛瑙来源"}},{q="谁能为宝石附魔？",a="避难谷地的学徒克里汀知道附魔这块宝石的咒语，使其能作为钥匙使用。",al={"谁为玛瑙附魔","克里汀的作用","谁把它变成钥匙"}}},fp="18,228,20.177.0,15.274.0,29.170.0,37.94.0,24.96.0"}
P.entries["quest:695"] = {n="学徒的魔法",s="学徒克里汀为你从巨石萨满手中取回的玛瑙施加了附魔。将它触碰塔底的基座，就能唤醒这座塔的防御系统。在你离开之前，他让你去找斯奎尔图了解剩下的事情。",h="学徒克里汀为你从巨石萨满手中取回的玛瑙施加了附魔。将它触碰塔底的基座，就能唤醒这座塔的防御系统。在你离开之前，他让你去找斯奎尔图了解剩下的事情。",kw={"学徒克里汀","阿拉希高地","附魔玛瑙","斯奎尔图","塔","特雷莱恩"},sec={{t="塔的钥匙",b="克里汀把附魔宝石交给你。他解释说，将其触碰塔底的基座即可唤醒塔的防御，当你准备好去取回特雷莱恩剩余的物品时，就用得上它。他会在营地等你回来。首先，去和斯奎尔图谈谈，他会告诉你还需要知道的其他事情。"}},faq={{q="附魔玛瑙有什么用途？",a="触碰塔底的基座，它能唤醒塔的防御系统。当你准备好进去取回特雷莱恩剩余的物品时，就可以使用它。",al={"为什么需要玛瑙","附魔玛瑙用法","宝石的作用"}},{q="离开营地前你需要找谁谈话？",a="斯奎尔图。克里汀让你在离开前和他谈谈，因为他会告诉你还需要知道的其他事情。",al={"应该找谁谈话","下一步去哪里","谁是斯奎尔图"}},{q="克里汀会在哪里？",a="他会在营地等你回来。",al={"克里汀在哪里","克里汀等待"}}},fp="27,225,19.338.0,43.152.0,47.110.0,21.44.0"}
P.entries["quest:696"] = {n="进攻高塔",s="随着高塔的防御机制被激活，避难谷地的斯奎尔图派遣你潜入食人魔控制的高塔，去寻找特瑞莱恩的护命匣、宝珠和余烬玛瑙。它们应该就在里面的箱子里，斯奎尔图说，如果你能把它们带回来，马林一定会非常高兴。",h="随着高塔的防御机制被激活，避难谷地的斯奎尔图派遣你潜入食人魔控制的高塔，去寻找特瑞莱恩的护命匣、宝珠和余烬玛瑙。它们应该就在里面的箱子里，斯奎尔图说，如果你能把它们带回来，马林一定会非常高兴。",kw={"阿拉希高地","攻击高塔","马林","食人魔","避难谷地","斯奎尔图","特瑞莱恩","特瑞莱恩的余烬玛瑙","特瑞莱恩的宝珠","特瑞莱恩的护命匣"},sec={{t="深入高塔",b="在克莱顿施加附魔之后，斯奎尔图会告诉你需要寻找的东西：特瑞莱恩的护命匣、宝珠和余烬玛瑙。这三样东西应该就在高塔内的箱子里，你打开它们应该不成问题，不过要小心食人魔。高塔的防御机制不会主动对付它们，如果食人魔发现你在偷窃，它们会让你吃尽苦头。"},{t="斯奎尔图的裁决",b="当你带回这三样物品时，斯奎尔图会说，马林再也找不到比你更适合在这里帮忙的人了。马林得知他们的冒险取得了圆满成功，一定会非常高兴。"}},faq={{q="谁指派了这个任务？",a="斯奎尔图，位于阿拉希高地的避难谷地，就在克莱顿为宝石施加附魔之后。",al={"谁给予攻击高塔任务","攻击高塔任务发布者","在哪里接攻击高塔任务"}},{q="你被派去取回什么物品？",a="特瑞莱恩的护命匣、宝珠和余烬玛瑙。它们应该都在高塔内的一个箱子里。",al={"攻击高塔任务物品","需要获取什么圣物","特瑞莱恩的物品"}},{q="食人魔会怎么做？",a="高塔的防御机制不会帮你对付它们。如果食人魔发现你在偷窃，它们会让你吃尽苦头。",al={"食人魔危险吗","高塔食人魔"}},{q="在此之前需要完成什么？",a="紧接着“学徒的附魔”任务，在该任务中，克莱顿会为宝石施加附魔并将你引向斯奎尔图。",al={"攻击高塔任务前置","哪个任务在前"}}},fp="19,246,14.384.0,17.189.1,22.85.0,36.86.0,23.137.0,23.98.0"}
P.entries["quest:6962"] = {n="冬幕节的礼物",s="给冬天爷爷的节日点心是奥格瑞玛在冬幕节期间发布的一项节日任务。那位坐在烟林牧场展示摊位上的快乐人物在听完节日愿望后感到十分疲惫，于是向一位热心的冒险者请求一些新鲜的姜饼和牛奶。",h="给冬天爷爷的节日点心是奥格瑞玛在冬幕节期间发布的一项节日任务。那位坐在烟林牧场展示摊位上的快乐人物在听完节日愿望后感到十分疲惫，于是向一位热心的冒险者请求一些新鲜的姜饼和牛奶。",kw={"姜饼","冬天爷爷","节日香料","冰镇牛奶","奥格瑞玛","烟林牧场","给冬天爷爷的节日点心","冬幕节"},ang={["faction:Horde"]="这场盛宴由富有进取心的烟林牧场地精带到奥格瑞玛，为这座粗犷的战士之城带来了一丝难得的轻快家庭欢乐。",["profession:Cooking"]="这项节日传统为学徒厨师提供了一个练习简单烘焙的机会，将野蛋和季节性香料变成节日的姜饼。"},sec={{t="冬日里的疲惫顾客",b="虽然冬天爷爷是艾泽拉斯冬日与富足的神话象征，但在这Valley of Strength迎接访客的这位人物，其实是烟林牧场雇佣的一名勤奋的表演者。长时间坐着听市民们谈论节日好物让他感到饥肠辘辘。厌倦了仅仅谈论节日美食，这位冬天爷爷很乐意招募路过的旅行者来满足他对热烘烘的糕点和冷饮的渴望。"},{t="节日美食精神",b="满足冬天爷爷的请求需要一点家常烹饪。冒险者必须从烟林牧场的地精商贩那里直接购买节日香料，从荒野的野生禽类身上采集小蛋，然后烘焙出经典的姜饼。配上一瓶从当地旅店购买的冰镇牛奶，这份小小的供品将回报烘焙者以节日欢欣和节日组织者的一点感激之情。"}},faq={{q="奥格瑞玛的冬天爷爷是谁？",a="他是烟林牧场雇佣的一名演员，负责在冬幕节期间扮演传说中的冬天爷爷。他坐在Valley of Strength的节日贸易展示摊位附近，迎接部落的公民，聆听节日的请求，并宣传季节性的欢乐。",al={"谁是冬天爷爷","奥格瑞玛冬天爷爷","他是真正的冬天爷爷吗"}},{q="冬天爷爷想要什么美食？",a="冬天爷爷想要五块刚烤好的姜饼和一份冰镇牛奶，以帮助他度过漫长而疲惫的迎接节日访客的一天。",al={"他想要什么","请求的美食","他需要什么曲奇"}},{q="如何制作姜饼？",a="节日展示摊位周围的烟林牧场商人出售食谱和节日香料。烘焙师将节日香料与从野生禽类身上采集的小蛋混合，然后在烹饪之火上制作饼干。",al={"如何获得姜饼","姜饼食谱","曲奇配料"}},{q="哪里可以找到冰镇牛奶？",a="冰镇牛奶可以从奥格瑞玛和其他主要定居点的几乎任何食物和饮料商贩、旅店老板或酒保处购买。",al={"哪里可以获得冰镇牛奶","购买牛奶","牛奶商人"}},{q="为什么冬天爷爷要亲自索要食物？",a="整天听孩子们和市民们谈论食物、礼物和庆典，让这位表演者饿坏了。由于他无法轻易离开他在Valley of Strength的岗位，他请求路过的冒险者为他带来一些快餐。",al={"为什么他想要美食","冬天爷爷饿了吗"}},{q="这个任务有联盟对应版本吗？",a="有。驻扎在铁炉堡的冬天爷爷也会提出同样的请求，他同样会在节日期间向联盟的勇士索要姜饼和冰镇牛奶。",al={"联盟版本","铁炉堡美食"}}},fp="30,167,24.237.0,23.264.0,39.268.0,44.134.0,36.193.0,33.128.0,50.240.0,45.141.0"}
P.entries["quest:697"] = {n="马林的要求",s="斯奎尔图交给你一封给大法师马林的密封信，他就在暴风城的Mage Quarter。信中告诉马林，克莱登和斯奎尔图很快就会回家了，斯奎尔图确信马林会因为你在阿拉希对他们的帮助而给予你丰厚的报酬。",h="斯奎尔图交给你一封给大法师马林的密封信，他就在暴风城的Mage Quarter。信中告诉马林，克莱登和斯奎尔图很快就会回家了，斯奎尔图确信马林会因为你在阿拉希对他们的帮助而给予你丰厚的报酬。",kw={"阿拉希高地","大法师马林","克莱登","mage quarter","马林的请求","密封信","斯奎尔图","暴风城"},sec={{t="给大法师的信",b="在阿拉希的工作完成后，斯奎尔图交给你一封信，让你带回暴风城。信中给Mage Quarter的大法师马林传达的消息是，克莱登和斯奎尔图很快就会回家了。斯奎尔图毫不怀疑马林会因为你帮助他们而给你丰厚的报酬，并祝愿你旅途平安。"},{t="马林阅读信件",b="当马林打开信件时，他的眼睛睁大了。他很高兴，并说特雷兰会非常开心的。他想克莱登和斯奎尔图现在正赶回暴风城，应该和他一样兴奋。"}},faq={{q="是谁让你送信的？",a="是斯奎尔图。信中告诉马林，他和克莱登很快就会回家了。",al={"谁给了这封信","谁开启了马林的请求","马林的请求起始"}},{q="大法师马林在哪里？",a="大法师马林在暴风城的Mage Quarter。",al={"大法师马林在哪里","大法师马林位置","我在哪里交这个任务"}},{q="克莱登是谁？",a="克莱登是斯奎尔图在阿拉希高地的同伴。斯奎尔图说他们两个很快就会回家了。",al={"克莱登是谁","克莱登阿拉希"}},{q="这一步之前是什么？",a="这是在“攻击塔楼”之后进行的，那是斯奎尔图在阿拉希的塔楼交给你的工作。",al={"上一个任务","前置任务","什么引导至此"}}},fp="15,230,25.296.0,22.199.1,30.74.0,32.51.0,14.102.0,28.85.0"}
P.entries["quest:698"] = {n="缺乏补给",s="达尔正在为东部海滩边的前哨站收集补给品，托克卡尔在那里除了执勤和为士兵做饭，几乎没有多余的时间。达尔让你给托克卡尔送去一批锯齿肉。",h="达尔正在为东部海滩边的前哨站收集补给品，托克卡尔在那里除了执勤和为士兵做饭，几乎没有多余的时间。达尔让你给托克卡尔送去一批锯齿肉。",kw={"达尔","肉排","肉","前哨站","锯齿鱼","悲伤沼泽","托克卡尔"},sec={{t="岸边的补给",b="达尔正在为东部海滩边的前哨站收集补给品。托克卡尔在那里竭尽所能地工作，但执勤和为士兵做饭让他几乎没有空闲时间。士兵们如果能弄到锯齿肉的话很喜欢烹饪它，但达尔一直没有时间给他们送去补给。"},{t="挑选肉类",b="达尔提醒你不要去动年幼的锯齿鱼，因为年长的肉质更好。幼鱼需要一两年的时间才能长到完全成熟。你需要带八块未经处理的锯齿鱼肉排给悲伤沼泽里的托克卡尔。"}},faq={{q="是谁在请求锯齿鱼肉？",a="达尔，他正在为东部海滩边的前哨站收集补给。",al={"谁给予物资匮乏任务","谁开启物资匮乏任务","达尔 悲伤沼泽"}},{q="托克卡尔驻扎在哪里？",a="在达尔提到的东部海滩前哨站。肉要送到那里给悲伤沼泽的托克卡尔。",al={"托克卡尔在哪里","托克卡尔位置","托克卡尔前哨站"}},{q="为什么托克卡尔需要别人帮忙带肉？",a="在执勤和为士兵做饭之间，托克卡尔几乎没有剩下的时间。",al={"为什么托克卡尔需要肉","为什么达尔要送食物"}},{q="应该猎杀哪种锯齿鱼？",a="年长的那些。幼鱼味道不够好，而且需要一两年的时间才能长到完全成熟。",al={"哪种锯齿鱼","什么锯齿鱼掉落肉","锯齿鱼肉排来源"}},{q="需要多少块肉排？",a="八块未经处理的锯齿鱼肉排，带给托克卡尔。",al={"需要多少肉排","未经处理的锯齿鱼肉排数量"}},{q="接下来要做什么？",a="后续有一个同名的第二步任务。",al={"物资匮乏的后续任务","物资匮乏后续"}}},fp="15,216,22.299.0,17.220.0,36.72.0,27.130.0,43.91.0,33.84.0,27.53.0,29.42.0"}
P.entries["quest:6981"] = {n="发光的碎片",s="发光的碎片是一块从哀嚎洞穴的黑暗深处开采出来的神秘翡翠色宝石。这件令人不安的遗物表面光洁，其下却翻涌着烟雾般的精粹，驱使着冒险者们前往棘齿城及更远的地方寻求答案。",h="发光的碎片是一块从哀嚎洞穴的黑暗深处开采出来的神秘翡翠色宝石。这件令人不安的遗物表面光洁，其下却翻涌着烟雾般的精粹，驱使着冒险者们前往棘齿城及更远的地方寻求答案。",kw={"贫瘠之地","尖牙德鲁伊","翡翠梦魇","菲拉·古风","发光的碎片","棘齿城","斯布特瓦夫","哀嚎洞穴"},ang={["class:Druid"]="对于德鲁伊来说，碎片那翡翠般的光泽和烟雾状的核心是翡翠梦魇通过哀嚎洞穴中堕落的同胞渗入现实世界的严峻证据。",["faction:Alliance"]="即使在远方的卡利姆多，联盟的探索者们也认识到，无论是什么样的黑暗力量在腐蚀贫瘠之地地下的自然，都构成了全球性的威胁。",["faction:Horde"]="解开碎片的谜团有助于保护贫瘠之地重要的十字路口和贸易路线，使其免受地下泉水中滋生的非自然威胁的影响。",["race:Tauren"]="贫瘠之地的平衡对舒哈鲁来说至关重要，将这件非自然的遗物交给菲拉·古风有助于了解毒害他们祖地的腐化。"},sec={{t="一个令人不安的发现",b="发光的碎片取自哀嚎洞穴深处，持有它的人会立刻感到不安。它呈耀眼的绿色，看似坚硬，但在其结晶体表面下却有着翻腾的雾状阴影。这块水晶散发着一种微妙的吸引力，引人注目，同时也流露出一种深沉而令人不安的气息，暗示了那些沉睡的德鲁伊和他们那被梦魇侵蚀的圣地受到了腐化。"},{t="在棘齿城寻求答案",b="冒险者们不清楚这块石头的来历或本质，于是将这件神器带到了地精港口棘齿城。当地的工程师斯布特瓦夫检查了这个古怪的东西，却意识到它的起源超出了地精机械学和常规地质学的范畴。于是，他指引寻找答案的人前往洞穴上方的岩脊，牛头人神秘学家菲拉·古风正在那里守护着贫瘠之地不安的灵魂。"}},faq={{q="发光的碎片是什么？",a="这是一块在哀嚎洞穴深处发现的、受到腐化的绿色发光水晶。在它玻璃般的外壳内，淡淡的烟雾在翻腾，让任何仔细观察它的人都感到不安。",al={"发光的碎片物品","这颗绿色宝石是什么","哀嚎洞穴的碎片"}},{q="在棘齿城有谁能检查这块碎片？",a="驻扎在棘齿城飞行管理员附近的工程师斯布特瓦夫会检查这块碎片。虽然他是一位工程师而非德鲁伊，但他认出了其中的奇异能量，并指引你去找一位拥有灵性专业知识的人。",al={"棘齿城里谁检查碎片","棘齿城碎片npc","斯布特瓦夫碎片"}},{q="菲拉·古风在哪里？",a="菲拉·古风在贫瘠之地中部哀嚎洞穴入口正上方的山顶扎营。",al={"菲拉·古风位置","菲拉在哪里","哀嚎洞穴上方的山峰"}},{q="斯布特瓦夫头上有任务标记吗？",a="没有。斯布特瓦夫不会显示活动的任务图标。你必须直接与他交谈，并选择关于那块奇怪发光碎片的对话选项来推进任务。",al={"斯布特瓦夫没有问号","无法向斯布特瓦夫交任务","斯布特瓦夫bug"}},{q="为什么碎片看起来像包含了烟雾？",a="水晶内翻腾的烟雾反映了正在扭曲哀嚎洞穴的广泛腐化，这直接与入侵沉睡的尖牙德鲁伊思想的翡翠梦魇有关。",al={"为什么碎片有烟雾","宝石里的绿色烟雾","碎片中的腐化"}},{q="谁能完成菲拉·古风之后的任务链？",a="部落和联盟的冒险者都可以进行这条故事线。菲拉·古风的发现直接引出了任务“梦魇之中”，要求英雄们向各自的领袖和长者寻求指引。",al={"这个任务是部落专属吗","联盟发光的碎片","谁能接到梦魇之中"}}},fx={["8f9c92be"]={q="为什么要调查发光的碎片？",a="这块发光的碎片令人极度不安。它质地坚硬，内部却有烟雾般的绿色深处不断翻涌，散发着一种不自然的气息，亟待解释。你从状况堪忧的哀嚎洞穴深处找到了它，需要弄清它携带着何种腐化，以及它可能会给贫瘠之地带来什么威胁。",al={"为什么调查发光的碎片","发光的碎片的动机","为什么把碎片带到棘齿城"}}},fp="17,241,22.398.0,26.419.1,26.170.0,37.225.0,32.126.0,52.167.0,47.196.0,54.208.1"}
P.entries["quest:6984"] = {n="烟林牧场的感谢",s="这项节日任务标志着熏木农场在奥格瑞玛的冬季恢复工作圆满结束。在从卑劣的格林奇手中夺回被盗的节日佳肴后，冒险者将受到地精商人凯玛德·考伯宾奇的指引，直接从冬天爷爷那里接受一份正式的节日感谢礼。",h="这项节日任务标志着熏木农场在奥格瑞玛的冬季恢复工作圆满结束。在从卑劣的格林奇手中夺回被盗的节日佳肴后，冒险者将受到地精商人凯玛德·考伯宾奇的指引，直接从冬天爷爷那里接受一份正式的节日感谢礼。",kw={"冬幕节","冬天爷爷","格林奇","凯玛德·考伯宾奇","奥格瑞玛","熏木农场","valley of strength"},ang={["faction:Horde"]="部落在奥格瑞玛的冬幕节庆祝活动将古老的萨满季节更替崇拜与喧闹的地精商业精神融合在了一起。",["profession:Cooking"]="熏木农场的时令补给是节日烹饪的核心，提供了大厨们每年翘首以盼的异国配方和节日食材。"},sec={{t="企业节日",b="熏木农场热衷于利用冬幕节的气氛，在艾泽拉斯的各大主城营销各类佳肴、配方和节日礼品。当他们的一批节日货物在奥特兰克山脉的雪山中被抢走后，业务陷入了停滞。随着佳肴被夺回，偷窃的格林奇也被解决，商人凯玛德·考伯宾奇迅速确保这些乐于助人的勇士们能够获得充分的企业感谢——以及一场隆重的颁奖仪式。"},{t="觐见冬天爷爷",b="地精们没有在柜台上递过普通的钱袋，而是安排冬天爷爷亲自颁发奖励。这位节日人物在力量谷的节日树旁主持大局，既是文化赞助人，也是节日庆典的名誉领袖。他用节日的祝福和一份熏木农场特殊礼物来嘉奖那些挽救了节日补给的人们。"}},faq={{q="谁指派我去和冬天爷爷谈话？",a="凯玛德·考伯宾奇，即驻扎在奥格瑞玛力量谷的熏木农场代表。一旦你成功夺回了公司被盗的节日佳肴，他就会指引你去找冬天爷爷。",al={"谁开启此任务","任务发布者","凯玛德的角色"}},{q="我做了什么才赢得了熏木农场的感激？",a="你在奥特兰克山脉追踪并找到了卑劣的格林奇，夺回了被盗的节日佳肴，为地精们挽救了冬幕节的供应链。",al={"为什么他们要感谢我","什么佳肴被偷了","格林奇背景"}},{q="冬天爷爷在奥格瑞玛的什么地方？",a="他就坐在力量谷那棵装饰华丽的大冬幕树下，就在熏木农场的摊位旁边。",al={"冬天爷爷位置","奥格瑞玛的圣诞老人哪里找","奥格瑞玛的冬幕树"}},{q="谁是冬天爷爷？",a="在古老的传说中，冬天爷爷是一位象征季节更替的元素或神话使者，他为大地披上冬雪。在冬幕节期间，凡人扮演者会穿上他传统的红色长袍，传播善意并向孩子们和冒险者分发糖果。",al={"冬天爷爷是谁","冬天爷爷真实存在吗","冬幕节传说"}},{q="什么是熏木农场？",a="熏木农场是一家由地精经营的餐饮和农业企业。在冬幕节期间，他们为部落和联盟供应节日食品、时令食材和装饰性小商品。",al={"熏木农场传说","熏木农场是什么","地精节日商人"}},{q="和他说过话后，我还会收到其他东西吗？",a="是的。冬天爷爷会代表公司交给你一份熏木农场特殊礼物，你的努力也会让你获得热砂港的声望。",al={"任务奖励","伪装道具","邮寄礼物"}}},fp="32,207,19.325.0,33.222.0,47.178.0,52.171.0,50.136.0,27.240.0,27.200.0,51.154.0"}
P.entries["quest:699"] = {n="缺乏补给",s="托克卡尔和海岸边的士兵们驻扎在这里，是为了防范鱼人对斯通纳德的威胁，或者在大规模敌袭时发出警报。托克卡尔需要六个锯齿龙虾人的爪子，并愿意用前哨站的一件武器作为报答。",h="托克卡尔和海岸边的士兵们驻扎在这里，是为了防范鱼人对斯通纳德的威胁，或者在大规模敌袭时发出警报。托克卡尔需要六个锯齿龙虾人的爪子，并愿意用前哨站的一件武器作为报答。",kw={"爪子","鱼人","锯齿龙虾人","斯通纳德","悲伤沼泽","托克卡尔"},sec={{t="海岸卫兵的武器",b="由于海岸边存在鱼人的威胁，托克卡尔和士兵们被派驻于此，以保卫斯通纳德，或者在敌方规模过大时发出警报。这让他们几乎没有休息的时间，托克卡尔希望能得到更多的帮助。锯齿龙虾人的爪子如果经过妥善处理，可以制成精良的武器。托克卡尔请求收集六个，并承诺以一件前哨站的武器作为回报，同时他也非常感激你能带来的肉食与陪伴。"}},faq={{q="谁要求收集爪子？",a="托克卡尔，他正驻扎在海岸边保卫斯通纳德。",al={"谁发布了供应短缺任务","任务发布者","托克卡尔"}},{q="为什么托克卡尔需要锯齿龙虾人的爪子？",a="如果经过妥善处理，它们的爪子可以制成精良的武器，托克卡尔需要六个。",al={"为什么需要爪子","锯齿龙虾人的用途","武器爪子"}},{q="海岸前哨站正在防范什么威胁？",a="海岸边的鱼人。士兵们驻扎在那里是为了保卫斯通纳德，或者在大规模敌袭时发出警报。",al={"海岸危险","鱼人攻击斯通纳德","托克卡尔在监视什么"}},{q="接下来的任务是什么？",a="接下来是“来自大海的威胁”。",al={"what comes next","后续任务","供应短缺之后"}}},fp="15,225,21.392.0,23.61.0,45.84.0,45.108.0,26.28.0"}
P.entries["quest:7"] = {n="剿灭狗头人",s="“清理狗头人营地”是治安官玛克布莱德指派给刚抵达北郡山谷的新兵的一项早期军事任务。该任务旨在让志愿者们清理潜伏在北部林地中的狗头人害虫，防止这些具有攻击性的地下食腐生物淹没修道院。这是新兵在保卫暴风城领土边界时的第一次真正考验。",h="“清理狗头人营地”是治安官玛克布莱德指派给刚抵达北郡山谷的新兵的一项早期军事任务。该任务旨在让志愿者们清理潜伏在北部林地中的狗头人害虫，防止这些具有攻击性的地下食腐生物淹没修道院。这是新兵在保卫暴风城领土边界时的第一次真...",kw={"回音山","艾尔文森林","狗头人","治安官玛克布莱德","北郡","北郡修道院","害虫"},ang={["faction:Alliance"]="北郡的不安局势凸显了暴风城本土领地所承受的压力，即使是低等级的食腐生物入侵也需要紧急动员志愿民兵。",["race:Human"]="对于北郡的人类来说，驱逐狗头人害虫是保护修道院和农田免遭蹂躏的一项基本公民义务。"},sec={{t="压力重重的山谷",b="北郡山谷曾是一片宁静的祈祷、务农与新兵训练场所，但近年来暴风城的军事力量已捉襟见肘。随着国王失踪以及皇家卫队被调离，野生生物和投机者们胆大妄为地向文明边缘推进。治安官玛克布莱德在北郡修道院内组织当地防务，依靠新招募的志愿者在威胁干扰修道院运作或威胁周边葡萄园之前将其镇压。"},{t="林中的害虫",b="狗头人天生胆小且痴迷蜡烛，通常满足于在远离阳光的地下矿脉中挖掘。然而，一个完整的狗头人氏族已经涌入了北郡北部的林线。如果不加遏制，它们庞大的数量足以将食腐行为演变成公开的掠夺。玛克布莱德下令猎杀狗头人害虫有着双重目的：既能削弱它们的先头部队，又能检验新兵是否具备保卫王国所需的决心。"}},faq={{q="是谁下令清理狗头人营地的？",a="治安官玛克布莱德下达了命令。他驻扎在北郡修道院内，代表暴风城负责监督当地新兵的招募以及山谷的安保工作。",al={"谁发布了这个任务","任务发布者","治安官玛克布莱德的角色"}},{q="为什么狗头人不在矿洞里，而是在北部的林地中？",a="虽然狗头人通常居住在洞穴和矿洞中，但它们在北郡的人口已经稠密到溢出到了森林中。它们在北部的树林间建立了原始营地，在文明之地的边缘徘徊。",al={"为什么狗头人在外面","地表的狗头人","为什么在林地"}},{q="为什么这些狗头人被视为对暴风城的威胁？",a="从个体来看，狗头人害虫胆小而虚弱。然而，成群结队的它们是肆无忌惮的盗贼，能够伏击旅行者、掠夺补给并占领无人防守的哨所，而在军事力量已经过度紧缩的情况下，暴风城无法承受这样的损失。",al={"狗头人危险吗","为什么要杀死害虫"}},{q="这项任务接下来会指向哪里？",a="在清理掉地表的害虫后，治安官玛克布莱德会要求新兵深入调查回音山矿洞，那里才是狗头人入侵的中心。",al={"下一个任务是什么","下一步","清理营地之后"}},{q="北郡能得到定期的皇家军队支援吗？",a="不能。由于国王瓦里安失踪后王国各地的政治紧张局势和部队短缺，像玛克布莱德这样的地方指挥官必须依靠平民志愿者、冒险者和受训人员来处理边界安全问题。",al={"暴风城的守卫在哪里","为什么要志愿者"}},{q="是什么让狗头人如此依恋蜡烛？",a="狗头人将蜡烛视为抵御地下隧道中窒息黑暗的主要防线。火焰对它们而言代表着安全、视力和所有权，因此如果有任何人试图夺走蜡烛，它们会表现出众所周知的敌意。",al={"为什么需要蜡烛","蜡烛痴迷症"}}},fp="19,229,23.429.0,23.359.0,42.123.0,56.202.0,55.197.0,34.145.1,50.184.0,48.164.0"}
P.entries["quest:70"] = {n="斯塔文的传说",s="调查的这一阶段将寻找者引向多年前遗落在闪金镇旅店的一封被遗弃的信件。沿着斯塔文·密斯特曼托的踪迹，调查从艾尔文森林一直延伸到暴风城的运河区。",h="调查的这一阶段将寻找者引向多年前遗落在闪金镇旅店的一封被遗弃的信件。沿着斯塔文·密斯特曼托的踪迹，调查从艾尔文森林一直延伸到暴风城的运河区。",kw={"运河","管理员弗索姆","闪金镇","旅店老板法雷","lion's pride inn","密斯特曼托","斯塔文","暴风城","未投递的信件"},ang={["faction:Alliance"]="解开斯塔文之谜需要穿过联盟的核心地带，从安静的闪金镇小村一路追溯到首都的大运河。",["race:Human"]="这项调查揭露了暴风王国更深层的黑暗暗流，表明困扰暮色森林的邪恶根源一直延伸到首都的门口。"},sec={{t="午夜惊魂",b="当询问Lion's Pride Inn的旅店老板法雷关于斯塔文·密斯特曼托的事情时，他回忆起多年前一个暴风雨的夜晚。一名旅行信使曾为了躲避倾盆大雨而在那里寻求庇护，却在午夜时分惊慌失措地冲下楼梯。那名信使只穿着睡衣，直接冲进了黑暗的风暴中，从此再也没有出现过。"},{t="遗留的包裹",b="在惊慌逃窜中，信使将他的挎包和个人箱子遗弃在楼上的房间里。在被遗忘的货物中有一封未寄出的信，上面写着斯塔文的名字，收件人是住在暴风城运河区的人。这个箱子一直原封不动地放在床脚，直到法雷允许将其打开。"},{t="冰冷的接待",b="将这封迟到的信带入暴风城，会找到管理员弗索姆，他负责看管公园附近运河沿岸的房产。提到斯塔文的名字并看到他的笔迹，并没有换来对完成遗留投递工作的感激，反而引发了立时的厌恶和敌意，暗示着与寄信人有关的深层丑闻。"}},faq={{q="未投递的信件存放在哪里？",a="信件放在闪金镇Lion's Pride Inn楼上的一个储物箱里。走上楼梯，向右转，进入那间带床的卧室；箱子就放在床架的脚头。",al={"寻找信件","斯塔文箱子位置","箱子在哪里"}},{q="为什么这封信最初没有被投递？",a="多年前，信使在Lion's Pride Inn躲避倾盆大雨。午夜时分，某种东西把他吓坏了，他只穿着睡衣就逃进了风暴中，留下了他的箱子和信件。",al={"为什么信被遗弃","信使被什么吓跑了","为什么信使逃跑了"}},{q="我在哪里能找到暴风城的管理员弗索姆？",a="管理员弗索姆站在暴风城的运河边，靠近公园区边缘。",al={"弗索姆位置","管理员弗索姆在哪里","运河区上交任务"}},{q="为什么管理员弗索姆对收到这封信感到愤怒？",a="弗索姆立刻认出了斯塔文的笔迹和名字，反应十分愤慨。斯塔文·密斯特曼托给暴风城中与他过去有牵连的人们留下了痛苦的回忆和愤慨。",al={"为什么弗索姆很生气","弗索姆的反应","你胆子不小"}},{q="这与暮色森林的麻烦有什么联系？",a="夜色镇的镇议会正在调查与斯塔文·密斯特曼托这个名字有关的挥之不去的邪恶。揭开斯塔文生前究竟是谁的真相，需要追溯他早年在艾尔文森林和暴风城的旅行与交往。",al={"为什么暮色森林任务在闪金镇","这与暮色森林有何关联"}},{q="将信交给管理员弗索姆后会发生什么？",a="管理员弗索姆激烈的回应开启了调查的暴风城篇章，推动你去揭开斯塔文曾经的雇佣关系，以及他所服务的贵族家庭发生的可怕事件。",al={"下一步","这个任务之后是什么"}}},fp="21,153,17.281.0,19.297.0,16.263.1,37.210.0,46.214.0,46.91.0,57.182.0,49.198.0,57.186.1"}
P.entries["quest:700"] = {n="国王的礼物",s="“国王的贡品”是向阵亡的矮人战士Sully Balloo致敬的最后一步。在从洛丹伦废墟收集了优质花岗岩后，大石匠玛布勒斯坦奉国王麦格尼·铜须之命，在铁炉堡雕刻了一座庄严肃穆的纪念碑。",h="“国王的贡品”是向阵亡的矮人战士Sully Balloo致敬的最后一步。在从洛丹伦废墟收集了优质花岗岩后，大石匠玛布勒斯坦奉国王麦格尼·铜须之命，在铁炉堡雕刻了一座庄严肃穆的纪念碑。",kw={"国王的贡品","花岗岩","铁炉堡","洛丹伦","magni bronzebeard","玛布勒斯坦","纪念碑","sully balloo"},ang={["class:Warrior"]="国王麦格尼·铜须的话语直接向Sully Balloo这样在战斗中牺牲了一切的前线士兵的无私英勇表示了敬意。",["faction:Alliance"]="这座纪念碑令人心酸地提醒着人们，近期发生的冲突在卡兹莫丹和北方诸王国造成了沉重的代价。",["race:Dwarf"]="对于矮人来说，用永恒的石头纪念祖先阵亡的勇士是他们最神圣的文化传统之一。"},sec={{t="镌刻哀思的纪念碑",b="国王麦格尼·铜须委托修建了一座永久性的纪念碑，以缅怀Sully Balloo，一位为保卫族人而牺牲的勇敢矮人。这座纪念碑由大石匠玛布勒斯坦使用从饱受战火摧残的洛丹伦运来的优质花岗岩雕刻而成，矗立在铁炉堡，作为阵亡将士的永恒见证，他们的牺牲守护了矮人王国。"},{t="君主的沉思",b="当得知纪念碑完工的消息时，Magni Bronzebeard陷入了对石头与凡人生命极限的沉思。虽然他承认雕刻出的岩石永远无法真正等同于一位勇敢矮人的生命，但他希望这座纪念碑能长久留存，让行走在艾泽拉斯的后世子孙永远不会忘记那些为了换取他们明天而流血牺牲的英雄。"}},faq={{q="这座纪念碑是为了纪念谁？",a="这座纪念碑是为了纪念Sully Balloo，一位为他的族人和联盟英勇作战而献出生命的勇敢矮人战士。",al={"谁的纪念碑","sully balloo纪念碑","阵亡者"}},{q="为什么要从洛丹伦采集石料？",a="大石匠玛布勒斯坦需要最优质的花岗岩来制作持久的皇家贡品。尽管洛丹伦在天灾军团入侵后已成废墟，但该地区盛产出色的采石。",al={"为什么使用洛丹伦的石头","洛丹伦花岗岩","玛布勒斯坦的石雕"}},{q="这个任务发生在哪里？",a="任务始于大石匠玛布勒斯坦，并最终在铁炉堡的High Seat面见国王麦格尼·铜须处完成。",al={"任务交还地点","完成任务的角色"}},{q="为什么国王麦格尼要亲自委托制作这个贡品？",a="麦格尼认为统治者必须向保卫王国的士兵致敬。他视纪念碑为后世子孙的重要警示，提醒他们普通的士兵为他们的安全付出了何等高昂的代价。",al={"国王麦格尼·铜须的用意","magni bronzebeard与sully balloo"}},{q="纪念碑完工后会发生什么？",a="向国王麦格尼汇报便完成了这一纪念任务线。雕像将留在铁炉堡，成为Sully Balloo一座庄严而永久的纪念碑。",al={"what comes next","国王的贡品后续"}},{q="这座雕像在石匠工艺上有什么意义？",a="大石匠玛布勒斯坦是铁炉堡成就最高的矮人工匠之一。他加工了进口的洛丹伦花岗岩，代表君主将未经雕琢的石料塑造成了一件适宜的国家艺术品。",al={"玛布勒斯坦的角色","大石匠的工艺"}}},fp="16,153,26.296.0,24.261.0,38.117.0,42.172.0,33.100.0,55.178.0,44.132.0,47.169.0"}
P.entries["quest:7003"] = {n="被缩小的巨人",s="在菲拉斯的被遗忘的海岸，码头附近，索尔宾·范达瑟声称那些巨人影响了他的生意。索尔宾根据地精的设计制造了一种缩小射线，并用地精的专有技术对其进行了改进。他把这种“超级缩小器”交给你，让你去对菲拉斯的巨人试用一下。",h="在菲拉斯的被遗忘的海岸，码头附近，索尔宾·范达瑟声称那些巨人影响了他的生意。索尔宾根据地精的设计制造了一种缩小射线，并用地精的专有技术对其进行了改进。他把这种“超级缩小器”交给你，让你去对菲拉斯的巨人试用一下。",kw={"峭壁巨人","菲拉斯","被遗忘的海岸","陆地漫步者","缩小残渣","超级缩小器","巨人的缩小射线","索尔宾·范达瑟"},sec={{t="巨人的缩小射线",b="索尔宾·范达瑟必须对菲拉斯的巨人采取一些行动，因为只要这些巨人存在，索尔宾就没法在这里好好做生意。解决办法是对地精缩小射线进行改进，索尔宾自豪地称之为“卓越的地精科技”。为了避免死亡等不便，索尔宾更希望由你来测试它。你需要对峭壁巨人、深渊漫步者、海浪漫步者、海岸漫步者或陆地漫步者等巨人使用超级缩小器，并在他们缩小后收集残留的缩小残渣，然后带回码头。"},{t="为什么索尔宾需要残渣",b="索尔宾称缩小残渣是工程学中的一种宝贵原料，因为它有助于确保射线枪不会发生令用户失望的爆炸。索尔宾随后补充说，这只适用于其他射线枪，而不适用于你手中的这一把。"},{t="回到码头",b="当你回来时，索尔宾很高兴看到残渣，并且发现你所有的主要肢体都还在。索尔宾随即坚称超级缩小器从未有过任何风险，并称你为所有地精的朋友。"}},faq={{q="谁制造了超级缩小器？",a="索尔宾·范达瑟，他在菲拉斯的被遗忘的海岸的码头附近。",al={"谁发布巨人的缩小射线任务","索尔宾·范达瑟任务发布者","巨人的缩小射线在哪里领取"}},{q="为什么索尔宾想把巨人变小？",a="索尔宾说，如果他要留在这里，这些巨人显然会妨碍生意，而缩小后的巨人要好对付得多。",al={"为什么要缩小巨人","为什么在菲拉斯缩小巨人","索尔宾·范达瑟的目的"}},{q="哪些巨人可以被缩小？",a="菲拉斯的任何巨人都可以。在被遗忘的海岸，这包括峭壁巨人、深渊漫步者、海浪漫步者、海岸漫步者和陆地漫步者。",al={"我可以缩小哪些巨人","哪些巨人计算任务进度","巨人的缩小射线目标"}},{q="什么是缩小残渣？",a="它是在巨人被缩小后在他们身上发现的物质。索尔宾称它是工程学中的宝贵原料，并表示它有助于确保射线枪不会对用户发生爆炸。",al={"为什么需要缩小残渣","残渣有什么用","索尔宾收集残渣的目的"}}},fp="13,258,30.547.0,28.261.0,17.213.1,33.71.0,39.129.0,27.154.0,32.170.0"}
P.entries["quest:701"] = {n="迅猛龙的狡诈",s="“迅猛龙的狡诈”是一个任务，在此任务中，托尔甘试图唤醒戈穆尔内心沉睡的战士精神。托尔甘计划通过收集高原血掠龙的心脏，来制作一件注入了迅猛龙狡诈与捕食力量的附魔物品。",h="“迅猛龙的狡诈”是一个任务，在此任务中，托尔甘试图唤醒戈穆尔内心沉睡的战士精神。托尔甘计划通过收集高原血掠龙的心脏，来制作一件注入了迅猛龙狡诈与捕食力量的附魔物品。",kw={"沉睡的战士","戈穆尔","迅猛龙的狡诈","高原血掠龙","迅猛龙心脏","托尔甘","战士"},ang={["class:Warrior"]="托尔甘试图用迅猛龙的狡诈和凶猛，来重新点燃戈穆尔内心沉睡的战士精神，提醒他那曾经拥有的武力。",["faction:Horde"]="这一仪式反映了部落利用原始野兽和自然之灵，来帮助消沉或受困的同伴找回人生目标的传统。"},sec={{t="唤醒沉睡的战士",b="托尔甘致力于恢复一位名叫戈穆尔的消沉同伴，此人的战士精神已经陷入沉睡。托尔甘并没有单纯依赖劝说，而是转向原始魔法，试图通过冲击让戈穆尔重振旗鼓。他希望通过制作一个注入了野生掠食者精魂的护符，让戈穆尔重新找回战斗的决心，并向他展示这股新力量的强大。"},{t="掠食者的心脏",b="为了引导野外的捕食本能，托尔甘需要高原血掠龙的心脏。在萨满教和原始传统中，狡猾猎手的心脏承载着它们的凶猛与狡诈。托尔甘利用这些战利品编织成一件实体信物并施加咒语，旨在直接向戈穆尔灌输掠食者的狡诈，从而让他重拾真正的使命。"}},faq={{q="托尔甘是谁？",a="托尔甘是一位萨满或精神领袖，他试图帮助戈穆尔。托尔甘认为戈穆尔已经失去了内心的力量，因此正在收集试剂，制作一件注入了野兽魔法的物品来唤醒他。",al={"托尔甘是谁","托尔甘","任务发布者"}},{q="戈穆尔是谁？",a="戈穆尔是一个已经丧失斗志，让内心的战士陷入沉睡的人。托尔甘打算向他注入原始掠食者的精魂，让他见证新的力量，并重新站起来战斗。",al={"戈穆尔是谁","为什么要帮助戈穆尔","沉睡的战士"}},{q="托尔甘为什么需要迅猛龙心脏？",a="托尔甘需要十二颗迅猛龙心脏来制作实体护身符，并完成注入戈穆尔所需的附魔。原始魔法经常使用掠食者的心脏来引导它们固有的本能、狡诈和捕食力量。",al={"为什么需要迅猛龙心脏","心脏有什么用","迅猛龙魔法"}},{q="这些迅猛龙心脏从哪里来？",a="所需的心脏取自高原血掠龙，这是一种以不懈的狩猎技巧和狡诈而闻名的掠食性迅猛龙。托尔甘认为它们的心脏足以驱动这种唤醒咒语。",al={"从哪获得心脏","哪种迅猛龙","高原血掠龙"}},{q="“迅猛龙的狡诈”象征着什么？",a="迅猛龙的狡诈代表了掠食者的狡猾、敏捷的反应和致命的本能。托尔甘相信引导这种特定的天性将能打破戈穆尔的怠惰，并复苏他的战斗本能。",al={"什么是迅猛龙的狡诈","什么力量","迅猛龙狡诈的含义"}},{q="仪式的最终目标是什么？",a="托尔甘利用收集到的心脏制作物品并编织咒语，旨在向戈穆尔展示新的力量，唤醒他沉睡的战士身份，让他重回正轨。",al={"戈穆尔痊愈了吗","仪式之后会发生什么","这管用吗"}}},fp="19,260,29.372.0,25.370.0,15.214.0,15.212.0,36.231.0,37.206.0,42.218.0,40.182.0"}
P.entries["quest:702"] = {n="迅猛龙的狡诈",s="在之前的“迅猛龙的狡诈”之后，托尔甘交给你一颗宝珠，并让你前往落锤镇寻找戈穆尔。宝珠的能量中蕴含着迅猛龙的精髓，旨在唤醒戈穆尔的精神，为他指引新的方向。",h="在之前的“迅猛龙的狡诈”之后，托尔甘交给你一颗宝珠，并让你前往落锤镇寻找戈穆尔。宝珠的能量中蕴含着迅猛龙的精髓，旨在唤醒戈穆尔的精神，为他指引新的方向。",kw={"阿拉希高地","戈穆尔","落锤镇","迅猛龙精髓","托尔甘","托尔甘的宝珠"},sec={{t="托尔甘的宝珠",b="托尔甘给了你一颗宝珠，其能量旨在将迅猛龙的精髓灌注给戈穆尔。他希望能借此唤醒这位战士的精神，让他开始新的人生。一旦戈穆尔恢复正常，托尔甘打算向他解释部落目前的处境，并在这个不断的战斗中寻求这位伟大战士的帮助。"},{t="戈穆尔的苦涩",b="戈穆尔对你的归来冷嘲热讽，声称他再也不需要托尔甘的怜悯，并用那些鲜艳的绳子戏弄你。"},{t="一股奇异的力量",b="尽管如此，这颗宝珠还是比戈穆尔预想的要有趣得多，他也注意到了它所散发出的奇异力量。"},{t="心中的迅猛龙",b="当戈穆尔接过宝珠时，他的血液开始沸腾，迅猛龙的狡诈渗透了他的全身。他自言自语地怀疑这是否就是托尔甘所说的萨满之道，随后宣称自己重获新生，力量也随之回归。"}},faq={{q="戈穆尔是谁？",a="戈穆尔是落锤镇的一名意志消沉的战士。托尔甘希望能鼓舞他的精神，让他走上新的道路，从而让部落获得这位伟大战士的帮助。",al={"戈穆尔是谁","戈穆尔背景故事","戈穆尔出了什么问题"}},{q="托尔甘的宝珠有什么用途？",a="它的能量旨在将迅猛龙的精髓灌注给戈穆尔，唤醒他的精神并赋予他新的目标。",al={"宝珠有什么用","托尔甘的宝珠用途","狡诈宝珠"}},{q="这一步之前发生了什么？",a="在此之前先是“迅猛龙的狡诈”，这一步是在此基础上展开的。",al={"上一个任务","前置任务"}}},fp="19,206,13.324.0,20.152.0,15.122.1,17.207.1,15.160.0,37.111.0,27.71.0"}
P.entries["quest:7025"] = {n="冬幕节的礼物",s="在冬幕节期间，扮演铁炉堡冬天爷爷的表演者感到非常疲惫，他请求过往的行人给他送点节日点心。给他送去新鲜出炉的曲奇和冰镇牛奶，就能换取一份节日奖励，并得到他的衷心感谢。",h="在冬幕节期间，扮演铁炉堡冬天爷爷的表演者感到非常疲惫，他请求过往的行人给他送点节日点心。给他送去新鲜出炉的曲奇和冰镇牛奶，就能换取一份节日奖励，并得到他的衷心感谢。",kw={"冬幕节","曲奇","冬天爷爷","冰镇牛奶","铁炉堡","熏木农场","冬天爷爷的馈赠"},ang={["faction:Alliance"]="铁炉堡是联盟主要的冬幕节庆祝中心，吸引了来自东部王国各地的旅行者来到平民区的节日树前。",["profession:Cooking"]="这个任务需要简单的烹饪技能，将小蛋和节日香料混合制作成节日的曲奇。",["race:Dwarf"]="对于矮人来说，冬天爷爷代表着一个与泰坦和冬季馈赠有关的古老传说，尽管看到他在平民区大嚼曲奇让这个神话变得非常接地气。"},sec={{t="坐得太久的漫长一天",b="虽然冬幕节的起源可以追溯到古老的泰坦传说和矮人神话中那位身披寒冬斗篷的不朽人物，但现代的庆祝活动在很大程度上依赖于熏木农场的商业赞助。在铁炉堡平民区的节日树旁，一位普通的矮人每天都要穿着沉重的冬天爷爷装束，倾听市民和孩子们诉说节日愿望，工作十分辛苦。"},{t="烘焙节日欢乐",b="在听了一整天的礼物请求后，扮演冬天爷爷的这位矮人自己也不免感到饥肠辘辘。他并没有要求什么奢华的东西，只是希望能吃上一口简单的慰藉：五个用节日香料制作的新鲜出炉的曲奇，再配上一杯冰镇牛奶。这一交易既让疲惫的节日工作人员得到了一丝喘息，也把善意传播到了这座冰雪覆盖的首都之中。"}},faq={{q="我在铁炉堡哪里能找到冬天爷爷？",a="冬天爷爷坐在铁炉堡平民区的大型节日树和熏木农场展位旁边，周围环绕着节日的装饰品。",al={"冬天爷爷在哪里","铁炉堡冬天爷爷位置","铁炉堡圣诞老人位置"}},{q="如何制作曲奇？",a="配方由冬天爷爷附近的熏木农场商人出售。烘焙它们需要烹饪技能，还需要从节日商人那里购买的节日香料，以及从野生鸟类身上收集的小蛋。",al={"哪里获得曲奇","曲奇配方","如何烘焙曲奇"}},{q="我在哪里能弄到冰镇牛奶？",a="冰镇牛奶可以从联盟各大主城（包括铁炉堡各处的旅店）的几乎任何旅店老板、食物商或饮料商那里买到。",al={"冰镇牛奶商人","哪里买牛奶","铁炉堡牛奶"}},{q="这个冬天爷爷是真正的神话人物吗？",a="不是，他是由熏木农场雇佣的矮人表演者，代表冬幕节庆祝活动中那位与泰坦有关的传说人物。",al={"冬天爷爷是真的吗","铁炉堡的那个人是谁","他是真的冬天爷爷吗"}},{q="完成任务后，冬天爷爷会给你什么？",a="收到曲奇和牛奶后，冬天爷爷会给你一份熏木农场礼物包作为一点心意。",al={"冬天爷爷的馈赠任务奖励","冬天爷爷的邮件","熏木农场样本"}},{q="部落玩家可以完成这个特定任务吗？",a="这个特殊的任务是在铁炉堡提供给联盟玩家的。部落成员有他们自己对应的任务，可以去奥格瑞玛拜访冬天爷爷。",al={"部落能做这个任务吗","部落的冬天爷爷的馈赠"}}},fp="29,214,22.338.0,20.249.0,48.144.0,36.191.0,29.128.0,50.119.0,64.124.1,47.145.0"}
P.entries["quest:703"] = {n="烧烤秃鹰翅膀",s="里格弗兹对烤秃鹫翅膀推崇备至，那是用浓郁的酱汁烹制出的鲜美肉食。除了秃鹫翅膀本身，制作这道菜所需的其他配料他都已经准备好了。只要你能带回足够的翅膀，里格弗兹或许会把食谱传授给你。",h="里格弗兹对烤秃鹫翅膀推崇备至，那是用浓郁的酱汁烹制出的鲜美肉食。除了秃鹫翅膀本身，制作这道菜所需的其他配料他都已经准备好了。只要你能带回足够的翅膀，里格弗兹或许会把食谱传授给你。",kw={"荒芜之地","烧烤","秃鹫","烹饪","食谱","里格弗兹","翅膀"},ang={["profession:Cooking"]="厨师们注意：这道菜的食谱可以作为奖励。"},sec={{t="当地人的最爱",b="里格弗兹以他的烤秃鹫翅膀为荣。酱汁浓郁，肉质鲜美，香气能传到很远的地方，引来饥肠辘辘的食客。制作这道菜的所有配料他都准备好了，就差秃鹫翅膀了。带四只秃鹫翅膀来，里格弗兹或许愿意分享这份食谱。"}},faq={{q="谁想要秃鹫翅膀？",a="里格弗兹想要秃鹫翅膀来做一批烤秃鹫翅膀。",al={"谁提供烤秃鹫翅膀","谁是里格弗兹","任务提供者"}},{q="里格弗兹用什么作为交换？",a="里格弗兹暗示如果你带回足够的翅膀，他就分享食谱。",al={"奖励是什么","我能得到什么","食谱奖励"}},{q="为什么里格弗兹需要秃鹫翅膀？",a="里格弗兹已经有了制作烤秃鹫翅膀所需的其他所有材料，只缺翅膀了。",al={"为什么选秃鹫","里格弗兹的目的","为什么里格弗兹想要翅膀"}},{q="里格弗兹需要多少翅膀？",a="四只秃鹫翅膀。",al={"多少只秃鹫翅膀","秃鹫翅膀数量"}}},fp="23,198,16.268.0,31.74.0,51.65.0,39.109.0,36.19.0"}
P.entries["quest:705"] = {n="潜水采珍珠",s="里格弗兹是一个地精，他发现荒芜之地充满了凶猛的掠食者和胆大的拾荒者，他靠着狡诈手段生存了下来：使用闪光弹吓跑野生动物。碎蓝珍珠粉的存货不多了，所以你被派往荆棘谷的暗礁海去获取更多。",h="里格弗兹是一个地精，他发现荒芜之地充满了凶猛的掠食者和胆大的拾荒者，他靠着狡诈手段生存了下来：使用闪光弹吓跑野生动物。碎蓝珍珠粉的存货不多了，所以你被派往荆棘谷的暗礁海去获取更多。",kw={"荒芜之地","蓝珍珠","闪光弹","潜水采珠","里格弗兹","荆棘谷","暗礁海"},ang={["profession:Engineering"]="工程学玩家很有理由对里格弗兹的闪光弹感兴趣。"},sec={{t="一个狡猾的小地精",b="荒芜之地非常严酷，里格弗兹承认作为一个置身于掠食者和拾荒者当中的矮小地精，他感到很害怕。里格弗兹懂得制作闪光弹的配方，并利用它们吓跑野生动物。其中一种原料快用完了：碎蓝珍珠粉。"},{t="来自暗礁海的珍珠",b="蓝珍珠来自荆棘谷暗礁海里的蛤蜊。里格弗兹开玩笑说你最好穿上结实的靴子，然后他在荒芜之地等着你带回九颗珍珠，并承诺会让你的努力物有所值。"}},faq={{q="为什么里格弗兹需要蓝珍珠？",a="里格弗兹使用碎蓝珍珠粉来制作闪光弹，而这些粉末快用完了。",al={"里格弗兹 珍珠","为什么潜水采珠","为什么需要蓝珍珠"}},{q="蓝珍珠在哪里可以找到？",a="它们可以在荆棘谷暗礁海里的蛤蜊中找到。",al={"蓝珍珠在哪里","蓝珍珠位置","暗礁海珍珠"}},{q="为什么里格弗兹要使用闪光弹？",a="荒芜之地到处都是凶猛的掠食者和胆大的拾荒者，闪光弹可以把这些野生动物吓跑。",al={"为什么使用闪光弹","里格弗兹的防御"}},{q="里格弗兹需要多少蓝珍珠？",a="九颗蓝珍珠，带回荒芜之地交给里格弗兹。",al={"蓝珍珠数量","需要多少珍珠"}}},fp="12,269,22.261.0,20.207.0,37.93.0,32.58.0,36.104.0,42.61.0"}
P.entries["quest:706"] = {n="黑龙之火",s="西格鲁·铁斧正在荒芜之地等待来自铁炉堡的消息，她掌握了一种为武器附上烈焰的技术。这需要从一只罕见的黑龙幼龙尚在跳动的心脏中提取血液，而莱瑟罗峡谷的幼龙正是你要寻找的目标。",h="西格鲁·铁斧正在荒芜之地等待来自铁炉堡的消息，她掌握了一种为武器附上烈焰的技术。这需要从一只罕见的黑龙幼龙尚在跳动的心脏中提取血液，而莱瑟罗峡谷的幼龙正是你要寻找的目标。",kw={"荒芜之地","黑龙心脏","费拉诺·钢趾","烈焰附魔","铁炉堡","莱瑟罗峡谷","灼热幼龙","焦灼卫士","西格鲁·铁斧"},ang={["faction:Alliance"]="西格鲁·铁斧正在等待铁炉堡的消息，而这项工作是为联盟准备的。"},sec={{t="学徒的手艺",b="西格鲁·铁斧在担任费拉诺·钢趾的学徒时，学会了一种特殊的为武器附加烈焰附魔的方法，据最后的消息，费拉诺在洛丹伦的一支狩猎队的铁匠铺里。西格鲁正在等待来自铁炉堡的消息，除此之外她没什么事可做。"},{t="莱瑟罗峡谷的幼龙",b="西格鲁几乎不透露关于这个过程的细节，只说它需要从一只罕见的黑龙幼龙尚在跳动的心脏中提取血液。从那条峡谷的幼龙身上取下一颗心脏交给西格鲁，她就会向你展示这项技艺。那里的灼热幼龙和焦灼卫士就是心脏的来源。"}},faq={{q="是谁教会了西格鲁·铁斧这种附魔技术？",a="西格鲁是在担任费拉诺·钢趾的学徒时学会的，据最后的消息，他曾在洛丹伦的一支狩猎队的铁匠铺工作。",al={"西格鲁的导师","谁训练了西格鲁","费拉诺·钢趾"}},{q="给刀刃附加烈焰需要什么材料？",a="从一只罕见的黑龙幼龙心脏中提取的血液，那颗心脏必须还在跳动。",al={"西格鲁需要什么","黑龙心脏需求","烈焰附魔材料"}},{q="在哪里可以找到黑龙幼龙？",a="在东部荒芜之地的莱瑟罗峡谷。",al={"在哪里寻找黑龙","莱瑟罗峡谷幼龙","黑龙心脏位置"}},{q="为什么西格鲁·铁斧滞留在荒芜之地？",a="西格鲁在等待来自铁炉堡的消息，在此期间她没什么其他事情可忙。",al={"为什么西格鲁在荒芜之地","西格鲁·铁斧的目的"}},{q="哪些生物会掉落所需的心脏？",a="莱瑟罗峡谷的灼热幼龙和焦灼卫士。",al={"什么掉落黑龙心脏","哪些幼龙有心脏"}}},fp="24,242,21.245.0,28.303.0,53.114.0,52.77.0,39.43.0,48.106.0,39.61.0"}
P.entries["quest:708"] = {n="黑盒子",s="一个金属制的黑匣子出现在荒芜之地的巨型秃鹫胃里，其表面严重凹陷，仿佛被酸液浸泡过一样。在其底部的符号下方印着一行字：19号引擎——铁炉堡攻城小队。",h="一个金属制的黑匣子出现在荒芜之地的巨型秃鹫胃里，其表面严重凹陷，仿佛被酸液浸泡过一样。在其底部的符号下方印着一行字：19号引擎——铁炉堡攻城小队。",kw={"荒芜之地","黑匣子","被腐蚀的黑匣子","巨型秃鹫","hall of arms","铁炉堡攻城小队","飞行员比罗·长须"},ang={["faction:Alliance"]="这个匣子上带有铁炉堡的标记，它的线索止于铁炉堡。"},sec={{t="从秃鹫胃中取出",b="这些凹痕表明这个黑匣子在秃鹫的胃里待了很久，酸液一直在腐蚀金属。翻过它，底部印着一个符号，下面写着“19号引擎——铁炉堡攻城小队”。你必须把它带到铁炉堡的Hall of Arms，交给飞行员比罗·长须。"}},faq={{q="这个被腐蚀的黑匣子是从哪里来的？",a="它是在荒芜之地的一只巨型秃鹫的胃里找到的，看起来已经在那里待了很长时间。",al={"匣子来自何处","匣子是怎么到这里的","黑匣子起源"}},{q="匣子上印着什么标记？",a="底部印有一个符号，下方写着“19号引擎——铁炉堡攻城小队”。",al={"匣子上写着什么","黑匣子上的标记","匣子铭文"}},{q="谁应该接收这个匣子？",a="铁炉堡Hall of Arms的飞行员比罗·长须。",al={"谁来接收匣子","黑匣子要送到哪里","我该把匣子交给谁"}}},fp="13,226,20.271.0,43.104.0,37.98.0,35.50.0"}
P.entries["quest:71"] = {n="回复托马斯",s="“向托马斯报告”是艾尔文森林东部的一个任务，内容是关于卫兵托马斯对东部水道附近失踪的暴风城卫兵的调查。冒险者在东部桥梁处协助卫兵托马斯，调查他失踪战友的下落，并报告河流沿岸的情况。",h="“向托马斯报告”是艾尔文森林东部的一个任务，内容是关于卫兵托马斯对东部水道附近失踪的暴风城卫兵的调查。冒险者在东部桥梁处协助卫兵托马斯，调查他失踪战友的下落，并报告河流沿岸的情况。",kw={"桥梁","艾尔文森林","闪金镇","卫兵托马斯","马拉凯","勋章","鱼人","罗尔夫"},ang={["faction:Alliance"]="罗尔夫和马拉凯的死亡说明了艾尔文森林边界的脆弱状态，由于人手短缺，即便是日常的河流巡逻也可能遭到覆灭。",["race:Human"]="找回阵亡卫兵的勋章，让那些死于保卫王国境内道路的暴风城士兵得到了一份荣誉和安息。"},sec={{t="令人沉痛的确认",b="卫兵托马斯在几乎没有多余人手的情况下，守卫着闪金镇和东谷伐木场之间的渡口。当他的两名战友，马拉凯和罗尔夫，在河岸地区失踪时，他仍抱有他们只是被隔绝或耽搁的希望。将他们找回的服役勋章带回桥上，打破了这一希望，证实了两名卫兵已在水道附近遇害。"},{t="水边的威胁",b="几个月来，暴风城的领导层一直将鱼人视为河岸的麻烦制造者而大加忽视，重点关注强盗活动和更广阔的王国边界。两名武装暴风城卫兵在内陆溪流沿岸被屠杀，证明了这是一场有组织的暴行。证据在手，托马斯意识到艾尔文森林的东部边境正面临积极的进攻，这迫使他要求采取应对措施，以免伐木路线和定居点被淹没。"}},faq={{q="卫兵托马斯驻扎在哪里？",a="卫兵托马斯驻扎在艾尔文森林东部跨河的石桥上，那里连接着闪金镇和东谷伐木场之间的道路。",al={"托马斯位置","卫兵托马斯桥梁","卫兵托马斯在哪里"}},{q="罗尔夫和马拉凯是谁？",a="罗尔夫和马拉凯是被派往艾尔文森林东部巡逻的暴风城卫兵。两人都被潜伏在河岸和石碑湖沿岸的鱼人包围并杀害了。",al={"艾尔文森林失踪卫兵","罗尔夫是谁","马拉凯是谁"}},{q="为什么要找回他们的勋章？",a="勋章是暴风城卫兵的正式身份证明。将它们带回为卫兵托马斯提供了确凿的证据，证明他失踪的部下已因公殉职。",al={"为什么要勋章","卫兵勋章的作用"}},{q="为什么鱼人的攻击如此严重？",a="鱼人通常被视为原始、胆怯的害虫，而不是对受训士兵的致命威胁。两名武装卫兵的死亡证明，这些河岸部落已经变得胆大妄为，并且有能力进行协调一致的伏击。",al={"为什么鱼人是威胁","艾尔文森林的鱼人危险吗"}},{q="向托马斯报告后会发生什么？",a="托马斯让你将一份关于卫兵死亡和日益严重的鱼人威胁的报告带给闪金镇的治安官杜汉。杜汉警告说该地区的防御力量已经捉襟见肘。",al={"向托马斯报告后的后续任务","托马斯接下来做什么"}},{q="为什么卫兵托马斯独自驻扎在桥上？",a="随着瓦里安·乌瑞恩国王的失踪和资源的紧张，暴风城的军事力量在全国范围内捉襟见肘。像东部大桥这样的偏远哨所只有极少的人员来保卫重要的交通路线。",al={"为什么托马斯独自一人","暴风城桥梁卫兵为何单独驻守"}}},fp="16,179,19.300.0,26.390.0,30.144.0,26.154.1,36.133.1,41.180.1,44.185.1,47.196.0"}
P.entries["quest:710"] = {n="研究石元素",s="鲁特维尔·沃拉图斯在荒芜之地停留，研究元素束缚枷锁。为了测试一些攻击性法术和几件拼凑起来的小玩意，鲁特维尔需要附近小型岩石元素身上的小型石片。",h="鲁特维尔·沃拉图斯在荒芜之地停留，研究元素束缚枷锁。为了测试一些攻击性法术和几件拼凑起来的小玩意，鲁特维尔需要附近小型岩石元素身上的小型石片。",kw={"荒芜之地","小型岩石元素","鲁特维尔·沃拉图斯","元素束缚枷锁","小型石片","元素研究：岩石"},ang={["class:Mage"]="鲁特维尔的枷锁是为法师们所准备的。"},sec={{t="元素枷锁",b="鲁特维尔·沃拉图斯在荒芜之地这里进行一项研究：元素束缚枷锁。一旦完成，法师们就能召唤出更强大的元素来为他们服务。为了开始这项研究，鲁特维尔需要十块小型石片，你可以轻松地从西边山丘上的小型岩石元素身上获得它们。"}},faq={{q="是谁在要求收集石片？",a="鲁特维尔·沃拉图斯，他因为一项研究工作在荒芜之地停留。",al={"谁发布了这个任务","任务发布者","鲁特维尔·沃拉图斯"}},{q="鲁特维尔·沃拉图斯在研究什么？",a="元素束缚枷锁，旨在让法师们召唤出更强大的元素。",al={"鲁特维尔的项目","元素束缚枷锁","鲁特维尔在建造什么"}},{q="鲁特维尔为什么需要小型石片？",a="它们用于测试鲁特维尔最新的一些攻击性法术和几件拼凑起来的小玩意。",al={"为什么要石片","石片的用途","石片是用来干什么的"}},{q="石片在哪里可以找到？",a="从鲁特维尔西边山丘上的小型岩石元素身上获取。",al={"去哪里找石片","小型岩石元素的位置","石片的来源"}}},fp="27,221,18.314.0,35.70.0,35.87.0,40.95.0,33.72.0"}
P.entries["quest:711"] = {n="研究石元素",s="鲁特维尔·沃拉图斯称赞你的能力远超他所有的学徒，并希望进行下一步的测试。这次需要的是三块大型石板，这种材料最好从岩石元素身上获取。",h="鲁特维尔·沃拉图斯称赞你的能力远超他所有的学徒，并希望进行下一步的测试。这次需要的是三块大型石板，这种材料最好从岩石元素身上获取。",kw={"荒芜之地","大型石板","鲁特维尔·沃拉图斯","岩石元素","石板","元素的研究：岩石"},sec={{t="更大的碎片",b="鲁特维尔·沃拉图斯的研究接下来的部分需要更强的力量。岩石元素拥有更大、更结实的躯体，因此它们更有可能携带着足以用于测试的碎片。鲁特维尔指引你前往更西边，或者沿着群山的边缘向东南方寻找，并让你去收集三块大型石板。鲁特维尔需要一些时间来测试你之前带来的较小的碎片。"},{t="鲁特维尔的期望",b="鲁特维尔的法术正如预料的那样对那些小碎片产生了作用。如果接下来的实验也像预想的那样顺利，那么在鲁特维尔控制下的元素将令之前召唤出的任何东西都黯然失色。"}},faq={{q="是谁派你去收集大型石板的？",a="鲁特维尔·沃拉图斯，他正在荒芜之地工作。",al={"谁给予这个任务","鲁特维尔任务","元素的研究给予者"}},{q="这个请求之前发生了什么？",a="那是早先的“元素的研究：岩石”，你当时给鲁特维尔带来了小的石片。",al={"上一个任务","前一步骤","我之前做了什么"}},{q="鲁特维尔说在哪里可以找到岩石元素？",a="在鲁特维尔所在位置的更西边，或者沿着群山的边缘向东南方向。",al={"元素在哪里","元素位置","哪里寻找石板"}},{q="鲁特维尔为什么需要大型石板？",a="鲁特维尔需要更大的碎片来进行接下来的测试。岩石元素有更大、更强壮的躯体，所以它们的碎片足够大。",al={"为什么要大型石板","石板的目的","鲁特维尔的研究目标"}}},fp="27,202,13.360.0,14.194.0,36.48.0,30.88.0,50.70.0,40.126.0"}
P.entries["quest:712"] = {n="研究石元素",s="鲁特维尔·沃拉图斯需要荒芜之地元素生物掉落的最后一样部件：岩石束缚护腕，它们来自高等岩石元素。据鲁特维尔的计算，这些护腕足以用来衡量他自己那些镣铐的强度。",h="鲁特维尔·沃拉图斯需要荒芜之地元素生物掉落的最后一样部件：岩石束缚护腕，它们来自高等岩石元素。据鲁特维尔的计算，这些护腕足以用来衡量他自己那些镣铐的强度。",kw={"荒芜之地","岩石束缚护腕","高等岩石元素","卡拉诺斯","鲁特维尔·沃拉图斯","卢西恩","食人魔","瑟沃"},sec={{t="衡量镣铐",b="在石板之后，鲁特维尔·沃拉图斯还要从荒芜之地的元素生物身上获取最后一样部件。取自高等岩石元素的岩石束缚护腕应该能让鲁特维尔判断他正在制造的镣铐的强度。如果鲁特维尔的记忆没错的话，他的探知术显示有一群元素生物在西南方向，靠近一些食人魔的地方。他需要五个护腕，这样可以多准备一些备用的，因为瑟沃出了名地会弄丢试剂和研究资料。"}},faq={{q="鲁特维尔为什么需要这些护腕？",a="根据鲁特维尔的计算，岩石束缚护腕足以用来衡量他自己那些镣铐的强度。",al={"为什么需要岩石束缚护腕","护腕的用途","鲁特维尔 束缚护腕"}},{q="鲁特维尔为什么要五个护腕？",a="为了多备一些，因为瑟沃出了名地会弄丢鲁特维尔的试剂和研究资料。",al={"为什么需要五个护腕","需要多少护腕","为什么要备用"}},{q="高等岩石元素在哪里？",a="根据鲁特维尔的探知，它们的一群栖息在鲁特维尔西南方，靠近一些食人魔的地方。卡格营地周围的山丘上就是它们的家。",al={"岩石元素在哪里","高等岩石元素位置","哪里可以找到护腕"}},{q="之前收集的石板怎么样了？",a="一旦这里的工作完成，卢西恩会把多余的石板带回卡拉诺斯，因为它们以后可能还会派上用场。",al={"石板去了哪里","卢西恩 石板","卡拉诺斯 石板"}}},fp="27,219,20.431.0,33.112.0,37.89.0,46.134.0,50.114.0"}
P.entries["quest:713"] = {n="至关重要的冷却剂",s="鲁特维尔·沃拉图斯想要一瓶冰霜之油，用来加固束缚所召唤朋友的枷锁。布洛金是鲁特维尔在奥特兰克的一位地精朋友，他可以教你如何制作这种油。",h="鲁特维尔·沃拉图斯想要一瓶冰霜之油，用来加固束缚所召唤朋友的枷锁。布洛金是鲁特维尔在奥特兰克的一位地精朋友，他可以教你如何制作这种油。",kw={"荒芜之地","布洛金","冷却剂至上","冰霜之油","鲁特维尔·沃拉图斯","奥特兰克废墟","枷锁"},sec={{t="至关重要的冷却剂",b="鲁特维尔·沃拉图斯发誓，没有什么比冰霜之油更能防止引擎或齿轮过热了，作为润滑剂，它的价值无与伦比。它还能帮助魔法物品保持其附魔效果。一瓶冰霜之油将提高鲁特维尔枷锁的魔法容量，使其足够强大，足以阻止他所召唤的朋友杀掉所有人。"},{t="奥特兰克的布洛金",b="鲁特维尔的一位地精朋友布洛金可以教你制作这种油。布洛金就在奥特兰克废墟，他在老城墙上进行售卖。"},{t="当油送到时",b="一旦油送到，鲁特维尔就称其为新护腕的完美冷却剂。鲁特维尔发誓，如果这些附魔无法持续一个世纪，他所有的财产都将归瑟沃所有。鲁特维尔还期待着当工作完成时，议会的法师们会感到敬畏。"}},faq={{q="为什么鲁特维尔·沃拉图斯需要冰霜之油？",a="一瓶冰霜之油可以增加鲁特维尔枷锁的魔法容量，这样它们就足够强大，能阻止他所召唤的朋友杀掉所有人。",al={"为什么需要冰霜之油","冰霜之油的用途","鲁特维尔的油"}},{q="谁知道怎么酿造冰霜之油？",a="鲁特维尔的一位地精朋友布洛金可以教你制作它。他在奥特兰克废墟，在老城的一面墙上。",al={"谁传授冰霜之油","在哪里学习冰霜之油","布洛金的配方"}},{q="冰霜之油有什么特别之处？",a="鲁特维尔说，没有什么比它更能防止引擎或齿轮过热，它作为润滑剂的价值无与伦比，并且它还能帮助魔法物品保持附魔效果。",al={"冰霜之油的特性","为什么冰霜之油很好"}}},fp="21,185,15.338.0,18.158.0,20.268.1,40.141.0,32.124.0,32.171.0"}
P.entries["quest:714"] = {n="发条式什么什么仪",s="在你带着“冷却头领必胜”任务中的冰霜之油交给鲁特维尔·沃拉图斯之后，你发现鲁特维尔依然沉浸在荒芜之地的某个装置里无法自拔。还差一个虽小但至关重要的零件：陀螺仪。",h="在你带着“冷却头领必胜”任务中的冰霜之油交给鲁特维尔·沃拉图斯之后，你发现鲁特维尔依然沉浸在荒芜之地的某个装置里无法自拔。还差一个虽小但至关重要的零件：陀螺仪。",kw={"荒芜之地","装置","冷却头领必胜","陀螺仪","卡拉诺斯","鲁特维尔·沃拉图斯"},ang={["profession:Engineering"]="工程师可以自己制作陀螺仪。"},sec={{t="至关重要的零件",b="鲁特维尔·沃拉图斯因为忙于工作而心不在焉，他说你完成的工作远超标准，并让你如果以后在卡拉诺斯见面，可以去申请一份工作。随后他急忙抓住了什么东西，提出了真正的请求：一个陀螺仪。鲁特维尔承认，这是一个虽小但至关重要的零件。带一个给他，项目应该就能完成了。"},{t="交付零件",b="当你把陀螺仪交给他时，鲁特维尔大喊着一把抓过，说工作真的快完成了，而且这个项目是目前的首要任务。但他承诺完成的时间一直在变，从几分钟到可能还要很久不等。"}},faq={{q="是谁在索要陀螺仪？",a="鲁特维尔·沃拉图斯，他正在荒芜之地研究一个装置。",al={"谁需要陀螺仪","陀螺仪任务发布者","鲁特维尔·沃拉图斯 荒芜之地"}},{q="鲁特维尔·沃拉图斯需要陀螺仪做什么？",a="这是一个虽小但相当关键的零件，有了它，鲁特维尔就能准备完成这个项目了。",al={"为什么需要陀螺仪","鲁特维尔在造什么"}},{q="关于卡拉诺斯的工作机会是怎么回事？",a="鲁特维尔因工作分心，说如果你在卡拉诺斯遇到他，随时可以去申请工作。",al={"鲁特维尔 卡拉诺斯","卡拉诺斯的工作机会"}},{q="在哪里可以找到陀螺仪？",a="工程师可以制作陀螺仪，也可以从工程学供应商那里购买。",al={"如何获得陀螺仪","陀螺仪来源","哪里购买陀螺仪"}}},fp="13,193,14.370.0,15.250.1,36.65.0,53.98.0,33.111.0,35.76.0"}
P.entries["quest:716"] = {n="有备无患",s="卢希恩·枪穗很清楚洛特维尔有多吝啬，他愿意为你付出的辛劳制造点东西作为补偿：用你收集的多余石头制作附魔护腕。卢希恩现在缺的是一件铁匠制造的纹饰青铜护腕。",h="卢希恩·枪穗很清楚洛特维尔有多吝啬，他愿意为你付出的辛劳制造点东西作为补偿：用你收集的多余石头制作附魔护腕。卢希恩现在缺的是一件铁匠制造的纹饰青铜护腕。",kw={"荒芜之地","元素岩石","附魔护腕","鲁特维尔·沃拉图斯","卢希恩·枪穗","纹饰青铜护腕"},ang={["profession:Blacksmithing"]="卢希恩想要的青铜护腕需要通过铁匠获得。"},sec={{t="对你辛苦劳作的答谢",b="在完成了“元素研究：岩石”的试炼后，卢希恩·枪穗承认洛特维尔确实很吝啬，并想补偿你。卢希恩一直在忙于处理你收集的多余石头，他可以用这些石头制造出精良的附魔护腕。这些护腕甚至可能在洛特维尔最新的发明所引发的所谓“即将到来的暴行”中保护你。"},{t="卢希恩需要什么",b="为了完成护腕的制作，卢希恩需要一件铁匠制造的纹饰青铜护腕。卢希恩警告说，最好别等太久，因为没人知道接下来会发生什么。"}},faq={{q="谁提出要制作护腕？",a="位于荒芜之地的卢希恩·枪穗提议用你收集的多余石头为你制作附魔护腕。",al={"谁提供石材胜于布料任务","任务发布者","卢希恩·枪穗"}},{q="卢希恩为什么要为你制作这件护甲？",a="卢希恩了解洛特维尔有多吝啬，他想为你的辛苦付出做点补偿。这或许也能帮你抵御洛特维尔的最新发明。",al={"为什么要制作护腕","卢希恩的动机","洛特维尔吝啬"}},{q="卢希恩完成护腕制作需要什么？",a="纹饰青铜护腕，也就是铁匠能做的那种。",al={"需要什么物品","所需物品","需要纹饰青铜护腕"}},{q="这个任务的前置是什么？",a="它紧接在洛特维尔的第三次“元素研究：岩石”任务之后。",al={"前置任务","石材胜于布料的前置条件"}}},fp="26,220,28.326.0,17.175.0,32.107.0,40.148.0,53.54.0,29.62.0"}
P.entries["quest:7162"] = {n="实验场",s="“试炼场”是哈格丁中尉为那些在奥特兰克向雷矛卫队应征入伍的联盟新兵所设立的入队仪式。为了获得正式的雷矛徽记，申请者必须冒险进入遍布鹰身人的冰翼洞穴，并取回一面插在那里的战旗。在洞穴中证明自己的勇气，是晋升远征军军衔的第一步。",h="“试炼场”是哈格丁中尉为那些在奥特兰克向雷矛卫队应征入伍的联盟新兵所设立的入队仪式。为了获得正式的雷矛徽记，申请者必须冒险进入遍布鹰身人的冰翼洞穴，并取回一面插在那里的战旗。在洞穴中证明自己的勇气，是晋升远征军军衔的第一...",kw={"丹巴达尔","哈格丁","鹰身人","冰翼洞穴","徽记","试炼场","雷矛","雷矛军旗"},ang={["faction:Alliance"]="雷矛远征军代表了联盟在奥特兰克的主要军事行动，结合了矮人的考古野心与对抗部落的领土防御。",["race:Dwarf"]="雷矛卫队主要由寻求先祖遗物和泰坦奥秘的铁炉堡矮人领导，因此这项试炼也是你加入本族最引以为傲的军事单位之一的途径。"},sec={{t="勇气的衡量",b="雷矛卫队正在奥特兰克山谷对霜狼氏族进行着无情的征战。哈格丁中尉在奥特兰克山脉的联盟营地协调部队，他拒绝让毫无经验的新兵在没有经过测试的情况下就进入战场。在授予任何士兵卫队中的正式身份前，哈格丁要求他们进入丹巴达尔西南方危险的冰翼洞穴，以证明自己的技能和胆量。"},{t="冰翼洞穴",b="这项试炼的概念很简单，但执行起来却很致命：一面雷矛军旗插在幽深的地下冰雪隧道之中。洞穴并非空无一物；凶残的冰霜鹰身人筑巢于这片冻土之中，迫不及待地将毫无防备的闯入者撕成碎片。带着完好无损的军旗返回，证明了新兵能够在危险的地形中穿行、经受住残酷掠食者的攻击，并能在压力下保持纪律。"},{t="雷矛徽记",b="在洞穴中幸存并取回军旗，士兵就能获得雷矛新兵徽记，从而正式加入远征军。正如哈格丁所承诺的那样，这枚徽记不仅仅是一个小饰品——它代表着军衔，随着士兵在战场上获得更高的荣誉，它还可以升级，最终有望获得像指挥官之眼这样传奇的荣誉。"}},faq={{q="哈格丁中尉是谁？",a="哈格丁中尉是一位驻扎在奥特兰克山脉的联盟军官，负责雷矛卫队的招募和战场识别工作。他负责测试潜在的战士，并用军事徽记来奖励他们的服务。",al={"哈格丁中尉","哈格丁","谁负责试炼场"}},{q="冰翼洞穴在哪里？",a="冰翼洞穴位于丹巴达尔联盟要塞的西南方，坐落在奥特兰克山谷的冰封地带内。它们是由冰雪和岩石雕凿而成的迷宫般的地下隧道。",al={"冰翼洞穴位置","冰翼洞穴在哪里","军旗位置"}},{q="冰翼洞穴里有什么威胁？",a="洞穴里栖息着凶猛的冰霜鹰身人。哈格丁中尉警告新兵，这些野蛮的生物会毫不犹豫地伏击闯入者，并扯断他们的喉咙。",al={"鹰身人","冰翼洞穴里有什么","冰翼鹰身人"}},{q="为什么雷矛卫队需要进行这项测试？",a="与霜狼兽人的战斗残酷且无情。哈格丁坚持要在新兵加入主力部队前将其筛选出来，以确保每一名扛着军旗的士兵都能在严酷的环境下作战。",al={"为什么要有试炼场","为什么要进行军旗试炼","雷矛入队仪式"}},{q="完成试炼场有什么奖励？",a="完成试炼后，新兵将获得一枚雷矛新兵徽记。随着士兵在奥特兰克山谷积累荣誉，哈格丁会将这枚徽记升级为更强大的版本。",al={"雷矛徽记","指挥官之眼","试炼场奖励"}},{q="哈格丁提到的霜狼氏族是谁？",a="霜狼氏族是一个兽人氏族，自几十年前被流放以来就一直居住在奥特兰克山谷。雷矛卫队认为他们是阻碍联盟在山谷中利益和挖掘工作的敌对野蛮人。",al={"霜狼野蛮人","霜狼氏族是谁","霜狼氏族"}}},fp="15,261,20.299.0,19.273.0,22.299.0,28.213.0,30.140.0,46.119.0,47.192.0,53.151.0,47.220.0"}
P.entries["quest:717"] = {n="大地的震颤",s="加瑞克认定布莱克拉什和赫玛图斯已不可信，无法继续被关押在莱索尔的监狱中。黑龙已经潜入那里，食人魔又夺走了大地印章，因此加瑞克派你去释放并击杀那些幼龙。",h="加瑞克认定布莱克拉什和赫玛图斯已不可信，无法继续被关押在莱索尔的监狱中。黑龙已经潜入那里，食人魔又夺走了大地印章，因此加瑞克派你去释放并击杀那些幼龙。",kw={"布莱克拉什","加瑞克","赫玛图斯","肯瑞托","克拉苏","莱瑟罗峡谷","符文石","大地之印","大地印章","大地的震颤"},ang={["faction:Alliance"]="加瑞克的请求是联盟的任务。"},sec={{t="摇摇欲坠的监狱",b="加瑞克无法再确保布莱克拉什和赫玛图斯会老实呆在监狱里。黑龙现在栖息在莱索尔，而食人魔带走了大地印章。加瑞克认为必须采取更严厉的手段，这些幼龙必须死。"},{t="破除封印",b="三块符文石将这些幼龙禁锢于此，只有大地印章才能取回它们。你将印章用于紫水晶、蛋白石和钻石之柱上，然后将符文石安放进大地之印中。这会释放那两个家伙，然后你要将它们击杀。加瑞克需要你带回布莱克拉什的锁链、赫玛图斯的锁链以及大地印章。"},{t="任务完成后",b="一旦这些幼龙被杀，加瑞克宣布肯瑞托不必再为莱索尔的囚犯而担忧。加瑞克打算向他的主人克拉苏报告这一成功，想必他会感到满意的。"}},faq={{q="谁是布莱克拉什和赫玛图斯？",a="被关押在莱索尔封印之后的幼龙。",al={"布莱克拉什和赫玛图斯","幼龙是谁","莱索尔关押着什么"}},{q="为什么要杀死这些幼龙，而不是继续关押它们？",a="加瑞克无法再确保它们会老实呆在监狱里。黑龙现在栖息在莱索尔，而食人魔带走了大地印章。",al={"为什么要杀死布莱克拉什","为什么要破除监狱","为什么要击杀赫玛图斯"}},{q="如何解除监狱的封印？",a="用大地印章从柱子上取下三块符文石，然后放入大地之印中。",al={"如何打开大地之印","如何召唤布莱克拉什","如何释放幼龙"}},{q="需要给加瑞克带回什么？",a="有三样东西要送回给加瑞克：布莱克拉什的锁链、赫玛图斯的锁链和大地印章。",al={"给加瑞克带回什么","布莱克拉什的锁链","赫玛图斯的锁链"}},{q="这个任务之前是什么任务？",a="这是《大地的震颤》任务的后续。",al={"前置任务","大地的震颤的前置条件"}}},fp="20,225,16.231.0,17.335.0,14.182.1,30.47.0,58.127.0,27.109.0,35.101.0,29.44.0"}
P.entries["quest:718"] = {n="饥肠辘辘",s="为了尽快逃离奥达曼挖掘场，西格鲁·铁斧一行人丢下了马车和箱子。来自柯什营地的食人魔抢走了装有他们所有武器的货车，从那以后，这群人就断粮了。",h="为了尽快逃离奥达曼挖掘场，西格鲁·铁斧一行人丢下了马车和箱子。来自柯什营地的食人魔抢走了装有他们所有武器的货车，从那以后，这群人就断粮了。",kw={"荒芜之地","柯什营地","挖掘场","海市蜃楼","食人魔","西格鲁·铁斧","补给箱","奥达曼"},ang={["faction:Alliance"]="西格鲁·铁斧正在寻求联盟的帮助。"},sec={{t="荒芜之地的饥饿",b="在仓促撤离奥达曼挖掘场时，西格鲁·铁斧和同伴们丢下了许多马车和补给箱。来自柯什营地的食人魔像秃鹫一样搜刮着这些遗弃的物资。他们抢走了装有这群人所有武器的货车，从那以后，他们就再也没吃过东西了。西格鲁承认这非常尴尬，并请求你帮她找回那个补给箱。"},{t="当你回来时",b="当你回来时，西格鲁承认在你离开的时候她吞了一口沙子。西格鲁迅速转移了话题，说他们今晚会出去寻找食物，并且要像国王一样饱餐一顿。"}},faq={{q="西格鲁·铁斧是谁？",a="西格鲁·铁斧是一行人的成员，他们仓促离开了奥达曼挖掘场，现在在荒芜之地陷入了断粮的困境。",al={"西格鲁·铁斧","谁发布海市蜃楼任务","西格鲁是谁"}},{q="为什么西格鲁一行人在挨饿？",a="食人魔抢走了装有他们所有武器和物资的货车，从那以后他们就再也没法弄到食物了。",al={"他们为什么挨饿","为什么没有食物","西格鲁的食物问题"}},{q="谁抢走了被遗弃的补给？",a="当地柯什营地的食人魔，他们一直在搜刮被丢弃的设备。",al={"谁偷了补给箱","柯什营地食人魔","谁抢走了武器"}},{q="西格鲁希望拿回什么？",a="补给箱，那是他们在仓促撤离挖掘场时丢下的。",al={"补给箱","为西格鲁取回什么"}}},fp="7,205,22.364.0,14.192.1,22.123.0,31.114.0,32.81.0,34.71.0"}
P.entries["quest:719"] = {n="矮人的工具",s="勘察员雷杜尔警告说，看起来像是黑铁矮人暗炉氏族的敌人到处都是。他们刚刚袭击了雷杜尔工作的挖掘场，雷杜尔想要回他的幸运矿镐。",h="勘察员雷杜尔警告说，看起来像是黑铁矮人暗炉氏族的敌人到处都是。他们刚刚袭击了雷杜尔工作的挖掘场，雷杜尔想要回他的幸运矿镐。",kw={"荒芜之地","黑铁矮人","挖掘","哈默托","幸运矿镐","雷杜尔","暗炉"},sec={{t="挖掘场袭击者",b="据勘察员雷杜尔所述，黑铁矮人暗炉氏族袭击了他工作的挖掘场。他们杀死了几乎所有人，包括雷杜尔的老板哈默托，而雷杜尔死里逃生。该挖掘场位于雷杜尔所处位置的北面。"},{t="一把幸运矿镐",b="雷杜尔正在想办法夺回一些遗失的货物，尤其是他的幸运矿镐。一定是某个黑铁矮人拿走了它，虽然具体是谁还不确定。雷杜尔希望你能帮忙，他正在哈默托挖掘场南面等着。"}},faq={{q="勘察员雷杜尔是谁？",a="雷杜尔曾在黑铁矮人袭击的挖掘场工作。他死里逃生，现在正在哈默托挖掘场南面等待。",al={"雷杜尔是谁","勘察员雷杜尔","谁发布了矮人和他的工具"}},{q="是谁袭击了挖掘营地？",a="看起来像是暗炉氏族的黑铁矮人。",al={"谁袭击了挖掘场","谁袭击了哈默托","什么袭击了营地"}},{q="哈默托怎么了？",a="哈默托是雷杜尔的老板，在这次袭击中丧生了。",al={"哈默托是谁","哈默托还活着吗","老板哈默托怎么了"}},{q="幸运矿镐在哪里？",a="雷杜尔认为某个黑铁矮人身上带着它，虽然可能是他们中的任何一个。",al={"雷杜尔的幸运矿镐在哪里","如何找到矿镐","谁拿走了雷杜尔的矿镐"}}},fp="21,189,18.287.0,12.233.0,25.131.0,33.59.0,27.70.0,32.76.0"}
P.entries["quest:72"] = {n="斯塔文的传说",s="这段调查将搜索者引向暴风城的运河，管理员弗索姆在那里照看着破败的弗林特里奇家族遗留下的财产。为了寻找关于神秘的斯塔文·密斯曼托的答案，冒险者们必须翻找装箱的遗产，同时还要面对与过去那场大屠杀有关的、不安的灵魂。",h="这段调查将搜索者引向暴风城的运河，管理员弗索姆在那里照看着破败的弗林特里奇家族遗留下的财产。为了寻找关于神秘的斯塔文·密斯曼托的答案，冒险者们必须翻找装箱的遗产，同时还要面对与过去那场大屠杀有关的、不安的灵魂。",kw={"运河","管理员弗索姆","暮色森林","弗林特里奇","弃灵","斯塔文的传说","大屠杀","密封的箱子","暴风城","蒂洛亚"},ang={["class:Priest"]="在城市运河中面对哭泣的弃灵，揭示了那些在生前被谋杀的无辜灵魂挥之不去的痛苦，她们渴望圣光的平静。",["faction:Alliance"]="弗林特里奇家族的静默悲剧就在王国的首都上演，揭示了即使是暴风城最受庇护的贵族血脉也可能被暴力毁灭。"},sec={{t="大屠杀的回响",b="追踪斯塔文的动向将人从暮色森林阴暗的树林中引向暴风城中心。在城市运河旁，管理员弗索姆照看着弗林特里奇家族仅存的这点家当。据弗索姆所言，他的父亲曾在该庄园供职，并承担了清理那场恐怖家族大屠杀后血迹的骇人任务——那是一场以某种方式与斯塔文这个名字联系在一起的悲剧。"},{t="没落家族的拍卖会",b="由于弗林特里奇家族的信托基金已彻底枯竭，且王国税收的秃鹫盘旋不去，该家族幸存的传家宝和打包好的财物已被列入拍卖名单。在流血事件中幸存下来的纪念品和文件被堆放在运河岸边的运输箱里。要揭开斯塔文的线索，就必须在这些庄园遗留的世俗财物被王国各地的收藏家瓜分之前，撬开这些密封的箱子。"},{t="不安的阴影",b="惊动死者的箱子不会不被察觉。谋杀带来的创伤依然附着在这些被抢救出来的财物上，化身为一个复仇的弃灵，攻击任何搜查这些家族遗物的人。这个哭泣的幽影被认为是年轻的蒂洛亚·弗林特里奇的幻影，她依然强烈地依附于她那被突然夺走的生命所留下的实物遗迹上。"}},faq={{q="我在哪里可以找到管理员弗索姆？",a="管理员弗索姆驻扎在暴风城的运河边，站在水道旁的一堆废弃的运输箱和家什附近。",al={"管理员弗索姆位置","弗索姆在哪里","管理员弗索姆在暴风城的什么地方"}},{q="弗林特里奇家族发生了什么事？",a="弗林特里奇一家是一个富裕的家庭，被一场突如其来的残暴大屠杀拆散。正如管理员的传闻所揭示的那样，那场血腥屠杀规模之大，以至于弗索姆的父亲不得不负责清理庄园。谁是罪魁祸首尚不清楚。",al={"弗林特里奇大屠杀","大屠杀是什么","谁杀了弗林特里奇一家"}},{q="为什么家族的财物被打包放在运河边的箱子里？",a="悲剧发生后，弗林特里奇家族的信托基金彻底枯竭。面对王国税务官的压力，庄园幸存的财物被装箱并放置在运河边，等待拍卖清算。",al={"为什么要拍卖弗林特里奇的物品","为什么箱子在运河里","弗林特里奇信托基金"}},{q="为什么打开箱子时会有灵魂发动攻击？",a="大屠杀带来的暴力创伤使受害者的灵魂被束缚在他们生前的财物上。现身保护这些箱子的弃灵被普遍认为是蒂洛亚·弗林特里奇，即遇害儿童之一的幽影。",al={"暴风城的弃灵","弃灵是谁","为什么运河里有鬼魂"}},{q="这与暮色森林有什么联系？",a="调查始于夜色镇，是对斯塔文·密斯曼托的失踪人口查询。追溯他的历史，发现他曾是艾尔文和暴风城弗林特里奇家族的家庭教师。",al={"斯塔文与暮色森林的联系","为什么暮色森林的任务要把我们带到暴风城","斯塔文传说与城市的联系"}},{q="在密封的箱子里能找到什么？",a="翻找打包的家具和个人物品会发现发霉的传家宝，而在底部附近，有一页斯塔文日记的残页，它成为了下一条线索。",al={"箱子里有什么","密封的箱子线索","弗林特里奇的箱内物品"}}},fp="21,221,20.311.0,29.334.0,16.285.1,34.133.0,39.174.0,66.178.0,50.210.0,39.179.0,41.155.0"}
P.entries["quest:720"] = {n="一线希望",s="一张揉皱的地图上潦草地写着几个字：铁趾向雷杜尔发出的求救信号，说他们要把铁趾带去奥达曼，并请求援助。勘察员雷杜尔应该知道铁趾格雷兹还活着。",h="一张揉皱的地图上潦草地写着几个字：铁趾向雷杜尔发出的求救信号，说他们要把铁趾带去奥达曼，并请求援助。勘察员雷杜尔应该知道铁趾格雷兹还活着。",kw={"希望的信号","荒芜之地","粉笔字条","揉皱的地图","铁趾格雷兹","勘察员雷杜尔","奥达曼"},sec={{t="粉笔字迹",b="在这张揉皱的地图上，用粉笔潦草地写着一张落款为铁趾的短条。它写给雷杜尔，内容仅提到他们要把铁趾带去奥达曼，并需要帮助。要带给勘察员雷杜尔的消息是：铁趾格雷兹还活着。"}},faq={{q="揉皱的地图上写着什么？",a="一张用粉笔写的字条，收件人是雷杜尔，署名是铁趾。上面写着他们要把铁趾带去奥达曼，并请求帮助。",al={"字条上写了什么","地图上的粉笔留言","揉皱的地图文本"}},{q="勘察员雷杜尔是谁？",a="这张字条的收件人。你应该去寻找勘察员雷杜尔，并告诉他铁趾格雷兹还活着。",al={"雷杜尔是谁","把揉皱的地图带到哪里"}},{q="字条上说铁趾格雷兹被带到哪里去了？",a="奥达曼。",al={"铁趾被带到了哪里","格雷兹被带到了哪里"}}},fp="14,206,14.259.0,36.122.0,25.108.0,57.11.0"}
P.entries["quest:723"] = {n="铁趾的遗愿",s="铁趾格雷兹在处理伤口的同时，让你带着护符去贫瘠之地找勘察员雷杜尔。雷杜尔知道铁趾在寻找什么，也知道绝不能让黑铁氏族找到它。",h="铁趾格雷兹在处理伤口的同时，让你带着护符去贫瘠之地找勘察员雷杜尔。雷杜尔知道铁趾在寻找什么，也知道绝不能让黑铁氏族找到它。",kw={"希望的征兆","荒芜之地","铁趾格雷兹","铁趾的护符","起源","勘察员雷杜尔","黑铁"},sec={{t="雷杜尔的护符",b="铁趾格雷兹捂着伤口，停下来稳住身形，然后请求你找到雷杜尔并把护符交给他。铁趾确信雷杜尔知道该怎么做。雷杜尔知道铁趾一直在寻找他们族人的起源，而且铁趾也意在挫败黑铁氏族，绝不能让他们得到这些卷轴。"},{t="雷杜尔的接手",b="雷杜尔在收到铁趾的护符后说，当人们以为铁趾已死时，士气反而更高，因为确切的死讯只会让痛苦加剧。雷杜尔称这个护符是铁趾毕生的心血，并誓言他的死不会毫无意义。"}},faq={{q="谁是勘察员雷杜尔？",a="勘察员雷杜尔就是你要将铁趾的护符送去的人，他在荒芜之地。雷杜尔知道铁趾在寻找什么。",al={"勘察员雷杜尔","谁是雷杜尔","雷杜尔在哪里"}},{q="铁趾格雷兹想要阻止什么？",a="铁趾想要阻止黑铁氏族，绝不能让他们得到那些卷轴。",al={"铁趾的目标","黑铁卷轴","为什么要阻止黑铁"}},{q="铁趾格雷兹在寻找什么？",a="据铁趾所言，他在寻找他们族人的起源。",al={"铁趾起源","铁趾在寻找什么"}},{q="这一步属于哪个任务线？",a="这属于以“希望的征兆”为开端的任务线。",al={"信仰的征兆任务线","希望的征兆任务线"}}},fp="17,195,20.348.0,17.246.1,25.126.0,38.100.0,32.52.0,33.57.0"}
P.entries["quest:724"] = {n="铁趾的遗愿",s="勘察员雷杜尔让你带着铁趾的护符前往铁炉堡。史学家卡尼克和铁趾曾经合作寻找奥达曼失落的文物，雷杜尔猜测暗炉部族发现他们知道的信息比表现出来的要多。",h="勘察员雷杜尔让你带着铁趾的护符前往铁炉堡。史学家卡尼克和铁趾曾经合作寻找奥达曼失落的文物，雷杜尔猜测暗炉部族发现他们知道的信息比表现出来的要多。",kw={"荒芜之地","铁趾","铁趾的护符","史学家卡尼克","铁炉堡","信念的展望","勘察员雷杜尔","暗炉部族","奥达曼"},sec={{t="致铁炉堡的消息",b="雷杜尔斟酌着谁可能知道下一步该做什么，最终决定是身在铁炉堡的史学家卡尼克。你要告诉卡尼克铁趾身上发生了什么，并把护符交到这位史学家手中。卡尼克会告知接下来该做什么。"},{t="卡尼克的欢迎",b="卡尼克起初只把你当作另一个来浪费他时间的旅行者，直到你出示了护符。这时卡尼克才认真对待此事，将对铁趾的哀悼暂且搁置，并召唤出铁趾的灵魂向你展示为什么这个护符如此重要。"}},faq={{q="谁开启了这个任务？",a="位于荒芜之地的勘察员雷杜尔让你带着铁趾的护符前往铁炉堡。",al={"谁给予信念的展望","信念的展望任务发布者","哪里开始信念的展望"}},{q="史学家卡尼克在哪里？",a="史学家卡尼克在铁炉堡。",al={"卡尼克在哪里","史学家卡尼克位置","卡尼克铁炉堡"}},{q="为什么要选择史学家卡尼克？",a="卡尼克和铁趾曾经合作寻找奥达曼失落的文物，所以雷杜尔相信卡尼克知道该怎么做。",al={"为什么要将护符送给卡尼克","卡尼克关联"}},{q="这个任务之后是什么？",a="卡尼克的故事线在“传递威胁的消息”中继续。",al={"信念的展望后的下一个任务","信念的展望后续"}}},fp="17,239,23.251.0,16.273.1,22.84.0,34.33.0,32.125.0,28.68.0"}
P.entries["quest:725"] = {n="亡者的警告",s="史学家卡尼克交给你一封给顾问贝尔格拉姆的密封信函。你必须告诉贝尔格拉姆你所目击的一切，并询问他打算如何处理，与此同时，卡尼克将就荒芜之地的黑铁矮人一事向铁趾的灵魂寻求指引。",h="史学家卡尼克交给你一封给顾问贝尔格拉姆的密封信函。你必须告诉贝尔格拉姆你所目击的一切，并询问他打算如何处理，与此同时，卡尼克将就荒芜之地的黑铁矮人一事向铁趾的灵魂寻求指引。",kw={"顾问贝尔格拉姆","荒芜之地","铁趾","史学家卡尼克","铁炉堡","传递威胁的消息","黑铁矮人"},sec={{t="给顾问贝尔格拉姆的口信",b="卡尼克希望你尽快找到顾问贝尔格拉姆，告诉他你所看到的一切，并询问他打算如何处理。信中解释了更多细节。与此同时，卡尼克将与铁趾的灵魂交谈，希望铁趾知道能阻止黑铁矮人在荒芜之地的所作所为的方法，他只能祈祷事实确实如此。"}},faq={{q="是谁派你去找顾问贝尔格拉姆的？",a="史学家卡尼克交给你一封密封的信函，并让你尽快找到顾问贝尔格拉姆。",al={"谁开启了传递威胁的消息","谁给予了传递威胁的消息","卡尼克任务"}},{q="卡尼克希望顾问贝尔格拉姆做些什么？",a="卡尼克希望你将目击的情况告知贝尔格拉姆，并询问他打算如何处理。信中解释了更多情况。",al={"为什么拜访贝尔格拉姆","贝尔格拉姆信函的目的","为什么要发送这封信"}},{q="当你去送信时，史学家卡尼克在做什么？",a="卡尼克打算花时间与铁趾的灵魂交谈，希望能获悉一些有助于阻止荒芜之地黑铁矮人的线索。",al={"卡尼克在做什么","卡尼克的计划","史学家卡尼克荒芜之地"}},{q="“传递威胁的消息”的前置任务是什么？",a="它接续“信仰的前景”任务，在那一步中，你将铁趾的护符带给了铁炉堡的卡尼克。",al={"传递威胁的消息前置条件","传递威胁的消息的上一个任务","前序任务"}}},fp="24,227,24.321.0,33.97.0,43.113.0,58.130.0,49.100.0"}
P.entries["quest:726"] = {n="亡者的警告",s="顾问贝尔格拉姆阅读了史学家卡尼克的字条，并以国王的名义让你带话回去给卡尼克：根据已知情报迅速果断地采取行动，阻止暗炉氏族在荒芜之地的所作所为。",h="顾问贝尔格拉姆阅读了史学家卡尼克的字条，并以国王的名义让你带话回去给卡尼克：根据已知情报迅速果断地采取行动，阻止暗炉氏族在荒芜之地的所作所为。",kw={"苦痛堡垒","荒芜之地","贝尔格拉姆","卡尼克","暗炉氏族","奥达曼"},sec={{t="贝尔格拉姆的答复",b="贝尔格拉姆读完了字条，双眼圆睁，称这是个坏消息。他让你返回卡尼克那里，并以国王的名义传达指示：必须迅速果断地根据这些情报采取行动。暗炉氏族在荒芜之地的活动必须停止。"},{t="卡尼克的回复",b="卡尼克将此视为国王本人的急令，并已准备好了一个计划：通过打击苦痛堡垒来迟滞奥达曼内暗炉氏族的行动，那里正是他们进行运作的大本营。"}},faq={{q="谁让你返回卡尼克那里？",a="顾问贝尔格拉姆，在读过卡尼克的字条后。你带着国王的命令，要求迅速果断地采取行动。",al={"谁下达了命令","贝尔格拉姆的命令","荒芜之地王室权威"}},{q="贝尔格拉姆想怎么处理暗炉氏族？",a="贝尔格拉姆希望卡尼克迅速而坚定地采取行动，并结束暗炉氏族在荒芜之地的所作所为。",al={"贝尔格拉姆想要什么","荒芜之地暗炉氏族指令"}},{q="此前的任务是什么？",a="你在之前的“传递威胁的消息”中将卡尼克的密封字条带给了顾问贝尔格拉姆，该任务是在“信仰的前景”步骤之后进行的。",al={"上一步骤","传递威胁的消息之前的任务","荒芜之地引导任务"}}},fp="24,221,16.268.0,14.177.1,29.120.0,50.116.0,22.136.0"}
P.entries["quest:727"] = {n="远赴铁炉堡",s="迷失者塞尔杜林派遣你去铁炉堡，并带上徽章。在Forlorn Cavern的一家商店里，葛利·硬骨会把你误认为是塞尔杜林躲避的那些人中的一员，你需要向葛利索要雅格因的笔记。",h="迷失者塞尔杜林派遣你去铁炉堡，并带上徽章。在Forlorn Cavern的一家商店里，葛利·硬骨会把你误认为是塞尔杜林躲避的那些人中的一员，你需要向葛利索要雅格因的笔记。",kw={"荒芜之地","forlorn cavern","葛利·硬骨","铁炉堡","战锤徽章","迷失者塞尔杜林","雅格因的笔记"},sec={{t="一本古老的书",b="石板告诉了塞尔杜林很多信息，但还远远不够。雅格因在很久以前写下了一本笔记，而塞尔杜林躲避的那些人在许多地方都保留着副本，并由他们最有学识的人进行研读。塞尔杜林认为其中蕴含着可以提供保护的博大知识，并希望将其取回。"},{t="Forlorn Cavern的商店",b="葛利·硬骨在铁炉堡的Forlorn Cavern经营着一家商店。塞尔杜林交给你战锤徽章并让你展示给葛利看，这样你就会被误认为是他们的一员，然后你就可以索要雅格因的笔记了。"},{t="葛利的问候",b="葛利警告你要小心店内触碰的东西，因为知识可能是致命的。当你出示徽章时，葛利会以兄弟或姐妹的身份欢迎你，并赞美地底的居民。"}},faq={{q="为什么塞尔杜林需要雅格因的笔记？",a="石板告诉了塞尔杜林很多信息，但还不够。这本笔记由雅格因在很久以前写成，其中蕴含着可以提供保护的博大知识，塞尔杜林希望能将其取回。",al={"为什么需要雅格因的笔记","雅格因的笔记是什么","雅格因的笔记用途"}},{q="葛利·硬骨在哪里？",a="葛利·硬骨在铁炉堡的Forlorn Cavern里经营着一家商店。",al={"葛利·硬骨在哪里","葛利·硬骨位置","葛利是谁"}},{q="战锤徽章是用来做什么的？",a="塞尔杜林把它交给你是为了展示给葛利·硬骨看，这样葛利就会认为你是塞尔杜林躲避的那群人中的一员。",al={"徽章有什么用","战锤徽章的用途","为什么要使用徽章"}},{q="这个任务在任务链中处于什么位置？",a="它紧接在迷失者塞尔杜林的“毁灭的解决方案”任务之后，并会继续进行任务链的下一步。",al={"去铁炉堡寻找雅格因的笔记之前是什么任务","雅格因任务链顺序"}}},fp="32,204,23.283.0,30.207.0,17.189.1,40.176.0,25.65.0,41.114.0,33.103.0"}
P.entries["quest:728"] = {n="远赴幽暗城",s="迷失者塞尔杜林让你带着一枚徽章前往洛丹伦的幽暗城。你需要让看守者贝尔杜加把你误认为是塞尔杜林所逃避的那些人中的一员，并向这位看守者索要《雅格因的笔记》。",h="迷失者塞尔杜林让你带着一枚徽章前往洛丹伦的幽暗城。你需要让看守者贝尔杜加把你误认为是塞尔杜林所逃避的那些人中的一员，并向这位看守者索要《雅格因的笔记》。",kw={"荒芜之地","贝尔杜加","笔记","战锤","徽章","塞尔杜林","幽暗城","雅格因"},sec={{t="一本写于久远之前的书",b="这块石板告诉了塞尔杜林很多信息，但还远远不够。雅格因在很久以前写下了一本笔记，而塞尔杜林所逃避的那些人在许多地方都保留着副本，并由他们中最博学的人进行研读。塞尔杜林相信其中蕴含着巨大的知识，能够保护他们，因此想要把它找回来。"},{t="幽暗城的看守者",b="看守者贝尔杜加就在洛丹伦的幽暗城。塞尔杜林给了你战锤徽章，让你出示给看守者看，这样你就会被误认为是他们的一员，从而向他索要这本笔记。"},{t="警告之言",b="贝尔杜加把你当作一个热切的收藏追求者来迎接，并警告说知识能让强者更强，却会令弱者疯狂。一旦出示了徽章，贝尔杜加就叮嘱你要谨慎对待这样的标志。有些人并不相信他们的誓言是正义的，还有些人如果知道了他们的存在，就会想方设法让他们失败。那些共同守誓的人必须时刻保持小心、警惕和耐心。"}},faq={{q="是谁派你前往幽暗城的？",a="迷失者塞尔杜林派你带着战锤徽章去寻找看守者贝尔杜加。",al={"谁发布了这个任务","谁给予前往幽暗城寻找雅格因的笔记的任务","任务发布者"}},{q="战锤徽章有什么用？",a="塞尔杜林把它交给你，让你出示给看守者贝尔杜加看，这样看守者就会以为你是塞尔杜林所逃避的那些人中的一员。",al={"战锤徽章的用途","为什么我需要这枚徽章","这枚徽章有什么作用"}},{q="什么是《雅格因的笔记》？",a="这是雅格因在久远年代之前写下的一本书。塞尔杜林说它蕴含着巨大的知识，并由塞尔杜林所逃避的那些人中最博学的一群人进行研读。",al={"什么是雅格因的笔记","雅格因是谁","雅格因之书"}},{q="看守者贝尔杜加在哪里？",a="看守者贝尔杜加待在洛丹伦的幽暗城，你可以在那里找到他。",al={"看守者贝尔杜加的位置","在哪里找到看守者贝尔杜加","贝尔杜加 幽暗城"}},{q="在此之前发生了什么？",a="这是紧接在“毁灭的解决之道”之后的任务。",al={"前置任务","在此之前有什么任务","毁灭的解决之道关联"}}},fp="36,193,23.279.0,27.192.0,17.394.1,31.85.0,36.119.0,24.143.0,26.80.0,22.28.0"}
P.entries["quest:729"] = {n="健忘的勘察员",s="考古学家霍莉在黑海岸南部的一处发掘现场被敌对的石元素攻占后，逃到了奥伯丁。她为她的资深同事感到担忧，请求旅行者火速南下，拯救勘察员雷姆塔维尔。这位受人尊敬的矮人学者在沉迷研究时，对致命的危险常常视而不见。",h="考古学家霍莉在黑海岸南部的一处发掘现场被敌对的石元素攻占后，逃到了奥伯丁。她为她的资深同事感到担忧，请求旅行者火速南下，拯救勘察员雷姆塔维尔。这位受人尊敬的矮人学者在沉迷研究时，对致命的危险常常视而不见。",kw={"奥伯丁","黑海岸","探险者协会","化石","石元素","灰须","霍莉","雷姆塔维尔"},ang={["faction:Alliance"]="这个任务凸显了铁炉堡研究员的合作，他们试图在卡利姆多研究其暗夜精灵盟友那些陌生而古老的土地。",["race:Dwarf"]="对矮人而言，雷姆塔维尔体现了探险者协会那种痴迷的好奇心和狭隘的专注，为了一个未被编目的化石，甚至不惜冒生命危险。"},sec={{t="危险的挖掘",b="考古学家霍莉受探险者协会派遣，在灰须大师的命令下跨海而来，并为能成为勘察员雷姆塔维尔的学徒感到激动不已。雷姆塔维尔因其开创性的发现而在铁炉堡的学术界享有盛誉，他受命调查黑海岸蛮荒海岸线上的古代遗迹。然而，在发掘看似一个古代伟大文明遗迹的过程中，暴躁的石元素从地底喷涌而出，迅速占领了发掘现场。"},{t="无视厄运",b="当霍莉惊慌失措地逃往暗夜精灵的港口奥伯丁寻求帮助时，雷姆塔维尔却几乎连眼皮都没抬一下。这位年迈的勘察员完全沉浸在自己发掘出的遗物中，依然深陷废墟之中，对环绕在营地周围的笨重构造体毫不在意。任何在奥伯丁南部找到他的人，都会发现他并非在恐惧中畏缩，而是在抱怨丢失的石刷和找不见的化石。"}},faq={{q="勘察员雷姆塔维尔是谁？",a="勘察员雷姆塔维尔是隶属于铁炉堡探险者协会的著名矮人研究员。他在矮人学院中以其里程碑式的发现而闻名，同时也因每当贵重遗物在侧时极度缺乏对周围环境的感知而臭名昭著。",al={"雷姆塔维尔","勘察员雷姆塔维尔背景故事","勘察员是谁"}},{q="为什么考古学家霍莉会在奥伯丁？",a="霍莉是由灰须大师指派给雷姆塔维尔担任助手的。当危险的石元素从发掘现场的地面下钻出时，她向北逃往奥伯丁寻求增援，以组织营救。",al={"考古学家霍莉","霍莉 奥伯丁","霍莉为何逃跑"}},{q="矮人们在黑海岸发掘什么？",a="这次探险队发现了黑海岸地下埋藏着一个古代先进社会的证据。在发掘现场被地下的构造体占领之前，雷姆塔维尔发现了一块神秘的化石和各种石制文物。",al={"雷姆塔维尔在挖掘什么","黑海岸挖掘点","雷姆塔维尔 化石"}},{q="在哪里可以找到勘察员雷姆塔维尔？",a="雷姆塔维尔位于黑海岸南部，栖身于奥伯丁以南的古代遗迹中，周围环绕着危险的石元素，他仍在执着地寻找他的石刷和化石。",al={"雷姆塔维尔在哪里","雷姆塔维尔位置","寻找勘察员雷姆塔维尔"}},{q="是谁派出了这支前往黑海岸的探险队？",a="这次探险由铁炉堡的探险者协会组织，并由灰须大师直接指派，他委派霍莉协助雷姆塔维尔对该地区的古代奇观进行编目。",al={"谁派出的霍莉","灰须大师","探险者协会 黑海岸"}},{q="雷姆塔维尔真的有危险吗？",a="是的。敌对的石元素在他周围的废墟中游荡。雷姆塔维尔对迫在眉睫的威胁毫无察觉，完全专注于记录他的发现，并纳闷他的工具和助手都跑到哪儿去了。",al={"雷姆塔维尔死了吗","雷姆塔维尔存活","帮助雷姆塔维尔"}}},fp="28,221,14.421.0,17.373.0,28.236.0,41.165.0,46.208.0,40.191.0,38.186.0,30.194.0"}
P.entries["quest:730"] = {n="黑海岸的麻烦事",s="“黑海岸的麻烦？”是一个联盟入门任务，由达纳苏斯的首席考古学家杜瑟·灰须提供。由于派往海对岸的挖掘队已经失联数周，他感到非常担忧，于是请求旅行者前往奥伯丁调查他们的失踪情况。该任务将矮人的学术考察队与黑海岸那片荒凉而阴暗的海岸连接了起来。",h="“黑海岸的麻烦？”是一个联盟入门任务，由达纳苏斯的首席考古学家杜瑟·灰须提供。由于派往海对岸的挖掘队已经失联数周，他感到非常担忧，于是请求旅行者前往奥伯丁调查他们的失踪情况。该任务将矮人的学术考察队与黑海岸那片荒凉而阴暗...",kw={"考古学家","奥伯丁","黑海岸","达纳苏斯","探险者协会","杜瑟·灰须","霍莉","黑海岸的麻烦"},ang={["faction:Alliance"]="这项任务展示了铁炉堡与达纳苏斯之间日益加强的合作，将泰达希尔与卡利姆多大陆的旅行者联系在一起。",["race:Dwarf"]="对于矮人来说，这个任务涉及探险者协会在各大陆挖掘泰坦传说和古代历史的传统。",["race:NightElf"]="暗夜精灵可能会以审慎的消遣或安静的担忧，来看待这些挥舞着镐头的矮人挖掘者出现在他们祖先的海岸遗迹中。"},sec={{t="沉寂的考察队",b="在宏伟的暗夜精灵主城达纳苏斯，来自铁炉堡的矮人研究员们正在探索卡利姆多的古老谜团。首席考古学家杜瑟·灰须派遣了一支挖掘队跨过海峡前往黑海岸，试图发掘古代文物。然而数周过去了，挖掘队没有发回任何信件或进度报告，这让杜瑟·灰须感到忧心忡忡，担心他的考察队员遇到了他们单枪匹马无法应付的危险。"},{t="未被掩埋的威胁",b="杜瑟·灰须感叹道，许多联盟成员都认为矮人的考古学不过是一种古怪的爱好。然而，在Khaz Modan的发现让他的同事们相信，一股古老而恐怖的力量正在威胁着从Lordaeron到卡利姆多的整个Azeroth。在黑海岸的遗迹中挖掘不仅仅是一项学术工作，更是一次了解历史大灾变以及埋藏在古代土壤之下的深层威胁的尝试。"},{t="奥伯丁的联络人",b="在从泰达希尔乘船穿过海峡到达奥伯丁的海岸港口后，旅行者会发现考古学家霍莉正在镇上等待。由于首席考古学家派来了援手，她感到如释重负，并向旅行者透露考察队确实陷入了困境，他们在沿海岸向下搜索古代遗物时遇到了麻烦。"}},faq={{q="谁发布了“黑海岸的麻烦？”这个任务？",a="在暗夜精灵主城达纳苏斯，首席考古学家杜瑟·灰须发布了这个任务，他正在寻找勇敢的冒险者去查看失踪队员的情况。",al={"谁发布了黑海岸的麻烦","黑海岸的麻烦任务发布者","在哪接黑海岸的麻烦任务"}},{q="我需要去哪里完成这个任务？",a="你需要从达纳苏斯渡海前往黑海岸的港口城镇奥伯丁，在那里你会找到考古学家霍莉。",al={"我该去哪","交付地点","找谁交付任务"}},{q="为什么矮人考古学家会出现在达纳苏斯和黑海岸？",a="继在Khaz Modan的近期发现之后，矮人研究员开始调查卡利姆多各处的古代遗址，以发掘关于威胁Azeroth的古老力量的线索。",al={"为什么矮人在达纳苏斯","在黑海岸的矮人","矮人考古卡利姆多"}},{q="找到考古学家霍莉后会发生什么？",a="与奥伯丁的考古学家霍莉交谈后，可以直接开启“健忘的勘察员”任务，要求你深入黑海岸的荒野，寻找勘察员雷姆塔维尔。",al={"what comes next","后续任务","下一个任务"}},{q="为什么挖掘队没有发回报告？",a="团队在黑海岸的实地考察中遇到了意想不到的危险和挫折，导致队员们分散开来，无法与达纳苏斯取得联系。",al={"挖掘队发生了什么","为什么他们失踪了","队员失踪"}},{q="杜瑟·灰须提到的隐忧是什么？",a="杜瑟·灰须提到了在Khaz Modan出土的发现，这些发现暗示着在Azeroth的古老遗迹深处，正沉睡着一种古老且无处不在的危险。",al={"什么古老威胁","杜瑟·灰须的警告","khaz modan的威胁"}}},fp="21,213,19.387.0,16.385.0,20.283.1,42.125.0,45.102.0,58.154.0,48.164.0,45.147.0,48.132.0"}
P.entries["quest:731"] = {n="健忘的勘察员",s="在黑海岸南部的废墟深处，勘察员雷姆塔维尔拒绝离开他的挖掘场，因为他没有带回任何成果向探险者协会交差。尽管他极其健忘，而且还有敌对的穴居人出没，但他坚持要找到一块神秘的化石才肯撤退。确保这位矮人研究员在反常的搜寻中幸存下来，可以让他的安全消息传回奥伯丁的助手那里。",h="在黑海岸南部的废墟深处，勘察员雷姆塔维尔拒绝离开他的挖掘场，因为他没有带回任何成果向探险者协会交差。尽管他极其健忘，而且还有敌对的穴居人出没，但他坚持要找到一块神秘的化石才肯撤退。确保这位矮人研究员在反常的搜寻中幸存下来...",kw={"奥伯丁","黑海岸","护送","挖掘","探险者协会","化石","霍莉","雷姆塔维尔","穴居人"},ang={["faction:Alliance"]="确保雷姆塔维尔及其发现的安全，维持了矮人探险者协会与泰达希尔暗夜精灵之间至关重要的外交与学术合作。",["race:Dwarf"]="对于矮人来说，雷姆塔维尔体现了探险者协会无情的激情和危险的固执，展现了对古代泰坦知识的奉献如何使学者对迫在眉睫的危险视而不见。",["race:NightElf"]="卡多雷通常以警惕的态度看待黑海岸的矮人挖掘活动；雷姆塔维尔挖掘出成群的暴力穴居人证实了他们对于在神圣土地上过度挖掘的担忧。"},sec={{t="危险的挖掘",b="雷姆塔维尔的挖掘场位于黑海岸南部，坐落在本应隐藏着被遗忘秘密的古代废墟之中。然而，矮人挖掘者意外地挖出了大群凶猛的穴居人，工人被驱赶走，营地也被围困。虽然大多数人会立即逃往奥伯丁，但勘察员雷姆塔维尔却执着于挽救他的发现。他不愿空手而归，因此冒险深入险境，试图寻回一块难以捉摸的化石，以便向探险者协会证明此次探险的成本是合理的。"},{t="混乱的记忆与穴居人的伏击",b="保护雷姆塔维尔的过程既令人沮丧又充满危险。他那丢三落四的本性使他在挖掘场四处乱转，把刷子错当成化石，跌跌撞撞地越过脚手架和废弃的帐篷。每一次停留都会吸引潜伏在采石场阴暗角落里的凶猛穴居人的注意。在护送者消灭了一波又一波地底野兽之后，这位学者终于记起他的奖品在哪里：他已经把化石交给霍莉了，于是他高高兴兴地回去工作了。"}},faq={{q="勘察员雷姆塔维尔是谁？",a="勘察员雷姆塔维尔是矮人探险者协会的一名资深实地研究员。他驻扎在黑海岸，负责挖掘沿海的古代废墟，但他极度的健忘经常使他陷入危及生命的境地。",al={"雷姆塔维尔","勘察员是谁","健忘的勘察员"}},{q="为什么雷姆塔维尔还待在挖掘场？",a="尽管挖掘场被穴居人占领，但雷姆塔维尔在没有带回切实的工作成果前，拒绝返回达纳苏斯。他坚持要找到一块神秘的化石交给探险者协会，才考虑放弃营地。",al={"为什么待在挖掘场","雷姆塔维尔为什么在那里","为什么他没有逃走"}},{q="穴居人是从哪里来的？",a="和许多矮人挖掘活动一样，雷姆塔维尔的团队向地底深处挖掘，无意中打通了穴居人居住的地底洞穴。这些原始生物成群结队地涌出地面，暴力地摧毁了机械、帐篷和工人。",al={"黑海岸为什么有穴居人","黑海岸穴居人","挖掘场穴居人"}},{q="考古学家霍莉是谁？",a="考古学家霍莉是雷姆塔维尔的同事兼助手，驻扎在沿海城镇奥伯丁。她对导师长时间的缺席感到心烦意乱，并且非常了解他健忘的习惯，因此她招募旅行者去寻找他，以确保他能安全返回。",al={"霍莉","考古学家霍莉","雷姆塔维尔的助手"}},{q="找到化石后会发生什么？",a="在帮助雷姆塔维尔搜寻完挖掘场后，向奥伯丁的考古学家霍莉报告他的安全情况。",al={"任务后续","接下来做什么","护送雷姆塔维尔之后"}}},fp="28,256,21.331.0,35.415.1,28.223.0,39.180.0,31.175.0,28.213.0,38.98.1"}
P.entries["quest:732"] = {n="大地的震颤",s="加瑞克听Sigrun说了你帮了多少忙，现在轮到他请求你的帮助了。加瑞克的导师，肯瑞托的Krasus，派遣加瑞克来阻止莱瑟罗峡谷中正在酝酿的一切，首先必须找到被窃的大地印章。",h="加瑞克听Sigrun说了你帮了多少忙，现在轮到他请求你的帮助了。加瑞克的导师，肯瑞托的Krasus，派遣加瑞克来阻止莱瑟罗峡谷中正在酝酿的一切，首先必须找到被窃的大地印章。",kw={"苦痛堡垒","博夫营地","黑铁矮人","deathwing","加瑞克","肯瑞托","krasus","莱瑟罗峡谷","大地印章"},sec={{t="严守的秘密",b="加瑞克的导师，肯瑞托的Krasus，派遣他前往Badlands，阻止莱瑟罗峡谷中正在酝酿的麻烦。具体任务内容不能透露，只能告诉你此事关系重大。一群流浪食人魔经常在博夫营地附近出没，他们拿走了大地印章，加瑞克需要它。把它带回来，你就能了解更多情况。"},{t="游荡的食人魔",b="食人魔在Badlands各处的营地间移动，炎热的温度和盘旋的风沙让它们的踪迹难以追踪。加瑞克听说它们有时会经过博夫营地，如果你找不到它们了，那里是个不错的搜寻地点。"},{t="加瑞克的解释",b="当你带着印章回来时，加瑞克告诉你，苦痛堡垒的Dark Iron矮人制作了它，目的是为了束缚Deathwing的双子副官，冷酷的Blacklash和Hematus。"}},faq={{q="加瑞克为谁效力？",a="加瑞克的导师是肯瑞托的Krasus，他派遣加瑞克前往Badlands，以阻止莱瑟罗峡谷中正在酝酿的麻烦。",al={"谁派遣了加瑞克","加瑞克的导师","krasus与badlands"}},{q="大地印章是什么？",a="游荡的食人魔偷走了它，加瑞克需要找回它。等你把它带回来，加瑞克会告诉你更多信息。",al={"大地印章","大地印章是什么","大地印章背景"}},{q="在哪里可以找到游荡的食人魔？",a="它们在Badlands各处的营地之间游荡，加瑞克听说它们有时会经过博夫营地。",al={"食人魔在哪里","食人魔与博夫营地","大地印章在哪里"}},{q="为什么加瑞克要保密任务内容？",a="加瑞克不愿透露任务内容或所需工作，只说它至关重要。",al={"为什么要保密","加瑞克的秘密任务"}}},fp="20,236,19.356.0,19.224.0,14.178.1,25.120.0,30.88.0,39.109.0,42.103.0"}
P.entries["quest:7321"] = {n="海龟汤",s="舒心龟肉浓汤是塔伦米尔的克里斯托弗·杰弗寇特提供的一项烹饪任务。这位被遗忘者厨师旨在通过制作这种用当地咬鳖肉熬制的浓汤，来驳斥亡灵缺乏烹饪天赋的说法。玩家必须在希尔斯布莱德丘陵的水域和洛丹米尔湖的湖岸边狩猎淡水龟，以掌握他珍视的食谱。",h="舒心龟肉浓汤是塔伦米尔的克里斯托弗·杰弗寇特提供的一项烹饪任务。这位被遗忘者厨师旨在通过制作这种用当地咬鳖肉熬制的浓汤，来驳斥亡灵缺乏烹饪天赋的说法。玩家必须在希尔斯布莱德丘陵的水域和洛丹米尔湖的湖岸边狩猎淡水龟，以掌握...",kw={"克里斯托弗·杰弗寇特","烹饪","希尔斯布莱德丘陵","洛丹米尔湖","咬鳖","舒心龟肉浓汤","塔伦米尔","龟肉"},ang={["faction:Horde"]="支持塔伦米尔的驻军不仅仅涉及保卫其边界；保持供应充足和士气高昂有助于巩固部落在饱受争夺的希尔斯布莱德的立足点。",["profession:Cooking"]="这项任务允许厨师掌握舒心龟肉浓汤，将洛丹米尔湖和希尔斯布莱德河流中的凶猛爬行动物变成一道恢复元气的餐点。",["race:Undead"]="克里斯托弗·杰弗寇特代表了被遗忘者更为轻松、注重技艺的一面，坚持认为死亡并没有磨灭他对烹饪的热情。"},sec={{t="被遗忘者的烹饪艺术",b="人们普遍认为被遗忘者已经完全抛弃了生活的舒适，包括享受美食的艺术。驻扎在塔伦米尔的克里斯托弗·杰弗寇特强烈反对这种假设。杰弗寇特夸口说他的浓郁、舒心的龟肉浓汤美味到足以将灵魂从坟墓中唤回，他试图证明即便是在这片被瘟疫和战争玷污的土地上，亡灵的手也能做出精致、暖心的工艺品。"},{t="猎杀咬鳖",b="通常情况下，杰弗寇特会亲自从希尔斯布莱德丘陵的水域以及邻近奥特兰克的洛丹米尔湖东岸采集原料。然而，塔伦米尔的任务和步步紧逼的联盟部队让他脱不开身。他只能依靠过往的部落厨师来猎杀咬鳖，采集肉块并带回来，好让这项烹饪传统得以延续。"}},faq={{q="为什么被遗忘者厨师会关心制作热浓汤？",a="虽然被遗忘者不需要像活着的凡人那样维持生计，但像克里斯托弗·杰弗寇特这样的人对他们的手艺感到非常自豪。杰弗寇特旨在驳斥亡灵缺乏精细技巧的偏见，并开玩笑说他的招牌浓汤美味到足以让逝者复活。",al={"亡灵烹饪","为什么要制作浓汤","亡灵进食"}},{q="在这个食谱中，可以在哪里找到龟肉？",a="龟肉是从居住在希尔斯布莱德丘陵和奥特兰克流经的河流沿岸，以及洛丹米尔湖岸边的凶猛咬鳖身上采集的。",al={"海龟在哪里","海龟位置","咬鳖位置"}},{q="为什么克里斯托弗·杰弗寇特不能亲自采集原料？",a="杰弗寇特声称他被塔伦米尔的职责缠身。他还对附近步步紧逼的联盟部队表示恼火，这使得个人的狩猎远足变得更加危险。",al={"为什么克里斯托弗不去","杰弗寇特困在镇子里"}},{q="接受这个任务需要烹饪知识吗？",a="是的。克里斯托弗·杰弗寇特只会与烹饪专业的同行分享他的技艺和食谱，尽管开始时并不需要任何高级的掌握程度。",al={"我需要烹饪吗","烹饪专业要求"}},{q="塔伦米尔对希尔斯布莱德的部落来说有多重要？",a="塔伦米尔是希尔斯布莱德丘陵主要的部落据点。它曾经是一个人类村庄，现在作为被遗忘者及其盟友的防御基地，经常面临与南海镇和当地联盟势力的冲突。",al={"什么是塔伦米尔","塔伦米尔背景故事"}},{q="龟肉浓汤是部落独有的吗？",a="联盟的厨师可以从南海镇当地也会利用当地龟类资源的人类厨师那里获得食谱，但克里斯托弗·杰弗寇特的个人任务和视角是部落独有的。",al={"联盟版本","联盟可以获得龟肉浓汤吗"}}},fp="22,191,19.353.0,20.303.0,54.214.0,47.130.0,56.129.0,49.100.0,59.215.0,37.178.0"}
P.entries["quest:733"] = {n="搜集行动",s="西格鲁·铁斧需要材料来为营地建造防御工事及其他必需品，并注意到附近的食人魔携带着大量的废金属。西格鲁想要七块废金属。",h="西格鲁·铁斧需要材料来为营地建造防御工事及其他必需品，并注意到附近的食人魔携带着大量的废金属。西格鲁想要七块废金属。",kw={"荒芜之地","火山洞穴","探险者协会","铁炉堡","食人魔","废金属","搜刮废料","西格鲁·铁斧"},sec={{t="营地材料短缺",b="西格鲁发现没有材料来建造防御工事和其他必需品十分困难，探矿者也一直担心这个小营地的状况。西格鲁想尽快开始工作，因此需要废金属。"},{t="食人魔的废料",b="该地区的食人魔似乎有充足的废金属储备，这让西格鲁认为关于荒芜之地有攻城机器的传言可能并非空穴来风。它们的主要营地是位于西格鲁营地以西长途跋涉之处的火山洞穴。"}},faq={{q="谁在索要废金属？",a="西格鲁·铁斧，她想要这些材料来为营地建造防御工事及其他必需品。",al={"任务发布者","谁发布了“搜刮废料”","西格鲁"}},{q="为什么营地需要废金属？",a="西格鲁缺少建造防御工事和其他必需品的材料，而且探矿者一直担心这个营地的状况。",al={"为什么需要废金属","废金属的用途","防御工事"}},{q="在哪里可以找到废金属？",a="该地区的食人魔携带这些东西。它们的主要营地是位于西格鲁营地以西长途跋涉之处的火山洞穴。",al={"废金属位置","去哪里获取废金属","食人魔营地"}},{q="这之前有什么任务？",a="它紧接在“海市蜃楼”之后。",al={"前置任务","“搜刮废料”的前提条件"}}},fp="10,179,25.219.0,16.227.0,34.82.0,35.133.0,35.103.0,23.19.0"}
P.entries["quest:734"] = {n="不祥的感觉",s="鲁特维尔·沃拉图斯正忙于处理一副镣铐，他让你去荒芜之地找卢希恩·枪穗谈谈。鲁特维尔需要一个5号齿轮，并要求你把它带回来。",h="鲁特维尔·沃拉图斯正忙于处理一副镣铐，他让你去荒芜之地找卢希恩·枪穗谈谈。鲁特维尔需要一个5号齿轮，并要求你把它带回来。",kw={"荒芜之地","5号齿轮","鲁特维尔·沃拉图斯","卢希恩·枪穗","镣铐"},sec={{t="5号齿轮",b="鲁特维尔抬头瞥了你一眼，随即又弯下腰继续处理那副镣铐。你要去和卢希恩·枪穗谈谈，因为鲁特维尔需要一个5号齿轮，并让你把它带回来。"},{t="卢希恩的裁决",b="一提到5号齿轮，卢希恩·枪穗对事情的结果感到不太乐观。"}},faq={{q="这个任务是谁给的？",a="鲁特维尔·沃拉图斯，他正在荒芜之地制作一副镣铐。",al={"谁发布此任务","鲁特维尔·沃拉图斯任务","任务发布者"}},{q="鲁特维尔需要什么？",a="一个5号齿轮，鲁特维尔让你在和卢希恩·枪穗谈过之后把它带回来。",al={"鲁特维尔想要什么","哪个齿轮","5号齿轮"}},{q="关于齿轮我应该和谁谈？",a="鲁特维尔让你去荒芜之地找卢希恩·枪穗。",al={"哪里寻找5号齿轮","卢希恩是谁","卢希恩·枪穗"}}},fp="24,155,15.173.0,16.86.1,21.69.0,22.86.0,32.56.0"}
P.entries["quest:735"] = {n="星，手，心",s="铁炉堡的葛利·硬骨有一本多余的《雅格因的笔记》，并愿意用三件充满力量的物品来交换。葛利不愿大声说出这些物品的名字，而是把它们写在了一张纸条上。",h="铁炉堡的葛利·硬骨有一本多余的《雅格因的笔记》，并愿意用三件充满力量的物品来交换。葛利不愿大声说出这些物品的名字，而是把它们写在了一张纸条上。",kw={"硬骨的纸条","葛利·硬骨","达古恩之手","铁炉堡","传承之心","希尔耶之星","雅格因的笔记"},sec={{t="闭口不言的交易",b="葛利听出你在打听《雅格因的笔记》，不禁好奇你是不是要在什么地方开启他们教团的新篇章，但他随即觉得这不该由他来过问。葛利手头正好有一本多余的笔记，并认为教团成员之间理应互相帮助。作为交换，你必须带来三件充满力量的物品。这些物品的名字不能宣之于口，以免隔墙有耳，所以葛利把它们写了下来。"},{t="这三件物品",b="纸条上写着希尔耶之星、达古恩之手和传承之心。这些就是他在交出笔记之前索要的东西。"},{t="葛利的评价",b="一旦你把这些圣物交到他手中，葛利会夸赞你足智多谋，并相信如果创建教团新篇章的任务确实由你负责，你一定能将其经营得很好。"}},faq={{q="是谁索要这三件物品？",a="铁炉堡的葛利·硬骨，他有一本多余的《雅格因的笔记》可以用来交换。",al={"任务发布者","谁开启了星、手与心任务","葛利·硬骨任务"}},{q="葛利·硬骨需要哪三件物品？",a="葛利·硬骨的纸条上要求三样东西：希尔耶之星、达古恩之手和传承之心。",al={"所需物品","他需要哪些圣物","硬骨纸条上的物品"}},{q="为什么葛利要把这些物品写下来而不是说出来？",a="葛利不愿说出它们的名字是因为担心隔墙有耳。",al={"为什么要写下来","为什么要用秘密纸条","硬骨低语"}},{q="这个任务链的前序任务是什么？",a="此任务紧接“为了雅格因的笔记前往铁炉堡”，在那里，迷失者塞尔杜林指引你去找葛利。",al={"前置任务","上一个任务"}}},fp="32,193,30.378.0,15.134.0,16.163.1,29.89.0,43.106.0,60.67.0,35.89.0"}
P.entries["quest:736"] = {n="星，手，心",s="“星辰、手与心”是一项幽暗城的任务，看守者贝尔杜加会在此考验一位寻求建立新分会的有志领袖。为了获得至关重要的雅格因的笔记，请求者必须追踪到三件力量之物，而贝尔杜加不敢大声说出它们的名字。",h="“星辰、手与心”是一项幽暗城的任务，看守者贝尔杜加会在此考验一位寻求建立新分会的有志领袖。为了获得至关重要的雅格因的笔记，请求者必须追踪到三件力量之物，而贝尔杜加不敢大声说出它们的名字。",kw={"贝尔杜加的便条","看守者贝尔杜加","组织","星辰、手与心","三件力量之物","幽暗城","雅格因的笔记"},ang={["class:Warlock"]="获取雅格因的笔记以建立一个新的群体，是扩展你黑暗组织的影响力和神秘掌控力的关键一步。",["race:Undead"]="看守者贝尔杜加在幽暗城运作，引导着那些寻求在城市阴影尖塔下深入钻研禁忌仪式的被遗忘者从业者。"},sec={{t="兄弟会的考验",b="在幽暗城阴影笼罩的走廊深处，有野心的从业者如果想要领导自己的圈子，就会向看守者贝尔杜加寻求帮助。为了建立一个新的群体并开启分会，有志领袖需要得到雅格因的笔记，这是一本由看守者守护的仪式知识权威典籍。贝尔杜加随时准备支持他的兄弟，但在交出这种权力之前，他要求对方证明自己的价值。"},{t="不可言说的圣物",b="看守者贝尔杜加不会轻易交出雅格因的笔记。他需要三件独特的力量之物来完成交换。这些圣物具有极度危险或神圣的意义，以至于它们的名字甚至无法大声说出；贝尔杜加将它们写在了一张私人便条上。只有有能力追踪并找回这三件不可言说的圣物的从业者，才证明自己有资格建立自己的分会。"}},faq={{q="看守者贝尔杜加是谁？",a="看守者贝尔杜加是幽暗城的一位神秘人物，他会协助其黑暗兄弟会的成员。他守护着强大的知识，并要求候选人在委托给他们神圣典籍之前证明自己的能力。",al={"看守者贝尔杜加是谁","贝尔杜加的角色","贝尔杜加幽暗城"}},{q="什么是雅格因的笔记？",a="雅格因的笔记是一本专门的教学文本，对于在秘密的神秘组织内建立和领导一个新的分会或聚集一个新群体来说是必不可少的。",al={"什么是雅格因的笔记","雅格因的笔记用途","雅格因的笔记书籍"}},{q="看守者贝尔杜加要求获得什么物品？",a="贝尔杜加需要三件特定的力量之物。由于它们的名字太过禁忌或危险而无法大声说出，他将它们悄悄写在一张便条上，供请求者去回收。",al={"贝尔杜加需要什么物品","贝尔杜加的便条物品","三件力量之物"}},{q="为什么请求的物品名字不能大声说出来？",a="看守者贝尔杜加明确指出，他无法大声说出这三件圣物的名字，这表明它们拥有黑暗、神圣或不稳定的力量，需要格外谨慎。",al={"为什么贝尔杜加不能说出物品名称","无法说出名字","不可言说的物品名称"}},{q="聚集另一个群体意味着什么？",a="聚集群体是指招募追随者并建立一个功能独立的兄弟会分会，证明一个人已准备好指导其他从业者。",al={"聚集群体意味着什么","开启分会","我们的组织分会"}},{q="这项任务的核心地点在哪里？",a="这项任务以看守者贝尔杜加为中心，他驻扎在被遗忘者地下的首都——幽暗城内。",al={"这项任务发生在哪里","贝尔杜加的位置","任务交付地点"}}},fp="32,291,21.413.0,19.424.0,24.221.0,24.160.0,41.190.0,58.174.0,42.188.0,29.118.0"}
P.entries["quest:737"] = {n="禁断的知识",s="雅格因的笔记被交给了你，并告诫你要妥善保管，切勿落入不友善之手。你需要把它交给迷失者塞尔杜林。",h="雅格因的笔记被交给了你，并告诫你要妥善保管，切勿落入不友善之手。你需要把它交给迷失者塞尔杜林。",kw={"荒芜之地","禁忌的知识","星、手与心","迷失者塞尔杜林","雅格因的笔记"},sec={{t="一本会灼伤人的书",b="铁炉堡的葛利·硬骨或幽暗城的看守者贝尔杜加会把这份笔记交给你。他们告诫你要妥善保管，切勿落入不友善之手，因为它承载了许多真理，而真理往往会灼伤人。把它交给迷失者塞尔杜林。"},{t="塞尔杜林的希望",b="塞尔杜林呼喊着希望的微光，并说你的努力或许能拯救所有人，让人们为你立碑、建龛，并让你的名字被后世世代传颂。但这一切的前提是，不能让“它们”重见天日并来到地表，否则，塞尔杜林说，所有人都会成为蠕虫的食物。"}},faq={{q="需要交付什么物品？",a="雅格因的笔记，一本承载了许多真理的书。它必须被严加保管，切勿落入不友善之手。",al={"这是什么书","什么是雅格因的笔记","我要带什么东西"}},{q="谁来接收这份笔记？",a="这份笔记是交给迷失者塞尔杜林的。",al={"谁会收到这本书","我要把它交给谁","笔记要送到哪里"}},{q="此任务之前发生了什么？",a="在此之前，你需要集齐三件物品来换取这份笔记。",al={"前置任务","什么任务引出这个任务","禁忌的知识之前的任务是什么"}}},fp="19,131,17.255.0,16.285.1,32.106.0,24.43.0,22.81.0"}
P.entries["quest:738"] = {n="寻找阿戈莫德",s="勘察员基恩萨·铁环已经几周没有Agmond的消息了。Agmond负责荒芜之地的挖掘场，铁环希望能找到他，以便收集报告。",h="勘察员基恩萨·铁环已经几周没有Agmond的消息了。Agmond负责荒芜之地的挖掘场，铁环希望能找到他，以便收集报告。",kw={"agmond","苦痛堡垒","荒芜之地","铁炉堡","勘察员基恩萨·铁环"},sec={{t="沉默的勘察员",b="Agmond负责西南方向荒芜之地的挖掘工作。铁环特意用了“负责”这个词，因为Agmond已经几周音讯全无了。铁环想要找到Agmond，并拿回他手中的报告。人们最后一次得到Agmond的消息是在荒芜之地最南端的挖掘场，那是一个位于苦痛堡垒之外的小型营地，搜寻工作应该从那里开始。"},{t="线索终点",b="在搜寻的终点，你发现了一具骸骨，这一定就是Agmond的遗骸。尸体破碎不堪，骨头已经被啃食殆尽。"}},faq={{q="谁是勘察员Agmond？",a="Agmond负责勘察员基恩萨·铁环西南方向荒芜之地的挖掘工作。",al={"谁是agmond","agmond是谁","agmond背景故事"}},{q="为什么勘察员基恩萨·铁环要寻找Agmond？",a="铁环已经几周没有Agmond的消息了，他想要拿到Agmond的报告。",al={"为什么要寻找agmond","铁环寻找agmond"}},{q="勘察员Agmond最后出现在哪里？",a="在荒芜之地最南端的挖掘场，一个位于苦痛堡垒之外的小型营地。",al={"agmond位置","agmond挖掘场在哪里","agmond最后在哪里"}},{q="在这个任务链中，上一步是什么？",a="它是“铁环需要你！”的任务后续。",al={"上一个任务","寻找agmond的前置任务"}}},fp="11,192,19.345.0,20.154.1,25.77.0,46.77.0,45.80.0,36.30.0"}
P.entries["quest:739"] = {n="莫达洛克",s="阿格蒙德的残骸躺在荒芜之地，死者手边的砂岩上潦草地写着一个名字：穆达洛克。必须除掉阿格蒙德的凶手，并将消息带回洛克莫丹交给勘察员基恩萨·铁环。",h="阿格蒙德的残骸躺在荒芜之地，死者手边的砂岩上潦草地写着一个名字：穆达洛克。必须除掉阿格蒙德的凶手，并将消息带回洛克莫丹交给勘察员基恩萨·铁环。",kw={"阿格蒙德","荒芜之地","洛克莫丹","穆达洛克","勘察员基恩萨·铁环","石库食骨者","穴居人"},sec={{t="砂岩上的名字",b="阿格蒙德的足迹从西边延伸而来，石头和沙子上涂抹的血迹诉说着这位矮人在死前挣扎了多远。在毫无生气的遗体旁，荒芜之地的砂岩上刻着一个词：穆达洛克。必须杀死阿格蒙德的凶手，还要解决掉一些石库食骨者，并将消息带给洛克莫丹的勘察员基恩萨·铁环。"},{t="铁环的回信",b="铁环严肃地接受了消息，他记得阿格蒙德是个臂力过人、挥锤凶猛且性格固执的矮人。铁环说阿格蒙德是被受诅咒的穴居人杀死的，并确信他在临死前也解决了不少敌人。"}},faq={{q="阿格蒙德是谁？",a="阿格蒙德是一名矮人，负责为勘察员基恩萨·铁环管理荒芜之地的挖掘场。你对阿格蒙德的搜寻最终在一具骸骨处结束了。",al={"阿格蒙德是谁","阿格蒙德背景故事"}},{q="穆达洛克是谁？",a="穆达洛克是刻在阿格蒙德遗体旁砂岩上的名字。你需要杀死阿格蒙德的凶手，穆达洛克。",al={"穆达洛克是什么","穆达洛克背景故事"}},{q="报告需要送到哪里？",a="送到洛克莫丹的勘察员基恩萨·铁环那里。",al={"我该向谁汇报穆达洛克的事","铁环在哪里"}}},fp="8,214,23.361.0,16.226.1,15.137.0,16.116.0,33.37.0"}
P.entries["quest:74"] = {n="斯塔文的传说",s="调查的这一步骤将把你引向暴风城运河旁遗留的一只旧箱子，里面装满了弗林特里奇家族的传家宝。在布满灰尘的遗物中仔细搜寻，你会发现一张被撕破的日记书页，这为斯塔文·密斯特曼托的过去生活提供了关键的手写线索，并引导你前往艾尔文森林寻找哈格德警官。",h="调查的这一步骤将把你引向暴风城运河旁遗留的一只旧箱子，里面装满了弗林特里奇家族的传家宝。在布满灰尘的遗物中仔细搜寻，你会发现一张被撕破的日记书页，这为斯塔文·密斯特曼托的过去生活提供了关键的手写线索，并引导你前往艾尔文森...",kw={"暮色森林","艾尔文森林","弃灵","哈格德警官","密斯特曼托","密封的箱子","斯塔文","一张被撕破的日记书页"},ang={["faction:Alliance"]="调查艾尔文森林中心的一些旧悬案揭示了那些个人的恐怖往事是如何在暴风城警官的眼皮底下被遗漏的。",["race:Human"]="哈格德警官代表了暴风城年迈的退伍军人一代，保留着第一次和第二次战争将家庭拆散之前关于王国的宝贵记忆。"},sec={{t="发掘过去",b="当调查员在翻找一只装满陈旧传家宝、古老狩猎战利品和家族肖像的密封的箱子时，在一只陶瓷花瓶下发现了一张被撕破的日记书页。这篇文字是斯塔文·密斯特曼托亲笔所写，让人们得以窥见这位隐居学者在悲剧发生前那段深藏心底的思绪。"},{t="警官日益模糊的视力",b="哈格德警官如今已上了年纪，且深受视力衰退的困扰，很难看清那张破损羊皮纸上的字迹。即便如此，那独特的笔迹仍让他感到一丝不安，让他回想起了黑暗降临、夺去他的视力之前，那些往年的文档与事件。"}},faq={{q="密封的箱子在哪里？",a="密封的箱子位于暴风城运河旁，就在管理员弗索姆的身后，夹杂在弗林特里奇家族打包好的行李中。在那里找到的书页随后会被送往艾尔文森林东南部的哈格德警官手中。",al={"箱子位置","箱子在哪里","哈格德的箱子"}},{q="密封的箱子里有什么？",a="箱子里装有满是灰尘的传家宝、一幅家族肖像、旧书、狩猎战利品和一个陶瓷花瓶，在花瓶下放着一张从斯塔文日记中撕下的书页。",al={"箱子内容物","箱子里有什么","被撕破的书页箱子"}},{q="哈格德警官是谁？",a="哈格德警官是一位年迈的暴风城退休官员，独自居住在艾尔文森林南部。尽管他视力衰退且身体虚弱，但他对旧时记录和旅行者的记忆使他成为了解过去事件的关键证人。",al={"谁是哈格德","哈格德警官背景故事","艾尔文森林的老警官"}},{q="为什么这张日记书页很重要？",a="这张被撕破的日记书页是斯塔文·密斯特曼托亲笔写下的直接证据。其独特的笔迹和残留的思绪有助于将暮色森林和艾尔文森林各处零散的记录与他个人的堕落联系起来。",al={"为什么被撕破的书页很重要","日记书页线索","斯塔文的日记"}},{q="打开箱子会发生什么？",a="惊扰斯塔文往事的残留物会唤醒不安的亡灵，导致一个充满复仇之心的弃灵现身，并攻击那些试图揭开这场悲剧真相的人。",al={"弃灵刷新","箱子后的鬼魂","为什么鬼魂攻击我"}},{q="接下来的调查方向是什么？",a="在将这张被撕破的书页交给哈格德警官后，他对笔迹的回忆将引导调查继续深入，去寻找更多幸存的斯塔文历史碎片。",al={"下一步","被撕破的书页之后","接下来要去哪里"}}},fp="21,161,19.264.0,24.204.1,34.236.0,32.158.0,23.229.0,35.192.0,38.154.0,39.153.0"}
P.entries["quest:741"] = {n="健忘的勘察员",s="这项差事将一件从黑海岸荒野海滩上发现的奇异石化标本送往达纳苏斯的探险者协会前哨站。考古学家霍莉拒绝抛下她那心不在焉的同事，转而委托一名路过的冒险者来运输这份标本。这份化石抵达暗夜精灵首都后，立刻引起了首席考古学家杜瑟·灰须的浓厚兴趣。",h="这项差事将一件从黑海岸荒野海滩上发现的奇异石化标本送往达纳苏斯的探险者协会前哨站。考古学家霍莉拒绝抛下她那心不在焉的同事，转而委托一名路过的冒险者来运输这份标本。这份化石抵达暗夜精灵首都后，立刻引起了首席考古学家杜瑟·灰...",kw={"考古学家","黑海岸","达纳苏斯","探险者协会","化石","杜瑟·灰须","霍莉","雷姆塔维尔"},ang={["faction:Alliance"]="这项任务展示了联盟成员之间在后勤方面的相互依赖，因为矮人研究员需要依靠旅行冒险者来安全地连接黑海岸偏远的海岸和达纳苏斯的高地。",["race:Dwarf"]="运送雷姆塔维尔的化石履行了探险者协会的首要使命：发掘世界深处的过去，并证明矮人坚持不懈的无限价值。",["race:NightElf"]="看着矮人挖掘者从黑海岸的神圣土地中挖出远古遗迹可能会让人感到不安，但与协会合作有助于维护联盟的纽带。"},sec={{t="前往首都的信使",b="勘察员雷姆塔维尔在黑海岸雾气缭绕的海岸沿线发掘出了一块奇特的化石，对他来说，深入挖掘比遵守规章制度更重要。考古学家霍莉不愿将这位游荡的勘察员独自留在海岸边危险的野兽和充满敌意的邪教徒之中，因此留下来看护他。为了记录下这一发现，她需要一名联盟旅者将标本送往达纳苏斯，探险者协会在那里设有学术代表团。"},{t="矮人在卡利姆多的利益",b="来自铁炉堡的矮人们在探险者协会的旗帜下大举跨越了无尽之海，渴望发掘卡利姆多土地下埋藏的远古遗物和失落的历史。首席考古学家杜瑟·灰须在暗夜精灵首都接收了这件文物，迫不及待地赞叹雷姆塔维尔发掘远古宝藏的天赋。暗夜精灵将他们的森林视为神圣的庇护所，而探险者协会则将这片古老的土地视为等待解读的巨大考古发掘场。"}},faq={{q="什么是神秘的化石？",a="这是勘察员雷姆塔维尔在黑海岸沿岸发掘出的一件未鉴定的石化标本。它古老的年代和奇异的特质使其成为驻扎在达纳苏斯的探险者协会学者们的珍贵发现。",al={"神秘的化石","这是什么化石","雷姆塔维尔的化石"}},{q="为什么霍莉留在黑海岸？",a="考古学家霍莉觉得有义务看护勘察员雷姆塔维尔。他在发掘时总是习惯四处游荡并忽视危险，所以她拒绝在他将发现物送往达纳苏斯时把他独自留在野外。",al={"为什么霍莉不去","霍莉留下来","为什么霍莉留下来"}},{q="首席考古学家杜瑟·灰须是谁？",a="杜瑟·灰须是铁炉堡探险者协会的高级代表，负责监督卡利姆多北部的考古事业。他在达纳苏斯开展工作，研究矮人挖掘者从野外带回的遗物。",al={"杜瑟·灰须","杜瑟·灰须是谁","首席考古学家杜瑟·灰须"}},{q="为什么探险者协会要在达纳苏斯开展活动？",a="国王麦格尼·铜须委任探险者协会发掘矮人种族的起源以及艾泽拉斯各地的远古历史。与暗夜精灵的友好外交关系使得矮人学者们能够以达纳苏斯为基地，开展远征以研究卡利姆多被遗忘的土地。",al={"达纳苏斯的矮人","达纳苏斯的探险者协会","矮人为什么在这里"}},{q="这块化石在达纳苏斯之后会被送到哪里？",a="首席考古学家杜瑟·灰须会在达纳苏斯检查该发现，但这种规模的发现通常会被编入目录，或者通过协会渠道进一步转运，最终送回铁炉堡的大博物馆。",al={"化石去哪了","化石的后续"}},{q="雷姆塔维尔是在哪里发现该标本的？",a="雷姆塔维尔是在黑海岸的荒野海岸线上发现该标本的，该地区遍布沉船、古代遗迹以及可追溯到大分裂之前的化石化的海洋生物。",al={"在哪里发现化石","雷姆塔维尔的发掘地点"}}},fp="28,183,24.371.0,29.376.0,30.188.0,41.193.0,39.219.0,52.257.0,46.181.0,38.159.0"}
P.entries["quest:742"] = {n="灰谷狩猎",s="“灰谷狩猎”是下达给造访雷霆崖的年轻部落勇士的一道征召令，催促他们向北前往灰谷那茂密的树冠之下。这道召集令由城中的传令官送达，指引旅行者向碎木岗哨的塞娜尼·雷心报到，参加一场试炼狩猎。",h="“灰谷狩猎”是下达给造访雷霆崖的年轻部落勇士的一道征召令，催促他们向北前往灰谷那茂密的树冠之下。这道召集令由城中的传令官送达，指引旅行者向碎木岗哨的塞娜尼·雷心报到，参加一场试炼狩猎。",kw={"灰谷","狩猎","塞娜尼","碎木","雷霆崖","雷心","斯塔德尔","佐拉姆海岸"},ang={["class:Hunter"]="灰谷中未被驯服的潜行者为猎人们提供了一个在茂密林地中磨练追踪技巧的机会，这与南方干燥开阔的稀树草原截然不同。",["faction:Horde"]="碎木岗哨和佐拉姆海岸是部落北方补给线的关键中转站，依靠新兵来阻挡野兽和敌对原住民的侵袭。",["race:Tauren"]="对于那些试炼都在莫高雷广阔平原上进行的牛头人来说，灰谷那茂密而阴郁的树冠在像塞娜尼这样的族人注视下，是一项陌生而神圣的挑战。"},sec={{t="来自高地居所的征召",b="在雷霆崖宁静的高地上，信使们向不断壮大的部落通报着莫高雷边界之外的机遇。雷霆崖信使斯塔德尔带着一封公开邀请函，旨在寻找那些寻求更大挑战的资深冒险者。随着部落在贫瘠之地北部的古老森林中建立立足点，年轻的战士们被召集起来，以巩固那些前哨站，并在更加严酷的环境中磨练他们的生存技巧。"},{t="北方前线",b="对于部落而言，灰谷既蕴含着丰富的资源，也充满了致命的危险。两个显眼的营地支撑着部落在该地区的势力：位于主干道旁的碎木岗哨，以及西海岸上的一座遥远哨所——佐拉姆海岸。抵达碎木岗哨后，新兵将直接归于塞娜尼·雷心的麾下，这位经验丰富的户外生存专家正在组织一场大规模的狩猎，旨在驯服这片荒野，并为部落赢取荣耀。"}},faq={{q="谁在雷霆崖提供这个任务？",a="雷霆崖信使斯塔德尔向路过的冒险者提供这项任务。他的职责是告知有能力的战士关于部落扩张工作的进展，并指引他们前往需要援助的偏远哨所。",al={"谁开启灰谷狩猎","灰谷狩猎任务给予者","雷霆崖信使斯塔德尔"}},{q="碎木岗哨位于何处？",a="碎木岗哨是部落在灰谷东部的一处防御要塞。要到达那里，请穿过贫瘠之地的边界直接向北进入灰谷，然后沿着东部的森林小径深入林地。",al={"碎木岗哨位置","如何到达碎木岗哨","碎木在哪里"}},{q="塞娜尼·雷心是谁？",a="塞娜尼·雷心是一位驻扎在碎木岗哨的资深牛头人追踪者。她负责协调灰谷的狩猎工作，考验部落新兵在当地掠食者面前的实力与耐心。",al={"塞娜尼·雷心","谁是塞娜尼","雷心npc"}},{q="为什么部落要在灰谷进行狩猎？",a="部落一直在向灰谷积极扩张，以收集木材并确保战略领地的安全。狩猎活动本身旨在清除那些威胁营地的危险野兽，同时让年轻的冒险者在陌生的地形中证明自己的实力。",al={"为什么在灰谷狩猎","灰谷狩猎目的","部落灰谷目标"}},{q="简报中提到的佐拉姆海岸是什么？",a="佐拉姆海岸是部落在灰谷最西端面向大海的沿海营地。它作为第二个海军立足点，也是抵御纳迦和敌对森林住民的堡垒。",al={"什么是佐拉姆海岸","佐拉姆海岸哨所","佐拉姆哨所"}},{q="向塞娜尼报到后会发生什么？",a="一旦你向塞娜尼·雷心报到，她会欢迎你加入岗哨，并立即引导你参与更广泛的狩猎任务，指引你去追踪并征服灰谷中最凶猛的野兽。",al={"灰谷狩猎之后是什么","塞娜尼之后的下一个任务","狩猎继续"}}},fp="18,197,28.304.0,21.314.0,39.191.0,35.171.0,27.166.0,38.189.0,51.173.0,39.169.0"}
P.entries["quest:743"] = {n="风怒鹰身人",s="“风怒的威胁”是卢尔·鹰爪在血蹄村提供的一项武备试炼。年轻的牛头人和部落冒险者们被指派去对抗筑巢于莫高雷东南悬崖上的凶残风怒鹰身人。在离开部族家园远行之前，狩猎这些凶猛的掠食者是检验技巧与生存能力的必要测试。",h="“风怒的威胁”是卢尔·鹰爪在血蹄村提供的一项武备试炼。年轻的牛头人和部落冒险者们被指派去对抗筑巢于莫高雷东南悬崖上的凶残风怒鹰身人。在离开部族家园远行之前，狩猎这些凶猛的掠食者是检验技巧与生存能力的必要测试。",kw={"血蹄村","风怒的威胁","鹰身人","莫高雷","卢尔·鹰爪","牛头人试炼","风怒","风怒鹰爪"},ang={["class:Warrior"]="对于有抱负的战士来说，卢尔·鹰爪的挑战意义非凡，他们必须学会格挡迅捷的俯冲打击，并以扎实的纪律压制这些凶残的空中伏击者。",["faction:Horde"]="参与卢尔试炼的牛头人盟友们证明了他们捍卫部落家园的决心，同时也赢得了血蹄村长久的尊敬。",["race:Tauren"]="对于年轻的牛头人来说，清理风怒巢穴既是捍卫平原的行动，也是在村中长者注视下迈向成年认同的神圣仪式。"},sec={{t="导师的评估",b="在血蹄村，老练的战士卢尔·鹰爪观察着每一位穿行于莫高雷中心的旅者。对于那些即将成年或是寻求证明自己已做好准备去迎接更广阔冒险的人，卢尔要求他们拿出战斗本能的切实证据。在莫高雷受庇护的峡谷之外生存，需要对付那些咄咄逼人的狡猾敌人，而卢尔正是利用这片土地上最凶猛的本土掠食者来衡量年轻人的勇气。"},{t="风怒的威胁",b="风怒鹰身人盘踞在莫高雷东南部的山区边缘，它们远离人迹罕至的道路，但始终对漫游的野生动物和落单的旅者构成威胁。这些鸟身怪凶残成性，渴望新鲜血肉，依靠迅捷的俯冲和锋利的爪子发动攻击。击败它们并夺取它们的爪子，不仅证明了拥有战胜顽固威胁的力量，也证明了能够反制空中袭击者的敏捷身手。"}},faq={{q="卢尔·鹰爪是谁？",a="卢尔·鹰爪是常驻于血蹄村的一位经验丰富的牛头人战士和导师。他指导年轻的冒险者，通过提供试炼来确保他们在动身前往卡利姆多更广阔、更危险的角落之前，具备所需的实力、反应能力和坚韧意志。",al={"卢尔·鹰爪","谁发布风怒的威胁任务","卢尔"}},{q="风怒鹰身人在莫高雷的什么地方？",a="风怒鹰身人栖息在莫高雷的东南部山区。它们将简陋的巢穴筑在岩架和山麓的高处，远离穿越峡谷的主路。",al={"风怒鹰身人位置","风怒鹰身人在哪里","风怒巢穴位置"}},{q="为什么风怒鹰身人被视为牛头人的天敌？",a="鹰身人是众所周知的极具攻击性、领地意识极强的食腐动物，它们会攻击任何擅闯其巢穴附近的人。在莫高雷，风怒族群以对新鲜血肉的贪婪渴望和对旅者及食草动物的不断侵扰而闻名，这使它们成为了平原上挥之不去的威胁。",al={"为什么牛头人要对抗鹰身人","莫高雷的鹰身人威胁","风怒背景知识"}},{q="卢尔·鹰爪要求从狩猎中获得什么证明？",a="卢尔要求冒险者从被击杀的鹰身人身上取回八只风怒鹰爪。割下并带回这些爪子，证明了冒险者能够制服这些鹰身人最主要的天然武器。",al={"风怒的威胁任务证明","为卢尔收集什么","风怒任务目标"}},{q="为什么冒险者在离开莫高雷之前必须通过这项试炼？",a="卢尔将凶猛的风怒鹰身人视为检验武备状况的理想标杆。如果一名冒险者无法应对鹰身人的速度、凶残和利爪，那么面对莫高雷防线之外那些潜伏着的更致命危险时，他们几乎毫无胜算。",al={"试炼的目的","为什么要做风怒的威胁任务","卢尔的测试"}},{q="血蹄村在哪里？",a="血蹄村位于莫高雷中心地带，靠近石牛湖，在大门和雷霆崖以南。它是牛头人旅者穿行平原时的文化、贸易和训练的主要枢纽。",al={"血蹄村位置","血蹄村在哪里","卢尔的位置"}}},fp="23,228,22.326.0,19.362.0,23.167.0,48.180.0,70.216.0,53.112.0,63.172.0,35.163.0"}
P.entries["quest:744"] = {n="准备典礼",s="仪式准备是牛头人的一种传统，重点在于为准备面见凯恩·血蹄大酋长的人制作仪式头饰。为了完成这套传统服饰，必须从雷霆崖外筑巢的危险鹰身人那里收集色彩鲜艳的羽毛，同时准备好皮革带。",h="仪式准备是牛头人的一种传统，重点在于为准备面见凯恩·血蹄大酋长的人制作仪式头饰。为了完成这套传统服饰，必须从雷霆崖外筑巢的危险鹰身人那里收集色彩鲜艳的羽毛，同时准备好皮革带。",kw={"凯恩·血蹄","仪式","羽毛","鹰身人","头饰","莫高雷","仪式准备","牛头人","雷霆崖"},ang={["faction:Horde"]="帮助部落的同胞完成他们传统的仪式职责，是对雷霆崖高原上牛头人盟友习俗的尊重。",["race:Tauren"]="用天然材料制作的头饰与牛头人的荣誉以及在大酋长面前的成人礼紧密相连。帮助制作此类礼服反映了莫高雷各部落的社区精神和自豪感。"},sec={{t="向大酋长致敬",b="在牛头人文化中，站在凯恩·血蹄大酋长面前是一件令人倍感自豪和崇敬的事情。这样的里程碑时刻需要得体的仪式服饰，尤其是用处理过的皮革和具有象征意义的羽毛精心制作的传统头饰。制作这套礼服被家族成员视为一种荣耀，他们会格外小心，以确保每一部分都能在联合部落的首领面前体现出尊严与尊重。"},{t="峭壁之羽",b="制作仪式头饰既需要技巧，也需要特定的材料。在将柔软的皮带鞣制成底带的同时，还必须找到长而原始的羽毛来装饰冠部。在雷霆崖北部和西北部的崎岖山丘上筑巢的鹰身人能提供所需尺寸和色泽完全吻合的羽毛，这就需要旅行者冒险进入充满敌意的巢穴去取回它们。"}},faq={{q="正在准备什么仪式？",a="这项仪式标志着一位牛头人即将面见凯恩·血蹄大酋长。为了纪念这一光荣的时刻，他的兄弟正在用鞣制的皮革和鲜艳的羽毛制作一种特殊的仪式头饰。",al={"这是什么仪式","仪式是什么","谁站在血蹄面前"}},{q="血蹄大酋长是谁？",a="凯恩·血蹄大酋长是受人尊敬的大酋长，也是联合牛头人部落的领袖，在雷霆崖的高原上进行统治。对他而言，站在他面前对任何牛头人来说都是一种特殊的荣誉。",al={"血蹄大酋长是谁","凯恩·血蹄","血蹄是谁"}},{q="为什么制作头饰需要鹰身人的羽毛？",a="仪式头饰需要特定尺寸和引人注目的羽毛——特别是天蓝色和青铜色的羽毛——以便在鞣制皮带的同时完成传统设计。",al={"为什么需要鹰身人羽毛","为什么是鹰身人羽毛","为什么要羽毛"}},{q="鹰身人在哪里？",a="那些产出羽毛的鹰身人栖息在莫高雷雷霆崖以北和西北方向很远的崎岖土地上。",al={"鹰身人住在哪里","去哪里找鹰身人","天蓝色和青铜色羽毛在哪里"}},{q="鹰身人在莫高雷扮演什么角色？",a="鹰身人是栖息在莫高雷周围岩石峭壁上的凶残的鸟人生物。除了对旅行者和部落构成威胁外，它们巨大而多彩的羽毛也使它们成为了仪式装饰品的主要来源。",al={"为什么要猎杀鹰身人","什么是鹰身人"}},{q="谁在制作仪式头饰？",a="艾安·鹰爪（Eyahn Eagletalon）正在鞣制皮带并制作头饰，以纪念他的兄弟准备在大酋长面前亮相。",al={"谁制作头饰","谁来制作头饰"}}},fp="24,307,22.430.0,21.430.0,36.217.0,23.195.0,48.194.0,30.131.0,37.226.0,41.150.0"}
P.entries["quest:745"] = {n="土地之争",s="由血蹄村的贝恩·血蹄指派，这项任务派遣年轻的部落冒险者去遏制当地白鬃豺狼人的破坏性偷猎行为。通过猎杀他们的制皮师、剥皮师和偷猎者，你保护了莫高雷的野生动物，并学习了牛头人与大地母亲和谐共处的哲学。",h="由血蹄村的贝恩·血蹄指派，这项任务派遣年轻的部落冒险者去遏制当地白鬃豺狼人的破坏性偷猎行为。通过猎杀他们的制皮师、剥皮师和偷猎者，你保护了莫高雷的野生动物，并学习了牛头人与大地母亲和谐共处的哲学。",kw={"贝恩·血蹄","血蹄村","豺狼人","莫高雷","白鬃","偷猎者","共享这片土地","剥皮师","制皮师"},ang={["class:Druid"]="德鲁伊们认识到，无节制的偷猎会破坏平原的灵魂，需要立即干预以修复土地的和谐。",["class:Hunter"]="白鬃剥皮师和偷猎者代表了真正猎人的对立面，他们残忍而浪费地屠杀野生生物，而非怀着敬意。",["faction:Horde"]="协助贝恩·血蹄加强了新部落冒险者与初生的牛头人国度领导层之间的纽带。",["race:Tauren"]="对于年轻的牛头人来说，响应贝恩的召唤是学习保卫莫高雷和尊崇大地母亲的平衡这一神圣职责的重要一步。"},sec={{t="失衡的土地",b="牛头人对自然世界怀有深深的敬意，只取生存之必要，在万事万物中尊崇大地母亲。白鬃豺狼人在血蹄村以南和西面的一处洞穴中定居，却毫无这种敬意。他们并未适度狩猎，而是在平原上疯狂屠戮野生动物，留下被剥皮的尸体和遭到破坏的生态系统。对于一个努力在莫高雷建立和平家园的种族来说，这种肆无忌惮的屠杀是无法容忍的。"},{t="当言语失效时",b="贝恩·血蹄起初希望能和平解决此事，试图与这些入侵的豺狼人展开对话。但白鬃豺狼人拒绝了所有的提议，以敌意和持续的破坏回应了外交努力。眼见谈判徒劳无功，贝恩转而使用武力。年轻的勇士们被直接派往他们的狩猎营地，在草原遭受永久性破坏之前铲除那些偷猎者、制皮师和剥皮师。"},{t="生与死的轮回",b="这项任务对成长中的勇士来说是一场成年礼和道德课。在完成猎杀任务归来后，贝恩提醒冒险者，夺取生命绝不能出于恶意，而必须是为了维持和谐的必要之举。生与死是一个相互关联的轮回，缺一不可，这是每一位莫高雷的守护者必须铭记在心的根本真理。"}},faq={{q="谁提供这个任务？",a="大酋长凯恩·血蹄之子，贝恩·血蹄，在莫高雷中部的血蹄村提供这项任务。",al={"任务发布者","谁开启共享这片土地","贝恩的任务"}},{q="为什么牛头人要针对白鬃豺狼人？",a="白鬃豺狼人疯狂地狩猎莫高雷的野生动物，在不尊重自然平衡的情况下消耗兽群数量。他们还拒绝了牛头人所有和平沟通的尝试。",al={"为什么要猎杀豺狼人","白鬃豺狼人问题","豺狼人做了什么"}},{q="这些豺狼人位于何处？",a="白鬃豺狼人在血蹄村以南设有营地，并居住在西面的白鬃石洞穴系统中。",al={"豺狼人位置","白鬃豺狼人营地","在哪里找到白鬃豺狼人"}},{q="牛头人是否先尝试过和平解决？",a="是的。贝恩指出，牛头人曾多次尝试沟通并共享这片土地，但豺狼人不仅不尊重，还拒绝了每一个和平的提议。",al={"牛头人是否与豺狼人沟通过","白鬃外交"}},{q="贝恩试图传达什么课程？",a="贝恩希望年轻的保卫者们理解，死亡与生命是一个不可分割的轮回。虽然为了捍卫平衡有时必须夺取生命，但必须始终怀着对大地母亲的深深敬意去行事。",al={"贝恩的教导","共享这片土地的含义"}},{q="白鬃豺狼人是谁？",a="他们是一个莫高雷本土的原始鬣狗类部族，以苍白的皮毛、领地侵略性和对平原和谐的完全无视而闻名。",al={"谁是白鬃豺狼人","白鬃部族"}}},fp="16,202,21.403.0,15.287.0,28.186.0,21.118.0,49.139.0,31.100.0,39.141.0,42.194.0,28.170.0"}
P.entries["quest:746"] = {n="矮人的挖掘场",s="“矮人的挖掘”是莫高雷的一个任务，由血蹄村的贝恩·血蹄发布。贝恩担心矮人的挖掘会激怒当地的野兽并亵渎神圣的土地，于是指派年轻的部落保卫者去没收并砸碎他们的十字镐，以破坏他们的挖掘工作。",h="“矮人的挖掘”是莫高雷的一个任务，由血蹄村的贝恩·血蹄发布。贝恩担心矮人的挖掘会激怒当地的野兽并亵渎神圣的土地，于是指派年轻的部落保卫者去没收并砸碎他们的十字镐，以破坏他们的挖掘工作。",kw={"贝恩·血蹄","血蹄村","矮人","熔炉","科多兽","莫高雷","十字镐","勘探员"},ang={["class:Shaman"]="萨满们明白，通过粗心的挖掘扰动基岩会打破元素平衡，并激起这片土地的灵魂和生物的不安。",["faction:Horde"]="这些蚕食部落腹地的联盟矮人破坏了第三次战争后建立的脆弱和平，公然无视部落的边界。",["profession:Mining"]="虽然矿工尊崇隐藏在石头中的财富，但矮人在莫高雷的手段绕过了尊重与和谐，选择了鲁莽的破坏。",["race:Tauren"]="大地母亲的身体是神圣的，看到外来的入侵者在莫高雷连绵的草原上钻探，这是一种必须立即予以坚决回应的冒犯。"},sec={{t="山丘上的入侵者",b="在血蹄村的西北方，矮人勘探员已经开始在莫高雷连绵的山丘中圈地挖掘。探险者协会及其挖掘队在整个卡利姆多搜寻泰坦圣物和大地秘密，但他们的行动很少尊重原住民的土地或习俗。对牛头人来说，大地是需要敬畏的活着的母亲，而不是为了石头和金属而被剥削和掏空的躯壳。"},{t="保卫神圣的大地",b="贝恩·血蹄认识到矮人的机械和无休止的爆破威胁到了平原脆弱的和谐。除了物理破坏之外，骚乱还激怒了当地的野生动物，导致平原上的科多兽陷入狂暴。通过在矮人自己的熔炉处砸碎勘探员的工具，牛头人希望传达一个直截了当的信息，并在造成持久伤害之前阻止这种蚕食行为。"}},faq={{q="为什么矮人在莫高雷挖掘？",a="矮人勘探员认为卡利姆多中部的大地深处隐藏着秘密和文物。然而，他们无视部落领地并使用暴力的采矿方法，这使他们与牛头人产生了直接冲突。",al={"莫高雷的矮人","勘探员为什么在这里","矮人挖掘莫高雷"}},{q="是谁发布了“矮人的挖掘”任务？",a="该任务由高阶酋长凯恩·血蹄的年轻儿子贝恩·血蹄发布，他位于莫高雷中部的血蹄村。",al={"矮人的挖掘任务发布者","谁开启矮人的挖掘"}},{q="为什么贝恩要求砸碎他们的工具，而不是仅仅偷走它们？",a="贝恩希望使这些设备彻底报废，以立即停止挖掘工作。在熔炉处摧毁工具传达了一个明确的象征性和实际意义：这片土地不会通过蛮力和亵渎来交出它的秘密。",al={"为什么要砸碎十字镐","砸碎矮人工具"}},{q="这种挖掘对莫高雷的野生动物有什么影响？",a="大声的挖掘和对地表的严重破坏极大地激怒了当地的生物，特别是漫游在山丘上的巨大科多兽，使原本平静的兽群变得焦躁且具有攻击性。",al={"愤怒的科多兽","为什么野兽会发狂"}},{q="在哪里可以砸碎十字镐？",a="十字镐可以在任何功能性的熔炉处被锤成废铁。玩家可以使用位于矮人挖掘营地内的熔炉，或者把它们带到雷霆崖的铁匠那里。",al={"熔炉在哪里","在熔炉砸碎勘探员十字镐"}},{q="这个任务与探险者协会在卡利姆多更广泛的活动有关联吗？",a="是的。来自铁炉堡的矮人远征队在整个卡利姆多建立了前哨站，包括莫高雷、贫瘠之地和卡利姆多南部，他们经常因领土主权和神圣土地问题与部落种族发生冲突。",al={"莫高雷探险者协会","卡利姆多的铁炉堡"}}},fp="15,202,24.363.0,26.315.0,35.185.0,36.130.0,63.159.0,52.156.0,31.131.0,75.217.0"}
P.entries["quest:747"] = {n="开始狩猎",s="“狩猎开始”是纳拉其营地红云台地年轻冒险者的一项基础试炼。在格鲁尔·鹰风的指派下，新兵们被派去猎杀当地的平原陆行鸟，为村庄提供肉和羽毛。完成这项任务是赢得鹰风酋长尊重并最终进入雷霆崖的第一步。",h="“狩猎开始”是纳拉其营地红云台地年轻冒险者的一项基础试炼。在格鲁尔·鹰风的指派下，新兵们被派去猎杀当地的平原陆行鸟，为村庄提供肉和羽毛。完成这项任务是赢得鹰风酋长尊重并最终进入雷霆崖的第一步。",kw={"纳拉其营地","鹰风酋长","羽毛","格鲁尔·鹰风","狩猎开始","莫高雷","平原陆行鸟","红云台地"},ang={["class:Hunter"]="追踪红云台地迅捷的平原陆行鸟，是射击、追踪和尊重那些供养你的野兽的最早实践练习。",["race:Tauren"]="对于年轻的舒哈鲁来说，猎杀你的第一只台地平原陆行鸟是一项必不可少的成年仪式，它确认了你与这片土地的羁绊，以及你供养纳拉其营地的职责。"},sec={{t="部落的补给",b="在红云台地的高处，生存与传统交织在一起。牛头人狩猎不仅是为了维持族人的温饱，也将跟踪和追捕视作一种磨练纪律和运动能力的重要考验。当纳拉其营地的储备不足时，社区便会指望年轻一代去收集新鲜的平原陆行鸟肉供烹饪使用，并获取结实的羽毛用于制作部落服饰。"},{t="获得认可",b="没有哪个有抱负的英雄能在不证明自己价值的情况下，就直接走出红云台地，踏入莫高雷更广阔的天地。格鲁尔·鹰风是新人们性格的主要评判者，他坚持要求新兵必须先证明自己的能力，然后才能去见他的父亲——鹰风酋长。完成一次干净利落的狩猎，不仅展现了独立生存的能力，也体现了对部落的奉献。"}},faq={{q="谁发布了这个任务？",a="格鲁尔·鹰风在纳拉其营地发布了这项任务。他是村庄领袖鹰风酋长的儿子，也是红云台地上年轻猎人和冒险者的早期导师。",al={"任务发布者","谁开启了狩猎开始","格鲁尔·鹰风"}},{q="为什么猎杀平原陆行鸟而不是其他野兽？",a="平原陆行鸟在台地上随处可见，不仅能提供充足的肉类来补充日益减少的食物储备，其结实的羽毛还可用于牛头人的传统服饰和装饰品。",al={"为什么选择平原陆行鸟","平原陆行鸟肉和羽毛","狩猎平原陆行鸟"}},{q="为什么我必须先证明自己才能见到鹰风酋长？",a="牛头人社会非常重视实际贡献和狩猎本领。格鲁尔·鹰风要求新兵在获得酋长的接见并承担更重要的职责之前，先展示其基本的生存技能和对村庄的忠诚。",al={"为什么要向鹰风酋长证明自己","鹰风酋长的认可","为什么要先狩猎"}},{q="在红云台地进行这些试炼的更宏大的目标是什么？",a="台地是一个试炼场。一旦年轻的牛头人向鹰风酋长和纳拉其营地的长者证明了自己的能力，他们就被认为做好了准备，可以下山进入莫高雷的广阔平原，并进入主城雷霆崖。",al={"台地试炼的目的","为什么我在红云台地","离开红云台地"}},{q="这次狩猎之后是什么？",a="成功带回肉和羽毛能赢得格鲁尔的认可，随后将直接进行“狩猎继续”，新兵们将在台地上追踪更大型、更难以捉摸的猎物。",al={"下一个任务","后续任务","狩猎开始之后是什么"}},{q="牛头人只为了生存而狩猎吗？",a="虽然维持生计以及获取皮革、骨骼和羽毛等资源至关重要，但牛头人也将狩猎作为一种体育运动和精神交流，这能磨练他们的直觉，使部落时刻保持警惕和强大。",al={"牛头人的狩猎哲学","为了运动而狩猎","牛头人为什么要狩猎"}}},fp="15,194,20.265.0,19.254.0,21.122.0,53.159.0,59.148.0,59.122.0,27.132.0,33.187.0"}
P.entries["quest:748"] = {n="毒水",s="“毒水”任务开启了牛头人清除莫高雷圣井污染的行动。在血蹄村的穆尔·雷角委托下，年轻的部落保卫者们从平原上收集天然材料，以制作恢复性的仪式图腾。",h="“毒水”任务开启了牛头人清除莫高雷圣井污染的行动。在血蹄村的穆尔·雷角委托下，年轻的部落保卫者们从平原上收集天然材料，以制作恢复性的仪式图腾。",kw={"血蹄村","净化图腾","莫高雷","穆尔·雷角","陆行鸟","毒水","草原狼","冰蹄水井"},ang={["class:Druid"]="地精污染淡水泉是对自然平衡的直接攻击，必须立即采取行动以保护莫高雷脆弱的动植物群。",["class:Shaman"]="通过野兽力量强化的图腾来恢复受污染的水源，阐释了牛头人萨满之道的基础：与当地野生动物并肩协作，以修复元素紊乱。",["race:Tauren"]="对淡水的亵渎打击了大地母亲馈赠的核心，这使得净化仪式成为任何在莫高雷成年的牛头人的基本职责。"},sec={{t="遭亵渎的土地",b="莫高雷的青草平原对于牛头人而言是圣地，但阴险的势力已经开始威胁到他们的生命之源。驻扎在血蹄村的长者穆尔·雷角发现，地精入侵者及其爪牙污染了维持部落和当地野生动物生存的珍贵水井。这种污染直接打击了这群刚定居于此的游牧民族的精神核心。"},{t="收集自然精华",b="为了对抗工业污染物，穆尔不依靠粗糙的手段，而是依循传统的牛头人萨满之道。净化冰蹄水井需要制作一种强大的仪式图腾，并注入莫高雷本土掠食者的生命力。他派遣猎人前往西南平原追踪草原狼以获取它们的爪子，并寻找成熟的陆行鸟获取它们的利爪，借用大地的力量来治愈它自身的创伤。"}},faq={{q="是谁污染了莫高雷的水井？",a="地精入侵者及其雇佣兵应对玷污莫高雷各地的圣洁水潭负责。他们破坏性的工业作业和对自然平衡的漠视，威胁着牛头人部落和当地的野生动物。",al={"谁污染了水井","谁毒害了莫高雷","谁污染了水源"}},{q="穆尔·雷角为什么需要狼爪和陆行鸟利爪？",a="穆尔利用从莫高雷本土野兽身上收集的部分来制作传统的净化图腾。通过驾驭平原掠食者与生俱来的灵魂与力量，他创造出了一种足够强大的媒介，用于进行净化水源的仪式。",al={"为什么要狼爪","为什么要陆行鸟利爪","图腾材料"}},{q="这个任务准备净化哪口水井？",a="此项任务收集的材料专用于制作冰蹄水井的净化图腾，这是首个需要仪式净化的受污染水井。",al={"这是为了哪口井","哪口水井"}},{q="穆尔·雷角在哪里？",a="穆尔·雷角居住在血蹄村，这是位于莫高雷中部，环绕石牛湖水域的主要牛头人定居点。",al={"穆尔·雷角位置","穆尔在哪里","毒水任务交付地点"}},{q="在哪里可以找到所需的狼和陆行鸟？",a="草原狼和成年陆行鸟在血蹄村西南方的草海平原上游荡。",al={"哪里可以找到草原狼","陆行鸟位置","狩猎场"}},{q="穆尔收到爪子和利爪后会发生什么？",a="穆尔将收集到的材料绑定制成冰蹄之井净化图腾，并委派你将其直接带往冰蹄水井以执行净化仪式。",al={"毒水之后的下一个任务","接下来要做什么"}}},fp="12,209,17.314.0,26.308.0,40.140.0,65.128.0,46.77.0,34.109.0,58.86.0,53.143.0"}
P.entries["quest:749"] = {n="被破坏的货车",s="摩林·云行者指引旅行者去调查石牛湖北岸附近被伏击的荆棘谷地精货车的残骸。虽然牛头人为了报复失去的同伴而焚毁了这支车队，但地精打捞者却回来回收完好的货物。调查幸存下来的补给箱，揭示了荆棘谷地精在莫高雷工业行动的真实规模。",h="摩林·云行者指引旅行者去调查石牛湖北岸附近被伏击的荆棘谷地精货车的残骸。虽然牛头人为了报复失去的同伴而焚毁了这支车队，但地精打捞者却回来回收完好的货物。调查幸存下来的补给箱，揭示了荆棘谷地精在莫高雷工业行动的真实规模。",kw={"摩林·云行者","莫高雷","被破坏的货车","石牛湖","补给箱","荆棘谷地精"},ang={["faction:Horde"]="荆棘谷地精在莫高雷肆无忌惮的企业扩张威胁到了雷霆崖的稳定，需要部落斥候去破坏荆棘谷地精的后勤。",["profession:Mining"]="这些坚固的板条箱和后勤记录证明了荆棘谷地精正在莫高雷全境进行积极的矿物勘探和开采活动。",["race:Tauren"]="荆棘谷地精的机器和伐木行动对平原造成的破坏直接打击了你的祖居之地，因此回收并摧毁他们的物资对于保卫莫高雷至关重要。"},sec={{t="湖畔的报复",b="石牛湖北岸那些焦黑的遗迹是牛头人迅速打击的结果。因为在之前的一次冲突中失去了两名同伴，摩林·云行者和他的战士们悲愤之下伏击了一支武装的荆棘谷地精补给车队。牛头人意图彻底摧毁入侵者的心血，便烧毁了货车，并离开了这片冒烟的废墟，认为大火会吞噬地精们试图运走的一切。"},{t="未竟之事",b="牛头人很快注意到有荆棘谷地精的打捞者在搜寻焦黑的残骸，这表明他们的大火没能摧毁最关键的货物。摩林不愿盲目冒险折损人手，便派遣斥候去检查残骸。在沾满煤烟的废墟中，放着标有荆棘谷地精采矿部门徽记的完好箱子，它们被打包好，正准备运往中央处理设施。"}},faq={{q="为什么这辆货车会被摧毁？",a="在之前与荆棘谷地精的冲突中失去了两名斥候后，摩林·云行者和他的牛头人战士为了报复，伏击并烧毁了这辆货车。",al={"谁摧毁了货车","为什么货车会被烧毁","袭击货车"}},{q="被破坏的货车位于何处？",a="烧毁的货车位于石牛湖北岸，莫高雷血蹄村的东面。",al={"货车位置","货车在哪里","被破坏的货车地点"}},{q="为什么地精会回到残骸现场？",a="因为大火没能摧毁所有的货物，荆棘谷地精派出了打捞者。他们试图取回那些盖有印章、准备运往其中央处理机构的耐用补给箱。",al={"为什么打捞者会在这里","荆棘谷地精打捞者","地精想要什么"}},{q="补给箱里有什么？",a="这些箱子上带有荆棘谷地精采矿部门的徽记，里面装有标明将运往其主要工业工厂进行精炼和处理的矿物资源。",al={"补给箱内容","补给箱里有什么","密封的补给箱"}},{q="摩林·云行者是谁？",a="摩林·云行者是一位驻扎在血蹄村东面的牛头人斥候兼追踪者，负责监视莫高雷中部发生的敌对入侵，尤其是来自荆棘谷地精的威胁。",al={"摩林是谁","摩林·云行者的职责"}},{q="这辆货车揭示了关于荆棘谷地精的什么信息？",a="它表明荆棘谷地精在莫高雷的存在不仅仅是一个勘探队，而是一个拥有武装补给线和集中式精炼网络的有组织的工业开采行动。",al={"荆棘谷地精在莫高雷的活动","为什么地精在莫高雷"}}},fp="19,298,23.313.0,19.368.0,30.176.0,37.100.0,46.185.0,33.171.0,26.185.0,56.206.0"}
P.entries["quest:7493"] = {n="一切才刚刚开始",s="“旅程才刚刚开始”是部落的一项任务，由奥格瑞玛提供给击败奥妮克希亚后的制皮大师。伦萨克大王认可了英雄的技艺，并传授了从这位龙族巢母的鳞片中制作防护披风所需的稀有技法。这项至关重要的工艺为部落应对黑石塔内致命的烈焰做好了准备。",h="“旅程才刚刚开始”是部落的一项任务，由奥格瑞玛提供给击败奥妮克希亚后的制皮大师。伦萨克大王认可了英雄的技艺，并传授了从这位龙族巢母的鳞片中制作防护披风所需的稀有技法。这项至关重要的工艺为部落应对黑石塔内致命的烈焰做好了准...",kw={"黑石","巢母","披风","制皮","伦萨克","奈法利安","奥妮克希亚","鳞片"},ang={["faction:Horde"]="对于部落而言，利用从敌人的尸骸上铸造的防护装备，对于保护部队免遭巨龙进一步的蹂躏至关重要。"},sec={{t="巢母的遗产",b="奥妮克希亚的陨落是部落的一大胜利，但这并不意味着黑龙军团带来的威胁已经结束。巢母鳞片的表皮对于龙炎具有显著的抗性。部落领袖不希望这些材料被浪费，因此正在寻找能够将巨龙遗骸转化为防御性护甲的工匠。"},{t="暗影烈焰之盾",b="伦萨克大王教导有天赋的制皮师如何缝制奥妮克希亚鳞片披风。这些知识不仅仅是为了炫耀或地位。在黑石山的深处，奥妮克希亚的兄弟奈法利安正挥舞着毁灭性的烈焰吐息。如果没有这件由巢母鳞片制成的附魔披风所提供的保护，任何直面黑石领主的先遣部队都会化为灰烬。"}},faq={{q="谁提供这项任务，他们在哪里？",a="这项任务由奥格瑞玛的伦萨克大王提供。他认可了那些精通制皮技艺并参与了奥妮克希亚讨伐战的部落勇士。",al={"伦萨克任务提供者","伦萨克大王在哪里","任务起始"}},{q="接受这项任务需要什么条件？",a="这项任务仅提供给那些精通制皮术，且完成了奥妮克希亚战后相关任务的勇士，例如“部落的胜利”或“最令人困惑的情况”。",al={"制皮要求","如何获得任务","前置条件"}},{q="伦萨克大王传授什么？",a="伦萨克大王指导制皮师使用从已故巢母身上采集的鳞片来制作奥妮克希亚鳞片披风的技法。",al={"任务奖励配方","奥妮克希亚披风图纸","我学到了什么"}},{q="为什么奥妮克希亚鳞片披风很重要？",a="这件披风能保护佩戴者免受黑石领主奈法利安致命烈焰吐息的伤害。如果没有其独特的防护属性，直面这位龙族主人将是致命的。",al={"为什么要制作披风","披风的作用","奈法利安披风"}},{q="谁是黑石领主？",a="黑石领主是奈法利安，一条强大的黑龙，也是奥妮克希亚的兄弟。他正盘踞在黑石山之巅，策划着统治凡人种族的阴谋。",al={"谁是黑石领主","奈法利安身份","黑石领主"}},{q="为什么任务说旅程才刚刚开始？",a="尽管奥妮克希亚已被击杀，但针对黑龙军团的全面战争以及奈法利安在黑石山内的阴谋才刚刚升级。",al={"标题的含义","为什么说旅程才刚刚开始"}}},fp="26,264,22.258.0,27.347.1,49.139.0,49.183.0,33.136.0,40.147.0,29.158.0,57.142.0"}
P.entries["quest:7497"] = {n="一切才刚刚开始",s="此任务代表了在击败奥妮克希亚后，一位经验丰富的工匠所获得的来之不易的认可。玛丁雷少校传授了制作奥妮克希亚鳞片披风所需的重要技巧，将这位陨落的育母留下的遗骸转变为抵御她兄弟的必要护具。",h="此任务代表了在击败奥妮克希亚后，一位经验丰富的工匠所获得的来之不易的认可。玛丁雷少校传授了制作奥妮克希亚鳞片披风所需的重要技巧，将这位陨落的育母留下的遗骸转变为抵御她兄弟的必要护具。",kw={"黑龙军团","黑石","制皮","玛丁雷少校","奈法利安","奥妮克希亚","奥妮克希亚鳞片披风","暴风城"},ang={["faction:Alliance"]="此任务将暴风城在奥妮克希亚一役中来之不易的胜利，与即将对她在黑石山的兄弟奈法利安发起的攻势联系在了一起。"},sec={{t="稀有的大师技艺",b="虽然许多勇士都可以声称自己击败了育母奥妮克希亚，但很少有人能同时拥有强大的武艺和处理她那坚韧外皮所需的大师级制皮技能。当具备这些天赋的英雄向暴风城的玛丁雷少校报告时，这位军官会意识到这些制作技能对于未来的战斗至关重要。"},{t="抵御黑龙军团的防护",b="奥妮克希亚之死并未终结黑龙军团的威胁。玛丁雷少校教导工匠如何处理并将这位育母的鳞片缝制成奥妮克希亚鳞片披风。这件独特的装备提供了专门的防护，用来抵御奥妮克希亚的兄弟，黑石之王奈法利安那具有毁灭性的烈焰吐息。"}},faq={{q="谁提供了任务“旅程刚刚开始”？",a="暴风城的玛丁雷少校会向那些在对抗奥妮克希亚的战役中证明过自己，并且拥有大师级制皮技能的联盟英雄提供此任务。",al={"谁提供旅程刚刚开始任务","在哪里接取旅程刚刚开始","旅程刚刚开始任务发布者"}},{q="此任务传授什么？",a="完成此互动后，大师级制皮师将学会制作奥妮克希亚鳞片披风的配方，这件物品是专门使用奥妮克希亚的鳞片剪裁而成的。",al={"我能获得什么配方","奥妮克希亚鳞片披风配方","旅程刚刚开始任务奖励"}},{q="为什么需要奥妮克希亚鳞片披风？",a="这件披风经过特殊处理，可以保护穿着者抵御黑石之王奈法利安那致命的烈焰吐息，这使它成为面对黑龙军团余下首领时不可或缺的装备。",al={"为什么要用奥妮克希亚鳞片披风","奥妮克希亚鳞片披风有什么用","暗影烈焰防护"}},{q="玛丁雷少校提到的黑石之王是谁？",a="黑石之王是奈法利安，他是奥妮克希亚的兄弟，一条强大的黑龙。他统治着黑石塔，并继续执行着黑龙军团的阴谋。",al={"谁是黑石之王","奈法利安是谁","玛丁雷关于龙的警告"}},{q="为什么英雄必须是制皮师才能获得这些知识？",a="在不破坏龙鳞先天魔法防护的情况下对其进行采集、淬炼和缝制的技巧，需要经验丰富的大师级制皮师所具备的高深专业知识。",al={"为什么仅限制皮","任何人都能接这个任务吗","制皮等级要求"}},{q="奥妮克希亚之死消除了暴风城的黑龙威胁了吗？",a="没有。尽管奥妮克希亚本人已被击杀，但她的兄弟奈法利安依然掌控着黑石山，并继续策划针对联盟和凡人种族的阴谋。",al={"暴风城现在安全了吗","奥妮克希亚死了接下来做什么","奥妮克希亚之后的黑龙军团"}}},fp="26,138,14.214.0,41.241.1,48.138.0,27.101.0,40.99.0,58.153.0,63.118.0,65.131.1"}
P.entries["quest:75"] = {n="斯塔文的传说",s="这次针对斯塔文·密斯曼特的调查将你带出了暮色森林，来到了艾尔文森林东南部的一处偏僻住宅。治安官哈格德是一位视力衰退、年迈的老兵，他指引你前往楼上的一个箱子，那里存放着他搬进来时遗留下来的一捆旧文件。",h="这次针对斯塔文·密斯曼特的调查将你带出了暮色森林，来到了艾尔文森林东南部的一处偏僻住宅。治安官哈格德是一位视力衰退、年迈的老兵，他指引你前往楼上的一个箱子，那里存放着他搬进来时遗留下来的一捆旧文件。",kw={"暮色森林","艾尔文森林","褪色的日记书页","弃灵","治安官哈格德","斯塔文"},ang={["faction:Alliance"]="揭开斯塔文的遗产揭露了艾尔文森林平静祥和的田园表象下所掩盖的黑暗篇章。",["race:Human"]="斯塔文的行踪穿过了普通的人类定居点，成为了一个关于隐藏在众目睽睽之下的孤立与恶意的警世故事。"},sec={{t="老兵的阁楼",b="治安官哈格德居住在艾尔文森林东南部边缘、靠近暮色森林与赤脊山交界处的偏远地带。当他搬进这处隐蔽的住所时，发现楼上藏着一个装满旧羊皮纸的箱子。由于视力衰退，他放弃了阅读这些文件的尝试，让它们一直尘封着，直到有调查者前来打听斯塔文的消息。"},{t="挥之不去的阴影",b="留在楼上箱子里的文件并非普通的家居垃圾。翻动斯塔文的遗物会扰动不安的魔法，引出一个与密斯曼特的过去息息相关的弃灵。藏在里面的日记书页提供了斯塔文私人手记的直接记录，确凿地证明了这位隐居的学者在消失前曾在艾尔文留下过痕迹。"}},faq={{q="治安官哈格德是谁？",a="治安官哈格德是一位年迈且几近失明的老兵，安静地生活在艾尔文森林东南部的一间僻静小屋里。他保存着在屋子里发现的、属于斯塔文·密斯曼特的被遗忘已久的文件。",al={"治安官哈格德","哈格德 艾尔文","哈格德是谁"}},{q="为什么线索会指向艾尔文森林？",a="在夜色镇和月溪镇收集的线索追溯了斯塔文在暴风城南部领地的游荡轨迹。哈格德的家宅中藏有斯塔文遗留下的旧文件。",al={"为什么是艾尔文森林","斯塔文 艾尔文","为什么要找哈格德"}},{q="楼上的箱子里有什么？",a="箱子里装着一张斯塔文·密斯曼特书写的褪色的日记书页，它被保存在一捆哈格德从未能仔细查阅过的羊皮纸中。",al={"楼上的箱子","褪色的日记书页","箱子里有什么"}},{q="为什么打开箱子时会有灵魂攻击？",a="一个弃灵徘徊在斯塔文往昔生活的遗物周围，当外人打扰他的私人笔记和记忆时，它便会狂暴地显现。",al={"弃灵","为什么幽灵会攻击","哈格德屋子里的幽灵"}},{q="这如何推进对斯塔文的调查？",a="这张褪色的书页提供了斯塔文亲笔写下的第一手证据，有助于拼凑出他过去的经历。",al={"斯塔文之谜","书页揭示了什么","斯塔文任务线进度"}},{q="为什么治安官哈格德自己无法阅读这些文件？",a="哈格德的视力随着年龄增长变得模糊不清，无法辨认出褪色文件上细小或风化的笔迹。",al={"哈格德 失明","为什么哈格德需要帮助"}}},fp="21,183,17.277.0,17.288.1,23.160.0,45.143.0,34.136.0,50.115.0,48.95.1,53.120.0"}
P.entries["quest:750"] = {n="继续狩猎",s="“狩猎继续”是格鲁尔·鹰风在纳拉其营地布置的一项早期的成人礼仪式。该任务要求有抱负的猎手从南部的丘陵收集山地美洲狮皮，用以缝制部落孩子们的衣服并修补他们的帐篷。",h="“狩猎继续”是格鲁尔·鹰风在纳拉其营地布置的一项早期的成人礼仪式。该任务要求有抱负的猎手从南部的丘陵收集山地美洲狮皮，用以缝制部落孩子们的衣服并修补他们的帐篷。",kw={"纳拉其营地","鹰风酋长","格鲁尔·鹰风","山地美洲狮皮","红云台地","牛头人狩猎","狩猎继续"},ang={["class:Hunter"]="这项任务强化了平原狩猎的核心哲学：以目的为导向去追踪野兽，只取所需，绝不将动物视为单纯的运动或战利品。",["race:Tauren"]="对于在红云台地成年的年轻牛头人来说，认识到野兽的每一个部分都必须服务于部落——从食物到衣物和住所——是必不可少的成人礼仪式。"},sec={{t="狩猎的目的",b="在纳拉其营地，年轻的猎手们会被教导：猎杀野兽绝非闲来无事或为了搜集战利品。格鲁尔·鹰风指示初出茅庐的冒险者前往红云台地的南部丘陵追踪山地美洲狮。这项任务强调的不仅仅是展现武艺，更是对社区的责任感，以此表明真正的猎手必须为族人提供必要的补给。"},{t="部落的庇护所",b="台地上的生活需要耐用的材料来抵御自然环境的侵袭。格鲁尔解释说，急需美洲狮皮来为部落的孩子们缝制衣服，并修补纳拉其营地各处的皮质帐篷。证明自己有能力获取这些珍贵的毛皮将赢得长者的感激，格鲁尔承诺会将猎手无私贡献的消息直接传达给他的父亲——鹰风酋长。"}},faq={{q="部落为什么需要山地美洲狮皮？",a="山地美洲狮的毛皮对纳拉其营地来说是至关重要的实用资源。格鲁尔·鹰风解释说，这些毛皮需要用来制作供部落孩子们御寒的衣物，并修补和加固村庄的帐篷。",al={"为何狩猎美洲狮","美洲狮皮的用途","山地美洲狮皮的用途"}},{q="谁发布了这个任务？",a="这项狩猎任务由格鲁尔·鹰风负责，他是纳拉其营地的一位杰出猎手，也是鹰风酋长的儿子。他指引着新手冒险者去学习支持定居点的基本职责。",al={"谁发布了狩猎继续","纳拉其营地任务发布者"}},{q="在哪里可以找到山地美洲狮？",a="山地美洲狮在纳拉其营地南部红云台地的岩石山脊和起伏的丘陵中徘徊。",al={"美洲狮在哪里","山地美洲狮位置","哪里寻找山地美洲狮"}},{q="格鲁尔·鹰风与鹰风酋长是什么关系？",a="格鲁尔·鹰风是纳拉其营地部落首领鹰风酋长的儿子。如果你能提供所需的毛皮，格鲁尔承诺会代表你向他的父亲进言，并分享你的慷慨义举。",al={"如何给鹰风酋长留下印象","鹰风酋长的儿子"}},{q="这项狩猎任务传达了什么样的牛头人传统？",a="在牛头人之中，狩猎从不被视为一项运动或获取战利品的途径。从大地上猎杀的每一只野兽都旨在维持社区的生存，通过利用毛皮、肉和骨头来延续部落，从而尊重大地。",al={"牛头人狩猎哲学","为何在莫高雷狩猎"}},{q="为什么山地美洲狮皮被认为很有价值？",a="美洲狮皮厚实、耐用，非常适合在风吹雨打的平原上抵御自然环境。因为它们能为年幼的孩子提供温暖，也是补缀居所的坚固材料，所以被村里的长者所珍视。",al={"美洲狮皮是否有价值","为何美洲狮皮很珍贵"}}},fp="18,230,23.420.0,21.427.0,46.228.0,22.197.0,37.124.0,54.202.0,49.220.0,55.228.0"}
P.entries["quest:751"] = {n="被破坏的货车",s="在莫高雷调查一辆破碎的运输车时发现，地精实业家们已经在牛头人的领地上建立了一个非法的立足点。通过从一个密封的补给箱中找回文件，斥候们确认荆棘谷地精正在系统性地剥夺这片土地的矿产财富。这一发现促使血蹄先锋们开始积极保卫他们祖先的平原。",h="在莫高雷调查一辆破碎的运输车时发现，地精实业家们已经在牛头人的领地上建立了一个非法的立足点。通过从一个密封的补给箱中找回文件，斥候们确认荆棘谷地精正在系统性地剥夺这片土地的矿产财富。这一发现促使血蹄先锋们开始积极保卫他们...",kw={"血蹄村","摩林·云行者","莫高雷","先锋","被破坏的货车","补给箱","荆棘谷地精","荆棘谷地精文件"},ang={["class:Druid"]="德鲁伊们视土地的平衡为神圣，这使得荆棘谷地精那破坏性的、烟雾缭绕的露天采矿成为必须被清除的亵渎行为。",["faction:Horde"]="部落依靠莫高雷的忠诚和稳定；任由外来的商业财团掠夺这里的山丘，将威胁到雷霆崖自身的安全。",["profession:Mining"]="箱子里装的高品位矿石证明，莫高雷的东部丘陵隐藏着丰富的地下矿脉，外来者正竞相开采这些矿脉。",["race:Tauren"]="对于牛头人来说，看到粗糙的工业机器撕裂莫高雷祖先的平原，这是对大地母亲的冒犯，也是对他们来之不易的和平发动的战争。"},sec={{t="剥削的证据",b="血蹄村以东一辆被破坏的货车的残骸诉说着令人不安的事实。在一个密封的补给箱里，存放着大量开采的矿石和矿物，旁边还有一捆扎好的荆棘谷地精文件。这些文书提供了无可辩驳的证据，证明贪婪的荆棘谷地精已经开始在莫高雷宁静的山谷深处进行未经许可的采矿作业。"},{t="先锋们的警戒",b="摩林·云行者和他的先锋同伴们一直警惕地守望着莫高雷的边界，防范着那些企图剥削他们和平家园的外来势力。递交了找回的文件证实了摩林最担心的事：东部丘陵上升起的浓烟预示着商业入侵正在升级。牛头人别无选择，只能在他们的山丘被彻底摧毁之前反击这些污染者。"}},faq={{q="密封的补给箱里有什么？",a="撬开箱子后，里面装满了开采的矿石、原材料，以及一捆列明了荆棘谷地精行动计划的文件。",al={"补给箱战利品","箱子里有什么","箱子内容物"}},{q="摩林·云行者是谁？",a="摩林·云行者是一名牛头人先锋，驻扎在血蹄村东往贫瘠之地边界的路上，负责巡逻莫高雷并追踪外来威胁。",al={"摩林是谁","摩林·云行者的职责","先锋摩林"}},{q="为什么荆棘谷地精会在莫高雷？",a="荆棘谷地精试图无情地开采莫高雷丰富的自然资源和矿脉，在不顾土地及其原住民的情况下挖掘丘陵。",al={"地精为什么在这里","荆棘谷地精在莫高雷的目标","地精想要什么"}},{q="这辆货车从哪里来？",a="这辆货车属于荆棘谷地精，负责将从山脚开采的矿石和行动文书运输出去，随后在路上被摧毁。",al={"这是谁的货车","货车来源","谁袭击了货车"}},{q="这次调查接下来会引向何处？",a="带着这些文件，摩林·云行者指引战士们直接对抗荆棘谷地精的领导层，并捣毁他们在东部丘陵的采矿作业。",al={"what comes next","被破坏的货车之后的下一个任务","追踪货车线索"}},{q="为什么这对牛头人构成威胁？",a="牛头人视土地为神圣，并敬畏大地母亲。荆棘谷地精鲁莽的露天开采和工业污染正在积极地玷污莫高雷原始的景观。",al={"牛头人为什么关心","荆棘谷地精威胁","莫高雷的威胁"}}},fp="19,373,24.371.0,21.434.0,39.146.0,26.176.0,38.180.0,32.169.0,40.178.1,34.178.0"}
P.entries["quest:752"] = {n="一件琐事",s="“谦卑的任务”是纳拉其营地中的鹰风酋长交给年轻勇士的一项早期义务仪式。酋长由于在红云台地忙于处理部落的紧急事务，便请求一位年轻的冒险者前往东南方，查看他在当地水井旁的老母亲。这个请求强调了集体责任、尊老敬老，以及牛头人生活中不可或缺的日常和谐。",h="“谦卑的任务”是纳拉其营地中的鹰风酋长交给年轻勇士的一项早期义务仪式。酋长由于在红云台地忙于处理部落的紧急事务，便请求一位年轻的冒险者前往东南方，查看他在当地水井旁的老母亲。这个请求强调了集体责任、尊老敬老，以及牛头人生...",kw={"谦卑的任务","纳拉其营地","鹰风酋长","鹰风酋长的母亲","莫高雷","红云台地","水井"},ang={["faction:Horde"]="纳拉其任务中宁静、田园牧歌般的性质突显了牛头人安宁的集体哲学，这与初生的部落在其他地方所展现出的严酷生存磨砺形成了鲜明对比。",["race:Tauren"]="对于年轻的牛头人勇士来说，响应酋长的号召展现了大地母亲教诲的核心原则：尊敬长者，并毫无保留地投身于维护部落共享的福祉。"},sec={{t="集体和谐与责任",b="在纳拉其营地的阴影下，部落的每一位成员都被期待着能尽一份力，共享生活的和谐。对于即将成年的年轻牛头人来说，部落的职责并不仅仅是以击败野猪人或掠食者来衡量战功；它始于基本的社会责任。鹰风酋长直接体现了这一准则：由于行政和防御上的领导职责，他无法离开岗位，因此他将照顾部落弱势长者的信任寄托在了新手冒险者身上。"},{t="纳拉其东南方的水井",b="莫高雷的红云台地依赖于散布在营地周边地区的重要天然水井。清晨时分，鹰风酋长的母亲离开村庄去东南方的泉水处取新鲜水源，却迟迟未归。在这片充满了领地意识强烈的野生动物和不断侵扰的刺鬃野猪人的土地上，一位长者长时间未归引起了小小的担忧，促使酋长派遣援助以确保她平安无事。"}},faq={{q="谁发布了这个任务，我在哪里能找到他们？",a="莫高雷红云台地纳拉其营地的首领鹰风酋长发布了该任务。他站在营地的中央亭子里，负责统筹当地事务。",al={"谁发布谦卑的任务","任务在哪里领取","鹰风酋长位置"}},{q="鹰风酋长的母亲在哪里？",a="鹰风酋长的母亲位于纳拉其营地东南方，正在台地低处照看水井。",al={"鹰风酋长的母亲位置","母亲在哪里","水井位置"}},{q="为什么鹰风酋长不亲自去查看他的母亲？",a="鹰风酋长必须留在纳拉其营地，以监督紧迫的部落事务并指导年轻的勇士。作为一名酋长，他仰仗部落的共同责任感，并信任成长中的冒险者能替他照顾村里的事务。",al={"为什么酋长不能去","为什么鹰风酋长不去查看","鹰风酋长很忙"}},{q="鹰风酋长的母亲在水井那里有危险吗？",a="虽然周围的平原上出没着好斗的山地美洲狮和陆行鸟，但鹰风酋长的母亲在水井旁安然无恙，她对有人特意前来探望一位长者感到十分惊喜。",al={"她安全吗","鹰风酋长的母亲受到攻击了吗","水井处有危险吗"}},{q="这个任务对牛头人有着怎样的文化意义？",a="牛头人文化极其重视家庭、社区凝聚力和对长者的尊敬。这个任务教导年轻的英雄，真正的力量源于谦卑的服务和保护自己的亲人，而不是追逐个人的荣耀。",al={"牛头人文化谦卑的任务","为什么这是一个谦卑的任务","牛头人长者"}},{q="找到鹰风酋长的母亲之后会发生什么？",a="一旦你与鹰风酋长的母亲交谈，她就会完成任务，并请求你进一步协助，将装满的水罐带回营地。",al={"后续任务","谦卑的任务后续","找到母亲后该做什么"}}},fx={b1d313d3={q="鹰风酋长为什么要你去看看他的母亲？",a="他的老母亲一大早就离开纳拉其营地，去东南方的水井打水，至今已经离开很久了。牛头人的生活建立在共同责任和相互照料之上。鹰风酋长虽然担心母亲的安危，但酋长的职责使他必须留守营地。",al={"鹰风酋长为什么要你做这件事","鹰风酋长的意图","为什么去看看鹰风酋长的母亲"}}},fp="13,384,25.486.0,29.432.0,47.166.0,38.125.0,55.242.0,46.215.0,64.231.0,48.151.0"}
P.entries["quest:753"] = {n="一件琐事",s="“卑微的任务”是红云台地的一项入门服务仪式，长者会在此考验初出茅庐的冒险者的谦逊与勤勉。通过将新鲜的井水跨越平原送到纳拉其营地的首领手中，年轻的牛头人将明白，为族人服务始于最简单的职责。",h="“卑微的任务”是红云台地的一项入门服务仪式，长者会在此考验初出茅庐的冒险者的谦逊与勤勉。通过将新鲜的井水跨越平原送到纳拉其营地的首领手中，年轻的牛头人将明白，为族人服务始于最简单的职责。",kw={"纳拉其营地","鹰风酋长","鹰风酋长的母亲","卑微的任务","莫高雷","红云台地","大地之母仪式","水罐"},ang={["faction:Horde"]="鹰风家族的教导说明了牛头人是如何在莫高雷维持团结与生存的，这构成了萨尔领导的部落中和平而坚定的基石。",["race:Tauren"]="为长者取水体现了牛头人社区关怀的基本美德，表明你已准备好走上大地之母的道路。"},sec={{t="年轻人的活力",b="鹰风酋长的母亲在她漫长的一生中走过许多道路，虽然她的精神依然坚定，但她的双腿已不再能像年轻时那样迅速地跨越平原。她驻守在红云台地南缘的水井旁，以耐心的决心履行着自己的职责。当有抱负的部落保卫者经过她身边时，她会将他们年轻的精力引导至实际的社区需求上，让他们有机会通过服务而非暴力来证明自己的价值。"},{t="为部落服务",b="这项任务要求初学者将一罐装满的水挑回西北方的纳拉其营地，并直接交给该定居点的首领——鹰风酋长，他恰好就是鹰风酋长的母亲的儿子。在牛头人社会中，要在莫高雷干旱的平原上生存，需要共同劳动和可靠的淡水供应。通过承担长者的负担来表现对社区长者的尊重，被认为是成为部落真正保护者的基石。"},{t="通往雷霆崖的道路",b="当年轻的旅者带着他母亲送来的水到达时，鹰风酋长看到的不仅仅是一件琐事的完成。在牛头人的习俗中，一个人准备好在更广阔的土地上捍卫族人，始于谦逊和自愿提供帮助的意愿。通过展现这种安静的纪律，初学者引起了酋长的注意，并获得了参加古老的“大地之母仪式”的推荐，这是通往雷霆崖的真正精神考验。"}},faq={{q="鹰风酋长的母亲是谁？",a="鹰风酋长的母亲是鹰风家族的一位长者，驻扎在红云台地的水井旁。她是纳拉其营地首领鹰风酋长的母亲，并引导年轻的牛头人学习谦逊和部落价值观。",al={"鹰风酋长的母亲","谁发布卑微的任务","鹰风长者"}},{q="水井在哪里？",a="水井位于纳拉其营地的东南方，坐落在红云台地的草地平原上。井边放着装满新鲜井水的“水罐”，供旅行者和营地管理员取回使用。",al={"水井位置","水井在哪里","寻找水罐"}},{q="鹰风酋长是谁？",a="鹰风酋长是负责监督红云台地纳拉其营地的酋长。他指导年轻牛头人的训练和精神仪式，为他们前往莫高雷更广阔的地区为部落服务做好准备。",al={"鹰风酋长","酋长是谁","纳拉其营地首领"}},{q="为什么这种琐事被视为一项重要的考验？",a="牛头人文化非常重视谦逊、社区支持和对长者的尊重。完成这些平淡无奇的日常职责表明，冒险者关心的是如何维持族人的生存，而不仅仅是在战斗中寻求个人的荣耀。",al={"为什么要背水","为什么是卑微的任务","这个任务重要吗"}},{q="完成“卑微的任务”后要做什么？",a="完成这项任务证明了你的纪律性，鹰风酋长随后会指引你参加“大地之母仪式”——这是所有成年牛头人必须经历的一系列传统挑战。",al={"what comes next","后续任务","卑微的任务之后"}},{q="这条道路最终通向哪里？",a="赢得纳拉其营地长者的尊重，将为你离开僻静的台地，踏入莫高雷更广阔的平原，并最终前往首都雷霆崖的高台地做好准备。",al={"未来目的地","我们要去哪里","雷霆崖目标"}}},fp="13,183,21.360.0,20.336.0,27.375.0,28.184.0,32.172.0,22.165.0,47.158.0,42.134.0,37.130.0"}
P.entries["quest:754"] = {n="净化冰蹄之井",s="“冰蹄净化”是血蹄村的穆尔·雷角委托给部落冒险者的一项仪式。在荆棘谷地精的非法作业污染了当地水源后，冒险者必须将一枚神圣的图腾带入荆棘谷地精的领地，以净化冰蹄水井。修复这处泉水是治愈莫高雷中部受污染水域至关重要的第一步。",h="“冰蹄净化”是血蹄村的穆尔·雷角委托给部落冒险者的一项仪式。在荆棘谷地精的非法作业污染了当地水源后，冒险者必须将一枚神圣的图腾带入荆棘谷地精的领地，以净化冰蹄水井。修复这处泉水是治愈莫高雷中部受污染水域至关重要的第一步。",kw={"血蹄村","净化","莫高雷","穆尔·雷角","毒","图腾","荆棘谷地精","水井","冰蹄"},ang={["class:Druid"]="看到口渴的野生动物立即回到净化后的泉水边，证明了在文明威胁要破坏自然的地方治愈自然是多么必要。",["class:Shaman"]="通过图腾引导灵魂来扭转不自然的工业污染，代表了萨满祭司与元素之水结合的核心目的。",["faction:Horde"]="保障莫高雷的淡水供应稳定了新定居的牛头人的心脏地带，加强了年轻部落的南方支柱。",["race:Tauren"]="莫高雷的水井是大地母亲赠予的生命之源；保卫它们免受地精贪婪的侵蚀，对每一位牛头人来说既是公民职责，也是神圣的义务。"},sec={{t="被蹂躏的土地",b="莫高雷的草原依赖于一个精巧的祖传水井网络来维持野生动物和星罗棋布的牛头人部族的生活。最近，荆棘谷地精那些冷酷无情的工业雇佣兵迁入了血蹄村东南方向的连绵丘陵。他们的作业已经污染了当地的蓄水层，导致冰蹄水井变得又脏又有毒。野生野兽避开受污染的水源，如果腐蚀进一步蔓延到大地，附近的营地将面临迫在眉睫的危机。"},{t="净化水源的仪式",b="为了对抗这些工业污垢，穆尔·雷角雕刻并附魔了一枚注入了大地母亲祝福的仪式净化图腾。然而，交付这个补救措施需要冒险者勇敢面对那些已经强占了泉水的全副武装的荆棘谷地精打手。通过将图腾直接放置在井口，冒险者可以驱散污浊的径流，让干净、充满生命力的水再次从大地深处涌出。"}},faq={{q="冰蹄水井在哪里？",a="冰蹄水井位于莫高雷血蹄村东南方向的丘陵地带。那里有荆棘谷地精的工人和雇佣兵在严密巡逻。",al={"冰蹄水井位置","冰蹄水井在哪","如何找到冰蹄水井"}},{q="为什么水井会被投毒？",a="荆棘谷地精在附近建立了采矿和挖掘作业点，导致有毒的工业径流和垃圾直接渗入蓄水层，使得当地野生动物和牛头人无法饮用这些天然泉水。",al={"谁污染了水源","为什么水井变脏了","荆棘谷地精水井"}},{q="穆尔·雷角是谁？",a="穆尔·雷角是一位驻扎在血蹄村的精神长老。他与大地的健康息息相关，通过制作仪式图腾来消除外来入侵者造成的环境破坏。",al={"穆尔是谁","穆尔·雷角的职责"}},{q="水井净化后会发生什么？",a="一旦冰蹄水井变得清澈，野生动物开始再次安全饮水，穆尔·雷角会引导你关注莫高雷的其他受损水井，首先就是雷角图腾。",al={"what comes next","冰蹄净化之后","穆尔下一步做什么"}},{q="水井处的守卫是谁？",a="水井被荆棘谷地精雇佣的工人和帮工占据，这是一个冷酷无情的地精领导的辛迪加组织，为了榨取自然资源而不顾当地生态系统。",al={"谁守卫着冰蹄水井","水井处有什么敌人"}},{q="净化图腾是如何运作的？",a="图腾上刻有神圣的牛头人礼仪和防御仪式，它汲取自然之灵和大地母亲的祝福，以净化泉水源头中不自然的化学污染物。",al={"净化图腾传说","穆尔图腾如何运作"}}},fx={["16ee77f0"]={q="穆尔·雷角为什么想净化冰蹄水井？",a="冰蹄水井对莫高雷的平衡与生存至关重要。井水遭到污染，威胁着当地野生生物以及依赖它的部族。穆尔·雷角已备好一根祝圣净化图腾，但必须将它带到水井所在之处，才能净化水源、恢复土地的和谐。",al={"为什么要净化冰蹄水井","穆尔·雷角的意图","为什么净化冰蹄水源"}}},fp="20,358,16.505.0,30.432.0,43.191.0,32.227.0,24.205.0,40.212.1,31.195.0,34.192.0"}
P.entries["quest:7541"] = {n="为部落效力",s="镶满珠宝的吊坠现在交给了奥格瑞玛的佐尔·孤树，这是在完成“向佐尔报告”后交付的。佐尔还有话要对你说。",h="镶满珠宝的吊坠现在交给了奥格瑞玛的佐尔·孤树，这是在完成“向佐尔报告”后交付的。佐尔还有话要对你说。",kw={"尘泥沼泽","吊坠","向佐尔报告","服务部落","佐尔·孤树"},sec={{t="奥格瑞玛的佐尔·孤树",b="你将镶满珠宝的吊坠送到了奥格瑞玛的佐尔·孤树手中，吊坠现在由佐尔保管。回到佐尔·孤树那里，听听关于你为部落所做贡献的更多评价。"},{t="佐尔的临别之言",b="佐尔说学者们需要时间来研究这枚吊坠。作为你服务部落的奖赏，佐尔提供了一点小小的谢礼，并表示你所做的一切为你自己和部落都带来了荣誉。"}},faq={{q="现在谁拿着吊坠？",a="奥格瑞玛的佐尔·孤树，在你将它从蕨墙村的纳泽尔·血矛那里送来之后。",al={"谁接收吊坠","谁给予此任务","佐尔·孤树的角色"}},{q="在此任务之前是什么任务？",a="它紧接在“向佐尔报告”之后，你当时带着镶满珠宝的吊坠去见了佐尔·孤树。",al={"之前的任务是什么","服务部落的前置条件","上一个任务"}}},fp="20,126,25.185.0,15.186.1,24.99.0,29.77.0"}
P.entries["quest:755"] = {n="大地之母仪祭",s="“大地母亲的仪式”标志着一位新人在红云台地的精神旅程的开始。在鹰风酋长的指引下，旅者们会前往纳拉其营地南部的山丘寻找灰舌先知。承担这些古老的仪式被视为牛头人成年过程中至关重要的试炼。",h="“大地母亲的仪式”标志着一位新人在红云台地的精神旅程的开始。在鹰风酋长的指引下，旅者们会前往纳拉其营地南部的山丘寻找灰舌先知。承担这些古老的仪式被视为牛头人成年过程中至关重要的试炼。",kw={"纳拉其营地","鹰风酋长","大地母亲","红云台地","大地母亲的仪式","灰舌先知","牛头人"},ang={["class:Druid"]="德鲁伊候选人通过尊重部落长者和先知的神圣指引，开启他们与自然和谐相处的道路。",["class:Shaman"]="对于有抱负的萨满祭司而言，进行由部落先知祝福的仪式是通往与元素以及莫高雷之灵沟通的重要第一步。",["faction:Horde"]="了解这些神圣的试炼可以让人深入洞察这些近期加入部落的牛头盟友的精神核心。",["race:Tauren"]="“大地母亲的仪式”代表了年轻牛头人基础性的精神旅程，考验着他们为部落服务并崇敬大地母亲的决心。"},sec={{t="试炼的开端",b="在红云台地上，鹰风酋长指引着那些渴望证明自己的年轻牛头人去寻找灰舌先知。灰舌先知居住在纳拉其营地正南方宁静的山丘中，负责监督年轻人的精神启蒙。这段简单的旅程标志着日常营地生活与部落习俗所要求的庄严承诺之间的正式门槛。"},{t="拥抱大地母亲",b="大地母亲是牛头人创世信仰和日常生活中的核心。她的仪式是关于成熟、坚韧和精神深度的神圣试炼。正如灰舌先知告诫每一位来到他居所的人那样，开启“大地母亲的仪式”绝非易事，它需要对台地的传统保持全心全意的奉献。"}},faq={{q="谁发布了“大地母亲的仪式”这个任务？",a="该任务由纳拉其营地的鹰风酋长发起，他会指引年轻的冒险者去寻找周围山丘中的灰舌先知。",al={"谁开启大地母亲的仪式","任务发布者"}},{q="我在哪里可以找到灰舌先知？",a="灰舌先知居住在位于莫高雷红云台地中，纳拉其营地正南方的山丘里。",al={"灰舌先知在哪里","灰舌位置","寻找灰舌"}},{q="什么是“大地母亲的仪式”？",a="“大地母亲的仪式”是牛头人青年为了证明他们对自己的人民和信仰的智慧、力量与奉献而进行的一项传统神圣试炼。",al={"什么是大地母亲的仪式","大地母亲试炼背景"}},{q="灰舌先知是谁？",a="灰舌先知是一位受人尊敬的精神长者，居住在纳拉其营地以南，负责监督并指引新人完成大地母亲的神圣试炼。",al={"灰舌先知是谁","灰舌职责"}},{q="鹰风酋长是谁？",a="鹰风酋长是掌管红云台地上纳拉其营地的部落领袖，他的职责是在将年轻的牛头人送往先知那里之前对其进行准备。",al={"鹰风酋长是谁","鹰风职责"}},{q="完成这项任务需要做什么？",a="你只需要从纳拉其营地向南前往山丘，与灰舌先知交谈，表明你已为试炼做好了准备。",al={"我需要做什么","如何完成任务"}}},fp="24,304,27.356.0,25.352.0,45.141.0,33.108.0,38.172.0,23.157.0,22.155.0,39.135.0"}
P.entries["quest:756"] = {n="雷角图腾",s="“雷角图腾”是血蹄村的穆尔·雷角发布的一项任务，旨在制作一个神圣的净化图腾。为了对抗正在污染莫高雷水井的荆棘谷地精，年轻的部落勇士必须从平原捕食者身上收集自然的爪子，将这片土地原始的力量束缚在仪式木桩之中。",h="“雷角图腾”是血蹄村的穆尔·雷角发布的一项任务，旨在制作一个神圣的净化图腾。为了对抗正在污染莫高雷水井的荆棘谷地精，年轻的部落勇士必须从平原捕食者身上收集自然的爪子，将这片土地原始的力量束缚在仪式木桩之中。",kw={"血蹄村","净化","平原狮的爪子","平原狮","莫高雷","穆尔·雷角","草原捕食者","草原捕食者的爪子","雷角图腾","水井"},ang={["class:Hunter"]="收集爪子需要了解平原上的原生捕猎野兽，并尊重杀戮以保护生态系统。",["class:Shaman"]="图腾的修复依赖于召唤大地的生命之灵，以净化因不自然、粗心的企业行为而受到腐蚀的水源。",["race:Tauren"]="保卫莫高雷的含水层免受外来者的剥削是神圣的部落职责，这反映了大地母亲关于平衡共存而非掠夺的训导。"},sec={{t="狩猎平原捕食者",b="随着荆棘谷地精的工业开采污染了莫高雷珍贵的水源，穆尔·雷角正急于寻找补救措施。制作雷角之井净化图腾需要平原上最专注的猎手——草原捕食者和平原狮——身上的自然精粹。通过获取这些在血蹄村东西方游荡的捕食者的爪子，仪式能够将野生动物原始且未被腐蚀的捕猎活力直接注入图腾之中。"},{t="狩猎的本质",b="牛头人的传统认为，为了维持生计或精神平衡而进行的狩猎，与地精所实行的掠夺性开采之间有着深刻的区别。穆尔强调，本土捕食者狩猎时所具备的纯粹性，对于净化被腐蚀的土地至关重要。地精的机器用石油和工业废料玷污了泉水，而这些与土地抗争的野兽所拥有的自然力量，正提供了恢复雷角水井所需的精神催化剂。"}},faq={{q="穆尔·雷角为什么需要捕食者的爪子？",a="穆尔使用草原捕食者和平原狮的爪子，将平原纯净、原始的捕猎精神灌注到净化图腾中。他相信自然猎手的纯净精神能够抵消人为的工业腐蚀。",al={"为什么需要爪子","草原捕食者爪子的用途","平原狮爪子的目的"}},{q="是谁在腐蚀莫高雷的水源？",a="在莫高雷活动的荆棘谷地精正在污染这片土地和水源。他们肆无忌惮的资源开采和采矿钻机将有毒淤泥排入了滋养部落水井的含水层中。",al={"谁污染了水井","为什么水井被下毒","什么东西毒害了莫高雷"}},{q="在哪里可以找到草原捕食者和平原狮？",a="这两种野兽都栖息在莫高雷中部的开阔平原上，主要分布在血蹄村东部和西部的连绵稀树草原中。",al={"草原捕食者位置","去哪里找平原狮","平原狮爪子掉落位置"}},{q="制作雷角图腾后会发生什么？",a="当穆尔用这些爪子雕刻并附魔图腾后，他会直接派遣你去受污染的雷角水井执行净化仪式，驱散其中的毒素。",al={"接下来做什么","雷角图腾之后","图腾任务后续"}},{q="这与之前冰蹄水井的净化有什么联系？",a="这是部落为保护莫高雷神圣水源而进行的持续努力的一部分。冰蹄水井首先得到了净化，而现在污染正威胁着北部的雷角水井。",al={"冰蹄水井的关联","上一个图腾任务"}},{q="为什么牛头人不使用草药疗法，而要使用动物爪子？",a="牛头人的仪式工艺汲取了自然界中独特的元素和物理特性。顶级捕食者那种尖锐的纯净感，提供了一种特定的、充满活力的精神力量，这是切断地精工业毒素侵蚀所必需的。",al={"为什么不用草药","萨满图腾材料"}}},fp="17,247,28.401.0,22.368.0,46.217.0,39.187.0,58.149.0,50.165.1,66.173.0,72.213.0"}
P.entries["quest:757"] = {n="力量仪祭",s="力量试炼是牛头人年轻人必须在纳拉其营地进行的传统大地之母试炼中的首项考验。为了证明自己的勇气并保卫部族，试炼者必须在刺刃峡谷清除那些不断入侵的鬃毛野猪人，并将它们的腰带呈交给鹰风酋长。",h="力量试炼是牛头人年轻人必须在纳拉其营地进行的传统大地之母试炼中的首项考验。为了证明自己的勇气并保卫部族，试炼者必须在刺刃峡谷清除那些不断入侵的鬃毛野猪人，并将它们的腰带呈交给鹰风酋长。",kw={"刺刃峡谷","鬃毛野猪人","纳拉其营地","鹰风酋长","大地之母","莫高雷","野猪人","力量试炼","灰舌先知"},ang={["faction:Horde"]="保卫台地可以确保部落的一个核心征兵基地安全，确保年轻的战士和萨满能够安全成长，为新联盟提供助力。",["race:Tauren"]="每一位牛头人年轻人都从这些古老的试炼开始他们的旅程，在离开红云台地之前，证明自己已做好准备去保护族人免受野猪人的威胁。"},sec={{t="第一项试炼",b="对于寻求部族长者认可并最终被雷霆崖接纳的牛头人年轻人来说，完成大地之母试炼是一项基本义务。由灰舌先知传授的力量试炼是这一系列试炼的起点。它要求试炼者展现出身体上的勇气，并能在保卫红云台地的战斗中果断出击，从而考验试炼者能否直面部族的致命敌人而毫无退缩。"},{t="鬃毛野猪人的威胁",b="这项试炼的选定地点是刺刃峡谷，这是一道位于纳拉其营地东侧、荆棘丛生的裂谷，被鬃毛野猪人所占据。这些极具侵略性的闯入者不断践踏部族的祖居之地，伏击狩猎队，并趁着夜色劫掠营地的补给。猎杀它们并收集其腰带，既是勇气的证明，也是保障营地安全的必要措施。"}},faq={{q="力量试炼的目的是什么？",a="这是大地之母试炼的奠基之步，旨在考验牛头人年轻人战斗中的勇气。通过清除对营地的敌对威胁，试炼者有权继续前行，向雷霆崖争取真正的尊重。",al={"为什么要进行力量试炼","力量试炼背景","力量试炼的目的"}},{q="谁负责指派并评判这项试炼？",a="灰舌先知负责向试炼者下达任务，概述试炼的精神与实践要求。当收集到十二条鬃毛野猪人腰带后，这份勇气证明必须直接呈交给纳拉其营地的鹰风酋长。",al={"谁发布力量试炼","谁负责交付力量试炼"}},{q="刺刃峡谷位于何处？",a="刺刃峡谷位于纳拉其营地正东方的红云台地上。那是一条荆棘密布的峡谷，四处潜伏着敌对的鬃毛野猪人。",al={"刺刃峡谷在哪里","刺刃峡谷位置"}},{q="为什么要针对鬃毛野猪人？",a="鬃毛野猪人正在侵占部族的祖传狩猎场。它们多次伏击牛头人猎人，并在夜间从纳拉其营地盗取补给，是部族直接的敌人。",al={"为什么要猎杀鬃毛野猪人","野猪人做了什么"}},{q="为什么要收集腰带而不是其他战利品？",a="腰带是被击败战士的实物凭证，证明试炼者在近距离与野猪人交锋，并击败了成年战士，而不是仅仅从远处进行拾荒。",al={"为什么要收集鬃毛野猪人腰带","为什么要腰带"}},{q="完成力量试炼后要做什么？",a="通过力量试炼证明了自身的勇气，使试炼者有资格进行后续的大地之母试炼，从而继续正式的成年之路，并提升在部族中的精神地位。",al={"力量试炼之后做什么","下一项大地之母试炼"}}},fp="16,171,15.318.0,22.308.0,44.215.0,34.166.0,37.123.0,40.180.0,44.146.0,49.206.0"}
P.entries["quest:758"] = {n="净化雷角之井",s="“雷角之井净化”是莫高雷一项至关重要的精神仪式，旨在委托旅行者净化遭受腐蚀的雷角水井。借助穆尔·雷角准备的仪式图腾，探险者们能够修复对当地部落至关重要的受污染泉水。净化成功将赢得雷角氏族祖先发自内心的赞许。",h="“雷角之井净化”是莫高雷一项至关重要的精神仪式，旨在委托旅行者净化遭受腐蚀的雷角水井。借助穆尔·雷角准备的仪式图腾，探险者们能够修复对当地部落至关重要的受污染泉水。净化成功将赢得雷角氏族祖先发自内心的赞许。",kw={"祖先之灵","血蹄村","净化图腾","大地母亲","莫高雷","穆尔·雷角","雷角之井净化","雷角水井"},ang={["class:Druid"]="净化受毒的水源可以阻止腐蚀在莫高雷生态系统中的蔓延，从而保护平原的自然和谐。",["class:Shaman"]="通过图腾引导祖先能量来治愈受腐蚀的天然泉水，这正是萨满教义的基础。",["faction:Horde"]="协助牛头人保护他们神圣的泉水，加强了年轻的部落与其骄傲的舒哈鲁盟友之间的纽带。",["race:Tauren"]="修复神圣的泉水是对大地母亲的敬奉，也能在你的族人于莫高雷开辟永久而宁静的家园时保护他们。"},sec={{t="受到污染的生命线",b="莫高雷广袤平原上的水井，是近期在此定居的牛头人游牧部落不可或缺的生命线。当邪恶的毒素污染了这些地下泉水，野生动物和附近的定居点都将面临灾难性的后果。位于血蹄村北部的雷角水井不幸遭到了污染，需要进行慎重的精神干预来治愈这片受困的土地。"},{t="祖先的净化",b="为了抵御腐蚀，穆尔·雷角制作了一根蕴含精神力量的神圣净化图腾。将这件圣物直接带到受污染的水源处，探险者们便能将祖先的力量注入泉水中，驱散毒素并恢复原始的自然平衡。当雷角氏族的祖先之灵在梦中拜访穆尔并表达他们永恒的感激时，穆尔便能直接确认此项善举的成功。"}},faq={{q="雷角水井位于何处？",a="雷角水井位于莫高雷血蹄村北部的平原上。它是为当地牛头人部族提供水源的几处重要水潭之一。",al={"雷角水井位置","水井在哪里","在哪里使用图腾"}},{q="谁发起了这项净化仪式？",a="穆尔·雷角发起了这项仪式。你可以在血蹄村找到他，他正在那里制作专门的图腾，以治愈莫高雷受损的环境。",al={"谁提供任务","穆尔·雷角位置","任务发布者"}},{q="为什么要净化莫高雷的水井？",a="莫高雷各地的水井都遭受了非自然的毒害和腐蚀，这威胁到了平原脆弱的平衡以及依赖净水生存的牛头人部落。",al={"为什么要净化水井","水怎么了","为什么水井被污染"}},{q="穆尔是如何得知仪式成功的？",a="在完成水井的仪式后，雷角氏族的祖先之灵会直接在梦中显现给穆尔，赞扬探险者的事迹并致以祖先的谢意。",al={"祖先梦境","穆尔如何得知","净化水井的结果"}},{q="净化雷角水井之后要做什么？",a="净化雷角水井是保护莫高雷泉水更广泛工作的一部分。接下来，穆尔会派遣旅行者前往另一个受困地区，通过制作狂鬃图腾来提供援助。",al={"接下来做什么","雷角之后的任务","狂鬃图腾后续"}},{q="什么是雷角之井净化图腾？",a="雷角之井净化图腾是由穆尔·雷角专门制作的一种经过仪式雕刻的精神焦点，旨在净化他所在部族祖传水井中受污染的水。",al={"净化图腾","什么是图腾物品","穆尔的图腾"}}},fx={da3030fe={q="穆尔·雷角为什么需要你净化水井？",a="穆尔·雷角已经制作好了仪式法器，但净化圣地是牛头人及其盟友的新晋勇士必须履行的服务与荣誉仪式。你亲自将雷角之井净化图腾带到受污染的水井，就能证明自己对大地母亲和他氏族祖灵的虔诚，并赢得守护水源的祖灵的恩宠与指引。",al={"穆尔·雷角为什么找我","穆尔为什么派你去","为什么要举行净化仪式"}}},fp="21,345,18.422.0,19.447.0,44.167.0,36.161.0,48.196.0,45.184.0,51.191.0,40.180.0"}
P.entries["quest:759"] = {n="蛮鬃图腾",s="野鬃图腾代表了穆尔·雷角为净化莫高雷被污染的水井而制作的净化图腾的第三个也是最后一个阶段。为了恢复野鬃之井，仪式需要从该地区最凶猛的天然捕食者——草原狼首领——身上获取祭品。",h="野鬃图腾代表了穆尔·雷角为净化莫高雷被污染的水井而制作的净化图腾的第三个也是最后一个阶段。为了恢复野鬃之井，仪式需要从该地区最凶猛的天然捕食者——草原狼首领——身上获取祭品。",kw={"血蹄村","莫高雷","穆尔·雷角","草原狼首领","雷霆崖","图腾","水井","野鬃"},ang={["class:Hunter"]="在高耸的悬崖周围追踪狡猾的首领狼，考验着猎人对荒野及其最敏锐捕食者的尊重。",["class:Shaman"]="萨满祭司们能够领会其中的微妙仪式，即通过调和捕食者图腾与元素之水，来清除毒害。",["race:Tauren"]="净化祖先水井强调了牛头人修复环境失衡并敬重大地母亲所要求的牺牲的义务。"},sec={{t="最后一座水井",b="在收集到制作冬蹄之井和雷角之井净化图腾所需的材料后，莫高雷中部只剩下一处受污染的水源：野鬃之井。平原上被毒化的水源正威胁着迁徙的野生动物和定居点，需要强大的原始素材来恢复大地的自然平衡。"},{t="捕食者的力量",b="为了对抗北方水域中挥之不去的强烈腐蚀，穆尔·雷角需要一份凶猛的祭品。草原狼首领潜伏在草原上，尤其是在雷霆崖下方高耸的悬崖周围。收集它们的牙齿，可以将莫高雷顶级猎手的无情动力和韧性直接注入到净化图腾的制作中。"},{t="牺牲与平衡",b="在牛头人的精神传统中，利用土地上的生物带有情感和元素上的重量。穆尔认为收集首领牙齿并非征服，而是一种沉重的必要之举，通过牺牲莫高雷的捕食者来帮助治愈大地母亲遭受重创的水域。"}},faq={{q="野鬃图腾有什么用？",a="该图腾由穆尔·雷角制作，用于净化野鬃之井，这是威胁到莫高雷牛头人的最后一处被污染的水源。",al={"为什么制作野鬃图腾","野鬃图腾的作用"}},{q="为什么特别需要草原狼首领的牙齿？",a="净化野鬃之井深层的污染需要引导顶级捕食者凶猛而坚韧的力量。狼群首领的牙齿提供了必要的原始力量。",al={"为什么需要狼牙","草原狼首领牙齿的用途"}},{q="在莫高雷哪里可以找到草原狼首领？",a="草原狼首领徘徊在莫高雷的北部平原，通常出没在雷霆崖基座周围的草原上。",al={"草原狼首领位置","去哪里找草原狼首领"}},{q="谁制作了图腾？",a="穆尔·雷角，驻守在血蹄村的一位精神长老，在试炼者收集到必要的祭品后会制作每一个净化图腾。",al={"谁制作图腾","图腾任务发布者"}},{q="制作完野鬃图腾后要做什么？",a="当穆尔·雷角用首领牙齿组装好图腾后，你将被派往北方，在野鬃之井进行实际的净化仪式。",al={"what comes next","野鬃图腾后续任务"}},{q="这种仪式如何体现牛头人的信仰？",a="牛头人将夺取动物的生命视为与自然之间庄严的交换。穆尔承认狼群的牺牲，既为它们的死亡感到悲伤，也为它们在治愈大地中所扮演的角色感到自豪。",al={"牛头人图腾哲学","穆尔·雷角的信仰"}}},fx={["054e923c"]={q="穆尔·雷角为什么想制作蛮鬃图腾？",a="莫高雷只剩下一口遭到污染的水井尚未净化——那就是蛮鬃氏族的水井。穆尔·雷角立志净化大地母亲的圣泉，而借助这片土地上掠食者的灵性制作最后一根净化图腾，是完成神圣仪式、为部族恢复纯净水源的关键。",al={"穆尔·雷角为什么要蛮鬃图腾","穆尔·雷角的意图","为什么制作蛮鬃图腾"}},["2aa23a29"]={q="草原狼前锋的牙齿有什么用？",a="草原狼首领的牙齿象征着莫高雷顶级掠食者的牺牲与凶猛活力。穆尔·雷角会将八颗獠牙嵌入蛮鬃图腾，使其中的灵性能安抚自然秩序，并赋予仪式所需的力量，以清除蛮鬃水井中的污秽。",al={"草原狼前锋的牙齿用途","草原狼前锋的牙齿有什么用","蛮鬃图腾所需的牙齿"}},eb5f4bd0={q="为什么要猎杀草原狼前锋？",a="你要猎杀草原狼前锋——它们是盘踞在雷霆崖山脚附近平原上的狼群首领。它们的力量与凶猛体现了平原的自然平衡，也能为穆尔·雷角最终的净水仪式提供所需的强大精华。",al={"为什么杀草原狼前锋","草原狼前锋目标","你要追捕谁"}}},fp="14,272,14.339.0,23.367.0,21.277.0,38.141.0,55.192.0,47.130.0,21.146.0,48.147.0,44.199.0"}
P.entries["quest:76"] = {n="玉石矿洞",s="在发现狗头人已经占领了法戈第矿洞后，治安官杜汉派遣侦察兵去调查更东边的玉石矿洞。到达目的地后情况得到了证实，最糟糕的预感应验了：这种入侵已经蔓延到了艾尔文森林重要的矿脉上，这让暴风城剩余的守军疲于奔命，达到了极限。",h="在发现狗头人已经占领了法戈第矿洞后，治安官杜汉派遣侦察兵去调查更东边的玉石矿洞。到达目的地后情况得到了证实，最糟糕的预感应验了：这种入侵已经蔓延到了艾尔文森林重要的矿脉上，这让暴风城剩余的守军疲于奔命，达到了极限。",kw={"阿祖拉","杜汉","艾尔文","法戈第","闪金镇","玉石矿洞","狗头人","矿洞","侦察"},ang={["faction:Alliance"]="法戈第和玉石矿洞的同时失守，暴露了在缺乏中央王权支持的情况下，暴风城的腹地是多么脆弱。",["profession:Mining"]="对于矿工来说，看到富饶的地下矿脉被害虫占领是令人苦涩的景象。玉石矿洞的隧道里蕴藏着宝贵的矿藏，但要开采它们，必须通过重重驻扎的狗头人的包围。",["race:Human"]="人类侦察兵亲眼见证了艾尔文森林农村基础设施的逐渐崩溃，边境资源就在首都的家门口不断陷落。"},sec={{t="第二次入侵",b="在确认了狗头人已经侵占了闪金镇南部的法戈第矿洞隧道后，治安官杜汉担心这并非个例。坐落在阿祖拉之塔东北方岩石丘陵中的玉石矿洞，是王国获取矿石与金属的另一个重要来源。由于无法抽调暴风城卫兵离开城镇去巡逻，杜汉不得不依靠独立冒险者向东深入，去确认这个地方是否也沦陷给了那些顶着蜡烛的地下害虫。"},{t="过度扩张的防御",b="深入调查玉石矿洞的内部发现，狗头人已经完全取代了人类矿工，它们在黑暗的通道中挖掘并修建了防御工事。对治安官杜汉来说，这份严峻的报告无异于在日益严重的危机中雪上加霜。由于瓦里安·乌瑞恩国王失踪，且皇家军队被限制在边境领土之外，当地驻军缺乏足够的人手来清理矿洞，导致王国的核心地带在经济上陷入匮乏，在地理上也陷入了困境。"}},faq={{q="玉石矿洞在哪里？",a="矿洞位于艾尔文森林东部的北部丘陵中。前往此处，需沿着闪金镇的主路向东走，到达阿祖拉之塔，然后向北进入丘陵即可。",al={"玉石矿洞在哪里","玉石矿洞位置","如何找到玉石矿洞"}},{q="为什么治安官杜汉需要侦察兵而不是派遣卫兵？",a="由于首都的政治僵局以及瓦里安·乌瑞恩国王的失踪，艾尔文森林的暴风城卫兵严重人手不足。由于当地部队兵力薄弱，又要保护农场和城镇免受强盗和豺狼人的侵害，治安官杜汉必须依赖民间的侦察兵。",al={"为什么要派遣冒险者","为什么没有暴风城卫兵","卫兵在哪里"}},{q="为什么狗头人要占领艾尔文森林的矿洞？",a="狗头人是天生的掘地者，被地下的矿脉和潮湿的洞穴所吸引。随着暴风城军事力量的削弱，这些生物变得更加大胆，大肆侵入像法戈第和玉石矿洞这样的人类矿场，以掠夺黄金、矿石和领地。",al={"为什么狗头人在玉石矿洞","狗头人想要什么","狗头人入侵原因"}},{q="侦察玉石矿洞之后会发生什么？",a="一旦你向治安官杜汉报告了玉石矿洞的沦陷，他会承认艾尔文森林正面临多线受敌的残酷现实。在确认东部矿洞失守后，他的注意力转移到了西艾尔文森林，那里的西泉要塞正面临河爪豺狼人的沉重压力。",al={"玉石矿洞之后做什么","玉石矿洞后续"}},{q="为什么玉石矿洞的丢失对暴风城意义重大？",a="艾尔文森林的矿洞提供了维持暴风城经济以及铸造武器和盔甲所需的原料矿石与石料。法戈第和玉石矿洞的双双丢失中断了矿产开采，严重损害了王国的恢复努力。",al={"为什么玉石矿洞很重要","玉石矿洞重要性"}},{q="附近的阿祖拉之塔是谁的？",a="阿祖拉之塔是一座位于艾尔文森林东部大路旁的小型法师塔，由阿祖拉大法师塞欧克瑞图斯主持，并由阿祖拉的仆从们运营。它是前往东部丘陵的旅人们的标志性地标。",al={"什么是阿祖拉之塔","谁住在阿祖拉之塔"}}},fp="19,132,18.387.0,21.391.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="净化蛮鬃之井",s="蛮鬃之井净化是牛头人净化莫高雷重要水源的仪式努力的最高潮。在血蹄村接受穆尔·雷角的委托后，英雄们带着制作完成的蛮鬃图腾向北前往，去净化最后一座被污染的水井。击退荆棘谷地精的污染不仅恢复了平原的平衡，也保障了牛头人部落的田园生活。",h="蛮鬃之井净化是牛头人净化莫高雷重要水源的仪式努力的最高潮。在血蹄村接受穆尔·雷角的委托后，英雄们带着制作完成的蛮鬃图腾向北前往，去净化最后一座被污染的水井。击退荆棘谷地精的污染不仅恢复了平原的平衡，也保障了牛头人部落的田...",kw={"血蹄村","净化","大地母亲","莫高雷","穆尔·雷角","图腾","荆棘谷地精","水井","蛮鬃"},ang={["class:Druid"]="扭转地精对环境的破坏，直接体现了塞纳里奥议会治愈受损生态系统、保护青翠牧场的使命。",["class:Shaman"]="利用仪式图腾来消除机械污染，体现了萨满维护自然元素与生命群落之间和谐的职责。",["race:Tauren"]="修复莫高雷的三口祖传水井是一项基础的成人礼，证明了一位年轻勇士对保护大地母亲恩赐的虔诚。"},sec={{t="净化大地母亲的恩赐",b="在阳光普照的莫高雷平原上，水是神圣的生命之源，滋养着兽群、土地以及最近聚集在雷霆崖周围的游牧部落。当荆棘谷地精和入侵的地精开始用有毒的工业废料污染这些蓄水层时，牛头人长老们意识到了生存的威胁。在净化了冰蹄水井和雷角水井之后，蛮鬃水井成了第三个、也是最后一个需要进行精神干预的受污染地点。"},{t="蛮鬃图腾",b="蛮鬃之井净化图腾由在该地区收集的特定元素制成，它引导着祖先之魂和大地元素的力量进行修复。将图腾插在雷霆崖以北污浊的水边，可以驱散有害的化学物质，吸出毒素并恢复自然流动。通过完成这一仪式，牛头人保护了族人免受疾病侵害，并传达了一个明确的信息：绝不容忍对他们圣地的亵渎。"}},faq={{q="蛮鬃水井为什么会被污染？",a="在工业贪婪和伐木事业的驱使下，地精的行动将恶毒的毒药和化学废料引入了莫高雷的地下水，威胁到了当地的野生动物和部落定居点。",al={"谁污染了水井","水井为何肮脏","地精毒素"}},{q="蛮鬃水井位于哪里？",a="蛮鬃水井位于雷霆崖高耸平顶山正北方的平原上。",al={"蛮鬃水井位置","蛮鬃水井在哪里","寻找蛮鬃水井"}},{q="谁发起了这个净化仪式？",a="驻扎在血蹄村的长老穆尔·雷角会引导你制作图腾，并派你去净化水井。",al={"谁发布了蛮鬃之井净化","任务发布者","穆尔·雷角的位置"}},{q="还有哪些水井属于这项净化工作的一部分？",a="蛮鬃水井是三个重要水源中的第三个，之前还有位于南方的冰蹄水井和雷角水井。",al={"其他水井","莫高雷水井","冰蹄水井和雷角水井"}},{q="净化图腾是如何工作的？",a="图腾中注入了祖先魔法和净化的自然元素，将修复性的精神能量引导入地下水位，以中和荆棘谷地精的污染物。",al={"净化图腾机制","图腾如何净化水"}},{q="完成这个仪式对血蹄村意味着什么？",a="净化这三口水井保证了莫高雷中部所有部落的饮水安全，也履行了牛头人治愈大地母亲、使其免受工业剥削的神圣职责。",al={"任务结果","为什么要净化水井","牛头人传说的重要性"}}},fx={["119d5a48"]={q="穆尔·雷角为什么想净化蛮鬃水井？",a="穆尔·雷角守护着莫高雷的精神平衡和重要资源。荆棘谷地精的污秽作业污染了土地珍贵的水源，威胁着各部族及其畜群的生存。蛮鬃水井是三口古老水井中最后一口仍遭污染的水井。净化它对于治愈大地母亲，并确保血蹄村和雷霆崖获得安全饮用水至关重要。",al={"穆尔·雷角的意图","为什么净化蛮鬃水井","穆尔为什么关心水井"}},b4cee6a1={q="蛮鬃之井净化图腾是什么？",a="蛮鬃之井净化图腾是穆尔·雷角制作的一种经过仪式准备的器具，用来引导先祖和大地之灵。在雷霆崖北面的蛮鬃水井受到污染后，于井边激活图腾，便能驱散地精污染者留下的有毒污泥，净化含水层，使泉水恢复自然、纯净的状态。",al={"蛮鬃之井净化图腾的用途","蛮鬃图腾是什么","净化图腾的作用"}}},fp="18,371,33.509.0,18.481.0,41.206.0,41.104.0,36.139.0,54.153.0,34.166.0,60.179.0"}
P.entries["quest:761"] = {n="猎捕猛鹫",s="狩猎猛鹫是哈肯·风之图腾在血蹄村提供的一项追踪与射击仪式。为了证明自己的机敏与耐心，猎人和旅行者们受命去莫高雷的草海平原追踪这种难以捉摸的鸟类。带着完好的猛鹫的羽毛归来，既证明了对狩猎的专注，也体现了对大地母亲自然试炼的尊重。",h="狩猎猛鹫是哈肯·风之图腾在血蹄村提供的一项追踪与射击仪式。为了证明自己的机敏与耐心，猎人和旅行者们受命去莫高雷的草海平原追踪这种难以捉摸的鸟类。带着完好的猛鹫的羽毛归来，既证明了对狩猎的专注，也体现了对大地母亲自然试炼的...",kw={"血蹄村","哈肯·风之图腾","莫高雷","猛鹫","狩猎猛鹫","牛头人试炼","猛鹫的羽毛"},ang={["class:Druid"]="在风蚀台地上追踪猛鹫，能让德鲁伊与维持莫高雷天空平衡的掠食鸟类建立更紧密的联系。",["class:Hunter"]="狩猎活动提供了一堂早期的进阶课，教授如何引导空中猎物、评估行为模式，并对警觉的掠食者进行精确打击。",["race:Tauren"]="对于牛头人青年和流浪者来说，狩猎莫高雷敏捷的猛鹫是一项神圣的成年仪式，它能磨砺追踪本能，并弘扬祖先的狩猎习俗。"},sec={{t="敏锐之眼的试炼",b="莫高雷的草原上充满了野兽，但很少有生物能像本土的猛鹫那样考验追猎者的直觉。这些大型掠食鸟类能与天际和草原融为一体，在头顶盘旋或贴着高草低飞。与笨拙的平原陆行鸟或吃草的科多兽不同，猛鹫需要高度的专注和敏捷的身手才能追捕到。因此，追捕猛鹫成了年轻猎人在部落中确立地位的传统证明仪式。"},{t="狩猎的徽记",b="对于哈肯·风之图腾来说，收集猛鹫的羽毛与其说是为了捕杀野生动物，不如说是为了培养纪律。在牛头人文化中，携带战利品象征着机敏与毅力。将这些完好的羽毛呈献给血蹄村的长者，标志着冒险者有能力供养和保卫社区，也证明了他们脚步迅捷，感官敏锐，足以驾驭更广阔的世界。"}},faq={{q="哈肯·风之图腾要求狩猎猛鹫的目的是什么？",a="哈肯·风之图腾委派猎人在莫高雷追踪猛鹫，以考验他们的机敏、速度和专注力。带回完好的猛鹫的羽毛是猎人技巧的公认证明，也能为他们赢得血蹄村牛头人的荣誉。",al={"为什么要狩猎猛鹫","哈肯·风之图腾的任务目的","狩猎猛鹫的目的"}},{q="通常在哪里能遇到猛鹫？",a="猛鹫分散在莫高雷的开阔平原上，它们会在草原上空翱翔，或是在血蹄村等定居点外搜寻草丛中的猎物。",al={"猛鹫在哪里","莫高雷的猛鹫位置","寻找猛鹫"}},{q="为什么说猛鹫很难狩猎？",a="与在平原上成群结队的动物不同，猛鹫是敏捷且警觉的猛禽，分布广泛且时刻保持警惕。追踪它们需要敏锐的视力来锁定它们的飞行轨迹，还需要快速的步伐，以便在它们逃脱前将其击落。",al={"为什么猛鹫难以捕获","猛鹫的行为习性"}},{q="猛鹫的羽毛对牛头人有什么意义？",a="在牛头人的传统中，猛鹫的羽毛代表着耐心、敏锐的洞察力和成功的追猎。展示这些羽毛意味着猎人拥有供养和保卫部落所必需的本能。",al={"猛鹫的羽毛含义","羽毛的意义"}},{q="哈肯·风之图腾是谁？",a="哈肯·风之图腾是血蹄村受人尊敬的牛头人居民，他会观察新来者和有志成为猎人的人，并通过在平原上进行的传统试炼来评估他们的足智多谋。",al={"谁提供狩猎猛鹫任务","哈肯·风之图腾的背景故事"}},{q="这种狩猎会影响莫高雷的自然平衡吗？",a="牛头人将狩猎视为与大地母亲的神圣对话，而非肆意屠杀。收集羽毛是一种衡量纪律的试炼，既是对猎物机敏的尊重，也维持了部落的平衡。",al={"狩猎猛鹫是否属于过度狩猎","猛鹫与莫高雷的平衡"}}},fx={["0d785fcd"]={q="哈肯·风之图腾为什么派外人去猎杀风鹏，而不是亲自去？",a="哈肯·风之图腾派你前去，并非因为他不会狩猎，而是为了考验你的能力。对牛头人来说，在平原上追踪狡猾的风鹏需要敏锐的目光、耐心和迅捷的蹄子。哈肯让你带回它们的羽毛，是给你一个向血蹄村证明技巧和决心的机会，表明你是一名真正出色的猎手。",al={"为什么让我去猎风鹏","哈肯为什么需要我帮忙","哈肯为什么不能自己猎风鹏"}}},fp="13,385,19.466.0,18.451.0,59.252.0,39.172.0,41.246.0,48.215.0,24.192.0,55.222.0"}
P.entries["quest:762"] = {n="邪恶的使者",s="史学家卡尼克希望你能除掉苦痛堡垒的因弗努斯大使。你需要回到荒芜之地，并将他被击杀的证明带给铁炉堡的顾问贝尔格拉姆。",h="史学家卡尼克希望你能除掉苦痛堡垒的因弗努斯大使。你需要回到荒芜之地，并将他被击杀的证明带给铁炉堡的顾问贝尔格拉姆。",kw={"顾问贝尔格拉姆","因弗努斯大使","苦痛堡垒","荒芜之地","史学家卡尼克","铁炉堡","拉格纳罗斯","黑铁矮人","奥达曼"},sec={{t="苦痛堡垒的大使",b="炎魔拉格纳罗斯亲自派遣因弗努斯大使前往苦痛堡垒，监督黑铁矮人在奥达曼搜寻失落的神器。矮人为此付出的生命代价已经非常惨重，而且还在不断增加。卡尼克不敢想象如果让黑铁矮人找到神器并用来对付铁炉堡，后果会有多严重。你必须回到荒芜之地，消灭因弗努斯，并将你胜利的证明带给贝尔格拉姆。时间紧迫，因为拉格纳罗斯可不会等他们慢慢准备。"},{t="贝尔格拉姆的谢意",b="贝尔格拉姆称赞了你对铁炉堡和矮人同胞的贡献，并会将你成功的消息传达给卡尼克。铁炉堡也将派遣援军前往荒芜之地以夺回挖掘场。以铜须国王的名义，贝尔格拉姆还有一件事要拜托你。"}},faq={{q="因弗努斯大使是谁？",a="拉格纳罗斯亲自派遣因弗努斯前往苦痛堡垒，监督黑铁矮人在奥达曼搜寻失落的神器。",al={"因弗努斯是谁","因弗努斯背景故事","因弗努斯大使背景"}},{q="因弗努斯大使在哪里？",a="在荒芜之地的苦痛堡垒。",al={"去哪里找因弗努斯大使","因弗努斯大使位置","因弗努斯在哪里"}},{q="为什么卡尼克想消灭因弗努斯大使？",a="黑铁矮人在奥达曼的搜索行动已经导致许多矮人丧生，卡尼克担心他们找到的神器会被用来对付铁炉堡。",al={"为什么要杀因弗努斯大使","因弗努斯在奥达曼做什么","铁炉堡荒芜之地威胁"}},{q="谁发布和完成这个任务？",a="由铁炉堡的史学家卡尼克发布，你需要将胜利的证明交给铁炉堡的顾问贝尔格拉姆。",al={"谁发布邪恶大使任务","谁交付邪恶大使任务","邪恶大使任务发布者"}},{q="需要什么样的证明？",a="因弗努斯大使的护腕，将其出示给顾问贝尔格拉姆作为你胜利的证明。",al={"我需要从因弗努斯身上获得什么","因弗努斯大使的证据","因弗努斯护腕"}}},fp="21,169,32.452.0,16.254.1,27.119.0,29.35.0,51.146.0,30.103.0,21.79.0"}
P.entries["quest:763"] = {n="大地之母仪祭",s="大地母亲的仪式标志着一名年轻的牛头人离开了隐蔽的红云台地，走向莫高雷更广阔的平原。既然已经在纳拉其营地证明了自己的实力，鹰风酋长便会让你带着一根雕刻过的图腾向北前往血蹄村，在贝恩·血蹄的指导下继续进行古老的试炼。",h="大地母亲的仪式标志着一名年轻的牛头人离开了隐蔽的红云台地，走向莫高雷更广阔的平原。既然已经在纳拉其营地证明了自己的实力，鹰风酋长便会让你带着一根雕刻过的图腾向北前往血蹄村，在贝恩·血蹄的指导下继续进行古老的试炼。",kw={"贝恩·血蹄","血蹄村","凯恩·血蹄","纳拉其营地","鹰风酋长","莫高雷","大地母亲的仪式","鹰风图腾"},ang={["faction:Horde"]="传统的仪式加强了整个莫高雷的部落团结，确保了部落的新守卫者既拥有战士的勇武，也拥有深厚的精神基础。",["race:Tauren"]="每一名年轻的牛头人都必须走过大地母亲的道路，向长老们证明自己的价值，并在团结的部落中找到属于自己的位置。"},sec={{t="离开台地",b="世世代代以来，年轻的牛头人们都在红云台地上纳拉其营地这片安全的摇篮里磨练自己的力量。完成最初的试炼证明了一个人拥有生存所需的纪律和决心，但神圣的大地母亲的仪式所要求的远不止是在当地的野生动物威胁下存活下来。鹰风酋长能够看出什么时候一名初生者已经不再适合台地庇护下的猎场，必须踏入更广阔的社群之中。"},{t="给贝恩的信物",b="为了搭建起纳拉其营地与中央聚落之间的桥梁，鹰风酋长提供了一根手工雕刻的图腾作为引荐的信物。带着这枚纹章顺着蜿蜒的小路前往血蹄村，你将会见到血蹄村的年轻酋长、大酋长凯恩·血蹄之子——贝恩·血蹄。这根图腾证明了你已经为前方更深奥的精神与智慧试炼做好了准备。"}},faq={{q="这个任务的目的是什么？",a="它作为成人礼引导你离开新手区域纳拉其营地，并指向血蹄村，让你开启牛头人仪式试炼的下一个篇章。",al={"为什么进行大地母亲的仪式","这个任务有什么作用","任务目的"}},{q="贝恩·血蹄是谁？",a="贝恩·血蹄是大酋长凯恩·血蹄的儿子。他领导着血蹄村，作为一名受人尊敬的当地酋长，负责监督年轻牛头人正在进行的精神与武力试炼。",al={"贝恩是谁","贝恩背景故事","凯恩之子"}},{q="什么是鹰风图腾？",a="这是一根由纳拉其营地的鹰风酋长手工雕刻的木质图腾。它充当了一份官方的证明和认可的印记，向贝恩·血蹄证明你已经获得了鹰风酋长的祝福，可以进行后续的仪式。",al={"鹰风图腾","雕刻图腾"}},{q="这之后还有什么仪式？",a="到达血蹄村并见到贝恩之后，你将被委派进行“幻象仪式”，通过神圣的先祖幻象来考验你的精神感应。",al={"接下来的仪式","之后要做什么","下一个任务"}},{q="血蹄村在哪里？",a="血蹄村位于纳拉其营地以北，坐落在莫高雷中央的石牛湖畔。旅行者只需沿着从台地下来的主路向北走即可。",al={"血蹄村在哪里","如何找到血蹄村","通往血蹄村的路径"}},{q="为什么要完成大地母亲的仪式？",a="大地母亲的仪式是牛头人中极度神圣的传统。通过仪式的所有阶段展现了肉体的坚韧、精神的连结与智慧，从而获得雷霆崖长老们真正的认可。",al={"为什么进行大地母亲仪式","牛头人试炼目的","大地母亲的仪式背景故事"}}},fx={["4a33bb81"]={q="鹰风酋长为什么让你去血蹄村？",a="鹰风酋长引导你完成了红云台地的入门试炼，但纳拉其营地已无法再教给你更多。要完成神圣的大地母亲仪式，并获得雷霆崖长老们的认可，你必须在莫高雷更广阔的平原上积累阅历。鹰风酋长让你带着他雕刻的图腾去见贝恩·血蹄，将你身心成长的责任托付给一位能够考验你是否已准备好真正成年的领袖。",al={"为什么派我去血蹄村","鹰风酋长的目的","为什么要进行大地母亲仪式"}},["9c980781"]={q="为什么必须由你亲自送去图腾？",a="这段旅程并非简单的跑腿差事，而是你成年礼中不可或缺的一部分。走出红云台地的庇护，沿着旷野大道前往莫高雷，能证明你的独立和毅力。亲手送上鹰风图腾，贝恩·血蹄便能亲自见到你，看到木头上刻着鹰风酋长的亲笔嘉许，并当面判断你的品格。",al={"为什么要我带图腾","鹰风酋长为什么不派信使","为什么让我进行大地母亲仪式"}}},fp="24,305,16.421.0,17.420.0,34.199.0,23.201.0,30.219.0,27.170.0,35.185.0,44.246.0"}
P.entries["quest:764"] = {n="风险投资公司",s="在莫高雷调查一辆被破坏的荆棘谷地精货车时，发现大量荆棘谷地精正在东部山丘进行挖掘活动。在采矿许可申请遭到断然拒绝后，该公司仍执意开采大地母亲的土壤，促使摩林·云行者下令采取致命的回击。",h="在莫高雷调查一辆被破坏的荆棘谷地精货车时，发现大量荆棘谷地精正在东部山丘进行挖掘活动。在采矿许可申请遭到断然拒绝后，该公司仍执意开采大地母亲的土壤，促使摩林·云行者下令采取致命的回击。",kw={"地精","采矿权","摩林·云行者","莫高雷","被破坏的货车","荆棘谷地精","荆棘谷地精矿场"},ang={["faction:Horde"]="在抵御商业开发中保卫莫高雷，巩固了你保护凯恩·血蹄子民的决心，他们正努力在这片新家园中扎根。",["profession:Mining"]="荆棘谷地精纯粹通过野蛮开采进行作业，他们偷工减料，破坏土地，丝毫不顾及自然平衡或采矿安全。",["race:Tauren"]="对牛头人而言，大地母亲是神圣的。荆棘谷地精的露天采矿不仅是越界行为，更是对他们祖传家园的暴力亵渎，必须立即将其强行驱逐。"},sec={{t="工业入侵",b="莫高雷的牛头人将这片土地视为大地母亲的延伸，珍视这里原始的平原与和谐的野生动物。当荆棘谷地精为了获取原矿，前来寻求在这片连绵起伏的山丘上进行爆破和挖掘的权利时，他们的请求被断然拒绝。这些贪婪的卡特尔不顾部落法令或领土主权，将重型机械、劳工和监工直接偷运进莫高雷的东部山脊，进行非法开采。"},{t="明确的讯息",b="像摩林·云行者这样的牛头人斥候意识到，一旦镐头敲击在石头上，就无法再通过外交呼吁来化解企业的贪婪。从一辆被破坏的荆棘谷地精货车中找到的文件证实了该公司的采矿作业，摩林派遣部落勇士去消灭那些挥舞鞭子的监工和操作钻机的劳工。这场血腥的报复旨在让荆棘谷地精明白，擅自闯入的代价是极其高昂的。"}},faq={{q="为什么荆棘谷地精会出现在莫高雷？",a="荆棘谷地精在莫高雷东部山丘沿线建立了非法的哨所和矿场，以开采矿石和自然资源。在牛头人正式拒绝授予其官方采矿权后，该卡特尔无视部落权威，执意开展了作业。",al={"为什么地精会在莫高雷","荆棘谷地精在莫高雷的目的","荆棘谷地精想要什么"}},{q="是谁下令攻击矿工的？",a="摩林·云行者，一位在血蹄村附近守卫的牛头人，下达了命令。他认为该卡特尔无视部落拒绝的做法是一种直接的侵犯，需要用武力而非进一步的谈话来解决。",al={"谁发布了这个任务","摩林·云行者的角色","任务发布者"}},{q="荆棘谷地精的矿场位于何处？",a="荆棘谷地精主矿场位于被破坏的货车和血蹄村以东的山麓地带。在雷霆崖北侧升降梯东北方的悬崖边，也能发现一处规模较小的卡特尔人员据点。",al={"荆棘谷地精矿场位置","监工在哪里","在哪里可以找到荆棘谷地精"}},{q="牛头人是否尝试过与这些地精谈判？",a="是的。荆棘谷地精曾向牛头人申请莫高雷的正式采矿权。部落首领拒绝让他们开采这片祖传土地，但地精们还是选择在未获许可的情况下进行挖掘。",al={"牛头人是否允许采矿","莫高雷采矿权","地精是否请求过许可"}},{q="这些地精属于热砂港吗？",a="不属于。荆棘谷地精是一个独立且臭名昭著的掠夺性工业卡特尔，与热砂港这样的中立贸易组织不同。无论在哪里开发资源，他们都与当地居民保持敌对关系。",al={"这些是棘齿城地精吗","荆棘谷地精友好吗","荆棘谷地精阵营"}},{q="这与被破坏的货车有什么关联？",a="那辆被破坏的货车是荆棘谷地精的车队，被牛头人摧毁了。从残骸中回收的采矿部门板条箱和文件揭露了该公司在莫高雷的行动，从而引发了这次对他们矿场的打击。",al={"货车关联","荆棘谷地精袭击过货车吗","被破坏的货车的关联"}}},fx={f6df914e={q="摩林·云行者为什么想要攻击荆棘谷地精？",a="荆棘谷地精公司在莫高雷的采矿权申请遭到正式拒绝，却无视拒绝，仍然开始筹备设备和招募工人。摩林·云行者不能容忍他们肆意破坏土地、掠夺自然资源。外交斡旋和断然拒绝都未能打消他们的贪欲，因此他认为牛头人必须以明确而强硬的方式警告他们：不会容忍擅闯和盗窃。",al={"摩林·云行者的目的","为什么攻击荆棘谷地精公司","摩林为什么要杀荆棘谷地精公司的人"}},eda5096c={q="你要去矿场对付谁？",a="你要对付的是驻扎在莫高雷东部采矿作业点的荆棘谷地精公司监工和工人。这些地精和受雇劳工未经部族许可，便在神圣的山丘上深挖，掠取矿物；而唯利是图的工头则推动公司咄咄逼人且非法的扩张。",al={"荆棘谷地精公司的任务目标","荆棘谷地精公司的工人是谁","我在矿场要打谁"}}},fp="15,339,20.472.0,23.485.0,38.269.0,40.215.0,42.253.0,54.219.0,50.237.0,46.224.0"}
P.entries["quest:765"] = {n="菲兹普罗克主管",s="监工费兹斯普罗克特是驻扎在莫高雷矿洞内的一名荆棘谷地精高层主管。摩林·云行者指派部落冒险者潜入矿洞，终结该地精组织的蓄意掠夺，并除掉他，取回他那份详细的剪贴板。",h="监工费兹斯普罗克特是驻扎在莫高雷矿洞内的一名荆棘谷地精高层主管。摩林·云行者指派部落冒险者潜入矿洞，终结该地精组织的蓄意掠夺，并除掉他，取回他那份详细的剪贴板。",kw={"剪贴板","费兹斯普罗克特","矿洞","摩林·云行者","莫高雷","监工","荆棘谷地精"},ang={["faction:Horde"]="协助牛头人对抗入侵的企业掠夺者，巩固了部落对卡利姆多新宣称的核心领土的保护。",["race:Tauren"]="荆棘谷地精企图驱逐你们的部族并掠夺这片圣土的公开阴谋，使得击杀费兹斯普罗克特成为一项至关重要的领土保卫行动。"},sec={{t="针对平原的阴谋",b="从一辆被破坏的荆棘谷地精货车中寻获的文件揭示，荆棘谷地精不仅仅是在挖掘矿石，他们还在精心策划将牛头人彻底赶出莫高雷。通过驱逐当地居民，这家贪婪的企业试图获得不受限制的自由，去掠夺连绵起伏的丘陵和深层矿脉中的一切自然资源。"},{t="痛击监工",b="摩林·云行者对针对其族人策划的企业暴行感到愤怒，他指挥勇士们进入位于被破坏的货车东侧的荆棘谷地精矿洞。监工费兹斯普罗克特在右侧矿洞深处管理着运作，周围环绕着劳工和下属头目。击杀费兹斯普罗克特并夺取他的剪贴板将瓦解当地的协调能力，并获得有关该组织未来计划的关键情报。"}},faq={{q="监工费兹斯普罗克特是谁？",a="监工费兹斯普罗克特是一名荆棘谷地精头目，负责莫高雷东部矿洞内的运作。他监管着挖掘大地的劳工，并执行旨在扩大该地区业务的企业策略。",al={"费兹斯普罗克特","谁是费兹斯普罗克特","费兹斯普罗克特背景故事"}},{q="为什么摩林·云行者想要费兹斯普罗克特死？",a="摩林在一辆被突袭的货车上发现了文件，证明荆棘谷地精密谋为了利益将牛头人赶出他们的祖居地。费兹斯普罗克特正是执行这些精心策划的剥削阴谋的直接负责人。",al={"为什么要击杀费兹斯普罗克特","摩林·云行者的动机"}},{q="监工费兹斯普罗克特在哪里？",a="他位于莫高雷被破坏的货车正东方的荆棘谷地精矿洞内。进入矿洞后，沿着最右侧的隧道走到一个房间，他就在那里，周围环绕着工人和监工。",al={"费兹斯普罗克特在哪里","费兹斯普罗克特矿洞位置","费兹斯普罗克特地图"}},{q="摩林需要什么证据来证明费兹斯普罗克特已被击败？",a="摩林·云行者需要费兹斯普罗克特的个人剪贴板，其中包含的账目和记录可能揭示荆棘谷地精在莫高雷的进一步企图。",al={"击杀证明","费兹斯普罗克特的剪贴板"}},{q="为什么荆棘谷地精会在莫高雷？",a="荆棘谷地精是一个肆无忌惮的商业卡特尔，一心想要剥削原始领土上的木材、矿产和宝贵的地下财富，完全无视原住民或环境平衡。",al={"莫高雷的荆棘谷地精","为什么地精在莫高雷"}},{q="击杀费兹斯普罗克特能将荆棘谷地精彻底赶走吗？",a="不能。虽然费兹斯普罗克特的死亡破坏了他们的当地领导层，并为摩林·云行者提供了有关他们计划的重要笔记，但荆棘谷地精仍然是盘踞在莫高雷丘陵中的持续威胁。",al={"荆棘谷地精离开了吗","费兹斯普罗克特死后"}}},fp="22,298,25.371.0,21.456.1,30.251.0,50.232.0,40.207.0,54.160.0,38.219.0,67.204.0"}
P.entries["quest:766"] = {n="马兹拉纳其",s="位于血蹄村的茂尔·祈雨遭到了玛兹拉纳切的毒咬，这只传奇的平原陆行鸟曾在一代人之前恐吓过他的祖父。在发烧和谵妄梦魇的折磨下，这位牛头人急需一种用莫高雷的野生生物制成的强效药剂，以保住性命。",h="位于血蹄村的茂尔·祈雨遭到了玛兹拉纳切的毒咬，这只传奇的平原陆行鸟曾在一代人之前恐吓过他的祖父。在发烧和谵妄梦魇的折磨下，这位牛头人急需一种用莫高雷的野生生物制成的强效药剂，以保住性命。",kw={"血蹄村","平原狮","茂尔·祈雨","玛兹拉纳切","莫高雷","平原陆行鸟","草原狼","猛鹫"},ang={["class:Hunter"]="在莫高雷各地追踪草原狼、平原狮、平原陆行鸟和猛鹫，是学习解读平原环境和了解大草原独特野生生物的一门实践课。",["faction:Horde"]="保护血蹄村免受莫高雷严酷危险的侵袭，对于在牛头人家园建立和平与稳定至关重要。",["race:Tauren"]="茂尔制作的药剂反映了牛头人直接从大地母亲的植物与动物身上获取疗法的古老习俗。"},sec={{t="平原的传说",b="多年来，茂尔·祈雨一直认为玛兹拉纳切不过是祖父口中令人毛骨悚然的家族传说。这位年长的牛头人曾提到过一只不同寻常的凶猛平原陆行鸟，它长着发红光的眼睛和锋利的爪子，毒咬的习性也与大多数莫高雷的野生生物那种温顺的本性背道而驰。当茂尔在开阔的草原上与这头野兽狭路相逢时，传说被证实是真实存在的，他身受重伤，挣扎着才逃回安全地带。"},{t="与感染赛跑",b="这种生物的毒液发作极快，会导致高烧和谵妄的梦魇。为了在毒液致命前将其清除，传统的牛头人医药依赖于当地野兽的生命力。茂尔需要草原狼的心脏、平原狮的腿骨、平原陆行鸟的鳞片和猛鹫的胃。通过结合这些各异的猎食者与食腐动物的精华，他可以调制出一种能够阻止毒素蔓延并助他恢复健康的药剂。"}},faq={{q="玛兹拉纳切是什么？",a="玛兹拉纳切是一只游荡在莫高雷草原上的臭名昭著的平原陆行鸟。与普通的陆行鸟不同，它以鲜艳的羽毛、恶魔般的红眼、凶猛的利爪以及不同寻常的剧毒咬击而闻名。它已经恐吓了数代旅行者。",al={"玛兹拉纳切是谁","玛兹拉纳切是什么野兽","玛兹拉纳切背景故事"}},{q="茂尔·祈雨是谁？",a="茂尔·祈雨是一位居住在血蹄村的牛头人。在穿越莫高雷时，他遭到玛兹拉纳切的伏击并被咬伤肩膀，导致他卧床不起，深受致命的毒性感染威胁。",al={"茂尔·祈雨","任务发布者是谁","生病的牛头人是谁"}},{q="为什么茂尔需要四种不同野兽的身体部位？",a="传统的牛头人药方利用平原动物的自然力量和精神精华来中和强效毒素。狼的心脏、平原狮腿骨中浓缩的骨髓、平原陆行鸟的鳞片以及猛鹫的胃，这些组合在一起形成了解毒剂，足以抵御玛兹拉纳切的毒液。",al={"为什么需要狼心和狮腿骨","为什么需要动物材料","玛兹拉纳切药剂配方"}},{q="茂尔的祖父杀死了玛兹拉纳切吗？",a="没有。茂尔的祖父曾与这只凶猛的平原陆行鸟战斗，但未能将其击败，他幸存下来后，便将关于它鲜艳色彩和凶狠攻击的警示传给了后代。",al={"祖父击败过玛兹拉纳切吗","茂尔的祖父与玛兹拉纳切","谁曾与玛兹拉纳切战斗"}},{q="这个任务要求我亲自去猎杀玛兹拉纳切吗？",a="不。茂尔当前的头等大事是挺过高烧。任务的重点完全在于收集制作解药所需的材料，而不是去猎杀这只传奇的鸟兽。",al={"我需要杀死玛兹拉纳切吗","玛兹拉纳切在哪里","猎杀玛兹拉纳切"}},{q="血蹄村位于何处？",a="血蹄村位于莫高雷中部，雷霆崖以南，石牛湖正东。它是年轻的牛头人勇士前往广阔平原历练的主要定居点。",al={"血蹄村在哪里","血蹄村位置"}}},fx={["3b88d77e"]={q="茂尔·祈雨为什么要你做这件事？",a="茂尔的性命危在旦夕。他在莫高雷平原旅行时遇上了马兹拉纳其，一头传说中的陆行鸟，曾以凶残著称，令他的祖父饱受惊吓。那头野兽狠狠咬伤了茂尔的肩膀，毒液也侵入了伤口。他开始发起令人虚弱的高烧，噩梦连连、神志昏乱，病情还在体内不断蔓延。若没有用于调制药方的动物材料，凶猛的感染很快就会夺走他的性命。",al={"茂尔·祈雨的目的","为什么要帮茂尔·祈雨","茂尔出了什么事"}},ce37bf7e={q="茂尔为什么要找外人帮忙，而不是自己治伤？",a="茂尔伤势严重，又发着高烧，已无法亲自在莫高雷狩猎。马兹拉纳其的毒牙让他神志昏乱、精疲力竭，只能留在血蹄村。感染致命之前所剩时间不多，他只能依靠路过的旅人，去追踪迅捷的山狮、风鹏、狼和陆行鸟，为他找齐药方所需的材料。",al={"茂尔为什么不能自己找材料","茂尔为什么需要你","为什么让我对付马兹拉纳其"}}},fp="11,313,22.471.0,20.462.0,20.251.0,23.208.0,52.303.0,40.198.0,55.180.0,35.193.0"}
P.entries["quest:767"] = {n="幻象仪祭",s="幻象仪式是大地之母仪式中至关重要的成人礼，旨在考验年轻冒险者的精神成熟度。这项任务由贝恩·血蹄发起，指引寻求者前往血蹄村，从预言者扎尔曼·双月那里寻求指引。对于任何想要获得雷霆崖高地上长者们祝福与尊重的人来说，这段旅程都是必不可少的。",h="幻象仪式是大地之母仪式中至关重要的成人礼，旨在考验年轻冒险者的精神成熟度。这项任务由贝恩·血蹄发起，指引寻求者前往血蹄村，从预言者扎尔曼·双月那里寻求指引。对于任何想要获得雷霆崖高地上长者们祝福与尊重的人来说，这段旅程都...",kw={"贝恩·血蹄","血蹄村","莫高雷","幻象仪式","大地之母仪式","牛头人试炼","雷霆崖","扎尔曼·双月"},ang={["class:Druid"]="与大地之母的幻象直接沟通，进一步加强了德鲁伊倾听生活世界智慧与低语的使命。",["class:Shaman"]="寻找扎尔曼·双月并走上幻象之路，与萨满在平衡世俗事务与祖先意志方面的职责产生了深刻的共鸣。",["faction:Horde"]="进行这些传统的圣礼，证明了你对帮助指引部落的牛头人长者们的忠诚与文化敬意。",["race:Tauren"]="幻象仪式是每一位年轻牛头人不可或缺的文化里程碑，标志着你正式转变为部族中受人信赖的捍卫者和灵魂行者。"},sec={{t="神圣的基石",b="世世代代以来，游牧的牛头人一直追随大地之母，在卡利姆多的平原上指引着族人。如今，他们聚集在莫高雷的安全边界内，其精神传统依然是他们社会的基石。幻象仪式是被称为“大地之母仪式”的古老试炼之一。早期的试炼旨在考验入门者的身体力量和与狩猎的联系，而幻象仪式则要求进行内心的探索，指引年轻的牛头人以及受人尊敬的盟友直接与灵魂沟通。"},{t="预言者的指引",b="在寻求任何精神幻象之前，入门者必须先由一位深谙古老智慧的人进行准备。在血蹄村，这一职责落在了受人尊敬的萨满扎尔曼·双月身上。受贝恩·血蹄之托为旅行者提供指导，扎尔曼拥有敏锐的洞察力，能够识别出那些走在祖先道路上的人，并提供穿透物质世界面纱所需的初步仪式和神圣准备。"}},faq={{q="什么是幻象仪式？",a="幻象仪式是大地之母仪式中的一项神圣仪式。它旨在拓宽冒险者的精神视野，使他们能够与祖先之灵沟通，并向雷霆崖的长者们证明自己的精神准备。",al={"幻象仪式任务","什么是幻象仪式","幻象仪式背景故事"}},{q="谁发布了这个任务？",a="该任务由大酋长凯恩·血蹄之子贝恩·血蹄发布。贝恩守护着血蹄村，并将值得信赖的旅行者引向村中的精神长者。",al={"谁发布幻象仪式","幻象仪式任务发布者"}},{q="扎尔曼·双月是谁？",a="扎尔曼·双月是一位经验丰富的牛头人萨满，也是血蹄村的精神领袖。他负责为寻求进行幻象仪式等神圣试炼的旅行者和入门者提供准备。",al={"扎尔曼是谁","扎尔曼·双月背景故事"}},{q="为什么大地之母仪式对牛头人很重要？",a="大地之母仪式代表了牛头人成人礼的传统仪式。成功完成这些仪式证明了一个人的身体能力、精神调和以及对大地的持久尊重，从而赢得高位长者的荣耀。",al={"大地之母仪式的意义","为什么要进行大地之母仪式"}},{q="非牛头人可以进行幻象仪式吗？",a="可以。途经莫高雷并赢得血蹄部族信任的部落盟友，被允许走上大地之母的道路，以对牛头人传统的尊重换取长者们的青睐。",al={"兽人可以进行幻象仪式吗","非牛头人大地之母"}},{q="这个试炼在哪里进行？",a="试炼始于血蹄村，这是一个位于莫高雷中部、雷霆崖南面、石牛湖畔的著名牛头人定居点。",al={"幻象仪式在哪里","幻象仪式地点"}}},fx={["1fa313da"]={q="贝恩·血蹄为什么要你进行先知之水仪式？",a="贝恩·血蹄正在引导你踏上先祖之路，向牛头人证明自己的价值。你在莫高雷成年后，必须履行神圣的大地母亲仪式，与灵魂交流，学会敬重土地，最终赢得雷霆崖长老的尊重。贝恩指引你去找村中的秘术师扎尔曼·双月，让你正式开始这场灵性试炼。",al={"贝恩为什么派你进行先知之水仪式","贝恩·血蹄让你进行先知之水仪式的目的","为什么要进行先知之水仪式"}}},fp="14,381,23.535.0,19.443.0,27.255.0,22.205.0,25.190.0,61.255.0,44.208.0,33.154.0"}
P.entries["quest:768"] = {n="收集皮革",s="“收集皮革”是维尔伦·陆行者在雷霆崖的高地上发布的一项简单的贸易请求。为了维持首都的运转并考验年轻的猎人，维尔伦用手工制品交换一批鞣制过的轻皮。这凸显了牛头人将平原狩猎的成果转化为必需的衣物和护甲这一根深蒂固的传统。",h="“收集皮革”是维尔伦·陆行者在雷霆崖的高地上发布的一项简单的贸易请求。为了维持首都的运转并考验年轻的猎人，维尔伦用手工制品交换一批鞣制过的轻皮。这凸显了牛头人将平原狩猎的成果转化为必需的衣物和护甲这一根深蒂固的传统。",kw={"收集皮革","制皮","轻皮","莫高雷","牛头人狩猎","雷霆崖","维尔伦·陆行者"},ang={["class:Hunter"]="前往莫高雷平原冒险的猎人自然擅长追踪猎物并采集维尔伦所需的轻皮。",["faction:Horde"]="为雷霆崖的工匠提供原材料可以加强这座年轻的首都，巩固其防御和贸易网络。",["race:Tauren"]="对于牛头人猎人来说，通过将倒下的野兽的皮毛转化为有用的商品来纪念它们，是一项代代相传的重要文化准则。"},sec={{t="维持雷霆崖的运转",b="在莫高雷高耸的平顶山上新建立的首都里，手工艺与生存息息相关。维尔伦·陆行者将兽皮加工成雷霆崖日益增长的人口所需的衣物和防护护甲。他没有亲自去采集所有材料，而是鼓励前往平原的年轻冒险者带回他们的猎物，将平凡的狩猎转化为光荣的公民服务。"},{t="狩猎之道",b="对于牛头人来说，在草原上猎杀野兽并非体育运动，而是一种能够让部落有饭吃、有衣穿、有住所的崇高事业。维尔伦·陆行者寻找渴望为氏族带来荣誉的猎人，专门要求从当地野生动物身上剥取轻皮。作为十二张保存完好的兽皮的回报，他会用结实的商品酬谢猎人，加强了将牛头人社会凝聚在一起的相互支持。"}},faq={{q="谁是维尔伦·陆行者？",a="维尔伦·陆行者是一位居住在雷霆崖的制皮师。他为牛头人人民制作衣物和防护护甲，并将成品与从平原带回新鲜兽皮的猎人进行交易。",al={"维尔伦·陆行者","谁发布收集皮革任务","雷霆崖皮革任务发布者"}},{q="维尔伦·陆行者需要什么？",a="维尔伦需要十二张轻皮，这些轻皮是从游荡在莫高雷及周边地区的野兽身上获取的，用于为雷霆崖制作商品。",al={"收集皮革任务要求","给维尔伦带什么","收集皮革所需材料"}},{q="这个任务在哪里进行？",a="该任务在雷霆崖顶的维尔伦·陆行者处开始和结束，尽管完成它需要在大草原上的野兽身上狩猎。",al={"维尔伦·陆行者在哪里","收集皮革任务地点"}},{q="为什么牛头人如此重视狩猎野兽？",a="牛头人文化将狩猎视为与大地母亲之间的一种神圣平衡。倒下的野兽的每一个部分都会被利用：肉用来喂养部落，骨头和鞣制过的兽皮则被加工成工具、帐篷和耐用的护甲。",al={"牛头人狩猎文化","为什么要狩猎获取皮革","牛头人制皮背景故事"}},{q="任何部落冒险者都可以承担这项任务吗？",a="是的，任何效忠于部落且被维尔伦认为渴望在平原上考验自己勇气的旅行者，都可以协助他收集皮革。",al={"谁可以做收集皮革任务","收集皮革任务是否仅限部落"}},{q="皮革交付后会发生什么？",a="维尔伦会检查兽皮的质量，称赞猎人的工作，并以公平交易的方式提供一件制造的装备。",al={"收集皮革任务交付","维尔伦·陆行者奖励"}}},fx={["1249c214"]={q="维尔伦·陆行者为什么要轻皮？",a="维尔伦·陆行者是一名制皮师，为雷霆崖的居民制作衣物和护甲。为了供给城市所需并维持自己的手艺，他依靠猎人从莫高雷平原带回优质兽皮。",al={"维尔伦为什么需要皮革","维尔伦·陆行者的目的","为什么给维尔伦轻皮"}},cd30155e={q="轻皮有什么用？",a="这些皮革会被制成必需的衣物、防护护甲和实用物品，供居住在雷霆崖高台地上的牛头人使用，也会被制成装备，作为交换交给旅行中的猎人。",al={"轻皮有什么用","轻皮的用途","维尔伦如何使用轻皮"}}},fp="17,360,24.407.0,19.436.0,25.210.0,33.153.0,33.147.0,61.219.0,45.137.0,43.128.0"}
P.entries["quest:769"] = {n="科多兽皮包",s="科多兽皮包是一个由维尔伦·陆行者提供的贸易任务。维尔伦·陆行者是一位技艺精湛的牛头人制皮匠，常驻雷霆崖的高地之上。为了换取基础的制作材料，他会传授一种传统的平原技艺，用结实的兽皮缝制耐用的旅行包。这对莫高雷的制皮学徒来说，是一次早期的试炼。",h="科多兽皮包是一个由维尔伦·陆行者提供的贸易任务。维尔伦·陆行者是一位技艺精湛的牛头人制皮匠，常驻雷霆崖的高地之上。为了换取基础的制作材料，他会传授一种传统的平原技艺，用结实的兽皮缝制耐用的旅行包。这对莫高雷的制皮学徒来说...",kw={"粗线","科多兽","科多兽皮包","制皮","轻皮","莫高雷","雷霆崖","维尔伦·陆行者"},ang={["faction:Horde"]="雷霆崖的工匠提供重要的后勤物资，使部落的猎人、斥候和战士能够在卡利姆多中部保持装备精良。",["race:Tauren"]="对于舒哈鲁人来说，学习如何用强大的科多兽皮制作可靠的装备，是纪念地母的馈赠和传承祖先方式的重要一步。"},sec={{t="高地上的课程",b="维尔伦·陆行者在雷霆崖的工匠高地上，秉持着狩猎不浪费的悠久游牧传统。想要获得他的指点，有志向的制皮匠必须向他进贡经过处理的轻皮和粗线。通过展示对基础材料的掌握能力，学徒们证明自己已经准备好制造能够携带补给物资穿越卡利姆多崎岖荒野的装备了。"},{t="科多兽之魂",b="对牛头人而言，科多兽是耐力、力量和坚定信念的象征。它们厚实的皮毛可以抵御荆棘、刺骨寒风以及野兽的利爪。用科多兽皮制作背包和服饰不仅是一种实用主义的行为，更是对这种哺育了舒哈鲁族并载着他们在莫高雷平原上繁衍生息无数代生灵的崇敬。"}},faq={{q="谁提供科多兽皮包任务？",a="该任务由维尔伦·陆行者提供，他是一位位于雷霆崖的牛头人制皮训练师兼商人。",al={"任务发布者","科多兽皮包任务在哪里接","维尔伦·陆行者位置"}},{q="谁有资格承接此任务？",a="只有至少达到初级制皮技能等级10级的冒险者，才能从维尔伦·陆行者那里接到这个培训任务。",al={"谁可以接此任务","任务要求","专业技能要求"}},{q="维尔伦·陆行者需要什么材料？",a="他需要四块轻皮和四卷粗线来补充贸易物资，然后才会分享他的配方。",al={"需要什么物品","科多兽皮包材料","任务上交物品"}},{q="为什么科多兽皮对牛头人匠人很重要？",a="科多兽体现了韧性和力量，这些品质深受牛头人珍视。用它们的皮制作耐用的装备既是对生物灵魂的致敬，也为横跨平原的旅者提供了结实的用具。",al={"为什么用科多兽皮","牛头人科多兽的意义","科多兽的重要性"}},{q="完成任务后维尔伦·陆行者会教授什么？",a="在收到物资后，维尔伦会教授制皮匠缝制科多兽皮包所需的专门知识。",al={"任务奖励","我能得到什么","背包配方"}},{q="在哪里可以获得必要的材料？",a="轻皮可以通过剥皮莫高雷及周边领地的低等级野兽获得，而粗线可以直接从贸易供应商和裁缝商人处购买。",al={"轻皮哪里获得","粗线哪里获得"}}},fx={c94273ea={q="维尔伦·陆行者为什么要你做这件事？",a="维尔伦·陆行者以培养新一代牛头人制皮师为荣。莫高雷的科多兽因力量和耐力而备受敬重，用它们的皮制作传统背包是基础技艺。维尔伦让你为他的手艺收集材料，以此考验你的投入和应变能力，然后才会传授这门手艺的技巧。",al={"维尔伦·陆行者为什么要皮革","维尔伦·陆行者的目的","为什么要做科多兽皮袋任务"}},["1f62e959"]={q="轻皮有什么用？",a="轻皮是维尔伦·陆行者用来换取指导的基础材料。鞣制兽皮是牛头人制皮技艺的核心。提供优质皮革，能证明你已掌握处理兽皮的基本功，之后才能学习缝制科多兽皮袋等专用容器。",al={"轻皮有什么用途","为什么要带轻皮","轻皮的作用"}},["7d0f7d7f"]={q="粗线有什么用？",a="粗线是裁缝和制皮工艺中不可或缺的材料，用来缝合厚重的兽皮。要制作能经受莫高雷平原考验的耐用背包，工匠需要结实的绳线，确保它不会在重压或恶劣天气下断裂。",al={"为什么要粗线","粗线的作用","粗线有什么用"}}},fp="13,362,20.426.0,18.388.0,35.113.0,39.149.0,46.133.0,59.224.0,50.125.0,46.176.0"}
P.entries["quest:77"] = {n="收集蜜糖",s="基沃拉丁·猎日者拥有德兰·德罗弗斯想要的辛特兰蜜糖的原包装，并愿意在收取两瓶额外报酬的情况下帮忙打包。这些瓶子就散落在隐匿石附近废弃部落营地的板条箱里。",h="基沃拉丁·猎日者拥有德兰·德罗弗斯想要的辛特兰蜜糖的原包装，并愿意在收取两瓶额外报酬的情况下帮忙打包。这些瓶子就散落在隐匿石附近废弃部落营地的板条箱里。",kw={"德兰·德罗弗斯","基沃拉丁·猎日者","辛特兰","辛特兰蜜糖","软泥怪","隐匿石","淤泥怪"},sec={{t="包装问题",b="德兰·德罗弗斯在寻找这种酒，而基沃拉丁·猎日者拥有它的原包装。帮忙可不是免费的：基沃拉丁想要两瓶额外的酒作为辛苦费。你需要收集十瓶辛特兰蜜糖并带回营地。"},{t="隐匿石废墟",b="板条箱就放在隐匿石附近废弃的部落营地周围。肮脏的软泥怪和淤泥怪盘踞在废墟中，据传那里还有某种软泥怪首领在统领它们。"}},faq={{q="谁想要包装辛特兰蜜糖？",a="德兰·德罗弗斯是那个寻找酒的人，而基沃拉丁·猎日者拥有原包装，这是为了马尔顿的父亲准备的。",al={"谁需要这种酒","德兰·德罗弗斯的酒","包装是给谁的"}},{q="基沃拉丁打包收费多少？",a="基沃拉丁要求额外两瓶这种酒作为费用。你需要从板条箱中找回十瓶酒。",al={"为什么要10瓶","基沃拉丁的费用","为什么需要这么多酒"}},{q="辛特兰蜜糖的板条箱存放在哪里？",a="它们被存放在辛特兰隐匿石附近废弃部落营地的板条箱里。",al={"酒的位置","辛特兰蜜糖在哪里","隐匿石的板条箱"}},{q="隐匿石的废弃营地里有什么？",a="肮脏的软泥怪和淤泥怪盘踞在废墟中，据传有一只软泥怪首领在统领它们。",al={"隐匿石的怪物","隐匿石有什么","隐匿石的软泥怪"}}},fp="18,243,21.259.0,19.159.0,48.140.0,46.115.0,54.86.0,44.82.0"}
P.entries["quest:770"] = {n="恶魔之伤",s="恶魔之伤是一张从传说中的白狼Ghost Howl身上获取的褴褛毛皮，它徘徊在莫高雷的草地上。这张毛皮上留下了过去与燃烧军团冲突时造成的永久性伤痕，是这只野兽从折磨中解脱的证明。将它带给血蹄村的长老，可以为一个悲剧性的当地传说画上句号。",h="恶魔之伤是一张从传说中的白狼Ghost...",kw={"燃烧军团","恶魔之伤","ghost howl","莫高雷","斯考恩·白云","白狼"},ang={["class:Druid"]="德鲁伊将这张留有恶魔伤痕的毛皮视为一种严峻的提醒，提醒人们这片土地及其野生居民仍然承受着卡利姆多恶魔入侵留下的未愈伤口。",["class:Hunter"]="追踪像Ghost Howl这样孤独、伤痕累累的头狼是一项必要的成年礼，可以获得斯考恩·白云长老的高度赞扬和一位大师级猎人的馈赠。",["race:Tauren"]="对于舒哈鲁人来说，狩猎Ghost Howl并非残忍或征服的行为，而是一种庄严的仪式，旨在让受折磨的生物从燃烧军团挥之不去的污秽中解脱，获得安宁。"},sec={{t="邪能创伤的遗物",b="Ghost Howl是一只难以捉摸的白狼，因其凶猛和悲伤的嚎叫而在莫高雷闻名。当这只野兽被杀后，会留下一张因邪恶的恶魔腐蚀而伤痕累累的毛皮。这些挥之不去的印记可以追溯到这只狼与燃烧军团的入侵恶魔进行的殊死搏斗，这场对峙使Ghost Howl在第三次大战结束后很久，肉体和精神上都留下了创伤。"},{t="让受折磨的灵魂安息",b="莫高雷的牛头人对他们家园的野生动物保持着深深的敬意，尊崇它们为大地母亲的孩子。将恶魔之伤交给血蹄村的斯考恩·白云，证实了这只饱受折磨的掠食者的死亡。斯考恩认可追踪并击败Ghost Howl所需的精湛技巧，并表达了沉重的希望，愿这只狼受尽折磨的灵魂在死后终于能获得安宁。"}},faq={{q="什么是恶魔之伤？",a="这是从莫高雷的传说白狼Ghost Howl身上获取的褴褛兽皮。这张毛皮上清晰地留下了过去与燃烧军团战斗中邪能留下的伤痕。",al={"什么是恶魔之伤","恶魔之伤物品","ghost howl毛皮"}},{q="披风上的恶魔伤痕是从哪里来的？",a="Ghost Howl的伤痕是在第三次大战期间，当恶魔入侵者横扫卡利姆多时，与燃烧军团的冲突中留下的。",al={"为什么ghost howl有伤痕","ghost howl是如何受伤的","ghost howl和军团"}},{q="我应该把披风带给谁？",a="把披风带给斯考恩·白云，他是一位居住在莫高雷血蹄村的牛头人老猎人。",al={"在哪里交恶魔之伤","谁需要恶魔之伤","斯考恩·白云交任务"}},{q="为什么斯考恩·白云会关心Ghost Howl？",a="斯考恩·白云是一位退休的猎人，他认为Ghost Howl是一只因恶魔腐蚀而深受折磨的可怕野兽。他尊重击败这样一只生物所需的技巧，并希望它的灵魂最终能安息。",al={"斯考恩·白云背景故事","为什么斯考恩想要ghost howl"}},{q="在哪里可以找到Ghost Howl？",a="Ghost Howl是一只稀有的白狼，它徘徊在莫高雷的草海平原，通常出现在红云台地和雷霆崖之间的北部或中部开阔地带。",al={"哪里找到ghost howl","ghost howl位置","ghost howl刷新"}},{q="为什么牛头人希望这只狼的灵魂能获得安宁？",a="牛头人文化强调与自然的和谐以及对野生灵魂的敬畏。由于恶魔的腐蚀给Ghost Howl的一生带来了无尽的折磨，击败它被视为一种回归大地母亲的仁慈解脱。",al={"牛头人对ghost howl的信仰","ghost howl灵魂"}}},fp="23,378,21.424.0,27.421.0,32.174.0,49.141.0,28.104.0,48.224.0,26.172.0,53.220.0"}
P.entries["quest:7701"] = {n="悬赏：工头玛托留斯",s="一张悬赏令宣称，监工马托留斯，一名叛逃的瑟银兄弟会特工，同时也是大熔炉黑铁熔渣之池挖掘队新雇佣的指挥官，必须死。奉监工油拳之命，必须将其头颅带回给侦查队长洛洛尔，作为他已死亡的证明。",h="一张悬赏令宣称，监工马托留斯，一名叛逃的瑟银兄弟会特工，同时也是大熔炉黑铁熔渣之池挖掘队新雇佣的指挥官，必须死。奉监工油拳之命，必须将其头颅带回给侦查队长洛洛尔，作为他已死亡的证明。",kw={"悬赏","大熔炉","侦查队长洛洛尔","监工马托留斯","监工油拳","灼热峡谷","熔渣之池","瑟银兄弟会"},sec={{t="叛徒的代价",b="叛逃的黑铁矮人监工马托留斯就藏在大熔炉的熔渣之池深处。命令是杀掉他，取下他的头颅，并带回给侦查队长洛洛尔以领取赏金。"}},faq={{q="谁是监工马托留斯？",a="一名背叛的黑铁矮人。通告称他为叛逃的瑟银兄弟会特工，以及大熔炉黑铁熔渣之池挖掘队新雇佣的指挥官。",al={"马托留斯背景故事","谁是马托留斯","监工马托留斯背景"}},{q="在哪里可以找到监工马托留斯？",a="在属于大熔炉的熔渣之池下方。",al={"马托留斯位置","马托留斯在哪里","如何找到监工马托留斯"}},{q="是谁下令处死监工马托留斯的？",a="监工油拳，他在通告中被指名为下达该命令的人。",al={"谁发布了悬赏","谁想要马托留斯死","谁下达了处决令"}},{q="谁负责接收马托留斯死亡的证明？",a="位于灼热峡谷的侦查队长洛洛尔。马托留斯的头颅就是所要求的证明。",al={"把马托留斯的头颅交给谁","把马托留斯的头颅带到哪里","侦查队长洛洛尔位置"}}},fp="26,274,20.217.0,26.162.0,38.52.0,44.71.0,40.97.0"}
P.entries["quest:7704"] = {n="Look at the Size of It!",s="你得到了一只巨大的华丽枕头，它曾经属于女仆Pillaclencher。灼热峡谷的Evonice Sootsmoker一定想要它。",h="你得到了一只巨大的华丽枕头，它曾经属于女仆Pillaclencher。灼热峡谷的Evonice Sootsmoker一定想要它。",kw={"女仆 pillaclencher","evonice sootsmoker","看看这东西的尺寸","枕头","灼热峡谷"},sec={{t="给Evonice的枕头",b="你现在拥有了女仆Pillaclencher保存的枕头。Evonice Sootsmoker肯定会迫不及待地想要得到它。把它带给灼热峡谷的她，看看她会为你这份辛苦提供什么报酬。"}},faq={{q="谁想要女仆Pillaclencher的枕头？",a="灼热峡谷的Evonice Sootsmoker应该会非常想要它。",al={"我该把枕头带给谁","evonice sootsmoker 枕头","枕头交给谁"}},{q="这个枕头是从哪来的？",a="它属于女仆Pillaclencher，又大又华丽。",al={"枕头掉落","谁掉落枕头","女仆枕头"}},{q="Evonice Sootsmoker在哪里？",a="在灼热峡谷。",al={"evonice 位置","evonice sootsmoker 在哪里","evonice 灼热峡谷"}}},fp="23,156,20.196.0,45.68.0,33.69.0,38.21.0"}
P.entries["quest:771"] = {n="幻象仪祭",s="幻象之礼是牛头人年轻人离开红云台地，前往更广阔的莫高雷时必须经历的一项基础性精神试炼。为了穿透帷幕并从先祖之灵那里获得指引，试炼者必须在血蹄村扎尔曼·双月的注视下，收集自然试剂来调制先知之水。",h="幻象之礼是牛头人年轻人离开红云台地，前往更广阔的莫高雷时必须经历的一项基础性精神试炼。为了穿透帷幕并从先祖之灵那里获得指引，试炼者必须在血蹄村扎尔曼·双月的注视下，收集自然试剂来调制先知之水。",kw={"琥珀玉米","血蹄村","大地母亲","莫高雷","幻象之礼","先知之水","水井石","扎尔曼·双月"},ang={["class:Druid"]="德鲁伊对琥珀玉米和水井石怀有深深的敬意，视它们为维持莫高雷平衡的植物群和生命之源的直接体现。",["class:Shaman"]="萨满会认出先知之水的调制是一种传统的稳固仪式，在与灵魂直接交流之前，先使精神能够感知到看不见的元素。",["race:Tauren"]="对于牛头人来说，幻象之礼是一个至关重要的文化里程碑，它将新晋的战士、猎人或秘法者与大地母亲和先祖的精神遗产紧密相连。"},sec={{t="大地的试剂",b="在获得任何幻象之前，试炼者必须展现出对散布在莫高雷各处的自然馈赠的深刻理解。扎尔曼·双月会指引寻求者收集神圣公用水井旁的水井石，以及落在莫高雷古树根部的琥珀玉米。这些自然元素不仅仅是物质，对于牛头人来说，它们蕴含着大地母亲的潜在魔力和生命之源，随时可以被引导用于仪式之中。"},{t="调制先知之水",b="收集齐之后，扎尔曼会将这些石头和琥珀玉米合成为强大的先知之水。在村庄的部落之火旁饮下这种仪式药剂后，思绪会变得清澈，并召唤出一名空灵的向导。跟随这道身影穿过平原是仪式的真正核心，它考验着试炼者在物质世界和大地精神低语之间行进的能力。"}},faq={{q="幻象之礼的目的是什么？",a="幻象之礼是一项针对Coming of Age且正在寻找道路的牛头人的精神测试。通过准备并饮下先知之水，试炼者学会了与灵魂交流，并跟随跨越莫高雷平原的先祖预兆前行。",al={"什么是幻象之礼","为什么要进行幻象之礼","幻象之礼的目的"}},{q="扎尔曼·双月是谁？",a="扎尔曼·双月是一位驻扎在血蹄村的牛头人萨满和先知。他负责监督年轻冒险者的精神试炼，准备诸如先知之水之类的仪式药剂，并解读大地母亲的迹象。",al={"扎尔曼是谁","扎尔曼·双月的职责","任务发布者扎尔曼"}},{q="在哪里可以找到水井石和琥珀玉米？",a="水井石可以在莫高雷各地散布的淡水水井旁的地面上收集到。琥珀玉米则散落在点缀着周围草地景观的大型蔓生树木的根部。",al={"去哪里找琥珀玉米","水井石位置","幻象之礼的试剂"}},{q="喝下先知之水后会发生什么？",a="在部落篝火旁饮下药剂会开启饮用者的灵视，显现出一名幽灵般的动物向导。寻求者必须跟随这个灵魂穿越平原，以揭开他们神圣旅程的下一阶段。",al={"幻象之礼下一步做什么","先知之水的效果","幻象任务后续"}},{q="为什么牛头人如此崇敬水井？",a="水是莫高雷的生命之源，也是大地母亲的珍贵馈赠。水井是神圣的公共中心，滋养着大地和兽群，这使得井边的石头充满了灵性。",al={"牛头人水井","为什么水井是神圣的","莫高雷的水"}},{q="这个任务会引出后续的仪式吗？",a="是的。这项任务是一个多阶段仪式的一部分。一旦扎尔曼调制好先知之水，试炼者必须饮下它，追踪出现的幻象，并向莫高雷各地的长者领袖报告。",al={"幻象之礼的下一个任务","幻象之礼是任务链吗","牛头人仪式任务链"}}},fx={["6b13f1a7"]={q="扎尔曼·双月为什么要你做这件事？",a="身为部族萨满，扎尔曼·双月有责任引导有潜力的年轻冒险者了解牛头人的神圣传统。他无法直接赐予你灵性智慧；你必须亲自参与仪式，亲手收集这片土地上的神圣元素，以此赢得大地母亲和先祖的眷顾。",al={"扎尔曼·双月的目的","扎尔曼为什么派你去","扎尔曼进行先知之水仪式的原因"}},cc7474fb={q="水井石有什么用？",a="水井石采自莫高雷各处的神圣水井。它们蕴含着大地母亲纯净泉水中的自然魔力，是扎尔曼·双月调制神秘的先知之水所需的关键材料之一。",al={"水井石的用途","为什么需要水井石","水井石的用法"}},["4efb8f2d"]={q="琥珀玉米有什么用？",a="琥珀玉米从莫高雷各处的参天树木上掉落，蕴含着这片土地植物的自然精华。它与水井石混合后，由扎尔曼·双月浸制，便能赋予先知之水所需的魔力，使你得以窥见先祖的景象。",al={"琥珀玉米的用途","琥珀玉米有什么用","为什么要找琥珀玉米"}},["761f0189"]={q="为什么要你收集材料，而不是扎尔曼·双月亲自去？",a="先知之水仪式是个人灵性成长的试炼，并非日常差事。要与灵魂交流，你必须亲自寻找大地赐予的自然恩泽，以此表明你敬重土地、与土地和谐共处。若由别人代为收集材料，便违背了这场试炼的神圣目的。",al={"为什么要我找琥珀玉米","扎尔曼为什么不自己收集水井石","为什么让我进行先知之水仪式"}}},fp="14,335,24.476.0,30.397.0,42.238.0,25.234.0,42.210.0,51.214.1,47.219.0,38.207.1"}
P.entries["quest:772"] = {n="幻象仪祭",s="幻象仪式是血蹄村年轻牛头人所进行的一项古老试炼的最高潮。通过在部落篝火旁饮用神圣的先知之水，试炼者能够召唤一位幽灵向导，指引他们走向命运。",h="幻象仪式是血蹄村年轻牛头人所进行的一项古老试炼的最高潮。通过在部落篝火旁饮用神圣的先知之水，试炼者能够召唤一位幽灵向导，指引他们走向命运。",kw={"血蹄村","幽灵狼","莫高雷","幻象仪式","先知奥萨迪·智慧行者","部落篝火","先知之水","扎尔曼·双月"},ang={["class:Druid"]="该仪式加强了对自然世界的敬畏，以及在动物形态指引面前的精神谦卑。",["class:Shaman"]="跟随先祖幽灵狼是行走于诸界之间的一门早期课程，它巩固了萨满与指引部落的灵魂之间的纽带。",["race:Tauren"]="对于年轻的牛头人来说，幻象仪式是一次神圣的成人礼，证明了他们与先祖的沟通以及对精神指引的服从。"},sec={{t="先知之水",b="在收集了必要的仪式草药并通过了最初的信仰试炼后，村庄萨满扎尔曼·双月会将先知之水赐予试炼者。这剂强力的药水必须在血蹄村中心那熊熊燃烧的部落篝火前饮用。当以专注且虔诚的心态饮用时，这神圣的水能够将饮用者的感知扩展到肉眼所见的范围之外，架起物质位面与精神领域之间的桥梁。"},{t="跟随幽灵狼",b="饮下药水后，火焰中会出现一个空灵的幻象：一只先祖幽灵狼。这灵体不会说话，也不会战斗，而是悄无声息地向西北方跑去，穿过莫高雷的草海平原。真正的试炼者必须留意它静谧的路径，追踪它远离村庄，深入岩石丘陵，那里，隐士先知奥萨迪·智慧行者正在潜心冥想。"},{t="智慧之旅",b="在山洞洞口找到先知奥萨迪·智慧行者，即标志着幻象试炼的成功完成。这段穿过草丘的旅程考验着试炼者的耐心、对先祖指引的信任以及与大地母亲的共鸣。通过这项仪式，年轻的冒险者将获得参加成人终极考验的资格：智慧仪式。"}},faq={{q="我喝下先知之水会发生什么？",a="在血蹄村的部落篝火旁饮用时，这种水会开启你的精神感知。饮用后不久，一只幽灵狼就会出现在火焰前方，指引你的道路。",al={"先知之水的作用原理","饮用先知之水","先知之水的效果"}},{q="灵魂向导会带我去哪儿？",a="幽灵狼会向西北方小跑出血蹄村，穿过莫高雷的丘陵，径直前往先知奥萨迪·智慧行者所居住的岩洞。",al={"幽灵狼去哪里","狼指引向谁","狼的目的地"}},{q="扎尔曼·双月是谁？",a="扎尔曼·双月是血蹄村一位著名的牛头人萨满，负责通过先祖仪式和神圣药剂帮助试炼者做好进入精神成年的准备。",al={"谁提供幻象仪式","扎尔曼·双月的职责"}},{q="先知奥萨迪·智慧行者是谁？",a="先知奥萨迪·智慧行者是一位年长的牛头人秘术师，在血蹄村西北方的悬崖中潜心冥想。跟随精神幻象的试炼者会找到他来完成试炼。",al={"先知奥萨迪·智慧行者是谁","莫高雷洞穴中的先知"}},{q="为什么必须在部落篝火旁饮用这种水？",a="部落篝火是血蹄村先祖之魂的神圣锚点。其受祝福的火焰与圣水相结合，使幻象得以在清醒的世界中显现。",al={"为什么要用部落篝火","篝火与幻象仪式"}},{q="幻象仪式之后是什么仪式？",a="在与先知奥萨迪·智慧行者完成幻象仪式后，试炼者将被指引去进行智慧仪式，这是他们在莫高雷早期旅程中的最后一次精神试炼。",al={"幻象仪式后的下一个任务","what comes next"}}},fx={["659b3713"]={q="扎尔曼·双月为什么要我进行先知之水仪式？",a="身为血蹄村的萨满，扎尔曼·双月引导年轻的牛头人踏上先祖的神圣道路。你已收集齐调制先知之水所需的材料，现在他将这剂药水交给你，让你亲自与灵魂交流、见证自己的幻象，并迈出下一步，在部族中探寻自己的命运。",al={"为什么要进行先知之水仪式","扎尔曼·双月的目的","先知之水仪式的目的"}},b8c8221c={q="为什么必须由我亲自进行这个仪式？",a="大地母亲的仪式是关乎成熟与灵性觉醒的个人试炼。没有守卫或长老能代你踏上灵魂之路；只有你自己的灵魂才能接受指引，发现自己在牛头人族群中的位置和使命。",al={"为什么必须由我进行仪式","为什么让我进行先知之水仪式","为什么不能让别人代替我进行仪式"}}},fp="14,249,22.467.0,24.371.0,16.362.0,49.192.0,36.150.0,25.171.0,23.189.0,49.197.0,41.173.0"}
P.entries["quest:7721"] = {n="压缩器的动力",s="在菲拉斯的被遗忘的海岸，索尔宾·范达瑟不顾劝阻开设了一家工程学商店，但当地的元素生物是个大麻烦。它们同时也是精炼“超级缩小器”的绝佳原始能量来源，而索尔宾想要的正是水元素核心。",h="在菲拉斯的被遗忘的海岸，索尔宾·范达瑟不顾劝阻开设了一家工程学商店，但当地的元素生物是个大麻烦。它们同时也是精炼“超级缩小器”的绝佳原始能量来源，而索尔宾想要的正是水元素核心。",kw={"菲拉斯","被遗忘的海岸","海元素","海浪","超级缩小器","水元素核心","索尔宾·范达瑟"},sec={{t="浪潮之力",b="索尔宾·范达瑟咒骂着元素魔法那不受控制的力量，并称海岸上的元素生物为害虫。但索尔宾同时也认为，它们是精炼“超级缩小器”时的绝佳原始能量来源。索尔宾要你去教训一下海岸上的海元素和海浪，收集它们的水元素核心，并带给码头边的索尔宾。"},{t="索尔宾的谢意",b="索尔宾非常高兴：这些核心足以维持一段时间的工作了，而且海岸上的元素生物也减少了。索尔宾补充说，把商店开在这个可能是世界上最糟糕的地方，让他每天晚上都想哭。索尔宾以酬金表达了谢意，尽管这让他的财政状况有些吃紧。"}},faq={{q="谁在索要水元素核心？",a="索尔宾·范达瑟，他在菲拉斯的被遗忘的海岸，靠近码头的地方开了一家工程学商店。",al={"谁发布了“浪潮之力”任务","索尔宾·范达瑟任务发布者","谁开启了“浪潮之力”"}},{q="索尔宾·范达瑟为什么需要水元素核心？",a="索尔宾认为当地的元素生物是精炼“超级缩小器”的绝佳原始能量来源，而他想要的正是水元素核心。",al={"为什么要水元素核心","核心有什么用","超级缩小器燃料"}},{q="从哪里收集这些元素核心？",a="索尔宾要你从游荡在菲拉斯被遗忘的海岸的海元素和海浪身上收集它们。",al={"哪里寻找核心","海元素位置","海浪在哪里"}}},fp="20,273,19.352.0,15.310.1,38.103.0,53.154.0,39.108.0"}
P.entries["quest:7722"] = {n="绝密配方！",s="大铁匠博恩奈特说，当马托里奥斯离开他们的氏族时，他带走了他们的炽热助熔剂配方，其价值远超一颗完美的奥术水晶。博恩奈特想要回这份秘密设计图，并确信它就在深入熔渣之池的马托里奥斯附近。",h="大铁匠博恩奈特说，当马托里奥斯离开他们的氏族时，他带走了他们的炽热助熔剂配方，其价值远超一颗完美的奥术水晶。博恩奈特想要回这份秘密设计图，并确信它就在深入熔渣之池的马托里奥斯附近。",kw={"博恩奈特","大熔炉","炽热助熔剂","马托里奥斯","设计图","灼热峡谷","熔渣之池"},sec={{t="失窃的配方",b="大铁匠博恩奈特称马托里奥斯是个叛徒，他带着炽热助熔剂的配方离开了氏族。博恩奈特敢打赌，这份配方一定随着马托里奥斯在黑铁矮人中的晋升一同被带走了，他想要回这份秘密设计图。"},{t="进入熔渣之池",b="博恩奈特确信设计图就在熔渣之池深处的马托里奥斯附近。博恩奈特想要带回的就是秘密设计图：炽热助熔剂。"}},faq={{q="是谁偷走了炽热助熔剂的配方？",a="马托里奥斯，大铁匠博恩奈特称他是氏族的叛徒。",al={"谁偷走了配方","谁拿走了设计图","炽热助熔剂叛徒"}},{q="秘密设计图在哪里？",a="博恩奈特相信它就在大熔炉的熔渣之池深处，靠近马托里奥斯的地方。",al={"设计图在哪里","秘密设计图：炽热助熔剂位置","去哪里寻找炽热助熔剂设计图"}},{q="是谁要求找回这些设计图？",a="是大铁匠博恩奈特，他想要回这些东西。",al={"谁发布了炽热助熔剂任务","炽热助熔剂任务发布者"}},{q="为什么这些设计图对博恩奈特很重要？",a="博恩奈特说，炽热助熔剂的配方价值远超一颗完美的奥术水晶，而且这是氏族自己的秘密。",al={"为什么炽热助熔剂很重要","炽热助熔剂配方的重要性"}}},fp="14,241,17.224.0,17.159.0,36.69.0,27.80.0,39.53.0,37.120.0"}
P.entries["quest:7723"] = {n="该死的手指头！",s="身处灼热峡谷的汉瑟尔·重拳由于手指浮肿，无法像以前那样挥舞拳头了。汉瑟尔请你去替他教训那些重型战争傀儡。",h="身处灼热峡谷的汉瑟尔·重拳由于手指浮肿，无法像以前那样挥舞拳头了。汉瑟尔请你去替他教训那些重型战争傀儡。",kw={"大熔炉","浮肿的手指","汉瑟尔·重拳","重型战争傀儡","灼热峡谷","塞尔萨玛血肠"},sec={{t="像香肠一样的手指",b="汉瑟尔·重拳说，峡谷的气候和稀薄的空气让他的手指肿胀起来，看起来就像巨大的塞尔萨玛血肠。结果，汉瑟尔无法像以前那样施展拳脚，只能请你代劳处理他的事务。"},{t="名单上的第一位",b="汉瑟尔议程上的第一项任务是那些峡谷里的重型战争傀儡，他要求你狠狠地教训它们。你需要摧毁二十个。它们在大熔炉周围游荡，等你消灭了足够多的傀儡后，再回到汉瑟尔那里。"}},faq={{q="谁是汉瑟尔·重拳？",a="一个身处灼热峡谷的人，由于手指浮肿无法继续战斗，所以他请你去替他打架。",al={"汉瑟尔·重拳","谁给予了该死的手指任务","谁是任务给予者"}},{q="为什么汉瑟尔不能亲自对付傀儡？",a="汉瑟尔认为是峡谷的气候和稀薄的空气导致了他的手指肿胀，他形容那肿胀的手指就像巨大的塞尔萨玛血肠。",al={"为什么汉瑟尔的手指会肿","手指浮肿背景故事","汉瑟尔浮肿的手"}},{q="需要对付哪些敌人？",a="二十个重型战争傀儡。",al={"我需要对付什么敌人","汉瑟尔想要消灭什么"}},{q="重型战争傀儡在哪里？",a="它们在大熔炉周围游荡，位于灼热峡谷内。",al={"傀儡在哪里","重型战争傀儡位置"}}},fp="23,169,21.266.0,17.223.0,25.111.0,47.134.0,29.24.0,39.62.0"}
P.entries["quest:7724"] = {n="熔岩蜘蛛的威胁！",s="汉瑟尔·重拳说，每当他想要片刻放松并反思自己的人生时，那些当权者就会派给他新的工作。大型熔岩蜘蛛在灼热峡谷制造了许多混乱，他想让你去杀掉二十只。",h="汉瑟尔·重拳说，每当他想要片刻放松并反思自己的人生时，那些当权者就会派给他新的工作。大型熔岩蜘蛛在灼热峡谷制造了许多混乱，他想让你去杀掉二十只。",kw={"烈焰威胁","大型熔岩蜘蛛","汉瑟尔·重拳","oilfist","灼热峡谷","蜘蛛"},sec={{t="汉瑟尔的又一项工作",b="汉瑟尔·重拳抱怨说，当权者从来不让他清静。大型熔岩蜘蛛正在制造混乱，他宁愿由你来动手而不是他自己。"},{t="大型熔岩蜘蛛",b="Oilfist说这些蜘蛛从一个尴尬的地方喷出火焰，这让孩子们感到不安。汉瑟尔想要猎杀二十只大型熔岩蜘蛛，它们可以在灼热峡谷的高原和熔岩池边找到。"}},faq={{q="是谁派你去对付蜘蛛的？",a="在灼热峡谷的汉瑟尔·重拳，他本希望有一段安静的时光，却被派了又一项工作。",al={"任务发布者","谁发布任务","汉瑟尔"}},{q="为什么要杀死这些蜘蛛？",a="大型熔岩蜘蛛在制造混乱，而且Oilfist说它们喷火的方式让孩子们感到不安。",al={"为什么要杀蜘蛛","蜘蛛做了什么","蜘蛛问题"}},{q="是谁告诉汉瑟尔关于蜘蛛的事的？",a="Oilfist，他说这些蜘蛛从一个尴尬的地方喷出火焰。",al={"谁抱怨了蜘蛛","oilfist"}},{q="必须杀死多少只大型熔岩蜘蛛？",a="汉瑟尔要求除掉二十只。",al={"多少只蜘蛛","蜘蛛数量"}}},fp="13,236,22.170.0,24.214.0,32.101.0,37.104.0,34.63.0,45.38.0"}
P.entries["quest:7725"] = {n="更多被缩小的巨人！",s="索尔宾·范达瑟知道你已经收集过残渣了，但他总是还需要更多。你可以再次使用索尔宾的超级压缩器去对付菲拉斯的巨人，索尔宾会在被遗忘的海岸码头等你。索尔宾这次没法给你太多的报酬，但他承诺会为你宣扬你的功绩。",h="索尔宾·范达瑟知道你已经收集过残渣了，但他总是还需要更多。你可以再次使用索尔宾的超级压缩器去对付菲拉斯的巨人，索尔宾会在被遗忘的海岸码头等你。索尔宾这次没法给你太多的报酬，但他承诺会为你宣扬你的功绩。",kw={"菲拉斯","被遗忘的海岸","巨人","微缩残渣","热砂港","超级压缩器","索尔宾·范达瑟"},sec={{t="超级压缩器的再演",b="索尔宾·范达瑟承认你已经收集过残渣，但称这次为再演，并说总是还需要更多。索尔宾请求你再次用索尔宾的超级压缩器去压缩菲拉斯的巨人，并将十份从被缩小的巨人身上得到的微缩残渣带到被遗忘的海岸码头。因为索尔宾无法提供太多的回报，他提议在他的地精朋友们中宣扬你的功绩，他们可是有很多双顺风耳呢。"},{t="索尔宾的感谢",b="索尔宾很高兴你能再次成功完成任务，即使报酬比你往常得到的要少。索尔宾坚持说，关于你为地精做出的伟大贡献的消息，已经在热砂港的权力核心中传开了。"}},faq={{q="谁需要更多的残渣？",a="索尔宾·范达瑟，他正在菲拉斯的被遗忘的海岸码头等你。",al={"任务发布者","索尔宾位置","谁发布了再次电击巨人"}},{q="之前发生了什么？",a="这是在“电击巨人”之后，即你为索尔宾·范达瑟进行的第一次残渣收集。",al={"前置条件","前置任务","我先做什么"}},{q="如何收集残渣？",a="对菲拉斯的任何一种巨人使用索尔宾的超级压缩器来将其缩小，然后就能在这些被缩小的巨人身上找到残渣。",al={"如何获取残渣","微缩残渣","如何缩小巨人"}},{q="在哪里可以找到巨人？",a="这些巨人分布在菲拉斯的西海岸。",al={"巨人位置","菲拉斯巨人在哪里","被遗忘的海岸巨人"}},{q="索尔宾以后还会要更多的残渣吗？",a="索尔宾说他永远需要更多的残渣，所以欢迎你再带十份回来。",al={"这是可重复任务吗","我可以重复再次电击巨人吗","可重复的巨人任务"}}},fp="28,289,32.448.0,15.232.1,26.68.0,22.85.0,28.128.0,27.56.0,43.103.0"}
P.entries["quest:7726"] = {n="补充动力",s="索尔宾·范达瑟需要更多的水元素之核。在被遗忘的海岸开设店铺十分困难，所以报酬会少一些，但索尔宾承诺会将你的帮助告诉周围的每一个人，并说热砂港里也有他的朋友。",h="索尔宾·范达瑟需要更多的水元素之核。在被遗忘的海岸开设店铺十分困难，所以报酬会少一些，但索尔宾承诺会将你的帮助告诉周围的每一个人，并说热砂港里也有他的朋友。",kw={"菲拉斯","被遗忘的海岸","海元素","海浪","热砂港","水元素之核","索尔宾·范达瑟"},sec={{t="如出一辙",b="索尔宾·范达瑟开玩笑说，从元素生物体内收集粘液这种英雄壮举，不知道你是不是想再来一次。抛开这些戏剧性的言论不谈，索尔宾确实需要更多的水元素之核。在这里建立店铺是一项孤注一掷的生意，所以能提供的报酬很少，但索尔宾承诺会告诉周围每一个能听到的人你是如何提供帮助的，并说你可以相信这一点，因为索尔宾在热砂港里认识不少人。需要六个核心，从被遗忘的海岸的海元素和海浪身上获取，并带给码头附近的索尔宾。"},{t="索尔宾的感谢",b="索尔宾很高兴，并承认这笔钱可能不是你从事此类工作所能获得的最丰厚的报酬。索尔宾在热砂港的同伴会知道你的努力，如果你还想找点事做，索尔宾还需要更多的核心和类似的东西。"}},faq={{q="是谁在请求水元素之核？",a="索尔宾·范达瑟，他在菲拉斯的被遗忘的海岸码头边。",al={"谁给予这个任务","索尔宾·范达瑟是谁","索尔宾在哪里"}},{q="水元素之核来自哪里？",a="它们是从菲拉斯被遗忘的海岸的海元素和海浪身上获取的。",al={"核心在哪里掉落","水元素之核位置","哪些敌人掉落核心"}},{q="为什么索尔宾·范达瑟需要更多的核心？",a="索尔宾只说需要更多的水元素之核，因为他在海岸建立店铺的过程举步维艰。",al={"为什么索尔宾想要核心","索尔宾·范达瑟的目的","核心是用来做什么的"}},{q="在此之前发生了什么？",a="这是“为充能提供燃料”的后续任务，当时你第一次为索尔宾收集了元素之核。",al={"之前的任务","前置任务","哪个任务在前"}}},fp="22,235,16.548.0,15.260.1,44.70.0,45.84.0,42.117.0,22.84.0"}
P.entries["quest:7727"] = {n="熏火龙",s="汉瑟尔·重拳说他的脚趾囊肿上又长了囊肿，以他现在这副糟糕的脚部状况根本无法去杀怪。斯克兰吉和伯纳特让他去清理熔渣之池里的灼热龙，所以他便打发你去杀掉二十只。",h="汉瑟尔·重拳说他的脚趾囊肿上又长了囊肿，以他现在这副糟糕的脚部状况根本无法去杀怪。斯克兰吉和伯纳特让他去清理熔渣之池里的灼热龙，所以他便打发你去杀掉二十只。",kw={"伯纳特","大熔炉","汉瑟尔·重拳","灼热龙","斯克兰吉","灼热峡谷","熔渣之池"},sec={{t="囊肿上的囊肿",b="汉瑟尔·重拳现在的状态根本无法战斗。斯克兰吉和伯纳特让他去杀掉灼热龙，以便考察队能够进入熔渣之池的熔岩池进行探索。汉瑟尔把这项工作推给了你。"},{t="熔岩池",b="灼热龙占据了大熔炉内熔渣之池的熔岩池。汉瑟尔要你杀掉二十只，在你完成任务之前他不想见到你。"}},faq={{q="汉瑟尔·重拳是谁？",a="他是在灼热峡谷给你指派这项任务的人。斯克兰吉和伯纳特让他去对付灼热龙，但他因为脚上的囊肿而无法行动。",al={"汉瑟尔·重拳","任务发布者是谁","谁给的任务"}},{q="为什么要清理掉灼热龙？",a="斯克兰吉和伯纳特需要考察队去探索熔渣之池的熔岩池。据说在那里的灼热龙制造了各种各样的麻烦。",al={"为什么要杀灼热龙","灼热龙的作用","为什么要清理熔渣之池"}},{q="在哪里能找到灼热龙？",a="在大熔炉内，熔渣之池的熔岩池里。",al={"灼热龙的位置","熔渣之池在哪里","熔岩池在哪里"}},{q="为什么汉瑟尔不亲自去狩猎它们？",a="他说他的脚趾囊肿上长了囊肿，他的脚太糟糕了，根本没法杀怪。",al={"为什么汉瑟尔不战斗","汉瑟尔的脚","汉瑟尔的囊肿"}}},fp="43,227,20.221.0,14.166.0,25.152.0,47.154.0,33.60.0,35.89.0"}
P.entries["quest:7728"] = {n="被盗：鼓风机和望远镜",s="一则通告列出了两件被盗物品：一个黑铁冶炼鼓风机和一副侦查员的望远镜。瑟银兄弟会确信是灼热峡谷中那些肆无忌惮、心怀嫉妒的黑铁矮人偷走了它们，无论谁找到这些物品，都应将其交给监工斯克兰格以换取报酬。",h="一则通告列出了两件被盗物品：一个黑铁冶炼鼓风机和一副侦查员的望远镜。瑟银兄弟会确信是灼热峡谷中那些肆无忌惮、心怀嫉妒的黑铁矮人偷走了它们，无论谁找到这些物品，都应将其交给监工斯克兰格以换取报酬。",kw={"黑铁","斯克兰格","灼热峡谷","冶炼","望远镜","瑟银兄弟会","鼓风机"},sec={{t="被盗货物",b="通告称这副望远镜是侦查员的精良工具，而那个鼓风机则是不可替代的冶炼工具。目前唯一确定的是黑铁矮人肯定偷走了它们。无论谁找到这些物品，都应将其归还给监工斯克兰格。"}},faq={{q="谁张贴了这份通告？",a="这份通告提到了瑟银兄弟会，他们确信是黑铁矮人偷走了这些物品。",al={"谁想要这些被盗物品","谁发布了这个任务","被盗冶炼鼓风机任务发布者"}},{q="谁偷走了这些工具？",a="瑟银兄弟会确信是灼热峡谷中那些肆无忌惮、心怀嫉妒的黑铁矮人所为。",al={"谁拿走了鼓风机","谁偷走了望远镜","谁持有这些被盗物品"}},{q="谁负责接收找回的物品？",a="灼热峡谷的监工斯克兰格。",al={"我在哪里提交任务","监工斯克兰格是谁","谁要收回望远镜"}},{q="这些被盗物品有什么用途？",a="鼓风机是一种不可替代的冶炼工具，而望远镜则是侦查员所用的贵重监控工具。",al={"什么是冶炼鼓风机","为什么兄弟会想要那个鼓风机","望远镜有什么用"}}},fp="46,258,12.236.0,22.100.0,20.106.0,33.40.0,30.115.0"}
P.entries["quest:7729"] = {n="工作机会：肃清竞争对手",s="一则告示宣布监工斯克兰格需要一些能干的人手去灼热峡谷清除竞争对手。工作内容是屠杀黑铁监工和黑铁奴役者，直到你的衣服被血染透，然后回到斯克兰格那里。",h="一则告示宣布监工斯克兰格需要一些能干的人手去灼热峡谷清除竞争对手。工作内容是屠杀黑铁监工和黑铁奴役者，直到你的衣服被血染透，然后回到斯克兰格那里。",kw={"清除竞争对手","黑铁奴役者","黑铁监工","工作机会","灼热峡谷","监工斯克兰格"},sec={{t="一个空缺职位",b="斯克兰格希望应聘者前往峡谷，屠杀他们遇到的黑铁监工和黑铁奴役者：各十五名。等你衣服上的血迹足够多时再回来。到时候你自然会知道，别问那么多。"}},faq={{q="谁提供了这份工作？",a="灼热峡谷的监工斯克兰格，他需要人手帮他清除竞争对手。",al={"谁提供这个任务","谁想要杀死监工","监工斯克兰格是谁"}},{q="必须杀死哪些敌人？",a="十五名黑铁监工和十五名黑铁奴役者。",al={"我要杀什么","工作机会的目标","谁是竞争对手"}},{q="斯克兰格如何判断工作已完成？",a="看你衣服的状态。斯克兰格会通过称量你穿衣和脱衣后的体重来确认。",al={"如何证明杀敌","血衣要求","斯克兰格如何检查"}}},fp="40,242,16.243.0,25.80.0,28.60.0,39.86.0"}
P.entries["quest:773"] = {n="智慧仪祭",s="智慧试炼是莫高雷的年轻冒险者们所要进行的传统大地母亲试炼中的最后一项。在通过幻象试炼净化了视界之后，祈求者会前往赤色石的神圣墓地，与一位先祖之魂进行沟通，并接受逝者的祝福。",h="智慧试炼是莫高雷的年轻冒险者们所要进行的传统大地母亲试炼中的最后一项。在通过幻象试炼净化了视界之后，祈求者会前往赤色石的神圣墓地，与一位先祖之魂进行沟通，并接受逝者的祝福。",kw={"先祖之魂","莫高雷","赤色石","智慧试炼","大地母亲试炼","先知奥萨迪·智慧行者","雷霆崖","先知之水"},ang={["class:Druid"]="这项试炼展示了生者世界与大地母亲所监管的永恒轮回之间的平衡，使年轻的德鲁伊们扎根于他们对这片土地的职责之中。",["class:Shaman"]="直接与先祖之魂进行沟通，强化了萨满祭司的核心职责，即尊崇逝者并坚守与守护莫高雷的灵魂之间的信仰。",["race:Tauren"]="对于舒哈鲁来说，在赤色石接受先祖赋予的传承重任，是迈向完全成年并被部落长者接纳的关键时刻。"},sec={{t="赤色石试炼",b="在通过幻象试炼清除了视界障碍后，年轻的保卫者们会被指引前往雷霆崖以东的赤色石。这片古老的墓地安葬着那些为了在莫高雷开辟和平家园而浴血奋战并牺牲者的遗骸，也留存着他们的灵魂。通过这项试炼需要以足够的敬意与沟通接近这些安息之所，并直面徘徊在山丘间的任何领地威胁，以寻求受人尊敬的先贤的指引。"},{t="传承重任",b="在赤色石之巅，与先祖之魂的沟通并非是对武力的考验，而是对精神准备和传承性的检验。安息在那里的灵魂代表着曾经与凯恩·血蹄并肩作战，建立雷霆崖并保卫部落的那一代先祖。通过接受他们的祝福，祈求者正式继承了守卫这座城市的庄严职责，从而赢得了作为一名被认可的成年人和保卫者的地位，可以自豪地进入雷霆崖。"}},faq={{q="智慧试炼的目的是什么？",a="智慧试炼完成了大地母亲试炼，将青年时代的幻象沟通与成年后的庄严责任连接了起来。通过获得先祖之魂的祝福，祈求者证明了他们尊重先辈的牺牲，并已做好保卫雷霆崖的准备。",al={"为什么进行智慧试炼","智慧试炼的作用","智慧试炼的目的"}},{q="是谁指引你进行智慧试炼的？",a="先知奥萨迪·智慧行者位于血蹄村西北方的洞穴中，他会指引那些成功完成幻象试炼并饮用了先知之水的初学者们进行这项试炼。",al={"谁提供智慧试炼","如何开始智慧试炼"}},{q="在哪里可以找到先祖之魂？",a="先祖之魂位于赤色石，那是一片坐落在雷霆崖正东方岩石峭壁中的古老牛头人墓地。",al={"先祖之魂的位置","灵魂在哪里","去哪里寻找先祖之魂"}},{q="为什么必须先进行幻象试炼？",a="只有那些饮用了先知之水并净化了灵视的人，才能感知并接受赤色石处古老灵魂的祝福。",al={"为什么先做幻象试炼","幻象试炼前提条件","先知之水要求"}},{q="完成智慧试炼后会发生什么？",a="在获得了先祖的认可后，初学者们会被指示正式踏上进入雷霆崖高地的旅程。",al={"完成智慧试炼后做什么","智慧试炼后的后续任务"}},{q="哪些生物威胁着赤色石的安宁？",a="赤色石的神圣墓地遭到了具有攻击性的苍鬃豺狼人的侵扰，它们潜伏在通往这处古老墓葬区的岩石小径上。",al={"赤色石的敌人","什么在守卫赤色石","赤色石的豺狼人"}}},fx={["740e2883"]={q="先知奥萨迪·智慧行者为何派你执行智慧仪式？",a="先知奥萨迪·智慧行者引导有前途的年轻牛头人完成大地母亲的传统仪式。他见你承受住了先知之水带来的幻象，便指引你前往赤色石，接受先祖的祝福。对智慧行者和长老们而言，这一仪式确保只有在精神上做好准备、并得到先祖认可的人，才能作为部族的守护者进入雷霆崖。",al={"先知奥萨迪·智慧行者的目的","为什么要进行智慧仪式","为什么派我执行智慧仪式"}},["8728f84f"]={q="为什么先知奥萨迪·智慧行者要你去，而不是亲自前往？",al={"为什么是我执行智慧仪式","先知奥萨迪·智慧行者为什么不亲自去","为什么要我寻找先祖之魂"}}},fp="14,321,22.468.0,18.492.0,42.310.0,36.186.0,39.137.0,41.175.0,49.138.0,49.160.0"}
P.entries["quest:7730"] = {n="祖卡什的入侵",s="在莫沙彻营地，哈杜肯·迅蹄听闻在豺狼人南面出现了一些昆虫般的生物：祖卡什。如果正是它们在煽动豺狼人发狂，那么它们构成的威胁丝毫不亚于豺狼人，甚至可能更严重。你被派往它们的老巢——痛苦深渊，去削减它们的数量并带回二十个甲壳。",h="在莫沙彻营地，哈杜肯·迅蹄听闻在豺狼人南面出现了一些昆虫般的生物：祖卡什。如果正是它们在煽动豺狼人发狂，那么它们构成的威胁丝毫不亚于豺狼人，甚至可能更严重。你被派往它们的老巢——痛苦深渊，去削减它们的数量并带回二十个甲壳...",kw={"莫沙彻营地","甲壳","菲拉斯","豺狼人","哈杜肯·迅蹄","昆虫","痛苦深渊","祖卡什"},sec={{t="豺狼人南面的敌人",b="哈杜肯·迅蹄认为，在豺狼人南面的敌人是一群昆虫般的生物。至于它们是否拥有智慧，哈杜肯并不关心。如果正是它们在驱使豺狼人疯狂攻击莫沙彻营地，那么它们构成的威胁就和豺狼人一样大，甚至更大。你必须深入它们居住的地方，也就是痛苦深渊，削减它们的数量。二十个祖卡什的甲壳将作为你的战果证明，哈杜肯还想听听你的发现。"},{t="哈杜肯的结论",b="当你回来时，哈杜肯感到很高兴。如果不进行全面的入侵，祖卡什的威胁将无法根除，但你已经为营地争取到了制定适当策略的时间。这些甲壳将被送去分析，因为营地必须了解关于这些生物的一切。不幸的是，这已经变成了一个比任何人预想中都要严重得多的问题。"}},faq={{q="是谁派你去对付祖卡什的？",a="菲拉斯莫沙彻营地的哈杜肯·迅蹄。",al={"任务发布者","哈杜肯·迅蹄","谁开启了祖卡什的侵扰"}},{q="祖卡什是什么？",a="哈杜肯认为它们是位于豺狼人南面的一群昆虫般的生物。至于它们是否拥有智慧，这对哈杜肯来说并不重要，重要的是它们可能正在驱使豺狼人发狂。",al={"什么是祖卡什","祖卡什昆虫","痛苦深渊虫子"}},{q="痛苦深渊在哪里？",a="那是祖卡什昆虫居住的地方，位于豺狼人南面。",al={"痛苦深渊位置","痛苦深渊在哪里","虫子在哪里"}},{q="为什么哈杜肯需要祖卡什的甲壳？",a="哈杜肯需要这些甲壳作为你对付祖卡什的战果证明。",al={"为什么需要甲壳","祖卡什甲壳的用途","甲壳的用途"}}},fp="20,317,27.474.0,17.347.1,33.49.0,22.185.0,27.60.0,41.79.0"}
P.entries["quest:7731"] = {n="毒刺鞭笞者",s="在勘察痛苦深渊时，哈杜肯·迅蹄的一名侦察兵发现了一只巨型昆虫，它远比其他的昆虫巨大，在扭曲的地形中游荡。这只怪兽被命名为毒刺鞭笞者，哈杜肯希望你能除掉它，并将它的分泌腺带回莫沙彻营地。",h="在勘察痛苦深渊时，哈杜肯·迅蹄的一名侦察兵发现了一只巨型昆虫，它远比其他的昆虫巨大，在扭曲的地形中游荡。这只怪兽被命名为毒刺鞭笞者，哈杜肯希望你能除掉它，并将它的分泌腺带回莫沙彻营地。",kw={"莫沙彻营地","菲拉斯","腺体","哈杜肯·迅蹄","昆虫","毒刺鞭笞者","痛苦深渊","祖卡什"},sec={{t="虫群中的巨人",b="痛苦深渊里的一名侦察兵看到了一只远比其他昆虫巨大的怪兽，正在扭曲的地形中徘徊。它似乎还散发出一种与其他昆虫截然不同的光环。它被命名为毒刺鞭笞者。在哈杜肯设法应对这一新威胁时，研究它的内脏将非常有价值，因此哈杜肯希望你能切下它的分泌腺，并直接带到莫沙彻营地。"},{t="哈杜肯的感谢",b="哈杜肯印象深刻。如果毒刺鞭笞者确实是这些昆虫中最强大的存在之一，那么研究这头野兽终将证明其价值。哈杜肯的任务是确保营地能够坚持足够长的时间以从中获益。作为全营地的谢意，他为你准备了一笔赏金。"}},faq={{q="是谁派你去对付毒刺鞭笞者的？",a="哈杜肯·迅蹄，位于菲拉斯的莫沙彻营地。",al={"任务发布者","谁发布毒刺鞭笞者任务","哈杜肯·迅蹄"}},{q="毒刺鞭笞者在哪里？",a="毒刺鞭笞者在痛苦深渊的扭曲地形中游荡。",al={"毒刺鞭笞者位置","毒刺鞭笞者在哪里","痛苦深渊位置"}},{q="毒刺鞭笞者与其他昆虫有什么不同？",a="一名侦察兵报告说发现了一只体型巨大的昆虫，而且它似乎散发出一种其他昆虫所没有的光环。",al={"为什么要杀毒刺鞭笞者","毒刺鞭笞者是什么","毒刺鞭笞者光环"}},{q="为什么哈杜肯想要毒刺鞭笞者的腺体？",a="哈杜肯说，在制定应对这一新威胁的计划时，研究它的内脏将是无价之宝。",al={"为什么要收集腺体","毒刺鞭笞者腺体用途"}}},fp="11,274,25.401.0,16.278.1,32.49.0,27.68.0,56.89.0,43.105.0"}
P.entries["quest:7732"] = {n="祖卡什报告",s="哈杜肯·迅蹄说你在对抗威胁莫沙彻营地的祖卡什虫群时表现得非常出色，但危险远未结束。为部落再帮最后一个忙：将记录了关于祖卡什虫群所有情报的文件带到奥格瑞玛，交给基尔兹宾·鼓眼。",h="哈杜肯·迅蹄说你在对抗威胁莫沙彻营地的祖卡什虫群时表现得非常出色，但危险远未结束。为部落再帮最后一个忙：将记录了关于祖卡什虫群所有情报的文件带到奥格瑞玛，交给基尔兹宾·鼓眼。",kw={"莫沙彻营地","力量谷","菲拉斯","哈杜肯·迅蹄","奥格瑞玛","其拉虫人","基尔兹宾·鼓眼","祖卡什报告"},sec={{t="送往力量谷的文件",b="哈杜彻·迅蹄手里有一份文件，记录了营地对祖卡什虫群的所有了解。它们构成的威胁远未结束，哈杜肯请求你把它带到奥格瑞玛。在那里的力量谷住着基尔兹宾·鼓眼，他是这类外来生物的专家，哈杜肯希望目前收集到的情报能发挥作用。"},{t="专家的结论",b="基尔兹宾一直在等待这份报告。他称你面对的生物是一种古老的威胁，而部落却一直选择忽视它，他说哈杜肯明智地同时送来了报告和你本人。祖卡什虫群不过是被称为其拉虫人的生物而已。有些人认为它们只是无脑的害虫，但基尔兹宾向你保证，它们比联盟可能集结的任何威胁都要可怕得多。"}},faq={{q="谁把报告送往奥格瑞玛？",a="位于菲拉斯莫沙彻营地的哈杜肯·迅蹄交给你这份文件。",al={"谁给出了祖卡什报告","谁开启祖卡什报告","任务发布者"}},{q="报告送交的对象是谁？",a="送交给住在奥格瑞玛力量谷的基尔兹宾·鼓眼。",al={"报告送到哪里","谁收到祖卡什报告","鼓眼的位置"}},{q="为什么要把这份文件送到奥格瑞玛？",a="基尔兹宾·鼓眼是像祖卡什这样的外来生物的专家，哈杜肯希望营地收集到的情报能派上用场。",al={"为什么要送往奥格瑞玛","报告的目的"}},{q="在此次交付之前发生了什么？",a="这发生在你对抗祖卡什虫群的努力之后，具体是在任务“祖卡什虫害”和“刺鞭虫”之后。",al={"之前的任务","前置条件"}}},fp="15,267,23.347.0,20.377.1,34.71.0,32.59.0,39.142.0,31.94.0"}
P.entries["quest:7733"] = {n="更高的品质",s="普拉特·马克格鲁比听说了一种比上次更好的兽皮。在菲拉斯的北部，怒痕堡内游荡着另一群雪人，它们比你之前面对的那些更强壮。羽月要塞需要十张它们的皮。",h="普拉特·马克格鲁比听说了一种比上次更好的兽皮。在菲拉斯的北部，怒痕堡内游荡着另一群雪人，它们比你之前面对的那些更强壮。羽月要塞需要十张它们的皮。",kw={"羽月要塞","菲拉斯","改进的品质","普拉特·马克格鲁比","怒痕堡","瑟银","雪人皮","雪人"},sec={{t="更强壮的雪人群",b="在完成“品质的证明”之后，普拉特·马克格鲁比找到了一条关于品质更优的兽皮的线索。在菲拉斯的北部，怒痕堡内居住着另一群雪人，它们比你之前面对的那些更加强壮。普拉特·马克格鲁比愿意花重金收购十张它们的皮，带回羽月要塞即可完成这笔交易。如果它们的品质能与怒痕兽皮相媲美，那它们将拥有像瑟银一样坚韧的特质。"},{t="普拉特的感谢",b="这些兽皮甚至比预想的还要好。普拉特·马克格鲁比已经看出，经过适当的鞣制，它们会变得非常坚硬，并把其中一件最新的成品作为谢礼交给你。"}},faq={{q="谁需要怒痕雪人的皮？",a="位于菲拉斯羽月要塞的普拉特·马克格鲁比。",al={"谁给予改进的品质任务","改进的品质任务发布者","普拉特·马克格鲁比"}},{q="怒痕雪人居住在哪里？",a="在菲拉斯北部的怒痕堡内。",al={"怒痕雪人位置","怒痕堡在哪里","去哪里获取怒痕兽皮"}},{q="需要多少张兽皮？",a="普拉特·马克格鲁比需要十张怒痕雪人皮。",al={"多少张雪人皮","改进的品质所需物品"}},{q="在此之前的任务是什么？",a="这是“品质的证明”后续任务，你之前已经处理了第一群雪人。",al={"前置任务","什么任务引导至改进的品质","上一个任务"}}},fp="16,238,25.430.0,14.171.1,38.54.0,34.47.0,26.47.0,22.78.0"}
P.entries["quest:7734"] = {n="更高的品质",s="杉多尔·迅蹄听说有一种比上一次更好的皮料。在菲拉斯的北部，怒痕堡里，漫游着另一群雪人，它们比你之前面对的那些更强壮。莫沙彻营地需要十张它们的皮。",h="杉多尔·迅蹄听说有一种比上一次更好的皮料。在菲拉斯的北部，怒痕堡里，漫游着另一群雪人，它们比你之前面对的那些更强壮。莫沙彻营地需要十张它们的皮。",kw={"莫沙彻营地","菲拉斯","改进的品质","杉多尔·迅蹄","怒痕堡","怒痕雪人","雪人皮"},sec={{t="更强的雪人群",b="在完成“品质的标志”后，杉多尔·迅蹄找到了一条关于品质更好的皮料的线索。在菲拉斯的北部，怒痕堡里生活着另一群雪人，它们比你之前面对的那些更强壮。如果你能把十张它们的皮带回莫沙彻营地，杉多尔·迅蹄将给你丰厚的报酬。如果它们的品质能达到菲拉斯伤痕皮的水平，它们可能和瑟银一样坚韧。"},{t="杉多尔的谢意",b="这些皮料比预想的还要好。杉多尔·迅蹄敢肯定，经过适当的处理，它们会变得非常坚硬。为了表示感谢，他交给你一件最新的成品。"}},faq={{q="谁需要怒痕雪人的皮？",a="位于菲拉斯莫沙彻营地的杉多尔·迅蹄。",al={"谁给予改进的品质任务","改进的品质任务发布者","杉多尔·迅蹄"}},{q="怒痕雪人生活在哪里？",a="在菲拉斯北部的怒痕堡内。",al={"怒痕雪人位置","怒痕堡在哪里","在哪里获取怒痕皮"}},{q="需要多少张皮？",a="杉多尔·迅蹄需要十张怒痕雪人皮。",al={"需要多少雪人皮","改进的品质所需物品"}},{q="在此之前发生了什么？",a="这是在“品质的标志”之后，当时你处理了第一批雪人。",al={"前置任务","什么任务引导至改进的品质","上一个任务"}}},fp="16,233,25.430.0,16.176.1,38.49.0,34.47.0,26.52.0,22.78.0"}
P.entries["quest:7735"] = {n="原始雪人毛皮",s="你获得了一张异常厚实坚韧的雪人皮，甚至比你在愤怒伤痕的雪人身上见过的任何皮毛都要结实。羽月要塞的普拉特·马克格鲁比正在寻找雪人皮，这张皮他可能会感兴趣。",h="你获得了一张异常厚实坚韧的雪人皮，甚至比你在愤怒伤痕的雪人身上见过的任何皮毛都要结实。羽月要塞的普拉特·马克格鲁比正在寻找雪人皮，这张皮他可能会感兴趣。",kw={"羽月要塞","菲拉斯","普拉特·马克格鲁比","完好的雪人皮","愤怒伤痕","雪人皮"},sec={{t="非同一般的皮毛",b="这张皮毛保存完好，显然比从愤怒伤痕的雪人身上剥下的皮毛更厚、更结实。位于菲拉斯羽月要塞的普拉特·马克格鲁比想要收购雪人皮，所以这张皮值得你带给他。"},{t="普拉特的反应",b="普拉特感到十分惊讶，并大声感叹这是否就是世间最棒的雪人皮。普拉特会为你支付报酬，这比通常的雪人皮价格要高得多，他认为可以用它制作出特别的东西。"}},faq={{q="谁想要这张完好的雪人皮？",a="位于菲拉斯羽月要塞的普拉特·马克格鲁比，他正在收购雪人皮。",al={"谁收购完好的雪人皮","我该把雪人皮带去哪里","普拉特·马克格鲁比 雪人皮"}},{q="这张皮有什么特别之处？",a="它异常厚实坚韧，甚至超过了来自愤怒伤痕的雪人皮。",al={"完好的雪人皮来源","这张皮有何特别之处","菲拉斯 雪人皮"}},{q="普拉特·马克格鲁比在哪里？",a="在菲拉斯的羽月要塞。",al={"普拉特·马克格鲁比在哪里","把完好的雪人皮交给谁"}}},fp="18,230,26.223.0,16.201.1,33.87.0,29.89.0,25.37.0"}
P.entries["quest:7736"] = {n="炽热助熔剂的补给：皇血草",s="在完成“这是什么助熔剂？”之后，大铁匠博恩奈特转而着手补充灼热峡谷中日益短缺的炽热助熔剂储备。博恩奈特需要火炎龙鳞、皇血草和煤炭，而且多多益善。",h="在完成“这是什么助熔剂？”之后，大铁匠博恩奈特转而着手补充灼热峡谷中日益短缺的炽热助熔剂储备。博恩奈特需要火炎龙鳞、皇血草和煤炭，而且多多益善。",kw={"博恩奈特","煤炭","炽热助熔剂","火炎龙","皇血草","灼热峡谷","瑟银兄弟会"},sec={{t="急需炽热助熔剂",b="大铁匠博恩奈特没时间闲聊。炽热助熔剂的库存已经告急，博恩奈特需要火炎龙鳞、皇血草和煤炭：两个鳞片，四株皇血草，以及煤炭。博恩奈特要你送来尽可能多的材料。"}},faq={{q="是谁在需求这些物资？",a="位于灼热峡谷的大铁匠博恩奈特，他会亲自接收这些物资。",al={"谁发布了这个任务","博恩奈特 炽热助熔剂","在哪里交任务"}},{q="博恩奈特需要什么材料？",a="两个火炎龙鳞，四株皇血草，以及一些煤炭。",al={"我需要什么物品","炽热助熔剂所需材料","博恩奈特 提交物品"}},{q="这个请求的前置任务是什么？",a="名为“这是什么助熔剂？”的任务，这是博恩奈特之前交给你的。",al={"此任务的前置要求","炽热助熔剂之前的任务","“这是什么助熔剂？”前置条件"}},{q="为什么博恩奈特需要这些物资？",a="博恩奈特说炽热助熔剂的供应正在减少，他想要补充储备。",al={"为什么需要炽热助熔剂","博恩奈特的动机"}}},fp="44,214,17.224.0,25.78.0,35.55.0,30.69.0,36.78.0"}
P.entries["quest:7738"] = {n="完美的雪人毛皮",s="你找到了一张完美的雪人皮，它非常厚实坚韧，远胜于Rage Scar的雪人所产出的皮。在莫沙彻营地，杉多尔·迅蹄正在寻找雪人皮。",h="你找到了一张完美的雪人皮，它非常厚实坚韧，远胜于Rage Scar的雪人所产出的皮。在莫沙彻营地，杉多尔·迅蹄正在寻找雪人皮。",kw={"莫沙彻营地","菲拉斯","杉多尔·迅蹄","完美的雪人皮","rage scar","雪人毛皮"},sec={{t="值得展示的毛皮",b="这张毛皮显然比Rage Scar雪人的皮更厚实、更坚固。在菲拉斯的莫沙彻营地，杉多尔·迅蹄希望能收购雪人皮，所以这张皮值得带去给他。"},{t="杉多尔的评价",b="杉多尔很高兴，称这是他见过的最好的雪人皮。他决定给予一份合理的奖励，比他平时收购单张毛皮的价格更高。他确信能用这张毛皮制作出某种特别的东西。"}},faq={{q="谁对完美的雪人皮感兴趣？",a="位于菲拉斯莫沙彻营地的杉多尔·迅蹄，他希望能收购雪人皮。",al={"谁需要毛皮","谁来上交完美的雪人皮","杉多尔雪人毛皮"}},{q="为什么这张毛皮被认为是完美的？",a="它异常厚实坚韧，极有可能是完美的，比Rage Scar雪人的皮要好得多。",al={"为什么它是完美的","这张毛皮有何特别之处"}},{q="杉多尔·迅蹄在哪里？",a="在菲拉斯的莫沙彻营地。",al={"杉多尔·迅蹄在哪里","去哪里上交完美的雪人皮"}}},fp="17,187,20.194.0,17.205.1,43.78.0,36.103.0,30.27.0"}
P.entries["quest:775"] = {n="雷霆崖之旅",s="“前往雷霆崖之旅”是年轻英雄在莫高雷试炼终点的朝圣之旅。在先祖之魂的指引下完成了神圣的大地母亲的试炼后，The Adventurer将获得觐见牛头人大酋长凯恩·血蹄的机会。",h="“前往雷霆崖之旅”是年轻英雄在莫高雷试炼终点的朝圣之旅。在先祖之魂的指引下完成了神圣的大地母亲的试炼后，The Adventurer将获得觐见牛头人大酋长凯恩·血蹄的机会。",kw={"先祖之魂","凯恩·血蹄","high rise","前往雷霆崖之旅","莫高雷","大地母亲的试炼","雷霆崖"},ang={["faction:Horde"]="牛头人愿意欢迎任何完成其神圣传统的盟友种族，这体现了将年轻的部落团结在一起的相互尊重。",["race:Tauren"]="对于年轻的牛头人来说，在完成大地母亲的试炼后站在凯恩·血蹄面前，是步入成年和部落荣誉的决定性门槛。"},sec={{t="一场试炼的终结",b="在任何旅者或雏鹰战士真正宣称自己在莫高雷证明了自己之前，他们都必须经历古老的大地母亲的试炼。这些试炼在草海平原和这片土地上的先祖遗迹中考验着他们的力量、视野和智慧。一旦先祖之魂认可了最后的试炼，修行者便被认为有资格进入雷霆崖，不再仅仅是一名访客，而是牛头人人民的一位荣耀的保卫者。"},{t="登上High Rise",b="任务指引旅者从先祖游荡的神圣土地径直前往高耸的雷霆崖。这座城市坐落在平顶山之上，是一座由红岩雕琢而成的和平灯塔，并由宽阔的绳桥和巨大的木制升降梯支撑。在那里，在High Rise上，大酋长凯恩·血蹄正等待着亲自迎接那些走过先祖之路的人们。"}},faq={{q="是谁指派你踏上这段旅程的？",a="在你完成大地母亲的试炼的最后一步——智慧试炼后，这个任务将由先祖之魂授予。",al={"谁发布任务","先祖之魂任务","任务发布者"}},{q="我在哪里可以找到凯恩·血蹄？",a="凯恩·血蹄居住在High Rise上，这是雷霆崖中心的高耸平顶山，俯瞰着周围的红色高原和平原。",al={"凯恩位置","凯恩在哪里","雷霆崖首领"}},{q="完成这个任务有什么意义？",a="它标志着你在莫高雷的起始冒险正式结束。觐见凯恩意味着你已得到牛头人领导层的完全认可，并准备好在更广阔的部落中承担责任。",al={"为什么要拜访凯恩","试炼的意义","前往雷霆崖之旅的意义"}},{q="只有牛头人才能完成这段旅程吗？",a="虽然这是一场根深蒂固的牛头人传统成年礼，但任何通过大地母亲的试炼证明了自己奉献精神的部落成员，都会被授予同样的荣誉，并被派遣去觐见大酋长。",al={"兽人可以完成吗","谁可以前往雷霆崖","种族"}},{q="与凯恩交谈后会发生什么？",a="凯恩会欢迎你来到他的家，认可你的功绩，并指引你前往卡利姆多，面对部落所面临的更广泛的冲突。",al={"下一个任务","找过凯恩后做什么","前往雷霆崖之旅之后"}},{q="如何抵达雷霆崖的High Rise？",a="乘坐从下方平原通往平顶山的巨大机械升降梯，然后穿过通往中心High Rise平台的绳索和木制桥梁，酋长的住所就矗立在那里。",al={"前往high rise","如何找到凯恩","雷霆崖升降梯"}}},fx={["74afb15b"]={q="先祖之魂为何派你前往雷霆崖？",a="你在莫高雷经受了重重考验，并与灵魂沟通，凭借大地母亲的仪式证明了自己的智慧、力量与虔诚。先祖之魂指引你前往雷霆崖，让牛头人族群及其最高领袖凯恩·血蹄知晓你的功绩。站在大酋长面前，意味着你正式成为他们社会的一员，并获接纳为受尊崇的勇士。",al={"先祖之魂为什么派你去","先祖之魂的目的","为什么要去找凯恩"}},c86a41a9={q="为什么必须由你亲自把消息告诉凯恩·血蹄？",a="大地母亲的仪式是神圣的个人试炼。先祖之魂是超凡的向导，受莫高雷圣地所缚，既无法也无意传递尘世的消息。既然接受考验的是你的灵魂与意志，亲自拜见大酋长凯恩·血蹄的荣誉便只属于你。",al={"为什么是我去找凯恩","为什么必须拜访凯恩","为什么必须去见凯恩·血蹄"}}},fp="26,296,27.451.0,26.407.0,30.141.0,34.138.0,50.216.0,37.208.0,38.141.0,48.197.0"}
P.entries["quest:776"] = {n="大地之母仪祭",s="这项由大酋长凯恩·血蹄亲自设立的试炼，要求初露锋芒的英雄们在莫高雷平原上猎杀伟大的科多兽阿兰其亚。尽管新兵可能已经完成了传统的成人仪式，但凯恩希望他的人民能够不断重申他们的力量、追踪技巧以及对部落的忠诚。带回阿兰其亚的角，证明了一位冒险者已经准备好为台地之外更广阔的部落效力。",h="这项由大酋长凯恩·血蹄亲自设立的试炼，要求初露锋芒的英雄们在莫高雷平原上猎杀伟大的科多兽阿兰其亚。尽管新兵可能已经完成了传统的成人仪式，但凯恩希望他的人民能够不断重申他们的力量、追踪技巧以及对部落的忠诚。带回阿兰其亚的角...",kw={"阿兰其亚","血蹄","凯恩","大地母亲","角","狩猎","科多兽","莫高雷","雷霆崖"},ang={["class:Hunter"]="在金色平原上追踪像阿兰其亚这样孤独漫游的庞然大物，体现了牛头人追踪大师们代代相传的古老狩猎哲学。",["faction:Horde"]="放倒阿兰其亚为雷霆崖提供了必要的食物、皮革和材料，展现了维持初生部落生存的集体生存理念。",["race:Tauren"]="站在凯恩·血蹄面前领取阿兰其亚的角，是年轻Shu'halo的终极成人仪式，这证明了你的勇武既告慰了你的祖先，也荣耀了莫高雷的兽群。"},sec={{t="大酋长的衡量标准",b="到达雷霆崖标志着牛头人简单青春期的结束，但大酋长凯恩·血蹄并没有让年轻的猎手们止步不前。对于凯恩来说，在高耸的峭壁中赢得一席之地仅仅是承担起对联合牛头人部族责任的开始。他并不满足于派遣新兵去对付一些小害虫，而是要求他们证明真正的野外生存技巧：追踪并干净利落地猎杀莫高雷最著名的漫游野兽之一。"},{t="猎杀阿兰其亚",b="猎物是阿兰其亚，一头巨大的传奇科多兽，它的足迹横跨雷霆崖东北部的金色平原。要放倒这样的生物不仅仅需要蛮力；还需要在开阔的草原上耐心地潜行，并对平原上的巨人保持敬意。将阿兰其亚的角带回High Rise不仅能赢得个人荣耀，还能为城市提供物资，因为凯恩会立即派遣剥皮者和采集者，确保这头神圣野兽的任何部分都不会被浪费。"}},faq={{q="谁发布了这个任务？",a="大酋长凯恩·血蹄亲自在雷霆崖的High Rise顶端布置了这项任务。",al={"任务发布者","谁发布了大地母亲的仪式","凯恩的任务"}},{q="阿兰其亚是什么？",a="阿兰其亚是一头强大而著名的科多兽，它漫游在莫高雷的平原上。它巨大的角是猎人追踪能力和武艺的证明。",al={"阿兰其亚是谁","阿兰其亚是什么","阿兰其亚背景故事"}},{q="我在哪里可以找到阿兰其亚？",a="阿兰其亚通常在雷霆崖峭壁东北部的一条宽阔圆形路径上漫游，沿着草海平原顺时针缓慢绕行。",al={"阿兰其亚在哪里","阿兰其亚位置","阿兰其亚路径"}},{q="既然我已经完成了早期的仪式，为什么凯恩还要要求进行这次狩猎？",a="在牛头人文化中，获得初步的地位并不意味着责任的终结。凯恩教导说，为了维持部族的生存，力量、谦逊和狩猎技巧必须不断地展现出来。",al={"为什么要完成这个任务","为什么要猎杀阿兰其亚","仪式的意义"}},{q="取走角之后，阿兰其亚的尸体会怎样处理？",a="为了遵循牛头人尊重猎物的传统，凯恩会派遣一支采集队伍去回收这头倒下野兽的肉和皮，让这次狩猎的成果能够喂养并供给雷霆崖。",al={"阿兰其亚的肉","科多兽怎么了","尸体背景"}},{q="这和早期的起始仪式任务一样吗？",a="不。虽然纳拉其营地的早期试炼教会了新兵最基础的“大地母亲的仪式”，但雷霆崖的这项终极试炼是凯恩对你作为一名猎人持续价值的个人考验。",al={"大地母亲的仪式差异","哪一个仪式任务","纳拉其营地仪式"}}},fx={d7a516d7={q="阿兰其亚的角有什么用？",a="这只角是你成功狩猎的实物证明。牛头人传统十分尊崇追踪并猎杀强大野兽的本领。将阿兰其亚的角亲自呈给大酋长凯恩·血蹄，便能证明你拥有供养和保护族人的实力。",al={"阿兰其亚的角有什么用","为什么带阿兰其亚的角","阿兰其亚的角的用途"}},a7e696eb={q="凯恩·血蹄为什么派你去，而不派城防卫兵？",a="这场狩猎不是防务差事，也不是简单的收集物资，而是一项传统试炼。你或许已经通过最初的大地母亲仪式，抵达雷霆崖，但凯恩期望部族中的每位猎人都不断以丰功伟绩证明自己的价值与自立能力，而不是躺在过去的功绩上。",al={"为什么派我去","为什么不派卫兵去对付阿兰其亚","凯恩为什么需要我"}}},fp="24,439,21.449.0,22.491.0,21.108.0,18.161.0,27.154.0,78.183.0,57.183.0,50.204.0"}
P.entries["quest:777"] = {n="不祥的感觉",s="卢希恩·枪穗将5号齿轮交给你，让你送给鲁特维尔·沃拉图斯，然后他便躲进了掩体，并邀请你一起过去。",h="卢希恩·枪穗将5号齿轮交给你，让你送给鲁特维尔·沃拉图斯，然后他便躲进了掩体，并邀请你一起过去。",kw={"荒芜之地","5号齿轮","鲁特维尔·沃拉图斯","卢希恩·枪穗","镣铐","这将会很难"},sec={{t="掩体后",b="卢希恩交出齿轮，让你把它送给鲁特维尔·沃拉图斯。卢希恩会在掩体后等你，如果你愿意也可以加入他。当你到达仍在埋头摆弄镣铐的鲁特维尔身边时，他伸出一只手，手指不耐烦地摆动着，索要那个齿轮。"},{t="创造历史",b="鲁特维尔接过齿轮并称赞它非常完美，让你站远点，他要为创造历史做准备了。鲁特维尔继续疯狂地工作。"}},faq={{q="谁为鲁特维尔交出了齿轮？",a="卢希恩·枪穗给了你5号齿轮，让你带给鲁特维尔·沃拉图斯。",al={"谁给了齿轮","我在哪里能拿到5号齿轮","卢希恩 齿轮"}},{q="卢希恩去了哪里？",a="卢希恩去了掩体后，并说欢迎你也一起过去。",al={"为什么卢希恩要躲起来","卢希恩 掩体"}},{q="当你带来齿轮时，鲁特维尔正在做什么？",a="鲁特维尔正在摆弄一副镣铐，他头也不抬，不耐烦地伸出手索要齿轮。",al={"鲁特维尔在做什么","鲁特维尔 镣铐","鲁特维尔的进度"}}},fp="24,106,12.254.0,14.158.1,34.65.0,21.58.0,44.105.0"}
P.entries["quest:778"] = {n="不祥的感觉",s="鲁特维尔·沃拉图斯宣布枷锁已经完成，并召集Lucien、Servo和你一同见证一个强大的元素被召唤出来。",h="鲁特维尔·沃拉图斯宣布枷锁已经完成，并召集Lucien、Servo和你一同见证一个强大的元素被召唤出来。",kw={"荒芜之地","元素","fam'retor guardian","鲁特维尔·沃拉图斯","lucien","servo","元素束缚镣铐"},sec={{t="开创性的一天",b="鲁特维尔大喊着枷锁已经完成，时机已到，并召集Lucien和Servo以及你一同见证。鲁特维尔声称这些枷锁完美融合了炼金术、工程学和奥术力量，并打算在这被他称为开创性的一天里召唤出一个强大的元素。"},{t="召唤之后",b="结果并非鲁特维尔所料，在击败Fam'retor Guardian后，他请求你把元素束缚镣铐找回来。事后，鲁特维尔虽然不清楚究竟哪里出了问题，但很庆幸手头有魔法可以将这种生物送回它原本的位面。"}},faq={{q="谁是鲁特维尔·沃拉图斯？",a="鲁特维尔·沃拉图斯是元素束缚镣铐的制造者，这种镣铐融合了炼金术、工程学和奥术。Lucien和Servo正与鲁特维尔一起待在荒芜之地。",al={"谁是鲁特维尔","鲁特维尔·沃拉图斯"}},{q="什么是元素束缚镣铐？",a="这是鲁特维尔刚刚完成的镣铐，融合了炼金术、工程学和奥术，用于他打算召唤的一个强大元素。",al={"什么是镣铐","元素束缚镣铐"}},{q="鲁特维尔召集了谁来见证？",a="鲁特维尔召集了Lucien和Servo，以及你，来见证这次召唤。",al={"谁是lucien","谁是servo"}},{q="在这一步之前发生了什么？",a="在此之前，你将5号齿轮交给了鲁特维尔。",al={"上一个任务","导致这一结果的原因"}}},fp="24,134,20.317.0,19.287.1,23.181.0,43.162.0,37.85.0,28.58.0"}
P.entries["quest:7781"] = {n="黑石之王",s="“黑石之王”是联盟的一项任务，在黑翼之巢内夺取黑龙奈法利安的断头后即可开启。将这件可怕的战利品交给Stormwind Keep的伯瓦尔·弗塔根公爵，宣告了黑石山主宰的覆灭。这是联盟近历史上最伟大的军事胜利之一。",h="“黑石之王”是联盟的一项任务，在黑翼之巢内夺取黑龙奈法利安的断头后即可开启。将这件可怕的战利品交给Stormwind Keep的伯瓦尔·弗塔根公爵，宣告了黑石山主宰的覆灭。这是联盟近历史上最伟大的军事胜利之一。",kw={"黑石山","黑翼之巢","伯瓦尔·弗塔根公爵","奈法利安的头颅","黑石之王","奈法利安","stormwind keep"},ang={["faction:Alliance"]="呈献黑龙奈法利安的头颅是联盟最顶级的军事成就之一，果断地粉碎了龙军团针对人类领土的阴谋。",["race:Human"]="暴风城遭受了无数来自黑石山的入侵和阴谋；看到它的主人被打败，让王国获得了期待已久的报复和解脱。"},sec={{t="胜利的丰碑",b="奈法利安，黑龙军团阴险的族群领袖，黑石塔上层的统治者，长期以来一直笼罩在周边人类王国的恐怖阴影之中。击杀他不仅仅是为了生存；这代表着彻底粉碎他扭曲的实验和阴谋。将他那颗巨大且伤痕累累的头颅带回暴风城，是“黑石之王”死于联盟最伟大的英雄之手的不争证明。"},{t="在Stormwind Keep觐见",b="这件令人毛骨悚然的战利品被直接带给了伯瓦尔·弗塔根公爵，他正在Stormwind Keep的王座大厅里治理王国。一颗巨龙的断头突然出现在王室法庭中，令围观者大为震惊，并引来即刻的敬畏。对于一个已经在内部政治斗争和外部威胁下苦苦挣扎的王国来说，这次胜利为王国带来了巨大的士气提振，并在联盟的历史中留下了不可磨灭的一笔。"}},faq={{q="“黑石之王”任务是关于什么的？",a="该任务始于冒险者在黑翼之巢夺取奈法利安的头颅。它指引胜利者将这座巨大的战利品带回暴风城，并代表王国将其呈献给伯瓦尔·弗塔根公爵。",al={"黑石之王任务","奈法利安的头颅任务 联盟","奈法利安的头颅 暴风城"}},{q="奈法利安是谁？",a="奈法利安是一条强大的黑龙，也是Deathwing之子。他统治着黑石山内的黑翼之巢，指挥着黑石兽人，并进行邪恶的实验以创造多彩龙军团。",al={"奈法利安是谁","黑石之王","奈法利安背景故事"}},{q="伯瓦尔·弗塔根公爵是谁？",a="伯瓦尔·弗塔根公爵是一位圣骑士，在瓦里安·乌瑞恩国王缺席期间担任暴风城的摄政王，他在Stormwind Keep的王座大厅主持朝政，并照看年轻的安度因·乌瑞恩国王。",al={"bolvar fordragon","伯瓦尔是谁","伯瓦尔公爵"}},{q="为什么要将这件战利品带到Stormwind Keep？",a="奈法利安在黑石山的统治对暴风城王国和整个南部大陆构成了致命威胁。将战利品直接带给王国的军事领导层，证实了这条巨龙已被消灭，并让整个王国能够围绕这一英勇壮举团结起来。",al={"为什么是暴风城","为什么要将头颅带到要塞","为什么是伯瓦尔"}},{q="将头颅交给伯瓦尔之后会发生什么？",a="伯瓦尔·弗塔根公爵对这一壮举感到震惊，宣称这一胜利将被永久载入史册。这直接导致了活动的后续阶段，即这颗头颅将被公开悬挂，供所有暴风城民众瞻仰。",al={"接下来会发生什么","黑石之王第二部分","奈法利安的头颅上交"}},{q="上交这颗头颅会影响整个城市吗？",a="是的。当奈法利安的头颅被送到首都并悬挂在城门之上时，它向所有在场的市民和士兵宣告了巨龙的覆灭，让暴风城的守卫者们充满了胜利的决心。",al={"城市增益","集结号令","奈法利安的头颅增益"}}},fp="21,273,21.325.0,26.302.0,42.167.0,16.211.0,33.197.0,45.238.0,45.176.0,48.190.0"}
P.entries["quest:7782"] = {n="黑石之王",s="这个任务代表了针对黑石山内敌对势力的最终战役的高潮。在向Stormwind Keep的杰斯·特瑞斯海军上将报告后，英雄们会被指引前往英雄谷，斯托布里奇元帅会在城门口协调举行一场公开的纪念仪式，让所有联盟成员都能看到。",h="这个任务代表了针对黑石山内敌对势力的最终战役的高潮。在向Stormwind Keep的杰斯·特瑞斯海军上将报告后，英雄们会被指引前往英雄谷，斯托布里奇元帅会在城门口协调举行一场公开的纪念仪式，让所有联盟成员都能看到。",kw={"黑石","屠龙者","奈法利安","屠龙者的咆哮","斯托布里奇","暴风城","英雄谷"},ang={["class:Warrior"]="屠龙者的咆哮所带来的巨大军事激励，鼓舞了前往保卫王国的战士们。",["faction:Alliance"]="在英雄谷展示奈法利安的头颅将所有联盟种族团结在一起，提醒着来自铁炉堡、达纳苏斯和诺莫瑞根的公民们，困扰着东部王国的黑暗势力是可以被粉碎的。",["race:Human"]="对于暴风城王国来说，击败黑石之王消除了边境上潜藏的龙族生存威胁。"},sec={{t="城市的凯旋",b="针对黑石氏族和黑龙军团子嗣的战役在公开的胜利展示中达到了高潮。在Stormwind Keep内展示过奈法利安的头颅后，伯瓦尔·弗塔根公爵会指引勇士们穿过城市前往英雄谷。在那里，斯托布里奇元帅正等待着接收这一血腥的战利品，并开启全城的庆祝活动。"},{t="集结联盟",b="当斯托布里奇元帅将奈法利安的头颅高悬于暴风城正门的巨大拱门上时，整座城市都感受到了震撼。这一展示伴随着屠龙者的咆哮，让城市守卫、到访显贵和普通公民们都备受鼓舞，因为他们知道Deathwing的子嗣遭受了毁灭性的打击。"}},faq={{q="完成这个任务会发生什么？",a="斯托布里奇元帅会将奈法利安的头颅高悬在英雄谷的石门拱门上。这会在暴风城触发屠龙者的咆哮增益效果，强化所有友方玩家和守卫的战斗力。",al={"奈法利安头颅任务提交","斯托布里奇的作用","屠龙者的咆哮触发"}},{q="斯托布里奇元帅是谁？",a="斯托布里奇元帅是暴风城军队的一名高级军官，驻守在靠近暴风城入口的英雄谷。她负责组织重大的军事胜利的公开纪念活动，包括悬挂被击败的龙族威胁的头颅。",al={"斯托布里奇","斯托布里奇元帅"}},{q="为什么伯瓦尔·弗塔根公爵要把你送到这里？",a="在王座间确认奈法利安被击败后，伯瓦尔命令你将消息传达到城门，以便联盟军队能公开展示这一胜利，从而提振首都的士气。",al={"伯瓦尔","为什么要去英雄谷"}},{q="上交这个任务会影响全城吗？",a="是的。当斯托布里奇接过战利品时，宏大的宣言将在暴风城中回荡，屠龙者的咆哮增益效果会施加给城内所有的人。",al={"世界增益奈法利安","暴风城获得增益"}},{q="英雄谷在哪里？",a="英雄谷是进入暴风城的宏伟入口通道，两旁矗立着纪念在黑暗之门前线作战的第二次战争英雄的雕像。",al={"英雄谷位置","斯托布里奇在哪里"}},{q="谁是“黑石之王”？",a="黑石之王是黑龙奈法利安，他是Deathwing之子，也是黑石山顶峰的统治者。",al={"谁是黑石之王","奈法利安身份"}}},fp="21,257,16.350.1,21.302.0,42.221.1,33.240.0,49.213.1,40.161.1,38.164.0,32.124.2"}
P.entries["quest:7783"] = {n="黑石之王",s="此任务标志着针对黑翼之巢的突袭达到了高潮，任务要求勇士们将奈法利安的头颅带回奥格瑞玛。将这件骇人的战利品呈献给萨尔大酋长，证明了黑龙军团的子嗣已被击溃。这是部落对付其最阴险的敌人之一时，一个具有里程碑意义的伟大胜利时刻。",h="此任务标志着针对黑翼之巢的突袭达到了高潮，任务要求勇士们将奈法利安的头颅带回奥格瑞玛。将这件骇人的战利品呈献给萨尔大酋长，证明了黑龙军团的子嗣已被击溃。这是部落对付其最阴险的敌人之一时，一个具有里程碑意义的伟大胜利时刻。",kw={"黑石","黑翼之巢","deathwing","屠龙者","萨尔","奈法利安","奥格瑞玛","屠龙者的咆哮"},ang={["class:Warrior"]="将龙族领主的巨大头颅呈献给大酋长本人，是武勇名望的最高标志之一。",["faction:Horde"]="击杀奈法利安捍卫了部落的荣耀，并将黑石地区从一位奴役了叛变的黑铁部落的恶龙的魔爪中解放出来。",["race:Orc"]="对于兽人来说，将奈法利安的头颅呈献给萨尔，代表着对那只操纵雷德·黑手并奴役兽人氏族进行实验的野兽的复仇。"},sec={{t="毁灭的战利品",b="黑翼之巢的主谋、东部王国黑龙军团的领袖奈法利安终于倒下了。他那颗布满战斗伤痕的巨大头颅，正是他死亡的铁证。对于部落的勇士们来说，将这件举世瞩目的战利品从燃烧的黑石山顶峰运往杜隆塔尔，跨越无尽之海，这无疑是一种无上的荣耀。"},{t="大酋长的审判",b="这份战利品被直接呈献给了萨尔大酋长。萨尔比任何人都更了解黑石山内部的腐化，他曾将自己的人民从集中营中解放出来，带领他们摆脱了旧部落的恶魔嗜血诅咒。看到死亡之翼的儿子被击杀，证明了多年抗争的意义，并终结了这条黑龙对黑石氏族兽人们残酷的统治。"},{t="父亲的阴影",b="虽然奈法利安的死终结了黑龙军团扭曲的基因实验，但他的陨落并没有消除所有的危险。在看到这颗被斩下的龙头时，萨尔表示，得知自己儿子的死讯，Deathwing本人必然会蠢蠢欲动。胜利固然真实，但这更严峻地提醒着人们，在世界表面之下还有更大的恐怖正在苏醒。"}},faq={{q="奈法利安是谁？",a="奈法利安是一条强大的黑龙，也是Deathwing之子。他盘踞在黑石山顶端的黑翼之巢，进行着扭曲的实验以创造多彩龙军团，并操纵着各个凡人种族——特别是黑铁部落——为他效命。",al={"奈法利安背景故事","奈法利安是谁","黑龙领主"}},{q="为什么要把战利品交给萨尔？",a="萨尔是部落的大酋长。他带领兽人走出了集中营，摆脱了旧部落的恶魔嗜血诅咒，因此，奴役黑石氏族兽人和黑铁部落的恶龙已被击败的证明，理应交到他的手中。",al={"为什么是萨尔","谁接受头颅"}},{q="当龙头被上交时，奥格瑞玛会发生什么？",a="当奈法利安的头颅被带回并悬挂在奥格瑞玛时，全城都会举行庆典。整座首都会获得“屠龙者的咆哮”效果，提升附近所有部落成员的战斗能力。",al={"龙头buff","奥格瑞玛世界buff","屠龙者的咆哮"}},{q="这个任务有联盟对应的版本吗？",a="有的，联盟英雄们可以完成一个名为“黑石之王”的对应任务，将奈法利安的头颅交给位于Stormwind Keep的伯瓦尔·弗塔根公爵，从而为他们的城市带来同样的祝福。",al={"联盟版本","联盟对应任务"}},{q="为什么Deathwing令人担忧？",a="Deathwing是奈法利安的父亲，也是黑龙军团的首领。击败他的儿子并不能消除这位龙父所带来的危险。",al={"邪恶者蠢蠢欲动","邪恶者是谁"}},{q="龙头是从哪里来的？",a="该任务始于在黑翼之巢的顶峰击败奈法利安后，直接从他的尸体上拾取奈法利安的头颅。",al={"如何获得奈法利安的头颅","任务起始物品"}}},fp="21,171,16.305.0,23.303.0,21.272.1,16.243.0,38.238.0,53.195.0,44.131.0,27.147.0,30.106.0"}
P.entries["quest:7784"] = {n="黑石之王",s="此任务标志着将奈法利安的首级呈交给奥格瑞玛领袖的最后一步。在向萨尔证明了这条黑龙的死讯后，勇士们被指引前往力量谷寻找萨鲁法尔大王，在整个部落面前展示这一战利品。",h="此任务标志着将奈法利安的首级呈交给奥格瑞玛领袖的最后一步。在向萨尔证明了这条黑龙的死讯后，勇士们被指引前往力量谷寻找萨鲁法尔大王，在整个部落面前展示这一战利品。",kw={"黑翼之巢","萨尔","奈法利安的头颅","萨鲁法尔","奥格瑞玛","奈法利安","valley of strength"},ang={["faction:Horde"]="公开展示奈法利安的首级巩固了萨尔的新秩序，并证明了重组后的部落对抗曾操纵黑石山兽人的黑龙的强大实力。",["race:Orc"]="对于兽人来说，见证那头曾奴役黑石氏族的巨龙的倒下，提供了一种深刻的宣泄，洗刷了笼罩在他们人民身上那段不光彩的阴影。"},sec={{t="部落的战利品",b="在黑翼之巢之巅击杀黑龙奈法利安后，他的首级被带到奥格瑞玛作为其战败的证据。大酋长萨尔确认了Deathwing之子的陨落，随后指引获胜者前往力量谷寻找萨鲁法尔大王。在那里，这些恐怖的残骸将被准备好进行公开展示，以此作为对敌人的警告，也是对真正部落的集结号召。"},{t="宣示传承",b="奈法利安统治着黑石山的高处，让黑石兽人和黑铁部落臣服于他的意志。通过击败他并将他的首级高悬在力量谷，大酋长萨尔的部落给予了黑龙军团沉重的一击，而萨鲁法尔大王也号召整个奥格瑞玛一同享受屠龙者的咆哮。"}},faq={{q="这个任务的目的是什么？",a="这是击杀奈法利安后的总结性交接任务。在向萨尔证明战果后，你将向位于奥格瑞玛力量谷的萨鲁法尔大王报告，以获得荣誉并将这颗首级公开展示。",al={"这个任务有什么用","黑石山的领主任务交接","为什么要去找萨鲁法尔"}},{q="萨鲁法尔大王是谁？",a="萨鲁法尔大王是一位资深的兽人战士，也是部落最伟大的勇士之一，他驻扎在奥格瑞玛的力量谷，在那里他将接收首级并将其悬挂供所有人瞻仰。",al={"萨鲁法尔是谁","萨鲁法尔大王的角色"}},{q="为什么要把奈法利安的首级展示出来？",a="悬挂这头黑龙的首级无可辩驳地证明了黑石山的主人已经倒下。它增强了奥格瑞玛守卫者的士气，并且城中的每个人都会获得屠龙者的咆哮效果。",al={"为什么要悬挂奈法利安的首级","奈法利安首级展示奥格瑞玛"}},{q="奈法利安是谁？",a="奈法利安是一头伟大的黑龙，也是Deathwing之子。在黑石山之巅的黑翼之巢中，他指挥着黑石兽人和黑铁部落，并培育了多彩龙军团。",al={"奈法利安是谁","奈法利安背景故事"}},{q="萨鲁法尔大王在哪里？",a="萨鲁法尔伫立在力量谷，那是奥格瑞玛的中心入口区域。",al={"萨鲁法尔在哪里","萨鲁法尔位置"}},{q="萨尔在其中扮演什么角色？",a="大酋长萨尔首先会接收首级。一旦他确认了奈法利安的死讯，他会派遣你去找萨鲁法尔，将这一战利品正式悬挂。",al={"为什么是萨尔","萨尔的参与"}}},fp="21,213,22.331.0,19.331.1,34.180.0,30.203.0,38.213.0,17.190.0,40.77.0,35.148.0"}
P.entries["quest:7792"] = {n="捐献毛料",s="达纳苏斯正在接受毛料捐赠，以补充库存。您的捐赠将让达纳苏斯充分认可您的慷慨之举。",h="达纳苏斯正在接受毛料捐赠，以补充库存。您的捐赠将让达纳苏斯充分认可您的慷慨之举。",kw={"达纳苏斯","捐赠","认可","库存","毛料"},sec={{t="毛料储备",b="达纳苏斯正在接受毛料捐赠。城中需要您捐赠六十块毛料，其余库存则希望从其他地方募集。您的捐赠将让达纳苏斯充分认可您的慷慨之举。"}},faq={{q="达纳苏斯需要什么？",a="达纳苏斯正在接受毛料捐赠。",al={"捐赠毛料","达纳苏斯需要什么布料"}},{q="我需要捐赠多少毛料？",a="需要捐赠六十块毛料。",al={"需要多少毛料","六十块毛料"}},{q="达纳苏斯为什么要收集毛料？",a="达纳苏斯正在收集毛料，以补充库存。",al={"为何需要毛料","募集毛料"}},{q="捐赠毛料能得到什么？",a="捐赠六十块毛料，达纳苏斯将充分认可您的慷慨之举。",al={"捐赠毛料的认可","捐赠毛料的奖励"}}},fp="18,123,11.219.0,25.47.0,34.43.0,33.56.0,32.99.0"}
P.entries["quest:78"] = {n="斯塔文的传说",s="这个差事标志着揭开Stalvan Mistmantle历史的一个转折点，它将调查者从艾尔文森林带回了阴影笼罩的夜色镇。在Marshal Haggard对自己服役岁月的记忆指引下，你带着找到的一张日记书页前往Scarlet Raven Tavern，交给旅店老板斯密茨，以辨认那令人不寒而栗的笔迹。",h="这个差事标志着揭开Stalvan Mistmantle历史的一个转折点，它将调查者从艾尔文森林带回了阴影笼罩的夜色镇。在Marshal...",kw={"夜色镇","暮色森林","艾尔文","日记","marshal haggard","mistmantle","scarlet raven tavern","stalvan","旅店老板斯密茨"},ang={["faction:Alliance"]="这个任务突显了王国前守卫者之间的深厚情谊，将退役的暴风城卫兵与整个暴风城王国的社区守护者联系在了一起。",["race:Human"]="这一步骤揭示了潜藏在人类聚居地中的阴暗记忆，表明艾尔文森林和夜色镇过去的悲剧并未真正尘封。"},sec={{t="来自元帅的线索",b="在艾尔文森林的Marshal Haggard的箱子里找到一张风化、破损的日记书页后，这位退役的指挥官因为视力下降而无法辨认上面褪色的字迹。意识到线索指向河对岸，Haggard回想起了他曾经指挥暴风城卫兵的往事，并记得自己曾在夜色镇的Scarlet Raven Tavern度过夜晚。他指引你去找旅店老板斯密茨，这位长期在此经营的酒保已成了当地历史和传闻的非官方守护者。"},{t="回到Scarlet Raven",b="穿过暮色森林阴沉的树林回到镇上，你将那张褪色的书页交给了柜台后的斯密茨。听到老熟人Haggard的名字，斯密茨的态度立刻缓和了下来，尽管他为这位老兵日益衰弱的健康感到惋惜。当这位旅店老板看到那张羊皮纸时，他原本随和的神态瞬间转为惊恐：他毫无疑问地认出了这独特的笔迹，这也让调查进一步揭开了Stalvan疯狂背后的恐怖真相。"}},faq={{q="为什么Marshal Haggard要我回到夜色镇？",a="Marshal Haggard年事已高，几近失明，这让他无法亲自查看找到的日记书页。他记得当他在暴风城卫兵服役时，夜色镇Scarlet Raven Tavern的旅店老板斯密茨是当地知识和历史方面的专家，这使他成为辨认笔迹的最佳人选。",al={"为什么要前往夜色镇","haggard与夜色镇","为什么要找斯密茨"}},{q="旅店老板斯密茨在哪里？",a="旅店老板斯密茨在Scarlet Raven Tavern内经营酒吧，该酒馆位于暮色森林的夜色镇东侧。",al={"斯密茨在哪里","斯密茨的位置","scarlet raven tavern的位置"}},{q="你带给旅店老板斯密茨什么物品？",a="你带来的是一张褪色的日记书页，这是Stalvan Mistmantle遗失日记中的一段，此前是在Marshal Haggard的箱子里找到的。",al={"什么物品","褪色的日记书页","stalvan日记书页"}},{q="旅店老板斯密茨认出笔迹了吗？",a="是的。当斯密茨看过那张褪色的书页时，他立刻惊恐地认出了笔迹，这种确认也为寻找Stalvan提供了下一条线索。",al={"斯密茨是否认识字迹","斯密茨对日记的反应"}},{q="斯密茨怎么认识Marshal Haggard的？",a="多年前，当Haggard率领暴风城卫兵巡逻队进入暮色森林，并经常光顾Scarlet Raven Tavern喝酒时，斯密茨曾接待过他。",al={"斯密茨与haggard的关系","斯密茨如何认识haggard"}},{q="寻找Stalvan的下一步是什么？",a="把那张褪色的日记书页带给Scarlet Raven Tavern的斯密茨，并跟随他提供的线索继续行动。",al={"接下来做什么","stalvan任务下一步","stalvan任务线后续"}}},fp="21,122,23.424.0,27.375.1,51.245.0,35.110.0,44.133.0,49.135.0,37.136.0,42.99.0"}
P.entries["quest:780"] = {n="斗猪",s="“战斗野猪”是纳拉其营地的格鲁尔·鹰风发布的一项成人礼狩猎任务。年轻的牛头人被委派去猎杀刺刃峡谷中那些凶猛的战训野猪，以保卫部落领地并为营地的幼年成员提供食物。",h="“战斗野猪”是纳拉其营地的格鲁尔·鹰风发布的一项成人礼狩猎任务。年轻的牛头人被委派去猎杀刺刃峡谷中那些凶猛的战训野猪，以保卫部落领地并为营地的幼年成员提供食物。",kw={"战斗野猪","刺刃峡谷","刺背","纳拉其营地","格鲁尔·鹰风","莫高雷","野猪人","红云台地"},ang={["class:Hunter"]="面对这些被刺背野猪人训练出恶意的野兽，年轻的猎人们得以认清自然野生动物与被扭曲为战争武器的动物之间的巨大区别。",["profession:Cooking"]="对侧腹肉和猪鼻的需求凸显了牛头人基础的饮食理念：粗糙、坚韧的肉总是可以通过烹煮转化为浓郁、滋补的炖菜。",["race:Tauren"]="这项任务体现了牛头人维护大地母亲领土的平衡，同时也确保了战斗中获得的任何东西都不会被浪费，将敌人的战兽转化为营地幼崽的养分。"},sec={{t="边境威胁",b="红云台地的东侧是刺刃峡谷，这是一道布满荆棘的伤疤，被刺背野猪人所占据。随着舒哈鲁与野猪人之间的紧张局势升级为公开的战争，刺背野猪人训练了凶猛的战斗野猪来试探牛头人的边界，并恐吓他们传统的狩猎场。如果不加遏制，这些好斗的野兽不仅会威胁到兽径，还会威胁到纳拉其营地本身的安全。"},{t="供养部落",b="对于牛头人来说，狩猎既是防御的需要，也是维持社区生存的手段。格鲁尔·鹰风指示新手们带回被杀死的战斗野猪的猪鼻和侧腹肉。即使是经由野猪人之手训练出来的野兽也不会被浪费；它们的肉和软骨会被采集起来，为部落的年轻人烹制浓郁的炖肉，将野猪人的武器转化为哺育下一代牛头人守卫者的养分。"}},faq={{q="为什么战斗野猪会袭击台地？",a="这些战斗野猪是由栖息在刺刃峡谷的刺背野猪人刻意培育和训练出来的。野猪人利用它们作为冲击性动物，骚扰牛头人并侵占红云台地的部落狩猎场。",al={"战斗野猪的侵略性","为什么战斗野猪具有敌意","战斗野猪的袭击"}},{q="是谁派遣玩家执行这次狩猎任务的？",a="驻扎在纳拉其营地的杰出猎人兼长者格鲁尔·鹰风，负责指导年轻牛头人完成早期训练的最终试炼。",al={"战斗野猪任务发布者","谁发布了战斗野猪任务","格鲁尔·鹰风的角色"}},{q="在哪里可以找到这些战斗野猪？",a="它们游荡在刺刃峡谷附近及其内部，这是一个位于纳拉其营地以东、红云台地东缘的崎岖峡谷。",al={"战斗野猪位置","战斗野猪在哪里","刺刃峡谷的野猪"}},{q="从野猪身上收集来的肉会被用来做什么？",a="战斗野猪的侧腹肉和猪鼻会被带回纳拉其营地，炖煮成供给营地孩童和长者的炖肉，这体现了牛头人利用狩猎所得的传统。",al={"战斗野猪侧腹肉的用途","野猪肉有什么用","野猪肉炖菜"}},{q="这项任务在当地的野猪人冲突中起到了什么作用？",a="它作为牛头人与刺背部落之间公开战争的早期引子。猎杀它们的战兽可以减少骚扰牛头人狩猎场的野兽数量，并向刺刃峡谷的刺背野猪人发出明确的信号。",al={"牛头人与野猪人的战争","刺背部族冲突","野猪人背景知识"}},{q="“战斗野猪”的前置任务是什么？",a="它的前置任务是“狩猎继续”，那是格鲁尔·鹰风发布的一项早期任务，重点是了解红云台地的狩猎场。",al={"战斗野猪前置条件","战斗野猪之前的任务","狩猎继续任务链"}}},fx={b70ec92c={q="格鲁尔·鹰风为什么要杀死战斗野猪？",a="战斗野猪从刺刃峡谷一路闯出，侵入红云部族祖传的狩猎场。它们由野猪人荆背氏族培育并训练得凶残无比，日益增长的敌意直接威胁纳拉其营地。格鲁尔·鹰风打算削减它们的数量，给荆背氏族一个明确的警告，同时把猎获的野猪肉供给部族的年轻成员。",al={"格鲁尔·鹰风为什么要杀死战斗野猪","格鲁尔·鹰风对付战斗野猪的目的","为什么要在莫高雷杀死战斗野猪"}},["58a19c3f"]={q="什么是战斗野猪？",a="战斗野猪是由刺刃峡谷的野猪人荆背氏族饲养和训练的凶猛野兽。与红云台地本土的野生山地狮和草原徘徊者不同，这些野猪经过刻意训练，专为战争与杀戮而生，是荆背氏族对抗牛头人的活体武器。",al={"战斗野猪是什么人","什么是战斗野猪","战斗野猪的背景"}}},fp="15,237,22.418.0,17.402.0,43.234.0,31.147.0,32.137.0,50.191.0,57.242.0,36.132.0"}
P.entries["quest:7802"] = {n="A Donation of Wool",s="铁炉堡正在接受毛料捐赠，以补充储备。捐赠六十块毛料，即可获得全额嘉奖，表彰你的慷慨。",h="铁炉堡正在接受毛料捐赠，以补充储备。捐赠六十块毛料，即可获得全额嘉奖，表彰你的慷慨。",kw={"捐赠","铁炉堡","嘉奖","六十块","储备","毛料"},ang={["faction:Alliance"]="作为一名联盟旅人，捐赠毛料便能获得铁炉堡的嘉奖。"},sec={{t="毛料储备",b="铁炉堡需要你捐赠六十块毛料。它的储备只需要你提供这么多，而其他人预计会捐赠足够的毛料来支持此次募集。"}},faq={{q="铁炉堡需要我捐赠多少毛料？",a="铁炉堡向你征集六十块毛料。",al={"毛料捐赠数量","需要多少毛料","六十块毛料"}},{q="捐赠毛料能得到什么？",a="捐赠六十块毛料，铁炉堡就会全额嘉奖你的慷慨。",al={"毛料捐赠奖励","捐赠毛料有什么用","铁炉堡嘉奖"}},{q="铁炉堡为什么要募集毛料？",a="铁炉堡正在募集毛料，以补充储备。",al={"毛料募集","为何捐赠毛料","铁炉堡毛料"}}},fp="18,122,11.164.0,42.50.0,32.98.0,33.56.0"}
P.entries["quest:7807"] = {n="捐献毛料",s="“捐献毛料”是由诺莫瑞根流亡者发起的一项物资征集活动，旨在收集基本的纺织物资。由于被迫离开了他们的科技之城，这些流亡的侏儒需要来自世界各地的慷慨冒险者提供六十块毛料，以维持其社区的运转。为这项活动做出贡献将使你获得侏儒难民的正式认可。",h="“捐献毛料”是由诺莫瑞根流亡者发起的一项物资征集活动，旨在收集基本的纺织物资。由于被迫离开了他们的科技之城，这些流亡的侏儒需要来自世界各地的慷慨冒险者提供六十块毛料，以维持其社区的运转。为这项活动做出贡献将使你获得侏儒难...",kw={"布料征集","捐献毛料","侏儒","诺莫瑞根","诺莫瑞根流亡者","纺织品","毛料"},ang={["faction:Alliance"]="向流亡的侏儒捐献原材料可以加强联盟的团结，并帮助维持这一从家园山脉中流离失所的重要盟友。",["profession:Tailoring"]="收集或编织毛料的裁缝拥有充足的纺织品储备，这正是难民群体制作基本衣物和生活用品所迫切需要的。",["race:Gnome"]="对于流亡的侏儒来说，收集毛料有助于为你的流离失所的族人提供补给，帮助他们在诺莫瑞根之外努力生存和重建。"},sec={{t="流离失所者的需求",b="在诺莫瑞根沦陷于穴居人入侵和放射性污染之后，幸存的侏儒被迫离开了他们的高科技大都市。作为由铁炉堡的矮人亲戚们主要收留的难民，诺莫瑞根流亡者面临着严峻的后勤压力。常规的物资征集活动（如收集布料等基本物资）对于在祖居地之外艰难求生的他们来说，是保证族人有衣穿、有补给、能维持组织运转的关键。"},{t="纺织品征集",b="为了避免给个人的捐赠者造成过大负担，征集活动的组织者要求每位志愿者提供恰好六十块毛料。通过汇集来自世界各地的微薄捐助，流亡者们能够积攒起制造寝具、绷带和衣物所需的大量纺织品，而不会给任何单一的供应者带来无法承受的压力。作为回报，侏儒们会向任何愿意帮助他们恢复重建的人提供正式的认可。"}},faq={{q="为什么诺莫瑞根流亡者需要毛料？",a="诺莫瑞根流亡者正在进行一场资源征集活动，以建立基础的纺织品储备。在被赶出家园城市之后，他们的族人需要毛料这样的重要物资来维持难民群体的生活以及日常运作。",al={"为什么需要毛料","毛料的用途","毛料捐赠目的"}},{q="需要多少毛料？",a="这项捐赠活动要求每位捐赠者一次性贡献六十块毛料。组织者计算认为，从世界各地的个人那里获得这一特定数量的物资，将足以满足他们的整体供应需求。",al={"需要多少毛料","捐赠数量","所需毛料"}},{q="是谁在组织这场捐赠活动？",a="诺莫瑞根流亡者的代表负责协调纺织品的收集工作，并代表目前在盟友庇护下的流离失所的侏儒群体接收捐赠。",al={"谁在接收捐赠","谁在接受毛料","捐赠接收者"}},{q="你可以多次捐献毛料吗？",a="这项征集活动限制每位捐赠者只能贡献一次，即六十块毛料。流亡者们表示，他们目前的库存只需要你提供这一固定数量，因为他们依靠世界各地更广泛的捐赠者群体来完成配额。",al={"可以再次捐赠吗","是否可重复","更多毛料捐赠"}},{q="诺莫瑞根流亡者提供什么样的认可？",a="提供六十块毛料将赢得诺莫瑞根流亡者的充分认可和感激，证明你在危机时期对他们这些流离失所的人民所展现出的忠诚与帮助。",al={"诺莫瑞根流亡者声望","侏儒声望","流亡者认可"}},{q="为什么侏儒目前处于流亡状态？",a="在一场灾难性的事故和穴居人入侵之后，侏儒们被迫逃离了他们的地下家园诺莫瑞根，这使他们不得不依赖临时营地、盟友的援助和物资征集活动，过着难民般的生活。",al={"为什么侏儒会流亡","诺莫瑞根在哪里","侏儒难民危机"}}},fp="18,365,26.459.0,17.448.0,45.241.0,30.243.0,38.178.0,41.252.0,48.188.0,38.229.0"}
P.entries["quest:781"] = {n="纳拉其营地的危机",s="“纳拉其营地的袭击”是在刺刃峡谷的野猪人巢穴中发现的一项重要发现。一张沾满泥土的地图显示，咄咄逼人的刺背部族正在策划一场针对纳拉其营地的有组织围攻。将这些计划送交给鹰风酋长，便能及时让纳拉其营地发出预警，并从血蹄村召唤援军。",h="“纳拉其营地的袭击”是在刺刃峡谷的野猪人巢穴中发现的一项重要发现。一张沾满泥土的地图显示，咄咄逼人的刺背部族正在策划一场针对纳拉其营地的有组织围攻。将这些计划送交给鹰风酋长，便能及时让纳拉其营地发出预警，并从血蹄村召唤援...",kw={"进攻计划","血蹄村","刺刃峡谷","刺背野猪人","纳拉其营地","鹰风酋长","沾满泥土的地图","野猪人","红云台地"},ang={["faction:Horde"]="保住牛头人在莫高雷的立足点，确保了部落在卡利姆多中部保有至关重要的南方据点。",["race:Tauren"]="对于在台地上进行最初试炼的年轻牛头人勇士来说，截获这张地图证明了你对部族的忠诚，也保护了你的族人免受突然的屠杀。"},sec={{t="荆棘丛中的阴谋",b="当年轻的牛头人冒险者在刺刃峡谷的洞穴深处侦察时，他们会在岩石地面上发现一张粗糙、沾满泥土的地图。仔细检查后，羊皮纸上揭示了刺背野猪人精心制定的战术标记。野猪人并非在进行零星的突袭，而是在协调一场针对纳拉其营地的全面、持久的围攻。"},{t="警告酋长",b="将袭击计划带回纳拉其营地，为鹰风酋长提供了至关重要的情报。意识到防守薄弱的营地及其年轻学徒所面临的严峻威胁，鹰风酋长准备向血蹄村发出求援信号。这张被截获的地图将一场可能导致灾难的伏击转变成了有准备的防御战。"}},faq={{q="在哪里可以找到刺背野猪人的进攻计划？",a="这些计划源自一张沾满泥土的地图，位于刺刃峡谷的一个洞穴内，就在锐牙酋长的棚屋右侧的小路上去。",al={"地图位置","沾满泥土的地图在哪里","寻找进攻计划"}},{q="谁会接收刺背野猪人的进攻计划？",a="这些计划必须直接送交给纳拉其营地中心的鹰风酋长。",al={"交任务对象","谁接收地图","任务终结者"}},{q="为什么刺背野猪人要袭击纳拉其营地？",a="刺背部族试图将牛头人赶出红云台地，并夺回莫高雷的狩猎场和圣地，据为己有。",al={"为什么袭击纳拉其营地","野猪人在莫高雷的动机","刺背围攻"}},{q="鹰风酋长计划如何应对这场围攻？",a="有了截获地图所提供的提前预警，鹰风酋长打算召唤血蹄村的族人前来增援台地，以击退敌人的进攻。",al={"鹰风酋长的计划","纳拉其营地的援军"}},{q="这个任务在拾取地图之前需要与任何人交谈吗？",a="不需要。任务直接由刺刃峡谷洞穴地面上的沾满泥土的地图触发，拾取后即转变为战斗计划。",al={"任务起始物品","沾满泥土的地图起始任务","如何开始纳拉其营地的袭击"}},{q="如果纳拉其营地陷落会怎样？",a="纳拉其营地是年轻牛头人勇士进行试炼的主要避难所；失去它将危及红云台地的安全，并切断莫高雷的精神修行之地。",al={"纳拉其营地的利害关系","为什么要保卫纳拉其"}}},fp="22,330,22.393.0,21.361.0,45.143.0,42.85.0,56.152.0,50.168.0,69.149.0,35.185.0"}
P.entries["quest:7810"] = {n="竞技场高手",s="想要精通竞技场，仅仅做到这些就够了吗？古拉巴什竞技场活动的幕后黑手，海盗小个子约翰·米斯瑞尔或许知道答案，你可以在荆棘谷竞技场找到他。",h="想要精通竞技场，仅仅做到这些就够了吗？古拉巴什竞技场活动的幕后黑手，海盗小个子约翰·米斯瑞尔或许知道答案，你可以在荆棘谷竞技场找到他。",kw={"竞技场大师","古拉巴什","海盗","小个子约翰·米斯瑞尔","荆棘谷竞技场","荆棘谷"},sec={{t="寻找海盗",b="无论你在古拉巴什收获了什么，要真正精通竞技场似乎还需要付出更多。组织那里的竞赛的海盗小个子约翰·米斯瑞尔可能知道详情。去荆棘谷竞技场里面找他吧。"},{t="小个子约翰的话",b="小个子约翰·米斯瑞尔告诉你，仅仅一个饰品还不足以让你成为竞技场大师。他说，现在才是真正考验你实力的时候。"}},faq={{q="我需要和谁交谈？",a="小个子约翰·米斯瑞尔，古拉巴什活动的幕后海盗。",al={"我要和谁谈","竞技场大师任务提交","去哪里"}},{q="小个子约翰·米斯瑞尔在哪里？",a="在荆棘谷的荆棘谷竞技场，古拉巴什。",al={"古拉巴什位置","荆棘谷竞技场在哪里","竞技场位置"}},{q="关于成为竞技场大师有什么提示吗？",a="只是暗示说，精通竞技场似乎需要比你目前做得更多，而且古拉巴什活动的幕后海盗可能知道内情。",al={"如何成为竞技场大师","我成为竞技场大师了吗"}}},fp="12,177,18.212.0,17.149.1,28.58.0,28.63.0,47.135.0"}
P.entries["quest:78124"] = {n="Nar'thalas Almanac",s="Nar'thalas Almanac是一本珍稀的学术手稿，记载了古老的魔法研究，档案管理员们一直在寻找它以充实图书馆的藏书。回收这卷书册能将失传的奥术知识交到可靠的人手中，让研究者们能够钻研其中被遗忘的见解。",h="Nar'thalas Almanac是一本珍稀的学术手稿，记载了古老的魔法研究，档案管理员们一直在寻找它以充实图书馆的藏书。回收这卷书册能将失传的奥术知识交到可靠的人手中，让研究者们能够钻研其中被遗忘的见解。",kw={"年鉴","奥术","书","图书馆","魔法作品","nar'thalas","narthalas","书籍"},ang={["class:Mage"]="法师们了解研究古代奥术传统的回收文本所具有的巨大学术价值，因此对图书馆魔法藏书的贡献尤为重要。",["faction:Alliance"]="在联盟档案馆工作的学者和馆长们依靠进取的冒险者去搜寻珍稀手稿，并扩充王国收集的知识。",["race:NightElf"]="Nar'thalas曾是大分裂摧毁旧世界之前卡多雷奥术学术的古代中心，这使得一本带有其名字的年鉴成为了与古代暗夜精灵历史之间深刻的联系。"},sec={{t="古代研究的遗物",b="Nar'thalas Almanac是一本珍稀的奥术研究书籍，源自大分裂前暗夜精灵学术的古老传统。对于大型档案馆的管理员来说，保护这样的文本能使数百年的知识免于湮没，并为书架增添一份至关重要的历史资料。发掘这些长期被忽视的著作的冒险者，有助于架起连接被遗忘的古代与现代学术认知的桥梁。"},{t="扩充档案馆",b="档案管理员和研究人员不断在艾泽拉斯各地搜寻失落的论文、实地笔记和编年史。将Nar'thalas Almanac带入专门的图书馆，可以确保它得到妥善保管、编目和研究，而不是任其在废墟中腐烂或落入漫不经心之人手中。每一本被挽救的书册都能为学者提供关于过去时代奥术艺术的新见解。"}},faq={{q="什么是Nar'thalas Almanac？",a="Nar'thalas Almanac是一份古代魔法学术手稿，馆长们通过搜集它来充实图书馆的历史档案。回收此类珍稀著作的冒险者将其送交学术机构保管，以便将其中的见解编目保存。",al={"什么是narthalas almanac","narthalas almanac任务","年鉴信息"}},{q="谁在收集Nar'thalas Almanac？",a="这本年鉴是献给那些对古代魔法文献和历史档案感兴趣的图书馆学者的。这些馆长积极寻求新增藏品，以扩充他们对世界奥术遗产的共同机构知识。",al={"谁想要年鉴","年鉴去向","年鉴上交"}},{q="Nar'thalas这个名字是指什么？",a="Nar'thalas是卡多雷在大分裂前的一个学习和魔法研究中心。与这个名字相关的现存文本代表了分裂前奥术和精灵知识的残篇。",al={"什么是narthalas","narthalas传说","narthalas在哪里"}},{q="为什么要为图书馆收集魔法文本？",a="许多历史记录和魔法论文在艾泽拉斯各地流离失所、遗失或埋没在废墟中。学者们依靠回收的书稿来加深对奥术流动的理解，并保护脆弱的记录免于彻底消失。",al={"为什么要收集魔法作品","图书馆目的","书的重要性"}},{q="可以将其他魔法著作带到图书馆吗？",a="学者们欢迎任何能阐明奥术理论和古代历史的回收论文、大部头或遗失的手稿，并不断寻求增加馆藏以充实书架。",al={"更多魔法书籍","其他书籍","更多文本"}},{q="Nar'thalas Almanac处理起来危险吗？",a="这本年鉴是一份研究记录汇编，而非不稳定的禁忌神器。它主要作为历史学家和研究历史魔法的从业者们的一份珍贵参考资料。",al={"年鉴危险吗","年鉴有黑魔法吗","阅读安全吗"}}},fp="18,251,24.420.0,22.377.0,31.251.0,41.223.0,39.219.0,54.238.0,50.182.0,46.201.0"}
P.entries["quest:78127"] = {n="The Dalaran Digest",s="一位图书管理员请你为藏书增添魔法典籍。每本书都会让图书馆的知识更加丰富。",h="一位图书管理员请你为藏书增添魔法典籍。每本书都会让图书馆的知识更加丰富。",kw={"藏书","达拉然文摘","知识","图书管理员","图书馆","魔法典籍"},sec={{t="藏书",b="图书管理员欢迎能让图书馆受益的魔法典籍。你带来一本书，将它收入藏书，你的努力也让知识不断增长。"}},faq={{q="图书管理员想要什么？",a="图书管理员请你带来可能有益于藏书的魔法典籍。",al={"该带什么","图书馆书籍","魔法典籍"}},{q="我该把书带到哪里？",a="把书交给请你将其收入藏书的图书管理员。",al={"图书管理员在哪里","图书馆位置"}},{q="图书管理员为何收集魔法典籍？",a="你的贡献让藏书中的知识不断增长。",al={"为何收集书籍","图书馆的用途"}}},fp="18,108,14.148.0,29.80.0,26.64.0,46.60.0"}
P.entries["quest:78142"] = {n="Bewitchments and Glamours",s="铁炉堡图书馆正在寻找魔法典籍，以充实馆藏。你可以带来可能对图书馆有益的书籍，帮助馆藏不断丰富。",h="铁炉堡图书馆正在寻找魔法典籍，以充实馆藏。你可以带来可能对图书馆有益的书籍，帮助馆藏不断丰富。",kw={"魔法与魅惑","书籍","馆藏","铁炉堡","图书馆","魔法典籍"},sec={{t="不断丰富的馆藏",b="图书馆请你带来可能对馆藏有益的魔法典籍。每一部新增典籍都会拓展馆员的知识。"}},faq={{q="图书馆想要什么？",a="图书馆正在寻找可能对馆藏有益的魔法典籍。",al={"他们想要什么","图书馆藏书","魔法典籍"}},{q="我该把魔法典籍送到哪里？",a="把它们送到铁炉堡的图书馆。",al={"把书送到哪里","图书馆在哪里","铁炉堡图书馆"}},{q="他们为什么要收集魔法典籍？",a="图书馆表示，这些典籍能拓展他们的知识。",al={"为何收集魔法书籍","馆藏有何用途"}}},fp="25,150,20.125.0,27.66.0,35.39.0,38.53.0"}
P.entries["quest:78143"] = {n="Secrets of the Dreamers",s="“Secrets of the Dreamers”任务要求冒险者寻回稀有的魔法文献，以充实学术档案。通过上交这些发现的论著，探索者能帮助图书馆的学者扩充他们的古代知识收藏。",h="“Secrets of the Dreamers”任务要求冒险者寻回稀有的魔法文献，以充实学术档案。通过上交这些发现的论著，探索者能帮助图书馆的学者扩充他们的古代知识收藏。",kw={"奥术","梦境者","图书馆","魔法著作","学者","secrets of the dreamers","典籍"},ang={["class:Druid"]="鉴于对“梦境者”的提及，与自然魔法和翡翠梦境相关的著作对于塞纳里奥技艺的修行者来说具有深远的意义。",["class:Mage"]="学术奥术师非常适合在艾泽拉斯各地搜寻晦涩的典籍和魔法文本，以充实机构档案库。",["faction:Alliance"]="联盟的学者，特别是那些保管大型知识库的学者，依赖于勇敢的勇士从危险的地方寻回失落的知识。"},sec={{t="寻回被遗忘的知识",b="“Secrets of the Dreamers”任务涉及从各地寻回稀有的魔法文本和历史论著。致力于记录艾泽拉斯奥术奥秘的学者们依靠四处游历的冒险者来发掘被遗忘的著作，并将它们安全带回档案库。这些收集工作确保了珍贵的知识不会在古代废墟或私人收藏中被埋没，而是能得到研究和保存，以造福后代。"},{t="扩充档案库",b="上交这些论著后，档案管理员会将它们归入永久馆藏，从而扩充知识库对魔法现象的理解。在这样的图书馆里，研究人员不断寻找晦涩的文稿，内容涵盖从翡翠梦境到奥术理论的方方面面。这项工作永远无法彻底完成，学者们始终渴望得到在野外发现的任何进一步的魔法著作。"}},faq={{q="“Secrets of the Dreamers”任务的目的是什么？",a="“Secrets of the Dreamers”是一个专注于寻回魔法著作和晦涩知识以扩充学术收藏的任务。冒险者在世界各地获取相关材料并将其上交，以充实研究人员的档案库。",al={"什么是secrets of the dreamers","secrets of the dreamers任务","该任务的内容"}},{q="谁在收集这些魔法文本？",a="该任务由负责管理图书馆藏书的一位学者发布和交还，他会请求四处游历的冒险者带回魔法著作。",al={"谁需要secrets of the dreamers","任务发布者","secrets of the dreamers交还地点"}},{q="寻回的著作存放在哪里？",a="寻回的文献会被直接加入机构图书馆不断增长的档案中，确保稀有的知识和魔法发现能被编目并保存下来，供联盟的学者和研究人员使用。",al={"什么是藏书","任务涉及的图书馆","书籍的去向"}},{q="标题中的“梦境者”是指什么？",a="“梦境者”通常指与翡翠梦境协调一致的德鲁伊修行者，或是与自然沉睡相连的古老沉睡实体。记载了他们秘密的魔法著作保存着神秘的原始力量。",al={"谁是梦境者","梦境者知识","为什么叫梦境者"}},{q="完成任务后还能带来更多的魔法著作吗？",a="档案管理员非常欢迎持续的贡献。在旅途中，如果您发现了对收藏有益的其他魔法著作，我们鼓励您将其带回以帮助进一步的研究。",al={"可以上交更多书籍吗","任务可重复吗","更多魔法著作"}},{q="收集这些魔法文献对学者为何重要？",a="整个联盟的图书馆和研究人员都在不断寻求扩展对奥术、自然和晦涩奥秘的理解。遗失或散落的论著中包含的见解，能帮助学者们揭开这个世界更深层的历史和谜团。",al={"为什么要收集魔法书籍","图书馆为何需要魔法典籍"}}},fp="23,228,25.462.0,22.421.0,57.238.0,33.142.0,37.199.0,47.217.0,59.220.0,63.250.0"}
P.entries["quest:78146"] = {n="Goaz Scrolls",s="一位图书管理员请你带来 Goaz Scrolls，以充实馆藏。你的贡献让图书馆的知识更加丰富。",h="一位图书管理员请你带来 Goaz Scrolls，以充实馆藏。你的贡献让图书馆的知识更加丰富。",kw={"馆藏","goaz scrolls","知识","图书馆","魔法典籍","卷轴"},sec={{t="不断丰富的馆藏",b="图书管理员感谢你为馆藏作出的贡献。其他魔法典籍也能为图书馆带来益处，图书管理员欢迎你带来这些典籍。"}},faq={{q="Goaz Scrolls 有什么用？",a="Goaz Scrolls 能充实图书馆的馆藏，增长馆藏知识。",al={"goaz scrolls 的用途","为何要带来卷轴","图书馆卷轴"}},{q="是谁在索要 Goaz Scrolls？",a="一位图书管理员请你带来 Goaz Scrolls，充实馆藏。",al={"谁想要 goaz scrolls","卷轴交给谁","图书馆人员"}},{q="这些卷轴要送到哪里？",a="Goaz Scrolls 是为图书馆馆藏准备的。",al={"把卷轴带到哪里","goaz scrolls 的位置","图书馆卷轴"}},{q="还有什么能让图书馆受益？",a="图书管理员欢迎你带来其他可能有益于图书馆的魔法典籍。",al={"其他魔法典籍","更多图书馆藏书","还要带什么"}}},fp="12,127,20.129.0,26.61.0,30.62.0,28.52.0,36.74.0"}
P.entries["quest:7815"] = {n="钳嘴龟！",s="在辛特兰，恶齿村的钓鱼者卡图姆几乎没法好好钓鱼，因为咸水钳嘴龟总是在破坏鱼线并偷走他的鱼饵。他想要干掉十五只这样的海龟。",h="在辛特兰，恶齿村的钓鱼者卡图姆几乎没法好好钓鱼，因为咸水钳嘴龟总是在破坏鱼线并偷走他的鱼饵。他想要干掉十五只这样的海龟。",kw={"钓鱼者","鱼饵","钓鱼","辛特兰","卡图姆","恶齿","钳嘴龟","海龟"},sec={{t="线上的麻烦",b="卡图姆告诫你不要被钳嘴龟那双大眼睛给骗了，并称这些海龟是个祸害。据他说，他甚至连五分钟都钓不了鱼，这些海龟就会扯断他的鱼线，叼走他的鱼饵。他请求你帮帮他，也帮帮村里的邻居，把这群祸害全部消灭掉；数量是十五只。"}},faq={{q="是谁让你去猎杀海龟的？",a="钓鱼者卡图姆，辛特兰恶齿村的一名渔夫。",al={"谁发布了钳嘴龟任务","钳嘴龟任务发布者","钓鱼者卡图姆"}},{q="为什么卡图姆想要杀掉这些咸水钳嘴龟？",a="卡图姆说它们弄断了他的鱼线并偷走了他的鱼饵，让他甚至没法安安静静地钓上五分钟鱼。",al={"为什么要杀钳嘴龟","海龟滋扰","为什么要杀恶齿村的海龟"}},{q="需要杀掉多少只钳嘴龟？",a="十五只咸水钳嘴龟。",al={"海龟数量","钳嘴龟计数","钳嘴龟任务计数"}}},fp="14,199,19.333.0,33.60.0,51.109.0,35.34.0"}
P.entries["quest:7816"] = {n="加莫里塔！",s="来自辛特兰恶齿村的钓鱼者卡图姆，他最好的鱼饵被海水钳嘴龟的首领加摩拉抢走了。他请求你去找到它，并把它夺回来。",h="来自辛特兰恶齿村的钓鱼者卡图姆，他最好的鱼饵被海水钳嘴龟的首领加摩拉抢走了。他请求你去找到它，并把它夺回来。",kw={"钓鱼者","加摩拉","辛特兰","卡图姆","鱼饵","恶齿村","钳嘴龟","乌龟"},sec={{t="龟群中的窃贼",b="卡图姆描述说，加摩拉可不是一只普通的乌龟：她是海水钳嘴龟的首领，被卡图姆称为小偷。她从他的鱼线上咬断了他最好的鱼饵，从那以后，鱼儿们就不像以前那样上钩了。"},{t="找回鱼饵",b="卡图姆希望你找到加摩拉，并从她的肚子里取回鱼饵。加摩拉通常待在海岸边，混在其他乌龟中间。"},{t="卡图姆的希望",b="拿回鱼饵并除掉一些钳嘴龟后，卡图姆期待着鱼儿能成群结队地游来。"}},faq={{q="钓鱼者卡图姆是谁？",a="辛特兰恶齿村的一位渔夫，他请求你去猎杀加摩拉。",al={"钓鱼者卡图姆是谁","卡图姆 恶齿村","卡图姆位置"}},{q="加摩拉是什么？",a="一只与众不同的乌龟，她是海水钳嘴龟的首领，被卡图姆称为小偷。",al={"加摩拉是谁","加摩拉是什么","加摩拉 乌龟"}},{q="为什么卡图姆要杀掉加摩拉？",a="加摩拉从卡图姆的鱼线上咬断了他最好的鱼饵，从那以后，鱼儿们就没怎么上钩了。卡图姆想从她的肚子里找回鱼饵。",al={"为什么要杀加摩拉","加摩拉偷了什么","卡图姆的目的"}},{q="在哪里可以找到加摩拉？",a="在海岸边，她和其他海水钳嘴龟待在一起。",al={"加摩拉在哪里","加摩拉位置","找到加摩拉"}}},fp="15,177,25.216.0,21.128.0,14.100.1,25.73.0,18.91.0,36.145.0,29.79.0"}
P.entries["quest:782"] = {n="破碎的联盟",s="在卡加斯，高恩想要在部落与Deathwing结盟之后恢复部落的荣誉。食人魔Boss Tho'grun受雇协助获取大地印章，但他却背叛了部落并将其据为己有，你需要前往博夫营地将它夺回。",h="在卡加斯，高恩想要在部落与Deathwing结盟之后恢复部落的荣誉。食人魔Boss Tho'grun受雇协助获取大地印章，但他却背叛了部落并将其据为己有，你需要前往博夫营地将它夺回。",kw={"badlands","blacklash","博夫营地","deathwing","高恩","hematus","卡加斯","莱瑟罗峡谷","大地印章","tho'grun"},sec={{t="雇佣兵的背叛",b="在第二次战争期间，部落曾与巨龙Deathwing并肩作战。他的两名副官Blacklash和Hematus最终被关押在远至东部的莱瑟罗峡谷中。高恩认为，若要恢复部落的荣誉，就必须让这些昔日堕落的盟友永远沉默。为了打开巨龙的囚笼，部落需要大地印章，于是雇佣了Boss Tho'grun麾下的食人魔佣兵来寻找它。Tho'grun随后反戈一击，击败了他们并将印章据为己有。"},{t="博夫营地",b="高恩派你前往卡加斯东南部的博夫营地，杀掉Tho'grun并带回大地印章。高恩会很高兴看到Tho'grun死去，并表示食人魔已不再是部落的一员。"},{t="印章的用途",b="随着Tho'grun的死亡，高恩预计食人魔们将陷入混乱，这将是一场以小博大的胜利。只要大地印章回到部落手中，莱瑟罗的黑龙囚笼就能被打开，让它们从无尽的囚禁中解脱出来，迎接属于它们的末日。"}},faq={{q="高恩是谁？",a="高恩是卡加斯的部落人物，他派你去寻找大地印章，并希望通过让部落昔日堕落的盟友永远沉默来恢复部落的荣誉。",al={"谁发布了破碎的盟约任务","卡加斯的高恩","高恩背景故事"}},{q="为什么高恩想要Boss Tho'grun死？",a="部落雇佣了Tho'grun和他的食人魔佣兵来帮助获取大地印章。Tho'grun背叛了他们，击败了他们并将印章据为己有。",al={"为什么要杀掉tho'grun","tho'grun的背叛","boss tho'grun背景故事"}},{q="博夫营地在哪里？",a="博夫营地位于卡加斯东南部。",al={"博夫营地位置","tho'grun在哪里","寻找boss tho'grun"}},{q="大地印章是什么？",a="它是打开莱瑟罗峡谷巨龙囚笼所需的钥匙。",al={"大地印章","大地印章的作用"}},{q="哪些巨龙被关押在莱瑟罗峡谷中？",a="Blacklash和Hematus，他们在第二次战争中是Deathwing与部落结盟时的副官。",al={"谁被关在莱瑟罗峡谷","blacklash和hematus","deathwing的副官"}}},fp="16,236,18.475.0,9.196.0,19.252.1,12.158.0,38.142.0,19.36.0,30.72.0,47.119.0"}
P.entries["quest:7820"] = {n="捐献毛料",s="雷霆崖正在接收毛料捐赠，捐赠六十块即可获得其对你慷慨之举的充分认可。雷霆崖的仓库需要你提供这么多，其他捐赠者还会提供更多物资。",h="雷霆崖正在接收毛料捐赠，捐赠六十块即可获得其对你慷慨之举的充分认可。雷霆崖的仓库需要你提供这么多，其他捐赠者还会提供更多物资。",kw={"布料征集","捐赠","认可","六十块","雷霆崖","毛料"},sec={{t="捐赠布料",b="雷霆崖正在收集毛料。你可以捐赠六十块，满足其仓库对你的需求，并获得充分认可。此次征集预计还能从王国中的其他人那里收集到足够的毛料，以满足需求。"}},faq={{q="雷霆崖希望收到什么捐赠？",a="雷霆崖正在接收毛料捐赠。",al={"捐赠毛料","他们需要什么布料"}},{q="我应该捐赠多少毛料？",a="捐赠六十块毛料即可获得雷霆崖的充分认可。",al={"需要多少毛料","六十块布料","捐赠数量"}},{q="捐赠毛料能得到什么？",a="捐赠六十块毛料即可获得雷霆崖的充分认可。",al={"捐赠毛料的认可","能获得什么认可","捐赠奖励"}},{q="雷霆崖为什么要收集毛料？",a="此次捐赠活动正在收集毛料，雷霆崖预计还能从王国中的其他捐赠者那里获得足够的物资，以满足需求。",al={"为何征集毛料","毛料有什么用","为何收集布料"}}},fp="18,200,16.224.0,37.48.0,34.68.0,32.78.0,37.129.0"}
P.entries["quest:7826"] = {n="A Donation of Wool",s="奥格瑞玛正在收集毛料布料捐赠，并承诺会认可捐赠六十块布料的人。城中已有一些毛料，预计其他捐赠者也会帮忙凑足所需数量。",h="奥格瑞玛正在收集毛料布料捐赠，并承诺会认可捐赠六十块布料的人。城中已有一些毛料，预计其他捐赠者也会帮忙凑足所需数量。",kw={"捐赠毛料","捐赠","奥格瑞玛","认可","六块","毛料","毛料布料"},sec={{t="捐赠毛料给奥格瑞玛",b="奥格瑞玛邀请你捐赠六十块毛料布料，以表彰你的善举。城中已有一些毛料，也希望其他捐赠者能助力这项捐赠活动。"}},faq={{q="奥格瑞玛需要什么？",a="奥格瑞玛正在收集毛料布料捐赠。",al={"他们需要什么","毛料捐赠"}},{q="我需要捐多少毛料？",a="需要捐赠六十块毛料布料。",al={"需要多少毛料","六块毛料"}},{q="捐赠毛料能得到什么？",a="捐赠六十块毛料布料，奥格瑞玛便会充分认可你的慷慨之举。",al={"捐赠认可","毛料奖励"}},{q="奥格瑞玛为什么要收集毛料？",a="奥格瑞玛正在收集毛料，以支持这项捐赠活动。",al={"毛料捐赠活动","为何要毛料"}},{q="奥格瑞玛已经有毛料了吗？",a="有。奥格瑞玛的仓库里已有毛料，并希望其他捐赠者能捐出足够的数量，助力这项活动。",al={"毛料仓库","毛料数量"}}},fp="18,180,18.169.0,29.47.0,34.43.0,32.89.0,33.58.0,33.107.0"}
P.entries["quest:7828"] = {n="银鬃捕猎者",s="来自辛特兰邪枝村的猎户马克霍尔指出，银鬃狼是该村猎人面临的最严重的威胁之一。他要求你反其道而行之，去猎杀这些猎手。",h="来自辛特兰邪枝村的猎户马克霍尔指出，银鬃狼是该村猎人面临的最严重的威胁之一。他要求你反其道而行之，去猎杀这些猎手。",kw={"辛特兰的狼","猎户马克霍尔","邪枝村","恶齿村","银鬃嚎叫者","银鬃潜行者","潜伏的猎手"},sec={{t="潜伏的狼群",b="马克霍尔提到了辛特兰荒野中已经丧命的许多巨魔，并将银鬃狼列为邪枝村猎人面临的最大威胁之一。这些狼潜伏在灌木丛和地形之中，等待时机成熟便发起猛扑。马克霍尔绝不会坐视不管，他敦促你像银鬃狼一样思考，调转枪头，将它们猎杀殆尽。"},{t="马克霍尔的要求",b="马克霍尔要求杀死十五只银鬃潜行者和十五只银鬃嚎叫者。马克霍尔补充说，这些狼潜伏在辛特兰的荒野中。"},{t="邪枝的感谢",b="任务完成后，马克霍尔代表邪枝部族感谢你所做的一切。"}},faq={{q="是谁要求猎杀这些狼？",a="来自辛特兰邪枝村的猎户马克霍尔。",al={"谁发布了潜伏的猎手","潜伏的猎手任务发布者","马克霍尔任务"}},{q="为什么银鬃狼是如此大的威胁？",a="马克霍尔将它们列为邪枝村猎人面临的最大威胁：它们潜伏在灌木丛和地形中，等待机会发起攻击，许多巨魔已经在荒野中丧命。",al={"为什么要杀银鬃狼","银鬃狼的威胁","为什么要消灭辛特兰的狼"}},{q="需要消灭哪些狼？",a="十五只银鬃潜行者和十五只银鬃嚎叫者。",al={"要杀什么狼","潜伏的猎手任务目标","辛特兰的狼种类"}},{q="在哪里可以找到这些狼？",a="马克霍尔说它们潜伏在辛特兰的荒野中。",al={"银鬃狼在哪里","银鬃潜行者位置","银鬃嚎叫者位置"}}},fp="21,202,16.414.0,17.144.0,18.92.1,37.65.0,44.207.0,31.59.0,29.52.0"}
P.entries["quest:7829"] = {n="野蛮的枭兽",s="来自辛特兰恶齿村的猎户马克霍尔称那些野蛮的枭兽是该地区最暴躁的生物之一，并要求你杀死二十只。",h="来自辛特兰恶齿村的猎户马克霍尔称那些野蛮的枭兽是该地区最暴躁的生物之一，并要求你杀死二十只。",kw={"辛特兰","猎杀野蛮生物","猎户马克霍尔","枭兽","恶齿","恶齿村","野蛮枭兽"},sec={{t="利爪与尖喙",b="马克霍尔形容那些野蛮的枭兽是辛特兰最暴躁的生物之一，并声称这些野兽的利爪和尖喙已经让恶齿部族损失了许多优秀的战士。马克霍尔希望你见到一只就杀一只，直到你无法再承受这场杀戮，届时你所做的贡献将会被衡量与评判。必须有二十只枭兽倒下。"},{t="清空思绪",b="马克霍尔给出的狩猎建议是清空脑中杂念，与荒野融为一体。枭兽就出没在辛特兰的荒野中。"},{t="马克霍尔的评判",b="狩猎结束后，马克霍尔将你称为恶齿部族值得信赖的朋友。"}},faq={{q="谁发布了这项狩猎任务？",a="来自辛特兰恶齿村的猎户马克霍尔。",al={"谁发布了猎杀野蛮生物任务","猎杀野蛮生物任务发布者","猎户马克霍尔任务"}},{q="为什么马克霍尔想要杀死这些野蛮的枭兽？",a="马克霍尔称它们非常暴躁，并表示这些枭兽已经用它们的利爪和尖喙夺去了许多优秀恶齿战士的生命。",al={"为什么要杀野蛮枭兽","猎杀枭兽的原因","为什么要猎杀野蛮生物"}},{q="在哪里可以找到这些野蛮的枭兽？",a="马克霍尔说它们栖息在辛特兰的荒野中。",al={"野蛮枭兽位置","野蛮枭兽在哪里","辛特兰的枭兽"}},{q="必须杀死多少只野蛮的枭兽？",a="二十只野蛮的枭兽。",al={"要杀多少只枭兽","猎杀野蛮生物要求"}}},fp="16,172,15.335.0,17.143.0,18.67.1,21.65.0,50.109.0,40.49.0,40.24.0"}
P.entries["quest:783"] = {n="身边的危机",s="“内在的威胁”标志着响应暴风城号召的保卫者在北郡山谷服役的开始。新兵们被指引前往北郡修道院去见治安官玛克布莱德，他们会发现王国的军队在海外兵力分散，导致当地驻军在没有平民协助的情况下无法应对国内的麻烦。",h="“内在的威胁”标志着响应暴风城号召的保卫者在北郡山谷服役的开始。新兵们被指引前往北郡修道院去见治安官玛克布莱德，他们会发现王国的军队在海外兵力分散，导致当地驻军在没有平民协助的情况下无法应对国内的麻烦。",kw={"内在的威胁","修道院","艾尔文森林","治安官玛克布莱德","北郡","招募","暴风城卫兵","志愿者"},ang={["faction:Alliance"]="这个任务强调了大联盟所面临的压力：在遥远的领土上维持军事承诺，使得即使是最安全的中心地带也容易受到内部崩溃的影响。",["race:Human"]="由于北郡是人类保卫者的起始山谷，响应治安官玛克布莱德的召唤代表了你保护家园和暴风城王国的第一次正式誓约。"},sec={{t="国力吃紧的王国",b="北郡山谷曾经是一个专注于祈祷、耕作和修道研究的宁静避风港。如今，它成为了防御艾尔文森林内部动乱的第一道防线。暴风城的正规军被广泛部署在遥远的前线，导致首都中心地带兵力严重不足。由于当地驻扎的正式士兵很少，暴风城卫兵必须招募任何到达修道院大门的志愿新兵。"},{t="治安官的召唤",b="在北郡修道院内，治安官玛克布莱德在日益增长的区域压力下协调着山谷的防御。当外来的威胁从远方威胁着联盟时，无法无天的强盗、成群的害虫和地下的怪物正利用权力真空，就在王国的家门口兴风作浪。响应这一召唤将使新兵立即投入军事服役，从清理修道院周边的威胁开始，进而对抗在整个艾尔文扎根的更深层的腐败。"}},faq={{q="这个任务的目的是什么？",a="它是为北郡山谷新到的新兵准备的入门召唤。你的指示是走进北郡修道院，直接向治安官玛克布莱德报告，加入当地的防御工作。",al={"内在的威胁任务","这是什么任务","北郡入门任务"}},{q="谁是治安官玛克布莱德？",a="治安官玛克布莱德是驻扎在北郡修道院的暴风城卫兵的高级军官。他负责监督山谷的防御，协调新兵，并分配任务以遏制出现在周边乡村的威胁。",al={"治安官玛克布莱德","谁是玛克布莱德","修道院指挥官"}},{q="为什么暴风城要招募志愿者而不是派遣正规士兵？",a="暴风城的常备军已被部署到海外进行远征，以保护联盟的利益。这种繁重的海外任务使中心地带的驻军严重人手不足，迫使当地指挥官不得不依靠新到的冒险者和志愿者来保卫自己的家园。",al={"为什么要招募志愿者","卫兵在哪里","为什么暴风城兵力不足"}},{q="目前有什么威胁在困扰着北郡山谷？",a="山谷正面临着多重压力：侵扰附近矿山和山丘的残暴狗头人，骚扰周边葡萄园的患病或掠食性害虫，以及利用当地驻军空虚而组织起来的强盗团伙。",al={"山谷威胁","什么在攻击北郡","北郡的问题"}},{q="这个任务接下来会引向哪里？",a="向治安官玛克布莱德报告后，将在北郡周边开启几项紧迫的任务，指引新兵清除山丘中的狗头人入侵，帮助当地的农民和工人，并调查日益猖獗的有组织的强盗。",al={"下一个任务","“内在的威胁”之后是什么","玛克布莱德的后续任务"}},{q="为什么北郡修道院被用作军事指挥所？",a="虽然北郡修道院是一个专注于学习和信仰的神圣场所，但其坚固的石墙和中心位置使其成为山谷中唯一实用的行动基地。随着当地行政力量的紧张，暴风城卫兵直接在其大厅内建立了行政指挥部。",al={"为什么修道院有军队","北郡教堂军队","神圣修道院士兵"}}},fp="15,247,24.347.0,18.360.0,34.131.0,23.173.0,75.173.0,54.175.0,37.171.0,62.226.0"}
P.entries["quest:7830"] = {n="死者的复仇",s="恶齿村的猎户马克霍尔说，蛮锤部族训练狮鹫来猎杀巨魔，因此他想要除掉该地区的狮鹫长者——天空领主。你必须杀死一只锋喙天空领主，并将它的羽毛带回来给他。",h="恶齿村的猎户马克霍尔说，蛮锤部族训练狮鹫来猎杀巨魔，因此他想要除掉该地区的狮鹫长者——天空领主。你必须杀死一只锋喙天空领主，并将它的羽毛带回来给他。",kw={"复仇之怒","狮鹫","辛特兰","猎户马克霍尔","锋喙天空领主","恶齿村","天空领主羽毛","蛮锤部族"},sec={{t="猎杀天空领主",b="辛特兰恶齿村的猎户马克霍尔对蛮锤部族训练狮鹫猎杀巨魔的行为感到愤恨。他发誓要让对方付出代价，但首先，他希望你先对该地区的狮鹫长者“天空领主”下手。杀掉一只并带回它的羽毛。锋喙天空领主是一种稀有品种，通常出没于辛特兰的荒野中，马克霍尔认为正是它们繁育了这些凶残的后代。"},{t="羽毛鉴定",b="马克霍尔仔细端详着那根羽毛，大声感叹着这头野兽在被你除掉之前，到底吞食了多少猎人。"}},faq={{q="谁提供这个任务？",a="猎户马克霍尔在辛特兰的恶齿村提供此任务。",al={"任务发布者","谁发布了复仇之怒","马克霍尔位置"}},{q="为什么猎户马克霍尔要猎杀天空领主？",a="马克霍尔说蛮锤部族训练狮鹫猎杀巨魔，所以他想要根除该地区的天空领主。他声称锋喙天空领主是一种繁育凶残后代的稀有品种。",al={"为什么要杀锋喙天空领主","为什么要杀天空领主","为什么要猎杀狮鹫"}},{q="在哪里可以找到锋喙天空领主？",a="马克霍尔说这种稀有品种通常出没于辛特兰的荒野中。",al={"天空领主位置","锋喙天空领主在哪里","天空领主羽毛位置"}},{q="必须带什么东西回给马克霍尔？",a="杀死一只锋喙天空领主，并将它的羽毛带回给马克霍尔。",al={"我需要什么物品","复仇之怒任务目标","天空领主掉落"}}},fp="19,229,20.422.0,18.119.1,21.67.0,47.206.0,39.67.0,37.62.0"}
P.entries["quest:7833"] = {n="捐献毛料",s="一名暗矛巨魔正在募集毛料。你捐出的六十块毛料，将在他人相助下帮助完成募集。",h="一名暗矛巨魔正在募集毛料。你捐出的六十块毛料，将在他人相助下帮助完成募集。",kw={"收集","暗矛","捐赠","储备","巨魔","羊毛","毛料"},sec={{t="共同募集",b="暗矛巨魔正在募集毛料，收集者现在可以接收你捐出的六十块毛料。他们的储备需要你提供这些毛料；预计还会有其他人相助，完成募集。"}},faq={{q="正在收集什么？",a="暗矛巨魔正在募集毛料。",al={"需要什么","捐赠毛料"}},{q="他们需要我提供多少毛料？",a="收集者请你提供六十块毛料。",al={"需要多少毛料","六十块毛料"}},{q="巨魔为什么要收集毛料？",a="收集这些毛料是为了补充他们的储备。",al={"为何要毛料","有何用途"}},{q="我现在可以交出毛料吗？",a="收集者现在可以接收你捐出的六十块毛料。",al={"哪里交毛料","现在捐赠"}}},fp="18,138,19.196.0,24.47.0,41.59.0,35.50.0,25.61.0"}
P.entries["quest:7839"] = {n="邪枝窃贼",s="恶齿村的铁匠斯拉提说恶齿巨魔入侵了村子并偷走了他的工具。他虽然还有备用工具，但被偷走的那套工具是一位好心的侏儒送给他的礼物，那名侏儒在他还是个年轻兽人时救过他的命，他希望能找回那套工具。",h="恶齿村的铁匠斯拉提说恶齿巨魔入侵了村子并偷走了他的工具。他虽然还有备用工具，但被偷走的那套工具是一位好心的侏儒送给他的礼物，那名侏儒在他还是个年轻兽人时救过他的命，他希望能找回那套工具。",kw={"亚戈瓦萨","辛特兰","玛戈尔","恶齿村","沙尔瓦萨","隐匿石","斯拉提丢失的工具","铁匠斯拉提","恶齿"},sec={{t="一份侏儒的礼物",b="恶齿巨魔入侵了恶齿村，偷走了铁匠斯拉提的工具。虽然他有备用工具，但被偷走的那套是曾在他年轻时救过他性命的一位好心侏儒所赠。他告诉你这套工具对他意义非凡，并请求你帮他找回来。"},{t="工具可能所在之处",b="斯拉提说玛戈尔报告说在辛特兰东北部的亚戈瓦萨和沙尔瓦萨神庙附近看到了这些工具。他还让你去隐匿石搜寻一下，并警告说该地区的恶齿巨魔凶残成性，极其危险。"}},faq={{q="为什么这些被偷的工具对铁匠斯拉提如此重要？",a="这套工具是一位好心的侏儒送给他的礼物，那名侏儒在他还是个年轻兽人时救过他的命。虽然他还有备用工具，但他表示这套对他来说意义非凡。",al={"为什么斯拉提在意他的工具","斯拉提丢失工具背景故事","为什么斯拉提的工具很特别"}},{q="是谁从恶齿村偷走了工具？",a="恶齿巨魔入侵了村子并偷走了铁匠斯拉提的工具。",al={"谁拿走了工具","谁偷了斯拉提的工具"}},{q="丢失的工具被带到了哪里？",a="玛戈尔在辛特兰东北部的亚戈瓦萨和沙尔瓦萨神庙附近看到了它们。斯拉提还让你去隐匿石搜寻一下。",al={"斯拉提的工具在哪里","去哪里寻找工具","斯拉提的工具位置"}},{q="是谁在袭击发生后报告看到了这些工具？",a="玛戈尔将工具可能所在的消息告诉了斯拉提。",al={"谁看到了工具","谁报告了被盗工具"}}},fp="20,243,19.273.0,25.258.0,58.157.0,43.71.0,35.141.0,45.74.0"}
P.entries["quest:784"] = {n="背信弃义的人类",s="“消灭背叛者”是一项由剃刀岭的加索克下达的部落军事突袭行动，旨在从人类入侵者手中夺回提拉加德城堡。本尼迪克特中尉麾下的库尔提拉斯军队重新占领了这座要塞，直接破坏了杜隆塔尔与塞拉摩之间脆弱的和平。消灭他们的驻军对于保卫兽人故乡的东海岸至关重要。",h="“消灭背叛者”是一项由剃刀岭的加索克下达的部落军事突袭行动，旨在从人类入侵者手中夺回提拉加德城堡。本尼迪克特中尉麾下的库尔提拉斯军队重新占领了这座要塞，直接破坏了杜隆塔尔与塞拉摩之间脆弱的和平。消灭他们的驻军对于保卫兽人...",kw={"戴林·普罗德摩尔","杜隆塔尔","加索克","库尔提拉斯","本尼迪克特中尉","海军陆战队","剃刀岭","水兵","提拉加德城堡","消灭背叛者"},ang={["faction:Horde"]="库尔提拉斯人对提拉加德城堡的占领是一场发生在杜隆塔尔家门口的持续战争。清除本尼迪克特的军队证明了部落有能力保卫其新建立的家园，抵御外来舰队的侵犯。",["race:Orc"]="兽人尊重在海加尔山与吉安娜达成的停战协议，但库尔提拉斯人却带来了第二次战争的苦涩回忆。击退本尼迪克特的海军陆战队关乎生存与祖先的荣耀。",["race:Troll"]="提拉加德城堡的位置距离暗矛部族的定居点森金村过近，令人不安。扫荡这些敌对的水兵可以直接保护巨魔脆弱的新家园。"},sec={{t="破碎的停战协议",b="当萨尔率领部落横跨无尽之海来到卡利姆多时，他与吉安娜·普罗德摩尔女士结成了不稳定的联盟，以在海加尔山击败燃烧军团。然而当吉安娜疏远的父亲，戴林·普罗德摩尔海军上将带着强大的库尔提拉斯舰队到来时，和平便荡然无存。海军上将将旧部落的所有暴行归咎于全体兽人，他入侵了杜隆塔尔并占领了包括提拉加德城堡在内的沿海据点。尽管戴林最终在塞拉摩被杀，但他舰队的残部拒绝履行任何条约，也不愿放弃他们的仇恨。"},{t="本尼迪克特的卷土重来",b="在海军上将陨落后，提拉加德城堡曾一度被击溃，但本尼迪克特中尉麾下的库尔提拉斯预备队此后又夺回了这座要塞。从这个位于剃刀岭和森金村之间的坚固堡垒出发，这些水兵和海军陆战队员不断袭扰过往旅人，并威胁着东部的海上航线。加索克认为他们根深蒂固的据点直接威胁到了杜隆塔尔的安全，因此号召部落勇士直接打击本尼迪克特的指挥部。"}},faq={{q="为什么库尔提拉斯人类要攻击杜隆塔尔？",a="他们是戴林·普罗德摩尔海军上将指挥的远征舰队的残部。这位上将拒绝接受人类与兽人之间的和平共存，一心想要彻底根除杜隆塔尔。即便在他死后，他的忠实拥护者们依然无视部落，继续盘踞在像提拉加德城堡这样的沿海据点中。",al={"为什么人类在杜隆塔尔","库尔提拉斯攻击","提拉加德城堡人类背景故事"}},{q="本尼迪克特中尉是谁？",a="本尼迪克特中尉是目前占据提拉加德城堡的库尔提拉斯预备队的指挥官。在普罗德摩尔海军上将战败后，本尼迪克特召集了幸存的海军陆战队员和水兵，夺回了这座沿海堡垒，并持续对兽人发动袭击。",al={"本尼迪克特是谁","本尼迪克特中尉背景故事","提拉加德城堡领袖"}},{q="吉安娜·普罗德摩尔支持这些人吗？",a="不支持。吉安娜与萨尔酋长签署了相互生存的条约，并积极反对她父亲的侵略性远征，以维护和平。占据提拉加德城堡的部队是库尔提拉斯的叛乱残部，他们拒绝塞拉摩的外交政策，并将吉安娜的停战协议视为背叛行为。",al={"吉安娜支持他们吗","塞拉摩库尔提拉斯联盟","吉安娜·普罗德摩尔提拉加德"}},{q="为什么称他们为“背叛者”？",a="加索克认为他们是背叛者，因为他们的入侵直接违背了萨尔与吉安娜·普罗德摩尔为在第三次战争中击败阿克蒙德而达成的外交共识。他们在部落领土上的持续军事存在，公然挑衅了战后在卡利姆多确立的边界。",al={"为什么是背叛者","谁背叛了谁","背叛者含义"}},{q="提拉加德城堡位于哪里？",a="提拉加德城堡位于杜隆塔尔的东海岸，剃刀岭以南，森金村的东北方。它高耸的石墙俯瞰着沿海海域，为入侵者提供了一个靠近部落定居点的战略基地。",al={"提拉加德城堡位置","提拉加德城堡在哪里","去哪里找本尼迪克特"}}},fp="22,203,17.455.0,21.411.0,43.279.0,27.252.0,43.253.0,32.269.0,32.219.0"}
P.entries["quest:7840"] = {n="拉尔德的午餐",s="住在辛特兰恶齿村的拉德又饿又怕。拉德在一次独自野餐时遭到了邪枝巨魔的袭击，惊慌中丢下午餐逃跑了。有人委托你从北边的一座岛屿上把午餐找回来。",h="住在辛特兰恶齿村的拉德又饿又怕。拉德在一次独自野餐时遭到了邪枝巨魔的袭击，惊慌中丢下午餐逃跑了。有人委托你从北边的一座岛屿上把午餐找回来。",kw={"辛特兰","岛屿","拉德","午餐","野餐","恶齿村","邪枝"},sec={{t="中断的野餐",b="拉德在一个秘密地点野餐时，被一个邪枝巨魔袭击了——按拉德的话说，那个巨魔又丑又坏，还用一根大棍子打了他。拉德落荒而逃回了恶齿村，把午餐留在了原地。现在拉德又饿又怕，不敢回去。"},{t="北方的岛屿",b="野餐地点位于北边的一座岛屿上。拉德希望你能去那里找到他的午餐并带回来，同时要小心那些邪枝巨魔。"},{t="拉德的感谢",b="这份午餐竟然是一大块肉。拉德狼吞虎咽地吃了个精光，向你表示感谢，并承诺给你一个特别的野餐篮作为回报。"}},faq={{q="谁是拉德？",a="辛特兰恶齿村的居民，因为被邪枝巨魔用大棍子袭击而又饿又怕。",al={"拉德 辛特兰","谁是拉德","拉德 恶齿村"}},{q="拉德在哪里丢了他的午餐？",a="在北边一座岛屿上的秘密野餐点。",al={"拉德的午餐在哪里","拉德的野餐点","拉德的秘密地点"}},{q="拉德为什么丢下他的食物？",a="在野餐时被一个邪枝巨魔用大棍子打了一下，拉德没带午餐就跑回了恶齿村。",al={"拉德为什么逃跑","谁攻击了拉德"}},{q="在岛上应该提防什么？",a="拉德说岛上的危险是邪枝巨魔。",al={"岛上的邪枝巨魔","拉德岛上的危险"}}},fp="19,213,20.211.0,20.153.0,13.136.1,12.114.0,30.50.0,35.107.0,44.61.0"}
P.entries["quest:7841"] = {n="给蛮锤部族的警告",s="在辛特兰的恶齿村，奥索·莫吉克声称蛮锤部族正在与巨魔的敌人做交易，而这一次，高等精灵成为了他们的伙伴。奥索想要将一条用奎尔丹尼小屋的高谷高等精灵的鲜血写成的讯息送给蛮锤矮人。",h="在辛特兰的恶齿村，奥索·莫吉克声称蛮锤部族正在与巨魔的敌人做交易，而这一次，高等精灵成为了他们的伙伴。奥索想要将一条用奎尔丹尼小屋的高谷高等精灵的鲜血写成的讯息送给蛮锤矮人。",kw={"高谷","辛特兰","给蛮锤的讯息","奥索·莫吉克","奎尔丹尼小屋","恶齿村","蛮锤"},sec={{t="血的讯息",b="蛮锤部族正在与巨魔的敌人建立新的盟约，而这一次高等精灵成为了他们的伙伴。奥索·莫吉克对这种想法嗤之以鼻。必须要给那些矮人一点颜色看看，用他们新朋友的鲜血写下讯息：杀掉你遇到的每一个高谷高等精灵，并将尸体留下作为警告。高谷先驱者、斥候、神射手和游侠都聚集在辛特兰西北部的奎尔丹尼小屋。"},{t="恶齿村的传闻",b="当你回来时，奥索宣称恶齿部族也在建立新的盟约，并称赞了你的工作。"}},faq={{q="谁提供这个任务？",a="奥索·莫吉克，他就在恶齿村。",al={"谁给予给蛮锤的讯息任务","奥索·莫吉克任务"}},{q="高谷高等精灵位于何处？",a="他们聚集在辛特兰西北部的奎尔丹尼小屋。",al={"奎尔丹尼小屋位置","高谷精灵在哪里","去哪里找高谷斥候"}},{q="为什么奥索·莫吉克想要攻击那些高等精灵？",a="奥索说蛮锤部族正在与巨魔的敌人做交易，现在他们又在与高等精灵合作。奥索想要将一条用高等精灵的鲜血写成的讯息送给蛮锤矮人。",al={"为什么要攻击奎尔丹尼","为什么要杀死辛特兰的高等精灵"}},{q="奥索想要屠杀哪些高谷精灵？",a="奎尔丹尼小屋的高谷先驱者、斥候、神射手和游侠。",al={"哪些高谷精灵","高谷神射手","高谷游侠"}}},fp="25,280,18.421.0,25.107.1,22.46.0,42.63.0,51.208.0,48.70.0"}
P.entries["quest:7842"] = {n="又一个给蛮锤部族的警告",s="在第一条信息之后，恶齿村的奥索·莫吉克说蛮锤部族和他们的狮鹫就像巨魔和他们的伴侣一样亲密。真恶心，但可以利用这一点来对付他们。奥索想要杀死辛特兰的狮鹫以获取它们的羽毛。",h="在第一条信息之后，恶齿村的奥索·莫吉克说蛮锤部族和他们的狮鹫就像巨魔和他们的伴侣一样亲密。真恶心，但可以利用这一点来对付他们。奥索想要杀死辛特兰的狮鹫以获取它们的羽毛。",kw={"狮鹫","辛特兰","修长的羽毛","奥索·莫吉克","恶齿村","蛮锤部族"},sec={{t="羽毛的讯息",b="在对付了高谷高等精灵之后，奥索·莫吉克还有另一条信息要传达。据说蛮锤部族和他们的狮鹫就像巨魔和他们的伴侣一样亲密，奥索觉得这很恶心，但很有用。杀死你在辛特兰遇到的狮鹫，并收集它们的修长的羽毛。据了解，狮鹫生活在那里的每一个地区。奥索将用这些羽毛制作出最后的信息。"},{t="奥索的乐趣",b="奥索希望最后的信息能把蛮锤部族吓跑，或者让他们变得非常非常愤怒。奥索很高兴，因为在让蛮锤部族明白巨魔不可招惹之前，只剩下最后一步了。"}},faq={{q="谁发布了这个任务？",a="奥索·莫吉克，他站在恶齿村。",al={"谁发布了致蛮锤部族的另一条讯息","另一条讯息任务发布者","奥索·莫吉克"}},{q="为什么奥索·莫吉克想要狮鹫羽毛？",a="奥索说蛮锤部族和他们的狮鹫就像巨魔和他们的伴侣一样亲密，他想利用这一点来对付他们。这些羽毛将用于最后的信息。",al={"为什么需要狮鹫羽毛","为什么要杀死辛特兰的狮鹫"}},{q="在哪里可以找到狮鹫？",a="据了解，狮鹫生活在辛特兰的每一个地区。",al={"辛特兰狮鹫位置","辛特兰的狮鹫在哪里"}},{q="在这条信息之前发生了什么？",a="它紧随“致蛮锤部族的讯息”之后，在那个任务中，奥索为了给矮人一个警告，屠杀了高谷高等精灵。",al={"致蛮锤部族的另一条讯息的前置任务","致蛮锤部族的讯息任务线"}}},fp="33,244,21.388.0,15.199.1,21.46.0,44.160.0,28.62.0,30.116.0"}
P.entries["quest:7843"] = {n="给蛮锤部族的最后警告",s="奥索·莫吉克给了你一根浸透了鲜血、系着狮鹫羽毛的长矛。你需要把它带到位于辛特兰西部的鹰巢山，并将其插在镇中心水井旁的土地上。",h="奥索·莫吉克给了你一根浸透了鲜血、系着狮鹫羽毛的长矛。你需要把它带到位于辛特兰西部的鹰巢山，并将其插在镇中心水井旁的土地上。",kw={"鹰巢山","狮鹫羽毛","辛特兰","奥索·莫吉克","恶齿村","长矛","蛮锤"},sec={{t="送给鹰巢山的矛",b="继“给蛮锤的另一个口信”之后，奥索·莫吉克给了你最后的口信：一根浸透了鲜血、系着狮鹫羽毛的长矛。带着它前往鹰巢山，把它插在城镇正中心的水井旁边，让那些矮人知道巨魔是动真格的。奥索希望你能活着回来，并警告你蛮锤矮人和喧闹的联盟成员会非常愤怒。"},{t="奥索的希望",b="奥索希望能亲眼看到那些矮人的表情，并大声猜测他们是否正在收拾行装准备离开。奥索承诺会为你完成这一壮举提供丰厚的奖励。"}},faq={{q="是谁让你去插这根长矛的？",a="奥索·莫吉克，他就在恶齿村。",al={"任务发布者","谁发布任务","奥索·莫吉克"}},{q="长矛必须插在哪里？",a="在辛特兰西部的鹰巢山，镇中心的水井旁边。",al={"长矛位置","我该把长矛放在哪里","鹰巢山水井"}},{q="这最后的口信是由什么构成的？",a="一根浸透了鲜血、系着狮鹫羽毛的长矛。",al={"长矛是什么","狮鹫羽毛长矛","最后的口信物品"}},{q="这个任务链的前序是什么？",a="它是“给蛮锤的另一个口信”的后续，在那个任务中，奥索要求收集狮鹫羽毛来制作这最后的口信。",al={"前置任务","先决条件","蛮锤口信任务链"}}},fp="35,215,22.361.0,11.167.1,33.46.0,32.75.0,34.56.0,35.115.0"}
P.entries["quest:7844"] = {n="野蛮的亲戚",s="恶齿村的秘法师雅尔金称邪枝巨魔是一群堕落之徒，他们以其他巨魔和类人生物为食。由于祖尔金不在那里消灭他们，她请求你去消灭东北偏北方向神庙附近的邪枝剥皮者和邪枝占卜师。",h="恶齿村的秘法师雅尔金称邪枝巨魔是一群堕落之徒，他们以其他巨魔和类人生物为食。由于祖尔金不在那里消灭他们，她请求你去消灭东北偏北方向神庙附近的邪枝剥皮者和邪枝占卜师。",kw={"亚戈瓦萨","同宗相食","秘法师雅尔金","恶齿村","剥皮者","沙尔瓦萨","占卜师","邪枝巨魔","祖尔金"},sec={{t="同宗相食",b="辛特兰生活着三个巨魔部族，秘法师雅尔金说，除了同在这一片土地上的巨魔之外，他们几乎没有什么共同点。她称邪枝巨魔（名字十分贴切）是一群以其他巨魔和类人生物为食的堕落之徒。祖尔金本可以轻易地将他们消灭，但祖尔金并不在那里，恶齿部族只能自谋生路。"},{t="邪枝巨魔的聚集地",b="雅尔金请求你去消灭邪枝剥皮者和邪枝占卜师，他们就在辛特兰东北偏北的沙尔瓦萨和亚戈瓦萨神庙附近。"},{t="雅尔金的赞许",b="当你回来时，雅尔金声称，即使是祖尔金也无法做得更好了。"}},faq={{q="谁提供这个任务？",a="站在恶齿村的秘法师雅尔金。",al={"同宗相食任务发布者","谁发布同宗相食","秘法师雅尔金"}},{q="为什么雅尔金想要消灭邪枝巨魔？",a="她称邪枝巨魔是一群以其他巨魔和类人生物为食的堕落之徒，并说清理该地区的污秽是你的职责。",al={"恶齿为什么与邪枝开战","邪枝巨魔的食人行为","恶齿与邪枝的冲突"}},{q="在哪里可以找到邪枝巨魔？",a="在辛特兰东北偏北的沙尔瓦萨和亚戈瓦萨神庙周围。",al={"沙尔瓦萨位置","亚戈瓦萨位置","邪枝占卜师在哪里"}},{q="雅尔金想要消灭哪些邪枝巨魔？",a="邪枝剥皮者和邪枝占卜师。",al={"同宗相食任务目标","同宗相食任务要杀谁"}},{q="祖尔金在哪里？",a="目前不在辛特兰。雅尔金说如果祖尔金在那里，他会轻易地消灭邪枝巨魔，但他并不在，所以恶齿部族只能自谋生路。",al={"祖尔金在这里吗","祖尔金在辛特兰的什么位置","祖尔金现状"}}},fp="21,258,22.361.0,27.176.0,17.79.1,22.49.0,48.137.0,41.86.0,46.47.0,17.180.0"}
P.entries["quest:7845"] = {n="被绑架的断齿长者！",s="恶齿村的断齿族长说，邪枝巨魔在深夜突袭，带走了她的配偶断齿长者。间谍报告说他还活着，被囚禁在辛萨罗之巅，她请求你去救他。",h="恶齿村的断齿族长说，邪枝巨魔在深夜突袭，带走了她的配偶断齿长者。间谍报告说他还活着，被囚禁在辛萨罗之巅，她请求你去救他。",kw={"断齿长者","哈卡","海克斯","辛特兰","辛萨罗","断齿族长","恶齿","邪枝巨魔"},sec={{t="深夜突袭",b="邪枝巨魔在午夜袭击了恶齿村，掳走了断齿长者，也就是断齿族长的配偶。她的间谍称他还活着，被关在辛萨罗，那是位于辛特兰南部的邪枝巨魔之都。断齿族长担心村子无法承受失去他的后果。"},{t="无面嗜血神",b="有消息称，邪枝祭司海克斯正准备将俘虏献祭给哈卡，那位无面嗜血神。"},{t="一旦你找到他",b="找到长者后，他会催促你快点行动，因为守卫肯定已经察觉到你的到来了。"}},faq={{q="是谁掳走了断齿长者？",a="邪枝巨魔在一次大胆的午夜袭击中掳走了他，袭击的目标是恶齿村。",al={"谁绑架了断齿长者","谁带走了断齿长者","断齿长者的绑架者"}},{q="断齿长者被关在哪里？",a="她的间谍称，他被关押在辛萨罗之巅，那是位于辛特兰南部的邪枝巨魔之都。",al={"断齿长者的位置","断齿长者在哪里","断齿长者被囚禁在哪里"}},{q="断齿长者在辛萨罗之巅面临怎样的命运？",a="有消息称，邪枝祭司海克斯正准备将他献祭给哈卡，那位无面嗜血神。",al={"为什么断齿长者被俘","邪枝巨魔想要对断齿长者做什么","海克斯献祭断齿长者"}},{q="断齿族长是谁？",a="断齿族长是断齿长者的配偶，她请求你去救他。",al={"谁是断齿族长","断齿族长的配偶"}}},fp="25,211,15.283.0,22.101.0,18.100.1,24.73.0,35.103.0,49.93.0,23.76.0"}
P.entries["quest:7846"] = {n="找回钥匙！",s="断齿长者被囚禁在辛萨罗的枷锁之中。他说看守者希塔亚持有他束缚的钥匙，就在附近守卫森严的洞穴里。他请求你杀了她，取回钥匙。",h="断齿长者被囚禁在辛萨罗的枷锁之中。他说看守者希塔亚持有他束缚的钥匙，就在附近守卫森严的洞穴里。他请求你杀了她，取回钥匙。",kw={"断齿长者","辛特兰","看守者希塔亚","辛萨罗","取回钥匙","恶齿部族","枷锁钥匙"},sec={{t="看守者的洞穴",b="在“被绑架的断齿长者！”之后，你在辛萨罗发现了被枷锁捆住的断齿长者。看守者希塔亚持有他束缚的钥匙，就在附近守卫森严的洞穴里。断齿长者请求你杀了她，取回钥匙来解开他的枷锁，只有这样他才能回家。"},{t="断齿长者的感谢",b="拿着钥匙，断齿长者站了起来。他感谢了你，并说恶齿部族会铭记你的功绩。"}},faq={{q="谁持有断齿长者枷锁的钥匙？",a="看守者希塔亚持有钥匙。断齿长者说她在附近的洞穴里，并且被严密守卫着。",al={"谁有钥匙","看守者希塔亚","枷锁钥匙在哪里"}},{q="断齿长者被关在哪里？",a="断齿长者被关在辛萨罗。",al={"断齿长者在哪里","断齿长者位置","辛萨罗断齿长者"}},{q="为什么断齿长者需要这把钥匙？",a="这把钥匙可以打开他身上的枷锁。他说，只有这样他才能重获自由并回家。",al={"为什么要枷锁钥匙","钥匙有什么用"}}},fp="16,194,17.293.0,23.114.1,47.101.0,29.38.0,37.95.0"}
P.entries["quest:7847"] = {n="向断齿族长复命",s="断齿长者请求你回到恶齿村他的配偶，断齿族长身边，告诉她他正要回家。",h="断齿长者请求你回到恶齿村他的配偶，断齿族长身边，告诉她他正要回家。",kw={"断齿长者","辛特兰","辛萨罗","断齿族长","恶齿","恶齿村"},sec={{t="给他配偶的消息",b="断齿长者已经摆脱了束缚，他请求你回到恶齿村。你必须去那里告诉他的配偶，断齿族长，他正要回家。"},{t="村庄的感激",b="断齿族长说你为恶齿巨魔做了巨大的贡献，整个村庄都对你感激不尽。"}},faq={{q="谁派你踏上这段旅程的？",a="断齿长者请求你将他获救的消息带给他的配偶。",al={"谁开启了回到断齿族长身边","断齿长者任务发布者"}},{q="断齿族长在哪里？",a="断齿族长位于辛特兰的恶齿村。",al={"断齿族长在哪里","断齿族长位置","回到断齿族长身边的交任务地点"}},{q="我该告诉断齿族长什么？",a="告诉她断齿长者正要回家。",al={"要告诉断齿族长什么","断齿消息"}},{q="这段旅程之前发生了什么？",a="这是在“取回钥匙！”之后进行的任务，而之前的努力始于“被绑架的断齿长者！”",al={"前置任务","断齿族长任务链"}}},fp="25,121,17.160.0,23.112.1,30.68.0,33.59.0,43.35.0,30.93.0"}
P.entries["quest:7849"] = {n="分离的痛苦",s="恶齿村的猎户马克霍尔失去了他的孪生兄弟马尔霍尔。那次袭击中，邪枝巨魔不仅掳走了托恩塔斯克的配偶，也抓走了马尔霍尔。马尔霍尔遭遇了残酷而迅速的死亡，他的遗骸被邪枝巨魔喂给了软泥怪和狼群。马克霍尔说他兄弟的生命已无法挽回，但他的灵魂尚可救赎，因此他请求你帮他找回遗骸。",h="恶齿村的猎户马克霍尔失去了他的孪生兄弟马尔霍尔。那次袭击中，邪枝巨魔不仅掳走了托恩塔斯克的配偶，也抓走了马尔霍尔。马尔霍尔遭遇了残酷而迅速的死亡，他的遗骸被邪枝巨魔喂给了软泥怪和狼群。马克霍尔说他兄弟的生命已无法挽回，但...",kw={"骨头","辛特兰","辛萨罗","马尔霍尔","马克霍尔","恶齿","头骨","邪枝","亚约金"},sec={{t="孪生兄弟的损失",b="马克霍尔说，村里有许多人都在荒野中失去了挚爱，他失去的亲人就是他的孪生兄弟马尔霍尔。邪枝巨魔在袭击托恩塔斯克的配偶时也带走了马尔霍尔。马尔霍尔命中注定难逃一劫，他的俘虏们残忍地杀害了他。"},{t="遗骸所在之处",b="邪枝巨魔把马尔霍尔剩下的残骸喂给了他们的软泥怪和狼群。辛萨罗神庙顶部附近有一个充斥着软泥怪的垃圾坑，还有一个狼穴。他的骨头就在顶层附近的一个淤泥坑里，而他的头骨则位于神庙的最顶层。马克霍尔打算把这些遗骸带给亚约金，由他来准备安葬事宜。"}},faq={{q="猎户马尔霍尔是谁？",a="马尔霍尔是猎户马克霍尔的孪生兄弟。邪枝巨魔在袭击托恩塔斯克的配偶时也带走了他，并残酷地杀害了他。",al={"马尔霍尔是谁","马克霍尔的兄弟","马尔霍尔背景故事"}},{q="马尔霍尔的遗骸被带到了哪里？",a="邪枝巨魔把他的遗骸喂给了软泥怪和狼群。他的头骨就在辛萨罗的最顶层，而他的骨头则在顶层附近的一个淤泥坑里。",al={"骨头在哪里","马尔霍尔的头骨在哪里","辛萨罗遗骸"}},{q="谁来为马尔霍尔准备安葬？",a="马克霍尔说他会把遗骸带给亚约金，由他来准备安葬事宜。",al={"马尔霍尔的葬礼","亚约金是谁","亚约金"}},{q="为什么马克霍尔需要找回骨头？",a="马克霍尔知道无法再挽救他兄弟的生命，但他认为兄弟的灵魂尚可救赎。为了做到这一点，他希望找回那些遗骸。",al={"为什么要找回遗骸","拯救马尔霍尔的灵魂","拯救他的灵魂"}}},fp="18,361,13.263.0,21.369.0,25.159.0,35.158.0,36.93.0,41.141.0"}
P.entries["quest:7850"] = {n="黑暗之瓶",s="恶齿村的断齿族长说邪枝巨魔拥有超自然的狂暴力量，这是邪恶的女祭司赫克斯施展邪恶魔法的结果。在辛萨罗各处散落着被污染的鲜血容器，它们散发出属于无面血神的邪恶魔法。断齿族长请求你将它们偷回来，以便消除这些污染。",h="恶齿村的断齿族长说邪枝巨魔拥有超自然的狂暴力量，这是邪恶的女祭司赫克斯施展邪恶魔法的结果。在辛萨罗各处散落着被污染的鲜血容器，它们散发出属于无面血神的邪恶魔法。断齿族长请求你将它们偷回来，以便消除这些污染。",kw={"血神","暗影容器","辛萨罗","断齿族长","恶齿村","被污染的鲜血","邪恶的女祭司赫克斯","邪枝巨魔"},sec={{t="邪枝的狂暴",b="你在辛萨罗的任何地方行走，都会发现被污染的鲜血容器。它们散发出无面血神的黑暗力量，这增强了邪枝巨魔的力量并驱使他们陷入疯狂。断齿族长相信，取走这些容器并消除其中的污染，可以减弱血神对他们的控制。"},{t="归还容器之后",b="随着容器到手，控制邪枝巨魔的黑暗能量被解除了，尽管只是暂时的。断齿族长提醒你要时刻警惕邪恶，因为倒下的女祭司很快就会被别人取代。"}},faq={{q="谁发布了“暗影容器”任务？",a="由辛特兰恶齿村的断齿族长发布。",al={"谁发布暗影容器任务","暗影容器任务发布者"}},{q="被污染的容器在哪里？",a="被污染的鲜血容器可以在辛特兰的辛萨罗各处找到。",al={"暗影容器在哪里","被污染的鲜血容器位置","寻找被污染的鲜血"}},{q="为什么邪枝巨魔如此狂暴？",a="断齿族长认为是邪恶的女祭司赫克斯施展的邪恶魔法所致。被污染的鲜血容器也带有无面血神的力量，这增强了邪枝巨魔的力量并驱使他们发疯。",al={"为什么邪枝巨魔会疯狂","邪枝巨魔的疯狂","邪枝巨魔的狂暴"}},{q="断齿族长打算如何处理这些容器？",a="断齿族长计划消除其中的污染，以减弱无面血神对邪枝巨魔的控制。",al={"为什么要收集这些容器","鲜血容器会发生什么"}}},fp="12,353,19.303.0,24.210.1,33.66.0,38.85.0,43.203.0,54.113.0"}
P.entries["quest:786"] = {n="科卡尔半人马的进攻",s="“挫败科卡尔的侵略”是一项由侦察兵拉尔·猎齿在森金村附近发布的至关重要的部落防御任务。玩家的任务是潜入科卡尔峭壁，在半人马部族袭击杜隆塔尔初建的定居点之前，摧毁三份协调一致的入侵计划。",h="“挫败科卡尔的侵略”是一项由侦察兵拉尔·猎齿在森金村附近发布的至关重要的部落防御任务。玩家的任务是潜入科卡尔峭壁，在半人马部族袭击杜隆塔尔初建的定居点之前，摧毁三份协调一致的入侵计划。",kw={"杜隆塔尔","科卡尔","科卡尔峭壁","拉尔·猎齿","奥格瑞玛","森金村","挫败科卡尔的侵略","试炼谷"},ang={["faction:Horde"]="阻止科卡尔的进攻使新生的部落免于在其新家园的门口被迫进行一场艰苦的多线领土战争。",["race:Orc"]="试炼谷是年轻兽人举行成年仪式的地方，因此在那里发生的半人马侵略是对兽人战士文化的极大侮辱。",["race:Troll"]="暗矛巨魔本已失去了古老的岛屿家园，他们无法承担让森金村被劫掠的半人马淹没的代价。"},sec={{t="迫在眉睫的入侵",b="当拉尔·猎齿在杜隆塔尔西部进行侦察时，这名巨魔追踪者潜入了科卡尔峭壁。他所发现的情况令人震惊：科卡尔半人马不仅在进行无组织的沿海突袭，还在策划一场雄心勃勃的三路入侵，目标直指兽人和暗矛巨魔的家园。半人马军阀将他们的战斗策略分派给三位不同的首领，意图袭击试炼谷、森金村以及奥格瑞玛的大门本身。"},{t="突袭峡谷",b="为了避免在杜隆塔尔干燥的红色峡谷中爆发灾难性的战斗，新兵被派往科卡尔峭壁深处，擒贼先擒王。潜入尘土飞扬的营地并烧毁三份进攻卷轴，可以破坏半人马的指挥链。尽管拉尔·猎齿坚信部落必然能击溃任何全面入侵，但摧毁这些文件能让杜隆塔尔的守军免受代价高昂的流血牺牲，毕竟这个年轻的国度才刚刚站稳脚跟。"}},faq={{q="谁提供了“挫败科卡尔的侵略”这个任务？",a="该任务由拉尔·猎齿提供，他是一位驻扎在杜隆塔尔南部悬崖边、森金村外不远处的暗矛巨魔侦察兵。",al={"任务发布者","谁给任务","拉尔·猎齿位置"}},{q="科卡尔半人马计划袭击哪些目标？",a="科卡尔的作战计划概述了一场协调一致的三层进攻，目标分别为试炼谷、森金村和部落首都奥格瑞玛。",al={"半人马攻击目标","什么是进攻计划","三个目标"}},{q="科卡尔峭壁位于哪里？",a="科卡尔峭壁是一片被太阳炙烤的峡谷群，坐落在杜隆塔尔南部，从森金村翻过岩石山脊向西即可到达。",al={"科卡尔峭壁位置","峭壁在哪里","杜隆塔尔半人马村庄"}},{q="在峭壁内哪里可以找到进攻计划？",a="载有入侵蓝图的三份卷轴分别由驻守在峭壁各处不同营地的三位科卡尔首领保管。",al={"进攻计划地点","卷轴在哪里","半人马首领"}},{q="为什么科卡尔人想要入侵杜隆塔尔？",a="科卡尔是一个极具侵略性的扩张主义半人马部族，土生土长于卡利姆多的干燥土地上。他们视新来的兽人和暗矛巨魔为入侵者，认为他们侵犯了自己的领地和狩猎场。",al={"为什么半人马要攻击","半人马动机","科卡尔背景传说"}},{q="销毁计划后会发生什么？",a="摧毁这些文件可以阻止一场协调一致的围攻，使科卡尔的战术进攻陷入混乱，保护杜隆塔尔脆弱的定居点免受突如其来的毁灭。",al={"任务后续影响","半人马进攻是否停止"}}},fp="27,151,18.336.0,20.353.0,49.117.0,55.86.0,29.86.0,49.89.0,41.174.0,43.117.0"}
P.entries["quest:7861"] = {n="通缉：邪恶祭司海克斯和她的爪牙",s="断齿族长下令必须将邪恶的女祭司海克斯和她的爪牙绳之以法，任何击杀这位女祭司及其精英阿曼扎希卫兵的人都将获得丰厚的奖赏。你可以在辛特兰的辛萨罗之巅找到他们。",h="断齿族长下令必须将邪恶的女祭司海克斯和她的爪牙绳之以法，任何击杀这位女祭司及其精英阿曼扎希卫兵的人都将获得丰厚的奖赏。你可以在辛特兰的辛萨罗之巅找到他们。",kw={"阿曼扎希","海克斯","辛特兰","辛萨罗","断齿族长","恶齿村","邪恶的女祭司海克斯","邪恶枝族"},sec={{t="突袭辛萨罗",b="断齿族长下令必须将邪恶的女祭司海克斯和她的爪牙绳之以法。目标是女祭司本人以及她的精英阿曼扎希卫兵。他们就在辛特兰的辛萨罗之巅。一旦将其击杀，就回到恶齿村向断齿族长报告。"}},faq={{q="是谁发布了针对邪恶的女祭司海克斯的悬赏？",a="这份号召令由断齿族长下达，任何击杀女祭司及其卫兵的人都将获得丰厚的奖励。",al={"谁想要海克斯死","谁发布了这个悬赏","女祭司海克斯任务发布者"}},{q="在哪里可以找到邪恶的女祭司海克斯和她的卫兵？",a="他们在辛特兰的辛萨罗之巅。",al={"海克斯在哪里","邪恶的女祭司海克斯位置","阿曼扎希卫兵位置"}},{q="必须击杀谁才能完成悬赏？",a="邪恶枝族的女祭司海克斯本人，以及她的阿曼扎希精英卫兵。",al={"海克斯悬赏目标","杀谁来完成海克斯的任务"}},{q="在哪里交付悬赏？",a="在击杀女祭司和她的卫兵后，向恶齿村的断齿族长报告。",al={"海克斯悬赏在哪里交付","断齿族长位置"}}},fp="43,226,23.300.0,46.131.0,54.51.0,40.83.0,30.90.0"}
P.entries["quest:7862"] = {n="职位空缺：恶齿村卫兵队长",s="卫兵队长马尔科尔下落不明，恶齿村的卫兵部队需要一位新队长。任何有意担任此职的人都必须消灭邪枝狂战士、暗影猎手、饮血者和噬魂者，然后将申请书提交给位于辛特兰的断齿族长。",h="卫兵队长马尔科尔下落不明，恶齿村的卫兵部队需要一位新队长。任何有意担任此职的人都必须消灭邪枝狂战士、暗影猎手、饮血者和噬魂者，然后将申请书提交给位于辛特兰的断齿族长。",kw={"狂战士","饮血者","卫兵队长","马尔科尔","恶齿","暗影猎手","噬魂者","断齿","邪枝"},sec={{t="空缺的职位",b="一份征兵公告显示，卫兵队长马尔科尔下落不明，因此恶齿村的卫兵部队再次失去了队长。任何想要领导卫兵部队的人，都需要完成公告中列出的任务，并将申请书递交给断齿族长。"},{t="证明价值",b="申请人需要消灭四种邪枝巨魔：狂战士、暗影猎手、饮血者和噬魂者。完成后，回到恶齿村找断齿族长复命。"}},faq={{q="为什么卫兵队长的职位空缺？",a="卫兵队长马尔科尔下落不明，公告称恶齿村的队长职位再次空缺。",al={"为什么卫兵队长职位空缺","马尔科尔发生了什么事","谁是上一任队长"}},{q="在消灭敌人后，应该向谁提交申请？",a="申请应提交给恶齿村的断齿族长。",al={"我应该向谁交任务","在哪里提交申请","谁来评估申请人"}},{q="为了获得资格，必须击败哪些敌人？",a="申请人必须消灭邪枝狂战士、暗影猎手、饮血者和噬魂者。",al={"要杀死哪些邪枝巨魔","职位空缺目标","为了担任卫兵队长我该杀谁"}}},fp="47,255,13.235.0,13.183.0,42.95.0,56.57.0,42.98.0"}
P.entries["quest:787"] = {n="新的部落",s="“新部落”是试炼谷的一项入门任务，由老兵伊崔格指派。任务引导新兵向大兽穴内的高内克报到，以开始他们的训练。通过这次简短的召集，伊崔格分享了他个人的经历，以及萨尔对于救赎后的部落所构想的愿景。",h="“新部落”是试炼谷的一项入门任务，由老兵伊崔格指派。任务引导新兵向大兽穴内的高内克报到，以开始他们的训练。通过这次简短的召集，伊崔格分享了他个人的经历，以及萨尔对于救赎后的部落所构想的愿景。",kw={"燃烧军团","杜隆塔尔","伊崔格","高内克","新部落","大兽穴","萨尔","试炼谷"},ang={["faction:Horde"]="这项任务概括了萨尔政权建立的基本精神：彻底断绝恶魔的奴役，转而追求荣誉、生存和祖先的身份认同。",["race:Orc"]="对于走进试炼谷的年轻兽人来说，伊崔格代表了他们种族悲惨过去的鲜活记忆，以及他们在萨尔领导下的救赎。",["race:Troll"]="暗矛巨魔在试炼谷与兽人并肩训练，他们已经拥抱了萨尔关于相互生存和荣誉的愿景。"},sec={{t="老兵的回归",b="伊崔格站在试炼谷，受大酋长萨尔之命负责评估和指导部落最新的希望之星。他在第二次战争后因对旧部落被燃烧军团腐蚀感到幻灭而离开，并在流亡中隐居，直到被人类俘虏。在被萨尔救出后，得知这位年轻大酋长的梦想——一个植根于萨满教义、彻底切断与恶魔主子联系的荣誉部落——他选择了回归。"},{t="向大兽穴报到",b="任何新兵在冒险走出试炼谷那崎岖的峡谷之前，都必须证明自己的实力。伊崔格会派遣新人进入被称为“大兽穴”的阴凉洞穴去见高内克。虽然高内克对新加入的应募者那粗糙的状态几乎从不委婉评价，但他的监督确保了只有那些掌握了纪律与生存之道的人，才被允许进入杜隆塔尔的更广阔天地。"}},faq={{q="谁是伊崔格？",a="伊崔格是一位年迈的兽人老兵，曾亲眼目睹了旧部落在燃烧军团影响下的堕落。心灰意冷之下，他在洛丹伦选择了自我流放。在被人类俘虏并随后被萨尔解放后，他向萨尔新改组的部落宣誓效忠，现在协助监督在试炼谷的新兵训练。",al={"谁是伊崔格","伊崔格背景故事","伊崔格背景知识"}},{q="为什么伊崔格会谈论“新部落”？",a="最初的部落曾在燃烧军团的摆布下被恶魔的嗜血冲动所操纵和奴役。萨尔建立的新部落旨在抛弃恶魔的控制，复兴传统的萨满之道，并为卡利姆多的兽人及其盟友建立一个荣耀、自主的未来。",al={"什么是新部落","新旧部落的区别","新部落的含义"}},{q="高内克在哪里？",a="高内克驻扎在大兽穴的入口处，那是试炼谷北侧岩壁上开凿出的一处显眼的洞穴。",al={"高内克在哪里","找到高内克","高内克位置"}},{q="向高内克报到后会发生什么？",a="高内克会接纳你成为伊崔格的学员之一，并交给你最初的实地任务，让你通过保卫山谷来投入工作，并测试你为部落效力的准备情况。",al={"新部落任务后的下一个任务","高内克做什么","高内克任务"}},{q="伊崔格为何被流放？",a="伊崔格离开部落是因为他对早期战争中术士侍奉燃烧军团所造成的恶魔腐蚀和毫无意义的屠杀感到厌恶。",al={"伊崔格为什么离开","伊崔格流放原因","伊崔格恶魔腐蚀"}},{q="为什么新兵要在试炼谷受训？",a="试炼谷为杜隆塔尔的年轻兽人和盟友新人提供了一个隐蔽、崎岖的环境，让他们在踏入更广阔的世界之前，能在老兵教官的注视下应对凶猛的野兽和蝎虫。",al={"为什么要试炼谷","试炼谷的目的","试炼谷训练"}}},fp="13,197,18.473.0,20.322.0,15.339.0,44.269.0,24.131.0,39.192.0,23.179.0,49.204.0"}
P.entries["quest:789"] = {n="工蝎的尾巴",s="“蝎尾之毒”是高内克交给试炼谷大兽穴中部落新兵的一项早期试炼。新手们需要前往营地西北方猎杀毒蝎工蜂，并带回十根尾巴，以证明他们的战斗准备已经就绪。这项任务旨在通过实战来教会新兵如何在战场险境中生存，以及无论对手多么弱小都不能轻视。",h="“蝎尾之毒”是高内克交给试炼谷大兽穴中部落新兵的一项早期试炼。新手们需要前往营地西北方猎杀毒蝎工蜂，并带回十根尾巴，以证明他们的战斗准备已经就绪。这项任务旨在通过实战来教会新兵如何在战场险境中生存，以及无论对手多么弱小都...",kw={"解药","杜隆塔尔","高内克","蝎子","蝎子工蜂","蝎尾之毒","大兽穴","试炼谷","剧毒"},ang={["class:Warrior"]="高内克将蝎子狩猎视为磨练战斗意志的基础课程，提醒战士们决断的打击可以克服坚硬的甲壳，而对弱小敌人的傲慢则会引致失败。",["race:Orc"]="对于在试炼谷成年的年轻兽人来说，猎杀剧毒蝎子是一项由高内克监督的必要试炼，旨在考验他们的耐力和战场意识。",["race:Troll"]="与部落一同在试炼谷进行训练的暗矛巨魔，也必须在深入杜隆塔尔之前证明他们对抗当地蝎子的勇武。"},sec={{t="毒刺的试炼",b="在烈日炙烤的试炼谷峡谷中，高内克通过让他们对抗当地野生生物来考验部落新兵。大兽穴西北方干旱土地上游荡的剧毒蝎子，曾让经验丰富的战士和笨拙的初学者同样吃过苦头。为了证明他们的战场能力，年轻的勇士必须深入岩石地带，击杀蝎子工蜂，并带回十根被切下的尾巴作为武艺的证明。"},{t="剧毒与警惕",b="虽然这些剧毒捕食者十分致命，但它们也为受伤的新手提供了救命良药。大兽穴储备有直接从蝎毒中提取并酿制而成的抗毒剂，专门用于救治受伤的新手。除了如何规避毒素之外，高内克还强调了一个核心的战术道理：在激烈的战场上，傲慢是致命的，即使是最小的敌人也足以用其致命的毒素放倒强大的战士。"}},faq={{q="谁发布了“蝎尾之毒”任务？",a="高内克，负责监督试炼谷大兽穴新兵训练的战歌军官，会向年轻的战士和冒险者发布此项试炼。",al={"谁发布蝎尾之毒","蝎子任务发布者","高内克任务"}},{q="蝎子在哪里？",a="蝎子工蜂大量栖息在试炼谷大兽穴的正西北方，在干旱的红色峡谷地形中游荡。",al={"哪里寻找蝎子","蝎子位置","试炼谷蝎子"}},{q="高内克要求从狩猎中带回什么？",a="高内克要求带回十根蝎子工蜂的尾巴，作为新兵已经面对过这些剧毒野兽并取得战斗胜利的确凿证据。",al={"蝎子掉落什么","蝎子任务物品","蝎子尾巴"}},{q="如何制造蝎毒解药？",a="蝎毒解药是直接从这些生物的毒刺中提取毒液酿制而成的。大兽穴储备有充足的解药，用于治疗那些低估了猎物的小看者。",al={"蝎毒治疗","解药设定","蝎毒解药如何制作"}},{q="高内克希望新兵学到什么教训？",a="高内克利用这次狩猎来教导新手战士，任何对手，无论大小，都具备致命的潜力。在面对看似弱小的生物时，战场上的过度自信很快就会导致死亡。",al={"高内克的教诲","为什么要猎杀蝎子","蝎子试炼目的"}},{q="在这场狩猎之后，高内克是否提供进一步的训练？",a="在交回尾巴后，高内克会表示他在大兽穴没什么可以再教你的了，并让你前往杜隆塔尔继续为部落效力。",al={"蝎尾之毒后要做什么","高内克的下一个任务","高内克是否教导更多内容"}}},fp="20,352,20.421.0,19.399.0,33.141.0,31.130.0,39.136.0,46.187.0,47.192.0,51.159.0"}
P.entries["quest:79"] = {n="斯塔文的传说",s="这个任务标志着关于斯塔文·密斯特曼托的零散传言汇聚成了无可辩驳的残酷罪证。旅店老板斯密茨交出了长期隐藏的沾满泥污的日记书页，并指引调查者直接去找夜色镇的指挥官阿尔泰娅·埃伯洛克。",h="这个任务标志着关于斯塔文·密斯特曼托的零散传言汇聚成了无可辩驳的残酷罪证。旅店老板斯密茨交出了长期隐藏的沾满泥污的日记书页，并指引调查者直接去找夜色镇的指挥官阿尔泰娅·埃伯洛克。",kw={"夜色镇","暮色森林","埃伯洛克","调查","密斯特曼托","沾满泥污的日记","夜色守夜人","斯密茨","斯塔文"},ang={["class:Paladin"]="将尘封已久的谋杀案公之于众，履行了圣骑士的使命，要求为在暮色森林阴影中惨遭杀害的无辜生命伸张正义。",["class:Rogue"]="在酒馆和布满灰尘的箱子之间拼凑笔迹样本，体现了追踪难以捉摸的猎物时通常所需的耐心侦探工作。",["faction:Alliance"]="这项调查展示了在暴风城的官方支持完全缺席时，南部地区必须依靠游荡的联盟英雄来执行正义。"},sec={{t="夜色镇的突破",b="多年来，一个来访贵族家庭的凄惨命运一直是暮色森林中一桩未解的悲剧。旅店老板斯密茨和当时担任暴风城卫兵队长的哈格德警官最初调查了屠杀现场，并发现了几页撕裂且沾满泥污的日记。由于缺乏笔迹样本或佐证文件，这些记录一直未能取得进展，无法正式指控传闻中隐居在荒野里的那个人。在艾尔文森林、西部荒野和暮色森林收集到的证据最终将笔迹与斯塔文·密斯特曼托联系了起来，将镇上的流言转变成了一起证据确凿的谋杀案。"},{t="诉诸卫兵",b="夜色镇一直生活在亡灵、野兽以及潜伏在森林阴影中更可怕的威胁的持续围困之下。当城镇的生存都岌岌可危时，指挥官阿尔泰娅·埃伯洛克对于无稽之谈或毫无根据的怀疑几乎没有耐心。交出这些沾满泥污的书页，架起了冰冷的历史与即时军事正义之间的桥梁。在暮色森林的土地上看到屠杀的确凿证据后，夜色守夜人终于被迫承认斯塔文·密斯特曼托不仅仅是一个古怪的隐士或鬼故事的主角，而是一个必须绳之以法的危险逃犯。"}},faq={{q="旅店老板斯密茨一直掌握着什么证据？",a="几年前，斯密茨曾与哈格德一起调查那场来访贵族的屠杀事件。他们在现场找回了撕裂且沾满泥污的日记书页，但直到现在才缺乏匹配的笔迹样本来证明斯塔文·密斯特曼托就是作者。",al={"斯密茨 日记书页","沾满泥污的日记书页","斯密茨发现了什么"}},{q="为什么斯密茨没有早点向埃伯洛克指挥官报告这件事？",a="由于缺乏将沾满泥污的书页上的笔迹与那位隐居的家庭教师联系起来的证据，斯密茨和哈格德当时只有一些推测性的碎片。向埃伯洛克指挥官呈报未经证实的谣言，会被视为对夜色守夜人紧缺人力的无用浪费，从而被驳回。",al={"为什么等这么久","为什么要隐瞒这些书页","为什么斯密茨不告诉卫兵"}},{q="指挥官阿尔泰娅·埃伯洛克是谁？",a="指挥官阿尔泰娅·埃伯洛克是夜色守夜人的首领，这是一支负责守卫夜色镇并在暮色森林的道路上巡逻，以抵御亡灵和森林掠食者的城镇民兵组织。",al={"埃伯洛克是谁","阿尔泰娅·埃伯洛克的职责","夜色镇指挥官"}},{q="暮色森林发生了什么大屠杀？",a="几年前，一个来访的贵族家庭在暮色森林中遭到屠杀。虽然传言指向他们以前的家庭教师斯塔文·密斯特曼托，但当地调查人员最初缺乏指控他所需的决定性证据。",al={"什么屠杀","贵族被屠杀","谁被谋杀了"}},{q="这一步骤在整体调查中处于什么位置？",a="这一步代表了从私人调查向正式司法的过渡。在查阅了三个地区的登记册、学校记录和家庭箱子后，你将收集到的证据交给地方当局，以批准对斯塔文采取行动。",al={"斯塔文任务线进度","进行到哪一步了","这是任务的终点吗"}},{q="为什么夜色守夜人如此不情愿调查旧案？",a="夜色镇每天都面临着被游荡的憎恶、狼人族群和蜘蛛毁灭的直接威胁。埃伯洛克指挥官必须将所有可用的守夜人集中在生存问题上，这意味着冷案在得到无可辩驳的证据之前，她不会分出人力去调查。",al={"为什么埃伯洛克很忙","夜色镇防御优先级","夜色守夜人的优先事项"}}},fp="21,159,27.516.0,22.464.1,51.215.0,61.186.0,34.169.0,37.179.0,56.226.0,62.210.0"}
P.entries["quest:79007"] = {n="... and that note you found",s="“……以及你找到的那张便条”始于一个不久前废弃的营地，营火余烬尚存，补给散落一地。余烬之中躺着一张被烧焦起泡的羊皮纸，上面写着一条关于寻找“双生之地”的谜语。由于没有其他向导，这张烧焦的残片成为了追寻遗留之物的唯一线索。",h="“……以及你找到的那张便条”始于一个不久前废弃的营地，营火余烬尚存，补给散落一地。余烬之中躺着一张被烧焦起泡的羊皮纸，上面写着一条关于寻找“双生之地”的谜语。由于没有其他向导，这张烧焦的残片成为了追寻遗留之物的唯一线索。",kw={"以及你找到的那张便条","起泡的便条","烧焦的便条","余烬","最近的营火","散落的物资","双生之地"},sec={{t="荒野余烬",b="在最近的一次营火的余温和散落的物资旁，躺着一张受损且起泡的纸。曾在此处停留的人不久前刚刚离开，只留下了正在冷却的余烬和一张险些被火焰吞噬的羊皮纸残片。现场迹象显示离开时非常匆忙或突发状况导致，物资甚至未加遮蔽地暴露在外。"},{t="晦涩的谜语",b="这张幸存的羊皮纸残片上写着一条神秘的指令：“并非所有燃烧之物皆已散失。寻觅双生之地，寻觅此处。”由于在火灾中没有留下签名、坐标或更多背景信息，这张烧焦的残片成了偶然发现它的人唯一的踪迹线索。"}},faq={{q="营地里找到的便条上写着什么？",a="这张烧焦、起泡的便条上写着一条神秘的信息：“并非所有燃烧之物皆已散失。寻觅双生之地，寻觅此处。”这是废弃营地里留下的唯一线索。",al={"便条上写了什么","便条正文","起泡的便条"}},{q="是谁留下了这张便条？",a="作者尚不得而知。它是在最近一次营火的余烬旁，在散落的物资中被发现的。这表明撰写或持有此便条的人不久前刚刚离开，或是被迫匆忙离去。",al={"便条来自何处","谁写了便条","谁生起的营火"}},{q="“双生之地”指的是什么？",a="便条中神秘地提到了“双生之地”，指引读者去寻找一个匹配或镜像的地点。这张烧焦的残片没有提供进一步的解释，将其实际含义留给旅行者自行解开谜题。",al={"什么是双生之地","双生之地线索"}},{q="该如何根据便条上的线索行动？",a="由于地图上没有标记明确的目的地，便条上烧焦的残余是你的唯一向导。要解开其中的谜语，必须寻找一个与便条中神秘描述相呼应的土地或地点。",al={"如何处理便条","任务导向何处"}},{q="为什么营地会被废弃？",a="现场显示出匆忙离开或遭遇突发状况的迹象，物资被留在了正在熄灭的余烬旁。除了幸存的那张起泡的纸片外，没有留下任何可以辨识身份的装备或标记。",al={"谁废弃了物资","散落物资的营地"}},{q="营火处还有其他线索吗？",a="营火处没有留下任何完好的文字或标记。火焰摧毁了几乎所有东西，只留下了那张起泡的纸片作为曾有人在此休息的幸存证据。",al={"营火还揭示了什么","营地线索"}}},fp="27,318,18.339.0,16.289.0,45.187.0,25.212.0,35.221.0,40.196.0,31.206.0,38.190.0"}
P.entries["quest:79008"] = {n="... and that note you found",s="这张烧焦的字条在西部荒野一处即将熄灭的营火灰烬中被发现，留下了一条晦涩而孤独的线索。其灼烧的讯息暗示了世上某处等待着的目的地，敦促发现者去寻找一片“孪生之地”。",h="这张烧焦的字条在西部荒野一处即将熄灭的营火灰烬中被发现，留下了一条晦涩而孤独的线索。其灼烧的讯息暗示了世上某处等待着的目的地，敦促发现者去寻找一片“孪生之地”。",kw={"烧焦的字条","营火","灰烬","字条","孪生之地","西部荒野"},ang={["class:Rogue"]="对那些依靠低语、秘密和隐秘信件生活的人来说，解读留在隐蔽营地中的晦涩线索是他们的第二天性。",["faction:Alliance"]="对于试图恢复西部荒野秩序的冒险者来说，一个身份不明的营地和一道神秘的暗语，代表着王国边境上又一个正在展开的谜团。"},sec={{t="熄灭的营火",b="在西部荒野那荒废的田野、搜刮一空的农庄和饱经风霜的平原之间，旅行者经常会遇到流浪汉、不法之徒或绝望的流民营地。然而，这座小营地却是在匆忙或秘密中被遗弃的，补给品被弃之不顾，灰烬中仍有微光闪烁。在散乱的残骸中，留着一张在火灾中幸存下来的烧焦羊皮纸。"},{t="晦涩的讯息",b="这张烧焦的字条上只写着两句简短的话：“并非所有燃烧之物皆已遗失。寻找孪生之地，寻找那个地方。”这些话语笼罩在谜团之中，既像是一道神秘的谜题，又像是一份邀请，指引人们离开西部荒野那凄凉的田野，前往另一个在名称、地理或命运上与之相连的领域。"}},faq={{q="字条上写了什么？",a="这张烧焦的字条上写着：“并非所有燃烧之物皆已遗失。寻找孪生之地，寻找那个地方。”这是被遗弃的营地中留下的唯一线索。",al={"字条内容","字条上写了什么","烧焦字条上的话"}},{q="这张字条在哪里被发现？",a="这张字条是在西部荒野野外的一处近期营火残骸和散落的补给品中被发现的。",al={"字条位置","字条在哪里","营火位置"}},{q="是谁留下了这个营火？",a="作者身份不明。无论谁生起了这堆火，都已经离开不久，留下了散乱的补给品和灰烬中烧焦的讯息。",al={"谁留下了字条","营火主人","字条作者"}},{q="“孪生之地”指的是什么？",a="这个短语是一个谜题，指向世上另一个与发现地相互映照或有着某种联系的地区，尽管这张烧焦的字条没有提供进一步的解释。",al={"孪生之地的含义","什么是孪生之地","孪生之地在哪里"}},{q="为什么字条会被烧焦？",a="这张字条是在营火的灰烬中被烫伤和烧焦的，这表明有人要么是匆忙中试图将其销毁，要么是在火焰熄灭时漫不经心地将其丢弃。",al={"为什么它会被烧毁","有人试图烧毁字条吗","烧焦的字条"}},{q="这与迪菲亚潜行者有关吗？",a="虽然西部荒野到处都是迪菲亚潜行者和赤贫的非法定居者，但这条讯息的晦涩本质表明其含义比普通的强盗通讯更为隐晦。",al={"迪菲亚字条","是迪菲亚吗","兄弟会营火"}}},fp="27,124,12.304.0,19.241.0,23.142.0,25.97.0,22.142.0,35.146.0,24.143.0,44.163.0"}
P.entries["quest:79091"] = {n="Archmage Antonidas: The Unabridged Autobiography",s="这个任务需要找回大法师安东尼达斯详尽的个人回忆录，他曾是备受尊崇的肯瑞托领袖。这本珍贵的书卷原藏于铁炉堡的宏伟档案馆中，为研究达拉然的历史和高等奥术学识提供了不可替代的洞见。",h="这个任务需要找回大法师安东尼达斯详尽的个人回忆录，他曾是备受尊崇的肯瑞托领袖。这本珍贵的书卷原藏于铁炉堡的宏伟档案馆中，为研究达拉然的历史和高等奥术学识提供了不可替代的洞见。",kw={"安东尼达斯","奥术","大法师安东尼达斯","自传","达拉然","hall of explorers","铁炉堡","肯瑞托","图书馆","法师"},ang={["class:Mage"]="大法师安东尼达斯是肯瑞托最伟大的领袖之一，也是奥术学术的典范。研究他的生平和个人著作对任何奥术练习者来说都能提供至关重要的见解。",["faction:Alliance"]="安东尼达斯曾是洛丹伦联盟对抗兽人部落和天灾军团的中流砥柱，这使得他的个人回忆录成为整个联盟领地内珍贵的历史记录。",["race:Dwarf"]="这卷书源自铁炉堡Hall of Explorers里的大图书馆，不过接收它的学者似乎并不在意夺走了矮人档案管理员的一本珍稀书籍。",["race:Human"]="安东尼达斯是一位受人尊敬的人类大法师，他带领肯瑞托和达拉然度过了第二次和第三次战争，这使得他的全本自传成为了一段珍贵的人类历史。"},sec={{t="大法师的箴言",b="大法师安东尼达斯是艾泽拉斯最聪慧的头脑之一，他曾担任肯瑞托的尊崇领袖及达拉然的统治者长达数十年。他的全本自传记载了他从紫罗兰城堡中不断晋升的过程、他对奥术的精通，以及在第二次和第三次战争那动荡时期中的领导经历。对于魔法学者和施法者来说，安东尼达斯的第一手回忆为深入了解达拉然的内幕和奥术艺术提供了一个绝佳窗口。"},{t="来自铁炉堡大图书馆",b="在被送往新家之前，这份珍稀的手稿一直存放于铁炉堡的大图书馆内，与Hall of Explorers里的古代泰坦遗物和矮人史料一同保管。矮人们拥有从艾泽拉斯各处的废墟和外邦王国中收集来的庞大藏书，这使得他们的档案馆成为了珍稀文献的宝库。然而，其他地方的奥术学者们却渴望将这些作品据为己有，他们确信忙碌的矮人档案管理员绝不会注意到少了一本书。"}},faq={{q="大法师安东尼达斯是谁？",a="大法师安东尼达斯曾是肯瑞托的长期领袖，也是魔法城市达拉然的统治者。作为一位传奇的奥术大师，他在第二次战争期间担任洛丹伦联盟的关键顾问，并在第三次战争中为了保卫达拉然而牺牲前，曾向泰瑞纳斯国王警告过瘟疫的到来。",al={"安东尼达斯是谁","大法师安东尼达斯背景故事","安东尼达斯身世"}},{q="什么是全本自传？",a="这是由大法师安东尼达斯本人撰写的详尽全本自传，详细记述了他的生平、学术研究以及在达拉然的领导生涯。鉴于他作为肯瑞托首领的地位，他的个人著作是一份极具价值的历史和魔法记录。",al={"这本书是什么","全本自传","安东尼达斯书卷"}},{q="这本书是从哪里来的？",a="这卷书是从铁炉堡的图书馆中获取的，原本存放于这座矮人要塞的Hall of Explorers里。矮人的探险家和档案管理员经常从东部大陆各地收集历史和魔法文献。",al={"书的来源","这书来自铁炉堡吗","铁炉堡图书馆书籍"}},{q="为什么要搜寻这本书？",a="学者和图书管理员们不断地搜寻强大或具有历史意义的魔法文献，以扩充他们的馆藏并保存奥术知识，尤其是那些由传奇法师所著、否则可能会失传或埋没在异国馆藏中的作品。",al={"为什么要收集魔法书","谁想要安东尼达斯的书","图书馆为何需要这本书"}},{q="大法师安东尼达斯遭遇了什么？",a="大法师安东尼达斯在第三次战争中，当堕落的阿尔萨斯·米奈希尔王子率领天灾军团入侵达拉然时不幸牺牲。安东尼达斯升起了一道强大的魔法结界来保卫城市及其秘密，但阿尔萨斯突破了防御，并击杀了他以夺取麦迪文之书。",al={"安东尼达斯死了吗","安东尼达斯是怎么死的","安东尼达斯发生了什么"}},{q="铁炉堡图书馆会发现书丢了吗？",a="收件人随口打消了关于矮人会察觉书本丢失的顾虑，认为铁炉堡的档案库规模宏大，少了一本书很可能根本不会被发现。",al={"铁炉堡会发现书丢了吗","从铁炉堡图书馆窃取"}}},fp="48,290,28.497.0,35.523.0,27.321.0,37.277.0,30.229.0,36.240.0,36.282.0,51.204.0"}
P.entries["quest:79092"] = {n="Archmage Theocritus' Research Journal",s="《塞欧克瑞图斯大法师的研究日志》是一卷记载了阿祖拉之塔的大法师所进行研究的奥术文献。这本日志被送往铁炉堡图书馆的学者手中，为这座伟大的矮人档案馆增添了宝贵的魔法见解。",h="《塞欧克瑞图斯大法师的研究日志》是一卷记载了阿祖拉之塔的大法师所进行研究的奥术文献。这本日志被送往铁炉堡图书馆的学者手中，为这座伟大的矮人档案馆增添了宝贵的魔法见解。",kw={"奥术知识","塞欧克瑞图斯大法师","铁炉堡","铁炉堡图书馆","研究日志","塞欧克瑞图斯","阿祖拉之塔"},ang={["class:Mage"]="奥术学者们珍视来自塞欧克瑞图斯大法师等杰出人物的笔记，他的研究有助于保护铁炉堡档案馆中的历史魔法论著。",["faction:Alliance"]="搜集稀有文本和日志丰富了铁炉堡核心地带为所有联盟学者所建立的庞大知识库。"},sec={{t="大师的实地笔记",b="塞欧克瑞图斯大法师在整个联盟中以一位受人尊敬的施法者而闻名，他驻扎在艾尔文森林东部边缘的阿祖拉之塔。经过多年的潜心研究，塞欧克瑞图斯调查了许多奇特的文物、能量线异常以及附近的魔法威胁，并将他的发现记录在详细的日志中。找回这样一卷日志，是研究一位肯瑞托资深大法师个人观察记录的难得机会。"},{t="扩充铁炉堡档案馆",b="探险者协会和铁炉堡图书馆的管理员们维护着大陆上最伟大的档案库之一。通过将《塞欧克瑞图斯大法师的研究日志》交付给他们，冒险者确保了其中的奥术见解能够被安全地保存，并与卡兹莫丹的历史卷宗一起编目收藏。图书管理员们热烈欢迎任何能进一步拓宽他们集体智慧的魔法发现。"}},faq={{q="什么是《塞欧克瑞图斯大法师的研究日志》？",a="这是一本属于塞欧克瑞图斯大法师的学术研究日志，上交至铁炉堡图书馆以保存奥术知识并扩充档案。",al={"塞欧克瑞图斯日志上交","什么是塞欧克瑞图斯日志"}},{q="塞欧克瑞图斯大法师是谁？",a="塞欧克瑞图斯大法师是一位著名的人类法师，他居住在艾尔文森林的阿祖拉之塔，研究古代魔法干扰和文物。",al={"谁是塞欧克瑞图斯","塞欧克瑞图斯大法师背景"}},{q="这本日志会被带到哪里？",a="这本日志会被带给铁炉堡图书馆的档案管理员，他们负责为馆藏收集稀有文献和魔法手稿。",al={"我在哪里上交塞欧克瑞图斯日志","谁想要塞欧克瑞图斯日志"}},{q="为什么图书馆想要这本日志？",a="铁炉堡图书馆的学者们致力于保存奥术知识，并研究来自施法大师的稀有论著，以扩充他们的历史记录。",al={"为什么收集魔法日志","塞欧克瑞图斯日志的用途"}},{q="还有更多的魔法作品可以送到图书馆吗？",a="是的，馆长们鼓励冒险者继续在世界各地寻找失落的魔法作品和历史文献，以帮助他们的档案收集工作。",al={"还有更多日志可以上交吗","还有其他书籍给图书馆吗"}},{q="日志中包含了什么样的研究？",a="这本日志包含了塞欧克瑞图斯大法师在对魔法现象和奥术知识进行广泛调查期间所编写的笔记和观察记录。",al={"塞欧克瑞图斯日志里有什么","塞欧克瑞图斯日志的内容"}}},fp="37,255,22.448.0,32.432.0,46.166.0,27.149.0,30.146.0,39.157.0,51.154.0,50.151.0"}
P.entries["quest:79093"] = {n="Rumi of Gnomeregan: The Collected Works",s="“Rumi of Gnomeregan: The Collected Works”涉及寻回并上交一卷侏儒著作汇编，以扩充图书馆的藏书。通过递交这些珍贵的文献，冒险者可以帮助学者们保护宝贵的历史和魔法知识，使其免于失传。",h="“Rumi of Gnomeregan: The Collected Works”涉及寻回并上交一卷侏儒著作汇编，以扩充图书馆的藏书。通过递交这些珍贵的文献，冒险者可以帮助学者们保护宝贵的历史和魔法知识，使其免于失传。",kw={"合集著作","诺莫瑞根背景知识","侏儒著作","图书馆","魔法著作","rumi of gnomeregan"},ang={["class:Mage"]="奥术学者非常重视从艾泽拉斯各地寻回的珍稀和奇特的著作，尤其是那些能扩展人们对魔法理论和历史的集体理解的作品。",["faction:Alliance"]="联盟的学者和馆长不断寻求寻回并保护珍贵的文学和魔法文献，以造福联盟的共同知识。",["race:Gnome"]="对于那些在诺莫瑞根陷落后试图保护本族文化和智力贡献的侏儒来说，确保像Rumi这样思想家的著作合集被安全地归档，是关乎遗产传承的大事。"},sec={{t="保护侏儒智慧",b="“Rumi of Gnomeregan: The Collected Works”代表了保护著名的侏儒文学作品和智力成就的努力。在诺莫瑞根被穴居人侵占而惨遭沦陷后，许多侏儒的文字遗产流散、掩埋或面临毁灭的威胁。在图书馆和学术中心工作的学者与档案管理员们正积极搜寻幸存的手稿、专著和汇编，以确保侏儒思想家的智慧和创造力不会随着时间流逝而湮灭。"},{t="档案回收",b="当冒险者在野外发现这些合集卷册并将其送交档案馆时，馆长会急切地将其纳入不断增长的藏品库中。档案管理员将每一份寻回的手稿都视为对集体认知的一次扩展，并鼓励旅行者带回他们发现的任何进一步的魔法或历史文献。通过这些贡献，知识得以让那些致力于保护艾泽拉斯学术遗产的学者、法师和历史学家们查阅。"}},faq={{q="什么是“Rumi of Gnomeregan: The Collected Works”？",a="“Rumi of Gnomeregan: The Collected Works”是一项涉及寻回并贡献一份著名的侏儒著作汇编的任务。冒险者将这些文学资料交给一位正在构建图书馆藏书的学者，以确保宝贵的知识得以保存和研究。",al={"rumi of gnomeregan任务","什么是rumi of gnomeregan","谁是rumi"}},{q="这些合集应该交给谁？",a="这些合集被上交给维护图书馆藏书的馆长或学者。接收者会搜寻重要的著作和魔法专著，以扩充他们的档案馆藏。",al={"在哪里上交rumi的作品","谁接收rumi的著作","rumi合集上交"}},{q="图书馆为什么要这些合集？",a="学者和档案管理员积极从世界各地搜集珍稀文献、历史专著和魔法手稿，以确保重要的学术成果得以保存，特别是那些源自诺莫瑞根的著作。",al={"为什么要收集rumi的著作","rumi of gnomeregan的目的","为什么图书馆需要rumi的著作"}},{q="谁是Rumi of Gnomeregan？",a="Rumi of Gnomeregan是一位知识分子或魔法作家，其汇编的著作备受档案管理员追捧。由于诺莫瑞根大部分地区已被占领，幸存的侏儒思想和学识合集便成为了他们学术传统的珍贵记录。",al={"rumi of gnomeregan是谁","rumi背景知识","rumi作者"}},{q="之后还可以带更多的书去图书馆吗？",a="可以，档案管理员欢迎更多的发现。馆长鼓励冒险者继续搜寻珍稀或重要的魔法专著和历史著作，将其添加到馆藏中。",al={"还有更多的书可以找吗","我可以带更多的文献吗","更多的魔法著作图书馆"}},{q="谁能完成这项任务？",a="该任务由协助学者保护历史和奥术文献的联盟冒险者承担。任何寻回这些珍贵文献的人都可以将其呈交给档案馆，以助力学术研究。",al={"rumi任务要求","谁可以上交rumi的作品","仅限联盟rumi"}}},fp="39,281,26.517.0,17.482.0,48.284.0,42.186.0,48.216.0,26.252.0,52.202.0,27.216.0"}
P.entries["quest:79095"] = {n="The Apothecary's Metaphysical Primer",s="\"The Apothecary's Metaphysical Primer\" 是一本专门的魔法文献，馆长们希望能借此丰富学术档案。上交此书有助于为研究者和施法者保存珍贵的炼金术与奥术理论。",h="\"The Apothecary's Metaphysical Primer\" 是一本专门的魔法文献，馆长们希望能借此丰富学术档案。上交此书有助于为研究者和施法者保存珍贵的炼金术与奥术理论。",kw={"炼金术","药剂师","幽暗城","图书馆","魔法著作","形而上学入门书","典籍"},ang={["class:Mage"]="奥术修行者们非常看重形而上学入门书，因为它们对魔法理论、炼金相互作用以及施法基础定律有着深刻的见解。",["faction:Horde"]="部落的学者和冒险者们通过回收珍稀论著来协助幽暗城的Owen Thadd，以此充实图书馆的奥术知识储备。"},sec={{t="学者的收藏",b="\"The Apothecary's Metaphysical Primer\" 是一本涵盖深奥魔法原理的学术文献。馆长们致力于扩充档案，非常欢迎上交此类论著，并将这本入门书直接加入到他们的魔法参考资料收藏中。"},{t="扩充档案",b="对于幽暗城的Owen Thadd收藏馆等图书馆来说，保存这些专业论著至关重要。通过上交有关奥术和炼金理论的珍稀入门书，探险者们能够确保这些罕见的形而上学见解被妥善存档，供研究人员查阅，而不是遗失在荒野之中。"}},faq={{q="什么是 \"The Apothecary's Metaphysical Primer\"？",a="\"The Apothecary's Metaphysical Primer\" 是一本罕见的学术文献，馆长们希望借此丰富他们的魔法书库，并扩展对形而上学科学的理解。",al={"什么是 \"the apothecary's metaphysical primer\"","形而上学入门书任务","这是什么书"}},{q="谁需要这份入门书？",a="这本书要交给幽暗城的Owen Thadd，他正在搜寻魔法著作和奥术论著，以便为研究者和施法者保存知识。",al={"谁需要这本书","我应该在哪里上交入门书","谁会接收这本入门书"}},{q="图书馆为什么要收集这类著作？",a="图书馆和档案库收集形而上学和魔法著作，旨在系统地扩充其知识储备，帮助学者、炼金术师和奥术师研究奥术原理。",al={"图书馆为什么需要入门书","收集入门书的目的","为什么要收集魔法书"}},{q="你能给图书馆带来更多魔法著作吗？",a="负责整理魔法文献的学者们欢迎你发现并带来的任何奥术与学术研究成果，这些成果将丰富他们的档案。",al={"还有更多的书可以上交吗","我可以带来其他的书吗","更多的图书馆藏书"}},{q="形而上学入门书里包含了什么样的知识？",a="在魔法学术界，形而上学涉及魔法能量的基本本质、支配现实的无形力量，以及物理试剂如何与奥术力量相互作用。",al={"什么是形而上学","魔兽世界中的形而上学知识","什么是药剂师形而上学"}},{q="谁撰写了 \"The Apothecary's Metaphysical Primer\"？",a="记录中并未提及撰写此书的具体药剂师，但药剂师和学者们经常编写入门书，总结实用的炼金术、草药混合配方和神秘公式。",al={"谁写了药剂师入门书","药剂师入门书作者","谁是那位药剂师"}}},fp="36,212,23.268.0,22.307.0,45.186.0,40.154.0,45.185.0,48.154.0,56.182.0,47.198.0"}
P.entries["quest:79096"] = {n="Ataeric: On Arcane Curiosities",s="“Ataeric: On Arcane Curiosities”涉及交付寻获的魔法文献，以扩充学术档案馆的馆藏。通过从野外收集晦涩的文本和论着，研究人员力求加深对奥术研究的理解并保存神秘学知识。",h="“Ataeric: On Arcane Curiosities”涉及交付寻获的魔法文献，以扩充学术档案馆的馆藏。通过从野外收集晦涩的文本和论着，研究人员力求加深对奥术研究的理解并保存神秘学知识。",kw={"奥术","奥术珍品","ataeric","图书馆","魔法作品","学者"},ang={["class:Mage"]="法师对奥术研究有着天生的兴趣，因此向学术图书馆捐赠和寻回魔法论着与他们的技艺直接相关。",["race:Dwarf"]="矮人学者和探险者协会非常重视积累书面记录、文物和深奥的学识。"},sec={{t="保存奥术知识",b="艾泽拉斯各地的学者和档案管理员都依赖四处游历的冒险者，从危险之地寻回稀有书籍和被遗忘的论着。在这个任务中，寻求者专门寻找魔法文献，以拓宽机构对奥术艺术的理解。每一本被寻回的卷册都有助于拼凑出那些本可能散佚或失传的神秘学实践。"},{t="不断扩充的档案馆",b="在收到这些珍品后，馆长会将其直接纳入档案馆的藏品库。图书馆并不认为收购任务已经完成，而是保持着对世界各地发现的任何进一步魔法文献的公开征集，确保其藏品随着持续的学术研究而不断增长。"}},faq={{q="这个任务的目的是什么？",a="“Ataeric: On Arcane Curiosities”代表着向寻求扩充图书馆深奥知识储备的收藏家交付学术或魔法文本。",al={"这是什么任务","ataeric任务","奥术珍品上交"}},{q="谁在收集这些奥术文献？",a="Ataeric是该论着的作者。它会被交给正在收集魔法着作和稀有卷册以充实图书馆档案馆的研究员或馆长。",al={"谁想要这个","谁获得了这本书","谁是ataeric"}},{q="哪座图书馆受益于这些珍品？",a="寻求这些文本是为了增强学术收藏，并使接收该作品的学术图书馆受益。",al={"这是什么图书馆","这些书去了哪里"}},{q="还有更多的魔法作品可以收集吗？",a="学者特别鼓励冒险者在旅途中带回任何额外发现的魔法作品，以持续拓宽他们的知识储备。",al={"可以上交更多吗","可重复收集的魔法作品","图书馆需要的更多书籍"}},{q="为什么图书馆要寻求奥术珍品？",a="学者们不断寻找稀有的论着，以更好地理解奥术的细微差别，并保存历史性的神秘学知识。",al={"图书馆研究什么","为什么要收集奥术书籍"}},{q="为什么寻回奥术作品很重要？",a="奥术文本通常包含不稳定或晦涩的知识，因此在专门的图书馆内妥善保存和研究它们，远比让它们遗落在野外要好。",al={"这有危险吗","奥术魔法的风险"}}},fp="30,271,27.371.0,20.321.0,34.164.0,35.154.0,46.110.0,40.169.0,45.136.0,41.165.0"}
P.entries["quest:79097"] = {n="Baxtan: On Destructive Magics",s="《Baxtan: On Destructive Magics》是一个学术性的上交任务，冒险者需要将Baxtan关于破坏性法术的论著交给图书馆学者。寻回这些著作有助于图书馆的档案管理员加深对不稳定的奥术能量的理解。",h="《Baxtan: On Destructive Magics》是一个学术性的上交任务，冒险者需要将Baxtan关于破坏性法术的论著交给图书馆学者。寻回这些著作有助于图书馆的档案管理员加深对不稳定的奥术能量的理解。",kw={"奥术","baxtan","书籍","破坏性魔法","图书馆","魔法","典籍"},ang={["class:Mage"]="关于破坏性魔法的学术论著自然会引起法师们的兴趣，他们致力于研究奥术力量与破坏性力量之间的平衡。",["class:Warlock"]="那些钻研不稳定或禁忌力量的施法者能够理解学者们在探究破坏性奥术时所展现出的学术兴趣。",["faction:Alliance"]="扩充联盟图书馆内收藏的知识，能够巩固整个联盟的学术基础。"},sec={{t="一本毁灭艺术典籍",b="这个任务代表了学者们在编纂和保存奥术知识方面所做的持续努力。当冒险者发现探讨破坏性魔法不稳定性本质的文本时，将其交由严谨的学术机构保管，可以确保这些艺术的力量与危险被理解，而不是失传。"},{t="整理图书馆的知识",b="图书馆是历史、科学和奥术的宝库。其学者负责获取稀有卷宗，并欢迎那些从世界各地危险角落寻回遗忘论著的旅者，以扩充图书馆的馆藏知识。"}},faq={{q="任务“Baxtan: On Destructive Magics”是什么？",a="这个任务的内容是将Baxtan的破坏性魔法论著交给图书馆学者，从而充实魔法著作的收藏。",al={"什么是baxtan: on destructive magics","这是一个什么任务","baxtan任务"}},{q="Baxtan是谁？",a="Baxtan是《On Destructive Magics》的作者。接收这本著作的学者正负责为图书馆收集重要的书籍和魔法论著。",al={"baxtan是谁","baxtan npc","baxtan在哪里"}},{q="Baxtan在寻找什么样的书籍？",a="图书馆的学者寻求对馆藏有益的学术和魔法著作，并欢迎在世界各地发现的任何进一步的魔法论著。",al={"baxtan想要什么样的书","baxtan书籍收藏","给baxtan的更多书籍"}},{q="这些魔法知识最终会被送到哪里？",a="收集到的文本会被纳入接收它们的图书馆的馆藏中，从而将奥术和危险艺术的知识保存下来以供研究。",al={"书会被送到哪里","哪个图书馆","铁炉堡图书馆藏书"}},{q="图书馆为什么要收集关于破坏性魔法的著作？",a="学者们编纂破坏性魔法，是为了更好地理解强大奥术能量所带来的危害、理论机制以及表现形式。",al={"为什么要研究破坏性魔法","破坏性魔法知识"}},{q="你还能给Baxtan带来更多的魔法著作吗？",a="可以。学者鼓励冒险者继续带来他们发现的任何额外魔法著作，这表明收集知识的工作仍在持续进行。",al={"baxtan还有更多任务吗","我可以上交更多书吗"}}},fp="29,263,22.297.0,27.261.0,50.141.0,14.166.0,42.158.0,41.150.0,56.138.0,43.141.0"}
P.entries["quest:791"] = {n="新的背包",s="“各尽其责”是由弗恩·凝眉在俯瞰剃刀岭的瞭望塔顶端提供的一项入门任务。这位伤痕累累的老兵已无法再上前线作战，他请求年轻的部落冒险者从当地的敌对人类和半人马身上搜集帆布，好让他制作出能助力他们旅途的补给品。",h="“各尽其责”是由弗恩·凝眉在俯瞰剃刀岭的瞭望塔顶端提供的一项入门任务。这位伤痕累累的老兵已无法再上前线作战，他请求年轻的部落冒险者从当地的敌对人类和半人马身上搜集帆布，好让他制作出能助力他们旅途的补给品。",kw={"帆布脚料","各尽其责","杜隆塔尔","弗恩·凝眉","诺克-卡隆","剃刀岭","razor hill watchtower","提拉加德"},ang={["faction:Horde"]="杜隆塔尔的每一位年轻士兵都依赖像弗恩·凝眉这样经验丰富的老兵，他们时刻提醒新兵：荣耀部落意味着履行家园要求的任何职责，无论是守卫前哨站还是缝制帆布。",["profession:Tailoring"]="弗恩展示了实用且硬朗的边境裁缝手艺，将从人类入侵者和半人马掠夺者那里剥下的废弃厚帆布变成了耐用的荒野生存装备。",["race:Orc"]="弗恩代表了那一代兽人：他们摆脱了恶魔的腐化，随萨尔跨越海洋，现在正将他们的余生奉献给培育他们初建国家的未来。"},sec={{t="老兵的召唤",b="弗恩·凝眉是第三次战争的老兵，他曾追随萨尔大酋长在杜隆塔尔的拓荒时期并肩作战，也参与了海加尔山的生死保卫战。如今，因年事已高且旧伤缠身，他已无法再挥舞战斧上阵。相反，他时刻在剃刀岭的瞭望塔上保持警惕，在防范外敌入侵的同时，也尽力为下一代守卫者提供支持。"},{t="搜集的帆布",b="随着部落对该地区的掌控日益稳固，警戒号角的鸣响声也随之减少，弗恩便将空闲时间用于制作实用的装备。在杜隆塔尔干旱的峡谷中，坚韧的帆布很难获得，但东岸的库尔提拉斯入侵者以及游荡在平原上的诺克-卡隆半人马身上却携带着大量这种材料。从这些敌对势力手中搜集脚料，让弗恩有了足够的布料，可以为活跃的侦察兵缝制多功能背包。"}},faq={{q="弗恩·凝眉是谁？",a="弗恩·凝眉是一位年迈的兽人老兵，驻守在剃刀岭上方的瞭望塔中。他曾在杜隆塔尔的奠基时期与萨尔并肩作战，也曾站在击败阿克蒙德的海加尔山联军阵列中。他已无法再上前线作战，现在担任瞭望员，并利用空闲时间为年轻的部落战士制作战地装备。",al={"弗恩是谁","弗恩·凝眉背景故事","谁发布各尽其责任务"}},{q="在杜隆塔尔哪里可以找到帆布脚料？",a="帆布脚料可以从杜隆塔尔沿岸占据提拉加德城堡的库尔提拉斯人身上，以及在平原上扎营的诺克-卡隆半人马身上获得。这两个势力都携带着大量结实的编织材料，可以从他们的营地和随身物品中搜集到。",al={"哪里获得帆布脚料","谁掉落帆布脚料","帆布脚料位置"}},{q="弗恩所在的瞭望塔在哪里？",a="弗恩的瞭望塔坐落在剃刀岭正西北方的高耸岩崖上。定居点后方的一条蜿蜒小路直通山顶，那座木制瞭望建筑就立在那里。",al={"弗恩·凝眉在哪里","剃刀岭瞭望塔位置","找到剃刀岭瞭望塔"}},{q="弗恩用帆布脚料制作什么？",a="弗恩将搜集到的帆布脚料缝制成结实的多功能背包。对于在杜隆塔尔各地旅行的年轻冒险者来说，增加携带补给品、口粮和缴获武器的容量，对于在残酷的荒野中生存至关重要。",al={"弗恩制作什么","帆布有什么用","帆布脚料奖励"}},{q="为什么一位老战士要在制作背包而不是去战斗？",a="几十年的残酷战斗让弗恩的身体不堪重负，他已无法再满足战场对速度和力量的要求。他并没有哀叹自己的退役，而是以守望剃刀岭并制造能直接增强年轻战士防卫能力的装备为荣。",al={"为什么弗恩在制作物品","为什么弗恩待在塔里","为什么弗恩不战斗"}},{q="弗恩参加过哪场战争？",a="弗恩在萨尔大酋长麾下参加了第三次战争，参与了杜隆塔尔的定居过程，以及对抗燃烧军团的海加尔山决战。他自豪地回忆起在部落、暗夜精灵和联盟为了击败阿克蒙德而达成临时且必要的停战协议时，他所响应的战吼。",al={"弗恩战斗历史","弗恩以前做过什么","阿克蒙德与弗恩"}}},fp="17,227,19.323.0,16.411.0,22.323.0,44.202.0,46.165.0,44.204.0,56.221.0,27.242.0"}
P.entries["quest:79192"] = {n="Stepping Stones",s="Stepping Stones 是一项调查任务，源于在贫瘠之地崎岖荒野中贴着的一张饱经风霜的便条。潦草的字迹写着有两名信使一直在为 The New Plague 运送货物，并将发生在他们身上的事称为简单的药剂师事故。神秘的作者敦促任何找到它的人前往凄凉之地边界的一处隐秘山间避难所。",h="Stepping Stones 是一项调查任务，源于在贫瘠之地崎岖荒野中贴着的一张饱经风霜的便条。潦草的字迹写着有两名信使一直在为 The New Plague...",kw={"凄凉之地","雇佣兵","山脉","the new plague","便条","皇家药剂师协会","stepping stones","贫瘠之地"},ang={["class:Rogue"]="追踪匿名线人并审查凄凉之地和贫瘠之地之间隐秘的偏远地区补给点，对于那些从事匕首与情报交易的人来说是第二天性。",["faction:Horde"]="在贫瘠之地游荡的部落成员必须决定，关于卡利姆多土地上致命瘟疫运输的传闻是否对他们的领土和联盟构成了威胁。",["race:Undead"]="对于被遗忘者的旅行者来说，任何关于皇家药剂师协会及其枯萎病研究的零星提及都是紧迫的安全问题，或者说是来自内部的危险阴谋。"},sec={{t="荒野中的便条",b="这张信息随意地钉在偏远营地的一块木板上，在贫瘠之地严酷的环境中格外显眼。这里的营地常有雇佣兵、亡命之徒和流浪者出没，他们寻求远离十字路口或棘齿城窥探目光的临时住所。这张撕碎的便条立刻打破了荒野中平淡的闲谈，发出了一个充满阴谋和黑暗基调的邀请。"},{t="关于 The New Plague 的私语",b="便条作者报告说，两名特工一直在为 The New Plague 运送货物，并将发生在他们身上的事称为简单的药剂师事故。在卡利姆多各地运送挥发性瘟疫药剂的信使承担着巨大的风险，作者提供了一个位于贫瘠之地和凄凉之地之间的山中舒适地点，作为一个安全的谈话场所。"}},faq={{q="在 Stepping Stones 中找到的便条说了些什么？",a="该便条透露，运送与被遗忘者的 The New Plague 有关材料的信使遭遇了突然死亡。作者称这些为简单的药剂师事故，但提供了一个山中的会面点来安全地讨论此事。",al={"stepping stones 便条","便条的内容","stepping stones 任务文本"}},{q="便条告诉你去哪里？",a="作者邀请读者前往一个隐藏在贫瘠之地和凄凉之地之间的高山上的营地，这里远离常规巡逻路线和贸易通道。",al={"stepping stones 前往何处","山间舒适地点","stepping stones 地点"}},{q="信中提到的 The New Plague 是什么？",a="The New Plague 是被遗忘者的皇家药剂师协会在幽暗城研发的致命混合药剂。它旨在根除天灾军团和活着的敌人，其在各大陆的测试和信使任务都充满了秘密和致命的危险。",al={"什么是 the new plague","皇家药剂师瘟疫","药剂师运送"}},{q="是谁写了钉在木板上的便条？",a="该信息是匿名留在偏远营地的一块粗糙木板上的。作者没有署名，只提供了一个位于贫瘠之地和凄凉之地之间的山中舒适地点作为安全的谈话场所。",al={"谁写了便条","stepping stones 作者","谁在山中等待"}},{q="被遗忘者的信使为什么会出现在卡利姆多？",a="被遗忘者的药剂师经常从卡利姆多各地的严酷动植物身上采集奇异的毒液、孢子和试剂，并通过部落哨所和荒野路线协调运输。",al={"贫瘠之地的被遗忘者","为什么 the new plague 出现在卡利姆多","贫瘠之地的药剂师"}},{q="为什么偏远营地会被用于此类便条？",a="贫瘠之地地域辽阔，在主要定居点之外的管理较为松散。中立的中转站、雇佣兵休息点和流浪者营地让旅行者、走私者和线人能够留下隐秘的消息，而不会引起部落或地区岗哨的注意。",al={"偏远营地背景知识","贫瘠之地的雇佣兵营地"}}},fp="15,223,19.315.0,26.263.1,56.201.0,35.94.0,47.251.0,39.156.0,51.169.0,51.241.0"}
P.entries["quest:792"] = {n="邪灵劣魔",s="“邪恶的魔仆”是祖雷萨在试炼谷向刚抵达的勇士下达的早期任务之一。在监视山谷内的试炼时，祖雷萨发现附近的一处洞穴中隐藏着一个阴险的火刃集会所。为了遏制他们突如其来的扩张，新兵们被派遣去猎杀那些潜入杜隆塔尔红土地上的恶魔仆从。",h="“邪恶的魔仆”是祖雷萨在试炼谷向刚抵达的勇士下达的早期任务之一。在监视山谷内的试炼时，祖雷萨发现附近的一处洞穴中隐藏着一个阴险的火刃集会所。为了遏制他们突如其来的扩张，新兵们被派遣去猎杀那些潜入杜隆塔尔红土地上的恶魔仆从...",kw={"火刃氏族","火刃集会所","杜隆塔尔","小鬼","大兽穴","试炼谷","邪恶的魔仆","祖雷萨"},ang={["class:Warlock"]="兽人和巨魔术士必须正视那些滥用恶魔契约进行破坏，而非将邪能用于部落生存的堕落施法者所带来的现实。",["faction:Horde"]="火刃氏族是杜隆塔尔目前面临的最迫切的内部威胁之一，他们试图在年轻的部落巩固主权之前从内部将其腐蚀。",["race:Orc"]="对于那些努力践行萨尔关于拒绝恶魔奴役理念的兽人来说，在他们神圣的训练场中遇到邪能污染，这是一个苦涩的提醒，表明暗影议会的遗产依然在发酵。"},sec={{t="山谷中的阴影",b="试炼谷旨在成为年轻的兽人和暗矛巨魔展示他们对萨尔领导的部落的忠诚、纪律和力量的试炼场。它原本是用来测试新兵对抗蝎虫和野猪这类本土掠食者的能力，而非对抗恶魔腐蚀。然而，在东北方的一处洞穴中，自称为火刃氏族的特工们在山谷监工的眼皮底下建立了一个秘密集会所。"},{t="扑杀小鬼",b="祖雷萨在指引大兽穴附近的新手时，在这些恶魔污染蔓延至整个峡谷之前就察觉到了异常。被称为“邪恶的魔仆”的次级恶魔生物开始从洞口蜂拥而出，向任何靠近的冒险者投掷火焰并进行威胁。在部落能够铲除隐藏在阴影中的幕后主使之前，年轻的新兵们肩负着斩杀这些低级仆从以保卫山谷的任务。"}},faq={{q="谁发布了“邪恶的魔仆”这个任务？",a="该任务由祖雷萨发布。她驻扎在试炼谷中心的大兽穴入口外。",al={"邪恶的魔仆任务发布者","谁发布邪恶的魔仆","在哪里接取邪恶的魔仆"}},{q="什么是邪恶的魔仆？",a="邪恶的魔仆是由火刃氏族术士召唤并束缚的小鬼状恶魔生物。它们作为次级爪牙和宠物，使用火焰骚扰闯入者。",al={"什么是邪恶的魔仆","邪恶的魔仆背景故事","邪恶的魔仆怪物类型"}},{q="火刃集会所位于何处？",a="该集会所坐落在试炼谷东北部尽头的一处洞穴内，穿过四处游荡的杂斑野猪和蝎虫工兵即可到达。",al={"火刃集会所位置","火刃集会所在哪","试炼谷洞穴"}},{q="为什么火刃氏族会在试炼谷中？",a="火刃氏族是一个致力于破坏萨尔新部落并传播恶魔腐蚀的秘密邪教。渗透进试炼谷让他们能够潜伏在暗处，并威胁到部落最新一代的战士。",al={"为什么火刃氏族在这里","火刃氏族动机","火刃氏族想要什么"}},{q="完成“邪恶的魔仆”之后会发生什么？",a="当洞穴外的魔仆被清除后，祖雷萨会指引你深入洞穴去面对邪教头目，并取回一枚火刃奖章。",al={"邪恶的魔仆后续任务","邪恶的魔仆之后是什么","火刃奖章任务"}},{q="我必须进入洞穴深处才能找到这些魔仆吗？",a="不需要。虽然它们栖息在洞穴内，但大量的邪恶的魔仆也在洞穴入口周围和洞口外的峡谷地面上游荡。",al={"邪恶的魔仆在洞穴里吗","在哪里击杀邪恶的魔仆","刷邪恶的魔仆"}}},fp="14,247,22.338.0,16.347.0,35.113.0,24.155.0,41.129.0,49.228.0,45.161.1,57.130.0"}
P.entries["quest:79236"] = {n="Cherry for Your Thoughts?",s="在藏宝海湾，一名叫托卡尔的雇佣兵想要一杯酒，作为交换，她愿意透露近期人类和矮人哨所遇袭背后的真相。虽然有流言指责部落是幕后黑手，但托卡尔坚称她的团队是在受私人雇佣合约的约束下行事。",h="在藏宝海湾，一名叫托卡尔的雇佣兵想要一杯酒，作为交换，她愿意透露近期人类和矮人哨所遇袭背后的真相。虽然有流言指责部落是幕后黑手，但托卡尔坚称她的团队是在受私人雇佣合约的约束下行事。",kw={"藏宝海湾","樱桃酒的代价","樱桃酒","治安官","雇佣兵","劫掠","私人合同","托卡尔"},ang={["faction:Alliance"]="联盟成员会很有兴趣了解，袭击人类和矮人定居点的劫掠者并非受部落指使，而是受雇于一位私人资助者。",["faction:Horde"]="部落冒险者可以在托卡尔的供述中找到辩护的理由，这澄清了针对联盟营地的袭击是私人雇佣合约，而非部落的官方侵略行为。"},sec={{t="藏宝海湾的低语",b="在热闹的藏宝海湾港口，一个叫托卡尔的人正保持着低调，同时警惕着执法者的动向。近期发生的一系列激进劫掠事件重创了人类和矮人营地，助长了部落策划了这些袭击的传言。当那些显然不为调查此事的治安官工作的旅者接近她时，托卡尔立刻反驳了这些广为流传的说法，并提出只要请她喝杯酒，就愿意讲述另一版本的真相。"},{t="私人雇佣兵",b="托卡尔坦承参与了对人类和矮人哨所的劫掠，但坚决否认这些袭击是受部落指使的。相反，她声称她的团伙是受某个未透露身份的第三方私下雇佣。在披露究竟是谁资助了这次行动以及动机之前，她坚持要求对方先请她喝杯清爽的樱桃酒。"}},faq={{q="托卡尔是谁？",a="托卡尔是一名藏身于海盗避风港藏宝海湾的特工或雇佣兵。由于近期对人类和矮人定居点的劫掠受到审查，她向任何愿意为她买一杯樱桃酒的人提出，会讲述她为谁工作的完整故事。",al={"托卡尔是谁","托卡尔 藏宝海湾","樱桃酒任务提供者"}},{q="为什么托卡尔想要樱桃酒？",a="托卡尔在清醒时不愿意分享她过往合同的敏感细节。给她买一杯樱桃酒能让她卸下心防，从而说明是谁私下资助了针对联盟营地的劫掠。",al={"为什么要买樱桃酒","樱桃酒 托卡尔","托卡尔想要什么"}},{q="是部落负责劫掠人类和矮人营地的吗？",a="根据托卡尔的说法，针对人类和矮人营地的袭击并非部落下令。虽然传言称部落是始作俑者，但她坚称她的团队是在私人雇佣合约下工作的。",al={"谁雇佣了托卡尔","部落攻击了联盟营地吗","部落是幕后黑手吗"}},{q="为什么托卡尔担心治安官？",a="托卡尔害怕遭到正在调查劫掠人类和矮人定居点事件的治安官的追捕。她非常小心，确保在藏宝海湾接近她的人不是被派来将她绳之以法的代理人。",al={"治安官是谁","托卡尔在躲避治安官吗","治安官寻找托卡尔"}},{q="在哪里可以为托卡尔弄到樱桃酒？",a="樱桃酒是一种可以从藏宝海湾的旅店老板和酒保处买到的饮料。给托卡尔送上一杯这种酒，就能满足她的要求，并促使她说出她的故事。",al={"哪里可以得到樱桃酒","樱桃酒位置","藏宝海湾的酒"}},{q="为什么托卡尔待在藏宝海湾？",a="藏宝海湾是一个中立的自由港，不受联盟和部落的严格管辖。对于一名在劫掠了人类和矮人定居点后想要避风头的雇佣兵来说，这里是一个理想的藏身处。",al={"为什么托卡尔在藏宝海湾","托卡尔的藏身处"}}},fp="25,253,25.465.0,19.385.1,13.261.0,34.209.0,68.211.0,37.204.0,39.194.0,34.217.0"}
P.entries["quest:793"] = {n="破碎的联盟",s="高恩派遣你去荒芜之地最东端的莱瑟罗峡谷，黑龙BossBlacklash和Hematus正被大地印章束缚在那里。这是“破碎的联盟”任务之后的后续。",h="高恩派遣你去荒芜之地最东端的莱瑟罗峡谷，黑龙BossBlacklash和Hematus正被大地印章束缚在那里。这是“破碎的联盟”任务之后的后续。",kw={"黑龙军团","blacklash","黑石兽人","高恩","hematus","莱瑟罗峡谷","大地印章"},sec={{t="三块符文石",b="三块符文石封印着大地印章。它们分别位于莱瑟罗峡谷的几根石柱中：钻石、猫眼石和紫水晶。高恩交给你的大地印章可以抽出这些石头并解开封印。峡谷里栖息着无数龙类，Blacklash和Hematus非常强大。高恩希望杀掉它们，并带回它们的束缚物。"},{t="高恩的意图",b="高恩称黑龙军团依然与黑石氏族的叛徒兽人结盟，无论龙类还是兽人都必须受到约束或被铲除。一旦Blacklash和Hematus伏诛，部落就可以将目光投向西边的黑石塔了。"}},faq={{q="谁发布了这个任务？",a="由高恩发布，作为“破碎的联盟”之后的下一步。",al={"破碎的联盟任务发布者","高恩位置","谁发布破碎的联盟"}},{q="莱瑟罗峡谷在哪里？",a="前往荒芜之地的最东端。峡谷中栖息着无数龙类。",al={"莱瑟罗峡谷位置","如何前往莱瑟罗峡谷","莱瑟罗峡谷在哪里"}},{q="如何释放Blacklash和Hematus？",a="大地印章可以从三根石柱中分别抽出一块符文石。将这些石头嵌入大地印章中，就能解开两头龙的束缚。",al={"如何召唤blacklash","大地印章","钻石猫眼石紫水晶石柱"}},{q="必须带回给高恩什么东西？",a="在两头龙死亡后，带回Blacklash的束缚物、赫玛图斯的锁链以及大地印章。",al={"破碎的联盟任务交付物品","高恩想要回什么","blacklash的束缚物"}}},fp="16,183,16.352.0,21.238.1,21.65.0,32.94.0,38.136.0,34.102.0"}
P.entries["quest:794"] = {n="火刃奖章",s="这项任务由术士祖雷萨指派，要求年轻的部落新兵深入试炼谷的火刃集会所洞穴。在那里，玩家必须直面一名潜藏的邪教徒，并找回一件名为火刃奖章的黑暗魔法神器。这项任务揭示了恶魔的腐化正在部落的眼皮底下生根发芽。",h="这项任务由术士祖雷萨指派，要求年轻的部落新兵深入试炼谷的火刃集会所洞穴。在那里，玩家必须直面一名潜藏的邪教徒，并找回一件名为火刃奖章的黑暗魔法神器。这项任务揭示了恶魔的腐化正在部落的眼皮底下生根发芽。",kw={"火刃氏族","集会所","杜隆塔尔","奖章","大兽穴","试炼谷","术士","yarrog baneshadow","祖雷萨"},ang={["class:Shaman"]="找回受污染的圣物有助于祖雷萨揭露那些玷污杜隆塔尔大地的恶魔腐化。",["class:Warlock"]="直面 Yarrog 是一个严酷的提醒，警示着在 Thrall 统治下所制定的受认可、经过仔细隐藏的契约之外，进行堕落的恶魔崇拜所带来的危险。",["faction:Horde"]="这项任务代表了年轻新兵的最终试炼，标志着他们已准备好前往杜隆塔尔更广阔的荒野，以保卫这个年轻的国家。",["race:Orc"]="追捕 Yarrog Baneshadow 凸显了新部落在训练场内清除旧时代残留恶魔污秽的内部斗争。"},sec={{t="谷中的隐藏威胁",b="当年轻的兽人和巨魔在试炼谷进行基础的战斗与生存试炼时，一股阴险的威胁正潜伏在阴影中。通过占卜，术士祖雷萨感觉到那些盘踞在北部峭壁上的邪恶魔仆只不过是更黑暗势力的先遣队。在附近的一个洞穴深处，火刃氏族建立了一个隐秘的集会所，他们在那练习黑暗魔法，并窝藏着危险的恶魔力量圣物。"},{t="直面 Yarrog Baneshadow",b="这枚奖章正掌握在 Yarrog Baneshadow 手中，这是一名充当火刃氏族代理人的兽人术士。Yarrog 躲藏在地下大兽穴深处的一处高台上，指挥着邪能野兽并施展黑暗魔法，避开了谷中监视者的目光。击败他并夺取奖章，可以在该邪教的仪式进一步蔓延到杜隆塔尔腹地之前，扰乱其当地的领导层。"},{t="挥之不去的阴影",b="获得这枚护身符证实了祖雷萨最担心的事。虽然试炼谷中的集会所已被拆除，但奖章证明了火刃氏族是有组织、有目的地在行动。该邪教的触角已远超试炼场，预示着羽翼未丰的部落将在整个杜隆塔尔面临更广泛的恶魔阴谋。"}},faq={{q="我在哪里可以找到火刃集会所？",a="火刃集会所位于试炼谷大兽穴西北方峭壁内的一个洞穴中，周围环绕着类似小鬼的邪恶魔仆。",al={"集会所洞穴位置","洞穴在哪里","试炼谷火刃氏族洞穴"}},{q="谁持有火刃奖章？",a="奖章由 Yarrog Baneshadow 持有，这名堕落的兽人邪教徒位于洞穴深处，处于浅水池后方的一处凸起的岩石平台上。",al={"谁掉落奖章","yarrog baneshadow","奖章持有者"}},{q="火刃氏族是什么？",a="火刃氏族是一个背叛的邪教组织，由受到邪能腐蚀的兽人和术士组成，他们沉迷于恶魔力量，并从隐藏的巢穴和营地中积极策划对抗 Thrall 的新部落。",al={"火刃氏族是什么","火刃邪教"}},{q="为什么这枚奖章对祖雷萨如此重要？",a="祖雷萨通过她的占卜发现了这枚奖章。它是一件能够助长邪教黑暗仪式的力量物品，并提供了无可辩驳的证据，证明恶魔特工正在渗透试炼谷。",al={"为什么祖雷萨想要它","什么是奖章","祖雷萨奖章"}},{q="击败 Yarrog 能彻底铲除杜隆塔尔的邪教吗？",a="不能。虽然 Yarrog 的死亡净化了试炼谷的洞穴，但祖雷萨警告说，这个集会所只是一个小组织，火刃氏族在整个杜隆塔尔还有更大的野心。",al={"火刃氏族被消灭了吗","他们消失了吗","火刃奖章之后"}},{q="上交奖章后会发生什么？",a="在击杀 Yarrog 并找回圣物证明了你的价值后，你被认为已经准备好离开试炼谷，并被指引前往杜隆塔尔南海岸的森金村报到。",al={"下一个任务","what comes next","完成此任务后"}}},fp="23,252,29.414.0,29.344.1,20.292.1,40.145.0,44.124.0,26.181.0,54.167.0,53.178.0,44.187.0"}
P.entries["quest:79974"] = {n="Wet Job",s="Wet Job是一个任务，其核心在于寻找一个遗留在高耸山腰上的应急补给箱。为了应对突发撤离的情况，这个补给箱被隐藏在风景秀丽的悬崖边，其中存放的物资通过精巧的矮人工艺得到了妥善保护。",h="Wet Job是一个任务，其核心在于寻找一个遗留在高耸山腰上的应急补给箱。为了应对突发撤离的情况，这个补给箱被隐藏在风景秀丽的悬崖边，其中存放的物资通过精巧的矮人工艺得到了妥善保护。",kw={"矮人工程","鹰巢","邮差包","山腰","羊皮纸","储备物资","补给品","wet job"},ang={["class:Rogue"]="对于生活在阴影中的人来说，将隐藏的应急补给箱藏好以备匆忙撤离，是他们的第二天性。",["profession:Engineering"]="该补给箱展示了矮人工程的独创性，作为隐藏在崎岖地形中的可靠应急库存。",["race:Dwarf"]="在找回补给箱的过程中，矮人工艺受到了赞誉，突显了他们山地手工制品持久的品质。"},sec={{t="应急补给箱",b="那些在危险条件下行动的人深知，不准备备用计划绝不能贸然行动。Wet Job要求定位一个隐藏在崎岖高地上的储备物资。作为紧急情况下的备用措施，万一需要快速撤离，这个补给箱便可以在计划出错时随时取用。"},{t="鹰巢",b="线索直接指向一处风景优美的山地制高点，诗意地描述为从时间的瀑布中雕刻而成。在这面岩壁的高处坐落着所谓的“鹰巢”。在那里，半埋在地下的一个风化邮差包，利用可靠的矮人工艺保护着里面的物资和羊皮纸，使其免受自然环境的侵蚀。"}},faq={{q="Wet Job是什么任务？",a="Wet Job是一个涉及找回隐藏在地貌中的应急储备物资的任务。准备这个补给箱的人确保了在需要紧急撤离时，物资能够得到保障。",al={"什么是wet job","wet job任务","wet job是什么类型的任务"}},{q="是谁留下了这个储备物资？",a="这个物资是由一个为防万一需要匆忙撤离而准备应急储备的人所留下的。找回的邮差包中藏有羊皮纸和通过卓越矮人工程制造的物资。",al={"是谁留下了储备物资","这些物资是谁的","谁隐藏了应急补给"}},{q="补给箱藏在哪里？",a="线索指向一处风景如画的山腰，那里被描述为从时间的瀑布中雕刻而成，具体指引寻找者前往岩壁高处的一处鹰巢，在那里邮差包从泥土中显露出来。",al={"补给箱在哪里","wet job位置","鹰巢位置"}},{q="邮差包里有什么？",a="打开埋藏的邮差包，会发现里面有必需的补给品和一张隐藏的羊皮纸，它们受到坚固耐用的矮人工艺的保护。",al={"补给箱里有什么","wet job物品","你会发现什么"}},{q="为什么这个任务被称为Wet Job？",a="虽然这个标题通常暗示隐秘或混乱的现场行动，但在这里它直接联系到山地的地标，周围是迷雾、时间的瀑布以及隐藏包裹的潮湿泥土。",al={"为什么叫wet job","wet job名字含义"}},{q="矮人工程是如何参与的？",a="在发现并打开补给箱后，该补给箱的结构和可靠性被赞誉为矮人工程的奇迹，足以承受户外埋藏环境。",al={"与矮人工程的联系","这是矮人制造的吗"}}},fp="7,246,18.303.0,16.356.0,32.206.0,27.218.0,26.221.0,35.155.0,31.186.0,36.165.0"}
P.entries["quest:79975"] = {n="Eagle's Fist",s="Eagle's Fist围绕着一封在迷雾缭绕的高海拔制高点工具箱中发现的神秘信件展开。信中揭示了一名孤独的哨兵，出于对旧王国以及“鹰与拳”的忠诚，守护着一座风化的路障。尽管篝火刚添过柴，但守望者已匆忙离开。",h="Eagle's Fist围绕着一封在迷雾缭绕的高海拔制高点工具箱中发现的神秘信件展开。信中揭示了一名孤独的哨兵，出于对旧王国以及“鹰与拳”的忠诚，守护着一座风化的路障。尽管篝火刚添过柴，但守望者已匆忙离开。",kw={"路障","篝火","eagle's fist","折叠的信","瞭望点","旧王国","降落伞滑翔机","工具箱"},ang={["profession:Engineering"]="这名瞭望者的笔记强调了此地是部署降落伞滑翔机的理想出发点，吸引了那些青睐空中侦察和机械飞行的工程学爱好者的注意。"},sec={{t="一处隐蔽的栖身之所",b="在一处风景优美的制高点，一个不起眼的工具箱里藏着一封折叠整齐的信。作者反思了这个高处瞭望台居高临下的位置，感叹这里既可以掌控全局，也能发射降落伞滑翔机飞越地貌。在这片被水雾浸湿的孤独哨位上，可以将历史悠久的土地尽收眼底。"},{t="对旧王国的忠诚",b="写信人声称对“鹰与拳”怀有深厚而持久的忠诚，并指出要妥善效忠于这一事业，需要保持适当的距离。虽然承认当地的路障已经年久失修——正如它曾经抵御危险的旧王国一样——但这位坚定的守望者发誓绝不会真正放弃这个岗位。"},{t="匆忙离去",b="不论是谁负责这个瞭望点，他们离开时都十分匆忙。发现该岗位的游客会看到一堆刚添过新柴的篝火，但哨兵却消失得无影无踪，只留下了工具、燃烧的余烬和那封神秘的信。"}},faq={{q="什么是Eagle's Fist？",a="Eagle's Fist是一次围绕着一个隐藏工具箱的遭遇，箱内装有一封折叠整齐的信，位于俯瞰一座旧路障、风景优美且雾气缭绕的制高点。它标志着一位最近逃离的神秘斥候的营地。",al={"什么是eagle's fist","eagle's fist任务","这是什么任务"}},{q="工具箱里的信是谁写的？",a="作者是一位身份不明的斥候或哨兵，忠于旧王国以及一个被称为“鹰与拳”的实体或联盟。他们在这座破败的路障处进行着孤独的守望。",al={"谁写的便条","谁留下的信","工具箱信件作者"}},{q="“鹰与拳”指的是什么？",a="信中提到了对“鹰与拳”的忠诚，并指出只有保持距离才能更好地效忠。虽然确切的组织情况仍是个谜，但它与保卫旧王国的残余势力有关。",al={"什么是鹰与拳","鹰与拳的含义","鹰与拳是谁"}},{q="营地为何被废弃了？",a="这名斥候匆匆离开，留下了一堆刚添过新柴的篝火。他们的去向仍然未知，不过这个地点被赞誉为部署降落伞滑翔机的绝佳场所。",al={"斥候去哪了","他们为何离开","谁添加的篝火燃料"}},{q="正在防守的是什么路障？",a="作者感叹该路障已不复往昔，将其破损的状态比作它曾经守护的、已陨落的人类旧王国，但却誓言绝不放弃对它的守卫。",al={"什么路障","哪些旧王国","路障背景故事"}},{q="这是一个什么样的瞭望点？",a="这个岗哨拥有绝佳的全景视野，空气中弥漫着水雾，表明它位于大型瀑布或湍流河道附近的高耸悬崖或制高点上。",al={"地点位置","为什么有水雾","eagle's fist位置"}}},fp="12,314,14.373.0,27.351.0,17.260.1,21.224.0,42.189.0,40.196.0,30.194.0,33.186.0,34.159.0"}
P.entries["quest:79976"] = {n="This Must Be The Place",s="This Must Be The Place标记了一个刚刚废弃的营地，其主人就在不久前刚刚消失。留下来的一张字条碎片揭示了这位神秘的作者为了防止研究成果落入不轨之徒手中，已转入地下继续工作。",h="This Must Be The Place标记了一个刚刚废弃的营地，其主人就在不久前刚刚消失。留下来的一张字条碎片揭示了这位神秘的作者为了防止研究成果落入不轨之徒手中，已转入地下继续工作。",kw={"废弃营地","装备包","藏身处","睡袋","this must be the place","字条碎片","地下"},sec={{t="匆忙离开",b="在这个偏僻的地方，一位身份不明的旅者刚刚匆忙撤离营地。现场只留下一只摊开在脚下的睡袋、捆扎着各类装备的沉重帆布，以及一张撕得刚好写下一句匆忙告别的字条。无论谁曾在这里露营，都在别人赶到之前就已不见踪影。"},{t="转入地下",b="留下的字条揭示了作者决定将他们的工作带回地下，以确保其不会落入不轨之徒的手中。这张字条究竟是最后的告别，还是暗示研究者下一个隐秘据点的线索，目前还不得而知，只留下一堆废弃的设备给偶然发现此地的人。"}},faq={{q="那张字条是谁写的？",a="字条中并未提及作者的身份。作者只是解释说，为了防止研究成果落入不轨之徒手中，他们决定转入地下，留下了废弃的营地和装备。",al={"谁写的字条","字条作者","谁留下了信息"}},{q="什么样的工作被带到了地下？",a="作者工作的具体性质尚未揭晓。他们提到转入地下仅仅是为了保护他们的研究或成果，使其免受可能滥用这些成果的不明敌人的侵害。",al={"什么地下工作","为什么要带入地下","什么工作"}},{q="营地的主人去了哪里？",a="无论占据此地的人是谁，他们都匆忙打包并在有人抵达前不久溜走了。他们的去向不明，尽管字条暗示他们可能转移到了另一个隐蔽的藏身处。",al={"我是不是错过了他们","他们去了哪里","作者在哪里"}},{q="营地里留下了什么？",a="这位旅者留下了一只未能收好、散落在地上的睡袋、包着各种装备的沉重帆布，以及一个装有杂物的背包。",al={"留下了什么","营地的补给品","背包里有什么"}},{q="这是否通往另一个藏身处的线索？",a="这张字条碎片含义模糊，无法确定这究竟是道别的话语，还是指引作者下一个地下避难所的有意留下的线索。",al={"还有其他的藏身处吗","下一个营地","更多线索"}},{q="字条中提到的“不轨之徒”是谁？",a="字条中并未具体说明谁是“不轨之徒”。作者显然担心被追捕或失窃，因此在成果可能泄露前匆忙撤离。",al={"谁是不轨之徒","不轨之徒的含义","谁在追赶作者"}}},fp="22,241,17.385.0,20.363.1,24.233.0,37.193.0,37.204.0,37.187.0,42.157.0,48.168.0"}
P.entries["quest:79980"] = {n="Scramble",s="“攀爬”是一场隐藏的寻宝游戏，指引冒险者沿着陡峭的悬崖向下寻找坐标。在寻宝者便条的引导下，旅行者们挖掘出了一个埋藏的信使袋，里面装有生存物资和一张肮脏的羊皮纸。",h="“攀爬”是一场隐藏的寻宝游戏，指引冒险者沿着陡峭的悬崖向下寻找坐标。在寻宝者便条的引导下，旅行者们挖掘出了一个埋藏的信使袋，里面装有生存物资和一张肮脏的羊皮纸。",kw={"藏匿点","悬崖边","信使袋","羊皮纸","攀爬","补给品"},sec={{t="向北的小径",b="一则神秘的信息指引着任何足够聪明的旅行者找到一个隐藏的补给藏匿点。作者在留下精确方向的同时，还留下了非正式的鼓励：向正北方向沿着险峻的悬崖行进一百步，就能找到为了让旅行者继续前行而留下的物资。"},{t="挖掘信使袋",b="沿着指示走下陡峭的悬崖面，可以发现一个埋藏的信使袋。从泥土中挖出袋子后，里面装着实用的生存物资，还有一张塞在里面的肮脏羊皮纸，暗示这次简短的“攀爬”只是更大路径的一部分。"}},faq={{q="“攀爬”任务是什么？",a="“攀爬”是一个寻宝路径任务，引导冒险者前往一个隐藏的生存物资藏匿点。一张写好的便条指引找到它的人向北沿着险峻的悬崖行进，去回收埋藏的补给。",al={"攀爬任务","什么是攀爬","攀爬藏匿点"}},{q="隐藏的藏匿点在哪里？",a="根据说明，藏匿点埋在正北方向大约一百步处，位于陡峭的悬崖下方。需要小心落脚，以免从岩壁上跌落。",al={"藏匿点在哪里","如何找到藏匿点","藏匿点位置"}},{q="是谁留下了便条和藏匿点？",a="作者的确切身份不明。写信人留下了一些非正式的实用笔记，意在让探险者定位他们的应急物资，并确认藏匿点保持完好。",al={"谁写了攀爬便条","谁留下了藏匿点","攀爬任务作者"}},{q="埋藏的藏匿点里有什么？",a="挖出藏匿点后，会发现一个埋藏的信使袋，里面装有生存物资和一张夹在装备中的肮脏羊皮纸。",al={"攀爬任务奖励","攀爬藏匿点里有什么","袋中物品"}},{q="与物资一起发现的肮脏羊皮纸是什么？",a="肮脏的羊皮纸与补给品一起塞在埋藏的信使袋里，是在将袋子从地下拉出来时被发现的。",al={"攀爬肮脏羊皮纸","羊皮纸上写了什么","攀爬便条"}},{q="到达藏匿点有什么危险？",a="主要的危险在于从北面的悬崖向下进行陡峭的下降，任何失足都可能导致脚踝骨折或严重的坠落。",al={"攀爬危险","悬崖攀爬","攀爬悬崖边"}}},fp="8,230,19.287.0,28.257.1,27.196.0,34.200.0,32.193.0,32.125.0,52.139.0,48.143.0"}
P.entries["quest:8"] = {n="潜行者的交易",s="卡尔文·蒙泰古在丧钟镇请求的一件看似随意的差事，将一名旅行者送上了前往布瑞尔恐惧之末旅店的道路。这项差事涉及以普通信使的名义，向旅店老板瑞尼递送一封神秘且没有收件人地址的信件。",h="卡尔文·蒙泰古在丧钟镇请求的一件看似随意的差事，将一名旅行者送上了前往布瑞尔恐惧之末旅店的道路。这项差事涉及以普通信使的名义，向旅店老板瑞尼递送一封神秘且没有收件人地址的信件。",kw={"布瑞尔","卡尔文·蒙泰古","丧钟镇","恐惧之末","旅店老板瑞尼","笔迹潦草的信件","潜行者","提瑞斯法林地"},ang={["class:Rogue"]="卡尔文·蒙泰古的私人信使差事让人们得以一窥丧钟镇和布瑞尔周围进行的非正式交易。",["faction:Horde"]="这次投递直接通向布瑞尔，将刚到达的盟友引向提瑞斯法林地被遗忘者行政和休整的区域中心。",["race:Undead"]="对于刚复活的被遗忘者来说，这项差事标志着他们第一次离开丧钟镇墓地的安全范围，前往熙熙攘攘的布瑞尔中心。"},sec={{t="友好的信使",b="卡尔文·蒙泰古在丧钟镇那庄严肃穆的墓地和破败的礼拜堂间徘徊，表现得像个被天灾僵尸和爬行的蜘蛛折磨得精疲力竭的战士。他声称自己只是需要人手帮忙把一封信送到布瑞尔，并将一封未标记的信件托付给路过的冒险者。他轻松的态度和丰厚报酬的承诺，让这项任务看起来不过是件为了引导刚觉醒的被遗忘者前往该地区主要城镇而进行的无害之举。"},{t="恐惧之末旅店",b="道路向东延伸，穿过提瑞斯法林地那枯萎的树木，经过炉灰庄园，最终到达布瑞尔定居点。在当地旅店的柜台后，旅店老板瑞尼最初以一种令人不安的阳光态度迎接新人，对客人的舒适度关怀备至。然而，在收到蒙泰古的信件后，她的热情立刻土崩瓦解。她抛弃了伪装出来的亲切，佯称自己收到了来自慈母的消息，随后责骂信使多管闲事，并要求他们买点东西或者立刻离开。事后回到卡尔文那里又会出现另一个惊喜：他并没有和平地支付承诺的报酬，而是向信使发起了决斗。"}},faq={{q="卡尔文·蒙泰古是谁？",a="卡尔文·蒙泰古是丧钟镇的一名潜行者，他请求刚觉醒的旅行者帮他把一封信送到布瑞尔的旅店老板瑞尼手中。他将此描述为一个简单的恩惠，并承诺给予丰厚的回报。",al={"卡尔文·蒙泰古","谁发布潜行者的交易","任务发布者"}},{q="笔迹潦草的信件里写了什么？",a="这封信的具体内容并未被记录。卡尔文交给信使一封未标记的信件，要求送给布瑞尔的旅店老板瑞尼。",al={"笔迹潦草的信件内容","信里有什么","卡尔文的信"}},{q="为什么旅店老板瑞尼表现得如此奇怪？",a="瑞尼经营着布瑞尔的旅店，并坚称她的信件是私人的。将蒙泰古的信件带给她，就能揭晓她对这次投递的反应。",al={"旅店老板瑞尼的态度","为什么瑞尼在演戏","瑞尼母亲的借口"}},{q="卡尔文·蒙泰古真的会为这次投递支付报酬吗？",a="蒙泰古承诺会为投递支付高额报酬。当信件送达时，瑞尼会提供食物或水；事后请回到卡尔文那里，继续就他承诺的报酬进行交涉。",al={"卡尔文是不是骗我","我的钱在哪里","蒙泰古的奖励"}},{q="布瑞尔在哪里？",a="布瑞尔位于丧钟镇的东北方。旅行者沿着起始山谷的主要道路向东走，向右拐过炉灰庄园，穿过一座廊桥即可到达该定居点。",al={"如何前往布瑞尔","去布瑞尔的路","布瑞尔路线指引"}},{q="把信交给瑞尼之后会发生什么？",a="后续任务名为“潜行者的交易”。回到丧钟镇的卡尔文·蒙泰古那里，继续与他进行交易。",al={"下一个任务","潜行者的交易后续","交给瑞尼后做什么"}}},fx={df83fdd9={q="卡尔文·蒙泰古为什么要送出这封信？",a="卡尔文·蒙泰古声称，自己在丧钟镇附近对付过不少毫无理智的僵尸和蜘蛛，现在只需要有人替他跑一趟腿。他不愿亲自沿路走到布瑞尔，便提出付给你一大笔钱，让你把他封好的、笔迹潦草的信件直接送给旅店老板瑞尼。",al={"卡尔文·蒙泰古的动机","为什么要把信送给瑞尼","卡尔文为什么要我做这件事"}}},fp="14,250,18.483.0,23.691.1,23.180.0,38.130.0,40.160.0,51.182.0,23.181.0,46.130.1"}
P.entries["quest:80"] = {n="斯塔文的传说",s="调查斯塔文·密斯曼托的关键一步是将收集到的证据提交给夜色镇的当局。指挥官阿尔泰娅·埃伯洛克手中拿着一张染血的日记书页，指示调查员去找书记员达尔塔，以便彻底鉴定笔迹的真伪。",h="调查斯塔文·密斯曼托的关键一步是将收集到的证据提交给夜色镇的当局。指挥官阿尔泰娅·埃伯洛克手中拿着一张染血的日记书页，指示调查员去找书记员达尔塔，以便彻底鉴定笔迹的真伪。",kw={"althea ebonlocke","染血的日记书页","书记员达尔塔","夜色镇","暮色森林","斯塔文的传说","夜色守夜人","斯塔文·密斯曼托"},ang={["faction:Alliance"]="这次调查突显了像夜色镇这样的边境城镇尽管受到亡灵和暗影野兽的围困，却依然努力维持法律、秩序和民事记录。",["race:Human"]="对于南方王国的人类来说，这个任务触及了将暴风城贵族、暮色森林定居者和艾尔文森林散落的庄园联系在一起的各种悲剧。"},sec={{t="收网",b="随着在暮色森林及周边人类领地搜寻到的日记书页留下的线索，夜色守夜人终于掌握了似乎能证实那个难以捉摸的导师——斯塔文·密斯曼托罪行的确凿证据。指挥官阿尔泰娅·埃伯洛克对这个人抱有怀疑已经有一段时间了，但要进行正式宣判，就需要绝对的确定性。在能够毫无疑问地证明这些恐怖的文字确实出自斯塔文之手前，单单一页染血的日记还不足以定罪。"},{t="书记员的慧眼",b="为了弥合怀疑与确定性之间的差距，夜色守夜人求助于夜色镇的镇档案管理员，书记员达尔塔。由于多年来一直负责镇上的登记工作，达尔塔检查过无数的账簿和签名，这使他成为了笔迹鉴定方面的权威。将新发现的日记书页与镇档案中斯塔文过去的签名直接进行对比，提供了确认其堕落和罪行所需的最后且无可辩驳的证据。"}},faq={{q="为什么埃伯洛克指挥官需要达尔塔书记员的确认？",a="指挥官阿尔泰娅·埃伯洛克希望在采取最终行动之前，确保斯塔文的罪行得到毫无疑问的证实。书记员达尔塔负责管理夜色镇的镇登记册，并且在检查签名方面经验丰富，这使他有独特的资格来验证那页染血的日记是否与镇档案中斯塔文的笔迹相符。",al={"为什么要找达尔塔","为什么要核对笔迹","书记员达尔塔的作用"}},{q="这一步在“斯塔文的传说”故事线中处于什么位置？",a="这是这项漫长调查的第十一章。它发生在找回染血的日记书页之后，是夜色守夜人对斯塔文采取果断行动之前进行的最后证据核实。",al={"这是任务的哪一部分","任务链进度","斯塔文任务链顺序"}},{q="书记员达尔塔在夜色镇的什么位置？",a="书记员达尔塔可以在夜色镇的市政厅内找到，他负责为社区管理当地的记录和财产登记册。",al={"达尔塔的位置","书记员达尔塔在哪里","寻找达尔塔"}},{q="调查员带给夜色镇什么证据？",a="调查员携带了一页在持续搜寻斯塔文下落的过程中找回的染血的日记书页。书页上的文字描述了他阴暗的思想和经历，但需要与官方记录进行笔迹比对。",al={"证据是什么","这是哪一页","染血的日记书页背景"}},{q="书记员达尔塔确认那是斯塔文的笔迹吗？",a="是的。通过将染血的书页与镇登记册中的签名进行比对，达尔塔确认笔迹相符，这让埃伯洛克在采取最终行动前获得了她所需要的确定性。",al={"笔迹匹配吗","是斯塔文吗","是斯塔文写的吗"}},{q="为什么夜色守夜人对指控斯塔文如此谨慎？",a="即使在暮色森林这片饱受困扰、与世隔绝的土地上，夜色守夜人也在努力维持合法的秩序。指控一位前学者犯下骇人听闻的罪行需要具体的、可验证的证据，而不是仅仅依靠传闻或推测。",al={"为什么要证据","为什么不直接杀了斯塔文","埃伯洛克的怀疑"}}},fp="21,205,15.391.0,15.326.1,62.326.0,62.225.0,43.121.0,54.194.0,55.187.1,58.224.0"}
P.entries["quest:804"] = {n="萨科斯",s="在为受伤的暗矛巨魔哈纳祖报仇，击杀了恐怖的蝎虫萨科斯之后，冒险者必须将他的困境传达回大兽穴。必须立刻通知高内克，这样救援才能及时抵达，在剧毒夺去这位侦察兵的性命之前将他救回。",h="在为受伤的暗矛巨魔哈纳祖报仇，击杀了恐怖的蝎虫萨科斯之后，冒险者必须将他的困境传达回大兽穴。必须立刻通知高内克，这样救援才能及时抵达，在剧毒夺去这位侦察兵的性命之前将他救回。",kw={"暗矛","杜隆塔尔","高内克","哈纳祖","萨科斯","蝎虫","大兽穴","试炼谷"},ang={["faction:Horde"]="新部落建立在严酷无情的土地上，强调共同生存；不抛弃任何一名同伴是学徒从迈出第一步起就被教导的基本原则。",["race:Orc"]="兽人文化重视个人的力量，但挺身而出捍卫一名失去行动能力的盟友的荣誉，这证明了一个真正战士的内心。",["race:Troll"]="暗矛部族与萨尔的兽人之间萌芽的联盟，正是通过诸如从缓慢的剧毒死亡中拯救哈纳祖这类兄弟情谊的行为而得以加强。"},sec={{t="侦察兵的困境",b="暗矛侦察兵哈纳祖被困在试炼谷的高耸峭壁上，他身中剧毒，无法独自走下险峻的山路。虽然他击败了将他打倒的恐怖蝎虫萨科斯并完成了复仇，但仅凭骄傲无法支撑一位中毒的战士穿越这片贫瘠的乱石之地。他被困在岩石上，只能寄希望于路过的学徒将消息带回训练营地。"},{t="大兽穴的荣誉",b="回到大兽穴向高内克复命即可完成试炼。高内克立刻意识到了萨科斯的威胁，并迅速组织人手营救哈纳祖。在部落指挥官眼中，暂时放下个人的训练去伸张正义并营救一名落难的陌生人，体现了真正的荣誉。这证明了学徒在真正踏入杜隆塔尔之前就已经具备了应有的价值。"}},faq={{q="哈纳祖是谁，他为什么会被困住？",a="哈纳祖是一位年轻的暗矛巨魔侦察兵，他在前往试炼谷高处时遭到恐怖蝎虫萨科斯的伏击并中毒。由于虚弱无法独自爬下山崖，他需要救援。",al={"哈纳祖","哈纳祖是谁","为什么巨魔受伤了"}},{q="高内克是谁？",a="高内克是一位驻扎在试炼谷大兽穴的兽人监工。他负责评估新兵、分配生存任务，并在学徒在峡谷中遭遇致命威胁时协调救援。",al={"高内克","高内克在哪里","大兽穴领导者"}},{q="萨科斯是什么？",a="萨科斯是一只臭名昭著的巨型蝎虫，栖息在试炼谷上方的岩石峭壁中。它的剧毒和凶猛使它成为年轻兽人和巨魔试炼中的一个传说级威胁。",al={"野兽萨科斯","萨科斯是什么样的怪物"}},{q="哈纳祖的伤势能痊愈吗？",a="高内克承诺在收到你的报告后会立即派遣救援前往哈纳祖所在的地方。至于这位侦察兵后来如何，文中并未提及。",al={"巨魔活下来了吗","哈纳祖还好吗","哈纳祖获救"}},{q="为什么高内克如此高度赞扬这一行为？",a="人们期望你能从试炼中存活下来，但将你自己的任务搁置一旁，为了一个陌生人的荣誉而战并确保他们能活下去，这才是新部落试图在战士身上培养的核心价值观。",al={"为什么高内克在意","高内克的荣誉演讲"}},{q="大兽穴在哪里？",a="大兽穴是位于杜隆塔尔西南部试炼谷中心地带的中央训练洞穴和集结地。",al={"大兽穴在哪里","杜隆塔尔大兽穴位置"}}},fp="7,197,16.333.0,16.328.0,39.172.0,14.182.0,16.183.0,33.121.1,43.179.0,25.117.0"}
P.entries["quest:805"] = {n="去森金村报到",s="“向森金村报告”标志着年轻的部落新兵离开了与世隔绝的试炼谷，去警告暗矛巨魔有关恶魔邪教活动的时刻。在祖雷萨的委托下，信使将火刃氏族的消息带给了加德林大师，并发现暗影魔法已经威胁到了附近的海岸。",h="“向森金村报告”标志着年轻的部落新兵离开了与世隔绝的试炼谷，去警告暗矛巨魔有关恶魔邪教活动的时刻。在祖雷萨的委托下，信使将火刃氏族的消息带给了加德林大师，并发现暗影魔法已经威胁到了附近的海岸。",kw={"火刃氏族","暗矛","杜隆塔尔","回音群岛","加德林大师","森金村","试炼谷","祖雷萨"},ang={["faction:Horde"]="这项任务展示了萨尔领导的部落各大创始种族之间至关重要的合作，他们通过交换情报来保护彼此年轻的定居点。",["race:Orc"]="对于年轻的兽人来说，离开试炼谷去帮助暗矛部族是考验荣誉和团结的一项早期试炼，也是对那些在无尽之海彼岸与萨尔并肩作战的盟友展现支持的契机。",["race:Troll"]="回到森金村，暗矛冒险者们将直面族人流离失所的现状，以及收复回音群岛的持续斗争。"},sec={{t="离开大兽穴",b="在证明了自己的战斗实力并从试炼谷内的火刃集会所夺回黑暗勋章后，新手们被认为已做好准备迎接更广阔的世界。祖雷萨意识到，这些神圣试炼场中的恶魔存在并非孤立的骚乱，而是杜隆塔尔蔓延开来的枯萎症的征兆。她引导年轻的冒险者们向东穿过峡谷出口，并向南前往海岸，以警告暗矛部族。"},{t="海岸之上的阴影",b="当旅行者抵达沿海定居点森金村时，他们将警告传达给了流亡中的暗矛部族领袖、年长的巫医加德林大师。虽然加德林证实火刃氏族本身并未袭击村庄的沙滩，但他透露黑暗魔法已在附近的回音群岛生根。这份报告揭示了年轻部落的立足点依然是多么脆弱：即使盟友们竞相保卫彼此，古老的部落背叛和邪能腐蚀也在同时打击着他们的侧翼。"}},faq={{q="祖雷萨为什么派人离开试炼谷？",a="在揭露了试炼谷内的恶魔活动后，祖雷萨担心火刃集会所对整个杜隆塔尔构成了有组织的威胁。她派遣久经考验的新兵走出山谷，去警告盟友的定居点，并查明邪教的影响范围有多广。",al={"为什么要离开山谷","为什么要前往森金","祖雷萨的任务"}},{q="加德林大师是谁？",a="加德林大师是一位年长的巫医，也是居住在森金村的暗矛巨魔的精神领袖。他担任沃金酋长的顾问，在处理笼罩着他们临时沿海避难所的威胁的同时，监督部落事务。",al={"加德林大师的背景","谁是加德林"}},{q="火刃氏族袭击过森金村吗？",a="没有，火刃氏族并未直接袭击过森金村。然而，加德林大师指出，类似的黑暗魔法和背叛已经在附近的回音群岛生根，这意味着巨魔们正面临着属于他们自己的迫在眉睫的危险。",al={"火刃氏族在森金村吗","森金村的邪教"}},{q="森金村在哪里？",a="森金村位于试炼谷主峡谷出口向东的方向，在路口处向南转，沿着杜隆塔尔的东南海岸即可到达。",al={"如何前往森金村","森金村的方向"}},{q="加德林大师提到了回音群岛的什么威胁？",a="加德林大师担心扎拉赞的黑暗背叛，这名巨魔巫医同僚利用阴险的妖术奴役了他的族人并夺取了回音群岛的控制权，迫使幸存的暗矛部族逃往大陆海岸。",al={"回音群岛的麻烦","回音群岛发生了什么"}},{q="向加德林大师报告后会发生什么？",a="在听取了你的报告并详细说明了巨魔们自己的困境后，加德林请求你协助应对威胁海岸线的危险，随后的命令会将你派往西北方向，去寻找剃刀岭的奥戈尼尔·魂痕。",al={"向森金报告后的下一个任务","加德林之后做什么"}}},fp="25,256,15.398.0,22.434.1,70.251.0,21.206.0,47.176.0,33.144.0,57.235.0,46.204.0"}
P.entries["quest:806"] = {n="黑暗风暴",s="“黑暗风暴”是剃刀岭的奥戈尼尔·魂痕委派的一项重要任务，旨在铲除一名正在腐化这片土地的邪恶术士。一个名叫费索·暗风的哥布林代表阴险的火刃氏族在雷霆山扎下了根。在他进一步扩散其邪教势力之前消灭他，对于保护杜隆塔尔免受恶魔复苏的威胁至关重要。",h="“黑暗风暴”是剃刀岭的奥戈尼尔·魂痕委派的一项重要任务，旨在铲除一名正在腐化这片土地的邪恶术士。一个名叫费索·暗风的哥布林代表阴险的火刃氏族在雷霆山扎下了根。在他进一步扩散其邪教势力之前消灭他，对于保护杜隆塔尔免受恶魔复...",kw={"火刃氏族","黑暗风暴","杜隆塔尔","费索·暗风","费索的爪子","奥戈尼尔·魂痕","剃刀岭","雷霆山"},ang={["class:Shaman"]="费索及其爪牙所施行的黑暗仪式扰乱了雷霆山的自然之灵，激怒了这里的野兽，迫切需要恢复元素平衡。",["class:Warlock"]="费索·暗风展示了对邪能盲目崇拜所带来的鲁莽危险，这使他成为了一个令部落严守纪律的施法者们无法容忍的污点和隐患。",["faction:Horde"]="确保杜隆塔尔的核心区域免受恶魔的颠覆，这能让初生的部落将防御力量集中于对外，而不是从内部瓦解。",["race:Orc"]="火刃氏族代表着兽人们每天都在努力克服的黑暗过去。消灭像费索这样的邪教潜入者，对于维护萨尔建立的自由国度至关重要。"},sec={{t="岭中的威胁",b="正当年轻的部落保卫者巡视杜隆塔尔边境时，内部的腐化正在他们的眼皮底下滋生。奥戈尼尔·魂痕在剃刀岭进行调查时发现，西北方的雷霆山已陷入黑暗魔法的掌控。那片峡谷里爬满了火刃氏族的邪教徒，他们给当地的野生生物和土地带来了毁灭与混乱。"},{t="费索·暗风",b="统领峡谷内邪教活动的正是费索·暗风，一个与火刃氏族结盟的投机主义哥布林术士。费索并非为了商业或财阀利益服务，而是直接运用邪能来推动该邪教的颠覆性议程。杀掉他并取回他的扭曲爪子，向奥戈尼尔证明该峡谷内邪教的直接领导层已被瓦解。"},{t="铲除邪教",b="火刃氏族代表着萨尔的新部落竭力摒弃的一切：恶魔奴役、鲁莽的腐化以及嗜血的疯狂。铲除费索不仅从杜隆塔尔的腹地清除了一名活跃的阴谋家，也预示着笼罩在兽人故乡上的阴影远比一些孤立的营地要深远得多。"}},faq={{q="谁是费索·暗风？",a="费索·暗风是一名代表火刃氏族行事的哥布林术士。他和他的邪教追随者躲藏在雷霆山，在峡谷中散布恶魔带来的混乱，直到奥戈尼尔·魂痕下令将他处决。",al={"谁是费索","费索·暗风背景故事","费索哥布林"}},{q="雷霆山位于何处？",a="雷霆山是一条崎岖的峡谷，位于杜隆塔尔西北部，剃刀岭以北，奥格瑞玛西南方。这里以充斥着带有闪电能量的野兽和火刃氏族邪教营地而闻名。",al={"雷霆山在哪里","雷霆山位置","如何找到雷霆山"}},{q="为什么火刃氏族会出现在杜隆塔尔？",a="火刃氏族试图破坏萨尔的部落，并重建恶魔对兽人的统治。他们在杜隆塔尔各处的隐秘峡谷、洞穴和山涧中秘密活动，试图从内部散布腐化。",al={"杜隆塔尔的火刃氏族","为什么邪教徒在杜隆塔尔","火刃氏族的目的"}},{q="为什么奥戈尼尔·魂痕特别需要费索的爪子？",a="奥戈尼尔需要确凿的证据来证明该术士已被终结。带回费索的爪子可以确认，雷霆山邪教团伙的首领已无法继续指挥行动。",al={"为什么需要费索的爪子","费索的爪子的含义","费索死亡证明"}},{q="击杀费索后会发生什么？",a="击败费索扫清了雷霆山的直接威胁，奥戈尼尔·魂痕会指引你去找萨满祭司玛戈兹，他了解更多关于火刃氏族腐化的信息，以铲除更多火刃氏族的阴谋。",al={"黑暗风暴之后的任务","黑暗风暴后续","黑暗风暴的下一个任务"}},{q="为什么哥布林会为火刃氏族效力？",a="虽然许多哥布林通过贸易财阀追求黄金，但也有一些哥布林被暗影魔法所带来的原始力量、影响力和黑暗技艺所诱惑。费索拥抱了邪能巫术，并将他那冷酷的狡诈直接贡献给了邪教徒。",al={"哥布林与火刃氏族","费索为何加入邪教","术士费索"}}},fp="11,198,21.250.0,16.314.0,20.277.1,24.210.0,31.169.0,36.193.0,57.171.0,35.182.1,46.167.0"}
P.entries["quest:808"] = {n="明希纳的颅骨",s="森金村的加德林大师一直被他已故兄弟明希纳绝望的哭喊声所困扰。明希纳在回音群岛被邪恶的巫医扎拉赞杀害并施以黑暗魔法，他的灵魂被禁锢在自己破碎的颅骨之中。想要解救这位倒下的巨魔，必须潜入扎拉赞的仪式场地，夺回这件圣物，并使他的灵魂从永恒的折磨中解脱出来。",h="森金村的加德林大师一直被他已故兄弟明希纳绝望的哭喊声所困扰。明希纳在回音群岛被邪恶的巫医扎拉赞杀害并施以黑暗魔法，他的灵魂被禁锢在自己破碎的颅骨之中。想要解救这位倒下的巨魔，必须潜入扎拉赞的仪式场地，夺回这件圣物，并使他...",kw={"能量之环","暗矛","回音群岛","加德林","明希纳","森金村","颅骨","巫毒","扎拉赞"},ang={["class:Priest"]="牧师理解已故灵魂的神圣性，也明白那种将倒下的兄弟禁锢在永恒安宁之外的死灵仪式的恐怖。",["class:Shaman"]="萨满崇敬祖先的灵魂；打破扎拉赞的圆环来释放一个被折磨的灵魂，能够恢复精神世界与现实世界之间的平衡。",["faction:Horde"]="协助加德林大师是对新部落与暗矛巨魔之间纽带的尊重，证明了盟友的悲痛是大家共同承担的。",["race:Troll"]="对于一名暗矛巨魔来说，取回明希纳的颅骨是对家庭和部落的神圣职责，这沉重打击了扎拉赞对祖先巫毒传统的扭曲。"},sec={{t="来自阴影的恳求",b="加德林大师是森金村暗矛巨魔部落的精神支柱之一，但他此刻正深受黑暗幻象的折磨。他的兄弟明希纳在疯狂的术士扎拉赞夺取回音群岛控制权时，成为了这场背叛的受害者。明希纳在那场冲突中丧生，但在巨魔的传统和巫毒秘术中，肉体的死亡并不意味着真正的安宁。明希纳受尽折磨的声音不断在加德林的梦境中响起，恳求着从这比死亡更糟糕的命运中获得救赎。"},{t="扎拉赞的能量之环",b="扎拉赞不仅仅是杀害了他的同胞，他还捕获了他们的灵魂，以此为自己的黑暗巫术提供力量。明希纳的灵魂被仪式性地禁锢在他自己的颅骨上，现在这颗颅骨正安放在回音群岛中最大的一座岛屿上的邪恶能量之环中。在被施了妖术的巨魔守卫下，浸泡在烛光仪式之中，这颗颅骨成为了那个叛徒扭曲巫术的焦点。只要它还留在那个圆环中，明希纳就将永远受制于扎拉赞的意志。"},{t="死亡中的自由",b="为了拯救明希纳，一位勇敢的勇士必须横渡森金村东侧的水域，抵达回音群岛的南端，闯入仪式圆环，并将颅骨从那位巫医的控制中解救出来。将遗骸带回给加德林大师可以切断黑暗的束缚，让明希纳感恩的灵魂短暂现身，鞠躬致敬，最终前往祖先的国度。"}},faq={{q="明希纳是谁？",a="明希纳是加德林大师的兄弟，加德林是居住在森金村的一位杰出的巫医兼长者。他在回音群岛的叛乱中被扎拉赞杀害，扎拉赞随后利用黑暗巫术亵渎了他的遗骸。",al={"明希纳身份","明希纳是谁","加德林的兄弟"}},{q="为什么明希纳的灵魂会被困在他的颅骨里？",a="扎拉赞利用黑暗巫毒和术士魔法来奴役被杀害的暗矛巨魔的灵魂。通过将明希纳的灵魂直接禁锢在他的颅骨上，并将其放置在一个仪式的能量之环中，扎拉赞剥夺了他前往来世的通道，并奴役了他的灵魂。",al={"为何禁锢颅骨","扎拉赞灵魂陷阱","明希纳灵魂"}},{q="能量之环在哪里？",a="这个仪式地点位于杜隆塔尔东南海岸外，回音群岛中最靠南、也是最大的一座岛屿山顶之上。那里有仪式蜡烛、跳舞的受控巨魔和展示的颅骨，非常容易辨认。",al={"颅骨在哪里","能量之环位置","明希纳颅骨位置"}},{q="当颅骨被带回森金村时会发生什么？",a="加德林大师收到颅骨后，死灵束缚将会破碎。明希纳的鬼魂将出现在他的兄弟和探险者面前，感激地鞠躬，然后消失，去与祖先们安息在一起。",al={"任务交还","明希纳发生了什么","明希纳会出现吗"}},{q="扎拉赞是谁？他为什么要这么做？",a="扎拉赞曾是暗矛巨魔部落里备受尊敬的巫医。由于对力量的渴望而陷入疯狂，他背叛了部落，使用妖术控制了族人的心智，并将剩余的暗矛难民驱赶到了杜隆塔尔的大陆上。",al={"谁是扎拉赞","为什么扎拉赞是邪恶的","扎拉赞背景故事"}},{q="为什么加德林自己不去取回颅骨？",a="加德林大师对于维持森金村的稳定至关重要。他既要指导年轻的暗矛领导层，又要为酋长沃金提供建议，还要积极应对扎拉赞在海岸沿线不断蔓延的妖术，因此他无法离开村庄，使其陷入无人保护的境地。",al={"为什么加德林不亲自去","加德林的职责"}}},fp="16,277,23.479.0,26.407.0,16.363.1,17.142.0,46.240.0,37.197.0,63.199.1,39.228.0,44.220.0"}
P.entries["quest:809"] = {n="雅克塞罗斯",s="Ak'Zeloth是一个早期部落任务，由术士Neeru Fireblade在奥格瑞玛深处的Cleft of Shadow中发布。由于发现了残留的恶魔腐蚀证据，Neeru派遣冒险者前往贫瘠之地，与他驻扎在边界附近的现场联络人会合。",h="Ak'Zeloth是一个早期部落任务，由术士Neeru Fireblade在奥格瑞玛深处的Cleft of...",kw={"ak'zeloth","贫瘠之地","火刃氏族","cleft of shadow","恶魔之种","鬼雾峰","前沿哨所","neeru fireblade"},ang={["class:Warlock"]="熟悉Neeru Fireblade教导的术士可能会注意到，当他自己的助手质疑摧毁恶魔圣物的命令时，其中必有蹊跷。",["faction:Horde"]="确保前沿哨所的安全并清除鬼雾峰对于保护连接杜隆塔尔与贫瘠之地的早期贸易和交通路线至关重要。",["race:Orc"]="兽人们曾为摆脱燃烧军团的掌控而进行过艰苦的战斗，因此在他们的家门口出现火刃氏族和恶魔圣物的任何迹象都是一种迫在眉睫的威胁。"},sec={{t="暗影的踪迹",b="在杜隆塔尔发现一条火刃氏族的徽记项圈后，Neeru Fireblade声称要追捕威胁这个新定居部落的恶魔残党。Neeru自诩为对抗邪能腐蚀的守门人，他将冒险者指引向贫瘠之地的干旱平原，并警告说一个邪恶的教派正在围绕一件名为恶魔之种的邪恶神器集结。"},{t="前沿哨所的联络人",b="为了协调针对该教派的打击行动，冒险者必须寻找Ak'Zeloth，他是Neeru的助手，驻扎在杜隆塔尔与贫瘠之地交界处的前沿哨所附近。然而在抵达时，Ak'Zeloth对这项任务表现出了一种沉默的怀疑，他公开揣测他的主人为何会真心想要销毁这件神器，随后才提供了关于如何处理鬼雾峰上恶魔之种的指示。"}},faq={{q="谁发布了这个任务？",a="该任务由Neeru Fireblade发布，他是一名居住在奥格瑞玛下方Cleft of Shadow阴暗洞穴中的术士。在你向他出示火刃氏族项圈后，他便会发布此任务。",al={"任务发布者","如何找到ak'zeloth","neeru fireblade任务"}},{q="Ak'Zeloth在哪里？",a="Ak'Zeloth位于前沿哨所外，就在贫瘠之地东部边界、杜隆塔尔桥梁过处的地方。",al={"ak'zeloth位置","ak'zeloth在哪里","寻找ak'zeloth"}},{q="什么是恶魔之种？",a="恶魔之种是一件拥有恶魔之力的污秽神器，被火刃氏族教派保存在贫瘠之地北部的险峻山峰鬼雾峰之上。",al={"恶魔之种背景","什么是恶魔之种"}},{q="为什么Ak'Zeloth觉得Neeru的命令很奇怪？",a="Ak'Zeloth没有解释原因。他只是评论说Neeru想要销毁恶魔之种令人感到奇怪，然后才同意告诉你如何移除它。",al={"为什么ak'zeloth感到惊讶","ak'zeloth的奇怪反应"}},{q="这个任务之后是什么任务？",a="与Ak'Zeloth交谈会直接引导至任务“恶魔之种”，该任务要求你登上鬼雾峰来清除这件具有腐蚀性的圣物。",al={"ak'zeloth后的下一个任务","ak'zeloth后续"}},{q="这个任务是火刃氏族剧情线的一部分吗？",a="是的。它起到了关键的连接作用，将杜隆塔尔发现的当地教派阴谋与贫瘠之地中更广泛、更有组织的教派活动联系了起来。",al={"火刃氏族任务线","奥格瑞玛教派任务"}}},fp="9,134,17.308.0,19.222.1,21.132.0,27.120.0,23.122.0,47.117.1,28.105.0,50.111.0"}
P.entries["quest:812"] = {n="救命如救火",s="暗矛巨魔林纳格被困在杜隆塔尔西北部崎岖的峭壁上，身中尾蝎毒素，生命垂危。在毒素发作之前的时间所剩无几，他只能寄希望于一名信使，请求其飞奔前往奥格瑞玛，从考格汉那里取回解药。",h="暗矛巨魔林纳格被困在杜隆塔尔西北部崎岖的峭壁上，身中尾蝎毒素，生命垂危。在毒素发作之前的时间所剩无几，他只能寄希望于一名信使，请求其飞奔前往奥格瑞玛，从考格汉那里取回解药。",kw={"解毒剂","cleft of shadow","杜隆塔尔","考格汉","寻求治疗","奥格瑞玛","林纳格","蝎子","尾蝎"},ang={["faction:Horde"]="杜隆塔尔的岩石地形严酷无情，对于新抵达萨尔年轻王国的保卫者而言，这是一场永无止境的烈火试炼。",["race:Troll"]="林纳格对返回森金村的恐惧，凸显了暗矛部族那严苛的自尊心，在荒野生存中表现出的粗心大意会招致同族的严厉嘲讽。"},sec={{t="蝎子的毒刺",b="杜隆塔尔干旱的峡谷中到处都是尾蝎，这些侵略性极强的掠食者尾刺中带有迅速且令人虚弱的神经毒素。林纳格在边境附近与这些野兽战斗时一时大意，不幸中毒。深知毒素蔓延下他活不过一小时，身体也无法支撑他自己走到城门，他只能将生存的希望托付给每一个经过他营地的人。"},{t="阴影中的秘密",b="林纳格没有去寻找普通的药剂师或萨满，而是指引旅人深入奥格瑞玛地底的暗影裂口——大断崖。那里住着考格汉，一位对杜隆塔尔荒野剧毒了如指掌的神秘修行者。考格汉拥有配制强效解毒剂的知识，但他很少轻易向那些尚未证明自己实力的人提供帮助。"}},faq={{q="林纳格是谁？",a="林纳格是一名暗矛巨魔冒险者，在杜隆塔尔西北部的峭壁上奄奄一息。他被尾蝎刺伤，不仅担心即将到来的死亡，更害怕如果以如此狼狈的状态回到森金村，会招致族人的嘲笑。",al={"林纳格背景故事","林纳格是谁","巨魔林纳格"}},{q="为什么考格汉在大断崖？",a="考格汉住在大断崖，这是奥格瑞玛地下的阴暗洞穴，术士、潜行者和其他黑魔法修行者都在这里避开萨尔荣誉卫士的目光进行活动。他对毒药配方和残酷试炼的理解与大断崖的地下环境非常契合。",al={"考格汉在哪里","谁是考格汉","考格汉位置"}},{q="为什么林纳格不直接去森金村找萨满或治疗者？",a="林纳格承认是自己的自尊心在作祟。他担心以如此大意且身中剧毒的状态回到森金村只会遭到同族巨魔的嘲笑，因此更愿意从考格汉那里寻求隐秘的治疗。",al={"为什么不去森金村","林纳格为何避开森金村"}},{q="林纳格服下解药后会发生什么？",a="林纳格喝下解药后恢复了健康，但他的麻烦并未就此结束。以他对考格汉的了解，这位施药者会要求林纳格通过更艰苦的试炼——猎杀野猪并收集蝎尾——以此来证明自己，直到他完全获得这位修行者的认可。",al={"林纳格活下来了吗","林纳格的后续"}},{q="林纳格在哪里？",a="他位于杜隆塔尔西北部崎岖的峭壁上，靠近通往西方贫瘠之地的边境关口附近。",al={"林纳格位置","林纳格在哪里"}},{q="为什么这剂解药这么紧急？",a="尾蝎的毒素极其猛烈，受害者若不及时治疗，不到一小时内毒素就会蔓延至重要器官，导致死亡。",al={"为什么会有时间限制","林纳格中毒倒计时"}}},fp="15,216,17.245.0,22.222.0,14.216.0,39.264.0,67.197.0,48.222.1,26.121.0,47.128.0"}
P.entries["quest:813"] = {n="寻找解毒剂",s="“寻找解药”是一项为了在奥格瑞玛的考格汉而进行的紧急任务，目的是为中毒的猎人林纳格酿制解药。由于必须在毒液致命前完成，冒险者必须在城墙外从蝎尾毒虫身上收集蝎尾毒囊。这突显了杜隆塔尔野生动物的残酷本性以及野外生存准备的必要性。",h="“寻找解药”是一项为了在奥格瑞玛的考格汉而进行的紧急任务，目的是为中毒的猎人林纳格酿制解药。由于必须在毒液致命前完成，冒险者必须在城墙外从蝎尾毒虫身上收集蝎尾毒囊。这突显了杜隆塔尔野生动物的残酷本性以及野外生存准备的必要...",kw={"解药","杜隆塔尔","考格汉","奥格瑞玛","毒液","林纳格","蝎尾毒虫"},ang={["class:Hunter"]="考格汉对所有猎人提出了严厉的提醒：了解野兽的毒液并携带适当的药物与你的弓箭和追踪技能一样至关重要。",["faction:Horde"]="杜隆塔尔的部落照顾着自己的人民，确保边境上孤立的游侠和侦察兵可以依靠奥格瑞玛的堡垒获得援助。",["race:Orc"]="在杜隆塔尔的生存考验着新定居的兽人的耐力，这表明即使是经验丰富的侦察兵，如果粗心大意，也可能倒在当地的危险之下。"},sec={{t="与毒液赛跑",b="在杜隆塔尔各地狩猎时，一名名叫林纳格的暗矛巨魔犯了一个危险的错误：在没有携带解药的情况下与当地的蝎尾毒虫交战。他被蜇伤并迅速屈服于它们强效的毒素之下，被迫求援。这项任务落在了居住在奥格瑞玛的经验丰富的猎人考格汉身上，他必须在毒素发作前调配出修复药剂。"},{t="制作解药",b="制作解药需要采集痛苦的源头：潜伏在奥格瑞玛大门外的成熟蝎尾毒虫的毒囊。考格汉指出，现在不是责备林纳格缺乏准备的时候，因为每一刻都至关重要。一旦迅速取回毒囊并带回城里，考格汉就会合成药剂，以便能立刻送往垂死的猎人手中。"}},faq={{q="林纳格是谁？",a="林纳格是杜隆塔尔的一名暗矛巨魔猎人，他在追踪野兽时被当地的蝎尾毒虫严重蜇伤。由于在野外缺乏解药，他丧失了行动能力，只能依靠信使从奥格瑞玛取回药物，以免死于中毒。",al={"林纳格背景故事","谁中毒了","谁需要解药"}},{q="考格汉是谁？",a="考格汉是一位经验丰富的暗矛巨魔猎人，常驻于奥格瑞玛的Cleft of Shadow。他深谙杜隆塔尔的野生动物，并拥有使用原始蝎尾毒虫毒囊酿制有效解毒剂所需的炼金知识。",al={"考格汉","考格汉是谁","考格汉 奥格瑞玛"}},{q="所需的毒囊来自哪里？",a="毒囊直接从在奥格瑞玛入口附近多岩石的干旱地面上游荡的蝎尾毒虫身上采集。",al={"蝎尾毒虫在哪里","毒囊位置","蝎尾毒虫毒囊"}},{q="为什么这个任务有时间限制？",a="紧迫性源于林纳格在野外恶化的健康状况。由于蝎尾毒虫的毒素极其猛烈且作用迅速，考格汉必须在猎人因全身中毒而死亡前收到原料并蒸馏出解药。",al={"为什么有计时","治愈的需求计时","限时任务"}},{q="考格汉在这次狩猎中强调了什么教训？",a="考格汉警告说，每一位猎人在与猎物交战前，都必须仔细研究它们的习性和致命危险。在没有做好充分准备或没有应对措施的情况下进入荒野，是一个很容易让战士付出生命代价的疏忽。",al={"考格汉的教训","狩猎教训","考格汉的建议"}},{q="这个任务如何与“治愈的需求”相衔接？",a="“治愈的需求”是引发紧急情况并启动计时的基础差事。“寻找解药”是中间步骤，玩家在此收集原始成分，供考格汉酿制成品药剂。",al={"治愈的需求关联","前置任务","它如何衔接"}}},fp="20,260,24.270.0,17.291.0,14.192.0,16.164.0,43.114.0,47.160.0,53.181.0,46.185.0"}
P.entries["quest:815"] = {n="恐龙蛋大餐",s="“打碎几个蛋”是一项跑腿任务，旨在协助一位忙得不可开交的厨师，他必须跟上无休止的餐点准备工作。搜集新鲜且易碎的食材而不将其弄碎，是维持厨房正常运转和烹饪进度按时进行的关键。",h="“打碎几个蛋”是一项跑腿任务，旨在协助一位忙得不可开交的厨师，他必须跟上无休止的餐点准备工作。搜集新鲜且易碎的食材而不将其弄碎，是维持厨房正常运转和烹饪进度按时进行的关键。",kw={"打碎几个蛋","早餐","厨师","烹饪","蛋","厨房","餐点"},ang={["profession:Cooking"]="每一位在职的厨师都知道让人们吃饱饭所带来的巨大压力。在任何厨房里，搜集易碎食材而不把它们打碎，这本身就是挑战的一半。"},sec={{t="无休止的餐点",b="供养一群人是一项精疲力竭、永无止境的工作。在早餐、午餐和晚餐之间，几乎没有时间离开炉灶，更不用说离开厨房去寻找原材料了。在“打碎几个蛋”中，一位焦头烂额的厨师求助于路过的冒险者，请他们赶在下一顿餐点服务延误之前找来新鲜的蛋。"},{t="厨师的感激",b="运输蛋需要一种蛮力无法替代的轻柔触碰。厨师可能会出言不逊，很少给予夸奖，但完好无损的食材本身就是最好的证明。一旦蛋被安全地送达且没有碎裂，厨师就会立刻打发采集者离开，直接回到火炉前继续工作。"}},faq={{q="“打碎几个蛋”是什么任务？",a="“打碎几个蛋”是一项烹饪任务，冒险者在此协助一位忙碌的厨师，他被准备餐点的持续需求压得喘不过气来。这项任务包括将蛋完好无损地送到，以确保烹饪进度不会滞后。",al={"打碎几个蛋任务","什么是打碎几个蛋","蛋任务"}},{q="“打碎几个蛋”里的厨师是谁？",a="这位厨师是杜隆塔尔剃刀岭的厨师托尔卡，他全天候都在准备餐点。虽然态度生硬且匆忙，但托尔卡依靠能干的帮手从回音群岛取回断尾龙虾的蛋，并确保在开饭前不把它们弄碎。",al={"谁发布打碎几个蛋","蛋任务厨师","谁在做饭"}},{q="厨师为什么需要蛋？",a="厨师需要它们进行持续的餐点准备，无论是早餐、午餐还是晚餐。供养人们是一项无休止的琐事，而新鲜的蛋是炉灶上迫切需要的厨房必需品。",al={"为什么需要蛋","蛋有什么用"}},{q="为什么厨师会评论说不要笨手笨脚？",a="蛋很脆弱，在运输过程中很容易损坏。厨师明确表示看重那些不笨手笨脚的人，因为蛋壳碎裂和蛋黄流失会毁掉餐点服务所需的食材。",al={"为什么拿蛋要小心","不要打破蛋","为什么不要笨手笨脚"}},{q="任务标题“打碎几个蛋”是指什么？",a="这个名字引用了一句常见的谚语：不打碎几个蛋就做不成煎蛋卷。这非常符合这项为繁忙的餐点服务收集易碎厨房食材的任务。",al={"打碎几个蛋含义","短语含义","为什么叫打碎几个蛋"}},{q="为什么厨师这么不耐烦？",a="厨师忙于应付早餐、午餐和晚餐的连轴转，根本没有时间停歇。还有这么多烹饪工作要做，厨师对闲聊毫无耐心，只想赶快回到炉灶前。",al={"厨师态度","为什么厨师很粗鲁","脾气暴躁的厨师"}}},fp="16,216,13.344.0,18.311.0,35.225.0,36.235.0,28.203.0,46.178.0,46.187.0,29.219.0"}
P.entries["quest:816"] = {n="丢失的孩子",s="“失踪但未被遗忘”是一个由米莎·托克伦发布的忧伤任务，她的家园位于剃刀岭西北方。为了寻求一个了结，她恳求旅者在危机四伏的怒水河岸搜寻她那倔强的儿子Kron的下落。",h="“失踪但未被遗忘”是一个由米莎·托克伦发布的忧伤任务，她的家园位于剃刀岭西北方。为了寻求一个了结，她恳求旅者在危机四伏的怒水河岸搜寻她那倔强的儿子Kron的下落。",kw={"护身符","鳄鱼","dreadmaw","kron","米沙","剃刀岭","怒水河","托克伦"},ang={["class:Hunter"]="对于猎人来说，Kron是一个警示故事，讲述了一名未能评估猎物凶猛程度的追踪者最终成为了它们的盘中餐。",["faction:Horde"]="杜隆塔尔早期的生活艰苦而严酷，平凡的家庭必须在无情的荒野和在其边界徘徊的致命掠食者之间挣扎求生。",["race:Orc"]="Kron的命运是一个悲剧性的提醒：虽然自尊和尚武荣耀是兽人文化的核心，但缺乏对危险野兽的敬畏的鲁莽傲慢只会导致毫无英雄气概的死亡。"},sec={{t="母亲的恐惧",b="在剃刀岭西北方，隐匿于杜隆塔尔干旱的红色荒原之中，坐落着简朴的托克伦农场。米莎·托克伦住在这里，这是一位被悲伤和焦虑所麻痹的兽人母亲。几天前，她的儿子Kron声称他要前往西边靠近贫瘠之地边界的怒水河，去猎杀河中凶猛的鳄鱼。尽管她警告过那些致命的野兽，但Kron倔强的自尊心驱使他冲了出去，想要证明自己的勇气。从那以后，他就再也没有出现过。"},{t="残酷的确认",b="米莎请求路过的探险者仔细搜寻怒水河岸，寻找任何关于Kron命运的线索，甚至建议他们去搜查那些鳄鱼的肚子。悲剧的是，她最坏的预感成真了。在水边屠宰凶恶的Dreadmaw鳄鱼时，可以发现Kron被吞下的护身符。将这件遗物带回给米莎虽然熄灭了她儿子幸存的最后希望，但终于让这位悲痛的母亲得到了她开始哀悼所需的结果。"}},faq={{q="谁是米莎·托克伦？",a="米莎·托克伦是一位兽人农场母亲，居住在杜隆塔尔剃刀岭西北方的一处偏僻家园。她饱受悲伤和忧虑的折磨，请求流浪者们搜寻她失踪的儿子Kron的下落。",al={"米莎·托克伦","谁发布失踪但未被遗忘任务","kron的母亲"}},{q="Kron是谁？",a="Kron是米莎·托克伦那倔强的儿子。为了证明自己的力量，他无视了母亲的警告，离开家去怒水河附近猎杀危险的鳄鱼，并在那里遭遇了不测。",al={"谁是kron","kron发生了什么","米莎的儿子"}},{q="Kron是在哪里失踪的？",a="Kron向西穿过杜隆塔尔，前往贫瘠之地的边界，在怒水河岸进行狩猎时失踪的。",al={"kron在哪里","去哪里寻找kron","kron的位置"}},{q="你如何向米莎证明Kron的命运？",a="你在徘徊于怒水河水域的Dreadmaw鳄鱼遗骸中找到了Kron被吞下的护身符。将这件找回的传家宝带回给米莎就确认了他的死亡。",al={"kron的护身符","kron命运的线索","鳄鱼的肚子"}},{q="米莎会给予什么奖励？",a="米莎把她原本准备给Kron庆祝狩猎凯旋的礼物送给了你。在得知他的死讯后，她无法忍受再看这件东西，于是把它转交给了带给她结果的探险者。",al={"失踪但未被遗忘奖励","米莎的礼物"}},{q="Kron当初为什么要离开？",a="Kron的离去源于他倔强的自尊心和想要证明自己狩猎本领的渴望。当他的母亲警告他这些鳄鱼太过凶恶危险时，他大发雷霆，执意冲出去进行狩猎。",al={"kron为什么要打猎","kron的自尊"}}},fp="22,148,16.317.0,19.323.1,22.177.0,13.150.1,26.104.0,38.141.1,28.201.1,38.172.0"}
P.entries["quest:817"] = {n="生活所需的虎皮",s="“实用的猎物”是由森金村的制皮师维尔林·长牙发布的一项狩猎任务。面对不断增长的人口和日渐枯竭的库存，暗矛巨魔必须从邻近的回音群岛采集耐用的虎皮，以制作必要的住所、衣物和装备。",h="“实用的猎物”是由森金村的制皮师维尔林·长牙发布的一项狩猎任务。面对不断增长的人口和日渐枯竭的库存，暗矛巨魔必须从邻近的回音群岛采集耐用的虎皮，以制作必要的住所、衣物和装备。",kw={"暗矛","杜隆塔尔猛虎","回音群岛","狩猎","制皮","实用的猎物","森金村","虎皮","维尔林·长牙"},ang={["class:Hunter"]="维尔林讲述的关于在出击前坚持静默追踪一整天的故事，正是暗矛巨魔教导所有年轻猎手耐心与精准这些核心美德的直接体现。",["faction:Horde"]="支持这处暗矛巨魔的新生飞地，并提供必要的贸易物资，有助于稳固部落在无尽之海沿岸的南方侧翼。",["race:Troll"]="对于流亡的暗矛巨魔来说，前往回音群岛狩猎是一种苦涩的提醒，让他们想起失去的家园，在那里，为了供养族人，他们必须踏上被扎拉赞窃取的土地。"},sec={{t="生存之道",b="杜隆塔尔干旱海岸上的生活十分艰苦，流亡到森金村的暗矛巨魔必须充分利用每一份资源。虎皮是现有的用途最广泛的材料之一，是缝制帐篷、厚毯子和加固护甲的必需品。随着定居点里难民和归来斥候人数的增加，储备物资已经捉襟见肘，迫使像维尔林·长牙这样的工匠不得不委托进行新的狩猎。"},{t="平衡与狩猎",b="暗矛巨魔与他们领地内的掠食者保持着一种审慎的关系。巨魔通常不会过度狩猎杜隆塔尔本土的猛虎，而是任由这些徘徊者自由繁衍，只在部落物资需要补充时才会进行捕杀。冒险渡水前往回音群岛去跟踪这些掠食者，既是出于实际需要，也是对耐心、纪律和野外生存技巧的一种传统考验。"}},faq={{q="谁是维尔林·长牙？",a="维尔林·长牙是一位在森金村工作的暗矛巨魔工匠，专门处理兽皮和皮革。他负责引导猎手采集必要的毛皮，以保障部落的衣物、住所和装备供应。",al={"维尔林·长牙","谁发布了实用的猎物"}},{q="为什么森金村需要虎皮？",a="森金村不断增长的人口已经让现有的储备不堪重负。虎皮可以提供耐用的材料，制作保暖的毯子、结实的帐篷以及皮革护甲，以保护村民免受恶劣环境的侵袭。",al={"为什么需要虎皮","实用的猎物目标","毛皮的用途"}},{q="杜隆塔尔的猛虎在哪里可以找到？",a="这些猛虎在回音群岛的荒野中徘徊，该群岛位于杜隆塔尔东南部海岸外。",al={"老虎在哪里","老虎位置","回音群岛的老虎"}},{q="为什么巨魔不捕杀附近所有的老虎？",a="维尔林解释说，暗矛巨魔特意在自身需求与当地生态之间保持平衡。他们让掠食者繁衍壮大以保持种群的可持续性，只在村庄的物资需求超过储备时才会介入进行捕杀。",al={"为什么要让老虎繁衍","捕杀"}},{q="狩猎老虎对暗矛巨魔的文化重要吗？",a="是的。跟踪老虎被视为一种考验耐心和狡黠的仪式。维尔林曾深情地讲述过他在回音群岛的枝叶间一动不动地等待了近一天时间，才最终完成了他第一次重大狩猎胜利的故事。",al={"狩虎传统","第一次狩虎"}},{q="如果回音群岛被扎拉赞控制，为什么猎手们必须前往那里？",a="虽然叛变的巫医扎拉赞和他被施了巫术的爪牙占据了群岛的大部分地区，但岛上的野生猛兽依然繁多。在群岛外围海岸进行搜寻和狩猎，对暗矛巨魔来说依然是一项必要的冒险。",al={"回音群岛的老虎","为什么去回音群岛"}}},fp="14,167,20.291.0,20.262.0,20.142.0,41.122.0,35.81.0,48.155.0,51.171.0,65.182.0"}
P.entries["quest:818"] = {n="沃纳尔大师",s="森金村的沃纳尔大师通过索要试剂来测试初出茅庐的冒险者，以弥补他日益衰退的视力。他会派遣未来的学生前往杜隆塔尔沿岸收集龙虾人的眼睛和甲壳虫的粘液。虽然他对收徒弟的想法嗤之以鼻，但这项任务实际上是对耐心和决心的刻意考验。",h="森金村的沃纳尔大师通过索要试剂来测试初出茅庐的冒险者，以弥补他日益衰退的视力。他会派遣未来的学生前往杜隆塔尔沿岸收集龙虾人的眼睛和甲壳虫的粘液。虽然他对收徒弟的想法嗤之以鼻，但这项任务实际上是对耐心和决心的刻意考验。",kw={"炼金术","甲壳虫粘液","暗矛海滩","杜隆塔尔","完好的龙虾人眼睛","龙虾人","沃纳尔大师","森金村"},ang={["faction:Horde"]="杜隆塔尔海岸对初出茅庐的部落来说依然危机四伏；清理具有攻击性的龙虾人和冲浪甲壳虫可以保障森金村周围渔场的安全。",["race:Orc"]="沃纳尔公开怀疑兽人是否具备炼金术所需的安静纪律，这使得这项任务成为了证明部落团结可以延伸至学术耐心的机会。",["race:Troll"]="对于在森金村重建的暗矛部族来说，向沃纳尔大师这样的长者证明自己，对于传承部落的神秘和炼金传统至关重要。"},sec={{t="大师衰退的视力",b="沃纳尔大师坐在森金村里，背负着岁月的沉重和日益模糊的视力。曾经信手拈来的原始魔法，如今他不得不更多地依赖炼金术来强化感知并编织法术。尽管身体状况每况愈下，这位固执的巨魔却拒绝收徒，声称暗矛部族和杜隆塔尔的兽人中还没出现过有资格接受他教导的人。"},{t="考验未受证明者",b="沃纳尔并不进行直接的教导，而是要求从严酷的海岸线获取原材料：完好的龙虾人眼睛和甲壳虫粘液瓶。从披甲且善于夹击的龙虾人身上获取未受损的眼睛需要精准的打击，而收集足够的粘液则是对冒险者是否愿意忍受枯燥杂务的考验。在沃纳尔看来，狩猎这些沿海野兽与其说是为了试剂，不如说是为了剔除那些缺乏专注力的人。"},{t="意志的衡量",b="对于沃纳尔大师来说，时间和耐心是衡量强度的终极标准。他预料鲁莽的年轻人会因挫折而放弃，或者彻底抛弃这项苦差事。带着纯净的原料回到森金村，不仅证明了在回音群岛海峡危险礁石区的生存技能，也证明了掌握炼金术微妙艺术所必需的纪律。"}},faq={{q="沃纳尔大师是谁？",a="沃纳尔大师是一位居住在森金村的老年巨魔炼金术士和施法者。随着年龄的增长，他的视力正在衰退，这迫使他不得不转而依靠炼金溶剂和药剂来施展曾经轻而易举的魔法。",al={"沃纳尔大师","沃纳尔是谁","沃纳尔背景故事"}},{q="为什么沃纳尔需要龙虾人的眼睛和甲壳虫粘液？",a="沃纳尔依靠炼金合剂来辅助他的魔法，并弥补他衰退的视力。粘液和完好的龙虾人眼睛既是他的药剂试剂，也充当了对他未来学徒的入门测试。",al={"为什么需要甲壳虫粘液","为什么需要龙虾人眼睛","沃纳尔制造什么"}},{q="为什么沃纳尔如此不愿收徒？",a="沃纳尔有着极高的标准，对傲慢毫无容忍度。他认为没有哪个巨魔或兽人展现出了向他学习所需的真正奉献精神和耐心，他眼中的大多数求学者都过于自负且容易气馁。",al={"沃纳尔学徒","为什么不收学徒","沃纳尔在找学生吗"}},{q="这些生物在森金村附近哪里可以找到？",a="甲壳虫和龙虾人在暗矛海滩沿岸的浅滩游荡，并栖息在离岸将大陆与回音群岛隔开的水道中。",al={"龙虾人在哪里","甲壳虫在哪里","暗矛海滩野兽"}},{q="为什么龙虾人的眼睛需要完好无损？",a="用于强化感知的炼金药剂需要未受损的感觉器官。战斗中的蛮力打击有压碎龙虾人脆弱眼睛的风险，因此需要狩猎者具备精准度和克制力。",al={"完好的眼睛","完好的龙虾人眼睛","为什么需要完好的眼睛"}},{q="沃纳尔试图传授什么课程？",a="沃纳尔认为耐心是品格的真正试金石。通过布置在岸边重复且肮脏的采集任务，他旨在观察新手是会屈服于软弱和急躁，还是能保持炼金术士那种冷静的专注。",al={"沃纳尔的教导","任务的意义","耐心测试"}}},fp="16,233,23.358.0,20.369.0,17.306.0,21.196.0,52.192.0,50.212.0,55.127.0,42.180.0,38.172.0"}
P.entries["quest:819"] = {n="老陈的空酒桶",s="在贫瘠之地的荒野中，遗落着一只刻有陈·风暴烈酒名字的空酒桶。找到它将开启一段旅程，追溯这位著名的游历酿酒师往日的功绩，他曾为杜隆塔尔的建立贡献了自己的战斗技艺。",h="在贫瘠之地的荒野中，遗落着一只刻有陈·风暴烈酒名字的空酒桶。找到它将开启一段旅程，追溯这位著名的游历酿酒师往日的功绩，他曾为杜隆塔尔的建立贡献了自己的战斗技艺。",kw={"贫瘠之地","酿酒","酿酒师德罗恩","陈·风暴烈酒","空酒桶","熊猫人","棘齿城","雷克萨"},ang={["faction:Horde"]="陈·风暴烈酒被铭记为一位受人尊敬的盟友，他曾与雷克萨和洛克汗并肩作战，建立杜隆塔尔，并在部落最初的日子里保卫了它。",["profession:Cooking"]="这只酒桶代表了一位技艺精湛的酿酒师的传承，他那传奇般的品味和对稀有原料的追求激励了整个卡利姆多的工匠。"},sec={{t="一件游历者的遗物",b="在贫瘠之地那片干旱广袤的土地上，旅人们偶尔会发现一只被遗弃的木桶。不同于剃刀鬃毛野猪人或科卡尔半人马留下的常见货色，这只木桶制作精良，上面还刻有一块独特的铭牌：“陈·风暴烈酒——愿你的灵魂得到升华，也愿你永远兴致高昂。”在卡利姆多的烈日炙烤下，这真是一件不同寻常的遗物，促使任何好奇心旺盛的人去寻找一位精通酿酒之道的人，以了解它为何会出现在这里。"},{t="杜隆塔尔奠基的回响",b="将这只木桶带给棘齿城的酿酒师德罗恩，就能揭开它的起源。德罗恩一眼就认出了这精湛的工艺：它属于陈·风暴烈酒，那位在萨尔的部落确保杜隆塔尔安全的关键战役中与雷克萨并肩作战的传奇熊猫人游历者。尽管陈行走在卡利姆多红土地上的日子已过去多年，但他那传奇的酿酒配方和游历精神在艾泽拉斯的资深酿酒师心中依然记忆犹新。"}},faq={{q="什么是陈的空酒桶？",a="它是在贫瘠之地发现的一只废弃酿酒桶。上面刻有题词，将其献给游历的熊猫人酿酒师，陈·风暴烈酒。",al={"空酒桶","陈的酒桶","这个木桶是什么"}},{q="陈·风暴烈酒是谁？",a="陈·风暴烈酒是一位行踪不定的熊猫人酿酒师，他曾广泛游历卡利姆多。他最出名的事迹是在杜隆塔尔的防御和早期建设过程中协助半食人魔兽王雷克萨。",al={"谁是陈","陈的背景故事","熊猫人酿酒师"}},{q="我应该把这只酒桶交给谁？",a="这只酒桶可以交给酿酒师德罗恩，他是一位驻扎在棘齿城附近路边的兽人酿酒师，认得陈的标记，也知道如何重现他的配方。",al={"酒桶交给谁","谁想要陈的酒桶","酒桶交付"}},{q="为什么陈的酒桶会丢在贫瘠之地？",a="多年前，陈曾游历卡利姆多，为他的佳酿寻找奇异的原料，特别是在他帮助新兴的部落保卫新家园、抵御普罗德摩尔上将的军队时。",al={"为什么酒桶在贫瘠之地","酒桶是怎么到这里的"}},{q="陈·风暴烈酒会亲自出现吗？",a="不。陈已经离开了该地区，很久没有在卡利姆多露面了。留下的只有他旧时的木桶、配方，以及像德罗恩和雷克萨这样的盟友对他的美好回忆。",al={"我能找到陈吗","陈·风暴烈酒在哪里","陈在经典旧世里吗"}},{q="酿酒师德罗恩会用这只酒桶做什么？",a="德罗恩看到这件遗物非常兴奋，并借此机会向冒险的游历者发起挑战，收集当地野兽的原料，以便他能重现陈那烈性十足的传奇佳酿。",al={"德罗恩任务线","酒桶后续"}}},fp="16,147,17.395.0,28.345.0,25.129.0,23.172.0,29.153.0,43.172.0,38.167.0,43.163.0"}
P.entries["quest:82"] = {n="腐化之巢",s="高级勘探员菲兹杜瑟想要弄清楚敌人到底是什么。虫子们一直在抽干腐化之巢所在的水池，关于它们的资料少之又少。你被要求从腐化之巢的蜈蚣身上收集五份虫壳，并将它们交给加基森的炼金师匹斯特苏格。",h="高级勘探员菲兹杜瑟想要弄清楚敌人到底是什么。虫子们一直在抽干腐化之巢所在的水池，关于它们的资料少之又少。你被要求从腐化之巢的蜈蚣身上收集五份虫壳，并将它们交给加基森的炼金师匹斯特苏格。",kw={"蜈蚣","菲兹杜瑟","加基森","昆虫","腐化之巢","匹斯特苏格","塔纳利斯"},sec={{t="来自巢穴的碎片",b="在完成加基森水质调查之后，高级勘探员菲兹杜瑟开始关注关于那些虫子的报告。目前已知的信息很少，只知道它们正在抽干曾经位于腐化之巢所在地的水池。菲兹杜瑟想先搞清楚敌人是谁，所以他请求你进入巢穴，从那里的蜈蚣身上收集五份样本，并将它们带回加基森交给炼金师匹斯特苏格进行检验。"},{t="匹斯特苏格的发现",b="匹斯特苏格立刻开始研究这些样本，并断言它们与之前见过的任何昆虫形态都不匹配，看起来就像是有某种外部力量在控制着这些虫子。随后，匹斯特苏格让你回去找菲兹杜瑟，因为有一个紧急情况需要你的帮助，这可能涉及塔纳利斯更多的虫子。"}},faq={{q="为什么高级勘探员菲兹杜瑟需要虫子样本？",a="虫子们正在抽干腐化之巢曾经所在的水池，人们对它们知之甚少。收集蜈蚣的碎片是为了帮助匹斯特苏格研究它们到底是什么。",al={"为什么收集虫子碎片","菲兹杜瑟 昆虫样本","腐化之巢的目的"}},{q="蜈蚣在哪里可以找到？",a="蜈蚣位于腐化之巢，也就是曾经的水池所在地。",al={"腐化之巢在哪里","蜈蚣位置","哪里能找到蜈蚣"}},{q="在加基森是谁负责接收这些虫子样本？",a="加基森的炼金师匹斯特苏格，他将对样本进行检验。",al={"向谁交付任务","匹斯特苏格位置","谁需要虫子样本"}},{q="这一步之前是什么？",a="它是加基森水质调查的后续任务。",al={"前置任务","任务前提","引导任务"}}},fp="26,308,19.413.0,21.291.1,56.189.0,30.68.0,43.58.0,28.38.0"}
P.entries["quest:821"] = {n="老陈的空酒桶",s="这个任务延续了贫瘠之地中熊猫人酿酒的传奇血统。棘齿城的酿酒师德罗恩提出，只要你从游荡在草原上的野生野兽身上收集野外原料，他就愿意为你重现Chen Stormstout那久负盛名的烈性佳酿。",h="这个任务延续了贫瘠之地中熊猫人酿酒的传奇血统。棘齿城的酿酒师德罗恩提出，只要你从游荡在草原上的野生野兽身上收集野外原料，他就愿意为你重现Chen Stormstout那久负盛名的烈性佳酿。",kw={"酿酒师德罗恩","chen stormstout","酒桶","平原陆行鸟的肾脏","棘齿城","草原狮的獠牙","贫瘠之地","雷霆蜥蜴的角","穴居人啤酒"},ang={["faction:Horde"]="Chen Stormstout曾与雷克萨并肩作战，帮助建立了杜隆塔尔，这使得他旅途中的任何遗留物都对部落有着特殊的文化共鸣。",["profession:Cooking"]="烹饪冒险家们会欣赏边境屠宰与精湛酿造之间那种大胆——尽管有些令人不安——的结合，正是这种结合打造出了传奇的卡利姆多烈酒。",["race:Orc"]="德罗恩体现了兽人是如何拥抱那些直接从曾与早期部落一同在这片土地上行走的旅行者那里传下来的古老酿酒师传统的。"},sec={{t="桶中的传奇",b="当一个刻有熊猫人文字的废弃酒桶最终落入棘齿城的酿酒师德罗恩手中时，这唤起了他对那位传奇流浪者Chen Stormstout的美好回忆。Chen将他同名佳酿的秘诀传授给了德罗恩的导师，而导师又将其托付给了德罗恩。虽然对非酿酒师来说这很罕见，但这份配方需要直接取自贫瘠之地凶猛野生动物身上的原始且强劲的材料。"},{t="收获草原",b="酿造Chen的烈性酒需要一系列不同寻常的成分：平原陆行鸟的肾脏、草原狮的獠牙，以及雷霆蜥蜴的角。寻找这些物品需要在尘土飞扬的平原上狩猎，这证明了只有最强韧的野兽才能提供真正熊猫人风格酿造所需的劲道。一旦收集齐，德罗恩便会充满怀旧之情，感叹重现这个古老的配方让他胃里感到的温暖，几乎不亚于他过去酿造的穴居人啤酒。"}},faq={{q="酿酒师德罗恩是谁？",a="酿酒师德罗恩是驻扎在棘齿城港口的一名兽人酿酒师。他从一位曾亲自从传奇流浪者Chen Stormstout那里获得配方的导师身上学到了酿酒艺术。",al={"酿酒师德罗恩","谁是德罗恩","棘齿城的德罗恩"}},{q="为什么啤酒配方需要动物肾脏和角？",a="熊猫人的酿酒传统——以及粗犷的边境酿酒师所做的调整——往往依赖于当地野生动物身上强大而神秘的成分，以便为他们的烈酒注入活力、劲道和独特的自然精华。",al={"为什么需要动物部位","平原陆行鸟肾脏啤酒","狮牙啤酒"}},{q="可以在哪里找到所需的原料？",a="这三种成分都采自贫瘠之地的本土动物。平原陆行鸟和草原狮在开阔的草原上游荡，而雷霆蜥蜴通常可以在平原上更干旱或多岩石的区域找到。",al={"在哪里可以找到獠牙","雷霆蜥蜴在哪里","寻找酿酒原料"}},{q="Chen Stormstout是谁？",a="Chen Stormstout是一位流浪的熊猫人酿酒师，他在杜隆塔尔建国期间游历了卡利姆多，在寻找珍稀原料来完善他那烈性啤酒的同时，也为部落提供了帮助。",al={"谁是chen","chen stormstout的背景故事","chen"}},{q="把原料带给德罗恩后会发生什么？",a="交出狮牙、平原陆行鸟肾脏和雷霆蜥蜴的角会让德罗恩感到高兴，这提醒了他早期的酿酒岁月，并直接进入了重现那传奇烈酒的最后阶段。",al={"陈的空酒桶之后的下一个任务","德罗恩的奖励","接下来是什么"}},{q="德罗恩提到的穴居人啤酒是什么？",a="看到这些野生原料，德罗恩深情地回忆起了一种早期的混合酒，即穴居人啤酒，这证明了他过去在边境发酵那些口感浓烈、不同寻常的混合酒的古怪历史。",al={"穴居人啤酒","德罗恩的穴居人啤酒"}}},fp="16,114,17.315.0,23.363.1,24.167.0,56.181.0,44.126.0,24.198.0,53.205.0,38.169.0"}
P.entries["quest:822"] = {n="老陈的空酒桶",s="在成功酿造出强力的风暴烈酒之后，位于棘齿城的酿酒师德罗恩提出可以制作另一种从神秘的熊猫人流浪者陈·风暴烈酒那里学到的秘方。这种名为“穴居人麦酒”的烈性混合饮料，需要从贫瘠之地的本土野兽身上获取稀有的器官和腺体。",h="在成功酿造出强力的风暴烈酒之后，位于棘齿城的酿酒师德罗恩提出可以制作另一种从神秘的熊猫人流浪者陈·风暴烈酒那里学到的秘方。这种名为“穴居人麦酒”的烈性混合饮料，需要从贫瘠之地的本土野兽身上获取稀有的器官和腺体。",kw={"贫瘠之地","酿酒师德罗恩","陈·风暴烈酒","陈的空酒桶","科多兽的肝脏","棘齿城","风暴兽","雷鹰","穴居人麦酒"},ang={["faction:Horde"]="陈·风暴烈酒曾在杜隆塔尔保卫战期间与部落并肩作战，给德罗恩等在早期遇到他的兽人们留下了深刻的印象。",["profession:Cooking"]="烹饪纯粹主义者或许会排斥穴居人麦酒，但提取丰富的脏器肉和强力腺体，体现了边境烹饪传统中“猎物绝不浪费”的精髓。",["race:Orc"]="酿酒师德罗恩代表了兽人中少见的职业，他摒弃了传统的战士之路，拥抱了陈的异域酿酒法，并在棘齿城经营着自己的生意。"},sec={{t="第二个熊猫人配方",b="在帮助酿酒师德罗恩复刻了传奇人物陈·风暴烈酒的最初配方后，这位兽人酿酒师透露，那位流浪的熊猫人分享的秘密远不止一个。德罗恩掌握着一种名为“穴居人麦酒”的奇特饮料的配方。与用谷物蒸馏而成的普通烈酒不同，这种奇怪的麦酒完全依赖于从卡利姆多中部最凶猛的野生动物身上搜集而来的强力有机试剂。"},{t="穴居人麦酒的配料",b="为了酿造这种味道浓烈、令人振奋的饮料，德罗恩需要一些雷霆般的成分：风暴兽的闪电腺、巨型雷鹰的雷鹰的唾液腺，以及平原上游荡的科多兽的肝脏。蒸馏后，这种混合物便成为了一种专为在荒野生存而设计的强力刺激饮品。"},{t="持久的合作",b="德罗恩的技艺并不仅限于酿造一批。他意识到穿梭于棘齿城这一中立港口的旅行冒险者和雇佣兵对此有需求，因此他愿意保持长期合作，只要有探险者带来新鲜的兽类器官，他就愿意酿造新的穴居人麦酒。"}},faq={{q="陈·风暴烈酒是谁？",a="陈·风暴烈酒是一位神秘的流浪熊猫人酿酒师，他在杜隆塔尔建立期间游历了卡利姆多。在旅途中，他在棘齿城向德罗恩分享了一些强力的酿酒技术，随后继续了他的流浪之旅。",al={"陈是谁","陈的背景故事","熊猫人陈"}},{q="酿酒师德罗恩在哪里？",a="酿酒师德罗恩居住在棘齿城的中立港口城镇，该城镇位于贫瘠之地的东海岸。他终日沉浸在钻研与陈相遇时学到的奇特酿酒技艺中。",al={"德罗恩位置","酿酒师德罗恩在哪里","德罗恩npc"}},{q="什么是穴居人麦酒？",a="穴居人麦酒是陈教给德罗恩的一种非传统且强力的混合饮料。它不使用标准的酿酒啤酒花，而是加入了兽类腺体和内脏，这使其具有一种备受硬派冒险者青睐的劲头。",al={"穴居人麦酒","这是什么饮料","德罗恩酿什么"}},{q="去哪里收集闪电腺？",a="闪电腺可以从潜伏在贫瘠之地干旱荒原上的风暴兽身上获取，它们的体内蕴含着天然的电荷。",al={"闪电腺来源","风暴兽位置","去哪里获得闪电腺"}},{q="哪些野兽会掉落雷鹰的唾液腺？",a="这些腺体专门从巨型雷鹰身上采集。巨型雷鹰是掠食性鸟类，体型雄伟，能够施放电击，狩猎于贫瘠之地广阔的天空之上。",al={"雷鹰的唾液腺","巨型雷鹰在哪里","雷鹰位置"}},{q="我可以多次酿造穴居人麦酒吗？",a="可以。只要冒险者为他提供新鲜的腺体和科多兽的肝脏，酿酒师德罗恩就愿意随时调制更多的麦酒。",al={"可以重复吗","我可以再做一次吗","重复穴居人麦酒"}}},fp="16,150,25.277.0,28.265.0,23.182.1,23.208.0,34.135.0,18.171.0,37.133.0,43.124.0,36.104.0"}
P.entries["quest:823"] = {n="向奥戈尼尔报告",s="“向奥戈尼尔报告”是部落早期的一项任务，由森金村的加德林大师派遣。它指引初出茅庐的冒险者向北前往剃刀岭，向奥戈尼尔·魂痕发出警告，告知其火刃氏族邪教那阴险的触角。这次派遣有助于协调杜隆塔尔各地分散的防御力量，对抗在兽人故乡酝酿的恶魔腐蚀。",h="“向奥戈尼尔报告”是部落早期的一项任务，由森金村的加德林大师派遣。它指引初出茅庐的冒险者向北前往剃刀岭，向奥戈尼尔·魂痕发出警告，告知其火刃氏族邪教那阴险的触角。这次派遣有助于协调杜隆塔尔各地分散的防御力量，对抗在兽人故...",kw={"火刃氏族","杜隆塔尔","加德林大师","奥戈尼尔·魂痕","剃刀岭","向奥戈尼尔报告","森金村"},ang={["faction:Horde"]="这项任务标志着新结盟的暗矛巨魔与杜隆塔尔的兽人在面对共同威胁时，进行了至关重要的沟通与合作。",["race:Orc"]="奥戈尼尔·魂痕代表了你新家园的前线防御，确保恶魔的污染不会在杜隆塔尔境内扎根。",["race:Troll"]="尽管暗矛部族正忙于与扎拉赞的战斗，加德林大师仍通过向兽人领导人通报区域性危险，展现了巨魔对部落的忠诚。"},sec={{t="协调防御",b="当森金村正忙于应对自身的当地困境——尤其是回音群岛上扎拉赞的背叛——时，加德林大师意识到有关火刃氏族邪教的报告代表着一种更为广泛的危险。在试炼谷发现了恶魔腐蚀的流言，这位暗矛巫医深知这些威胁不能孤立处理。他派遣远道而来的英雄沿着尘土飞扬的道路向北前往剃刀岭，那里的当地兽人官员负责对杜隆塔尔进行更广泛的监视。"},{t="奥戈尼尔·魂痕",b="奥戈尼尔·魂痕驻扎在剃刀岭的军事营地中，他是一位负责铲除内部邪恶并保卫中部腹地的兽人。当冒险者传达加德林大师的警告时，奥戈尼尔毫不迟疑地整合了来自试炼谷和森金村的报告。他意识到火刃氏族的阴影正危险地逼近，随即迅速动员部队，试图在邪教徒的黑暗仪式动摇这个年轻国家之前将他们瓦解。"}},faq={{q="谁发布了“向奥戈尼尔报告”这个任务？",a="加德林大师，即居住在森金村的暗矛巫医兼精神领袖，会在你协助巨魔解决了当地的初步困难后将此任务交给你。",al={"谁发布向奥戈尼尔报告","在哪里接向奥戈尼尔报告","向奥戈尼尔报告任务发布者"}},{q="奥戈尼尔·魂痕在哪里？",a="奥戈尼尔·魂痕位于剃刀岭，那是位于森金村以北、杜隆塔尔中部的一个防御定居点。",al={"奥戈尼尔·魂痕在哪里","奥戈尼尔·魂痕位置","寻找奥戈尼尔·魂痕"}},{q="为什么加德林大师要派你去剃刀岭？",a="加德林大师意识到在试炼谷及杜隆塔尔周边发现的恶魔邪教活动对所有人构成威胁，而不仅仅是针对巨魔。他指引你去找奥戈尼尔·魂痕，这位兽人负责在该地区执行针对火刃氏族的治安任务。",al={"为什么要向奥戈尼尔报告","为什么要前往剃刀岭","向奥戈尼尔报告的目的"}},{q="任务中提到的火刃氏族是什么？",a="火刃氏族是一个在杜隆塔尔及更广阔区域的阴影中活动的背叛性恶魔崇拜邪教。他们在附近峡谷和洞穴中的秘密存在威胁着新部落的安全与稳定。",al={"谁是火刃氏族","火刃氏族邪教","什么是火刃氏族"}},{q="“向奥戈尼尔报告”之后是什么任务？",a="当你向剃刀岭的奥戈尼尔·魂痕提交报告后，他会立即指派你执行“黑暗风暴”任务，以调查并对抗正在集结的邪教徒威胁。",al={"向奥戈尼尔报告后的下一个任务","向奥戈尼尔报告后续","向奥戈尼尔报告之后是什么"}},{q="在接受此任务之前必须完成什么前置条件？",a="它自然而然地衔接在你通过“向森金村报告”任务抵达森金村之后，将试炼谷早期的发现与更广泛的杜隆塔尔战役联系起来。",al={"向奥戈尼尔报告前置任务","如何解锁向奥戈尼尔报告","向奥戈尼尔报告的前置任务"}}},fp="16,177,21.394.0,15.401.0,37.151.0,33.103.0,46.230.0,49.196.0,36.166.0,64.157.0"}
P.entries["quest:824"] = {n="大地之环的耶努萨克雷",s="这个任务指引部落冒险者将从灰谷的元素生物身上找到的被污染的水球交给大地之环的耶努萨克雷。作为一名致力于元素和谐的萨满祭司，耶努萨克雷试图了解佐拉姆海岸和黑暗深渊内蔓延的腐蚀。研究这个圣物有望制止这种正在毒害该地区水域的非自然枯萎。",h="这个任务指引部落冒险者将从灰谷的元素生物身上找到的被污染的水球交给大地之环的耶努萨克雷。作为一名致力于元素和谐的萨满祭司，耶努萨克雷试图了解佐拉姆海岸和黑暗深渊内蔓延的腐蚀。研究这个圣物有望制止这种正在毒害该地区水域的非...",kw={"被污染的水球","黑暗深渊","大地之环","元素生物","耶努萨克雷","马斯托克·维尔西斯","佐拉姆海岸","佐拉姆加前哨站"},ang={["class:Shaman"]="这项任务直接涉及维护元素平衡的萨满职责。运送被污染的球体有助于大地之环的成员诊断一种危险的精神疾病。",["faction:Horde"]="随着部落在灰谷建立像佐拉姆加前哨站这样的防御营地，挖掘当地元素敌意背后的黑暗起源对于确保海岸线的安全至关重要。",["race:Troll"]="耶努萨克雷展现了暗矛部族深厚的精神智慧，代表大地之环运用他与灵魂的祖传羁绊。"},sec={{t="元素的信使",b="当奇怪且受到污染的元素生物开始在灰谷各处出现时，斥候们注意到了驱动它们的那股非自然力量。在残留物中躺着一颗被污染的水球，这是一个跳动着腐蚀魔法的完整容器。由于知道普通士兵和斥候缺乏诊断这种异常现象所需的精神洞察力，马斯托克·维尔西斯指引部落旅行者去寻找一位拥有深厚古代传说和元素知识的人：耶努萨克雷。"},{t="大地之环的注视",b="耶努萨克雷隶属于大地之环，这是一个致力于维护艾泽拉斯原始力量平衡的萨满教团。当部落军队在佐拉姆海岸沿线守卫边疆时，耶努萨克雷则专注于在附近的黑暗深渊神庙遗迹中溃烂的精神创伤。对他而言，一个从受污染的容器中汲取力量的元素生物不仅仅是一个孤立的威胁，更是一个令人警觉的预兆，表明未知的古老力量正在扭曲自然秩序。"}},faq={{q="耶努萨克雷是谁？",a="耶努萨克雷是一位代表卡利姆多北部大地之环的巨魔萨满祭司。他毕生致力于与元素沟通并进行研究，他驻扎在佐拉姆海岸附近，调查从黑暗深渊升起的黑暗骚乱。",al={"耶努萨克雷是谁","耶努萨克雷背景故事","耶努萨克雷在这里做什么"}},{q="什么是大地之环？",a="大地之环是一个致力于保持艾泽拉斯原始元素和谐的萨满组织。他们钻研古代传说、被遗忘的灵魂和旧日轶事，以修复元素混乱并治愈世界各地的精神腐蚀。",al={"什么是大地之环","大地之环是什么组织","大地之环背景故事"}},{q="在哪里可以找到耶努萨克雷？",a="耶努萨克雷位于灰谷佐拉姆海岸的佐拉姆加前哨站，他在那里研究从附近黑暗深渊升起的元素骚乱。",al={"耶努萨克雷在哪里","耶努萨克雷位置","寻找耶努萨克雷"}},{q="什么是被污染的水球？",a="这个球体是一个魔法导管，强大的水元素通过它引导自己的力量。发现一个被污染且完整的球体表明该地区的黑暗力量正在蓄意扭曲并奴役当地的灵魂。",al={"什么是被污染的水球","被污染的水球背景故事","水球"}},{q="是谁派你去和耶努萨克雷交谈的？",a="马斯托克·维尔西斯，一位驻扎在灰谷的部落军官，在意识到军队无法解读这种奇怪的魔法本质后，指引冒险者将这个被污染的圣物交给耶努萨克雷。",al={"谁开启了这个任务","马斯托克任务"}},{q="耶努萨克雷会怎么处理这个球体？",a="耶努萨克雷会保管这个容器，以便大地之环能够检查其枯萎的本质，希望研究结果能揭示一种净化水域并恢复该地区受困元素平静的方法。",al={"这个球体会怎么样","治愈腐蚀"}}},fp="26,352,28.452.0,28.401.0,22.235.0,25.235.0,34.173.0,33.217.0,35.170.0,35.189.0"}
P.entries["quest:8241"] = {n="炽热助熔剂的补给：铁锭",s="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而开始补充灼热峡谷中日益减少的炽热助熔剂供应。博恩奈特需要炽火龙鳞、铁锭和煤块，而且他有多少要多少。",h="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而开始补充灼热峡谷中日益减少的炽热助熔剂供应。博恩奈特需要炽火龙鳞、铁锭和煤块，而且他有多少要多少。",kw={"煤块","炽热助熔剂","炽火龙鳞","铁锭","大铁匠博恩奈特","通过铁补给恢复炽热助熔剂","灼热峡谷","瑟银兄弟会"},sec={{t="急需炽热助熔剂",b="大铁匠博恩奈特没时间闲聊。炽热助熔剂快用完了，博恩奈特需要炽火龙鳞、铁锭和煤块：两块龙鳞、四块铁锭以及煤块。他有多少要多少。"}},faq={{q="谁需要这些物资？",a="位于灼热峡谷的大铁匠博恩奈特，他会亲自接收这些物资。",al={"谁发布此任务","博恩奈特 炽热助熔剂","在哪里交任务"}},{q="博恩奈特需要什么材料？",a="两块炽火龙鳞、四块铁锭和一些煤块。",al={"我需要什么物品","炽热助熔剂的材料","博恩奈特上交物品"}},{q="这个任务的前置任务是什么？",a="名为“助熔剂怎么了？”的任务步骤，博恩奈特在这之前给你的任务。",al={"此任务的前置任务","炽热助熔剂的上一个任务","助熔剂怎么了的前置条件"}},{q="博恩奈特为什么需要这些物资？",a="博恩奈特说炽热助熔剂的供应正在减少，他想要补充库存。",al={"为什么要炽热助熔剂","博恩奈特的动机"}}},fp="38,213,17.222.0,25.78.0,35.54.0,30.69.0,36.78.0"}
P.entries["quest:8242"] = {n="炽热助熔剂的补给：重皮",s="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而致力于补充灼热峡谷内日渐减少的炽热助熔剂储备。博恩奈特需要焚火龙鳞、重皮和煤块，并且有多少收多少。",h="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而致力于补充灼热峡谷内日渐减少的炽热助熔剂储备。博恩奈特需要焚火龙鳞、重皮和煤块，并且有多少收多少。",kw={"大铁匠博恩奈特","煤块","炽热助熔剂","重皮","焚火龙鳞","灼热峡谷","瑟银兄弟会"},sec={{t="急需炽热助熔剂",b="大铁匠博恩奈特没时间闲聊。炽热助熔剂快用完了，博恩奈特需要焚火龙鳞、重皮和煤块：两片鳞片、十张重皮和一些煤块。博恩奈特有多少就会收多少。"}},faq={{q="谁需要这些物资？",a="位于灼热峡谷的大铁匠博恩奈特，他会亲自接收这些物资。",al={"谁发布此任务","博恩奈特炽热助熔剂","在哪里交任务"}},{q="博恩奈特需要什么材料？",a="两片焚火龙鳞、十张重皮和一些煤块。",al={"我需要什么物品","炽热助熔剂材料","博恩奈特上交物品"}},{q="在这个任务之前有什么前置任务？",a="名为“助熔剂怎么了？”的任务步骤，这是博恩奈特在此之前交给你的任务。",al={"此任务的前置要求","炽热助熔剂的前置任务","助熔剂怎么了的前置条件"}},{q="博恩奈特为什么要这些物资？",a="博恩奈特说炽热助熔剂的储备正在减少，因此需要进行补充。",al={"为什么需要炽热助熔剂","博恩奈特的动机"}}},fp="47,217,17.239.0,25.78.0,35.67.0,30.69.0,36.78.0"}
P.entries["quest:8249"] = {n="垃圾箱",s="在拉文霍德庄园，法拉德对坚固的锁闭容器有着源源不断的需求，以训练公会中冉冉升起的潜行者。由于庄园内部工匠提供的练习锁对于高阶学员来说太过简单，法拉德愿意用特制的飞刀与任何愿意提供真正重垃圾箱的人进行交易。",h="在拉文霍德庄园，法拉德对坚固的锁闭容器有着源源不断的需求，以训练公会中冉冉升起的潜行者。由于庄园内部工匠提供的练习锁对于高阶学员来说太过简单，法拉德愿意用特制的飞刀与任何愿意提供真正重垃圾箱的人进行交易。",kw={"重垃圾箱","希尔斯布莱德","垃圾箱","开锁","偷窃","拉文霍德","法拉德","赞"},ang={["class:Rogue"]="搜集这些重箱子完全依赖于偷窃老练对手的技艺，这使得拉文霍德成为潜行者非法技能的终极集散地。",["faction:Alliance"]="虽然隐藏在洛丹伦的争议领土中，但拉文霍德独立运作，接受来自联盟流浪者的契约，不考虑阵营界限。",["faction:Horde"]="勇敢踏入希尔斯布莱德山脉的部落特工会发现，拉文霍德对阵营忠诚度漠不关心，他们视有用的非法货物高于一切。"},sec={{t="磨砺拉文霍德之爪",b="在希尔斯布莱德丘陵上方群山中隐藏的拉文霍德庄园内，训练从未停止。盗贼大师法拉德负责指导公会特工的训练，非常看重实战开锁的精通程度。虽然赞为新兵提供练习装置，但法拉德认为那种粗糙的工艺完全不适合需要应付野外真实、顽固锁具的资深特工。"},{t="奇怪的开放式安排",b="为了让庄园获得真正的实战开锁装置，法拉德外包了从艾泽拉斯各处危险目标身上偷来的重垃圾箱。虽然只有熟练的盗贼才能从野外的目标身上偷窃这些箱子，但法拉德并不将业务仅限于潜行者。任何人只要送来一批这些锁闭的箱子——即使已经清空了里面的主要贵重物品——都能赢得法拉德的好感，并获得庄园精心制造的致命飞刀，前提是箱子里还要留有一枚代币，以激励学员。"}},faq={{q="为什么法拉德需要这些垃圾箱？",a="拉文霍德的潜行者学徒需要真实的装置来练习开锁。法拉德认为庄园驻地工匠赞制作的练习箱对于初学者以外的任何人来说都太基础了，他们需要从危险的目标身上收集真正的锁箱。",al={"为什么需要垃圾箱","垃圾箱的用途","为什么法拉德想要箱子"}},{q="这个任务在哪里进行？",a="交换地点位于拉文霍德庄园，这是隐藏在希尔斯布莱德丘陵以北山脉中的盗贼公会秘密避难所。",al={"垃圾箱任务地点","法拉德在哪里","拉文霍德位置"}},{q="只有潜行者才能交付这个任务吗？",a="虽然重垃圾箱最初是通过潜行者的偷窃艺术获得的，但法拉德接受任何有能力将其带到庄园的人的交付。",al={"这是潜行者专属任务吗","任何人都可以做垃圾箱任务吗","其他职业垃圾箱任务"}},{q="为什么箱子里必须保留硬币？",a="法拉德坚持每个箱子里都要留几枚硬币，因为即使是训练中的潜行者也需要实实在在的激励和奖励来鞭策他们的开锁训练。",al={"为什么要在箱子里留硬币","箱子里需要有战利品吗","空的垃圾箱"}},{q="拉文霍德提供什么作为交换？",a="法拉德会用公会声望和精心制作的飞刀奖励贡献者，他讽刺地希望这些飞刀能直接扎进某人的心脏。",al={"垃圾箱任务奖励","法拉德给什么","拉文霍德飞刀"}},{q="法拉德抱怨的赞是谁？",a="赞是拉文霍德内部的锁具供应商。法拉德认为赞制作的练习装置太粗糙，只适合最原始的新手，而不是严肃的特工。",al={"赞是谁","赞和拉文霍德","赞的锁具"}}},fp="16,183,30.363.0,28.420.0,37.272.0,32.145.0,35.150.0,52.131.0,39.145.0,39.148.0"}
P.entries["quest:825"] = {n="海底沉船",s="剃刀岭的加索克指挥部落侦察兵去流亡海岸搜寻戴林·普罗德摩尔海军上将舰队的沉船残骸。通过从水下的残骸中回收先进的侏儒的工具，部落希望能够拆解联盟的工程学技术，并将这种技术优势转化为自己的利益。",h="剃刀岭的加索克指挥部落侦察兵去流亡海岸搜寻戴林·普罗德摩尔海军上将舰队的沉船残骸。通过从水下的残骸中回收先进的侏儒的工具，部落希望能够拆解联盟的工程学技术，并将这种技术优势转化为自己的利益。",kw={"杜隆塔尔","加索克","侏儒的工具","普罗德摩尔","剃刀岭","打捞","流亡海岸","提拉加德城堡","残骸"},ang={["faction:Horde"]="加索克将每一片联盟的金属残片视为双重奖赏：既是击败未来入侵的知识，又是帮助建设杜隆塔尔这个新生国家的材料。",["profession:Engineering"]="对于工匠来说，侏儒的工具的回收凸显了联盟机械精度与部落蓬勃发展的工艺产业之间早期的技术摩擦。",["race:Gnome"]="虽然身材矮小，但侏儒在联盟航行的每一个地方都留下了他们的印记；他们精密的装备受到了部落足够的尊重，值得专门进行回收任务。"},sec={{t="舰队的回响",b="当戴林·普罗德摩尔海军上将将库尔提拉斯的海军力量带到卡利姆多时，他的船只挤满了提拉加德城堡附近的海岸线。在他战败后，破碎的船体散落在流亡海岸。虽然幸存的库尔提拉斯人士兵加固了城堡本身，但他们舰队的残骸却破碎地躺在浅滩上，在潮汐下慢慢腐烂。"},{t="侏儒的装置",b="兽人的战争传统上依靠蛮力、钢铁和鲜血，但部落也意识到了联盟的独创性所带来的危险优势。侏儒技术人员曾随远征舰队同行，为联盟的船只配备了复杂的机械和精密齿轮。加索克试图回收这些沉没的工具，以便部落能够解开它们背后的机械原理。"},{t="运往奥格瑞玛",b="这些回收的工具并非要在剃刀岭落满灰尘。加索克安排将它们通过大篷车直接运往奥格瑞玛。通过对侏儒仪器进行逆向工程，部落的工匠和战术家旨在在未来的冲突中更好地应对联盟的装置，同时增强自己新兴的工业。"}},faq={{q="为什么部落要从这些沉船中回收工具？",a="部落想要了解联盟所使用的先进技术。侏儒为人类军队制造精密的机械，通过研究这些工具，部落的战术家可以找到对抗联盟装置的方法，同时为自己的工匠采用有用的机械原理。",al={"为什么要获取侏儒的工具","为什么要打捞沉船","加索克对工具的意图"}},{q="流亡海岸外沉没的是谁的船？",a="这些沉没的船只属于戴林·普罗德摩尔海军上将的库尔提拉斯舰队。在登陆杜隆塔尔的海岸并向萨尔新建立的国家发动战争后，几艘船只在提拉加德城堡以东的海岸线沿线被摧毁。",al={"这些是谁的船","谁在杜隆塔尔摧毁了船只","普罗德摩尔舰队残骸"}},{q="回收的工具在离开剃刀岭后会被运往哪里？",a="加索克会将回收的侏儒的工具通过下一支前往奥格瑞玛的大篷车运走。在那里，工程师和工匠可以彻底研究这些装置，以帮助加强首都的防御和工业。",al={"工具会怎么样","侏儒的工具去哪里","谁获得了打捞物"}},{q="为什么人类的战舰上会有侏儒工具？",a="侏儒是联盟中人类的亲密盟友，经常为海军远征队提供机械专业知识、攻城装备和精密维护工具，以保持作战舰队的正常运转。",al={"为什么侏儒与人类在一起","普罗德摩尔船上的侏儒","联盟的侏儒科技"}},{q="什么是流亡海岸？",a="流亡海岸是杜隆塔尔东部的海岸线，经过提拉加德城堡。它的得名是因为在与普罗德摩尔的远征军战斗后，这里浅水区遍布半沉和沉没的船只。",al={"流亡海岸在哪里","流亡海岸的位置","杜隆塔尔沉船区域"}},{q="这项任务与提拉加德城堡的威胁有什么联系？",a="在对提拉加德城堡的突袭中扫清了库尔提拉斯海军陆战队之后，加索克利用这个机会搜刮了剩余的联盟资源。剥离附近的沉船残骸可以确保在拾荒者或潮汐带走一切之前，部落能从敌人的失败中获利。",al={"提拉加德城堡的联系","战胜背叛者任务链接","为什么在提拉加德之后做这个"}}},fp="21,169,19.310.0,20.314.0,22.245.0,51.251.0,46.213.0,49.182.0,46.163.0,26.186.0,58.245.0"}
P.entries["quest:826"] = {n="扎拉赞恩",s="森金村的加德林大师派遣部落的勇士前往回音群岛，终结巫医扎拉赞恩的背叛。受黑魔法蛊惑而疯狂的扎拉赞恩奴役了自己的族人，并占领了暗矛巨魔原本的家园，迫使他们流亡至杜隆塔尔的海岸。",h="森金村的加德林大师派遣部落的勇士前往回音群岛，终结巫医扎拉赞恩的背叛。受黑魔法蛊惑而疯狂的扎拉赞恩奴役了自己的族人，并占领了暗矛巨魔原本的家园，迫使他们流亡至杜隆塔尔的海岸。",kw={"暗矛","杜隆塔尔","回音群岛","被施法的巨魔","加德林大师","森金村","沃金","巫毒巨魔","扎拉赞恩"},ang={["class:Shaman"]="扎拉赞恩扭曲了巨魔萨满和巫医所修习的灵性技艺与原始力量，将禁锢魔法用于攻击自己的同胞。",["faction:Horde"]="这场冲突代表了年轻部落面临的第一次重大团结考验，证明了来自杜隆塔尔各地的盟友会团结起来，保卫流离失所的暗矛巨魔部落。",["race:Troll"]="对于暗矛巨魔来说，击杀扎拉赞恩是一场极其私人的复仇与职责履行，是对那个窃取了你们民族的真正家园并奴役你们兄弟的叛徒的惩罚。"},sec={{t="群岛上的背叛",b="当暗矛巨魔逃离他们沉没的岛屿家园，跟随萨尔跨越无尽之海后，他们在杜隆塔尔东南海岸外的回音群岛建立了一个定居点。扎拉赞恩，这位部落中受人尊敬且力量强大的巫医，屈服于权力欲望。他利用奴役心智的妖术，控制了许多族人并掀起了一场暴乱。幸存的自由暗矛巨魔在沃金的带领下被驱逐出祖传的营地，被迫在森金村建立了一个临时避难所。"},{t="部落的磨难",b="扎拉赞恩并不满足于仅仅将族人赶走。他在回音群岛最大的岛屿上的山顶堡垒中，不断派突袭队穿过海峡，抓捕更多的暗矛巨魔并将其变成奴隶。那些受害者变成了毫无思想的巫毒奴隶，对部落而言已彻底失去。加德林大师认为这不仅仅是领土的占领，更是一种生存威胁：除非将扎拉赞恩的首级带到长老面前，否则没有任何暗矛巨魔能真正安全。"}},faq={{q="扎拉赞恩是谁？",a="扎拉赞恩曾是暗矛巨魔中一位杰出的巫医。他因对黑暗力量的渴望而堕落，转而攻击同胞，利用控制心智的巫毒术奴役族人，并为自己占领了回音群岛。",al={"扎拉赞恩传说","回音群岛的首领是谁","巫医扎拉赞恩"}},{q="为什么暗矛巨魔会逃离回音群岛？",a="扎拉赞恩在岛上发动了突袭政变，通过邪恶的巫术将兄弟姐妹变成了毫无思想的奴隶。沃金和幸存的自由暗矛巨魔因人数不足无法对抗被施了法的同胞，于是撤退到杜隆塔尔大陆，建立了森金村作为临时避难所。",al={"为什么巨魔在森金村","回音群岛背景故事","巨魔是如何失去回音群岛的"}},{q="在扎拉赞恩控制下的巨魔会怎样？",a="在扎拉赞恩控制下的巨魔，其心智已被强大的妖术完全摧毁。他们完全沦为扎拉赞恩毫无思想的仆从，在岛上巡逻并对大陆发起突袭以捕获更多受害者。加德林大师认为他们对部落而言已彻底沦丧，执行处决是唯一的仁慈。",al={"被施法的巨魔","巫毒巨魔","扎拉赞恩的奴隶能治愈吗"}},{q="扎拉赞恩在哪里？",a="扎拉赞恩将巢穴设在回音群岛链中最大的岛屿上，位于杜隆塔尔南海岸的正东方。他在中央山丘的高峰和下方那一群巨魔小屋之间巡逻。",al={"扎拉赞恩位置","寻找扎拉赞恩","扎拉赞恩在哪里"}},{q="是谁发布了杀死扎拉赞恩的任务？",a="加德林大师，即位于杜隆塔尔南岸森金村的部落长老，会在你完成处理当地威胁的入门任务并从试炼谷来到这里后提供该任务。",al={"谁发布扎拉赞恩的任务","在哪里接扎拉赞恩任务"}},{q="为什么沃金不亲自领导进攻？",a="虽然沃金统领着部落，并在奥格瑞玛与萨尔大酋长一同协调暗矛巨魔的防御工作，但森金村仍由像加德林大师这样的当地长老负责引导。加德林负责协调日常生存，并招募有能力的冒险者反击这位背叛的巫医。",al={"沃金在哪里","为什么沃金不打扎拉赞恩"}}},fp="8,329,21.501.0,17.435.0,16.205.0,42.291.0,52.233.0,26.186.0,37.186.0,46.241.0"}
P.entries["quest:827"] = {n="骷髅石",s="此项任务由隐士Margoz委派，指引部落冒险者前往位于奥格瑞玛正东方的骷髅石洞穴。该洞穴已被火刃氏族邪教所占据，他们使用痛苦的恶魔装置将自己与黑暗魔法绑定。收缴这些被诅咒的神器可以让Margoz研究在这个首都家门口出现的邪教动向。",h="此项任务由隐士Margoz委派，指引部落冒险者前往位于奥格瑞玛正东方的骷髅石洞穴。该洞穴已被火刃氏族邪教所占据，他们使用痛苦的恶魔装置将自己与黑暗魔法绑定。收缴这些被诅咒的神器可以让Margoz研究在这个首都家门口出现的...",kw={"火刃氏族","邪教徒","恶魔","杜隆塔尔","邪能","margoz","奥格瑞玛","灼热项圈","骷髅石"},ang={["class:Warlock"]="灼热项圈展示了粗糙但强大的邪能绑定，让黑暗践行者得以一窥该邪教如何将恶魔祭品转化为原始力量。",["faction:Horde"]="一个在奥格瑞玛城墙外滋生的恶魔邪教威胁着年轻部落的核心与安全。",["race:Orc"]="火刃氏族代表了兽人们每天都在努力摆脱的黑暗过去；将他们从杜隆塔尔的岩石中清除出去，不仅关乎生存，也关乎荣誉。"},sec={{t="阴影巢穴",b="骷髅石是位于杜隆塔尔东北部崎岖山丘中的一座险恶洞穴。虽然看似偏僻，但它距离Gates of Orgrimmar却近得令人不安。这些洞穴里没有野兽或普通的亡命之徒，而是盘踞着火刃氏族的一个分支——长期以来一直困扰着兽人社会的阴暗恶魔邪教。在这些昏暗的隧道中，邪教徒在大酋长的斥候眼皮底下进行着邪恶的仪式。"},{t="恶魔协调",b="在骷髅石内活动的邪教徒佩戴着灼热项圈，这是一种旨在灼烧和烙印他们自身血肉的颈圈。据Margoz说，这种自残行为远非单纯的残忍；金属中嵌入的灼热痛苦和邪能魔法有助于使佩戴者与恶魔力量达成协调。通过回收这些神器，Margoz打算解开赋予火刃氏族力量的具体咒语和绑定。"},{t="迫在眉睫的威胁",b="揭开项圈背后的秘密证实了该邪教在杜隆塔尔的活动是蓄意且有组织的。火刃氏族并非仅仅以分散的强盗形式活动；他们的魔法根深蒂固，对新建立的部落领地构成了直接而阴险的威胁。分析这些项圈引发了一连串的调查，并将线索直接指向了奥格瑞玛阴影中的圈子。"}},faq={{q="骷髅石位于何处？",a="骷髅石是一座位于杜隆塔尔东北部的海岸洞穴，坐落在奥格瑞玛以东、森金村以北的海岸线上。其入口处有险峻的悬崖作为标记。",al={"骷髅石位置","骷髅石在哪里","杜隆塔尔骷髅石洞穴"}},{q="火刃氏族是什么？",a="火刃氏族是一个危险的兽人与邪能崇拜者邪教，致力于崇拜恶魔实体和黑暗魔法。虽然现代部落已经脱离了恶魔的奴役，但像火刃氏族这样的分裂团体仍在继续进行禁忌仪式，试图从阴影中腐化部落。",al={"火刃氏族是什么","火刃氏族邪教徒是谁","火刃氏族背景"}},{q="邪教徒使用灼热项圈做什么？",a="邪教徒将灼热的金属带戴在脖子上以灼烧自己的血肉。Margoz怀疑这种仪式性的痛苦和恶魔附魔使他们能够引导并协调自己以获取黑暗的邪能。",al={"灼热项圈用途","为什么要佩戴灼热项圈","什么是灼热项圈"}},{q="Margoz是谁？",a="Margoz是一位兽人隐士，居住在杜隆塔尔悬崖顶上的一个小营地里，靠近骷髅石。他密切关注着沿海地区的邪教活动，并致力于瓦解火刃氏族的黑暗行动。",al={"margoz是谁","杜隆塔尔margoz","margoz任务给予者"}},{q="为什么部落允许邪教在奥格瑞玛附近存在？",a="他们并非知情并容忍。该邪教在极度保密的情况下运作，隐藏在常规巡逻队很少到达的洞穴和荒凉的峡谷中。冒险者之所以被派去调查，正是因为这些邪教徒在黑暗仪式开始前，成功地掩盖了他们的立足点。",al={"为什么骷髅石在奥格瑞玛附近","奥格瑞玛火刃氏族"}},{q="Margoz检查项圈后会发生什么？",a="Margoz打算检查灼热项圈。调查将随着奥格瑞玛的Neeru Fireblade任务继续进行。",al={"骷髅石之后的任务","项圈线索","margoz法术"}}},fp="10,244,16.338.0,18.307.0,18.240.1,28.150.0,25.260.0,49.201.0,14.197.0,56.232.0,47.107.1"}
P.entries["quest:8273"] = {n="奥兰的感谢",s="在“林吉的秘密”任务之后，始于“林吉被困！”的任务线，随着你将一块石板带给奥兰·斯内克威瑟而宣告终结。",h="在“林吉的秘密”任务之后，始于“林吉被困！”的任务线，随着你将一块石板带给奥兰·斯内克威瑟而宣告终结。",kw={"黑暗女王","辛特兰","奥兰·斯内克威瑟","眺望台悬崖","林吉","石板"},sec={{t="给奥兰的石板",b="“林吉被困！”开启了这条任务线，而“林吉的秘密”是紧接在这一步之前的任务。奥兰·斯内克威瑟是你所携带石板的交付对象。"},{t="奥兰的回答",b="奥兰询问石板是在哪里发现的，你告诉他是在眺望台悬崖边的一座荒废小岛上。奥兰觉得这非常有趣，小心地收好了石板，并说黑暗女王会对这个发现感到非常高兴。"}},faq={{q="奥兰·斯内克威瑟是谁？",a="奥兰·斯内克威瑟是结束了那条始于“林吉被困！”并贯穿了“林吉的秘密”的任务线的人。",al={"奥兰","奥兰是谁","奥兰·斯内克威瑟背景故事"}},{q="任务线中这一步之前是什么？",a="在这之前是“林吉的秘密”，而在那之前是“林吉被困！”。",al={"前序任务","奥兰的感激的前置任务","如何开始奥兰的感激"}}},fp="16,137,17.154.0,13.233.1,24.120.0,36.68.0"}
P.entries["quest:828"] = {n="玛高兹",s="Margoz是一个部落任务，要求冒险者寻找一位守望在杜隆塔尔北部的隐居兽人萨满。在枯水谷遭遇邪能腐蚀后，奥戈尼尔·魂痕会指引勇士们在袭击附近的邪教据点前先去咨询Margoz。这位睿智的隐士对火刃氏族投下的日益增长的阴影提供了关键建议。",h="Margoz是一个部落任务，要求冒险者寻找一位守望在杜隆塔尔北部的隐居兽人萨满。在枯水谷遭遇邪能腐蚀后，奥戈尼尔·魂痕会指引勇士们在袭击附近的邪教据点前先去咨询Margoz。这位睿智的隐士对火刃氏族投下的日益增长的阴影提...",kw={"火刃氏族","枯水谷","杜隆塔尔","margoz","奥戈尼尔·魂痕","奥格瑞玛","萨满","骷髅石"},ang={["class:Shaman"]="Margoz代表了萨满教古老而耐心的智慧，他在荒野边缘守望，以便在精神腐蚀演变成战争之前就察觉到它。",["faction:Horde"]="Margoz的警告突显了奥格瑞玛的脆弱性，证明了恶魔邪教潜伏在部落心脏的打击距离之内。",["race:Orc"]="拜访Margoz提醒了兽人战士们邪能力量挥之不去的诱惑，敦促新一代人走上一条纯洁而光荣的道路。"},sec={{t="隐士的守望",b="在发现雷霆山的邪能腐蚀深度后，奥戈尼尔·魂痕认识到仅靠蛮力不足以净化杜隆塔尔。他指引他的勇士们去找Margoz，一位经验丰富的兽人萨满，在剃刀岭东北部的岩石地带独自扎营。Margoz位于枯水谷的崎岖高地与东海之间，时刻监视着奥格瑞玛那些忙碌的战士们往往会忽略的黑暗预兆。"},{t="骷髅石的威胁",b="Margoz掌握着有关火刃氏族在杜隆塔尔北部真正权力基地的关键情报：一个被称为骷髅石的隐藏洞穴系统，就开凿在奥格瑞玛南门外的山崖上。通过与Margoz商议，旅行者们了解到这些邪教徒在Thrall的首都附近的活动，远比酋长的卫兵们所意识到的要近得多。这位萨满确保任何被派去清除该集会所的人都不会盲目地陷入恶魔的伏击。"}},faq={{q="Margoz是谁？",a="Margoz是一位效忠于部落的睿智兽人萨满，住在杜隆塔尔东北部的一个隐蔽营地里。他研究黑暗魔法的动向，并监视着在该地区蔓延的恶魔腐蚀。",al={"margoz背景故事","margoz是谁","margoz npc"}},{q="我在哪里可以找到Margoz？",a="Margoz在杜隆塔尔东北部的崎岖山丘中扎营，位于枯水谷和东海岸线之间，就在奥格瑞玛的东南部。",al={"margoz位置","寻找margoz","margoz在哪里"}},{q="为什么奥戈尼尔·魂痕要派我去找Margoz？",a="奥戈尼尔认识到Margoz花了大量时间研究当地的火刃氏族邪教徒。在派你去袭击他们的据点之前，奥戈尼尔希望你能得到Margoz的精神智慧和实践建议。",al={"为什么要与margoz交谈","奥戈尼尔·魂痕 margoz"}},{q="什么是骷髅石？",a="骷髅石是一个位于奥格瑞玛东墙南侧的隐藏山洞。它作为火刃氏族的一个防御森严的集会所，崇拜恶魔的邪教徒们就在部落的眼皮底下进行仪式。",al={"骷髅石背景故事","什么是骷髅石"}},{q="找到Margoz之后会发生什么？",a="一旦你向Margoz报告，他会认可你不断增长的实力，并立即指派你进入骷髅石，杀死邪教徒并取回他们受腐蚀的徽记。",al={"margoz之后的后续任务","margoz后续"}},{q="Margoz是火刃氏族的一员吗？",a="不。Margoz是一位忠诚的部落萨满，致力于清除恶魔的影响，并让年轻的勇士们保持在一条光荣且未受腐蚀的道路上。",al={"margoz是邪恶的吗","margoz是邪教徒吗"}}},fp="6,321,16.372.0,24.393.0,14.191.0,23.151.0,43.214.0,19.207.0,34.153.1,36.133.0"}
P.entries["quest:829"] = {n="尼尔鲁·火刃",s="这个任务将杜隆塔尔的Margoz指引部落冒险者前往奥格瑞玛那阴影笼罩的腹地。你带着从火刃氏族邪教徒手中缴获的恶魔灼热项圈，被指引去寻找Neeru Fireblade。他是一位居住在Cleft of Shadow的著名术士，声称自己研究黑暗魔法仅仅是为了保护部落。",h="这个任务将杜隆塔尔的Margoz指引部落冒险者前往奥格瑞玛那阴影笼罩的腹地。你带着从火刃氏族邪教徒手中缴获的恶魔灼热项圈，被指引去寻找Neeru Fireblade。他是一位居住在Cleft of...",kw={"火刃氏族","cleft of shadow","杜隆塔尔","margoz","neeru fireblade","奥格瑞玛","灼热项圈","骷髅石","术士"},ang={["class:Shaman"]="Margoz的坦白标志着萨满教义与恶魔魔法之间有着清晰的界限：元素不会与邪能神器沟通，因此需要术士的协助。",["class:Warlock"]="进入Cleft of Shadow咨询Neeru Fireblade，让你直接接触到了奥格瑞玛最著名的术士，验证了你的禁忌技艺对部落的现实价值。",["faction:Horde"]="这项任务展示了奥格瑞玛内部脆弱的休战状态，大酋长的萨满们有时必须求助于Cleft of Shadow中的阴影流放者，以保护杜隆塔尔免于灭亡。"},sec={{t="萨满的极限",b="在从潜伏于骷髅石的邪教徒手中回收了灼热项圈后，萨满Margoz发现，解开这些邪恶魔法的奥秘已超出了他先祖技艺的能力范围。萨满与元素之灵和大地沟通，而这些神器却散发着原始的恶魔腐蚀气息。Margoz意识到，若要了解火刃氏族的装置，就需要找一位精通神秘学的人，因此他派你去寻找居住在首都的一位术士。"},{t="进入Cleft of Shadow",b="在奥格瑞玛的红色峭壁之下，坐落着Cleft of Shadow，这是一个光线昏暗的洞穴，禁忌魔法的修行者们在Thrall警惕的注视下在此施展技艺。兽人术士Neeru Fireblade居住于此，他是一位极具影响力的人物，坚称自己对邪能的掌握完全是为了挫败恶魔的威胁。将项圈样本交给他引起了他极大的好奇心，将杜隆塔尔对邪教的调查直接带入了术士聚集地的核心。"}},faq={{q="为什么Margoz要我去找术士？",a="Margoz是一位萨满，他的力量源自元素和先祖之灵。从骷髅石回收的灼热项圈本质上纯粹是恶魔之物，而要探明其附魔和起源，需要精通邪能魔法和黑暗艺术的人。",al={"为什么需要术士","为什么是neeru","margoz 术士"}},{q="我在哪里可以找到Neeru Fireblade？",a="Neeru Fireblade位于Cleft of Shadow，这是奥格瑞玛下方的一个地下洞穴群，术士、潜行者和暗影施法者们聚集于此。",al={"neeru位置","neeru fireblade在哪","cleft of shadow neeru"}},{q="Neeru Fireblade值得信任吗？",a="Margoz本人也抱有怀疑。他指出，虽然Neeru声称他的神秘学研究是无害的，仅用于对抗恶魔，但这究竟是真是假还有待观察。Thrall允许术士在奥格瑞玛活动，但会对他们进行严格的监督，建议保持警惕。",al={"neeru是邪恶的吗","neeru值得信任吗","我可以信任fireblade吗"}},{q="什么是项圈样本？",a="项圈样本是从骷髅石的火刃氏族邪教徒身上缴获的灼热项圈之一。Margoz把它交给你，让你直接送交给Neeru Fireblade进行魔法分析。",al={"项圈样本","什么是项圈","灼热项圈任务物品"}},{q="把项圈交给Neeru之后会发生什么？",a="Neeru会仔细检查这个项圈，随后引出任务“Ak'Zeloth”，他会派你深入调查该邪教在杜隆塔尔的阴影存在。",al={"neeru之后的后续任务","neeru做什么","neeru的任务线"}},{q="为什么部落允许术士留在奥格瑞玛？",a="大酋长Thrall出于现实的需要容忍了术士的存在，将他们限制在Cleft of Shadow的地下，以便对其危险的研究进行监视和控制，并偶尔利用他们的知识来了解恶魔敌人。",al={"为什么允许术士存在","cleft of shadow里的术士","thrall 术士"}}},fp="15,215,17.285.0,24.340.0,37.228.0,33.121.0,31.205.0,27.167.0,46.148.0,47.210.0"}
P.entries["quest:83"] = {n="红色亚麻布",s="“红色亚麻面罩”是东谷伐木场的一位裁缝萨拉·迪博雷恩提供的一项艾尔文森林任务。由于布料短缺，她请求过往的冒险者去猎杀当地的迪菲亚强盗，并夺取他们身上的亚麻面罩。作为交换，她会利用回收来的布料为旅行者制作有用的商品。",h="“红色亚麻面罩”是东谷伐木场的一位裁缝萨拉·迪博雷恩提供的一项艾尔文森林任务。由于布料短缺，她请求过往的冒险者去猎杀当地的迪菲亚强盗，并夺取他们身上的亚麻面罩。作为交换，她会利用回收来的布料为旅行者制作有用的商品。",kw={"粗麻布","迪菲亚潜行者","东谷伐木场","艾尔文森林","红色亚麻面罩","萨拉·迪博雷恩","裁缝"},ang={["faction:Alliance"]="清理侵扰艾尔文森林树林的迪菲亚强盗不仅能为东谷带来有用的回收品，还能积极削弱兄弟会对王国腹地的控制。",["profession:Tailoring"]="萨拉·迪博雷恩的生意展示了乡村裁缝业的严酷现实，由于布料极其匮乏，当地裁缝不得不直接从地区强盗的背上收割布料。"},sec={{t="强盗与粗麻布",b="虽然在北郡山谷游荡的低等级迪菲亚强盗们只会用廉价的粗麻布面罩凑合，但在广阔的艾尔文森林出没的有组织的不法之徒们佩戴的却是更精细的绯红色亚麻面罩。对于缺乏原材料的当地工匠来说，这些帮派标识代表着一种极其务实且可用的布料来源。"},{t="营地回收",b="萨拉·迪博雷恩在艾尔文森林东部边缘繁忙的东谷伐木场工作，她总是在寻找可用的纺织品。通过鼓励冒险者清理隐藏在森林各处的迪菲亚营地，她既能维持自己的裁缝生意，又能帮助遏制兄弟会日益猖獗的侵扰。"}},faq={{q="是谁提供了“红色亚麻面罩”任务？",a="这项任务是由位于艾尔文森林东部东谷伐木场的裁缝萨拉·迪博雷恩提供的。",al={"谁提供红色亚麻面罩任务","红色亚麻面罩任务发布者","萨拉·迪博雷恩任务"}},{q="完成“红色亚麻面罩”任务需要哪些物品？",a="你需要收集6个红色亚麻面罩，它们可以从散布在艾尔文森林各处的迪菲亚帮派成员身上拾取。",al={"红色亚麻面罩需要收集什么","红色亚麻面罩所需物品","需要的面罩"}},{q="我在哪里可以在艾尔文森林找到迪菲亚强盗？",a="迪菲亚不法之徒栖息在艾尔文森林各处的小型营地中，包括布莱克威尔南瓜田、斯通菲尔德农场以及杰罗德码头周围的森林区域。",al={"艾尔文森林迪菲亚位置","迪菲亚营地在哪里","去哪里获取红色面罩"}},{q="为什么艾尔文森林的迪菲亚成员戴的是亚麻布而不是粗麻布？",a="根据萨拉·迪博雷恩的说法，北郡的低阶迪菲亚成员佩戴的是简陋的粗麻布面罩，而活跃在更广阔的艾尔文森林区域的成员装备更好，佩戴的是红色亚麻布，这标志着他们在兄弟会内部拥有更高的组织和补给层级。",al={"为什么要红色亚麻布","迪菲亚粗麻布对比亚麻布","迪菲亚面罩材质"}},{q="为什么萨拉·迪博雷恩想要强盗的面罩？",a="萨拉的裁缝生意正面临布料短缺。她会对从迪菲亚面罩上回收的干净亚麻布进行再利用，为伐木工和旅行者缝制实用的物品。",al={"为什么要收集面罩","萨拉如何处理面罩"}},{q="东谷伐木场位于哪里？",a="东谷伐木场位于艾尔文森林的最东端，就在通往赤脊山桥梁的主路北侧。",al={"东谷位置","东谷在哪里","如何找到萨拉·迪博雷恩"}}},fp="15,204,18.211.0,19.309.0,37.97.0,42.92.0,49.138.0,54.188.0,46.157.0,43.127.0"}
P.entries["quest:830"] = {n="将军的命令",s="这些饱经风霜的文件是从提拉加德城堡顶层的一个锁着的保险箱里回收的，上面印有已故海军上将戴林·普罗德摩尔的个人印章。这些回收的命令揭示出，杜隆塔尔海岸沿线的库尔提拉斯人驻军绝非简单的海难幸存者，而是更加根深蒂固、组织严密的军队。将这些文件交给剃刀岭的加索克，便暴露了威胁着这个新生兽人国度的残余军事计划。",h="这些饱经风霜的文件是从提拉加德城堡顶层的一个锁着的保险箱里回收的，上面印有已故海军上将戴林·普罗德摩尔的个人印章。这些回收的命令揭示出，杜隆塔尔海岸沿线的库尔提拉斯人驻军绝非简单的海难幸存者，而是更加根深蒂固、组织严密的...",kw={"海军上将的命令","旧信封","戴林·普罗德摩尔","加索克","库尔提拉斯","本尼迪克特中尉","剃刀岭","提拉加德城堡"},ang={["faction:Horde"]="发掘普罗德摩尔的命令证明，联盟在杜隆塔尔海岸的存在是一场蓄谋已久的灭绝行动，这更加强调了部落为何必须时刻警惕地保卫其新家园。",["race:Orc"]="对于在杜隆塔尔为建立未来而奋斗的兽人来说，这些文件无情地提醒着他们戴林·普罗德摩尔那不懈的仇恨，以及那些仍试图毁灭他们的残余势力。"},sec={{t="一份尘封的遗赠",b="在提拉加德城堡上层的一个沉重箱子里，藏着一个旧信封，由本尼迪克特中尉看守。这份羊皮纸上盖着海军上将戴林·普罗德摩尔的徽章，概述了库尔提拉斯在血腥入侵杜隆塔尔期间发布的直接海军命令。即使在海军上将倒在塞拉摩之后，他的军官们仍坚守着防御工事，紧紧地执行着消灭部落定居点的任务。"},{t="剃刀岭的警报",b="将回收的文件交给剃刀岭的指挥官加索克，证实了当地防御部队最担心的事。沿东海岸扎根的人类部队并非漫无目的的落难者，而是一处等待增援的稳固滩头阵地。加索克立刻意识到，瓦解提拉加德的指挥体系对于杜隆塔尔的生存来说是当务之急。"}},faq={{q="在哪里可以找到海军上将的命令？",a="这些命令位于杜隆塔尔提拉加德城堡三楼一个锁着的箱子里，装在一个旧信封中。要打开这个箱子，你必须先击败二楼的本尼迪克特中尉，夺取他的钥匙。",al={"命令位置","旧信封在哪里","寻找海军上将的命令"}},{q="普罗德摩尔上将是谁？",a="海军上将戴林·普罗德摩尔是库尔提拉斯的统治者，也是第二次战争期间联盟海军舰队的最高指挥官。他拒绝相信兽人可以和平生活，于是航行至卡利姆多，对杜隆塔尔发动了一场灭绝战争，最终在塞拉摩陨落。",al={"海军上将是谁","戴林·普罗德摩尔的背景故事","谁发布了这些命令"}},{q="为什么库尔提拉斯的士兵仍留在提拉加德城堡？",a="当戴林·普罗德摩尔入侵杜隆塔尔时，他建立了像提拉加德城堡这样加固的沿海立足点。在他战败后，本尼迪克特中尉领导的残存军官和海军陆战队依然坚守岗位，决心继续他针对部落的战役。",al={"人类为什么在杜隆塔尔","提拉加德城堡的士兵","杜隆塔尔的库尔提拉斯人"}},{q="为什么加索克对这些命令如此担忧？",a="作为剃刀岭的军事指挥官，加索克的职责是保卫杜隆塔尔中部。发现组织严密的海军命令证明了提拉加德城堡对兽人家园构成了主动且经过计算的军事威胁，而非仅仅是无组织的落难幸存者。",al={"加索克的反应","为什么加索克关心这件事"}},{q="谁持有海军上将箱子的钥匙？",a="本尼迪克特中尉是位于提拉加德城堡二层的库尔提拉斯指挥官，他携带着打开装有旧信封的保险箱所需的钥匙。",al={"本尼迪克特之钥","谁掉落钥匙"}},{q="把命令交给加索克后会发生什么？",a="在检查了这些命令后，加索克认识到了危险：普罗德摩尔的计划在他死前就已经制定好了，而且可能会有更多波次的军队登陆杜隆塔尔海岸。他立即将命令送往奥格瑞玛，以便让大酋长的议会发出警报。",al={"海军上将的命令后续","下一个任务"}}},fp="20,412,15.452.0,19.385.1,37.221.0,27.293.0,51.255.0,48.265.0,41.180.0,49.251.0"}
P.entries["quest:8311"] = {n="耶斯帕尔的万圣节糖果！",s="在万圣节期间，一个名叫耶斯帕尔的孤儿因病躺在暴风城的孤儿院里，他渴望能参加节日庆典。由于病重无法外出，他请求联盟的冒险者代他去世界各地进行不给糖就捣蛋的活动。",h="在万圣节期间，一个名叫耶斯帕尔的孤儿因病躺在暴风城的孤儿院里，他渴望能参加节日庆典。由于病重无法外出，他请求联盟的冒险者代他去世界各地进行不给糖就捣蛋的活动。",kw={"达纳苏斯","橡皮糖","万圣节","铁炉堡","耶斯帕尔","水果糖","夜莺","杏仁糖","暴风城","塔瓦斯德","不给糖就捣蛋"},ang={["faction:Alliance"]="这项节日任务将遥远的首都联系在一起，要求英雄们从暴风城的大街，前往铁炉堡的山中大厅和达纳苏斯的树枝上，为一名孤儿带来欢乐。",["race:Gnome"]="由于他们的家园被穴居人和辐射摧毁，侏儒对节日的参与落到了铁炉堡的塔瓦斯德·基瑟尔身上，他确保了诺莫瑞根橡皮糖仍然可以被分享。"},sec={{t="一个受庇护的孩子",b="耶斯帕尔住在暴风城Cathedral Square的孤儿院里，这个万圣节他生病了。无法享受从艾泽拉斯各地收集糖果这种简单的童年乐趣，耶斯帕尔只能待在室内，希望路过的冒险者能分享节日精神，代他收集这些糖果。"},{t="联盟各地的糖果戏法",b="为了收集耶斯帕尔梦寐以求的节日糖果，冒险者必须前往艾尔文森林之外的远方。任务要求拜访暴风城、铁炉堡和达纳苏斯的旅店老板，以及流亡的侏儒塔瓦斯德·基瑟尔。每个成年人都要求你在交出奖品前进行表演——迫使旅行者模仿小鸡打鸣、跳舞、展示肌肉或像火车一样鸣笛，以换取暴风城杏仁糖和诺莫瑞根橡皮糖等地区特产。"}},faq={{q="耶斯帕尔是谁？",a="耶斯帕尔是住在暴风城孤儿院的一名年轻孤儿。在万圣节期间，他渴望得到节日糖果，但因病无法外出亲自收集。",al={"耶斯帕尔 暴风城","孤儿 耶斯帕尔","谁是耶斯帕尔"}},{q="为什么耶斯帕尔不能亲自去进行不给糖就捣蛋？",a="耶斯帕尔生病了，当城市其他地方都在庆祝万圣节时，他的病情使他不得不留在孤儿院里。",al={"为什么耶斯帕尔不能离开","耶斯帕尔生病了吗","耶斯帕尔 不给糖就捣蛋"}},{q="耶斯帕尔想要哪些糖果？",a="他请求四种不同的地区特产糖果：暴风城杏仁糖、铁炉堡薄荷糖、达纳苏斯水果糖和诺莫瑞根橡皮糖。",al={"耶斯帕尔 糖果","万圣节 糖果列表","耶斯帕尔 需要的糖果"}},{q="你在哪里可以获得诺莫瑞根橡皮糖？",a="由于诺莫瑞根仍然受到辐射且被占领，这种橡皮糖由目前待在铁炉堡Mystic Ward的侏儒难民塔瓦斯德·基瑟尔分发。",al={"诺莫瑞根橡皮糖 位置","谁提供橡皮糖","塔瓦斯德 糖果"}},{q="旅店老板让你表演什么戏法？",a="旅店老板要求你表演滑稽的动作来换取糖果：在暴风城展示肌肉，在达纳苏斯跳舞，在铁炉堡模仿小鸡打鸣，并为塔瓦斯德发出火车鸣笛声。",al={"万圣节 戏法","旅店老板 戏法","糖果戏法 联盟"}},{q="耶斯帕尔会给你什么作为糖果的回报？",a="在收到四种节日糖果后，耶斯帕尔会很高兴地用他积攒的一些南瓜糖果与旅行者交换。",al={"耶斯帕尔 奖励","给耶斯帕尔的糖果 完成"}}},fp="31,177,17.253.0,37.372.0,14.138.0,46.104.0,30.117.0,43.90.0,47.135.0,50.101.0"}
P.entries["quest:8312"] = {n="斯波普斯的万圣节糖果！",s="“给斯普普的万圣节糖果！”是一个节日任务，冒险者需要替生病无法出门进行“不给糖就捣蛋”的斯普普收集节日糖果。作为回报，斯普普会提供一些神奇的糖果，食用后可以将你变身为各种滑稽又可怕的形态。你需要在各大主城的旅店老板和森金村的卡利·雷米克处收集这些糖果。",h="“给斯普普的万圣节糖果！”是一个节日任务，冒险者需要替生病无法出门进行“不给糖就捣蛋”的斯普普收集节日糖果。作为回报，斯普普会提供一些神奇的糖果，食用后可以将你变身为各种滑稽又可怕的形态。你需要在各大主城的旅店老板和森金...",kw={"糖果","万圣节","旅店老板","卡利·雷米克","森金村","斯普普","不给糖就捣蛋"},ang={["faction:Horde"]="这个任务让部落冒险者们为了一个生病的孩子，在各大主城以及森金村的暗矛巨魔聚落进行“不给糖就捣蛋”的活动。",["race:Troll"]="杜隆塔尔的暗矛巨魔也参与了庆祝活动，卡利·雷米克就在森金村分发节日糖果。"},sec={{t="卧床的节日",b="万圣节带来了庆祝、恶作剧和遍布各地的节日糖果，但并不是每个人都能参与户外的欢庆活动。当世界各地沉浸在节日的狂欢中时，斯普普却因病被困在室内。无法出门走动，斯普普便委托过往的旅行者代为收集糖果，并以一袋奇特的变形糖果作为回报。"},{t="遍布各地的“不给糖就捣蛋”",b="想要收集糖果，需要走遍各地的定居点。各大主城的旅店老板都存有节日糖果，但他们会要求访客在交出糖果前先展示一下节日精神，表演一些戏法。除了繁华的主城旅店，这一传统也延伸到了杜隆塔尔的海岸，那里的森金村的卡利·雷米克也会为前往那里的旅行者分发糖果。"}},faq={{q="谁是斯普普？",a="斯普普是一个生病的孩子，无法在万圣节期间出门进行“不给糖就捣蛋”。为了能参与这个节日，斯普普请求旅行者代为向世界各地的旅店老板和商贩收集节日糖果。",al={"谁是斯普普","斯普普","斯普普是什么人"}},{q="为什么斯普普不能去“不给糖就捣蛋”？",a="斯普普身体不适，病得太重，无法外出庆祝万圣节。由于疾病使他卧床不起，他只能依靠热心的冒险者去拜访各地的旅店老板，收集节日糖果。",al={"为什么斯普普不能去不给糖就捣蛋","为什么斯普普要待在家里","斯普普生病"}},{q="斯普普会交换什么糖果？",a="作为从旅店老板那里收集到的节日糖果的回报，斯普普承诺提供具有神奇变形效果的特殊糖果。食用它们可以将你变成各种既滑稽又可怕的生物和形态。",al={"斯普普给什么糖果","斯普普的糖果奖励","特殊糖果"}},{q="去哪里找给斯普普的糖果？",a="节日糖果由分布在各个主城的旅店老板发放，他们会要求旅行者表演戏法来交换糖果。除了城市旅店外，杜隆塔尔森金村的巨魔卡利·雷米克也会分发节日糖果。",al={"去哪里拿糖果","谁给糖果","糖果位置"}},{q="谁是卡利·雷米克？",a="卡利·雷米克是居住在杜隆塔尔森金村的一名巨魔，他通过向到访的欢乐旅行者发放节日糖果来参与万圣节活动。",al={"谁是卡利·雷米克","卡利·雷米克糖果","森金村糖果"}},{q="为什么旅店老板会要求表演戏法？",a="万圣节期间，主要定居点的旅店老板会要求访客通过表演各种滑稽的戏法或动作来展示他们的节日精神，然后才会分享他们的节日糖果。",al={"旅店老板想要什么","旅店老板戏法","如何获得旅店老板的糖果"}}},fp="31,332,19.408.0,34.400.0,14.242.0,38.224.0,41.236.0,40.246.0,18.154.0,33.197.0"}
P.entries["quest:832"] = {n="燃影之眼",s="这个神秘的炽光坠饰是在骷髅石深处从火刃氏族邪教徒Gazz'uz身上收缴的，它不断在持有者的脑海中低语着紧急警告。那个声音特别提到要让奥格瑞玛的兽人术士Neeru Fireblade去惩罚Gazz'uz。",h="这个神秘的炽光坠饰是在骷髅石深处从火刃氏族邪教徒Gazz'uz身上收缴的，它不断在持有者的脑海中低语着紧急警告。那个声音特别提到要让奥格瑞玛的兽人术士Neeru Fireblade去惩罚Gazz'uz。",kw={"火刃氏族","灼热之影","cleft of shadow","杜隆塔尔","燃影之眼","gazz'uz","neeru fireblade","奥格瑞玛","骷髅石"},ang={["class:Warlock"]="对于在Cleft of Shadow中修行的术士来说，看到另一个修行者的名字被火刃氏族引用，这严酷地提醒着人们：国家准许的邪能研究与公开叛国之间的界限是多么薄弱。",["faction:Horde"]="在首都大门外发现邪教徒之间的低语，揭示了旧部落的恶魔腐化仍然在离杜隆塔尔中心非常近的地方令人不安地滋生着。",["race:Orc"]="与萨尔并肩作战净化燃烧军团腐化的兽人们，将火刃氏族在杜隆塔尔的存在视为对他们新家园不可容忍的亵渎。"},sec={{t="石中的声音",b="在骷髅石深处击杀Gazz'uz后，从他的遗骸中可以拾取到一个名为“燃影之眼”的不祥坠饰。这颗石头并非只是一个惰性的魔法饰品，它还会通过心灵感应发出震动。任何持有它的人都能直接听到一个严厉的声音在脑海中响起，向Gazz'uz索要报告，并警告他，他在奥格瑞玛以东的秘密行动已经暴露了。"},{t="奇怪的威胁",b="任何忠诚的部落侦察兵都会被这个声音发出的孤注一掷的最后通牒所震惊：如果不回应，Neeru Fireblade就会接到通知，以迅猛且残暴的手段猎杀Gazz'uz。Neeru Fireblade公开居住在奥格瑞玛的Cleft of Shadow中，表面上是在萨尔的严格监督下研习黑暗魔法。将这个护身符交给Neeru，他会表现出假装的惊讶和好奇，并对自己的名字被当作恐吓邪教徒的“鬼怪”而感到诧异。"}},faq={{q="什么是燃影之眼？",a="燃影之眼是火刃氏族首领Gazz'uz在骷髅石内掉落的一枚附魔坠饰。它充当了邪教特工与其幕后神秘主人之间的双向心灵感应中继器。",al={"燃影之眼","这个坠饰是什么","gazz'uz之眼"}},{q="谁在通过坠饰说话？",a="暗影议会或火刃氏族内部的一位身份不明的上级正试图联系Gazz'uz，但他并不知道这个邪教徒已经在骷髅石被杀死了。",al={"谁在和我说话","坠饰里的声音","谁在通过眼睛说话"}},{q="为什么那个声音要用Neeru Fireblade来威胁Gazz'uz？",a="那个声音声称，如果Gazz'uz不提交报告，Neeru Fireblade就会以残酷的手段对他进行惩罚。Neeru本人表示，他确实以猎杀大酋长的敌人而闻名，但他觉得因为自己的名字被单独点出来而感到奇怪。",al={"为什么要提到neeru","neeru fireblade的威胁","neeru的联系"}},{q="我应该把燃影之眼交给谁？",a="把坠饰带给Neeru Fireblade，他就在奥格瑞玛的Cleft of Shadow深处，盘旋在坩埚和书籍旁边。",al={"灼热之影任务去哪里交","neeru fireblade在哪里"}},{q="Neeru Fireblade在收到燃影之眼时有什么反应？",a="Neeru对那个声音点出他的名字感到十分好奇，更让他觉得奇怪的是，火刃氏族的邪教徒名字竟然与他如此相近。他留下了坠饰，打算对其进行研究，并思考其中传达的信息含义。",al={"neeru的反应","neeru说了什么"}},{q="Gazz'uz在哪里？",a="Gazz'uz潜伏在骷髅石的最深处，那是一个隐藏在杜隆塔尔东海岸岩壁中的洞穴，就在奥格瑞玛以东。",al={"gazz'uz在哪里","gazz'uz的位置","骷髅石首领"}}},fx={["286b7c01"]={q="燃影之眼中的声音为什么想要一份报告？",a="在吊坠中低语的声音正试图联系骷髅石的火刃氏族首领加兹乌兹。邪教高层已获悉他们的隐秘据点被部落发现，这位隐秘的指挥官急于召集加兹乌兹做好防御准备，以免他们的立足之地在不可避免的进攻中被摧毁。",al={"吊坠为什么会说话","燃影之眼为什么要报告","燃影之眼中的声音有何目的"}}},fp="15,272,20.410.0,16.454.1,34.200.0,36.174.0,57.224.0,42.134.0,50.220.1,25.136.0"}
P.entries["quest:833"] = {n="神圣的墓地",s="“神圣的安葬”是由博学者诺拉·暴雨图腾委托的一项任务，要求部落的冒险者们保护位于莫高雷东部的赤色石。这片神圣的先祖埋骨地正遭受刺鬃野猪人的劫掠，这些野猪人正在亵渎受人尊敬的牛头人战士的坟墓。驱逐这些闯入者，将为那些为了建立和保卫雷霆崖而献出生命的先烈恢复荣耀与安宁。",h="“神圣的安葬”是由博学者诺拉·暴雨图腾委托的一项任务，要求部落的冒险者们保护位于莫高雷东部的赤色石。这片神圣的先祖埋骨地正遭受刺鬃野猪人的劫掠，这些野猪人正在亵渎受人尊敬的牛头人战士的坟墓。驱逐这些闯入者，将为那些为了建...",kw={"神圣的安葬","先祖","刺鬃闯入者","博学者诺拉·暴雨图腾","莫高雷","野猪人","赤色石","雷霆崖"},ang={["class:Shaman"]="对圣地的亵渎惊扰了受尊崇先祖的灵魂，因此你必须介入以恢复大地的平衡。",["faction:Horde"]="协助牛头人长者守卫他们的神圣遗迹，巩固了部落与盟友共同保卫莫高雷的誓约。",["race:Tauren"]="保卫赤色石是一项深重的先祖荣耀，确保那些为你们族人的统一家园做出贡献的战士们能够不受干扰地安息。"},sec={{t="舒哈鲁的圣地",b="赤色石是整个莫高雷最受尊崇的圣地之一。它坐落在东部山脉下方的岩架中，是专门为最英勇的牛头人预留的最后安息之所。安葬在这里的英雄们都是传说中的战士，他们曾为保护族群、支持酋长以及在雷霆崖的高原上开辟永久家园而浴血奋战。对于舒哈鲁人来说，打扰他们的安息不仅是对传统的冒犯，更是对大地母亲本人的亵渎。"},{t="刺鬃氏族的亵渎",b="游牧的刺鬃氏族野猪人一直以来都在挑战牛头人对卡利姆多中部地区的控制，但他们最近向赤色石的推进标志着事态的严重升级。成群的刺鬃闯入者已经潜入了这片圣地，蹂躏大地并扰动安息之所。由于守护者博学者诺拉·暴雨图腾年事已高，无法独自一人驱逐入侵者，部落的年轻勇士们必须拿起武器，清除此地的闯入者，保卫那些受尊崇的逝者。"}},faq={{q="什么是赤色石？",a="赤色石是一处神圣的先祖墓地，位于莫高雷的东部山脉沿线。它专门为最英勇的牛头人战士预留，特别是那些为了保卫族群和建立雷霆崖而牺牲的战士。",al={"赤色石在哪里","莫高雷赤色石","牛头人墓地"}},{q="博学者诺拉·暴雨图腾是谁？",a="博学者诺拉·暴雨图腾是一位年长的牛头人，负责照料和守护神圣的赤色石。他意识到自己已过壮年，无法凭一己之力抵御入侵的刺鬃野猪人，因此他呼唤有能力的冒险者前来保卫逝者。",al={"暴雨图腾","博学者诺拉·暴雨图腾","谁发布神圣的安葬任务"}},{q="为什么刺鬃野猪人会出现在赤色石？",a="刺鬃氏族不断向莫高雷和贫瘠之地的牛头人领地施压。由于对领土和资源的渴望，成群的闯入者闯进了赤色石的岩架，在此过程中亵渎了坟墓。",al={"为什么野猪人在赤色石","刺鬃闯入者","野猪人入侵"}},{q="为什么这种亵渎行为对牛头人来说如此不可原谅？",a="牛头人文化极其推崇对先祖的敬意，并主张与逝者的灵魂和谐共存。任由野蛮的野猪人践踏大地，惊扰那些为雷霆崖献身的英雄们的骸骨，是对精神层面的极大侮辱。",al={"牛头人丧葬习俗","牛头人为何重视墓地"}},{q="这个任务接下来会导向哪里？",a="“神圣的安葬”是一项由博学者诺拉·暴雨图腾提供的独立防御任务。一旦刺鬃闯入者被解决，眼前的亵渎行为便会停止。",al={"神圣的安葬后续","神圣的安葬之后是什么"}},{q="谁被安葬在赤色石？",a="此地是为那些为了种族生存和酋长荣耀而战的牛头人勇士所预留的，尤其是那些因他们的牺牲才使得雷霆崖得以建立和保卫的英雄们。",al={"谁被埋葬在这里","赤色石坟墓"}}},fx={e11b84bd={q="博学者诺拉·暴雨图腾为什么请你帮忙，而不自己赶走他们？",a="博学者诺拉·暴雨图腾是一位长者，年事已高，早已不复当年，无法拿起武器对抗凶暴的战团。他的职责是照料并尊崇赤色石的灵魂，而非在前线作战，因此只能依靠你这样的能干旅人，去承担驱逐刺背入侵者的危险任务。",al={"诺拉·暴雨图腾为什么不能自己处理","诺拉·暴雨图腾为什么需要帮忙","诺拉·暴雨图腾为什么不战斗"}}},fp="15,401,31.497.0,27.505.0,18.233.0,28.262.0,46.243.0,51.257.0,32.165.0,27.196.0"}
P.entries["quest:834"] = {n="沙漠之风",s="雷兹拉克是加兹鲁维手下的一名承包工程师，他急需帮助来找回被杜隆塔尔的鹰身人偷走的建筑材料。一队开往奥格瑞玛的商队在烈风峡谷遭到伏击，货物被散落在悬崖各处。",h="雷兹拉克是加兹鲁维手下的一名承包工程师，他急需帮助来找回被杜隆塔尔的鹰身人偷走的建筑材料。一队开往奥格瑞玛的商队在烈风峡谷遭到伏击，货物被散落在悬崖各处。",kw={"商队","杜隆塔尔","尘风鹰身人","加兹鲁维","奥格瑞玛","棘齿城","烈风峡谷","雷兹拉克","物资"},ang={["faction:Horde"]="每一批在峡谷中损失的货物都威胁着部落在杜隆塔尔的据点的快速扩张和防御加固。",["profession:Engineering"]="雷兹拉克代表了热砂港工程师务实的精明，他们更关心的是让蓝图和交付如期进行，而不是当地的野外麻烦。",["race:Orc"]="兽人依靠地精的专业知识和外来物资，将杜隆塔尔贫瘠干燥的土地变成了防御稳固的家园。"},sec={{t="有期限的地精",b="雷兹拉克是由棘齿城的总工程师加兹鲁维直接派遣的，旨在协助部落在杜隆塔尔进行庞大的建筑工程。在贫瘠严酷的地形上修建防御工事本身就已经困难重重，如果再加上后勤灾难，情况就更糟了，但雷兹拉克的货物总是在运抵工地前就消失不见。没有了必要的货物，所有工作都陷入了停滞，这让这位脾气暴躁的地精主管陷入了无米下锅的窘境。"},{t="峡谷伏击",b="雷兹拉克原本期待的一批重要物资在烈风峡谷被尘风鹰身人拦截了。这些长着翅膀的食腐动物在剃刀岭和奥格瑞玛之间的道路两侧高耸的峡谷缝隙中筑巢，并会俯冲袭击毫无防备的货车。鹰身人们并没有吃掉或毁坏货物，而是将这些板条箱和麻袋囤积在巢穴周围，这使得任何有勇气杀入它们领地的人都可以完好地找回这些物资。"}},faq={{q="雷兹拉克是谁？",a="雷兹拉克是一名地精工人，受雇于棘齿城的头目加兹鲁维。加兹鲁维派他前往杜隆塔尔，协助兽人在奥格瑞玛大门外进行持续的建设工作。",al={"雷兹拉克","雷兹拉克是谁","谁给的任务"}},{q="为什么地精要帮助在杜隆塔尔进行建设？",a="加兹鲁维和热砂港与萨尔大酋长之间有着长期的商业和工程合作关系。地精工程师和机器帮助打下了奥格瑞玛的基石，而加兹鲁维也继续为部落提供承包劳动力和材料。",al={"为什么地精帮助兽人","加兹鲁维 杜隆塔尔","地精与部落合作"}},{q="物资从哪里来？",a="雷兹拉克并没有说明这些物资的来源。他只说是为了协助他在杜隆塔尔为兽人工作而运送的货物。",al={"物资来源","商队来源"}},{q="鹰身人在杜隆塔尔做什么？",a="尘风鹰身人是一种好斗的掠夺性食腐生物，它们盘踞在杜隆塔尔中部的悬崖和峡谷中。它们骚扰过往的旅行者，抢劫穿过烈风峡谷的贸易路线，并搜集任何发光或有用的东西来装饰巢穴。",al={"为什么杜隆塔尔有鹰身人","尘风鹰身人背景故事","烈风峡谷鹰身人"}},{q="烈风峡谷在哪里？",a="烈风峡谷直接从连接奥格瑞玛和剃刀岭的主要南部峡谷分支出来。峡谷切割了东侧和西侧的悬崖壁，形成了高耸的栖息地，尘风鹰身人就将偷来的货物藏在那里。",al={"烈风峡谷位置","在哪里寻找物资","补给袋位置"}},{q="为什么兽人守卫没有保护商队？",a="雷兹拉克说商队一直难以保持安全，并且这批货物原本承诺过会顺利送达。他没有解释随行了什么样的护卫，也没有解释为什么其防御在尘风鹰身人面前失败了。",al={"商队为什么失败","杜隆塔尔安全","兽人商队"}}},fp="19,163,22.328.0,20.359.0,14.157.0,41.241.0,33.129.0,38.220.0,34.190.0,46.182.0"}
